insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('1s',30,18,'crampon1923','David sauva tout ce que les Amalécites avaient pris, et David sauva ses deux femmes.'),
('1s',30,19,'crampon1923','Il ne leur manqua personne, ni petit ni grand, ni fils ni fille, ni aucune partie du butin, ni rien de ce qu''on leur avait enlevé: David ramena tout.'),
('1s',30,20,'crampon1923','Et David prit tout le menu et le gros bétail, et ils se mirent en marche devant ce troupeau, en disant: « C''est le butin de David. »'),
('1s',30,21,'crampon1923','David revint vers les deux cents hommes qui avaient été trop fatigués pour suivre David, et qu''on avait laissés au torrent de Bésor; ils s''avancèrent au-devant de David et au-devant du peuple qui était avec lui. S''approchant d''eux, David les salua amicalement.'),
('1s',30,22,'crampon1923','Tout ce qu''il y avait d''hommes méchants et vils parmi les gens qui étaient allés avec David prirent la parole et dirent: « Puisqu''ils ne sont pas venus avec nous, nous ne leur donnerons rien du butin que nous avons sauvé, sinon à chacun sa femme et ses enfants; qu''ils les emmènent et s''en aillent. »'),
('1s',30,23,'crampon1923','Mais David dit: « N''agissez pas ainsi, mes frères, avec ce que Yahweh nous a donné; car il nous a gardés, et il a livré entre nos mains la bande qui était venue contre nous.'),
('1s',30,24,'crampon1923','Et qui vous écouterait dans cette affaire? La part doit être la même pour celui qui est descendu au combat et pour celui qui est resté près des bagages: ils partageront ensemble. »'),
('1s',30,25,'crampon1923','Il en fut ainsi dès ce jour et dans la suite, et David a fait de cela une loi et une règle qui subsiste jusqu''à ce jour.'),
('1s',30,26,'crampon1923','De retour à Siceleg, David envoya une partie du butin aux anciens de Juda, ses amis, en disant: « Voici un présent pour vous sur le butin des ennemis de Yahweh. »'),
('1s',30,27,'crampon1923','Il fit ces envois à ceux de Béthel, à ceux de Ramoth du Négéb, à ceux de Jéther,'),
('1s',30,28,'crampon1923','à ceux d''Aroër, à ceux de Séphamoth, à ceux d''Estamo,'),
('1s',30,29,'crampon1923','à ceux de Rachal, à ceux des villes de Jéraméélites, à ceux des villes des Cinéens,'),
('1s',30,30,'crampon1923','à ceux d''Arama, à ceux de Cor-Asan, à ceux d''Athach,'),
('1s',30,31,'crampon1923','à ceux d''Hébron et dans tous les lieux où David et ses gens avaient passé.'),
('1s',31,1,'crampon1923','Les Philistins ayant livré bataille à Israël, les hommes d''Israël prirent la fuit devant les Philistins, et tombèrent blessés à mort sur la montagne de Gerboé.'),
('1s',31,2,'crampon1923','Les philistins s''attachèrent à la poursuite de Saül et de ses fils, et les Philistins tuèrent Jonathas, Abinadab, et Melchisua, fils de Saül.'),
('1s',31,3,'crampon1923','L''effort du combat se porta sur Saül: les archers l''ayant découvert, il eut grandement peur des archers.'),
('1s',31,4,'crampon1923','Alors Saül dit à son écuyer: « Tire ton épée et m''en transperce, de peur que les incirconcis ne viennent me transpercer et m''outrager. » Son écuyer ne le voulut pas faire, car il était saisi de crainte; alors Saül prit son épée et se jeta dessus.'),
('1s',31,5,'crampon1923','L''écuyer, voyant que Saül était mort, se jeta aussi sur son épée et mourut avec lui.'),
('1s',31,6,'crampon1923','Ainsi périrent ensemble dans cette journée Saül et ses trois fils, son écuyer et tous ses hommes.'),
('1s',31,7,'crampon1923','Les hommes d''Israël qui étaient de ce côté de la Plaine et ceux qui étaient de ce côté du Jourdain, voyant que les enfants d''Israël s''étaient enfuis, et que Saül et ses fils étaient morts, abandonnèrent leurs villes et prirent aussi la fuite; et les Philistins vinrent et s''y établirent.'),
('1s',31,8,'crampon1923','Le lendemain, les Philistins vinrent pour dépouiller les morts, et ils trouvèrent Saül et ses trois fils gisant sur la montagne de Gelboé.'),
('1s',31,9,'crampon1923','Ils lui coupèrent la tête et lui enlevèrent ses armes; puis ils envoyèrent publier cette bonne nouvelle par tout le pays des Philistins, dans les temples de leurs idoles et parmi le peuple.'),
('1s',31,10,'crampon1923','Ils déposèrent les armes de Saül dans le temple d''Astarté, et ils attachèrent son cadavre aux murailles de Bethsan.'),
('1s',31,11,'crampon1923','Les habitants de Jabès en Galaad ayant appris ce que les Philistins avaient fait à Saül,'),
('1s',31,12,'crampon1923','tous les vaillants hommes se levèrent et, après avoir marché toute la nuit, ils enlevèrent des murailles de Bethsan le cadavre de Saül et les cadavres de ses fils, puis ils revinrent à Jabès, où ils les brûlèrent.'),
('1s',31,13,'crampon1923','Ils prirent leurs os et les enterrèrent sous le tamarisque, à Jabès; et ils jeûnèrent sept jours.'),
('2s',1,1,'crampon1923','Après la mort de Saül, David était revenu de battre les Amalécites, et David demeurait depuis deux jours à Siceleg.'),
('2s',1,2,'crampon1923','Le troisième jour, voici qu''un homme arriva du camp, d''auprès de Saül, les vêtements déchirés et de la terre sur la tête. Lorsqu''il arriva près de David, il se jeta par terre et se prosterna.'),
('2s',1,3,'crampon1923','David lui dit: « D''où viens-tu? » Et il lui répondit: « Je me suis sauvé du camp d''Israël. »'),
('2s',1,4,'crampon1923','David lui dit: « Qu''est-il arrivé? Raconte-le-moi donc. » Il dit: « Le peuple s''est enfui de la bataille, et un grand nombre parmi le peuple sont tombés et ont péri; Saül même et son fils Jonathas sont morts. »'),
('2s',1,5,'crampon1923','David dit au jeune homme qui lui apportait ces nouvelles: « Comment sais-tu que Saül et son fils Jonathas sont morts? »'),
('2s',1,6,'crampon1923','Et le jeune homme qui lui apportait la nouvelle répondit: « Je me trouvais par hasard sur la montagne de Gelboé; et voici que Saül s''appuyait sur sa lance, et voici que les chars et les cavaliers étaient près de l''atteindre.'),
('2s',1,7,'crampon1923','Il se retourna et, m''ayant aperçu, il m''appela, et je dis: « Me voici. »'),
('2s',1,8,'crampon1923','Et il me dit: « Qui es-tu? » Je lui répondis: « Je suis un Amalécite. »'),
('2s',1,9,'crampon1923','Et il me dit: « Approche-toi donc de moi et donne-moi la mort; car je suis pris de vertige, et ma vie est encore tout entière en moi. »'),
('2s',1,10,'crampon1923','Je m''approchai de lui et je lui donnai la mort, car je savais bien qu''il ne survivrait pas à sa défaite. J''ai pris le diadème qui était sur sa tête et le bracelet qu''il avait au bras, et je les apporte ici à mon seigneur. »'),
('2s',1,11,'crampon1923','David saisit ses vêtements et les déchira, et tous les hommes qui étaient auprès de lui firent de même.'),
('2s',1,12,'crampon1923','Ils célébrèrent leur deuil, pleurant et jeûnant jusqu''au soir, sur Saül, sur son fils Jonathas, sur le peuple de Yahweh et sur la maison d''Israël, parce qu''ils étaient tombés par l''épée.'),
('2s',1,13,'crampon1923','David dit au jeune homme qui lui avait apporté la nouvelle: « D''où es-tu? » Il répondit: « Je suis fils d''un étranger, d''un Amalécite. »'),
('2s',1,14,'crampon1923','David lui dit: « Comment n''as-tu pas craint d''étendre ta main pour donner la mort à l''oint de Yahweh? »'),
('2s',1,15,'crampon1923','Et David, appelant un des jeunes gens, dit: « Approche et tue-le. » Cet homme frappa l''Amalécite, et il mourut.'),
('2s',1,16,'crampon1923','Et David lui dit: « Que ton sang soit sur ta tête! Car ta bouche a déposé contre toi quand tu as dit: C''est moi qui ai donné la mort à l''oint de Yahweh. »'),
('2s',1,17,'crampon1923','David entonna ce chant funèbre sur Saül et sur Jonathas, son fils,'),
('2s',1,18,'crampon1923','et il ordonna de l''enseigner aux enfants de Juda; c''est le chant de l''Arc. Voici qu''il est écrit dans le Livre du Juste:'),
('2s',1,19,'crampon1923','La splendeur d''Israël a-t-elle péri sur tes hauteurs? Comment sont tombés les héros?'),
('2s',1,20,'crampon1923','Ne l''annoncez pas à Geth, ne le publiez pas dans les rues d''Ascalon, de peur que les filles des Philistins ne s''en réjouissent, de peur que les filles des incirconcis ne sautent de joie!'),
('2s',1,21,'crampon1923','Montagnes de Gelboé, qu''il n''y ait sur vous ni rosée ni pluie, ni champs de prémices! Car là fut jeté bas le bouclier des héros. Le bouclier de Saül n''était pas oint d''huile,'),
('2s',1,22,'crampon1923','mais du sang des blessés, de la graisse des vaillants; l''arc de Jonathas ne recula jamais en arrière, et l''épée de Saül ne revenait pas inactive.'),
('2s',1,23,'crampon1923','Saül et Jonathas, chéris et aimables dans la vie et dans la mort, ils ne furent point séparés. Ils étaient plus agiles que les aigles, ils étaient plus forts que les lions.'),
('2s',1,24,'crampon1923','Filles d''Israël, pleurez sur Saül, qui vous revêtait de pourpre au sein des délices, qui mettait des ornements d''or sur vos vêtements!'),
('2s',1,25,'crampon1923','Comment les héros sont-ils tombés dans la bataille? Jonathas a été percé sur tes hauteurs!'),
('2s',1,26,'crampon1923','L''angoisse m''accable à cause de toi, Jonathas, mon frère. Tu faisais toutes mes délices; ton amour m''était plus précieux que l''amour des femmes.'),
('2s',1,27,'crampon1923','Comment les héros sont-ils tombés? Comment les guerriers ont-ils péri?'),
('2s',2,1,'crampon1923','Après cela, David consulta Yahweh, en disant: « Monterai-je dans une des villes de Juda? » Yahweh lui répondit: « Monte. » David dit: « Où monterai-je? » Et Yahweh répondit: « A Hébron. »'),
('2s',2,2,'crampon1923','David y monta, avec ses deux femmes, Achinoam de Jezraël et Abigaïl de Carmel, femme de Nabal.'),
('2s',2,3,'crampon1923','David fit aussi monter les hommes qui étaient avec lui, chacun avec sa famille; ils habitèrent dans les villes d''Hébron.'),
('2s',2,4,'crampon1923','Et les hommes de Juda vinrent, et là ils oignirent David pour roi sur la maison de Juda. On informa David que c''étaient les hommes de Jabès en Galaad qui avaient enterré Saül.'),
('2s',2,5,'crampon1923','Et David envoya des messagers aux gens de Jabès en Galaad pour leur dire: « Soyez bénis de Yahweh, de ce que vous avez rempli ce pieux devoir envers Saül, votre seigneur, et l''avez enterré.'),
('2s',2,6,'crampon1923','Et maintenant, que Yahweh use envers vous de bonté et de fidélité! Moi aussi, je vous rendrai ce bien, parce que vous avez agi de la sorte.'),
('2s',2,7,'crampon1923','Et, maintenant, que vos mains se fortifient, et soyez de vaillants hommes; car votre seigneur Saül est mort, et c''est moi que la maison de Juda a oint pour être son roi. »'),
('2s',2,8,'crampon1923','Cependant Abner, fils de Ner, chef de l''armée de Saül, prit Isboseth, fils de Saül, et, l''ayant fait passer à Mahanaïm,'),
('2s',2,9,'crampon1923','il l''établit roi sur Galaad, sur les Assurites, sur Jezraël, sur Ephraïm, sur Benjamin, sur tout Israël.'),
('2s',2,10,'crampon1923','— Isboseth, fils de Saül, était âgé de quarante ans lorsqu''il régna sur Israël, et il régna deux ans. — Seule, la maison de Juda restait attachée à David.'),
('2s',2,11,'crampon1923','Le temps pendant lequel David régna, à Hébron, sur la maison de Juda fut de sept ans et six mois.'),
('2s',2,12,'crampon1923','Abner, fils de Ner, et les serviteurs d''Isboseth, fils de Saül, sortirent de Mahanaïm pour marcher sur Gabaon.'),
('2s',2,13,'crampon1923','Joab, fils de Sarvia, et les serviteurs de David, se mirent aussi en marche. Ils se rencontrèrent près de l''étang de Gabaon, et ils s''établirent, les uns d''un côté de l''étang, les autres de l''autre côté de l''étang.'),
('2s',2,14,'crampon1923','Abner dit à Joab: « Que les jeunes gens se lèvent et qu''ils joutent devant nous! » Joab répondit: « Qu''ils se lèvent! »'),
('2s',2,15,'crampon1923','Ils se levèrent et s''avancèrent en nombre égal, douze pour Benjamin et pour Isboseth, fils de Saül, et douze des serviteurs de David.'),
('2s',2,16,'crampon1923','Chacun, saisissant son adversaire par la tête, enfonça son épée dans le flanc de son compagnon, et ils tombèrent tous ensemble. Et l''on donna à ce lieu le nom de Chelqath Hatsourim; il est en Gabaon.'),
('2s',2,17,'crampon1923','Et le combat devint très rude en ce jour-là, et Abner et les hommes d''Israël furent défaits par les serviteurs de David.'),
('2s',2,18,'crampon1923','Là se trouvaient les trois fils de Sarvia: Joab, Abisaï et Asaël. Asaël avait les pieds légers comme une des gazelles qui sont dans les champs;'),
('2s',2,19,'crampon1923','Asaël poursuivit Abner, sans se détourner de derrière Abner, pour aller à droite ou à gauche.'),
('2s',2,20,'crampon1923','Abner, se tourna derrière lui et dit: « Est-ce toi, Asaël? » Et il répondit: « C''est moi. »'),
('2s',2,21,'crampon1923','Abner lui dit: « Ecarte-toi à droite ou à gauche; saisis l''un des jeunes gens et prends sa dépouille. » Mais Asaël ne voulut pas se détourner de lui.'),
('2s',2,22,'crampon1923','Abner dit encore à Asaël: « Détourne-toi de derrière moi; pourquoi te frapperais-je et t''étendrais-je par terre? Comment pourrais-je ensuite lever mon visage devant Joab, ton frère! »'),
('2s',2,23,'crampon1923','Et Asaël refusa de se détourner. Alors Abner le frappa au ventre avec l''extrémité inférieure de sa lance, et la lance sortit par derrière. Il tomba là, et mourut sur place. Tous ceux qui arrivaient au lieu où Asaël était tombé et était mort, s''y arrêtaient.'),
('2s',2,24,'crampon1923','Joab et Abisaï poursuivirent Abner; au coucher du soleil, ils arrivèrent à la colline d''Ammah, qui est à l''est de Giach, sur le chemin du désert de Gabaon.'),
('2s',2,25,'crampon1923','Les fils de Benjamin se rallièrent à la suite d''Abner et, réunis en un seul corps d''armée, ils s''arrêtèrent au sommet d''une colline.'),
('2s',2,26,'crampon1923','Abner appela Joab et dit: « L''épée dévorera-t-elle toujours? Ne sais-tu pas qu''il y aura de l''amertume à la fin? Jusques à quand attendras-tu à dire au peuple de cesser de poursuivre ses frères? »'),
('2s',2,27,'crampon1923','Joab répondit: « Aussi vrai que Dieu est vivant! si tu n''avais pas parlé, le peuple n''aurait pas cessé avant demain matin de poursuivre chacun son frère. »'),
('2s',2,28,'crampon1923','Et Joab sonna de la trompette, et tout le peuple s''arrêta; ils ne poursuivirent plus Israël, et ils ne continuèrent pas à se battre.'),
('2s',2,29,'crampon1923','Abner et ses gens, après avoir marché toute la nuit dans la Plaine, passèrent le Jourdain, traversèrent tout le Bithron, et arrivèrent à Mahanaïm.'),
('2s',2,30,'crampon1923','Joab aussi cessa de poursuivre Abner et rassembla tout le peuple; il manquait dix-neuf hommes des serviteurs de David, et Asaël.'),
('2s',2,31,'crampon1923','Et les serviteurs de David avaient frappé à mort trois cent soixante hommes de Benjamin et des hommes d''Abner.'),
('2s',2,32,'crampon1923','Ils emportèrent Asaël et l''enterrèrent dans le sépulcre de son père, qui est à Bethléem. Joab et ses hommes marchèrent toute la nuit, et ils arrivèrent à Hébron au point du jour.'),
('2s',3,1,'crampon1923','La guerre fut longue entre la maison de Saül et la maison de David. David allait se fortifiant, et la maison de Saül allait s''affaiblissant.'),
('2s',3,2,'crampon1923','Il naquit à David des fils à Hébron. Son premier-né fut Ammon, d''Achinoam de Jezraël;'),
('2s',3,3,'crampon1923','le second Chéléab, d''Abigaïl de Carmel, femme de Nabal; le troisième Absalom, fils de Maaca, fille de Tholmaï, roi de Gessur;'),
('2s',3,4,'crampon1923','le quatrième Adonias, fils de Haggith; le cinquième Saphathia, fils d''Abital,'),
('2s',3,5,'crampon1923','et le sixième Jéthraam, d''Egla, femme de David. Tels sont les fils qui naquirent à David à Hébron.'),
('2s',3,6,'crampon1923','Pendant qu''il y avait guerre entre la maison de Saül et la maison de David, Abner se fortifiait dans la maison de Saül.'),
('2s',3,7,'crampon1923','Or Saül avait eu une concubine, nommée Respha, fille d''Aia. Et Isboseth dit à Abner:'),
('2s',3,8,'crampon1923','« Pourquoi es-tu venu vers la concubine de mon père? » Abner, très irrité des paroles d''Isboseth, répondit: « Suis-je une tête de chien appartenant à Juda? Aujourd''hui je montre de la faveur à la maison de Saül, ton père, à ses frères et à ses amis, et je ne t''ai point livré aux mains de David, et c''est aujourd''hui que tu me reproches une faute avec cette femme?'),
('2s',3,9,'crampon1923','Que Dieu traite Abner dans toute sa rigueur, si je n''agis pas avec David selon ce que Yahweh lui a juré,'),
('2s',3,10,'crampon1923','en disant qu''il enlèverait la royauté de la maison de Saül, et qu''il établirait le trône de David sur Israël et sur Juda, depuis Dan jusqu''à Bersabée! »'),
('2s',3,11,'crampon1923','Isboseth ne put répondre un seul mot à Abner, parce qu''il le craignait.'),
('2s',3,12,'crampon1923','Abner envoya des messagers à David pour lui dire de sa part: « A qui est le pays? Fais ton alliance avec moi, et voici que ma main t''aidera pour tourner vers toi tout Israël. »'),
('2s',3,13,'crampon1923','Il répondit: « Bien! je ferai alliance avec toi; mais je te demande une chose, c''est que tu ne voies pas ma face sans m''amener Michol, fille de Saül, lorsque tu viendras pour voir ma face. »'),
('2s',3,14,'crampon1923','Et David envoya des messagers à Isboseth, fils de Saül, pour lui dire: « Donne-moi ma femme Michol, que j''ai épousée pour cent prépuces de Philistins. »'),
('2s',3,15,'crampon1923','Isboseth l''envoya prendre à son mari Phaltiel, fils de Laïs;'),
('2s',3,16,'crampon1923','et son mari l''accompagna, marchant et pleurant derrière elle, jusqu''à Bathurim. Là Abner lui dit: « Va, retourne chez toi. » Et il s''en retourna.'),
('2s',3,17,'crampon1923','Abner eut des pourparlers avec les anciens d''Israël, et leur dit: « Vous désiriez depuis longtemps déjà avoir David pour roi;'),
('2s',3,18,'crampon1923','agissez donc maintenant, car Yahweh a dit à David: C''est par la main de David, mon serviteur, que je délivrerai mon peuple d''Israël de la main des Philistins et de la main de tous ses ennemis. »'),
('2s',3,19,'crampon1923','Abner parla aussi aux oreilles de Benjamin, et Abner alla reporter aux oreilles de David, à Hébron, ce qui paraissait bon aux yeux d''Israël et aux yeux de toute la maison de Benjamin.'),
('2s',3,20,'crampon1923','Abner vint près de David, à Hébron, accompagné de vingt hommes; et David fit un festin à Abner et aux hommes qui l''accompagnaient.'),
('2s',3,21,'crampon1923','Et Abner dit à David: « Je vais me lever et partir pour rassembler tout Israël vers mon seigneur le roi; ils feront alliance avec toi et tu régneras sur tout ce que ton âme désire. » Et David congédia Abner, qui s''en alla en paix.'),
('2s',3,22,'crampon1923','Mais voici que les serviteurs de David et Joab revenaient d''une excursion, ramenant avec eux un grand butin. — Abner n''était plus auprès de David à Hébron, car David l''avait congédié et il s''en était allé en paix. —'),
('2s',3,23,'crampon1923','Joab et toute la troupe qui était avec lui arrivèrent, et on fit ce rapport à Joab: « Abner, fils de Ner, est venu auprès du roi, qui l''a congédié, et il s''en est allé en paix. »'),
('2s',3,24,'crampon1923','Joab se rendit chez le roi et dit: « Qu''as-tu fait? Voilà qu''Abner est venu vers toi: pourquoi l''as-tu congédié et laissé partir?'),
('2s',3,25,'crampon1923','Tu connais Abner, fils de Ner: c''est pour te tromper qu''il est venu, pour épier ta conduite, et savoir tout ce que tu fais. »'),
('2s',3,26,'crampon1923','Joab, ayant quitté David, envoya sur les traces d''Abner des messagers qui le ramenèrent depuis la citerne de Sira, sans que David en sût rien.'),
('2s',3,27,'crampon1923','Quand Abner fut de retour à Hébron, Joab le tira à l''écart, dans l''intérieur de la porte, comme pour lui parler tranquillement, et là il le frappa au ventre; il mourut, à cause du sang d''Asaël, frère de Joab.'),
('2s',3,28,'crampon1923','David l''apprit ensuite, et il dit: « Je suis à jamais, moi et mon royaume, innocent, devant Yahweh, du sang d''Abner, fils de Ner.'),
('2s',3,29,'crampon1923','Que ce sang retombe sur la tête de Joab et sur toute la maison de son père! Qu''il y ait toujours dans la maison de Joab un homme qui souffre d''un flux ou de la lèpre, ou qui tienne le fuseau, ou qui tombe par l''épée, ou qui manque de pain. »'),
('2s',3,30,'crampon1923','C''est ainsi que Joab et Abisaï, son frère, tuèrent Abner, parce qu''il avait donné la mort à leur frère Asaël, à Gabaon, dans la bataille.'),
('2s',3,31,'crampon1923','David dit à Joab et à tout le peuple qui était avec lui: « Déchirez-vos vêtements, ceignez-vous de sacs et faites le deuil devant Abner. » Et le roi David marchait derrière la litière.'),
('2s',3,32,'crampon1923','On enterra Abner à Hébron. Le roi pleura à haute voix sur le tombeau d''Abner et tout le peuple pleura.'),
('2s',3,33,'crampon1923','Le roi chanta un chant funèbre sur Abner, et dit: Abner devait-il mourir comme meurt un insensé?'),
('2s',3,34,'crampon1923','Tes mains ne furent pas liées et tes pieds ne furent pas jetés dans les chaînes! Tu es tombé comme on tombe devant des scélérats. Tout le peuple continua de se lamenter sur Abner;'),
('2s',3,35,'crampon1923','et tout le peuple s''approcha de David pour lui faire prendre de la nourriture lorsqu''il était encore jour. Mais David fit ce serment: « Que Yahweh me traite dans toute sa rigueur, si je goûte du pain ou quoi que ce soit avant le coucher du soleil! »'),
('2s',3,36,'crampon1923','Tout le peuple le remarqua et le trouva bon, comme il trouvait bon tout ce que faisait le roi.'),
('2s',3,37,'crampon1923','Tout le peuple et tout Israël comprirent en ce jour que ce n''était point de par le roi qu''on avait fait mourir Abner, fils de Ner.'),
('2s',3,38,'crampon1923','Le roi dit à ses serviteurs: « Ne savez-vous pas qu''un chef, qu''un grand homme est tombé aujourd''hui en Israël?'),
('2s',3,39,'crampon1923','Pour moi, je suis doux, quoiqu''ayant reçu l''onction royale; et ces hommes, les fils de Sarvia, sont plus durs que moi. Que Yahweh rende à qui fait le mal selon le mal qu''il fait! »'),
('2s',4,1,'crampon1923','Lorsque le fils de Saül apprit qu''Abner était mort à Hébron, ses mains furent sans force, et tout Israël fut dans la consternation.'),
('2s',4,2,'crampon1923','Le fils de Saül avait deux chefs de bandes, dont l''un s''appelait Baana, et l''autre Réchab, tous deux fils de Remmon de Béroth, d''entre les fils de Benjamin. Car Béroth est aussi comptée comme faisant partie de Benjamin,'),
('2s',4,3,'crampon1923','et les Bérothites s''étaient enfuis à Géthaïm, et ils y ont habité jusqu''à ce jour.'),
('2s',4,4,'crampon1923','Jonathas, fils de Saül, avait un fils perclus des deux pieds. Cet enfant était âgé de cinq ans lorsque la nouvelle de la mort de Saül et de Jonathas arriva de Jezraël; sa nourrice l''avait pris et s''était enfuie, et, dans la précipitation de sa fuite, il était tombé et devenu boiteux; il s''appelait Miphiboseth.'),
('2s',4,5,'crampon1923','Or les fils de Remmon de Béroth, Réchab et Baana, vinrent et entrèrent pendant la chaleur du jour dans la maison d''Isboseth, qui était couché pour le repos de midi.'),
('2s',4,6,'crampon1923','Ayant pénétré jusqu''au milieu de la maison pour prendre du blé, ils le frappèrent au ventre. Et Réchab, et Baana, son frère, se glissèrent à la dérobée.'),
('2s',4,7,'crampon1923','Quand ils entrèrent dans la maison, Isboseth reposait sur son lit, dans sa chambre à coucher; ils le frappèrent à mort et, lui ayant coupé la tête, ils la prirent, et marchèrent toute la nuit au travers de la Plaine.'),
('2s',4,8,'crampon1923','Ils apportèrent la tête d''Isboseth à David, à Hébron, et ils dirent au roi: « Voici la tête d''Isboseth, fils de Saül, ton ennemi, qui en voulait à ta vie. Yahweh a accordé aujourd''hui au roi, mon seigneur, la vengeance sur Saül et sur sa race. »'),
('2s',4,9,'crampon1923','David répondit à Réchab et à Baana, son frère, fils de Remmon de Béroth, et leur dit: « Yahweh, qui m''a délivré de tout péril, est vivant!'),
('2s',4,10,'crampon1923','Celui qui est venu me dire cette nouvelle: Voici que Saül est mort, celui-là était à ses propres yeux porteur d''une bonne nouvelle; mais je l''ai fait saisir et mettre à mort à Siceleg, pour lui donner le salaire de son bon message;'),
('2s',4,11,'crampon1923','combien plus, quand de méchants hommes ont assassiné un homme innocent dans sa maison, sur sa couche, dois-je redemander son sang de vos mains et vous exterminer de la terre? »'),
('2s',4,12,'crampon1923','Et David ordonna aux jeunes gens de les tuer; ils leurs coupèrent les mains et les pieds et les pendirent au bord de l''étang d''Hébron. Puis, ayant pris la tête d''Isboseth, ils l''enterrèrent dans le tombeau d''Abner à Hébron.'),
('2s',5,1,'crampon1923','Toutes les tribus d''Israël vinrent auprès de David, à Hébron, et dirent: « Nous voici: nous sommes tes os et ta chair.'),
('2s',5,2,'crampon1923','Autrefois déjà, quand Saül était notre roi, c''était toi qui menais et ramenais Israël. Et Yahweh t''a dit: “C''est toi qui paîtras mon peuple d''Israël, et c''est toi qui seras prince sur Israël.” »'),
('2s',5,3,'crampon1923','Ainsi tous les anciens d''Israël vinrent auprès du roi, à Hébron, et le roi David fit alliance avec eux devant Yahweh, à Hébron, et ils oignirent David pour roi sur Israël.'),
('2s',5,4,'crampon1923','David était âgé de trente ans lorsqu''il devint roi, et il régna quarante ans.'),
('2s',5,5,'crampon1923','A Hébron, il régna sur Juda sept ans et six mois, et il régna à Jérusalem trente-trois ans sur tout Israël et Juda.'),
('2s',5,6,'crampon1923','Le roi marcha avec ses hommes sur Jérusalem contre les Jébuséens, habitants du pays. Et on dit à David: « Tu n''entreras pas ici, mais les aveugles et les boiteux te repousseront ». Ce qui voulait dire: David n''entrera jamais ici.'),
('2s',5,7,'crampon1923','Mais David s''empara de la forteresse de Sion: c''est la cité de David.'),
('2s',5,8,'crampon1923','David dit ce jour-là: « Quiconque frappera les Jébuséens et atteindra par le canal... » Quant aux boiteux et aux aveugles, ce sont les ennemis de l''âme de David. De là vient le dicton: « L''aveugle et le boiteux n''entreront point dans la maison. »'),
('2s',5,9,'crampon1923','David s''établit dans la forteresse et l''appela cité de David, et David bâtit à l''entour, à partir du Mello, et à l''intérieur.'),
('2s',5,10,'crampon1923','David devenait de plus en plus grand, et Yahweh, le Dieu des armées, était avec lui.'),
('2s',5,11,'crampon1923','Hiram, roi de Tyr, envoya des messagers à David, avec des bois de cèdre, ainsi que des charpentiers et des tailleurs de pierres, qui bâtirent une maison à David.'),
('2s',5,12,'crampon1923','Et David reconnut que Yahweh l''affermissait comme roi sur Israël, et qu''il élevait sa royauté à cause de son peuple d''Israël.'),
('2s',5,13,'crampon1923','David prit encore des concubines et des femmes de Jérusalem, après qu''il fut venu d''Hébron, et il naquit encore à David des fils et des filles.'),
('2s',5,14,'crampon1923','Voici les noms de ceux qui lui naquirent à Jérusalem: Samua, Sobab, Nathan, Salomon,'),
('2s',5,15,'crampon1923','Jébahar, Elisua, Népheg,'),
('2s',5,16,'crampon1923','Japhia, Elisama, Elioda et Eliphaleth.'),
('2s',5,17,'crampon1923','Les Philistins apprirent qu''on avait oint David pour roi sur Israël; alors tous les Philistins montèrent pour rechercher David. David l''apprit et il descendit à la forteresse.'),
('2s',5,18,'crampon1923','Les Philistins, étant venus, se répandirent dans la vallée des Rephaïm.'),
('2s',5,19,'crampon1923','David consulta Yahweh, en disant: « Monterai-je contre les Philistins? Les livrerez-vous entre mes mains? » Et Yahweh dit à David: « Monte, car je livrerai certainement les Philistins entre tes mains. »'),
('2s',5,20,'crampon1923','David vint donc à Baal-Pharasim, et là David les battit. Et il dit: « Yahweh a brisé mes ennemis devant moi, comme les eaux brisent les digues. » C''est pourquoi on a donné à ce lieu le nom de Baal-Pharasim.'),
('2s',5,21,'crampon1923','Ils laissèrent là leurs idoles, et David et ses gens les emportèrent.'),
('2s',5,22,'crampon1923','Les Philistins montèrent de nouveau et se répandirent dans la vallée des Rephaïm.'),
('2s',5,23,'crampon1923','Et David consulta Yahweh, qui lui dit: « Ne monte pas; tourne-les par derrière, et tu arriveras sur eux du côté des balsamiers.'),
('2s',5,24,'crampon1923','Quand tu entendras un bruit de pas dans les cimes des balsamiers, alors attaque vivement, car alors Yahweh sortira devant toi pour porter ses coups dans l''armée des Philistins. »'),
('2s',5,25,'crampon1923','David fit ainsi, comme Yahweh le lui ordonnait, et il battit les Philistins depuis Gabaa jusqu''à Géser.'),
('2s',6,1,'crampon1923','David rassembla encore toute l''élite d''Israël, au nombre de trente mille hommes.'),
('2s',6,2,'crampon1923','Accompagné de tout le peuple réuni auprès de lui, David se leva et se mit en marche depuis Baalé-Juda, pour faire monter de là l''arche de Dieu, sur laquelle est invoqué le Nom, le nom de Yahweh des armées qui siège sur les Chérubins.'),
('2s',6,3,'crampon1923','Ils placèrent sur un chariot neuf l''arche de Dieu, et l''emmenèrent de la maison d''Abinadab, qui était sur la colline; Oza et Achio, fils d''Abinadab, conduisaient le chariot neuf'),
('2s',6,4,'crampon1923','(et ils l''emmenèrent de la maison d''Abinadab, qui était sur la colline) avec l''arche de Dieu; Achio marchait devant l''arche.'),
('2s',6,5,'crampon1923','David et toute la maison d''Israël dansaient devant Yahweh, au son de toutes sortes d''instruments de bois de cyprès, de harpes, de luths, de tambourins, de sistres et de cymbales.'),
('2s',6,6,'crampon1923','Lorsqu''ils furent arrivés à l''aire de Nachon, Oza étendit la main vers l''arche de Dieu et la saisit, parce que les bœufs avaient fait un faux pas.'),
('2s',6,7,'crampon1923','La colère de Yahweh s''enflamma contre Oza, et Dieu le frappa sur place, à cause de sa précipitation; et Oza mourut là, près de l''arche de Dieu.'),
('2s',6,8,'crampon1923','David fut fâché de ce que Yahweh avait ainsi porté un coup à Oza; et ce lieu a été appelé jusqu''à ce jour Phéréts-Oza.'),
('2s',6,9,'crampon1923','David eut peur de Yahweh en ce jour-là, et il dit: « Comment l''arche de Yahweh viendrait-elle vers moi? »'),
('2s',6,10,'crampon1923','Et David ne voulut pas retirer l''arche de Yahweh chez lui, dans la cité de David; et la David la fit conduire dans la maison d''Obédédom de Geth.'),
('2s',6,11,'crampon1923','L''arche de Yahweh resta trois mois dans la maison d''Obédédom de Geth, et Yahweh bénit Obédédom et toute sa maison.'),
('2s',6,12,'crampon1923','On vint dire au roi David: « Yahweh a béni la maison d''Obédédom et tout ce qui est à lui, à cause de l''arche de Dieu. » Et David se mit en route, et il fit monter l''arche de Dieu de la maison d''Obédédom dans la cité de David, avec un joyeux cortège.'),
('2s',6,13,'crampon1923','Quand les porteurs de l''arche de Yahweh eurent fait six pas, on offrit en sacrifice un bœuf et un veau gras.'),
('2s',6,14,'crampon1923','David dansait de toute sa force devant Yahweh, et David était ceint d''un éphod de lin.'),
('2s',6,15,'crampon1923','David et toute la maison d''Israël firent monter l''arche de Yahweh avec des cris de joie et au son des trompettes.'),
('2s',6,16,'crampon1923','Lorsque l''arche de Yahweh entra dans la cité de David, Michol, fille de Saül, regarda par la fenêtre et, voyant le roi David sauter et danser devant Yahweh, elle le méprisa dans son cœur.'),
('2s',6,17,'crampon1923','Après qu''on eut fait entrer l''arche de Yahweh et qu''on l''eut déposée à sa place, au milieu de la tente que David avait dressée pour elle, David offrit devant Yahweh des holocaustes et des sacrifices pacifiques.'),
('2s',6,18,'crampon1923','Quand David eut achevé d''offrir les holocaustes et les sacrifices pacifiques, il bénit le peuple au nom de Yahweh des armées.'),
('2s',6,19,'crampon1923','Puis il distribua à tout le peuple, à toute la multitude d''Israël, hommes et femmes, à chacun un gâteau, une portion de viande et une pâte de raisins. Et tout le peuple s''en alla chacun dans sa maison.'),
('2s',6,20,'crampon1923','Comme David s''en retournait pour bénir sa maison, Michol, fille de Saül, sortit à la rencontre de David, et elle dit: « Quelle gloire aujourd''hui pour le roi d''Israël de s''être découvert aujourd''hui aux yeux des servantes de ses serviteurs, comme se découvrirait un homme de rien! »'),
('2s',6,21,'crampon1923','David répondit à Michol: « C''est devant Yahweh, qui m''a choisi de préférence à ton père et à toute sa maison pour m''établir prince sur son peuple, sur Israël, c''est devant Yahweh que j''ai dansé.'),
('2s',6,22,'crampon1923','Je m''humilierai encore plus que cela et je serai vil à mes propres yeux, et auprès des servantes dont tu parles, auprès d''elles, je serai en honneur. »'),
('2s',6,23,'crampon1923','Et Michol, fille de Saül, n''eut point d''enfant jusqu''au jour de sa mort.'),
('2s',7,1,'crampon1923','Lorsque le roi fut établi dans sa maison et que Yahweh lui eut donné du repos en le délivrant de tous ses ennemis à l''entour,'),
('2s',7,2,'crampon1923','le roi dit à Nathan le prophète: « Vois donc! J''habite dans une maison de cèdre, et l''arche de Dieu habite au milieu de la tente! »'),
('2s',7,3,'crampon1923','Nathan répondit au roi: « Va, fais tout ce que tu as dans le cœur, car Yahweh est avec toi. »'),
('2s',7,4,'crampon1923','Cette nuit-là, la parole de Yahweh fut adressée à Nathan en ces termes:'),
('2s',7,5,'crampon1923','« Va dire à mon serviteur, à David: Ainsi parle Yahweh: Est-ce toi qui me bâtirais une maison pour que j''y habite?'),
('2s',7,6,'crampon1923','Car je n''ai point habité dans une maison depuis le jour où j''ai fait monter d''Egypte les enfants d''Israël jusqu''à ce jour; j''ai voyagé sous une tente et dans un tabernacle.'),
('2s',7,7,'crampon1923','Pendant tout le temps que j''ai voyagé avec tous les enfants d''Israël, ai-je dit un mot à l''un des chefs d''Israël à qui j''ai ordonné de paître mon peuple d''Israël, en disant: Pourquoi ne me bâtissez-vous pas une maison de cèdre?'),
('2s',7,8,'crampon1923','Maintenant, tu diras à mon serviteur, à David: Ainsi parle Yahweh des armées: Je t''ai pris au pâturage, derrière les brebis, pour être prince sur mon peuple, sur Israël;'),
('2s',7,9,'crampon1923','j''ai été avec toi partout où tu allais, j''ai exterminé tous tes ennemis devant toi, et je t''ai fait un grand nom, comme le nom des grands qui sont sur la terre;'),
('2s',7,10,'crampon1923','j''ai assigné un lieu à mon peuple, à Israël, et je l''ai planté, et il habite chez lui, et il ne sera plus troublé, et les fils d''iniquité ne l''opprimeront plus, comme autrefois'),
('2s',7,11,'crampon1923','et comme au jour où j''avais établi des juges sur mon peuple d''Israël. Je t''ai accordé du repos en te délivrant de tous tes ennemis. Et Yahweh t''annonce qu''il te fera une maison.'),
('2s',7,12,'crampon1923','Quand tes jours seront accomplis et que tu seras couché avec tes pères, j''élèverai ta postérité après toi, celui qui sortira de tes entrailles, et j''affermirai sa royauté.'),
('2s',7,13,'crampon1923','C''est lui qui bâtira une maison à mon nom, et j''affermirai pour toujours le trône de son royaume.'),
('2s',7,14,'crampon1923','Je serai pour lui un père, et il sera pour moi un fils. S''il fait le mal, je le châtierai avec une verge d''hommes et des coups de fils d''hommes.'),
('2s',7,15,'crampon1923','Mais ma grâce ne se retirera point de lui, comme je l''ai retirée de Saül, que j''ai retiré de devant toi.'),
('2s',7,16,'crampon1923','Ta maison et ta royauté seront pour toujours assurées devant toi; ton trône sera affermi pour toujours. »'),
('2s',7,17,'crampon1923','Nathan parla à David selon toutes ces paroles et toute cette vision.'),
('2s',7,18,'crampon1923','Le roi David vint et demeura devant Yahweh; et il dit: « Qui suis-je, Seigneur Yahweh, et quelle est ma maison, pour que vous m''ayez fait arriver jusque-là?'),
('2s',7,19,'crampon1923','Et c''est encore peu de chose à vos yeux, Seigneur Yahweh; vous avez parlé aussi de la maison de votre serviteur pour les temps lointains: c''est agir à mon égard selon la loi de l''homme, Seigneur Yahweh!'),
('2s',7,20,'crampon1923','Que pourrait vous dire de plus David? Vous connaissez votre serviteur, Seigneur Yahweh!'),
('2s',7,21,'crampon1923','C''est à cause de votre parole et selon votre cœur que vous avez fait toute cette grande chose, pour la faire connaître à votre serviteur.'),
('2s',7,22,'crampon1923','C''est pourquoi vous êtes grand, Seigneur Yahweh! car nul n''est semblable à vous, et il n''y a point d''autre Dieu que vous, d''après tout ce que nous avons entendu de nos oreilles.'),
('2s',7,23,'crampon1923','Quelle autre nation y a-t-il sur la terre comme votre peuple, comme Israël, que Dieu est venu racheter pour en faire son peuple, pour lui faire un nom et accomplir pour vous des choses grandes et des prodiges en faveur de votre terre, en chassant de devant votre peuple, que vous vous êtes racheté d''Egypte, les nations et leurs dieux?'),
('2s',7,24,'crampon1923','Vous avez affermi votre peuple d''Israël pour qu''il soit votre peuple à jamais, et vous, Yahweh, vous êtes devenu son Dieu.'),
('2s',7,25,'crampon1923','Maintenant donc, Yahweh Dieu, la parole que vous avez dite au sujet de votre serviteur et au sujet de sa maison, maintenez-la à jamais et agissez selon votre parole;'),
('2s',7,26,'crampon1923','et que votre nom soit glorifié à jamais, et que l''on dise: Yahweh des armées est Dieu sur Israël! Et que la maison de votre serviteur David soit affermie devant vous.'),
('2s',7,27,'crampon1923','Car vous-même Yahweh des armées, Dieu d''Israël, vous vous êtes révélé à votre serviteur, en disant: Je te bâtirai une maison; c''est pourquoi votre serviteur s''est enhardi à vous adresser cette prière.'),
('2s',7,28,'crampon1923','Maintenant, Seigneur Yahweh, c''est vous qui êtes Dieu, et vos paroles sont vraies. Or vous avez dit à votre serviteur cette parole agréable;'),
('2s',7,29,'crampon1923','maintenant, qu''il vous plaise de bénir la maison de votre serviteur, afin qu''elle subsiste à jamais devant vous. Car c''est vous, Seigneur Yahweh, qui avez parlé, et par votre bénédiction la maison de votre serviteur sera bénie éternellement. »'),
('2s',8,1,'crampon1923','Après cela, David battit les Philistins et les abaissa, et David ôta de la main des Philistins les rênes de leur capitale.'),
('2s',8,2,'crampon1923','Il battit les Moabites et, les ayant fait coucher par terre, il les mesura au cordeau; il en mesura deux cordeaux pour les faire mourir, et un plein cordeau pour leur laisser la vie. Et les Moabites furent pour David des esclaves lui apportant le tribut.'),
('2s',8,3,'crampon1923','David battit Hadadézer, fils de Rohob, roi de Soba, lorsqu''il était en chemin pour établir sa domination sur le fleuve de l''Euphrate.'),
('2s',8,4,'crampon1923','Et David lui prit mille sept cents cavaliers et vingt mille hommes de pied; et David coupa les jarrets à tous les chevaux d''attelage et n''en laissa que cent attelages.'),
('2s',8,5,'crampon1923','Les Syriens de Damas étant venus au secours d''Hadadézer, roi de Soba, David battit aux Syriens vingt-deux mille hommes.'),
('2s',8,6,'crampon1923','David mit des garnisons dans la Syrie de Damas, et les Syriens furent pour David des esclaves apportant le tribut. Yahweh donnait la victoire à David partout où il allait.'),
('2s',8,7,'crampon1923','David prit les boucliers d''or qui étaient sur les serviteurs d''Hadadézer, et les apporta à Jérusalem.'),
('2s',8,8,'crampon1923','Le roi David prit encore une grande quantité d''airain à Bété et à Béroth, villes d''Hadadézer.'),
('2s',8,9,'crampon1923','Lorsque Thoü, roi de Hamath, apprit que David avait battu toutes les forces d''Hadadézer,'),
('2s',8,10,'crampon1923','Thoü envoya Joram, son fils, vers le roi David, pour le saluer et le féliciter d''avoir attaqué Hadadézer et de l''avoir battu, car Thoü était constamment en guerre avec Hadadézer. Joram avait dans la main des vases d''or, des vases d''argent et des vases d''airain.'),
('2s',8,11,'crampon1923','Le roi David les consacra aussi à Yahweh, avec l''argent et l''or qu''il consacra après les avoir enlevés à toutes les nations qu''il avait foulées aux pieds,'),
('2s',8,12,'crampon1923','à la Syrie, à Moab, aux fils d''Ammon, aux Philistins, à Amalec, et au butin d''Hadadézer, fils de Rohob, roi de Soba.'),
('2s',8,13,'crampon1923','David se fit un nom, lorsqu''il revint de battre les Syriens, dans la vallée du Sel, au nombre de dix-huit mille.'),
('2s',8,14,'crampon1923','Il mit des garnisons dans Edom; en tout Edom il mit des garnisons, et tout Edom fut assujetti à David. Et Yahweh donnait la victoire à David partout où il allait.'),
('2s',8,15,'crampon1923','David régna sur tout Israël, et David faisait droit et justice à tout son peuple.'),
('2s',8,16,'crampon1923','Joab, fils de Sarvia, commandait l''armée; Josaphat, fils d''Ahilud, était archiviste;'),
('2s',8,17,'crampon1923','Sadoc, fils d''Achitob, et Achimélec, fils d''Abiathar, étaient prêtres; Saraias était secrétaire;'),
('2s',8,18,'crampon1923','Banaïas, fils de Joiada, était chef des Céréthiens et des Phéléthiens; et les fils de David étaient ses conseillers intimes.'),
('2s',9,1,'crampon1923','David dit: « Reste-t-il encore quelqu''un de la maison de Saül, que je lui fasse du bien à cause de Jonathas? »'),
('2s',9,2,'crampon1923','Il y avait un serviteur de la maison de Saül, nommé Siba. On le fit venir auprès de David, et le roi lui dit: « Es-tu Siba? » Et il répondit: « Ton serviteur! »'),
('2s',9,3,'crampon1923','Le roi dit: « N''y a-t-il plus personne de la maison de Saül à qui je puisse faire du bien comme Dieu? » Et Siba répondit au roi: « Il y a encore un fils de Jonathas, qui est perclus des deux pieds. »'),
('2s',9,4,'crampon1923','Et le roi lui dit: « Où est-il? »; et Siba répondit au roi: « Voici qu''il est dans la maison de Machir, fils d''Ammiel, à Lodabar. »'),
('2s',9,5,'crampon1923','Le roi David l''envoya chercher de la maison de Machir, fils d''Ammiel de Lodabar.'),
('2s',9,6,'crampon1923','Arrivé auprès de David, Miphiboseth, fils de Jonathas, fils de Saül, tomba sur sa face et se prosterna. Et David dit: « Miphiboseth! » Il répondit: « Voici ton serviteur. »'),
('2s',9,7,'crampon1923','Et David lui dit: « Ne crains point, car je veux te faire du bien à cause de Jonathas, ton père. Je te rendrai toutes les terres de Saül, ton père, et toi tu prendras toujours ta nourriture à ma table. »'),
('2s',9,8,'crampon1923','Il se prosterna et dit: « Qu''est ton serviteur pour que tu te tournes vers un chien mort tel que moi? »'),
('2s',9,9,'crampon1923','Le roi appela Siba, serviteur de Saül, et lui dit: « Tout ce qui appartenait à Saül et à toute sa maison, je le donne au fils de ton maître.'),
('2s',9,10,'crampon1923','Tu cultiveras pour lui les terres, toi, tes fils et tes serviteurs, et tu apporteras la récolte, afin que le fils de ton maître ait de quoi se nourrir; mais Miphiboseth, le fils de ton maître, prendra toujours sa nourriture à ma table. » Or Siba avait quinze fils et vingt serviteurs.'),
('2s',9,11,'crampon1923','Siba dit au roi: « Ton serviteur fera tout ce que le roi, mon seigneur, ordonne à son serviteur. » Et Miphiboseth mangea à la table de David, comme l''un des fils du roi.'),
('2s',9,12,'crampon1923','Miphiboseth avait un jeune fils nommé Micha, et tous ceux qui demeuraient dans la maison de Siba étaient ses serviteurs.'),
('2s',9,13,'crampon1923','Miphiboseth habitait à Jérusalem, car il mangeait toujours à la table du roi; et il était boiteux des deux pieds.'),
('2s',10,1,'crampon1923','Après cela, le roi des fils d''Ammon mourut, et Hanon, son fils, régna à sa place.'),
('2s',10,2,'crampon1923','David dit: « Je montrerai de la bienveillance à Hanon, fils de Naas, comme son père m''a montré de la bienveillance. » Et David l''envoya consoler au sujet de son père, par l''intermédiaire de ses serviteurs. Lorsque les serviteurs de David furent arrivés dans le pays des fils d''Ammon,'),
('2s',10,3,'crampon1923','les princes des fils d''Ammon dirent à Hanon, leur maître: « Penses-tu que ce soit pour honorer ton père que David t''envoie des consolateurs? N''est-ce pas pour reconnaître et explorer la ville, afin de la détruire, que David a envoyé ses serviteurs vers toi? »'),
('2s',10,4,'crampon1923','Alors Hanon, ayant saisi les serviteurs de David, leur rasa la moitié de la barbe et coupa leurs habits à mi-hauteur, jusqu''aux fesses, et il les renvoya.'),
('2s',10,5,'crampon1923','On informa David, et il envoya des gens à leur rencontre, car ces hommes étaient dans une grande confusion; et le roi leur fit dire: « Restez à Jéricho jusqu''à ce que votre barbe ait repoussé, et vous reviendrez ensuite. »'),
('2s',10,6,'crampon1923','Les fils d''Ammon virent qu''ils s''étaient rendus odieux à David; et les fils d''Ammon envoyèrent prendre à leur solde les Syriens de Beth-Rohob et les Syriens de Soba, soit vingt mille hommes de pied, puis le roi de Maacha, soit mille hommes, et les gens de Tob, soit douze mille hommes.'),
('2s',10,7,'crampon1923','David l''apprit et il fit partir contre eux Joab et toute l''armée, les hommes vaillants.'),
('2s',10,8,'crampon1923','Les fils d''Ammon sortirent et se rangèrent en bataille à l''entrée de la porte; les Syriens de Soba et de Rohob, ainsi que les hommes de Tob et de Maacha, étaient à part dans la campagne.'),
('2s',10,9,'crampon1923','Lorsque Joab vit qu''il y avait un front de bataille devant et derrière lui, il choisit parmi toute l''élite d''Israël un corps qu''il rangea en face des Syriens;'),
('2s',10,10,'crampon1923','et il mit le reste du peuple sous le commandement de son frère Abisaï, qui les rangea en face des fils d''Ammon.'),
('2s',10,11,'crampon1923','Il dit: « Si les Syriens sont plus forts que moi, tu viendras à mon secours; et si les fils d''Ammon sont plus forts que toi, j''irai te secourir.'),
('2s',10,12,'crampon1923','Sois ferme et combattons vaillamment pour notre peuple et pour les villes de notre Dieu, et que Yahweh fasse ce qui semblera bon à ses yeux! »'),
('2s',10,13,'crampon1923','Joab s''avança donc, ainsi que le peuple qui était avec lui, pour attaquer les Syriens, et ceux-ci s''enfuirent devant lui.'),
('2s',10,14,'crampon1923','Les fils d''Ammon, voyant que les Syriens avaient pris la fuite, s''enfuirent aussi devant Abisaï, et rentrèrent dans la ville. Et Joab s''en retourna de la guerre contre les fils d''Ammon et rentra dans Jérusalem.'),
('2s',10,15,'crampon1923','Les Syriens, voyant qu''ils avaient été battus devant Israël, se réunirent ensemble.'),
('2s',10,16,'crampon1923','Hadadézer envoya des messagers pour faire venir les Syriens qui étaient de l''autre côté du fleuve, et ils vinrent à Hélam, et Sobach, chef de l''armée d''Hadadézer, marchait devant eux.'),
('2s',10,17,'crampon1923','David en reçut la nouvelle et, ayant assemblé tout Israël, il passa le Jourdain et vint à Hélam. Les Syriens se rangèrent en bataille contre David, et engagèrent le combat contre lui.'),
('2s',10,18,'crampon1923','Mais les Syriens s''enfuirent devant Israël, et David tua aux Syriens les chevaux de sept cents chars et quarante mille cavaliers; il frappa aussi le chef de leur armée, Sobach, qui mourut là.'),
('2s',10,19,'crampon1923','Tous les rois vassaux de Hadadézer, se voyant battus devant Israël, firent la paix avec Israël et lui furent assujettis; et les Syriens craignirent de porter encore secours aux fils d''Ammon.'),
('2s',11,1,'crampon1923','Au retour de l''année, au temps où les rois se mettent en campagne, David envoya Joab avec ses serviteurs et tout Israël, et ils ravagèrent le pays des fils d''Ammon et assiégèrent Rabba. Mais David resta à Jérusalem.'),
('2s',11,2,'crampon1923','Un soir que David s''était levé de sa couche et se promenait sur le toit de la maison du roi, il aperçut de dessus le toit une femme qui se baignait, et cette femme était très belle d''aspect.'),
('2s',11,3,'crampon1923','David fit rechercher qui était cette femme, et on lui dit: « C''est Bethsabée, fille d''Eliam, femme d''Urie le Héthéen. »'),
('2s',11,4,'crampon1923','Et David envoya des gens pour la prendre; elle vint chez lui et il coucha avec elle. Puis elle se purifia de sa souillure et retourna dans sa maison.'),
('2s',11,5,'crampon1923','Cette femme fut enceinte, et elle le fit annoncer à David, en disant: « Je suis enceinte. »'),
('2s',11,6,'crampon1923','Alors David expédia cet ordre à Joab: « Envoie-moi Urie, le Héthéen. » Et Joab envoya Urie à David.'),
('2s',11,7,'crampon1923','Urie s''étant rendu auprès de David, celui-ci demanda des nouvelles de Joab, de l''armée et du combat.'),
('2s',11,8,'crampon1923','Puis David dit à Urie: « Descend dans ta maison et lave tes pieds. » Urie sortit de la maison du roi, et on porta après lui un don de la table du roi;'),
('2s',11,9,'crampon1923','mais Urie se coucha devant la porte de la maison du roi avec tous les serviteurs de son maître, et il ne descendit pas dans sa maison.'),
('2s',11,10,'crampon1923','On en informa David, en disant: « Urie n''est pas descendu dans sa maison. » Et David dit à Urie: « N''arrives-tu pas de voyage? Pourquoi n''es-tu pas descendu dans ta maison? »'),
('2s',11,11,'crampon1923','Urie répondit à David: « L''arche, et Israël, et Juda habitent sous des tentes, mon seigneur Joab et les serviteurs de mon seigneur campent en rase campagne, et moi j''entrerai dans ma maison pour manger et boire, et pour coucher avec ma femme! Par ta vie et par la vie de ton âme, je n''en ferai rien. »'),
('2s',11,12,'crampon1923','David dit à Urie: « Reste ici encore aujourd''hui, et demain je te renverrai. » Et Urie resta donc à Jérusalem ce jour-là et le suivant.'),
('2s',11,13,'crampon1923','David l''invita à manger et à boire en sa présence, et il l''enivra; et le soir, Urie sortit pour s''étendre sur sa couche auprès des serviteurs de son maître, mais il ne descendit pas dans sa maison.'),
('2s',11,14,'crampon1923','Le lendemain matin, David écrivit une lettre à Joab et l''envoya par la main d''Urie.'),
('2s',11,15,'crampon1923','Il écrivait dans cette lettre: « Placez Urie au plus fort du combat, et retirez-vous de derrière lui, afin qu''il soit frappé et qu''il meure. »'),
('2s',11,16,'crampon1923','Joab, qui faisait le siège de la ville, plaça Urie à l''endroit où il savait que se trouvaient les hommes les plus vaillants.'),
('2s',11,17,'crampon1923','Les hommes de la ville, ayant fait une sortie pour attaquer Joab, plusieurs tombèrent d''entre le peuple, d''entre les serviteurs de David; Urie le Héthéen mourut aussi.'),
('2s',11,18,'crampon1923','Joab envoya un messager pour informer David de tous les faits du combat;'),
('2s',11,19,'crampon1923','il donna cet ordre au messager: « Quand tu auras achevé de raconter au roi tous les faits du combat, si la colère du roi se soulève et qu''il te dise:'),
('2s',11,20,'crampon1923','Pourquoi vous êtes-vous approchés de la ville pour livrer combat? Ne saviez-vous pas que les assiégés lanceraient des traits du haut de la muraille?'),
('2s',11,21,'crampon1923','Qui a frappé Abimélech, fils de Jérobaal? N''est-ce pas une femme qui a lancé sur lui du haut de la muraille un morceau de meule, ce dont il est mort à Thébès? Pourquoi donc vous êtes-vous approchés de la muraille? — Alors tu diras: Ton serviteur Urie le Héthéen est mort aussi. »'),
('2s',11,22,'crampon1923','Le messager partit et, à son arrivée, il raconta à David tout ce que Joab lui avait ordonné.'),
('2s',11,23,'crampon1923','Le messager dit à David: « Ces gens, plus forts que nous, ont fait une sortie contre nous dans la campagne, mais nous les avons repoussés jusqu''à la porte.'),
('2s',11,24,'crampon1923','Alors leurs archers ont tiré du haut de la muraille sur tes serviteurs, et plusieurs des serviteurs du roi sont morts tués, et ton serviteur Urie le Héthéen est mort aussi. »'),
('2s',11,25,'crampon1923','David dit au messager: « Voici ce que tu diras à Joab: Ne sois pas trop en peine de cette affaire, car l''épée dévore tantôt l''un, tantôt l''autre. Redouble de vigueur contre la ville et renverse-la. Et toi, encourage-le. »'),
('2s',11,26,'crampon1923','La femme d''Urie apprit que son mari, Urie, était mort, et elle pleura sur son mari.'),
('2s',11,27,'crampon1923','Quand le deuil fut passé, David l''envoya chercher et la recueillit dans sa maison. Elle devint sa femme et lui enfanta un fils. Et l''action que David avait faite déplut aux yeux de Yahweh.'),
('2s',12,1,'crampon1923','Yahweh envoya Nathan vers David; et Nathan vint à lui et lui dit: « Il y avait dans une ville deux hommes, l''un riche et l''autre pauvre.'),
('2s',12,2,'crampon1923','Le riche avait des brebis et des bœufs en très grand nombre,'),
('2s',12,3,'crampon1923','et le pauvre n''avait rien, si ce n''est une petite brebis qu''il avait achetée; il l''élevait et elle grandissait chez lui avec ses enfants, mangeant de son pain, buvant de sa coupe et dormant sur son sein, et elle était pour lui comme une fille.'),
('2s',12,4,'crampon1923','Une visite arriva chez l''homme riche; et le riche s''abstint de prendre de ses brebis ou de ses bœufs, pour préparer un repas au voyageur qui était venu chez lui; il prit la brebis du pauvre et l''apprêta pour l''homme qui était venu chez lui. »'),
('2s',12,5,'crampon1923','La colère de David s''enflamma violemment contre cet homme, et il à Nathan: « Aussi vrai que Yahweh est vivant! l''homme qui a fait cela mérite la mort;'),
('2s',12,6,'crampon1923','et il rendra quatre fois la brebis, pour avoir fait une pareille chose et pour avoir été sans pitié. »'),
('2s',12,7,'crampon1923','Et Nathan dit à David: « Tu es cet homme-là! Ainsi parle Yahweh, le Dieu d''Israël: Je t''ai oint pour roi sur Israël, et je t''ai délivré de la main de Saül;'),
('2s',12,8,'crampon1923','je t''ai donné la maison de ton maître, et j''ai mis sur ton sein les femmes de ton maître; et je t''ai donné la maison d''Israël et de Juda, et, si cela était trop peu, j''y aurais encore ajouté ceci ou cela.'),
('2s',12,9,'crampon1923','Pourquoi as-tu méprisé la parole de Yahweh, en faisant ce qui est mal à ses yeux? Tu as frappé par l''épée Urie le Héthéen; tu as pris sa femme pour en faire ta femme, et tu l''as tué par l''épée des fils d''Ammon.'),
('2s',12,10,'crampon1923','Et maintenant, l''épée ne s''éloignera jamais de ta maison, parce que tu m''as méprisé et que tu as pris la femme d''Urie le Héthéen, pour en faire ta femme.'),
('2s',12,11,'crampon1923','Ainsi parle Yahweh: Voici que je vais faire lever, de ta maison même, le malheur sur toi, et je prendrai sous tes yeux tes femmes pour les donner à ton voisin, et il couchera avec tes femmes à la vue de ce soleil.'),
('2s',12,12,'crampon1923','Car toi, tu as agi en secret; et moi, je ferai cela en présence de tout Israël et à la face du soleil. »'),
('2s',12,13,'crampon1923','David dit à Nathan: « J''ai péché contre Yahweh. » Et Nathan dit à David: « Yahweh a pardonné ton péché, tu ne mourras point.'),
('2s',12,14,'crampon1923','Mais, parce que tu as fait, par cette action, mépriser Yahweh par ses ennemis, le fils qui t''est né mourra. »'),
('2s',12,15,'crampon1923','Et Nathan s''en alla dans sa maison. Yahweh frappa l''enfant que la femme d''Urie avait enfanté à David, et il devint gravement malade.'),
('2s',12,16,'crampon1923','David pria Dieu pour l''enfant, et jeûna; et, étant entré dans sa chambre, il passa la nuit couché par terre.'),
('2s',12,17,'crampon1923','Les anciens de sa maison insistèrent auprès de lui pour le faire lever de terre; mais il ne voulut point et ne mangea pas avec eux.'),
('2s',12,18,'crampon1923','Le septième jour, l''enfant mourut. Les serviteurs de David craignaient de lui annoncer que l''enfant était mort, car ils disaient: « Lorsque l''enfant vivait encore, nous lui avons parlé, et il n''a pas écouté notre voix; comment lui dirons-nous: L''enfant est mort? Il fera pis encore. »'),
('2s',12,19,'crampon1923','David s''aperçut que ses serviteurs parlaient tout bas entre eux, et David comprit que l''enfant était mort. David dit à ses serviteurs: « L''enfant est donc mort? » Ils dirent: « Il est mort. »'),
('2s',12,20,'crampon1923','Alors David, s''étant levé de terre, se baigna, s''oignit et changea de vêtements; puis il alla dans la maison de Yahweh et se prosterna. Revenu chez lui, il demanda qu''on lui servît à manger, et il mangea.'),
('2s',12,21,'crampon1923','Ses serviteurs lui dirent: « Qu''est-ce que tu fais là? Lorsque l''enfant vivait, tu jeûnais et tu pleurais, et maintenant que l''enfant est mort, tu te lèves et tu manges du pain! »'),
('2s',12,22,'crampon1923','Il dit: « Quand l''enfant vivait encore, je jeûnais et je pleurais, car je disais: Qui sait? Yahweh aura peut-être pitié de moi, et l''enfant vivra?'),
('2s',12,23,'crampon1923','Maintenant qu''il est mort, pourquoi jeûnerais-je? Puis-je encore le faire revenir? J''irai vers lui; mais il ne reviendra pas vers moi. »'),
('2s',12,24,'crampon1923','David consola Bethsabée, sa femme; il s''approcha d''elle et coucha avec elle, et elle enfanta un fils, qu''il appela Salomon; et Yahweh l''aima,'),
('2s',12,25,'crampon1923','et il envoya dire par l''intermédiaire de Nathan, le prophète, qui lui donna le nom de Jedidiah, à cause de Yahweh.'),
('2s',12,26,'crampon1923','Joab, qui assiégeait Rabba des fils d''Ammon, s''empara de la ville royale;'),
('2s',12,27,'crampon1923','et Joab envoya des messagers à David pour lui dire: « J''ai assiégé Rabba et je me suis déjà emparé de la ville des eaux.'),
('2s',12,28,'crampon1923','Maintenant, rassemble le reste du peuple, viens camper contre la ville et prends-la, de peur que je ne prenne moi-même la ville, et qu''on ne l''appelle de mon nom. »'),
('2s',12,29,'crampon1923','David rassembla tout le peuple et, ayant marché sur Rabba, il l''attaqua, et s''en rendit maître.'),
('2s',12,30,'crampon1923','Il enleva la couronne de leur roi de dessus sa tête: son poids était d''un talent d''or; et il y avait sur elle une pierre précieuse, et elle fut mise sur la tête de David. Et il emporta de la ville un très grand butin.'),
('2s',12,31,'crampon1923','Quant au peuple qui s''y trouvait, il l''en fit sortir et le mit aux scies, aux pics de fer et aux haches de fer, et il les fit passer au moule à briques; il traita de même toutes les villes des fils d''Ammon. Puis David retourna à Jérusalem avec tout le peuple.'),
('2s',13,1,'crampon1923','Après cela, il arriva qu''Absalom, fils de David, ayant une sœur qui était belle et qui s''appelait Thamar, Amnon, fils de David, l''aima.'),
('2s',13,2,'crampon1923','Amnon se tourmentait, jusqu''à se rendre malade, au sujet de Thamar, sa sœur; car elle était vierge, et il semblait impossible à Amnon de lui rien faire.'),
('2s',13,3,'crampon1923','Amnon avait un ami, nommé Jonadab, fils de Sammaa, frère de David, et Jonadab était un homme fort avisé.'),
('2s',13,4,'crampon1923','Il lui dit: « Pourquoi es-tu ainsi défait, fils du roi, chaque matin? Ne me l''indiqueras-tu pas? » Amnon lui répondit: « J''aime Thamar, sœur de mon frère Absalom. »'),
('2s',13,5,'crampon1923','Jonadab lui dit: « Mets-toi au lit et fais le malade. Quand ton père viendra te voir, tu lui diras: Permets, je te prie, que Thamar, ma sœur, vienne me donner à manger, et qu''elle prépare le mets sous mes yeux, afin que je le voie, et je mangerai de sa main. »'),
('2s',13,6,'crampon1923','Amnon se coucha et fit le malade. Le roi vint le voir, et Amnon dit au roi: « Je te prie, que Thamar, ma sœur, vienne faire deux gâteaux sous mes yeux, et que je les mange de sa main. »'),
('2s',13,7,'crampon1923','David envoya dire à Thamar dans la maison: « Va à la maison de ton frère Amnon et prépare-lui un mets. »'),
('2s',13,8,'crampon1923','Thamar alla chez son frère Amnon, qui était couché. Prenant de la pâte, elle la pétrit, la mit en gâteaux sous ses yeux et fit cuire les gâteaux;'),
('2s',13,9,'crampon1923','elle prit ensuite la poêle et les versa devant lui. Mais il refusa de manger. Amnon dit alors: « Faites sortir d''auprès de moi tout le monde. » Lorsque tous furent sortis d''auprès de lui,'),
('2s',13,10,'crampon1923','Amnon dit à Thamar: « Apporte le mets dans l''alcôve, et que je le mange de ta main. » Thamar prit les gâteaux qu''elle avait faits, et les apporta à son frère Amnon dans l''alcôve.'),
('2s',13,11,'crampon1923','Comme elle les lui présentait à manger, il la saisit et lui dit: « Viens, couche avec moi, ma sœur. »'),
('2s',13,12,'crampon1923','Elle lui répondit: « Non, mon frère, ne me déshonore pas, car on n''agit point ainsi en Israël; ne commets pas cette infamie.'),
('2s',13,13,'crampon1923','Moi, où irais-je porter ma honte? Et toi, tu serais comme l''un des infâmes en Israël. Parles-en au roi, je te prie, et il ne refusera pas de me donner à toi. »'),
('2s',13,14,'crampon1923','Mais il ne voulut pas écouter sa voix; plus fort qu''elle, il la violenta et coucha avec elle.'),
('2s',13,15,'crampon1923','Aussitôt Amnon eut pour elle une très forte aversion, et la haine dont il la haït fut plus forte que l''amour dont il l''avait aimée; et Amnon lui dit: « Lève-toi, va-t-en! »'),
('2s',13,16,'crampon1923','Elle lui répondit: « Au mal que tu m''as fait, n''ajoute pas le mal plus grand encore de me chasser. » Mais, sans vouloir l''écouter,'),
('2s',13,17,'crampon1923','il appela le garçon qui le servait et dit: « Jetez cette femme dehors, loin de moi; et ferme la porte derrière elle. »'),
('2s',13,18,'crampon1923','Or elle avait une robe longue, car c''était le vêtement que portaient les filles du roi encore vierges. Le serviteur d''Amnon la mit dehors et ferma la porte derrière elle.'),
('2s',13,19,'crampon1923','Thamar prit de la poussière et la mit sur sa tête; elle déchira la longue robe qu''elle portait et, mettant la main sur sa tête, elle s''en alla en poussant des cris.'),
('2s',13,20,'crampon1923','Absalom, son frère, lui dit: « Ton frère Amnon a-t-il été avec toi? Maintenant, ma sœur, tais-toi, c''est ton frère; ne prends pas cette affaire à cœur. » Et Thamar demeura, désolée, dans la maison de son frère Absalom.'),
('2s',13,21,'crampon1923','Lorsque le roi David apprit toutes ces choses, il fut très irrité. (* La Vulgate ajoute: Mais il ne voulut pas contrister l''esprit d''Amnon, son fils, car il l''aimait comme étant son premier né. *) —'),
('2s',13,22,'crampon1923','Absalom n''adressait plus aucune parole, bonne ou mauvaise, à Amnon, car Absalom haïssait Amnon, à cause de l''outrage fait à Thamar, sa sœur.'),
('2s',13,23,'crampon1923','Deux ans après, Absalom avait les tondeurs à Baal-Hasor, près d''Ephraïm, et Absalom invita tous les fils du roi.'),
('2s',13,24,'crampon1923','Absalom alla trouver le roi et dit: « Voici que ton serviteur a les tondeurs; que le roi et ses domestiques viennent chez ton serviteur. »'),
('2s',13,25,'crampon1923','Et le roi dit à Absalom: « Non, mon fils, nous n''irons pas tous, de peur que nous ne te soyons à charge. » Absalom fit des instances, mais le roi ne voulut pas y aller, et il le bénit.'),
('2s',13,26,'crampon1923','Alors Absalom dit: « Si tu ne viens pas, permets du moins à Amnon, mon frère, de venir avec nous. » Le roi répondit: « Pourquoi irait-il avec toi? »'),
('2s',13,27,'crampon1923','Absalom ayant insisté, le roi laissa aller avec lui Amnon et tous les fils du roi.'),
('2s',13,28,'crampon1923','Absalom donna cet ordre à ses serviteurs: « Faites attention! Quand le cœur d''Amnon sera gavé par le vin et que je vous dirai: Frappez Amnon! vous le tuerez. Ne craignez pas; n''est-ce pas moi qui vous l''ai commandé? Soyez fermes et montrez du courage! »'),
('2s',13,29,'crampon1923','Les serviteurs d''Absalom firent à Amnon comme Absalom l''avait ordonné. Et tous les fils du roi se levant, montèrent chacun sur sa mule et s''enfuirent.'),
('2s',13,30,'crampon1923','Comme ils étaient encore en chemin, ce bruit arriva à David: « Absalom a tué tous les fils du roi, et il n''en est pas resté un seul. »'),
('2s',13,31,'crampon1923','Le roi se leva, déchira ses vêtements et se coucha par terre, et tous ses serviteurs se tenaient là, les vêtements déchirés.'),
('2s',13,32,'crampon1923','Jonadab, fils de Semmaa, frère de David, prit la parole et dit: « Que mon seigneur ne dise point qu''on a tué tous les jeunes gens, fils du roi; Amnon seul est mort. C''est une chose qui était sur les lèvres d''Absalom depuis le jour où Amnon a déshonoré Thamar, sa sœur.'),
('2s',13,33,'crampon1923','Et maintenant, que le roi mon seigneur ne s''imagine pas que tous les fils du roi sont morts; car Amnon seul est mort. »'),
('2s',13,34,'crampon1923','Et Absalom prit la fuite. Or le jeune homme placé en sentinelle leva les yeux et regarda, et voici qu''une grande troupe venait par la route occidentale, du côté de la montagne.'),
('2s',13,35,'crampon1923','Jonadab dit au roi: « Voici les fils du roi qui arrivent; les choses se sont passées comme le disait ton serviteur. »'),
('2s',13,36,'crampon1923','Comme il achevait de parler, les fils du roi arrivèrent et, élevant la voix, ils pleurèrent; le roi aussi et tous ses serviteurs versèrent des larmes abondantes.'),
('2s',13,37,'crampon1923','Mais Absalom s''enfuit et s''en alla chez Tholomaï, fils d''Ammiud, roi de Gessur. Et David faisait le deuil de son fils tous les jours.'),
('2s',13,38,'crampon1923','Absalom s''enfuit et s''en alla à Gessur, et il y fut trois ans.'),
('2s',13,39,'crampon1923','Et le roi David renonça à poursuivre Absalom, car il s''était consolé de la mort d''Amnon.'),
('2s',14,1,'crampon1923','Joab, fils de Sarvia, s''aperçut que le cœur du roi se tournait vers Absalom.'),
('2s',14,2,'crampon1923','Joab envoya chercher à Thécua une femme habile, et il lui dit: « Feins d''être dans le deuil et revêts des habits de deuil; ne t''oins pas d''huile et sois comme une femme qui depuis longtemps est dans le deuil pour un mort.'),
('2s',14,3,'crampon1923','Tu viendras chez le roi et tu lui tiendras ce discours... » Et Joab lui mit dans la bouche ce qu''elle devait dire.'),
('2s',14,4,'crampon1923','La femme de Thécua vint parler au roi. Tombant la face contre terre et se prosternant, elle dit: « O roi, sauve-moi! »'),
('2s',14,5,'crampon1923','Le roi lui dit: « Qu''as-tu? » Elle répondit: « Je suis une veuve, mon mari est mort.'),
('2s',14,6,'crampon1923','Or ta servante avait deux fils; et ils se sont tous deux querellés dans les champs; comme il n''y avait personne pour les séparer, l''un a frappé l''autre et l''a tué.'),
('2s',14,7,'crampon1923','Et voici que toute la famille s''est levée contre ta servante, en disant: Livre le meurtrier de son frère; nous le ferons mourir pour la vie de son frère qu''il a tué, et nous détruirons même l''héritier! Ils éteindront ainsi le charbon qui me reste, pour ne laisser à mon mari ni un nom ni un survivant sur la face de la terre. »'),
('2s',14,8,'crampon1923','Le roi dit à la femme: « Va à ta maison; je donnerai des ordres à ton sujet. »'),
('2s',14,9,'crampon1923','La femme de Thécua dit au roi: « Que ce soit sur moi, ô roi mon Seigneur, et sur la maison de mon père que la faute retombe; que le roi et son trône n''aient pas à en souffrir! »'),
('2s',14,10,'crampon1923','Le roi dit: « Si quelqu''un t''inquiète encore, amène-le-moi, et il ne lui arrivera plus de te toucher. »'),
('2s',14,11,'crampon1923','Elle dit: « Que le roi fasse mention de Yahweh, ton Dieu, afin que le vengeur du sang n''augmente pas le dommage, et qu''on ne détruise pas mon fils! » Il répondit: « Aussi vrai que Yahweh est vivant! Il ne tombera pas à terre un cheveu de ton fils. »'),
('2s',14,12,'crampon1923','La femme dit: « Permets à ta servante, je te prie, de dire un mot à mon seigneur le roi! » Il répondit: « Parle! »'),
('2s',14,13,'crampon1923','Et la femme dit: « Pourquoi as-tu pensé ainsi à l''égard du peuple de Dieu — le roi, en prononçant ce jugement, se déclare coupable, — à savoir que le roi ne rappelle pas celui qu''il a banni.'),
('2s',14,14,'crampon1923','Car nous mourrons certainement; nous sommes comme les eaux répandues à terre et qui ne se rassemblent plus; Dieu n''ôte pas la vie, et il forme le dessein que le banni ne reste pas banni de sa présence.'),
('2s',14,15,'crampon1923','Maintenant, si je suis venue dire ces choses au roi mon seigneur, c''est que le peuple m''a effrayée; et ta servante a dit: Je veux parler au roi; peut-être le roi fera-t-il ce que dira ta servante.'),
('2s',14,16,'crampon1923','Oui, le roi écoutera, pour délivrer sa servante de la main de l''homme qui veut nous retrancher, mon fils et moi, de l''héritage de Dieu.'),
('2s',14,17,'crampon1923','Ta servant a dit: Que la parole de mon seigneur le roi me donne le repos! Car mon seigneur le roi est comme un ange de Dieu, pour écouter le bien et le mal. Et que Yahweh, ton Dieu, soit avec toi! »'),
('2s',14,18,'crampon1923','Le roi répondit et dit à la femme: « Ne me cache rien de ce que je vais te demander. » La femme dit: « Que mon seigneur le roi parle! »'),
('2s',14,19,'crampon1923','Et le roi dit: « La main de Joab est-elle avec toi dans tout cela? » La femme répondit: « Aussi vrai que ton âme est vivante, ô mon seigneur le roi, il est impossible d''aller à droite ou à gauche de tout ce que dit mon seigneur le roi. Oui, c''est ton serviteur Joab qui m''a donné des ordres et qui a mis toutes ces paroles dans la bouche de ta servante.'),
('2s',14,20,'crampon1923','C''est pour détourner l''aspect de la chose que ton serviteur Joab a fait cela; mais mon seigneur est aussi sage qu''un ange de Dieu, pour connaître tout ce qui se passe sur la terre. »'),
('2s',14,21,'crampon1923','Le roi dit à Joab: « Voici, je vais faire cela; va donc, ramène le jeune homme Absalom. »'),
('2s',14,22,'crampon1923','Joab tomba la face contre terre et se prosterna, et il bénit le roi; puis Joab dit: « Ton serviteur connaît aujourd''hui que j''ai trouvé grâce à tes yeux, ô roi, mon seigneur, puisque le roi agit selon la parole de son serviteur. »'),
('2s',14,23,'crampon1923','Et Joab, s''étant levé, alla à Gessur, et il ramena Absalom à Jérusalem.'),
('2s',14,24,'crampon1923','Mais le roi dit: « Qu''il se retire dans sa maison, et qu''il ne voie point ma face. » Et Absalom se retira dans sa maison, et il ne vit point la face du roi.'),
('2s',14,25,'crampon1923','Dans tout Israël il n''y avait pas un homme aussi renommé qu''Absalom pour sa beauté; de la plante du pied au sommet de la tête, il n''y avait en lui aucun défaut.'),
('2s',14,26,'crampon1923','Lorsqu''il se rasait la tête, — c''était chaque année qu''il le faisait; lorsque sa chevelure lui pesait, il la rasait — le poids des cheveux de sa tête était de deux cents sicles, poids du roi.'),
('2s',14,27,'crampon1923','Il naquit à Absalom trois fils et une fille nommée Thamar; c''était une femme de belle figure.'),
('2s',14,28,'crampon1923','Absalom demeura deux ans à Jérusalem sans voir la face du roi.'),
('2s',14,29,'crampon1923','Absalom fit demander Joab pour l''envoyer vers le roi; mais Joab ne voulut pas venir vers lui. Absalom le fit demander une seconde fois, et il ne voulut pas venir.'),
('2s',14,30,'crampon1923','Absalom dit alors à ses serviteurs: « Voyez, le champ de Joab est à côté du mien; il s''y trouve de l''orge pour lui: allez-y mettre le feu. » Et les serviteurs d''Absalom mirent le feu au champ.'),
('2s',14,31,'crampon1923','Joab se leva et, étant venu vers Absalom dans sa maison, il lui dit: « Pourquoi tes serviteurs ont-ils mis le feu au champ qui m''appartient? »'),
('2s',14,32,'crampon1923','Absalom répondit à Joab: « Voilà que je t''avais envoyé dire: Viens ici et je t''enverrai vers le roi afin que tu lui dises: Pourquoi suis-je revenu de Gessur? Il vaudrait mieux pour moi que j''y fusse encore. Maintenant, je veux voir la face du roi; et, s''il y a quelque iniquité en moi, qu''il me fasse mourir! »'),
('2s',14,33,'crampon1923','Joab alla trouver le roi et lui rapporta ces choses. Et il appela Absalom, et celui-ci vint auprès du roi et se prosterna la face contre terre devant le roi. Et le roi baisa Absalom.'),
('2s',15,1,'crampon1923','Après cela, Absalom se procura un char et des chevaux, et cinquante hommes qui couraient devant lui.'),
('2s',15,2,'crampon1923','Absalom se levait de bonne heure, et se tenait près de l''avenue de la porte; et chaque fois qu''un homme ayant un procès se rendait vers le roi pour obtenir un jugement, Absalom l''appelait et disait: « De quelle ville es-tu? » Lorsqu''il avait répondu: « Ton serviteur est de telle tribu d''Israël, »'),
('2s',15,3,'crampon1923','Absalom lui disait: « Vois, ta cause est bonne et juste; mais personne ne t''écoutera de la part du roi. »'),
('2s',15,4,'crampon1923','Absalom ajoutait: « Qui m''établira juge dans le pays! Quiconque aurait un procès ou une affaire viendrait à moi, et je lui rendrais justice. »'),
('2s',15,5,'crampon1923','Et lorsque quelqu''un s''approchait pour se prosterner devant lui, il lui tendait la main, le prenait et le baisait.'),
('2s',15,6,'crampon1923','Absalom agissait ainsi envers tous ceux d''Israël qui se rendaient vers le roi pour demander justice; et il séduisait les cœurs des gens d''Israël.'),
('2s',15,7,'crampon1923','Au bout de quatre ans, Absalom dit au roi: « Permets, je te prie, que j''aille à Hébron pour m''acquitter du vœu que j''ai fait à Yahweh.'),
('2s',15,8,'crampon1923','Car pendant que je demeurais à Gessur en Aram, ton serviteur a fait un vœu, en disant: “Si Yahweh me ramène à Jérusalem, je servirai Yahweh.” »'),
('2s',15,9,'crampon1923','Le roi lui dit: « Va en paix! » Il se leva et partit pour Hébron.'),
('2s',15,10,'crampon1923','Absalom envoya des émissaires dans toutes les tribus d''Israël, pour dire: « Dès que vous entendrez le son de la trompette, vous direz: Absalom règne à Hébron! »'),
('2s',15,11,'crampon1923','Avec Absalom partirent deux cents hommes de Jérusalem: c''étaient des invités qui allaient en toute simplicité, sans se douter de rien.'),
('2s',15,12,'crampon1923','Pendant qu''Absalom offrait les sacrifices, il envoya chercher à sa ville de Gilo Achitophel le Gilonite, conseiller de David. La conjuration devint puissante, car le peuple était de plus en plus nombreux autour d''Absalom.'),
('2s',15,13,'crampon1923','On vint en informer David, en disant: « Le cœur des hommes d''Israël s''est mis à la suite d''Absalom. »'),
('2s',15,14,'crampon1923','Et David dit à tous ses serviteurs qui étaient avec lui à Jérusalem: « Levez-vous, fuyons, car il n''y a pas moyen pour nous d''échapper devant Absalom. Hâtez-vous de partir, de peur que, se hâtant, il ne nous surprenne, qu''il ne fasse tomber sur nous le malheur et qu''il ne frappe la ville du tranchant de l''épée. »'),
('2s',15,15,'crampon1923','Les serviteurs du roi lui dirent: « Quelque parti que prenne mon seigneur le roi, voici tes serviteurs. »'),
('2s',15,16,'crampon1923','Le roi partit, avec toute sa famille, à pied, et il laissa dix concubines pour garder la maison.'),
('2s',15,17,'crampon1923','Le roi sortit avec tout le peuple à pied, et ils s''arrêtèrent à la dernière maison.'),
('2s',15,18,'crampon1923','Tous ses serviteurs marchaient à ses côtés, tous les Céréthiens et tous les Phéléthiens; et tous les Géthéens, au nombre de six cents hommes, qui étaient venus de Geth sur ses pas, marchaient devant le roi.'),
('2s',15,19,'crampon1923','Le roi dit à Ethaï le Géthéen: « Pourquoi viendrais-tu, toi aussi, avec nous? Retourne et reste avec le roi, car tu es un étranger et même tu es un exilé sans domicile.'),
('2s',15,20,'crampon1923','Tu es arrivé d''hier, et aujourd''hui je te ferais errer avec nous, alors que moi-même je m''en vais je ne sais où! Retourne et emmène tes frères avec toi; sur toi soient la grâce et la fidélité de Yahweh! »'),
('2s',15,21,'crampon1923','Ethaï répondit au roi et dit: « Yahweh est vivant et mon seigneur le roi est vivant! A l''endroit où sera mon seigneur le roi, soit pour mourir soit pour vivre, là sera ton serviteur. »'),
('2s',15,22,'crampon1923','David dit à Ethaï: « Va, passe! » Et Ethaï le Géthéen passa avec tous ses hommes et tous les enfants qui étaient avec lui.'),
('2s',15,23,'crampon1923','Toute la contrée pleurait et poussait des cris au passage de tout ce peuple. Le roi ayant passé le torrent de Cédron, tout le peuple passa vis-à-vis du chemin du désert.'),
('2s',15,24,'crampon1923','Et voici que Sadoc, et avec lui tous les lévites qui portaient l''arche de l''alliance de Dieu, déposèrent l''arche de Dieu, tandis qu''Abiathar montait, jusqu''à ce que tout le peuple eut achevé de sortir de la ville.'),
('2s',15,25,'crampon1923','Alors le roi dit à Sadoc: « Reporte l''arche de Dieu dans la ville. Si je trouve grâce aux yeux de Yahweh, il me ramènera et me fera voir l''arche et sa demeure.'),
('2s',15,26,'crampon1923','Mais s''il dit: Je n''ai pas de plaisir en toi, — me voici: qu''il me traite comme il lui semblera bon. »'),
('2s',15,27,'crampon1923','Le roi dit encore au prêtre Sadoc: « O toi, voyant, retourne en paix dans la ville, avec Achimaas, ton fils, et Jonathas, fils d''Abiathar: vos deux fils avec vous.'),
('2s',15,28,'crampon1923','Voyez! Moi j''attendrai dans les plaines du désert, jusqu''à ce qu''il m''arrive un mot de vous qui me renseigne. »'),
('2s',15,29,'crampon1923','Sadoc et Abiathar reportèrent donc l''arche de Dieu à Jérusalem, et ils y restèrent.'),
('2s',15,30,'crampon1923','David gravissait la colline des Oliviers; il montait en pleurant, la tête voilée, et il marchait nu-pieds; et tout le peuple qui était avec lui avait aussi la tête couverte, et ils montaient en pleurant.'),
('2s',15,31,'crampon1923','On apporta à David cette nouvelle: « Achitophel est avec Absalom parmi les conjurés. » Et David dit: « Yahweh réduisez à néant, je vous prie, les conseils d''Achitophel. »'),
('2s',15,32,'crampon1923','Lorsque David fut arrivé au sommet, là où l''on adore Dieu, voici que Chusaï l''Arachite vint au-devant de lui, la tunique déchirée et de la terre sur la tête.'),
('2s',15,33,'crampon1923','David lui dit: « Si tu passes avec moi, tu me seras à charge.'),
('2s',15,34,'crampon1923','Mais si, retournant dans la ville, tu dis à Absalom: O roi, je veux être ton serviteur; j''ai été le serviteur de ton père autrefois, je serai maintenant le tien, — tu déjoueras en ma faveur le conseil d''Achitophel.'),
('2s',15,35,'crampon1923','Tu auras là avec toi les prêtres Sadoc et Abiathar, et tout ce que tu apprendras de la maison du roi, tu le feras savoir aux prêtres Sadoc et Abiathar.'),
('2s',15,36,'crampon1923','Et comme ils ont auprès d''eux leurs deux fils, Achimaas, fils de Sadoc, et Jonathas, fils d''Abiathar, vous m''informerez par eux de tout ce que vous aurez appris. »'),
('2s',15,37,'crampon1923','Et Chusaï, ami de David, retourna à la ville, au même temps qu''Absalom faisait son entrée à Jérusalem.'),
('2s',16,1,'crampon1923','Lorsque David eut un peu dépassé le sommet, voici que Siba, serviteur de Miphiboseth, vint au-devant de lui, avec une paire d''ânes bâtés, portant deux cents pains, cent masses de raisins secs, cent fruits mûrs et une outre de vin.'),
('2s',16,2,'crampon1923','Le roi dit à Siba: « Que veux-tu faire de cela? » Siba répondit: « Les ânes sont pour la maison du roi, pour les monter, le pain et les fruits sont pour que les jeunes gens mangent, et le vin pour que boivent ceux qui seront fatigués dans le désert. »'),
('2s',16,3,'crampon1923','Le roi dit: « Et où est le fils de ton maître? » Siba répondit au roi: « Voici qu''il est resté à Jérusalem, car il a dit: Aujourd''hui la maison d''Israël me rendra le royaume de mon père. »'),
('2s',16,4,'crampon1923','Le roi dit à Siba: « Voici que tout ce qui appartient à Miphiboseth est à toi. » Et Siba dit: « Je me mets à tes pieds; que je trouve grâce devant toi, ô mon seigneur le roi! »'),
('2s',16,5,'crampon1923','Lorsque le roi fut arrivé à Bahurim, voici que sortit de là un homme de la même famille que la maison de Saül; il se nommait Séméï, fils de Géra; il s''avançait en maudissant,'),
('2s',16,6,'crampon1923','et il jetait des pierres à David et à tous les serviteurs du roi David, tandis que tout le peuple et tous les hommes vaillants étaient à sa droite et à sa gauche.'),
('2s',16,7,'crampon1923','Séméï parlait ainsi en le maudissant: « Va-t''en, va-t''en, homme de sang, homme de Bélial!'),
('2s',16,8,'crampon1923','Yahweh a fait retomber sur toi tout le sang de la maison de Saül, à la place duquel tu t''es fait roi, et il a livré le royaume entre les mains d''Absalom, ton fils; et te voilà dans ton malheur, car tu es un homme de sang! »'),
('2s',16,9,'crampon1923','Alors Abisaï, fils de Sarvia, dit au roi: « Pourquoi ce chien mort maudit-il le roi, mon seigneur? Laisse-moi donc passer que je lui coupe la tête. »'),
('2s',16,10,'crampon1923','Le roi répondit: « Qu''ai-je à faire avec vous, fils de Sarvia? Qu''il maudisse! Car si Yahweh lui a dit: Maudis David, qui lui dira: Pourquoi agis-tu ainsi? »'),
('2s',16,11,'crampon1923','Et David dit à Abisaï et à tous ses serviteurs: « Voici que mon fils, qui est sorti de mes entrailles, en veut à ma vie; à plus forte raison ce fils de Benjamin! Laissez-le maudire, car Yahweh le lui a ordonné.'),
('2s',16,12,'crampon1923','Peut-être Yahweh regardera-t-il mon affliction, et Yahweh me fera-t-il du bien en retour de la malédiction d''aujourd''hui. »'),
('2s',16,13,'crampon1923','Et David et ses gens continuaient leur chemin, tandis que Séméï marchait sur le flanc de la montagne, près de David, ne cessant de le maudire, lui jetant des pierres et faisant voler de la poussière.'),
('2s',16,14,'crampon1923','Le roi et tout le peuple qui était avec lui arrivèrent fatigués à..., et là ils prirent du repos.'),
('2s',16,15,'crampon1923','Absalom et tout le peuple, les hommes d''Israël, entrèrent à Jérusalem, et Achitophel était avec Absalom.'),
('2s',16,16,'crampon1923','Lorsque Chusaï l''Arachite, ami de David, vint vers Absalom, Chusaï dit à Absalom: « Vive le roi! Vive le roi! »'),
('2s',16,17,'crampon1923','Absalom dit à Chusaï: « Voilà donc ton attachement pour ton ami! Pourquoi n''es-tu pas allé avec ton ami? »'),
('2s',16,18,'crampon1923','Chusaï répondit à Absalom: « Non, mais c''est à celui qu''ont choisi Yahweh, et tout ce peuple, et tous les hommes d''Israël, que je veux appartenir, c''est avec lui que je veux rester.'),
('2s',16,19,'crampon1923','D''ailleurs, quel est celui que je servirai? N''est-ce pas son fils? Comme j''ai été le serviteur de ton père, ainsi je serai le tien! »'),
('2s',16,20,'crampon1923','Absalom dit à Achitophel: « Tenez conseil entre vous, pour savoir ce que nous avons à faire. »'),
('2s',16,21,'crampon1923','Et Achitophel dit à Absalom: « Va vers les concubines que ton père a laissées pour garder la maison; tout Israël saura ainsi que tu t''es rendu odieux à ton père, et les mains de tous ceux qui sont avec toi seront fortifiées. »'),
('2s',16,22,'crampon1923','On dressa donc pour Absalom une tente sur le toit, et Absalom vint vers les concubines de son père, aux yeux de tout Israël.'),
('2s',16,23,'crampon1923','Le conseil que donnait en ce temps-là Achitophel était comme la parole de Dieu à celui qui la demande; il en était ainsi de tous ses conseils, soit pour David, soit pour Absalom.'),
('2s',17,1,'crampon1923','Achitophel dit à Absalom: « Laisse-moi choisir douze mille hommes; je me lèverai et je poursuivrai David cette nuit même et,'),
('2s',17,2,'crampon1923','tombant sur lui à l''improviste pendant qu''il est fatigué et que ses mains sont affaiblies, je l''épouvanterai, et tout le peuple qui est avec lui s''enfuira; je frapperai alors le roi seul,'),
('2s',17,3,'crampon1923','et je ramènerai à toi tout le peuple: l''homme à qui tu en veux vaut le retour de tous; et tout le peuple sera en paix. »'),
('2s',17,4,'crampon1923','Ce discours plut à Absalom et à tous les anciens d''Israël.'),
('2s',17,5,'crampon1923','Cependant Absalom dit: « Appelez encore Chusaï l''Arachite et que nous entendions ce que lui aussi a dans la bouche. »'),
('2s',17,6,'crampon1923','Chusaï vint auprès d''Absalom, et Absalom lui dit: « Voici comment a parlé Achitophel; devons-nous faire ce qu''il a dit? Sinon, parle à ton tour. »'),
('2s',17,7,'crampon1923','Chusaï répondit à Absalom: « Pour cette fois, le conseil qu''a donné Achitophel n''est pas bon. »'),
('2s',17,8,'crampon1923','Et Chusaï ajouta: « Tu sais que ton père et ses gens sont des braves; ils sont exaspérés comme le serait dans la campagne une ourse privée de ses petits. Ton père est un homme de guerre, et il ne passe pas la nuit avec le peuple.'),
('2s',17,9,'crampon1923','Voici que maintenant il est caché dans quelque ravin ou dans quelque autre lieu. Et si, dès le commencement, il tombe quelques-uns des vôtres, on l''apprendra et l''on dira: Il y a eu une déroute dans le peuple qui suit Absalom.'),
('2s',17,10,'crampon1923','Alors, même le plus vaillant, son cœur fût-il comme un cœur de lion, sera découragé; car tout Israël sait que ton père est un héros, et que ceux qui l''accompagnent sont des braves.'),
('2s',17,11,'crampon1923','Je conseille donc que tout Israël se rassemble auprès de toi, depuis Dan jusqu''à Bersabée, multitude pareille au sable qui est sur le bord de la mer; et tu marcheras en personne au combat.'),
('2s',17,12,'crampon1923','Nous l''atteindrons en quelque lieu qu''il se trouve, et nous tomberons sur lui comme la rosée tombe sur le sol, et nous ne laisserons échapper ni lui, ni aucun de tous les hommes qui sont avec lui.'),
('2s',17,13,'crampon1923','S''il se retire dans une ville, tout Israël apportera des cordes vers cette ville, et nous la traînerons jusqu''au torrent, jusqu''à ce qu''on n''y trouve plus même une pierre. »'),
('2s',17,14,'crampon1923','Absalom et tous les gens d''Israël dirent: « Le conseil de Chusaï l''Arachite vaut mieux que le conseil d''Achitophel. » Yahweh avait décidé de rendre vain le bon conseil d''Achitophel, afin que Yahweh amenât le malheur sur Absalom.'),
('2s',17,15,'crampon1923','Chusaï dit aux prêtres Sadoc et Abiathar: « Achitophel a donné tel et tel conseil à Absalom et aux anciens d''Israël, et moi j''ai donné tel et tel conseil.'),
('2s',17,16,'crampon1923','Envoyez donc de suite informer David, et faites-lui dire: Ne passe pas la nuit dans les plaines du désert, mais hâte-toi de traverser, de peur qu''il n''y ait un suprême désastre pour le roi et pour tout le peuple qui est avec lui. »'),
('2s',17,17,'crampon1923','Jonathas et Achimaas se tenaient à En-Rogel; la servante allait les informer, et eux-mêmes allaient donner avis au roi David; car ils ne pouvaient se faire voir en entrant dans la ville.'),
('2s',17,18,'crampon1923','Un jeune homme les ayant aperçus, il le rapporta à Absalom. Mais ils se hâtèrent tous deux de partir, et ils arrivèrent à Bahurim, dans la maison d''un homme qui avait une citerne dans sa cour, et ils y descendirent.'),
('2s',17,19,'crampon1923','La femme prit une couverture, qu''elle étendit au dessus de la citerne, et elle y répandit du grain pilé, en sorte qu''on ne remarquait rien.'),
('2s',17,20,'crampon1923','Les serviteurs d''Absalom entrèrent chez la femme dans la maison, et dirent: « Où sont Achimaas et Jonathas? » La femme leur répondit: « Ils ont passé le ruisseau. » Ils cherchèrent et, ne les trouvant pas, ils retournèrent à Jérusalem.'),
('2s',17,21,'crampon1923','Après leur départ, Achimaas et Jonathas remontèrent de la citerne, et allèrent informer le roi David. Ils dirent à David: « Levez-vous et hâtez-vous de passer l''eau, car Achitophel a donné tel conseil contre vous. »'),
('2s',17,22,'crampon1923','David et tout le peuple qui était avec lui, s''étant levés, passèrent le Jourdain; au point du jour, il n''en restait pas un seul qui n''eût passé le Jourdain.'),
('2s',17,23,'crampon1923','Quand Achitophel vit que son conseil n''était pas suivi, il sella son âne, et se leva pour s''en aller chez lui dans sa ville; puis, après avoir donné ses ordres à sa maison, il s''étrangla, et mourut; et on l''enterra dans le tombeau de son père.'),
('2s',17,24,'crampon1923','David arriva à Mahanaïm; et Absalom passa le Jourdain, lui et tous les hommes d''Israël avec lui.'),
('2s',17,25,'crampon1923','Absalom avait mis à la tête de l''armée Amasa, à la place de Joab; Amasa était fils d''un homme appelé Jéthra, l''Ismaélite, qui était allé vers Abigaïl, fille de Naas, sœur de Sarvia, la mère de Joab.'),
('2s',17,26,'crampon1923','Ainsi Israël et Absalom campaient dans le pays de Galaad.'),
('2s',17,27,'crampon1923','Lorsque David fut arrivé à Mahanaïm, Sobi, fils de Naas, de Rabba des fils d''Ammon, Machir, fils d''Ammiel de Lodabar, et Berzellaï, le Galaadite, de Rogelim,'),
('2s',17,28,'crampon1923','vinrent lui offrir des lits, des plats, des vases de terre, du froment, de l''orge, de la farine, du grain rôti, des fèves, des lentilles, du grain rôti,'),
('2s',17,29,'crampon1923','du miel, du beurre, des brebis et des fromages de vache: ils apportèrent ces choses en nourriture à David et au peuple qui était avec lui, car ils disaient: « Ce peuple a souffert de la faim, de la fatigue et de la soif dans le désert. »'),
('2s',18,1,'crampon1923','David, ayant passé en revue le peuple qui était avec lui, établit sur eux des chefs de milliers et des chefs de centaines.'),
('2s',18,2,'crampon1923','David mit le peuple, un tiers aux mains de Joab, un tiers aux mains d''Abisaï, fils de Sarvia, frère de Joab, et un tiers aux mains d''Ethaï, le Géthéen. Et le roi dit au peuple: « Moi aussi je veux sortir avec vous. »'),
('2s',18,3,'crampon1923','Mais le peuple dit: « Tu ne sortiras point! Car, si nous sommes mis en fuite, ils ne prendront pas garde à nous, et si la moitié d''entre nous succombe, ils n''y prendront pas garde. Mais toi, tu es comme dix mille d''entre nous; il vaut donc mieux que tu puisses venir de la ville à notre secours. »'),
('2s',18,4,'crampon1923','Le roi leur répondit: « Ce qui vous paraîtra bon, je le ferai. » Et le roi se tint à côté de la porte, pendant que tout le peuple sortait par groupes de cent et par groupes de mille.'),
('2s',18,5,'crampon1923','Le roi donna cet ordre à Joab, à Abisaï et à Ethaï: « Ménagez-moi le jeune homme, Absalom! » Et tout le peuple entendit que le roi donnait un ordre à tous les chefs au sujet d''Absalom.'),
('2s',18,6,'crampon1923','Le peuple sortit dans la campagne à la rencontre d''Israël, et la bataille eut lieu dans la forêt d''Ephraïm.'),
('2s',18,7,'crampon1923','Là le peuple d''Israël fut battu devant les serviteurs de David, et il y eut là en ce jour un grand carnage; vingt mille hommes périrent.'),
('2s',18,8,'crampon1923','Le combat s''étendit sur la surface de tout le pays, et ce jour-là la forêt dévora plus de gens que n''en dévora l''épée.'),
('2s',18,9,'crampon1923','Absalom se trouva en présence des serviteurs de David. Absalom était monté sur un mulet, et le mulet s''engagea dans les branches touffues d''un grand térébinthe; la tête d''Absalom se prit au térébinthe, et il resta suspendu entre le ciel et la terre, et le mulet qui le portait passa outre.'),
('2s',18,10,'crampon1923','Un homme l''ayant vu, vint le rapporter à Joab, disant: « Voilà que j''ai vu Absalom suspendu à un térébinthe. »'),
('2s',18,11,'crampon1923','Joab dit à l''homme qui lui apportait cette nouvelle: « Tu l''as vu! Pourquoi donc ne l''as-tu pas abattu sur place? Je t''aurais bien donné dix sicles d''argent et une ceinture. »'),
('2s',18,12,'crampon1923','Cet homme répondit à Joab: « Non, quand je pèserais sur ma main mille sicles d''argent, je n''étendrais pas la main sur le fils du roi; car à nos oreilles le roi t''a donné cet ordre, à toi, à Abisaï et à Ethaï: Prenez garde chacun de toucher au jeune homme, à Absalom!'),
('2s',18,13,'crampon1923','Et si j''avais perfidement attenté à sa vie, rien n''aurait été caché au roi, toi-même tu te serais dressé contre moi. »'),
('2s',18,14,'crampon1923','Joab dit: « Je ne veux pas m''attarder auprès de toi; » et ayant pris en main trois javelots, il les enfonça dans le cœur d''Absalom, encore vivant au milieu du térébinthe.'),
('2s',18,15,'crampon1923','Et dix jeunes gens, qui portaient les armes de Joab, entourèrent Absalom, et, le frappant, lui donnèrent la mort.'),
('2s',18,16,'crampon1923','Joab fit sonner de la trompette, et le peuple revint de poursuivre Israël, car Joab retint le peuple.'),
('2s',18,17,'crampon1923','Ayant pris Absalom, ils le jetèrent dans une grande fosse au milieu de la forêt, et on éleva sur lui un très grand monceau de pierres. Et tout Israël s''enfuit chacun dans sa tente.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('2s',18,18,'crampon1923','De son vivant Absalom s''était érigé le monument qui est dans la vallée du Roi; car il disait: « Je n''ai point de fils pour conserver le souvenir de mon nom. » Et il donna son propre nom au monument, et on l''appela la Main d''Absalom, jusqu''à ce jour.'),
('2s',18,19,'crampon1923','Achimaas, fils de Sadoc, dit: « Laisse-moi courir et porter au roi la bonne nouvelle que Yahweh lui a fait justice en le délivrant de la main de ses ennemis. »'),
('2s',18,20,'crampon1923','Joab lui dit: « Tu ne seras pas aujourd''hui le porteur de la bonne nouvelle; tu la porteras une autre fois, mais tu ne la porteras pas aujourd''hui puisque le fils du roi est mort. »'),
('2s',18,21,'crampon1923','Et Joab dit à un Couschite: « Va, et annonce au roi ce que tu as vu. » Le Couschite se prosterna devant Joab et courut.'),
('2s',18,22,'crampon1923','Achimaas, fils de Sadoc, dit encore à Joab: « Quoi qu''il puisse arriver, laisse-moi courir, moi aussi, après le Couschite. » Et Joab dit: « Pourquoi veux-tu courir, mon fils? Ce message ne saurait te profiter. »'),
('2s',18,23,'crampon1923','Achimaas reprit: « Quoi qu''il arrive, je courrai. » Et Joab lui dit: « Cours! » Achimaas courut par le chemin de la Plaine, et il devança le Couschite.'),
('2s',18,24,'crampon1923','David était assis entre les deux portes. La sentinelle alla sur le toit de la porte, au-dessus de la muraille et, levant les yeux, elle regarda et voici un homme qui courait seul.'),
('2s',18,25,'crampon1923','La sentinelle cria et avertit le roi. Le roi dit: « S''il est seul, il y a une bonne nouvelle dans sa bouche. » Pendant que cet homme continuait à approcher,'),
('2s',18,26,'crampon1923','la sentinelle vit un autre homme qui courait. La sentinelle cria au portier et dit: « Voici un homme qui court seul. » Le roi dit: « Lui aussi apporte un bonne nouvelle. »'),
('2s',18,27,'crampon1923','La sentinelle dit: « Je vois que la manière de courir du premier est la manière de courir d''Achimaas, fils de Sadoc. » Et le roi dit: « C''est un homme de bien; il vient pour de bonnes nouvelles. »'),
('2s',18,28,'crampon1923','Achimaas, cria et dit au roi: « Victoire! » Puis il se prosterna devant le roi la face contre terre, et dit: « Béni soit Yahweh, ton Dieu, qui a livré les hommes qui levaient la main contre mon seigneur le roi! »'),
('2s',18,29,'crampon1923','Le roi dit: « Tout va-t-il bien pour le jeune homme, pour Absalom? » Achimaas répondit: « J''ai aperçu une grande foule au moment où Joab envoyait le serviteur du roi et moi, ton serviteur, et j''ignore ce que c''était. »'),
('2s',18,30,'crampon1923','Et le roi dit: « Ecarte-toi et tiens-toi ici. » Il s''écarta et demeura là.'),
('2s',18,31,'crampon1923','Et voici qu''arriva le Couschite; il dit: « Que le roi mon seigneur apprenne une bonne nouvelle! Aujourd''hui Yahweh t''a fait justice de tous ceux qui s''élevaient contre toi. »'),
('2s',18,32,'crampon1923','Le roi dit au Couschite: « Tout va-t-il bien pour le jeune homme, pour Absalom? » Le Couschite répondit: « Qu''ils soient comme ce jeune homme, les ennemis de mon seigneur le roi et tous ceux qui s''élèvent contre toi pour te faire du mal! »'),
('2s',19,1,'crampon1923','Le roi, tremblant d''émotion, monta dans la chambre au-dessus de la porte et pleura. Il disait en marchant: « Mon fils Absalom! Mon fils, mon fils Absalom! Que ne suis-je mort à ta place! Absalom mon fils, mon fils! »'),
('2s',19,2,'crampon1923','On vint dire à Joab: « Voici que le roi pleure et se lamente sur son fils. »'),
('2s',19,3,'crampon1923','La victoire, ce jour-là, fut changée en deuil pour tout le peuple, car le peuple entendit dire en ce jour-là: « Le roi est affligé à cause de son fils. »'),
('2s',19,4,'crampon1923','Ce jour-là le peuple entra dans la ville à la dérobée, comme entrent à la dérobée des gens honteux d''avoir fui dans la bataille.'),
('2s',19,5,'crampon1923','Le roi s''était voilé le visage, et le roi criait à haute voix: « Mon fils Absalom! Absalom, mon fils, mon fils! »'),
('2s',19,6,'crampon1923','Joab vint vers le roi chez lui, et dit: « Tu couvres aujourd''hui de confusion la face de tous tes serviteurs qui ont en ce jour sauvé ta vie et la vie de tes fils et de tes filles, et la vie de tes femmes et la vie de tes concubines.'),
('2s',19,7,'crampon1923','Tu aimes ceux qui te haïssent et tu hais ceux qui t''aiment, car tu montres aujourd''hui que chefs et serviteurs ne sont rien pour toi, et je vois aujourd''hui que si Absalom vivait et que nous fussions tous morts en ce jour, cela serait heureux à tes yeux.'),
('2s',19,8,'crampon1923','Lève-toi donc, sors et parle selon le cœur de tes serviteurs; car je jure par Yahweh que, si tu ne sors pas, pas un homme ne passera avec toi cette nuit; et ce sera pour toi un mal pire que tous les maux qui te sont arrivés depuis ta jeunesse jusqu''à présent. »'),
('2s',19,9,'crampon1923','Alors le roi se leva et il s''assit à la porte. On l''annonça à tout le peuple en disant: « Voici que le roi est assis à la porte. » Et tout le peuple vint devant le roi. Israël s''était enfui chacun dans sa tente.'),
('2s',19,10,'crampon1923','Tout le peuple, dans toutes les tribus d''Israël, s''accusait, en disant: « Le roi nous a délivrés de la main de nos ennemis; c''est lui qui nous a sauvés de la main des Philistins; et maintenant il a dû fuir du pays devant Absalom.'),
('2s',19,11,'crampon1923','Or Absalom, que nous avions oint pour régner sur nous, est mort dans la bataille: pourquoi donc ne parlez-vous pas de faire revenir le roi? »'),
('2s',19,12,'crampon1923','Le roi David envoya parler aux prêtres Sadoc et Abiathar en ces termes: « Parlez aux anciens de Juda et dites-leur: Pourquoi seriez-vous les derniers à ramener le roi dans sa maison? — Et ce qui se disait dans tout Israël était parvenu au roi chez lui. —'),
('2s',19,13,'crampon1923','Vous êtes mes frères, vous êtes mes os et ma chair: pourquoi seriez-vous les derniers à ramener le roi. »'),
('2s',19,14,'crampon1923','Vous direz aussi à Amasa: « N''es-tu pas mon os et ma chair? Que Dieu me traite dans toute sa rigueur, si tu ne deviens pas devant moi pour toujours chef de l''armée à la place de Joab! »'),
('2s',19,15,'crampon1923','Et David fléchit le cœur de tous les hommes de Juda comme d''un seul homme; et ils envoyèrent dire au roi: « Reviens, toi et tous tes serviteurs ».'),
('2s',19,16,'crampon1923','Le roi revint et arriva jusqu''au Jourdain; et Juda se rendit à Galgala pour aller au-devant du roi et faire passer au roi le Jourdain.'),
('2s',19,17,'crampon1923','Séméï, fils de Géra, Benjamite, de Bahurim, se hâta de descendre avec les hommes de Juda à la rencontre du roi David.'),
('2s',19,18,'crampon1923','Il avait avec lui mille hommes de Benjamin, et Siba, serviteur de la maison de Saül, et ses quinze fils et ses vingt serviteurs; ils se précipitèrent au Jourdain devant le roi.'),
('2s',19,19,'crampon1923','Déjà le bateau qui devait transporter la maison du roi et se mettre à sa disposition, était passé. Séméï, fils de Géra, se jeta aux pieds du roi, au moment où celui-ci allait passer le Jourdain,'),
('2s',19,20,'crampon1923','et il dit au roi: « Que mon seigneur ne m''impute point d''iniquité, et ne se souvienne pas de l''offense de ton serviteur, le jour où le roi mon seigneur sortait de Jérusalem, pour y prêter attention, ô roi!'),
('2s',19,21,'crampon1923','Car ton serviteur reconnaît que j''ai péché; et voici que je viens aujourd''hui le premier de toute la maison de Joseph pour descendre à la rencontre du roi mon seigneur. »'),
('2s',19,22,'crampon1923','Abisaï, fils de Sarvia, prit la parole et dit: « Au contraire, Séméï ne doit-il pas être mis à mort pour avoir maudit l''oint de Yahweh? »'),
('2s',19,23,'crampon1923','Mais David dit: « Qu''ai-je à faire avec vous, fils de Sarvia, que vous vous faites aujourd''hui mes adversaires? Un homme serait-il mis à mort en ce jour en Israël? Ne sais-je donc pas que je deviens roi aujourd''hui sur Israël? »'),
('2s',19,24,'crampon1923','Et le roi dit à Séméï: « Tu ne mourras point »; et le roi le lui jura.'),
('2s',19,25,'crampon1923','Miphiboseth, petit-fils de Saül, descendit aussi à la rencontre du roi. Il n''avait pas lavé ses pieds ni arrangé sa moustache, il n''avait pas lavé ses vêtements depuis le jour où le roi était parti jusqu''au jour où il revenait en paix.'),
('2s',19,26,'crampon1923','Lorsqu''il vint de Jérusalem au-devant du roi, le roi lui dit: « Pourquoi n''es-tu pas venu avec moi, Miphiboseth? »'),
('2s',19,27,'crampon1923','Et il répondit: « Mon seigneur le roi, mon serviteur m''a trompé; car ton serviteur s''était dit: Je ferai seller l''ânesse, je monterai sur elle et j''irai avec le roi! car ton serviteur est boiteux.'),
('2s',19,28,'crampon1923','Et il a calomnié ton serviteur auprès de mon seigneur le roi. Mais mon seigneur le roi est comme un ange de Dieu; fais ce qui te semblera bon.'),
('2s',19,29,'crampon1923','Car toute la maison de mon père n''est faite pour mon seigneur le roi que de gens dignes de mort; et cependant tu as mis ton serviteur au nombre de ceux qui mangent à ta table. Quel droit puis-je encore avoir de crier encore vers le roi? »'),
('2s',19,30,'crampon1923','Le roi lui dit: « Pourquoi tant de paroles? Je l''ai déclaré: toi et Siba, vous partagerez les terres. »'),
('2s',19,31,'crampon1923','Et Miphiboseth dit au roi: « Qu''il prenne même le tout, puisque mon seigneur le roi est rentré en paix dans sa maison. »'),
('2s',19,32,'crampon1923','Berzellaï le Galaadite descendit de Rogelim et passa vers le roi au Jourdain pour l''accompagner au fleuve.'),
('2s',19,33,'crampon1923','Berzellaï était très vieux, âgé de quatre-vingt ans; il avait fourni des aliments au roi pendant son séjour à Mahanaïm, car c''était un homme fort riche.'),
('2s',19,34,'crampon1923','Le roi dit à Berzellaï: « Passe avec moi, je te nourrirai chez moi à Jérusalem. »'),
('2s',19,35,'crampon1923','Mais Berzellaï répondit au roi: « Combien d''années ai-je encore à vivre, pour que je monte avec le roi à Jérusalem?'),
('2s',19,36,'crampon1923','Je suis aujourd''hui âgé de quatre-vingt ans. Puis-je distinguer ce qui est bon de ce qui est mauvais? Ton serviteur peut-il savourer ce qu''il mange et ce qu''il boit? Puis-je encore entendre la voix des chanteurs et des chanteuses? Et pourquoi ton serviteur serait-il encore à charge à mon seigneur le roi?'),
('2s',19,37,'crampon1923','Ton serviteur passera un peu au delà du Jourdain avec le roi. Et pourquoi le roi m''accorderait-il cette récompense?'),
('2s',19,38,'crampon1923','Laisse, je t''en prie, ton serviteur s''en retourner, et que je meure dans ma ville, près du sépulcre de mon père et de ma mère. Mais voici ton serviteur Chamaam; qu''il passe avec le roi mon seigneur, et fais pour lui ce que tu trouveras bon. »'),
('2s',19,39,'crampon1923','Le roi dit: « Que Chamaam passe avec moi, et je ferai pour lui tout ce qui te plaira; et tout ce que tu désireras de moi, je te l''accorderai. »'),
('2s',19,40,'crampon1923','Et quand tout le peuple eut passé le Jourdain, le roi le passa aussi, et le roi baisa Berzellaï et le bénit, et celui-ci retourna chez lui.'),
('2s',19,41,'crampon1923','Le roi passa à Galgala, et Chamaam passa avec lui; et tout le peuple de Juda, ainsi que la moitié du peuple d''Israël escortèrent le roi.'),
('2s',19,42,'crampon1923','Mais voici que tous les hommes d''Israël vinrent auprès du roi et lui dirent: « Pourquoi nos frères, les hommes de Juda, t''ont-ils enlevé, et ont-ils fait passer le Jourdain au roi, à sa maison et à tous les gens de David avec lui? »'),
('2s',19,43,'crampon1923','Tous les hommes de Juda répondirent aux hommes d''Israël: « C''est que le roi me tient de plus près; pourquoi te fâches-tu de cela? Avons-nous vécu aux dépens du roi? Ou bien en avons-nous reçu quelque chose? »'),
('2s',19,44,'crampon1923','Les hommes d''Israël répondirent aux hommes de Juda, en disant: « J''ai dix parts sur le roi, et même David m''appartient plus qu''à toi. Pourquoi m''as-tu fait cette injure? Ma parole n''a-t-elle pas été la première pour rétablir mon roi? Et le langage des hommes de Juda fut plus dur que celui des hommes d''Israël. »'),
('2s',20,1,'crampon1923','Il se trouvait là un homme de Bélial, nommé Séba, fils de Bochri, Benjamite; il sonna de la trompette et dit: « Nous n''avons point de part avec David, nous n''avons point d''héritage avec les fils de Jessé. Chacun à ses tentes, Israël! »'),
('2s',20,2,'crampon1923','Et tous les hommes d''Israël s''éloignèrent de David et suivirent Séba, fils de Bochri. Mais les hommes de Juda s''attachèrent à leur roi, depuis le Jourdain jusqu''à Jérusalem.'),
('2s',20,3,'crampon1923','David revint dans sa maison, à Jérusalem, et le roi prit les dix concubines qu''il avait laissées pour veiller sur la maison, et les mit dans une maison gardée. Il pourvut à leur entretien, mais il n''alla plus vers elles; et elles furent enfermées jusqu''au jour de leur mort, vivant ainsi dans l''état de veuvage.'),
('2s',20,4,'crampon1923','Le roi dit à Amasa: « Convoque-moi d''ici à trois jours les hommes de Juda; et toi, sois ici présent. »'),
('2s',20,5,'crampon1923','Amasa partit pour convoquer Juda; mais il tarda au-delà du temps que le roi avait fixé.'),
('2s',20,6,'crampon1923','Alors David dit à Abisaï: « Séba, fils de Bochri, va maintenant nous faire plus de mal qu''Absalom. Toi donc, prends les serviteurs de ton maître et poursuis-le, de peur qu''il ne trouve des villes fortes et ne se dérobe à nos yeux. »'),
('2s',20,7,'crampon1923','Derrière Abisaï partirent les gens de Joab, les Céréthiens et les Phéléthiens, et tous les vaillants hommes; ils sortirent de Jérusalem afin de poursuivre Séba, fils de Bochri.'),
('2s',20,8,'crampon1923','Lorsqu''ils furent près de la grande pierre qui est à Gabaon, Amasa arriva devant eux. Joab avait pour vêtement une tunique militaire, et sur cette tunique était ceinte une épée attachée à ses reins dans son fourreau. Comme il s''avançait, l''épée tomba.'),
('2s',20,9,'crampon1923','Et Joab dit à Amasa: « Te portes-tu bien, mon frère? » Et la main droite de Joab saisit la barbe d''Amasa pour le baiser.'),
('2s',20,10,'crampon1923','Amasa ne prit pas garde à l''épée qui était dans la main de Joab; et Joab l''en frappa au ventre et répandit ses entrailles à terre et, sans qu''on lui portât un second coup, Amasa mourut. Joab et son frère Abisaï se mirent à la poursuite de Séba, fils de Bochri.'),
('2s',20,11,'crampon1923','Mais un des jeunes hommes de Joab resta près d''Amasa, et il disait: « Qui est favorable à Joab, et qui est pour David, qu''il suive Joab! »'),
('2s',20,12,'crampon1923','Or Amasa s''était roulé dans son sang, au milieu de la route. Cet homme, voyant que tout le peuple s''arrêtait, tira Amasa hors de la route dans un champ, et jeta sur lui un manteau, parce qu''il voyait que tous ceux qui arrivaient près de lui s''arrêtaient.'),
('2s',20,13,'crampon1923','Lorsqu''il fut ôté de la route, chacun passa après Joab, à la poursuite de Séba, fils de Bochri.'),
('2s',20,14,'crampon1923','Joab traversa toutes les tribus d''Israël jusqu''à Abel et Beth-Maacha, et tous les hommes d''élite se rassemblèrent et le suivirent.'),
('2s',20,15,'crampon1923','Ils vinrent assiéger Séba dans Abel-Beth-Maacha, et ils élevèrent contre la ville une terrasse, qui atteignait le rempart; et tout le peuple qui était avec Joab s''efforçait à faire tomber la muraille.'),
('2s',20,16,'crampon1923','Alors une femme avisée se mit à crier de la ville: « Ecoutez, écoutez, je vous prie! Dites à Joab: Approche jusqu''ici, je veux te parler. »'),
('2s',20,17,'crampon1923','Il s''approcha d''elle et la femme dit: « Es-tu Joab? » Il répondit: « C''est moi. » Et elle lui dit: « Ecoute les paroles de ta servante. » Il répondit: « J''écoute. »'),
('2s',20,18,'crampon1923','Et elle dit: « Autrefois on avait coutume de dire: Que l''on consulte Abel, — et tout s''arrangeait ainsi.'),
('2s',20,19,'crampon1923','Je suis une des villes paisibles et fidèles en Israël; toi, tu cherches à détruire une ville qui est une mère en Israël! Pourquoi détruirais-tu l''héritage de Yahweh! »'),
('2s',20,20,'crampon1923','Joab répondit: « Loin, bien loin de moi! Je ne veux ni détruire ni ruiner?'),
('2s',20,21,'crampon1923','La chose n''est pas ainsi. Mais un homme de la montagne d''Ephraïm, nommé Séba, fils de Bochri, a levé sa main contre le roi David; livrez-le, lui seul, et je m''éloignerai de la ville. » La femme dit à Joab: « Voici que sa tête te sera jetée par-dessus la muraille. »'),
('2s',20,22,'crampon1923','La femme alla vers tout le peuple et lui parla sagement; et ils coupèrent la tête à Séba, fils de Bochri, et la jetèrent à Joab. Joab fit sonner de la trompette, et l''on se dispersa loin de la ville, chacun vers ses tentes; et Joab retourna à Jérusalem vers le roi.'),
('2s',20,23,'crampon1923','Joab commandait toute l''armée d''Israël; Banaïas, fils de Joïada, commandait les Céréthiens et les Phéléthiens;'),
('2s',20,24,'crampon1923','Aduram était préposé aux corvées; Josaphat, fils d''Ahilud, était archiviste; Siva était secrétaire;'),
('2s',20,25,'crampon1923','Sadoc et Abiathar étaient prêtres,'),
('2s',20,26,'crampon1923','et Ira le Jaïrite était aussi conseiller intime de David.'),
('2s',21,1,'crampon1923','Au temps de David, il y eut une famine, et elle dura trois ans continus. David consulta la face de Yahweh, et Yahweh dit: « C''est à cause de Saül et de sa maison, parce qu''il y a du sang, parce qu''il a mis à mort des Gabaonites. »'),
('2s',21,2,'crampon1923','Le roi appela les Gabaonites et leur dit: — Les Gabaonites n''étaient pas d''entre les enfants d''Israël, mais ils étaient du reste des Amorrhéens, et les enfants d''Israël s''étaient liés envers eux par serment. Et néanmoins, Saül avait voulu les frapper, par zèle pour les enfants d''Israël et de Juda. —'),
('2s',21,3,'crampon1923','David dit aux Gabaonites: « Que ferai-je pour vous, et avec quoi ferai-je l''expiation, afin que vous bénissiez l''héritage de Yahweh? »'),
('2s',21,4,'crampon1923','Les Gabaonites lui dirent: « Ce n''est pas pour nous une question d''argent et d''or avec Saül et avec sa maison, et il n''est pas question pour nous de faire mourir personne en Israël. » Et le roi dit: « Que voulez-vous donc que je fasse pour vous? »'),
('2s',21,5,'crampon1923','Ils répondirent au roi: « Cet homme nous a détruits et il avait formé le projet de nous exterminer, pour que nous ne subsistions pas dans tout le territoire d''Israël:'),
('2s',21,6,'crampon1923','qu''on nous livre sept hommes d''entre ses fils, pour que nous les pendions devant Yahweh à Gabaa de Saül, l''élu de Yahweh. » Et le roi dit: « Je les livrerai. »'),
('2s',21,7,'crampon1923','Le roi épargna Miphiboseth, fils de Jonathas, fils de Saül, à cause du serment par Yahweh qui était entre eux, entre David et Jonathas, fils de Saül.'),
('2s',21,8,'crampon1923','Le roi prit les deux fils que Respha, fille d''Aia, avait enfantés à Saül, Armoni et Miphiboseth, et les cinq fils que Michol, fille de Saül, avait enfantés à Hadriel, fils de Bersellaï, de Molathi,'),
('2s',21,9,'crampon1923','et il les livra entre les mains des Gabaonites, qui les pendirent sur la montagne, devant Yahweh. Tous les sept périrent ensemble; ils furent mis à mort dans les premiers jours de la moisson, au commencement de la moisson des orges.'),
('2s',21,10,'crampon1923','Respha, fille d''Aia, ayant pris un sac, l''étendit pour elle sur le rocher, depuis le commencement de la moisson jusqu''à ce que la pluie se répandit du ciel sur eux; et elle empêcha les oiseaux du ciel de se poser sur eux pendant le jour, et les bêtes des champs pendant la nuit.'),
('2s',21,11,'crampon1923','On apprit à David ce qu''avait fait Respha, fille d''Aia, concubine de Saül.'),
('2s',21,12,'crampon1923','Et David alla prendre les os de Saül et les os de Jonathas, son fils, chez les habitants de Jabès en Galaad, qui les avaient enlevés de la place de Bethsan, où les Philistins les avaient suspendus, au jour où les Philistins avaient battu Saül à Gelboé.'),
('2s',21,13,'crampon1923','Il emporta de là les os de Saül et les os de Jonathas, son fils, et l''on recueillit aussi les os de ceux qui avaient été pendus.'),
('2s',21,14,'crampon1923','On enterra les os de Saül et de son fils Jonathas dans le pays de Benjamin, à Séla, dans le sépulcre de Cis, père de Saül, et l''on fit tout ce que le roi avait ordonné. Après cela, Dieu fut apaisé envers le pays.'),
('2s',21,15,'crampon1923','Il y eut encore guerre entre les Philistins et Israël, et David descendit avec ses serviteurs, et ils combattirent les Philistins: David fut fatigué.'),
('2s',21,16,'crampon1923','Et Jesbi-Benob, l''un des fils de Rapha, — le poids de sa lance était de trois cents sicles d''airain, et il était ceint d''une épée neuve, — parlait de frapper David.'),
('2s',21,17,'crampon1923','Abisaï, fils de Sarvia, vint au secours de David; il frappa le Philistin et le tua. Alors les gens de David lui firent serment, en lui disant: « Tu ne sortiras plus avec nous pour combattre, et tu n''éteindras point le flambeau d''Israël. »'),
('2s',21,18,'crampon1923','Après cela, il y eut encore une bataille à Gob avec les Philistins. Alors Sabochaï, le Husathite, tua Saph, qui était parmi les fils de Rapha.'),
('2s',21,19,'crampon1923','Il y eut encore une bataille à Gob avec les Philistins; et Elchanan, fils de Jaaré-Oreghim, de Bethléem, tua Goliath de Geth; le bois de sa lance était semblable à une ensouple de tisserand.'),
('2s',21,20,'crampon1923','Il y eut encore une bataille à Geth. Il s''y trouva un homme de haute taille, et les doigts de ses mains et les doigts de ses pieds étaient au nombre respectif de six, vingt-quatre en tout, et lui aussi descendait de Rapha.'),
('2s',21,21,'crampon1923','Il insulta Israël, et Jonathan, fils de Samaa, frère de David, le tua.'),
('2s',21,22,'crampon1923','Ces quatre hommes étaient des fils de Rapha, à Geth; ils périrent par la main de David et par la main de ses serviteurs.'),
('2s',22,1,'crampon1923','David adressa à Yahweh les paroles de ce cantique, au jour où Yahweh l''eut délivré de la main de tous ses ennemis et de la main de Saül.'),
('2s',22,2,'crampon1923','Il dit: Yahweh est mon rocher, ma forteresse, mon libérateur,'),
('2s',22,3,'crampon1923','Dieu est mon roc où je trouve un asile, mon bouclier, la corne de mon salut, ma haute retraite et mon refuge. Mon Sauveur, tu m''as sauvé de la violence.'),
('2s',22,4,'crampon1923','J''invoquai celui qui est digne de louange, Yahweh, et je fus délivré de mes ennemis.'),
('2s',22,5,'crampon1923','Car les vagues de la mort m''environnaient, les torrents de Bélial m''épouvantaient.'),
('2s',22,6,'crampon1923','Les liens du schéol m''enlaçaient, les filets de la mort étaient tombés devant moi.'),
('2s',22,7,'crampon1923','Dans ma détresse, j''invoquai Yahweh, et je criai vers mon Dieu; de son temple il entendit ma voix, et mon cri parvint à ses oreilles.'),
('2s',22,8,'crampon1923','La terre fut ébranlée et trembla, les fondements du ciel s''agitèrent; ils furent ébranlés, parce qu''il était courroucé;'),
('2s',22,9,'crampon1923','une fumée montait de ses narines, et un feu dévorant sortait de sa bouche; il en jaillissait des charbons embrasés.'),
('2s',22,10,'crampon1923','Il abaissa les cieux, et descendit; une sombre nuée était sous ses pieds.'),
('2s',22,11,'crampon1923','Il monta sur un Chérubin, et il volait, il apparut sur les ailes du vent.'),
('2s',22,12,'crampon1923','Il s''entoura des ténèbres comme d''une tente, d''amas d''eaux et de sombres nuages.'),
('2s',22,13,'crampon1923','De l''éclat qui le précédait jaillissaient des charbons de feu.'),
('2s',22,14,'crampon1923','Yahweh tonna des cieux, le Très-Haut fit retentir sa voix.'),
('2s',22,15,'crampon1923','Il lança des flèches et les dispersa, la foudre, et il les confondit.'),
('2s',22,16,'crampon1923','Alors le lit de la mer apparut, les fondements de la terre furent mis à nu; à la menace de Yahweh, au souffle du vent de ses narines.'),
('2s',22,17,'crampon1923','Il étendit sa main d''en haut et me saisit, il me retira des grandes eaux;'),
('2s',22,18,'crampon1923','il me délivra de mon ennemi puissant, de ceux qui me haïssaient, alors qu''ils étaient plus forts que moi.'),
('2s',22,19,'crampon1923','Ils m''avaient surpris au jour de mon malheur, mais Yahweh fut mon appui.'),
('2s',22,20,'crampon1923','Il m''a mis au large, il m''a sauvé, parce qu''il s''est complu en moi.'),
('2s',22,21,'crampon1923','Yahweh m''a récompensé selon ma justice, il m''a rendu selon la pureté de mes mains.'),
('2s',22,22,'crampon1923','Car j''ai gardé les voies de Yahweh, et je n''ai pas péché, pour m''éloigner de mon Dieu.'),
('2s',22,23,'crampon1923','Tous ses jugements étaient devant moi, et je ne m''écartais pas de ses lois.'),
('2s',22,24,'crampon1923','J''étais sans reproche envers lui, et je me tenais en garde contre mon iniquité.'),
('2s',22,25,'crampon1923','Yahweh m''a rendu selon ma justice, selon ma pureté devant ses yeux.'),
('2s',22,26,'crampon1923','Avec celui qui est bon, tu te montres bon, avec l''homme droit, tu te montres droit;'),
('2s',22,27,'crampon1923','avec celui qui est pur, tu te montres pur, et avec le fourbe, tu agis perfidement.'),
('2s',22,28,'crampon1923','Tu sauves le peuple humilié, et de ton regard tu abaisses les orgueilleux.'),
('2s',22,29,'crampon1923','Car tu es ma lumière, ô Yahweh; Yahweh éclaire mes ténèbres.'),
('2s',22,30,'crampon1923','Avec toi je me précipite sur les bataillons armés. Avec mon Dieu je franchis les murailles.'),
('2s',22,31,'crampon1923','Dieu!... Ses voies sont parfaites, la parole de Yahweh est éprouvée; il est un bouclier pour tous ceux qui se confient en lui.'),
('2s',22,32,'crampon1923','Car qui est Dieu, si ce n''est Yahweh, et qui est un rocher, si ce n''est notre Dieu?'),
('2s',22,33,'crampon1923','Dieu est ma forte citadelle, il conduit l''homme intègre dans sa voie,'),
('2s',22,34,'crampon1923','Il rend mes pieds semblables à ceux des biches, et il me fait tenir debout sur mes hauteurs.'),
('2s',22,35,'crampon1923','Il forme mes mains au combat, et mes bras tendent l''arc d''airain.'),
('2s',22,36,'crampon1923','Tu m''as donné le bouclier de ton salut, et ta douleur me fait grandir.'),
('2s',22,37,'crampon1923','Tu élargis mon pas au-dessous de moi, et mes pieds ne chancellent point.'),
('2s',22,38,'crampon1923','Je poursuis mes ennemis et je les détruis; je ne reviens pas sans les avoir anéantis.'),
('2s',22,39,'crampon1923','Je les anéantis, je les brise, ils ne se relèvent pas; ils tombent sous mes pieds.'),
('2s',22,40,'crampon1923','Tu me ceins de force pour le combat, tu fais plier sous moi mes adversaires.'),
('2s',22,41,'crampon1923','Mes ennemis, tu leur fais tourner le dos devant moi, comme à ceux qui me haïssent, pour que je les extermine.'),
('2s',22,42,'crampon1923','Ils regardent, et personne qui les sauve! Ils crient vers Yahweh, et il ne leur répond pas!'),
('2s',22,43,'crampon1923','Je les broie comme la poussière de la terre; comme la boue des rues, je les écrase, je les foule.'),
('2s',22,44,'crampon1923','Tu me délivres des révoltes de mon peuple; tu me conserves pour chef des nations; un peuple que je ne connaissais pas m''est asservi.'),
('2s',22,45,'crampon1923','Les fils de l''étranger me flattent, dès qu''ils ont entendu, ils m''obéissent.'),
('2s',22,46,'crampon1923','Les fils de l''étranger sont défaillants, ils sortent tremblants de leurs forteresses.'),
('2s',22,47,'crampon1923','Vive Yahweh et béni soit mon rocher! Dieu, mon rocher de refuge, qu''il soit exalté!'),
('2s',22,48,'crampon1923','Dieu, qui m''accorde des vengeances, qui fait descendre les peuples sous mes pieds,'),
('2s',22,49,'crampon1923','qui me fait échapper à mes ennemis; toi qui m''élèves au-dessus de mes adversaires, qui me délivres de l''homme de violence.'),
('2s',22,50,'crampon1923','C''est pourquoi je te louerai parmi les nations, ô Yahweh, et je chanterai à la gloire de ton nom.'),
('2s',22,51,'crampon1923','Il accorde de glorieuses délivrances à son roi, il fait miséricorde à son oint, à David et à sa postérité pour toujours.'),
('2s',23,1,'crampon1923','Voici les dernières paroles de David: Oracle de David, fils d''Isaï, oracle de l''homme haut placé, de l''oint du Dieu de Jacob, de l''aimable chantre d''Israël.'),
('2s',23,2,'crampon1923','L''Esprit de Yahweh a parlé par moi, et sa parole est sur ma langue.'),
('2s',23,3,'crampon1923','Le Dieu d''Israël a parlé, le Rocher d''Israël a parlé: Un juste dominant sur les hommes, dominant dans la crainte de Dieu!...'),
('2s',23,4,'crampon1923','C''est comme la lumière du matin, quand se lève le soleil, un matin sans nuages! Par ses rayons, après la pluie, l''herbe sort de terre.'),
('2s',23,5,'crampon1923','N''en est-il pas ainsi de ma maison avec Dieu? Car il a fait avec moi une alliance éternelle, de tous points bien ordonnée et gardée; oui, il fera germer tout mon salut et tout son bon plaisir.'),
('2s',23,6,'crampon1923','Mais les gens de Bélial sont tous comme des épines que l''on rejette, on ne les prend pas avec la main;'),
('2s',23,7,'crampon1923','l''homme qui y touche s''arme d''un fer ou d''un bois de lance, et on les consume par le feu sur place.'),
('2s',23,8,'crampon1923','Voici les noms des héros qui étaient au service de David: Jessbam, fils de Hachamoni, chef des officiers. Il brandit sa lance sur huit cents hommes, qu''il fit périr en une seule fois.'),
('2s',23,9,'crampon1923','Après lui, Eléazar, fils de Dodo, fils d''Ahohi. Il était parmi les trois vaillants qui étaient avec David, lorsqu''ils défièrent les Philistins qui étaient rassemblés là pour combattre,'),
('2s',23,10,'crampon1923','tandis que les hommes d''Israël remontaient. Il se leva et frappa les Philistins jusqu''à ce que sa main fut lasse, et que sa main adhérât à l''épée. Yahweh opéra une grande délivrance en ce jour-là, et le peuple revint à la suite d''Eléazar, mais seulement pour ramasser les dépouilles.'),
('2s',23,11,'crampon1923','Après lui, Semma, fils d''Agé, le Hararite. Les Philistins s''étaient rassemblés en une seule troupe; il y avait là une pièce de terre pleine de lentilles, et le peuple fuyait devant les Philistins.'),
('2s',23,12,'crampon1923','Semma se plaça au milieu du champ, le défendit et battit les Philistins. Et Yahweh opéra une grande délivrance.'),
('2s',23,13,'crampon1923','Trois d''entre les trente capitaines descendirent et vinrent, au temps de la moisson, auprès de David, à la caverne d''Odollam, tandis qu''une troupe de Philistins était campée dans la vallée des Réphaïm.'),
('2s',23,14,'crampon1923','David était alors dans la forteresse, et il y avait un poste de Philistins à Bethléem.'),
('2s',23,15,'crampon1923','David eut un désir, et il dit: « Qui me fera boire de l''eau de la citerne qui est à la porte de Bethléem? »'),
('2s',23,16,'crampon1923','Aussitôt les trois braves, passant au travers du camp des Philistins, puisèrent de l''eau de la citerne qui est à la porte de Bethléem. Ils la prirent et l''apportèrent à David; mais il ne voulut pas la boire, et il en fit une libation à Yahweh,'),
('2s',23,17,'crampon1923','en disant: « Loin de moi, ô Yahweh, de faire cela! N''est-ce pas le sang de ces hommes qui sont allés au péril de leur vie? » Et il ne voulut pas la boire. Voilà ce que firent ces trois braves.'),
('2s',23,18,'crampon1923','Abisaï, frère de Joab, fils de Sarvia, était aussi chef des officiers. Il brandit sa lance contre trois cents hommes et les tua, et il eut du renom parmi les trois.'),
('2s',23,19,'crampon1923','Il était le plus considéré d''entre les trois, et il fut leur chef; mais il n''égala pas les trois premiers.'),
('2s',23,20,'crampon1923','Banaïas, fils de Joïadas, fils d''un homme vaillant et riche en exploits, de Cabséel. Il frappa les deux ariels de Moab. Il descendit et frappa le lion au milieu de la citerne un jour de neige.'),
('2s',23,21,'crampon1923','Il frappa un Egyptien d''un aspect redoutable; et dans la main de l''Egyptien il y avait une lance. Il descendit vers lui avec un bâton, et il arracha la lance de la main de l''Egyptien et le frappa de sa propre lance.'),
('2s',23,22,'crampon1923','Voilà ce que fit Banaïas, fils de Joïadas, et il eut du renom parmi les trois vaillants.'),
('2s',23,23,'crampon1923','Il était plus considéré que les trente, mais il n''égala pas les trois. David le fit membre de son conseil.'),
('2s',23,24,'crampon1923','Asaël, frère de Joab, était des trente; Elchanan, fils de Dodo, de Bethléem;'),
('2s',23,25,'crampon1923','Semma, de Harod; Elica, de Harod;'),
('2s',23,26,'crampon1923','Hélès de Phalti; Hira, fils d''Accès, de Thécué;'),
('2s',23,27,'crampon1923','Abiéser, d''Anathoth; Mobonnaï, le Husatite;'),
('2s',23,28,'crampon1923','Selmon, l''Ahohite; Maharaï, de Nétopha;'),
('2s',23,29,'crampon1923','Héled, fils de Baana, de Nétopha; Ethaï, fils de Ribaï, de Gabaa des fils de Benjamin;'),
('2s',23,30,'crampon1923','Banaïa, de Pharaton; Heddaï, des vallées de Gaas;'),
('2s',23,31,'crampon1923','Abi-Albon, d''Araba; Azmaveth, de Bérom;'),
('2s',23,32,'crampon1923','Eliaba, de Salabon; Benê-Yassen; Jonathan;'),
('2s',23,33,'crampon1923','Semma, le Hararite; Ahiam, fils de Sarar, le Haradite;'),
('2s',23,34,'crampon1923','Eliphélet, fils d''Aasbaï, fils d''un Machatien; Eliam, fils d''Achitophel, de Gilo;'),
('2s',23,35,'crampon1923','Hesraï, de Carmel; Pharaï, d''Arbi;'),
('2s',23,36,'crampon1923','Igaal, fils de Nathan, de Soba; Bonni de Gad;'),
('2s',23,37,'crampon1923','Sélec, l''Ammonite; Naharaï, de Béroth, écuyer de Joab, fils de Sarvia;'),
('2s',23,38,'crampon1923','Ira, de Jéther; Gareb, de Jéther;'),
('2s',23,39,'crampon1923','Urie, le Héthéen. En tout trente-sept.'),
('2s',24,1,'crampon1923','La colère de Yahweh s''enflamma de nouveau contre Israël, et il excita David contre eux, en disant: « Va, fais le dénombrement d''Israël et de Juda. »'),
('2s',24,2,'crampon1923','Le roi dit à Joab, chef de l''armée, qui était avec lui: « Parcours donc toutes les tribus d''Israël, depuis Dan jusqu''à Bersabée; faites le dénombrement du peuple, afin que je sache le chiffre du peuple. »'),
('2s',24,3,'crampon1923','Joab dit au roi: « Que Yahweh ton Dieu ajoute au peuple cent fois ce qu''il y en a, et que les yeux du roi mon seigneur le voient! Mais pourquoi le roi mon seigneur met-il son plaisir à faire cela? »'),
('2s',24,4,'crampon1923','Mais la parole du roi prévalut contre Joab, et sur les chefs de l''armée; et Joab et les chefs de l''armée partirent de devant le roi pour faire le dénombrement du peuple d''Israël.'),
('2s',24,5,'crampon1923','Ayant passé le Jourdain, ils campèrent à Aroër, à droite de la ville, qui est au milieu de la vallée de Gad, puis à Jazer.'),
('2s',24,6,'crampon1923','Ils vinrent en Galaad et dans le pays de Thachthim-Hodsi; puis ils vinrent à Dan-Jaan et aux environs de Sidon.'),
('2s',24,7,'crampon1923','Ils vinrent à la place forte de Tyr et dans toutes les villes des Hévéens et des Chananéens, ils aboutirent au Négeb de Juda, à Bersabée.'),
('2s',24,8,'crampon1923','Lorsqu''ils eurent ainsi parcouru tout le pays, ils revinrent à Jérusalem au bout de neuf mois et vingt jours.'),
('2s',24,9,'crampon1923','Joab remit au roi le rôle du dénombrement du peuple: il y avait en Israël huit cent mille hommes de guerre tirant l''épée, et en Juda cinq cent mille hommes.'),
('2s',24,10,'crampon1923','David sentit battre son cœur après qu''il eut compté le peuple, et David dit à Yahweh: « J''ai commis un grand péché en ce que j''ai fait! Maintenant, ô Yahweh, ôtez, je vous prie, l''iniquité de votre serviteur, car j''ai tout à fait agi en insensé. »'),
('2s',24,11,'crampon1923','Le lendemain, quand David se leva, la parole de Yahweh fut adressée à Gad, le prophète, le voyant de David, en ces termes:'),
('2s',24,12,'crampon1923','« Va dire à David: Ainsi parle Yahweh: Je mets devant toi trois choses; choisis-en une, et je te la ferai. »'),
('2s',24,13,'crampon1923','Gad vint vers David et lui fit connaître la parole de Yahweh, et lui dit: « Une famine de sept années viendra-t-elle dans ton pays, ou bien fuiras-tu trois mois devant tes ennemis qui te poursuivront, ou bien y aura-t-il une peste de trois jours dans ton pays? Maintenant, sache et vois ce que je dois répondre à celui qui m''envoie. »'),
('2s',24,14,'crampon1923','David répondit à Gad: « Je suis dans une cruelle angoisse. Ah! Tombons entre les mains de Yahweh, car ses miséricordes sont grandes; mais que je ne tombe pas entre les mains des hommes! »'),
('2s',24,15,'crampon1923','Et Yahweh envoya une peste en Israël depuis le matin de ce jour jusqu''au temps fixé; et il mourut, de Dan à Bersabée, soixante-dix mille hommes parmi le peuple.'),
('2s',24,16,'crampon1923','L''ange étendait la main sur Jérusalem pour la détruire. Et Yahweh se repentit de ce mal, et il dit à l''ange qui faisait périr le peuple: « Assez! retire maintenant ta main. » L''ange de Yahweh se tenait près de l''aire d''Areuna, le Jébuséen.'),
('2s',24,17,'crampon1923','A la vue de l''ange qui frappait le peuple, David dit à Yahweh: « Voici, c''est moi qui ai péché, c''est moi qui suis coupable; mais celles-là, ces brebis, qu''ont-elles fait? Que ta main soit donc sur moi et sur la maison de mon père! »'),
('2s',24,18,'crampon1923','Ce jour-là, Gad vint auprès de David et lui dit: « Monte et élève à Yahweh un autel sur l''aire d''Areuna, le Jébuséen. »'),
('2s',24,19,'crampon1923','David monta, selon la parole de Gad, comme Yahweh l''avait ordonné.'),
('2s',24,20,'crampon1923','Areuna, ayant regardé, vit le roi et ses serviteurs qui se dirigeaient vers lui;'),
('2s',24,21,'crampon1923','Areuna sortit et se prosterna devant le roi, le visage contre terre, en disant: « Pourquoi mon seigneur le roi vient-il vers son serviteur? » Et David répondit: « Pour acheter de toi cette aire afin de bâtir un autel à Yahweh, pour que la plaie se retire de dessus le peuple. »'),
('2s',24,22,'crampon1923','Areuna dit à David: « Que mon seigneur le roi prenne l''aire et qu''il offre en sacrifice ce qu''il trouvera bon! Voici les bœufs pour l''holocauste, les traîneaux et les jougs des bœufs pour le bois.'),
('2s',24,23,'crampon1923','Tout cela, ô roi, Areuna le donne au roi. » Et Areuna dit encore au roi: « Que Yahweh; ton Dieu, te sois favorable! »'),
('2s',24,24,'crampon1923','Mais le roi dit à Areuna: « Non! Mais je veux l''acheter de toi à prix d''argent, et je n''offrirai point à Yahweh, mon Dieu, des holocaustes qui ne me coûtent rien. » Et David acheta l''aire et les bœufs pour cinquante sicles d''argent.'),
('2s',24,25,'crampon1923','Et David bâtit là un autel à Yahweh et offrit des holocaustes et des sacrifices pacifiques. Ainsi Yahweh fut apaisé envers le pays, et la plaie se retira d''Israël.'),
('1r',1,1,'crampon1923','Le roi David était vieux, avancé en âge; on le couvrait de vêtements, sans qu''il pût se réchauffer.'),
('1r',1,2,'crampon1923','Ses serviteurs lui dirent: « Que l''on cherche pour mon seigneur le roi une jeune fille vierge; qu''elle se tienne devant le roi et le soigne, et qu''elle couche dans ton sein, et mon seigneur le roi se réchauffera. »'),
('1r',1,3,'crampon1923','On chercha dans tout le territoire d''Israël une jeune fille qui fût belle, et l''on trouva Abisag, la Sunamite, que l''on amena au roi.'),
('1r',1,4,'crampon1923','Cette jeune fille était fort belle; elle soigna le roi et le servit; mais le roi ne la connut point.'),
('1r',1,5,'crampon1923','Or Adonias, fils de Haggith, s''élevait dans ses pensées, disant: « C''est moi qui serai roi. » Et il se procura des chars et des chevaux, et cinquante hommes courant devant lui.'),
('1r',1,6,'crampon1923','Et son père ne lui avait jamais fait de peine dans sa vie en lui disant: « Pourquoi agis-tu ainsi? » En outre, Adonias était très beau de figure, et sa mère l''avait enfanté après Absalom.'),
('1r',1,7,'crampon1923','Il y eut des entretiens avec Joab, fils de Sarvia, et avec le prêtre Abiathar; et ils embrassèrent le parti d''Adonias.'),
('1r',1,8,'crampon1923','Mais le prêtre Sadoc, Banaïas, fils de Joïadas, Nathan le prophète, Séméï, Réï et les vaillants hommes de David ne furent pas avec Adonias.'),
('1r',1,9,'crampon1923','Adonias immola des brebis, des bœufs et des veaux gras près de la pierre de Zohéleth, qui est à côté d''En-Rogel, et il invita tous ses frères, fils du roi, et tous les hommes de Juda, serviteurs du roi.'),
('1r',1,10,'crampon1923','Mais il n''invita pas Nathan le prophète, ni Banaïas, ni les vaillants hommes, ni Salomon, son frère.'),
('1r',1,11,'crampon1923','Alors Nathan dit à Bethsabée, mère de Salomon: « N''as-tu pas appris qu''Adonias, fils de Haggith, est devenu roi, sans que notre seigneur David le sache?'),
('1r',1,12,'crampon1923','Viens donc maintenant, laisse-moi te donner un conseil, afin que tu sauves ta vie et celle de ton fils Salomon.'),
('1r',1,13,'crampon1923','Va, entre chez le roi David, et dis-lui: O roi, mon seigneur, n''as-tu pas fait serment à ta servante en disant: Salomon, ton fils, régnera après moi, et c''est lui qui s''assiéra sur mon trône? Pourquoi donc Adonias est-il devenu roi?'),
('1r',1,14,'crampon1923','Et voici, pendant que tu parleras là avec le roi, j''entrerai après toi, et je confirmerai tes paroles. »'),
('1r',1,15,'crampon1923','Bethsabée se rendit auprès du roi, dans sa chambre; le roi était très vieux, et Abisag, la Sunamite, servait le roi.'),
('1r',1,16,'crampon1923','Bethsabée s''inclina et se prosterna devant lui, et le roi dit: « Que veux-tu? »'),
('1r',1,17,'crampon1923','Elle lui répondit: « Mon seigneur, tu as fait serment à ta servante par Yahweh, ton Dieu, en disant: Salomon, ton fils, régnera après moi, et c''est lui qui sera assis sur mon trône.'),
('1r',1,18,'crampon1923','Et maintenant, voici qu''Adonias est devenu roi, et cependant, toi, ô roi mon seigneur, tu l''ignores!'),
('1r',1,19,'crampon1923','Il a immolé des bœufs, des veaux gras et des brebis en grand nombre; et il a invité tous les fils du roi, le prêtre Abiathar, et Joab, chef de l''armée, mais il n''a pas invité Salomon, ton serviteur.'),
('1r',1,20,'crampon1923','Cependant, ô roi mon seigneur, tout Israël a les yeux sur toi, pour que tu fasses connaître qui doit s''asseoir sur le trône du roi mon seigneur après lui.'),
('1r',1,21,'crampon1923','Autrement, lorsque le roi mon seigneur sera couché avec ses pères, il arrivera que nous serons, moi et mon fils Salomon, traités comme des criminels. »'),
('1r',1,22,'crampon1923','Comme elle parlait encore avec le roi, voici que Nathan, le prophète, arriva.'),
('1r',1,23,'crampon1923','On l''annonça au roi, en disant: « Voici Nathan, le prophète. » Il entra en présence du roi et se prosterna devant lui, le visage contre terre;'),
('1r',1,24,'crampon1923','et Nathan dit: « O roi, mon seigneur, tu as donc dit: Adonias régnera après moi et il s''assiéra sur mon trône!'),
('1r',1,25,'crampon1923','Car il est descendu aujourd''hui, il a immolé des bœufs, des veaux gras et des brebis en quantité, et il a invité tous les fils du roi, les chefs de l''armée et le prêtre Abiathar. Et voici qu''ils mangent et boivent devant lui, et ils disent: Vive le roi Adonias!'),
('1r',1,26,'crampon1923','Mais il n''a invité ni moi, ton serviteur, ni le prêtre Sadoc, ni Banaïas, fils de Joïadas, ni Salomon, ton serviteur.'),
('1r',1,27,'crampon1923','Est-ce bien par la volonté de mon seigneur le roi qu''une telle chose a lieu, sans que tu aies fait connaître à tes serviteurs qui doit s''asseoir sur le trône du roi mon seigneur, après lui? »'),
('1r',1,28,'crampon1923','Le roi David répondit et dit: « Appelez-moi Bethsabée. » Elle entra devant le roi et se présenta devant le roi.'),
('1r',1,29,'crampon1923','Et le roi fit ce serment: « Vive Yahweh qui m''a délivré de toutes les adversités!'),
('1r',1,30,'crampon1923','Ce que je t''ai juré par Yahweh, le Dieu d''Israël, en disant: Salomon, ton fils, régnera après moi, et il s''assiéra sur mon trône à ma place, — je le ferai en ce jour. »'),
('1r',1,31,'crampon1923','Bethsabée s''inclina le visage contre terre et se prosterna devant le roi; et elle dit: « Vive à jamais mon seigneur, le roi David! »'),
('1r',1,32,'crampon1923','Le roi David dit: « Appelez-moi le prêtre Sadoc, Nathan le prophète, et Banaïas, fils de Joïadas. » Lorsqu''ils furent entrés en présence du roi,'),
('1r',1,33,'crampon1923','le roi leur dit: « Prenez avec vous les serviteurs de votre maître, faites monter mon fils Salomon sur ma mule, et vous le ferez descendre à Gihon.'),
('1r',1,34,'crampon1923','Là, le prêtre Sadoc et Nathan le prophète l''oindront pour roi sur Israël; et vous sonnerez de la trompette et vous direz: Vive le roi Salomon!'),
('1r',1,35,'crampon1923','Puis vous remonterez après lui; il viendra s''asseoir sur mon trône, et il régnera à ma place, car c''est lui que j''établis pour être chef d''Israël et de Juda. »'),
('1r',1,36,'crampon1923','Banaïas, fils de Joïadas, répondit au roi: « Amen! Qu''ainsi l''ordonne Yahweh, le Dieu de mon seigneur le roi!'),
('1r',1,37,'crampon1923','Comme Yahweh a été avec mon seigneur le roi, qu''il soit de même avec Salomon, et qu''il élève son trône au-dessus du trône de mon seigneur le roi David! »'),
('1r',1,38,'crampon1923','Le prêtre Sadoc descendit avec Nathan le prophète, Banaïas, fils de Joïadas, les Céréthiens et les Phéléthiens, et, ayant fait monter Salomon sur la mule du roi David, ils le menèrent à Gihon.'),
('1r',1,39,'crampon1923','Le prêtre Sadoc prit dans le tabernacle la corne d''huile, et il oignit Salomon; on sonna de la trompette et tout le peuple dit: « Vive le roi Salomon! »'),
('1r',1,40,'crampon1923','Puis tout le peuple monta après lui. Le peuple jouait de la flûte et se livrait à une grande joie; la terre se fendait au bruit de leurs clameurs.'),
('1r',1,41,'crampon1923','Adonias entendis ce bruit, ainsi que tous les conviés qui étaient avec lui, au moment où ils achevaient leur festin. En entendant le son de la trompette, Joab dit: « Pourquoi ce bruit de la ville en émoi? »'),
('1r',1,42,'crampon1923','Il parlait encore, et voici que Jonathas, fils de prêtre Abiathar, arriva. Adonias lui dit: « Viens, car tu es un brave et porteur de bonnes nouvelles. »'),
('1r',1,43,'crampon1923','Jonathas répondit et dit à Adonias: « Oui, vraiment! notre seigneur le roi David a fait roi Salomon.'),
('1r',1,44,'crampon1923','Le roi a envoyé avec lui le prêtre Sadoc, Nathan le prophète, Banaïas, fils de Joïadas, les Céréthiens et les Phéléthiens, et ils l''ont fait monter sur la mule du roi.'),
('1r',1,45,'crampon1923','Le prêtre Sadoc et Nathan le prophète l''ont oint pour roi à Gihon; de là ils sont remontés remontés joyeux, et la ville est en émoi: c''est là le bruit que vous avez entendu.'),
('1r',1,46,'crampon1923','Salomon s''est même assis sur le trône royal.'),
('1r',1,47,'crampon1923','Et même les serviteurs du roi sont venus pour bénir notre seigneur le roi David, en disant: Que ton Dieu rende le nom de Salomon plus grand que ton nom, et qu''il élève son trône au-dessus de ton trône! Et le roi s''est prosterné sur son lit.'),
('1r',1,48,'crampon1923','Et même le roi a parlé ainsi: Béni soit Yahweh, le Dieu d''Israël, qui m''a donné aujourd''hui un successeur sur mon trône, afin que je puisse le voir de mes yeux!»'),
('1r',1,49,'crampon1923','Tous les conviés d''Adonias furent saisis de terreur; ils se levèrent et s''en allèrent chacun de son côté.'),
('1r',1,50,'crampon1923','Adonias, ayant peur de Salomon, se leva et s''en alla, et il saisit les cornes de l''autel.'),
('1r',1,51,'crampon1923','On l''annonça à Salomon en ces termes: « Voici qu''Adonias a peur du roi Salomon, et voici qu''il a saisi les cornes de l''autel en disant: Que le roi Salomon me jure aujourd''hui qu''il ne fera pas mourir son serviteur par l''épée! »'),
('1r',1,52,'crampon1923','Salomon dit: « S''il se montre homme brave, il ne tombera pas à terre un de ses cheveux; mais s''il se trouve du mal en lui, il mourra. »'),
('1r',1,53,'crampon1923','Et le roi Salomon envoya des gens qui le firent descendre d''auprès de l''autel. Et Adonias vint se prosterner devant le roi Salomon; et Salomon lui dit: « Va dans ta maison. »'),
('1r',2,1,'crampon1923','Comme le temps de sa mort approchait, David donna ses ordres à Salomon, son fils, en disant:'),
('1r',2,2,'crampon1923','« Je m''en vais par le chemin de toute la terre; montre-toi fort et sois un homme!'),
('1r',2,3,'crampon1923','Garde le service de Yahweh, ton Dieu, en marchant dans ses voies, en observant ses lois, ses commandements, ses ordonnances et ses préceptes, selon ce qui est écrit dans la loi de Moïse, afin que tu réussisses dans tout ce que tu feras et partout où tu te tourneras,'),
('1r',2,4,'crampon1923','en sorte que Yahweh accomplisse sa parole qu''il a prononcée sur moi, en disant: Si tes fils prennent garde à leur voie, en marchant devant moi avec fidélité, de tout leur cœur et de toute leur âme, tu ne manqueras jamais d''un descendant assis sur le trône d''Israël.'),
('1r',2,5,'crampon1923','Tu sais aussi toi-même ce que m''a fait Joab, fils de Sarvia, ce qu''il a fait aux deux chefs des armées d''Israël, à Abner, fils de Ner, et à Amasa, fils de Jéther: il les a tués, versant pendant la paix le sang de la guerre, et mettant le sang de la guerre sur la ceinture qu''il avait aux reins et sur la chaussure qu''il avait aux pieds.'),
('1r',2,6,'crampon1923','Tu agiras selon ta sagesse, et tu ne laisseras pas ses cheveux blancs descendre en paix au séjour des morts.'),
('1r',2,7,'crampon1923','Mais aux fils de Berzellaï le Galaadite tu montreras de la bienveillance, et ils seront de ceux qui mangent à ta table; car c''est ainsi qu''ils se sont approchés de moi lorsque je fuyais devant Absalom, ton frère.'),
('1r',2,8,'crampon1923','Voici que tu as près de toi Séméï, fils de Géra, Benjamite, de Bahurim. Il a proféré contre moi des malédictions violentes le jour où j''allais à Mahanaïm. Mais comme il descendit à ma rencontre vers le Jourdain, je lui jurai par Yahweh, en disant: Je ne te ferai point mourir par l''épée.'),
('1r',2,9,'crampon1923','Et maintenant, tu ne le laisseras pas impuni; car tu es un homme sage, et tu sais comment tu dois le traiter; c''est dans le sang que tu feras descendre ses cheveux blancs au séjour des morts. »'),
('1r',2,10,'crampon1923','David se coucha avec ses pères, et il fut enterré dans la cité de David.'),
('1r',2,11,'crampon1923','Le temps que David régna sur Israël fut de quarante ans: il régna sept ans à Hébron, et il régna trente-trois ans à Jérusalem.'),
('1r',2,12,'crampon1923','Et Salomon s''assit sur le trône de David, son père, et son règne fut bien affermi.'),
('1r',2,13,'crampon1923','Adonias, fils de Haggith, vint trouver Bethsabée, mère de Salomon. Elle lui dit: « Viens-tu dans une intention pacifique? » Il répondit: « Oui! dans une intention pacifique; »'),
('1r',2,14,'crampon1923','et il ajouta: « J''ai un mot à te dire. » Elle dit: « Parle. »'),
('1r',2,15,'crampon1923','Et il dit: « Tu sais que le royaume m''appartenait, et que tout Israël portait ses regards sur moi pour que je règne. Mais la royauté a été transférée, et elle a été donnée à mon frère, parce que Yahweh la lui avait destinée.'),
('1r',2,16,'crampon1923','Maintenant, je te demande une seule chose; ne me rejette pas. » Elle lui répondit: « Parle. »'),
('1r',2,17,'crampon1923','Et il dit: « Dis, je te prie, au roi Salomon — car il ne te rejettera pas — de me donner pour femme Abisag, la Sunamite. »'),
('1r',2,18,'crampon1923','Bethsabée dit: « Bien! Je parlerai au roi à ton sujet. »'),
('1r',2,19,'crampon1923','Bethsabée se rendit auprès du roi Salomon pour lui parler au sujet d''Adonias. Et le roi se leva pour aller à sa rencontre et il se prosterna devant elle; il s''assit sur son trône, et fit placer un trône pour la mère du roi, et elle s''assit à sa droite.'),
('1r',2,20,'crampon1923','Puis elle dit: « J''ai une petite demande à te faire: ne me rejette pas. » Le roi lui dit: « Demande, ma mère, car je ne te rejetterai pas. »'),
('1r',2,21,'crampon1923','Elle dit: « Qu''Abisag, la Sunamite, soit donnée pour femme à Adonias, ton frère. »'),
('1r',2,22,'crampon1923','Le roi Salomon répondit et dit à sa mère: « Pourquoi demandes-tu Abisag, la Sunamite, pour Adonias? Demande donc la royauté pour lui, — car il est mon frère aîné, — pour lui, pour le prêtre Abiathar, et pour Joab, fils de Sarvia! »'),
('1r',2,23,'crampon1923','Le roi Salomon jura par Yahweh, en disant: « Que Dieu me traite dans toute sa rigueur si ce n''est pas pour sa perte qu''Adonias a prononcé cette parole!'),
('1r',2,24,'crampon1923','Et maintenant, Yahweh est vivant! — lui qui m''a affermi et m''a fait asseoir sur le trône de David, mon père, et qui m''a édifié une maison selon qu''il l''avait dit, — aujourd''hui même, Adonias sera mis à mort! »'),
('1r',2,25,'crampon1923','Et le roi Salomon députa Banaïas, fils de Joïadas; il frappa Adonias, qui mourut.'),
('1r',2,26,'crampon1923','Le roi dit au prêtre Abiathar: « Va-t''en à Anathoth dans tes terres, car tu mérites la mort; mais je ne te ferai pas mourir aujourd''hui, parce que tu as porté l''arche du Seigneur Yahweh devant David, mon père, et parce que tu as eu ta part dans tout ce qu''a souffert mon père. »'),
('1r',2,27,'crampon1923','Et Salomon chassa Abiathar pour qu''il ne fût plus prêtre de Yahweh, accomplissant ainsi la parole que Yahweh avait prononcée sur la maison d''Héli à Silo.'),
('1r',2,28,'crampon1923','La nouvelle en parvint à Joab, car Joab avait suivi le parti d''Adonias, quoiqu''il n''eût pas suivi le parti d''Absalom. Et Joab s''enfuit au tabernacle de Yahweh, et il saisit les cornes de l''autel.'),
('1r',2,29,'crampon1923','On annonça au roi Salomon que Joab s''était réfugié au tabernacle de Yahweh et qu''il était auprès de l''autel; et Salomon envoya Banaïas, fils de Joïadas, en lui disant: « Va, frappe-le. »'),
('1r',2,30,'crampon1923','Arrivé au tabernacle de Yahweh, Banaïas dit à Joab: « Ainsi parle le roi: Sors. » Mais il répondit: « Non! je mourrai ici. » Banaïas rapporta cette réponse au roi, en disant: « C''est ainsi qu''a parlé Joab, c''est ainsi qu''il m''a répondu. »'),
('1r',2,31,'crampon1923','Et le roi dit à Banaïas: « Fais comme il a dit, frappe-le et enterre-le; tu ôteras ainsi de dessus moi et de dessus la maison de mon père le sang que Joab a répandu sans raison.'),
('1r',2,32,'crampon1923','Yahweh fera retomber son sang sur sa tête, lui qui a frappé deux hommes plus justes et meilleurs que lui, et qui les a tués par l''épée, sans que mon père David le sût: Abner, fils de Ner, chef de l''armée d''Israël, et Amasa, fils de Jéther, chef de l''armée de Juda.'),
('1r',2,33,'crampon1923','Leur sang retombera sur la tête de Joab et sur la tête de ses descendants à jamais; mais il y aura paix pour toujours, de la part de Yahweh, pour David et sa postérité, pour sa maison et son trône. »'),
('1r',2,34,'crampon1923','Banaïas, fils de Joïadas, monta et, ayant frappé Joab, il lui donna la mort, et il fut enterré dans sa maison, au désert.'),
('1r',2,35,'crampon1923','Et le roi mit à sa place, comme chef de l''armée, Banaïas, fils de Joïadas; et le roi mit le prêtre Sadoc à la place d''Abiathar.'),
('1r',2,36,'crampon1923','Le roi envoya appeler Séméï et lui dit: « Bâtis-toi une maison à Jérusalem; tu y demeureras et tu n''en sortiras point pour aller de côté et d''autre.'),
('1r',2,37,'crampon1923','Le jour où tu sortiras et passeras le torrent de Cédron, sache bien que certainement tu mourras; ton sang sera sur ta tête. »'),
('1r',2,38,'crampon1923','Séméï répondit au roi: « Cette parole est bonne; ce que dit mon seigneur le roi, ton serviteur le fera. » Et Séméï demeura de nombreux jours à Jérusalem.'),
('1r',2,39,'crampon1923','Il arriva, au bout de trois ans, que deux serviteurs de Séméï s''enfuirent auprès d''Achis, fils de Maacha, roi de Geth. On le rapporta à Séméï, en disant: « Voici que tes serviteurs sont à Geth. »'),
('1r',2,40,'crampon1923','Séméï se leva et, ayant sellé son âne, il se rendit à Geth, auprès d''Achis, pour chercher ses serviteurs. Séméï s''en alla et ramena de Geth ses serviteurs.'),
('1r',2,41,'crampon1923','On rapporta à Salomon que Séméï était allé de Jérusalem à Geth et qu''il était de retour.'),
('1r',2,42,'crampon1923','Le roi envoya appeler Séméï et lui dit: « Ne t''avais-je pas fait jurer par Yahweh, et ne t''avais-je pas fait une injonction en disant: Le jour où tu sortiras pour aller de côté ou d''autre, sache bien que certainement tu mourras? Et ne m''as-tu pas répondu: La parole que j''ai entendue est bonne?'),
('1r',2,43,'crampon1923','Pourquoi donc n''as-tu pas observé le serment fait à Yahweh et l''ordre que je t''avais donné? »'),
('1r',2,44,'crampon1923','Et le roi dit à Séméï: « Tu sais — ton cœur le sait — tout le mal que tu as fait à David, mon père; Yahweh fait retomber ta méchanceté sur ta tête.'),
('1r',2,45,'crampon1923','Mais le roi Salomon sera béni, et le trône de David sera affermi à jamais devant Yahweh. »'),
('1r',2,46,'crampon1923','Et le roi donna des ordres à Banaïas, fils de Joïadas; et il sortit et frappa Séméï, qui mourut. Et la royauté fut affermie entre les mains de Salomon.'),
('1r',3,1,'crampon1923','Salomon s''allia par un mariage avec Pharaon, roi d''Egypte. Il prit pour femme la fille de Pharaon, et il l''amena dans la cité de David, jusqu''à ce qu''il eût achevé de bâtir sa maison et la maison de Yahweh, ainsi que le mur d''enceinte de Jérusalem.'),
('1r',3,2,'crampon1923','Seulement le peuple sacrifiait sur les hauts lieux, car il n''avait pas été bâti de maison au nom de Yahweh jusqu''à ces jours.'),
('1r',3,3,'crampon1923','Salomon aimait Yahweh, marchant selon les préceptes de David, son père; seulement il offrait des sacrifices sur les hauts lieux et y brûlait des parfums.'),
('1r',3,4,'crampon1923','Le roi se rendit à Gabaon pour y sacrifier, car c''était le grand haut lieu. Salomon offrit mille holocaustes sur cet autel.'),
('1r',3,5,'crampon1923','A Gabaon, Yahweh apparut en songe à Salomon pendant la nuit, et Dieu lui dit: « Demande ce que tu veux que je te donne. »'),
('1r',3,6,'crampon1923','Salomon répondit: « Vous avez montré une grande bienveillance envers votre serviteur David, mon père, selon qu''il marchait en votre présence dans la fidélité, dans la justice et dans la droiture de cœur envers vous; vous lui avez conservé cette grande bienveillance, et vous lui avez donné un fils qui est assis sur son trône, comme il paraît aujourd''hui.'),
('1r',3,7,'crampon1923','Maintenant, Yahweh, mon Dieu, vous avez fait régner votre serviteur à la place de David, mon père; et moi je ne suis qu''un tout jeune homme, ne sachant pas comment me conduire.'),
('1r',3,8,'crampon1923','Votre serviteur est au milieu de votre peuple que vous avez choisi, peuple immense, qui ne peut être évalué ni compté, tant il est nombreux.'),
('1r',3,9,'crampon1923','Accordez donc à votre serviteur un cœur attentif pour juger votre peuple, pour discerner le bien et le mal. Car qui pourrait juger votre peuple, ce peuple si nombreux? »'),
('1r',3,10,'crampon1923','Le Seigneur eut pour agréable que Salomon lui eût fait cette demande,'),
('1r',3,11,'crampon1923','et Dieu lui dit: « Parce que tu as fait cette demande, et que tu n''as pas demandé pour toi de longs jours, et que tu n''as pas demandé pour toi des richesses, et que tu n''as pas demandé pour toi la mort de tes ennemis, mais que tu as demandé pour toi de l''intelligence pour exercer la justice,'),
('1r',3,12,'crampon1923','voici que je fais selon ta parole: voici que je te donne un cœur sage et intelligent, de telle sorte qu''il n''y ait eu personne avant toi qui te soit semblable, et qu''il ne s''élèvera personne après toi qui te soit semblable.'),
('1r',3,13,'crampon1923','Et même ce que tu n''as pas demandé, je te le donne, richesses et gloire, au point que parmi les rois il n''y aura personne comme toi, pendant tous tes jours.'),
('1r',3,14,'crampon1923','Et si tu marches dans mes voies, en observant mes lois et mes commandements, comme a marché David, ton père, je prolongerai tes jours. »'),
('1r',3,15,'crampon1923','Salomon s''éveilla, et il comprit que c''était un songe. De retour à Jérusalem, il se tint devant l''arche de l''alliance de Yahweh; il offrit des holocaustes et des sacrifices pacifiques, et il donna un festin à tous ses serviteurs.'),
('1r',3,16,'crampon1923','Alors deux femmes de mauvaise vie vinrent vers le roi et se tinrent devant lui.'),
('1r',3,17,'crampon1923','L''une des femmes dit: « De grâce, mon seigneur! Cette femme et moi, nous demeurions dans la même maison, et j''ai mis au monde un enfant près d''elle dans la maison.'),
('1r',3,18,'crampon1923','Trois jours après que j''avais mis au monde mon enfant, cette femme a mis aussi au monde un enfant. Nous étions ensemble; aucun étranger n''était avec nous dans la maison, il n''y avait que nous deux dans la maison.'),
('1r',3,19,'crampon1923','Le fils de cette femme mourut pendant la nuit, parce qu''elle s''était couchée sur lui.'),
('1r',3,20,'crampon1923','Elle se leva au milieu de la nuit, elle prit mon fils à mes côtés tandis que la servante dormait, et elle le coucha dans son sein, et son fils qui était mort, elle le coucha dans mon sein.'),
('1r',3,21,'crampon1923','Lorsque je me suis levée le matin pour allaiter mon fils, voici qu''il était mort; mais, l''ayant considéré attentivement le matin, je m''aperçus que ce n''était pas mon fils que j''avais enfanté. »'),
('1r',3,22,'crampon1923','L''autre femme dit: « Non! C''est mon fils qui est vivant, et c''est ton fils qui est mort. » Mais la première répliqua: « Nullement, c''est ton fils qui est mort, et c''est mon fils qui est vivant. » Et elles se disputaient devant le roi.'),
('1r',3,23,'crampon1923','Le roi dit: « L''une dit: C''est mon fils qui est vivant, et c''est ton fils qui est mort; et l''autre dit: Nullement, c''est ton fils qui est mort, et c''est mon fils qui est vivant. »'),
('1r',3,24,'crampon1923','Et le roi dit: « Apportez-moi une épée. » On apporta l''épée devant le roi.'),
('1r',3,25,'crampon1923','Et le roi dit: « Partagez en deux l''enfant qui vit, et donnez-en la moitié à l''une et la moitié à l''autre. »'),
('1r',3,26,'crampon1923','Alors la femme dont le fils était vivant dit au roi, car elle sentait ses entrailles s''émouvoir pour son fils: « Ah! mon seigneur, donnez-lui l''enfant qui vit, et qu''on ne le tue pas! » Et l''autre disait: « Qu''il ne soit ni à moi ni à toi; partagez-le. »'),
('1r',3,27,'crampon1923','Et le roi répondit et dit: « Donnez à la première l''enfant qui vit, et qu''on ne le tue pas; c''est elle qui est sa mère. »'),
('1r',3,28,'crampon1923','Tout Israël apprit le jugement que le roi avait prononcé, et l''on craignit le roi, en voyant qu''il y avait en lui une sagesse divine pour rendre la justice.'),
('1r',4,1,'crampon1923','Le roi Salomon était roi sur tout Israël.'),
('1r',4,2,'crampon1923','Voici les chefs qu''il avait à son service: Azarias, fils de Sadoc, était le premier ministre;'),
('1r',4,3,'crampon1923','Elihoreph et Ahia, fils de Sisa, étaient secrétaires; Josaphat, fils d''Ahilud, était archiviste;'),
('1r',4,4,'crampon1923','Banaïas, fils de Joïadas, commandait l''armée; Sadoc et Abiathar étaient prêtres;'),
('1r',4,5,'crampon1923','Azarias, fils de Nathan, était chef des intendants; Zabud, fils de Nathan, prêtre, était conseiller intime du roi;'),
('1r',4,6,'crampon1923','Ahisar était préfet du palais; et Adoniram, fils d''Abda, était préposé aux corvées.'),
('1r',4,7,'crampon1923','Salomon avait douze intendants sur tout Israël; ils pourvoyaient à l''entretien du roi et de sa maison, chacun devant y pourvoir pendant un mois de l''année.'),
('1r',4,8,'crampon1923','Voici leurs noms: Ben-Hur, dans la montagne d''Ephraïm; —'),
('1r',4,9,'crampon1923','Ben-Décar, à Maccès, à Salebim, à Beth-Sames et à Elon de Béthanan; —'),
('1r',4,10,'crampon1923','Ben-Hésed, à Aruboth: il avait Socho et toute la contrée d''Epher; —'),
('1r',4,11,'crampon1923','Ben-Abinadab, qui avait toutes les hauteurs de Dor; Tapheth, fille de Salomon, était sa femme; —'),
('1r',4,12,'crampon1923','Bana, fils d''Ahilud, qui avait Thanac et Mageddo, et tout Bethsan, qui est près de Sarthana au-dessous de Jezraël, depuis Bethsan jusqu''à Abel-méhula, jusqu''au delà de Jecmaan. —'),
('1r',4,13,'crampon1923','Ben-Gaber, à Ramoth-de-Galaad: il avait les Bourgs de Jaïr, fils de Manassé, qui sont en Galaad; il avait la contrée d''Argob qui est en Basan, soixante grandes villes à murailles et à barres d''airain; —'),
('1r',4,14,'crampon1923','Ahinadab, fils d''Addo, à Manaïm; —'),
('1r',4,15,'crampon1923','Ahimaas, en Nephthali: lui aussi avait pris pour femme une fille de Salomon, nommée Basemath; —'),
('1r',4,16,'crampon1923','Baana, fils de Husi, en Aser et à Aloth; —'),
('1r',4,17,'crampon1923','Josaphat, fils de Pharué, en Issachar; —'),
('1r',4,18,'crampon1923','Séméï, fils d''Ela, en Benjamin; —'),
('1r',4,19,'crampon1923','Gabar, fils d''Uri, dans le pays de Galaad, pays de Séhon, roi des Amorrhéens, et de Og, roi de Basan: il y avait un seul intendant pour cette contrée.'),
('1r',4,20,'crampon1923','Juda et Israël étaient nombreux comme le sable qui est sur le bord de la mer; ils mangeaient, buvaient et se réjouissaient.'),
('1r',5,1,'crampon1923','Salomon dominait sur tous les royaumes, depuis le fleuve jusqu''au pays des Philistins et à la frontière d''Egypte; ils apportaient des présents et ils furent assujettis à Salomon tous les jours de sa vie.'),
('1r',5,2,'crampon1923','Salomon consommait chaque jour en vivres: trente cors de fleur de farine et soixante cors de farine commune,'),
('1r',5,3,'crampon1923','dix bœufs gras, vingt bœufs de pâturage et cent moutons, sans compter les cerfs, les chevreuils, les daims et les volailles engraissées.'),
('1r',5,4,'crampon1923','Car il dominait sur tout le pays au delà du fleuve, depuis Taphsa jusqu''à Gaza, sur tous les rois au delà du fleuve; et il avait la paix avec tous ses sujets de tous côtés.'),
('1r',5,5,'crampon1923','Juda et Israël habitaient en sécurité, chacun sous sa vigne et sous son figuier, depuis Dan jusqu''à Bersabée, pendant tous les jours de Salomon.'),
('1r',5,6,'crampon1923','Salomon avait quarante mille stalles pour les chevaux destinés à ses chars, et douze mille chevaux de selle.'),
('1r',5,7,'crampon1923','Les intendants pourvoyaient à l''entretien du roi Salomon et de tous ceux qui étaient admis à la table du roi Salomon, chacun pendant son mois; ils ne laissaient rien manquer.'),
('1r',5,8,'crampon1923','Ils faisaient aussi venir de l''orge et de la paille pour les chevaux de trait et de course dans le lieu où ceux-ci se trouvaient, chacun selon ce qui lui avait été prescrit.'),
('1r',5,9,'crampon1923','Dieu donna à Salomon de la sagesse, une très grande intelligence et un esprit étendu comme le sable qui est au bord de la mer.'),
('1r',5,10,'crampon1923','La sagesse de Salomon surpassait la sagesse de tous les fils de l''Orient et toute la sagesse de l''Egypte.'),
('1r',5,11,'crampon1923','Il était plus sage qu''aucun homme, plus qu''Ethan l''Ezrahite, plus qu''Héman, Chalcol et Dorda, les fils de Mahol, et sa renommée était répandue parmi toutes les nations d''alentour.'),
('1r',5,12,'crampon1923','Il prononça trois mille maximes, et ses cantiques furent au nombre de mille et cinq.'),
('1r',5,13,'crampon1923','Il disserta sur les arbres, depuis le cèdre qui est au Liban jusqu''à l''hysope qui sort de la muraille; il disserta aussi sur les quadrupèdes et sur les oiseaux, et sur les reptiles, et sur les poissons.'),
('1r',5,14,'crampon1923','On venait de tous les peuples pour entendre la sagesse de Salomon, de la part de tous les rois de la terre qui avaient entendu parler de sa sagesse.'),
('1r',5,15,'crampon1923','Hiram, roi de Tyr, envoya ses serviteurs vers Salomon, car il avait appris qu''on l''avait oint pour roi à la place de son père, et Hiram avait toujours été l''ami de David.'),
('1r',5,16,'crampon1923','Et Salomon envoya dire à Hiram:'),
('1r',5,17,'crampon1923','« Tu sais que David, mon père, n''a pu bâtir une maison au nom de Yahweh, son Dieu, à cause des guerres dont ses ennemis l''ont entouré, jusqu''à ce que Yahweh les eût mis sous la plante de ses pieds.'),
('1r',5,18,'crampon1923','Maintenant, Yahweh, mon Dieu m''a donné du repos de tous côtés; il n''y a plus d''adversaire, plus d''affaire fâcheuse.'),
('1r',5,19,'crampon1923','Et voici que je pense à bâtir une maison au nom de Yahweh, mon Dieu, comme Yahweh l''a déclaré à David, mon père, en disant: C''est ton fils, que je mettrai à ta place sur ton trône, qui bâtira la maison à mon nom.'),
('1r',5,20,'crampon1923','Et maintenant, ordonne que l''on coupe pour moi des cèdres sur le Liban. Mes serviteurs seront avec tes serviteurs, et je te donnerai pour le salaire de tes serviteurs tout ce que tu diras; car tu sais qu''il n''y a personne parmi nous qui s''entende à couper le bois comme les Sidoniens. »'),
('1r',5,21,'crampon1923','Lorsque Hiram entendit les paroles de Salomon, il eut une grande joie et il dit: « Béni soit aujourd''hui Yahweh qui a donné à David un fils sage pour régner sur ce grand peuple! »'),
('1r',5,22,'crampon1923','Et Hiram envoya dire à Salomon: « J''ai entendu ce que tu m''as envoyé dire; je ferai ce que tu désires au sujet des bois de cèdre et des bois de cyprès.'),
('1r',5,23,'crampon1923','Mes serviteurs les descendront du Liban à la mer, et je les ferai flotter par mer jusqu''au lieu que tu m''enverras dire; là, je les ferai délier, et tu les prendras. Et toi, tu accompliras mon désir, en fournissant les vivres à ma maison. »'),
('1r',5,24,'crampon1923','Hiram donnait à Salomon des bois de cèdre et des bois de cyprès autant qu''il en voulait;'),
('1r',5,25,'crampon1923','et Salomon donnait à Hiram vingt mille cors de froment pour l''entretien de sa maison, et vingt cors d''huile d''olives broyées. Voilà ce que Salomon livrait chaque année à Hiram.'),
('1r',5,26,'crampon1923','Et Yahweh donna de la sagesse à Salomon, comme il le lui avait promis; et il y eut paix entre Hiram et Salomon, et ils firent alliance ensemble.'),
('1r',5,27,'crampon1923','Le roi Salomon leva parmi tous les Israélites des hommes de corvée, et les hommes de corvée étaient au nombre de trente mille.'),
('1r',5,28,'crampon1923','Il les envoyait au Liban, dix mille par mois alternativement; ils étaient un mois au Liban, et deux mois chez eux; Adoniram était préposé sur les hommes de corvée.'),
('1r',5,29,'crampon1923','Salomon avait encore soixante-dix mille hommes qui portaient les fardeaux, et quatre-vingt mille qui taillaient les pierres dans la montagne,'),
('1r',5,30,'crampon1923','sans compter les surintendants préposés aux travaux par Salomon, au nombre de trois mille trois cents; ils dirigeaient le peuple qui travaillait aux entreprises.'),
('1r',5,31,'crampon1923','Le roi ordonna d''extraire de grandes pierres, pierres de choix, pour établir en pierres de taille les fondements de la maison.'),
('1r',5,32,'crampon1923','Les maçons de Salomon et les maçons de Hiram, et les Gibliens, taillèrent et préparèrent les bois et les pierres pour bâtir la maison.'),
('1r',6,1,'crampon1923','En la quatre cent quatre-vingtième année après la sortie des enfants d''Israël du pays d''Egypte, la quatrième année du règne de Salomon sur Israël, au mois de ziv, qui est le second mois, il bâtit la maison de Yahweh.'),
('1r',6,2,'crampon1923','La maison que le roi Salomon bâtit à Yahweh avait soixante coudées de longueur, vingt de largeur et trente coudées de hauteur.'),
('1r',6,3,'crampon1923','Le portique devant le temple de la maison avait vingt coudées de longueur dans le sens de la largeur de la maison, et dix coudées de largeur sur le devant de la maison.'),
('1r',6,4,'crampon1923','Le roi fit à la maison des fenêtres à grilles fixes.'),
('1r',6,5,'crampon1923','Il bâtit, contre la muraille de la maison, des étages autour des murs de la maison, autour du Lieu saint et du Lieu très saint, et il fit des chambres latérales tout autour.'),
('1r',6,6,'crampon1923','L''étage inférieur avait cinq coudées de largeur, celui du milieu six coudées de largeur, et me troisième sept coudées de largeur; car on avait fait en retrait les murs de la maison tout autour, en dehors, afin que les poutres n''entrassent pas dans les murs de la maison.'),
('1r',6,7,'crampon1923','Lorsqu''on bâtit la maison, on la bâtit de pierres toutes préparées dans la carrière; et ainsi ni marteau, ni hache, ni aucun instrument de fer ne furent entendus dans la maison, pendant qu''on la construisait.'),
('1r',6,8,'crampon1923','L''entrée de l''étage du milieu était du côté droit de la maison; on montait par des escaliers tournants à l''étage du milieu et de celui du milieu au troisième.'),
('1r',6,9,'crampon1923','Salomon bâtit la maison et l''acheva; il couvrit la maison de poutres et de planches de cèdre.'),
('1r',6,10,'crampon1923','Il bâtit les étages adossés à toute la maison, en leur donnant cinq coudées de hauteur, et les liant à la maison par des bois de cèdre.'),
('1r',6,11,'crampon1923','Et la parole de Yahweh fut adressée à Salomon, en ces termes:'),
('1r',6,12,'crampon1923','« Cette maison que tu bâtis..., si tu marches selon mes lois, si tu mets en pratique mes ordonnances, si tu observes tous mes commandements, réglant sur eux ta conduite, j''accomplirai à ton égard ma parole que j''ai dite à David, ton père;'),
('1r',6,13,'crampon1923','j''habiterai au milieu des enfants d''Israël, et je n''abandonnerai pas mon peuple d''Israël. »'),
('1r',6,14,'crampon1923','Et Salomon bâtit la maison et l''acheva.'),
('1r',6,15,'crampon1923','Il revêtit intérieurement les murs de la maison de planches de cèdre, depuis le sol de la maison jusqu''au plafond; il revêtit ainsi de lambris l''intérieur; et il recouvrit le sol de la maison de planches de cyprès.'),
('1r',6,16,'crampon1923','Il revêtit de planches de cèdre les vingt coudées à partir du fond de la maison, depuis le sol jusqu''au haut des murs, et il prit sur la maison de quoi lui faire un sanctuaire, le Saint des saints.'),
('1r',6,17,'crampon1923','La maison, c''est-à-dire le temple antérieur, était de quarante coudées.'),
('1r',6,18,'crampon1923','Le bois de cèdre à l''intérieur de la maison était sculpté en coloquintes et en fleurs épanouies; tout était cèdre; on ne voyait pas la pierre.'),
('1r',6,19,'crampon1923','Salomon disposa le sanctuaire à l''intérieur de la maison, au fond, pour y placer l''arche de l''alliance de Yahweh.'),
('1r',6,20,'crampon1923','L''intérieur du sanctuaire avait vingt coudées de longueur, vingt coudées de largeur et vingt coudées de hauteur. Salomon le revêtit d''or fin, et il revêtit l''autel de cèdre.'),
('1r',6,21,'crampon1923','Salomon revêtit d''or fin l''intérieur de la maison, et il ferma avec des chaînes d''or le devant du sanctuaire, qu''il couvrit d''or.'),
('1r',6,22,'crampon1923','C''est ainsi qu''il revêtit d''or toute la maison, la maison toute entière, et il revêtit d''or tout l''autel qui était devant le sanctuaire.'),
('1r',6,23,'crampon1923','Il fit dans le sanctuaire deux chérubins de bois d''olivier sauvage, ayant dix coudées de haut.'),
('1r',6,24,'crampon1923','Une des ailes de chaque chérubin avait cinq coudées, et la deuxième aile du chérubin avait cinq coudées; il y avait dix coudées de l''extrémité d''une de ses ailes à l''extrémité de l''autre.'),
('1r',6,25,'crampon1923','Le second chérubin avait aussi dix coudées. Même mesure et même forme pour les deux chérubins.'),
('1r',6,26,'crampon1923','La hauteur d''un chérubin était de dix coudées; et de même pour le deuxième chérubin.'),
('1r',6,27,'crampon1923','Salomon plaça les chérubins au milieu de la maison intérieure, les ailes déployées; l''aile du premier touchait à l''un des murs, et l''aile du second chérubin touchait à l''autre mur, et leurs autres ailes se touchaient, aile contre aile, vers le milieu de la maison.'),
('1r',6,28,'crampon1923','Et Salomon revêtit d''or les chérubins.'),
('1r',6,29,'crampon1923','Il fit sculpter en relief, sur tous les murs de la maison, tout autour, à l''intérieur comme à l''extérieur, des chérubins, des palmiers et des fleurs épanouies.'),
('1r',6,30,'crampon1923','Il revêtit d''or le sol de la maison, à l''intérieur comme à l''extérieur.'),
('1r',6,31,'crampon1923','Il fit à la porte du sanctuaire des battants de bois d''olivier sauvage; l''encadrement avec les poteaux prenait le cinquième du mur.'),
('1r',6,32,'crampon1923','Sur les deux battants en bois d''olivier sauvage, il fit sculpter des chérubins, des palmiers et des fleurs épanouies, et il les revêtit d''or, étendant l''or sur les chérubins et sur les palmiers.'),
('1r',6,33,'crampon1923','De même il fit, pour la porte du temple, des poteaux de bois d''olivier sauvage, qui prenaient le quart du mur,'),
('1r',6,34,'crampon1923','et deux battants en bois de cyprès; le premier battant était formé de deux feuillets qui se repliaient; le deuxième battant était pareillement formé de deux feuillets qui se repliaient.'),
('1r',6,35,'crampon1923','Il y sculpta des chérubins, des palmiers et des fleurs épanouies, et il les revêtit d''or, adapté à la sculpture.'),
('1r',6,36,'crampon1923','Il bâtit le parvis intérieur de trois rangées de pierres de taille et d''une rangée de poutres de cèdre.'),
('1r',6,37,'crampon1923','La quatrième année, au mois de ziv, furent posés les fondements de la maison de Yahweh;'),
('1r',6,38,'crampon1923','et la onzième année, au mois de bul, qui est le huitième mois, la maison fut achevée dans toutes ses parties et telle qu''il convenait. Salomon la construisit dans l''espace de sept ans.'),
('1r',7,1,'crampon1923','Salomon bâtit sa maison en treize ans, et il l''acheva tout entière.'),
('1r',7,2,'crampon1923','Il construisit la maison de la Forêt du Liban, dont la longueur était de cent coudées, la largeur de cinquante coudées et la hauteur de trente coudées; elle reposait sur quatre rangées de colonnes de cèdre, et il y avait des poutres de cèdre sur les colonnes.'),
('1r',7,3,'crampon1923','Un toit de cèdre la recouvrait, au-dessus des chambres qui reposaient sur les colonnes, au nombre de quarante-cinq, quinze par rangées.'),
('1r',7,4,'crampon1923','Il y avait trois rangées de chambres, et les fenêtres se faisaient face, trois fois.'),
('1r',7,5,'crampon1923','Toutes les portes et tous les poteaux étaient formés d''ais en carré, et les fenêtres se faisaient face, trois fois.'),
('1r',7,6,'crampon1923','Il fit le portique à colonnes, dont la longueur était de cinquante coudées et la largeur de trente coudées, et, en avant, un autre portique avec des colonnes et des degrés devant elles.'),
('1r',7,7,'crampon1923','Il fit le portique du trône, où il rendait la justice, le portique du jugement, et il le revêtit de cèdre depuis le sol jusqu''au plafond.'),
('1r',7,8,'crampon1923','Sa maison d''habitation fut construite de la même manière, dans une seconde cour, après le portique; et il fit une maison semblable à ce portique pour la fille de Pharaon, que Salomon avait épousée.'),
('1r',7,9,'crampon1923','Toutes ces constructions étaient en pierres de prix, taillées d''après des mesures, sciées avec la scie, à l''intérieur comme à l''extérieur, depuis les fondements jusqu''aux corniches, et en dehors jusqu''à la grande cour.'),
('1r',7,10,'crampon1923','Les fondements étaient aussi en pierres de prix, en pierres de grande dimension, en pierres de dix coudées et en pierres de huit coudées.'),
('1r',7,11,'crampon1923','Au-dessus, il y avait encore des pierres de prix, taillées d''après des mesures, et du bois de cèdre.'),
('1r',7,12,'crampon1923','La grande cour avait dans tout son circuit trois rangées de pierre de taille et une rangée de poutres de cèdre, comme le parvis intérieur de la maison de Yahweh, et comme le portique de la maison.'),
('1r',7,13,'crampon1923','Le roi Salomon envoya chercher Hiram de Tyr.'),
('1r',7,14,'crampon1923','Il était fils d''une veuve de la tribu de Nephthali, mais son père était tyrien et travaillait l''airain. Il était rempli de sagesse, d''intelligence et de savoir pour faire toutes sortes d''ouvrages d''airain; il vint auprès du roi Salomon, et il exécuta tous ses ouvrages.'),
('1r',7,15,'crampon1923','Il fabriqua les deux colonnes en airain; la hauteur d''une colonne était de dix-huit coudées et un fil de douze coudées mesurait la circonférence de la deuxième colonne.'),
('1r',7,16,'crampon1923','Il fit deux chapiteaux d''airain fondu, pour les placer sur les sommets des colonnes; la hauteur d''un chapiteau était de cinq coudées et la hauteur du deuxième chapiteau était de cinq coudées.'),
('1r',7,17,'crampon1923','Il y avait des treillis en forme de réseaux, des festons en forme de chaînettes, aux chapiteaux qui surmontaient le sommet des colonnes, sept à un chapiteau, sept au deuxième chapiteau.'),
('1r',7,18,'crampon1923','Il fit deux rangs de grenades autour de l''un des treillis, pour couvrir le chapiteau qui surmontait l''une des colonnes; et de même fit-il pour le second chapiteau.'),
('1r',7,19,'crampon1923','Les chapiteaux qui étaient sur le sommet des colonnes, dans le portique, figuraient des lis ayant quatre coudées de hauteur.'),
('1r',7,20,'crampon1923','Les chapiteaux placés sur les deux colonnes étaient entourés de deux cents grenades, en haut, près du renflement qui était au delà du treillis; il y avait aussi deux cents grenades rangées tout autour, sur le second chapiteau.'),
('1r',7,21,'crampon1923','Il dressa les colonnes au portique du temple; il dressa la colonne de droite et la nomma Jachin; puis il dressa la colonne de gauche et la nomma Booz.'),
('1r',7,22,'crampon1923','Et il y avait sur le sommet des colonnes un travail figurant des lis. Ainsi fut achevé l''ouvrage des colonnes.'),
('1r',7,23,'crampon1923','Il fit la mer d''airain fondu. Elle avait dix coudées d''un bord à l''autre, elle était entièrement ronde; sa hauteur était de cinq coudées, et un cordon de trente coudées mesurait sa circonférence.'),
('1r',7,24,'crampon1923','Des coloquintes l''entouraient, au-dessous du bord, dix par coudées, faisant tout le tour de la mer sur deux rangs; les coloquintes étaient fondues avec elle en une seule pièce.'),
('1r',7,25,'crampon1923','Elle était posée sur douze bœufs, dont trois regardaient le nord, trois regardaient l''occident, trois regardaient le midi et trois regardaient l''orient; la mer était sur eux, et toute la partie postérieure de leur corps était cachée en dedans.'),
('1r',7,26,'crampon1923','Son épaisseur était d''un palme, et son bord était semblable au bord d''une coupe, à fleur de lis. Elle contenait deux mille baths.'),
('1r',7,27,'crampon1923','Il fit les dix bases d''airain; chacune avait quatre coudées de long, quatre coudées de large et trois coudées de haut.'),
('1r',7,28,'crampon1923','Voici comment les bases étaient faites: elles étaient formées de panneaux, et les panneaux s''engageaient entre des châssis;'),
('1r',7,29,'crampon1923','sur les panneaux qui étaient entre les châssis, il y avait des lions, des taureaux et des chérubins; et sur les châssis, par en haut, un support, et au-dessous des lions, des taureaux et des chérubins pendaient des guirlandes.'),
('1r',7,30,'crampon1923','Chaque base avait quatre roues d''airain avec des essieux d''airain, et ses quatre pieds avaient des supports; ces supports fondus étaient au-dessous du bassin et au delà des guirlandes.'),
('1r',7,31,'crampon1923','L''ouverture pour recevoir le bassin était à l''intérieur du couronnement de la base, elle était haute d''une coudée; cette ouverture était ronde, de la forme d''une base de colonne et ayant une coudée et demie de diamètre; et sur cette ouverture il y avait aussi des sculptures; les panneaux étaient carrés, et non arrondis.'),
('1r',7,32,'crampon1923','Les quatre roues étaient au-dessous des panneaux; et les essieux des roues fixés à la base; chaque roue avait une coudée et demie de hauteur.'),
('1r',7,33,'crampon1923','Les roues étaient faites comme la roue d''un char; leurs essieux, leurs jantes, leurs rais et leurs moyeux, tout était fondu.'),
('1r',7,34,'crampon1923','Aux quatre angles de chaque base étaient quatre supports, et ses supports étaient d''une même pièce avec la base.'),
('1r',7,35,'crampon1923','Au sommet de la base était un cercle haut d''une demi-coudée; et sur le sommet de la base, ses appuis et ses panneaux étaient d''une même pièce.'),
('1r',7,36,'crampon1923','Sur les plaques des appuis et sur les panneaux, il grava des chérubins, des lions et des palmiers, selon l''espace libre pour chacun, et des guirlandes tout autour.'),
('1r',7,37,'crampon1923','C''est ainsi qu''il fit les dix bases; une même fonte, une même dimension, une même forme pour toutes.'),
('1r',7,38,'crampon1923','Il fit dix bassins d''airain; chaque bassin contenait quarante baths; chaque bassin avait quatre coudées de diamètre; chaque bassin reposait sur une base, une des dix bases.'),
('1r',7,39,'crampon1923','Il disposa ainsi les dix bases: cinq sur le côté droit de la maison, et cinq sur le côté gauche de la maison; et il plaça la mer au côté droit de la maison, à l''est, vers le sud.'),
('1r',7,40,'crampon1923','Hiram fit les chaudrons, les pelles et les coupes. C''est ainsi qu''Hiram acheva tout l''ouvrage qu''il fit pour le roi Salomon dans la maison de Yahweh:'),
('1r',7,41,'crampon1923','les deux colonnes; les deux bourrelets des chapiteaux qui sont sur le sommet des colonnes; les deux treillis pour couvrir les deux bourrelets des chapiteaux qui sont sur le sommet des colonnes;'),
('1r',7,42,'crampon1923','les quatre cents grenades pour les deux treillis, deux rangées de grenades par treillis, pour couvrir les deux bourrelets des chapiteaux qui sont sur les colonnes;'),
('1r',7,43,'crampon1923','les dix bases, et les dix bassins sur les bases;'),
('1r',7,44,'crampon1923','la mer, et les douze bœufs sous la mer;'),
('1r',7,45,'crampon1923','les pots, les pelles et les coupes. Tous ces ustensiles qu''Hiram fit pour le roi Salomon dans la maison de Yahweh étaient d''airain poli.'),
('1r',7,46,'crampon1923','Le roi les fit fondre dans la plaine du Jourdain, dans un sol argileux, entre Sochoth et Sarthan.'),
('1r',7,47,'crampon1923','Salomon laissa sans les peser tous ces ustensiles, parce qu''ils étaient en très grande quantité; le poids de l''airain ne fut pas vérifié.'),
('1r',7,48,'crampon1923','Salomon fit encore tous les autres ustensiles qui étaient dans la maison de Yahweh: l''autel d''or; la table d''or, sur laquelle on mettait les pains de proposition;'),
('1r',7,49,'crampon1923','les chandeliers d''or pur, cinq à droite et cinq à gauche, devant l''oracle, avec les fleurs, les lampes et les mouchettes d''or;'),
('1r',7,50,'crampon1923','les bassins, les couteaux, les coupes, les tasses et les encensoirs d''or pur, ainsi que les gonds d''or pour les portes de la maison intérieure, savoir du Saint des saints, et pour les portes de la maison, savoir du Saint.'),
('1r',7,51,'crampon1923','Ainsi fut achevé tout l''ouvrage que le roi Salomon fit dans la maison de Yahweh; et Salomon apporta ce que David, son père, avait consacré, l''argent, l''or et les vases, et il les déversa dans les trésors de la maison de Yahweh.'),
('1r',8,1,'crampon1923','Alors le roi Salomon assembla près de lui à Jérusalem les anciens d''Israël et tous les chefs des tribus, les princes des familles des enfants d''Israël, pour transporter de la cité de David, c''est-à-dire de Sion, l''arche de l''alliance de Yahweh.'),
('1r',8,2,'crampon1923','Tous les hommes d''Israël se réunirent auprès du roi Salomon, au mois d''éthanim, qui est le septième mois, pendant la fête.'),
('1r',8,3,'crampon1923','Lorsque tous les anciens d''Israël furent arrivés, les prêtres portèrent l''arche.'),
('1r',8,4,'crampon1923','Ils transportèrent l''arche de Yahweh, ainsi que la tente de réunion et tous les ustensiles sacrés qui étaient dans la tente; ce furent les prêtres et les lévites qui les transportèrent.'),
('1r',8,5,'crampon1923','Le roi Salomon et toute l''assemblée d''Israël convoquée auprès de lui se tenaient avec lui devant l''arche. Ils immolèrent des brebis et des bœufs, qui ne pouvaient être ni comptés ni nombrés à cause de leur multitude.'),
('1r',8,6,'crampon1923','Les prêtres portèrent l''arche de l''alliance de Yahweh à sa place, dans le sanctuaire de la maison, dans le Saint des saints, sous les ailes des Chérubins.'),
('1r',8,7,'crampon1923','Car les Chérubins étendaient leurs ailes sur la place de l''arche, et les Chérubins couvraient l''arche et ses barres par-dessus.'),
('1r',8,8,'crampon1923','Les barres avaient une longueur telle que leurs extrémités se voyaient du lieu saint devant le sanctuaire, mais on ne les voyait point du dehors. Elles ont été là jusqu''à ce jour.'),
('1r',8,9,'crampon1923','Il n''y avait dans l''arche que les deux tables de pierre, que Moïse y avait déposées sur le mont Horeb, lorsque Yahweh conclut une alliance avec les enfants d''Israël à leur sortie du pays d''Egypte.'),
('1r',8,10,'crampon1923','Au moment où les prêtres sortirent du lieu saint, la nuée remplit la maison de Yahweh.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('1r',8,11,'crampon1923','Les prêtres ne purent pas y rester pour faire leur service, à cause de la nuée; car la gloire de Yahweh remplissait la maison de Yahweh.'),
('1r',8,12,'crampon1923','Alors Salomon dit: « Yahweh veut habiter dans l''obscurité.'),
('1r',8,13,'crampon1923','J''ai bâti une maison qui sera votre demeure, un lieu pour que vous y résidiez à jamais. »'),
('1r',8,14,'crampon1923','Puis le roi tourna son visage et bénit toute l''assemblée d''Israël, et toute l''assemblée d''Israël était debout.'),
('1r',8,15,'crampon1923','Et il dit: « Béni soit Yahweh. Dieu d''Israël, qui a parlé par sa bouche à David, mon père, et qui a accompli par sa main ce qu''il avait déclaré en disant:'),
('1r',8,16,'crampon1923','Depuis le jour où j''ai fait sortir d''Egypte mon peuple d''Israël, je n''ai point choisi de ville, parmi toutes les tribus d''Israël, pour qu''on y bâtisse une maison où réside mon nom, mais j''ai choisi David pour qu''il règne sur mon peuple d''Israël.'),
('1r',8,17,'crampon1923','David, mon père, avait l''intention de bâtir une maison au nom de Yahweh, Dieu d''Israël;'),
('1r',8,18,'crampon1923','mais Yahweh dit à David, mon père: Puisque tu as eu l''intention de bâtir une maison à mon nom, tu as bien fait d''avoir eu cette intention.'),
('1r',8,19,'crampon1923','Seulement, ce ne sera pas toi qui bâtiras la maison; ce sera ton fils, sorti de tes entrailles, qui bâtira la maison à mon nom.'),
('1r',8,20,'crampon1923','Yahweh a accompli la parole qu''il avait prononcée: je me suis élevé à la place de David, mon père, et je me suis assis sur le trône d''Israël, comme Yahweh l''avait dit, et j''ai bâti la maison au nom de Yahweh, Dieu d''Israël.'),
('1r',8,21,'crampon1923','J''y ai établi un lieu pour l''arche où se trouve l''alliance de Yahweh, alliance qu''il a conclue avec nos pères quand il les a fait sortir du pays d''Egypte. »'),
('1r',8,22,'crampon1923','Salomon se plaça devant l''autel de Yahweh, en face de toute l''assemblée d''Israël, et, étendant ses mains vers le ciel,'),
('1r',8,23,'crampon1923','il dit: « Yahweh, Dieu d''Israël, il n''y a point de Dieu semblable à vous, ni en haut dans les cieux, ni en bas sur la terre: à vous, qui gardez l''alliance et la miséricorde envers vos serviteurs qui marchent de tout leur cœur en votre présence;'),
('1r',8,24,'crampon1923','comme vous avez gardé à votre serviteur David, mon père, ce que vous lui avez dit; ce que vous avez déclaré par votre bouche, vous l''avez accompli par votre main, comme on le voit en ce jour.'),
('1r',8,25,'crampon1923','Maintenant, Yahweh, Dieu d''Israël, observez en faveur de votre serviteur David, mon père, ce que vous lui avez dit en ces termes: “Il ne te manquera jamais devant moi un descendant qui siège sur le trône d''Israël, pourvu que tes fils prennent garde à leur voie, en marchant devant moi comme tu as marché devant moi.”'),
('1r',8,26,'crampon1923','Et maintenant, Dieu d''Israël, qu''elle s''accomplisse donc la parole que vous avez dite à votre serviteur David, mon père!'),
('1r',8,27,'crampon1923','« Mais est-il vrai que Dieu habite sur la terre? Voici que le ciel et le ciel des cieux ne peuvent vous contenir: combien moins cette maison que j''ai bâtie!'),
('1r',8,28,'crampon1923','Cependant soyez attentif, Yahweh, mon Dieu, à la prière de votre serviteur et à sa supplication, en écoutant le cri joyeux et la prière que votre serviteur prononce devant vous aujourd''hui,'),
('1r',8,29,'crampon1923','en tenant vos yeux ouverts nuit et jour sur cette maison, sur le lieu dont vous avez dit: Là sera mon nom, en écoutant la prière que votre serviteur fait en ce lieu.'),
('1r',8,30,'crampon1923','Ecoutez la supplication de votre serviteur et de votre peuple d''Israël, lorsqu''ils prieront en ce lieu; écoutez du lieu de votre demeure, du ciel, écoutez et pardonnez.'),
('1r',8,31,'crampon1923','« Si quelqu''un pèche contre son prochain et qu''on lui fasse prêter un serment, s''il vient jurer devant votre autel, dans cette maison,'),
('1r',8,32,'crampon1923','écoutez-le du ciel, agissez, et jugez vos serviteurs, condamnant le coupable et faisant retomber sa conduite sur sa tête, déclarant juste l''innocent et lui rendant selon son innocence.'),
('1r',8,33,'crampon1923','« Quand votre peuple d''Israël sera battu devant l''ennemi parce qu''il aura péché contre vous, s''ils reviennent à vous et rendent gloire à votre nom, s''ils vous adressent des prières et des supplications dans cette maison,'),
('1r',8,34,'crampon1923','écoutez-les du ciel, pardonnez le péché de votre peuple d''Israël, et ramenez-les dans le pays que vous avez donné à leurs pères.'),
('1r',8,35,'crampon1923','« Quand le ciel sera fermé et qu''il n''y aura pas de pluie parce qu''ils auront péché contre vous, s''ils prient dans ce lieu et rendent gloire à votre nom, et s''ils se détournent de leurs péchés, parce que vous les aurez affligés,'),
('1r',8,36,'crampon1923','écoutez-les du ciel, pardonnez les péchés de vos serviteurs et de votre peuple d''Israël, en leur enseignant la bonne voie dans laquelle ils doivent marcher, et faites tomber la pluie sur la terre que vous avez donnée en héritage à votre peuple.'),
('1r',8,37,'crampon1923','« Quand la famine sera dans le pays, quand il y aura la peste, quand il y aura la rouille, la nielle, la sauterelle, le hasil; quand l''ennemi assiégera votre peuple dans le pays, dans ses portes; quand il y aura fléau ou maladie quelconques,'),
('1r',8,38,'crampon1923','si un homme, si tout votre peuple d''Israël fait entendre des prières et des supplications, et que chacun, reconnaissant la plaie de son cœur, étende ses mains vers cette maison,'),
('1r',8,39,'crampon1923','écoutez-les du ciel, du lieu de votre demeure, et pardonnez; agissez et rendez à chacun selon toutes ses voies, vous qui connaissez son cœur, — car seul vous connaissez les cœurs de tous les enfants des hommes, —'),
('1r',8,40,'crampon1923','afin qu''ils vous craignent tous les jours qu''ils vivront sur la face du pays que vous avez donné à nos pères.'),
('1r',8,41,'crampon1923','« Quant à l''étranger, qui n''est pas de votre peuple d''Israël, mais qui viendra d''un pays lointain à cause de votre nom,'),
('1r',8,42,'crampon1923','— car on entendra parler de votre grand nom, de votre main forte et de votre bras étendu, — quand il viendra prier dans cette maison,'),
('1r',8,43,'crampon1923','écoutez-le du ciel, du lieu de votre demeure, et agissez selon tout ce que vous demandera l''étranger, afin que tous les peuples de la terre connaissent votre nom, pour vous craindre, comme votre peuple d''Israël, et qu''ils sachent que votre nom est appelé sur cette maison que j''ai bâtie.'),
('1r',8,44,'crampon1923','« Quand votre peuple sortira pour combattre son ennemi, en suivant la voie dans laquelle vous les aurez envoyés, et qu''ils adresseront des prières à Yahweh, le visage tourné vers la ville que vous avez choisie et vers la maison que j''ai bâtie à votre nom,'),
('1r',8,45,'crampon1923','écoutez du ciel leur prière et leur supplication, et rendez-leur justice.'),
('1r',8,46,'crampon1923','« Quand ils pécheront contre vous, — car il n''y a pas d''homme qui ne pèche, — et quand, irrité contre eux, vous les livrerez à l''ennemi, et que leur vainqueur les emmènera captifs au pays de l''ennemi, lointain ou rapproché,'),
('1r',8,47,'crampon1923','s''ils rentrent en eux-mêmes dans le pays de leurs vainqueurs, s''ils se convertissent et vous adressent des supplications dans le pays de leurs tyrans, en disant: Nous avons péché, nous avons fait l''iniquité, nous avons commis le crime;'),
('1r',8,48,'crampon1923','s''ils reviennent à vous de tout leur cœur et de toute leur âme, dans le pays de leurs ennemis qui les ont emmenés captifs, s''ils vous adressent des prières, le visage tourné vers leur pays que vous avez donné à leurs pères, vers la ville que vous avez choisie et vers la maison que j''ai bâtie à votre nom,'),
('1r',8,49,'crampon1923','écoutez, du ciel, du lieu de votre demeure, leur prière et leur supplication, et faites-leur droit;'),
('1r',8,50,'crampon1923','pardonnez à votre peuple ses transgressions et tous ses péchés qu''il a commis contre vous; faites-en un sujet de compassion devant leurs tyrans, afin qu''ils aient pitié d''eux;'),
('1r',8,51,'crampon1923','car ils sont votre peuple et votre héritage, que vous avez fait sortir d''Egypte, du milieu d''une fournaise de fer:'),
('1r',8,52,'crampon1923','afin que vos yeux soient ouverts à la supplication de votre serviteur et à la supplication de votre peuple d''Israël, pour les écouter en tout ce qu''ils vous demanderont.'),
('1r',8,53,'crampon1923','Car vous les avez séparés de tous les peuples de la terre pour vous, pour en faire votre héritage, comme vous l''avez déclaré par Moïse, votre serviteur, quand vous avez fait sortir nos pères d''Egypte, ô Seigneur Yahweh. »'),
('1r',8,54,'crampon1923','Lorsque Salomon eut achevé d''adresser à Yahweh toute cette prière et cette supplication, il se leva de devant l''autel de Yahweh, où il était à genoux, les mains étendues vers le ciel.'),
('1r',8,55,'crampon1923','S''étant levé, il bénit toute l''assemblée d''Israël à haute voix en disant:'),
('1r',8,56,'crampon1923','« Béni soit Yahweh qui a donné du repos à son peuple d''Israël, selon tout ce qu''il a dit! De toutes les bonnes paroles qu''il a fait entendre par l''organe de Moïse, son serviteur, aucune parole n''est restée sans effet.'),
('1r',8,57,'crampon1923','Que Yahweh, notre Dieu, soit avec nous, comme il a été avec nos pères; qu''il ne nous abandonne point et ne nous délaisse point,'),
('1r',8,58,'crampon1923','mais qu''il incline nos cœurs vers lui, afin que nous marchions dans toutes ses voies, et que nous observions ses commandements, ses lois et ses ordonnances, qu''il a prescrits à nos pères.'),
('1r',8,59,'crampon1923','Que mes paroles de supplication que j''ai prononcées devant Yahweh soient proches de Yahweh, notre Dieu, nuit et jour, pour que, selon le besoin de chaque jour, il fasse droit à son serviteur et à son peuple d''Israël,'),
('1r',8,60,'crampon1923','afin que tous les peuples de la terre sachent que Yahweh est Dieu, qu''il n''y en a point d''autre.'),
('1r',8,61,'crampon1923','Que votre cœur soit tout à Yahweh, notre Dieu, pour marcher selon ses lois et pour observer ses commandements, comme nous le faisons aujourd''hui. »'),
('1r',8,62,'crampon1923','Le roi et tout Israël avec lui offrirent des sacrifices devant Yahweh.'),
('1r',8,63,'crampon1923','Salomon immola vingt-deux mille bœufs et cent vingt mille brebis pour le sacrifice pacifique qu''il offrit à Yahweh. C''est ainsi que le roi et tous les enfants d''Israël firent la dédicace de la maison de Yahweh.'),
('1r',8,64,'crampon1923','En ce jour, le roi consacra le milieu du parvis qui est devant la maison de Yahweh; car il offrit là les holocaustes, les oblations et les graisses des sacrifices pacifiques, parce que l''autel d''airain qui est devant Yahweh était trop petit pour contenir les holocaustes, les oblations et les graisses des sacrifices pacifiques.'),
('1r',8,65,'crampon1923','Salomon célébra la fête en ce temps-là, et tout Israël avec lui, grande multitude venue depuis l''entrée d''Emath jusqu''au torrent d''Egypte, — devant Yahweh, notre Dieu, — pendant sept jours et sept autres jours, soit quatorze jours.'),
('1r',8,66,'crampon1923','Le huitième jour il renvoya le peuple. Et ils bénirent le roi, et s''en allèrent dans leurs demeures, joyeux et le cœur content pour tout le bien que Yahweh avait fait à David, son serviteur, et à Israël, son peuple.'),
('1r',9,1,'crampon1923','Lorsque Salomon eut achevé de bâtir la maison de Yahweh et la maison du roi, et tout ce qui plaisait à Salomon, ce qu''il désirait faire,'),
('1r',9,2,'crampon1923','Yahweh lui apparut une seconde fois, comme il lui était apparu à Gabaon.'),
('1r',9,3,'crampon1923','Et Yahweh lui dit: « J''ai exaucé ta prière et ta supplication que tu as proférée devant moi; j''ai sanctifié cette maison que tu as bâtie, pour y mettre à jamais mon nom, et là seront à jamais mes yeux et mon cœur.'),
('1r',9,4,'crampon1923','Et toi, si tu marches devant moi comme a marché David, ton père, dans la sincérité de ton cœur et avec droiture, mettant en pratique ce que je t''ai prescrit, si tu observes mes lois et mes ordonnances,'),
('1r',9,5,'crampon1923','j''affermirai pour toujours le trône de ta royauté en Israël, comme je l''ai déclaré à David, ton père, en disant: Il ne te manquera jamais un descendant qui siège sur le trône d''Israël.'),
('1r',9,6,'crampon1923','Mais si vous vous détournez de moi, vous et vos fils; si vous n''observez pas mes commandements et mes lois, que j''ai mis devant vous, et si vous allez servir d''autres dieux et vous prosterner devant eux,'),
('1r',9,7,'crampon1923','j''exterminerai Israël du pays que je lui ai donné; la maison que j''ai consacrée à mon nom, je la rejetterai de devant moi, et Israël sera un sujet de sarcasme et de raillerie parmi tous les peuples;'),
('1r',9,8,'crampon1923','cette maison sera toujours haut placée, mais quiconque passera près d''elle sera dans la stupeur et sifflera. On dira: Pourquoi Yahweh a-t-il traité ainsi ce pays et cette maison?'),
('1r',9,9,'crampon1923','Et l''on répondra: Parce qu''ils ont abandonné Yahweh, leur Dieu, qui a fait sortir leurs pères du pays d''Egypte, et que s''attachant à d''autres dieux, ils se sont prosternés devant eux et les ont servis: voilà pourquoi Yahweh a fait venir sur eux tous ces maux. »'),
('1r',9,10,'crampon1923','Au bout de vingt ans, quand Salomon eût bâti les deux maisons, la maison de Yahweh et la maison du roi,'),
('1r',9,11,'crampon1923','— Hiram, roi de Tyr, avait fourni à Salomon des bois de cèdre et des bois de cyprès, et de l''or, autant qu''il en voulait, — le roi Salomon donna à Hiram vingt villes dans le pays de Galilée.'),
('1r',9,12,'crampon1923','Hiram sortit de Tyr pour voir les villes que lui donnait Salomon; elles ne lui plurent pas,'),
('1r',9,13,'crampon1923','et il dit: « Quelles sont ces villes que tu m''as données là, mon frère? » Et il les appela pays de Chaboul, leur nom jusqu''à ce jour.'),
('1r',9,14,'crampon1923','Hiram avait envoyé à Salomon cent vingt talents d''or.'),
('1r',9,15,'crampon1923','Voici ce qui concerne les hommes de corvée que leva le roi Salomon pour bâtir la maison de Yahweh et sa propre maison, Mello et le mur de Jérusalem, Héser, Mageddo et Gazer.'),
('1r',9,16,'crampon1923','Pharaon, roi d''Egypte, était monté et s''était emparé de Gazer. Après l''avoir incendiée et avoir tué les Chananéens qui habitaient dans la ville, il l''avait donnée en dot à sa fille, femme de Salomon.'),
('1r',9,17,'crampon1923','Salomon bâtit Gazer, Beth-Horon le bas,'),
('1r',9,18,'crampon1923','Baalath, et Thadmor dans le pays du désert;'),
('1r',9,19,'crampon1923','toutes les villes servant de magasins qui appartenaient à Salomon, les villes pour les chars, les villes pour la cavalerie, et tout ce qu''il plut à Salomon de bâtir à Jérusalem, au Liban et dans tout le pays soumis à sa domination.'),
('1r',9,20,'crampon1923','Tout le peuple qui était resté des Amorrhéens, des Héthéens, des Phérézéens, des Hévéens et des Jébuséens, ne faisant point partie des enfants d''Israël,'),
('1r',9,21,'crampon1923','savoir, leurs descendants qui étaient restés après eux dans le pays, et que les enfants d''Israël n''avaient pu vouer à l''anathème, Salomon les leva comme esclaves de corvée, ce qu''ils ont été jusqu''à ce jour.'),
('1r',9,22,'crampon1923','Mais Salomon ne fit esclave aucun des enfants d''Israël; car ils étaient des hommes de guerre, ses serviteurs, ses chefs, ses officiers, les commandants de ses chars et de sa cavalerie.'),
('1r',9,23,'crampon1923','Les chefs des inspecteurs des travaux de Salomon étaient au nombre de cinq cent cinquante, chargés de commander au peuple occupé aux travaux.'),
('1r',9,24,'crampon1923','La fille de Pharaon monta de la cité de David dans sa maison que Salomon lui avait bâtie; ce fut alors qu''il bâtit Mello.'),
('1r',9,25,'crampon1923','Salomon offrait trois fois chaque année des holocaustes et des sacrifices pacifiques sur l''autel qu''il avait bâti à Yahweh, et il brûlait des parfums sur celui qui était devant Yahweh. C''est ainsi qu''il acheva de bâtir la maison.'),
('1r',9,26,'crampon1923','Le roi Salomon construisit une flotte à Asiongaber, qui est près d''Ailath, sur les bords de la mer Rouge, dans le pays d''Edom.'),
('1r',9,27,'crampon1923','Et Hiram envoya sur les vaisseaux, auprès des serviteurs de Salomon, ses propres serviteurs, des matelots connaissant la mer.'),
('1r',9,28,'crampon1923','Ils allèrent à Ophir, et ils y prirent quatre cent vingt talents d''or, qu''ils apportèrent au roi Salomon.'),
('1r',10,1,'crampon1923','La reine de Saba, ayant appris la renommée de Salomon, au nom de Yahweh, vint pour l''éprouver par des énigmes.'),
('1r',10,2,'crampon1923','Elle vint à Jérusalem avec un équipage très considérable, des chameaux portant des aromates, de l''or en très grande quantité, et des pierres précieuses. Elle se rendit auprès de Salomon, et elle lui dit tout ce qu''elle avait dans le cœur.'),
('1r',10,3,'crampon1923','Salomon répondit à toutes ses questions: il n''y eut rien qui restât caché au roi, sans qu''il pût répondre.'),
('1r',10,4,'crampon1923','Quand la reine de Saba eut vu toute la sagesse de Salomon, et la maison qu''il avait bâtie,'),
('1r',10,5,'crampon1923','et les mets de sa table, et les appartements de ses serviteurs, et les chambres et les vêtements de ses domestiques, ses échansons, et l''escalier par où il montait dans la maison de Yahweh, elle fut hors d''elle-même,'),
('1r',10,6,'crampon1923','et elle dit au roi: « C''était donc vrai ce que j''ai appris dans mon pays de ce qui te concerne et de ta sagesse!'),
('1r',10,7,'crampon1923','Je n''en croyais pas le récit avant d''être venue et d''avoir vu de mes yeux, et voici qu''on ne m''en avait pas dit la moitié! Tu surpasses en sagesse et en magnificence ce que la renommée m''avait fait connaître.'),
('1r',10,8,'crampon1923','Heureux tes gens, heureux tes serviteurs, qui sont continuellement devant toi, qui entendent ta sagesse!'),
('1r',10,9,'crampon1923','Béni soit Yahweh, ton Dieu, qui s''est complu en toi et t''a placé sur le trône d''Israël! C''est parce que Yahweh aime à jamais Israël, qu''il t''a établi roi pour que tu fasses droit et justice. »'),
('1r',10,10,'crampon1923','Elle donna au roi cent vingt talents d''or, une grande quantité d''aromates et des pierres précieuses. Il ne vint plus jamais autant d''aromates que la reine de Saba en donna au roi Salomon.'),
('1r',10,11,'crampon1923','Les vaisseaux de Hiram, qui apportaient de l''or d''Ophir, amenèrent aussi d''Ophir une très grande quantité de bois de santal et des pierres précieuses.'),
('1r',10,12,'crampon1923','Le roi fit avec le bois de santal des balustrades pour la maison de Yahweh et pour la maison du roi, et des harpes et des lyres pour les chantres. Il ne vint plus de ce bois de santal, et on n''en a plus vu jusqu''à ce jour.'),
('1r',10,13,'crampon1923','Le roi Salomon donna à la reine de Saba tout ce qu''elle désira, ce qu''elle demanda, sans parler des présents, en rapport avec la puissance d''un roi tel que Salomon. Puis elle s''en retourna et alla dans son pays, elle et ses serviteurs.'),
('1r',10,14,'crampon1923','Le poids de l''or qui arrivait à Salomon en une année était de six cent soixante-six talents d''or,'),
('1r',10,15,'crampon1923','outre ce qu''il recevait des marchands ambulants et du trafic des négociants, de tous les rois d''Arabie et des gouverneurs du pays.'),
('1r',10,16,'crampon1923','Le roi Salomon fit deux cents grands boucliers d''or battu, employant six cents sicles d''or pour chaque bouclier,'),
('1r',10,17,'crampon1923','et trois cents petits boucliers d''or battu, employant trois mines d''or pour chaque bouclier; et le roi les mit dans la maison de la forêt du Liban.'),
('1r',10,18,'crampon1923','Le roi fit un grand trône d''ivoire et le revêtit d''or pur.'),
('1r',10,19,'crampon1923','Ce trône avait six degrés, et la partie supérieure du trône était arrondie par derrière; il y avait des bras de chaque côté du siège; deux lions se tenaient près des bras,'),
('1r',10,20,'crampon1923','et douze lions se tenaient là, sur les six degrés, six de chaque côté. Il ne s''est rien fait de pareil dans aucun royaume.'),
('1r',10,21,'crampon1923','Tous les vases à boire du roi Salomon étaient d''or, et toute la vaisselle de la maison de la forêt du Liban était d''or fin. Rien n''était d''argent; on n''en faisait nul cas du temps de Salomon.'),
('1r',10,22,'crampon1923','Car le roi avait en mer des vaisseaux de Tharsis avec les vaisseaux de Hiram; une fois tous les trois ans, les vaisseaux de Tharsis arrivaient, apportant de l''or et de l''argent, de l''ivoire, des singes et des paons.'),
('1r',10,23,'crampon1923','Le roi Salomon fut plus grand que tous les rois de la terre par les richesses et par la sagesse.'),
('1r',10,24,'crampon1923','Tout le monde cherchait à voir Salomon, pour entendre la sagesse que Dieu avait mise dans son cœur.'),
('1r',10,25,'crampon1923','Et chacun apportait son présent, des objets d''argent et des objets d''or, des vêtements, des armes, des aromates, des chevaux et des mulets, chaque année.'),
('1r',10,26,'crampon1923','Salomon rassembla des chars et de la cavalerie; il avait quatorze cents chars et douze mille cavaliers, qu''il plaça dans les villes où étaient déposés ses chars, et près du roi à Jérusalem.'),
('1r',10,27,'crampon1923','Le roi fit que l''argent était à Jérusalem aussi commun que les pierres, et il fit que les cèdres étaient aussi nombreux que les sycomores qui croissent dans la plaine.'),
('1r',10,28,'crampon1923','C''était de l''Egypte que provenaient les chevaux de Salomon; une caravane de marchands du roi les allait prendre par troupes à un prix convenu:'),
('1r',10,29,'crampon1923','un char montait et sortait d''Egypte pour six cents sicles d''argent, et un cheval pour cent cinquante sicles. Ils en faisaient aussi sortir de la même manière, par eux-mêmes, pour tous les rois des Héthéens et pour les rois de Syrie.'),
('1r',11,1,'crampon1923','Le roi Salomon aima beaucoup de femmes étrangères, outre la fille de Pharaon: des Moabites, des Ammonites, des Edomites, des Sidoniennes, des Héthéennes,'),
('1r',11,2,'crampon1923','d''entre les nations dont le Seigneur avait dit aux enfants d''Israël: « Vous n''aurez point de commerce avec elles, et elles n''en auront point avec vous; autrement elles tourneraient vos cœurs du côté de leurs dieux. » Salomon s''attacha à ces nations par amour.'),
('1r',11,3,'crampon1923','Il eut sept cents femmes princesses et trois cents concubines; et ses femmes détournèrent son cœur.'),
('1r',11,4,'crampon1923','Au temps de la vieillesse de Salomon, ses femmes inclinèrent son cœur vers d''autres dieux, et son cœur ne fut pas tout entier à Yahweh, son Dieu, comme l''avait été le cœur de David, son père.'),
('1r',11,5,'crampon1923','Salomon alla après Astarté, déesse des Sidoniens, et après Melchom, l''abomination des Ammonites.'),
('1r',11,6,'crampon1923','Et Salomon fit ce qui est mal aux yeux de Yahweh, et il ne suivit pas pleinement Yahweh, comme avait fait David, son père.'),
('1r',11,7,'crampon1923','Alors Salomon bâtit, sur la montagne qui est en face de Jérusalem, un haut lieu pour Chamos, l''abomination de Moab, et pour Moloch, l''abomination des fils d''Ammon.'),
('1r',11,8,'crampon1923','Il fit de même pour toutes ses femmes étrangères, qui brûlaient des parfums et offraient des sacrifices à leurs dieux.'),
('1r',11,9,'crampon1923','Yahweh fut irrité contre Salomon, parce qu''il avait détourné son cœur de Yahweh, Dieu d''Israël, qui lui était apparu deux fois,'),
('1r',11,10,'crampon1923','et lui avait, à ce sujet défendu d''aller après d''autres dieux; mais Salomon n''observa pas ce que Yahweh avait ordonné.'),
('1r',11,11,'crampon1923','Et Yahweh dit à Salomon: « Parce que tu t''es conduit de la sorte, et que tu n''as pas observé mon alliance et mes lois que je t''avais prescrites, j''arracherai sûrement de ta main le royaume, et je le donnerai à ton serviteur.'),
('1r',11,12,'crampon1923','Seulement je ne le ferai point pendant ta vie, à cause de David, ton père; c''est de la main de ton fils que je l''arracherai.'),
('1r',11,13,'crampon1923','Et encore n''arracherai-je pas tout le royaume: je laisserai une tribu à ton fils, à cause de David, mon serviteur, et à cause de Jérusalem, que j''ai choisie. »'),
('1r',11,14,'crampon1923','Yahweh suscita un ennemi à Salomon: Adad, l''Edomite, de la race royale d''Edom.'),
('1r',11,15,'crampon1923','Dans le temps où David était en guerre avec Edom, où Joab, chef de l''armée, étant monté pour enterrer les morts, tua tous les mâles qui étaient en Edom,'),
('1r',11,16,'crampon1923','— Joab y resta six mois avec tout Israël, jusqu''à ce qu''il eût exterminé tous les mâles en Edom; —'),
('1r',11,17,'crampon1923','Adad prit la fuite avec des Edomites, d''entre les serviteurs de son père, pour se rendre en Egypte; Adad était encore un jeune garçon.'),
('1r',11,18,'crampon1923','Etant partis de Madian, ils allèrent à Pharan, prirent avec eux des hommes de Pharan, et arrivèrent en Egypte auprès de Pharaon, roi d''Egypte, qui donna une maison à Adad, pourvut à sa subsistance et lui accorda des terres.'),
('1r',11,19,'crampon1923','Adad trouva grâce aux yeux de Pharaon, jusque là que Pharaon lui donna pour femme la sœur de sa femme, la sœur de la reine Taphnès.'),
('1r',11,20,'crampon1923','La sœur de Taphnès lui enfanta un fils, Genubath, que Taphnès sevra dans la maison de Pharaon, et Genubath habita dans la maison de Pharaon au milieu des enfants de Pharaon.'),
('1r',11,21,'crampon1923','Adad ayant appris en Egypte que David était couché avec ses pères, et que Joab, chef de l''armée était mort, il dit à Pharaon: « Laisse-moi aller dans mon pays. »'),
('1r',11,22,'crampon1923','Et Pharaon lui dit: « Que te manque-t-il auprès de moi, pour que tu désires aller dans ton pays? » Il répondit: « Rien, mais laisse-moi partir. »'),
('1r',11,23,'crampon1923','Dieu suscita un autre ennemi à Salomon: Razon, fils d''Eliada, qui s''était enfui de chez son maître Hadarézer, roi de Soba.'),
('1r',11,24,'crampon1923','Il avait rassemblé des gens auprès de lui, et il était chef d''une bande, lorsque David massacra les troupes de son maître. Ils allèrent à Damas, et s''y établirent; et ils régnèrent à Damas.'),
('1r',11,25,'crampon1923','Il fut un ennemi d''Israël pendant toute la vie de Salomon, outre le mal que lui faisait Adad, et il avait Israël en aversion. Il régna sur la Syrie.'),
('1r',11,26,'crampon1923','Jéroboam leva aussi la main contre le roi; il était fils de Nabat, Ephratéen de Saréda, il avait pour mère une veuve nommée Sarva, et il était serviteur de Salomon.'),
('1r',11,27,'crampon1923','Voici la cause de sa rébellion contre le roi. Salomon bâtissait Mello, et fermait la brèche de la cité de David, son père.'),
('1r',11,28,'crampon1923','Ce Jéroboam était fort et vaillant; Salomon, ayant vu comment ce jeune homme était actif au travail, l''institua surveillant de tous les gens de corvée de la maison de Joseph.'),
('1r',11,29,'crampon1923','Dans ce temps-là, Jéroboam, étant sorti de Jérusalem, fut rencontré en chemin par le prophète Ahias de Silo, revêtu d''un manteau neuf; ils étaient tous deux seuls dans les champs.'),
('1r',11,30,'crampon1923','Ahias, saisissant le manteau neuf qu''il avait sur lui, le déchira en douze morceaux,'),
('1r',11,31,'crampon1923','et il dit à Jéroboam: « Prends pour toi dix morceaux. Car ainsi parle Yahweh, le Dieu d''Israël: Voici que je vais arracher le royaume de la main de Salomon, et je te donnerai dix tribus.'),
('1r',11,32,'crampon1923','Une seule tribu lui restera, à cause de mon serviteur David et à cause de Jérusalem, la ville que j''ai choisie dans toutes les tribus d''Israël:'),
('1r',11,33,'crampon1923','et cela, parce qu''ils m''ont abandonné et se sont prosternés devant Astarté, déesse des Sidoniens, devant Chamos, dieu de Moab, et devant Melchom, dieu des fils d''Ammon, et parce qu''ils n''ont pas marché dans mes voies pour faire ce qui est droit à mes yeux et pour observer mes lois et mes ordonnances, comme l''a fait David, père de Salomon.'),
('1r',11,34,'crampon1923','Néanmoins je n''ôterai de sa main aucune partie du royaume, mais je le maintiendrai prince tout le temps de sa vie, à cause de David, mon serviteur, que j''ai choisi et qui a observé mes commandements et mes lois.'),
('1r',11,35,'crampon1923','C''est de la main de son fils que j''ôterai le royaume, et je t''en donnerai dix tribus.'),
('1r',11,36,'crampon1923','Je donnerai une tribu à son fils, afin que David, mon serviteur, ait toujours une lampe devant moi à Jérusalem, la ville que j''ai choisie pour y mettre mon nom.'),
('1r',11,37,'crampon1923','Je te prendrai, et tu régneras sur tout ce que ton âme désire, et tu seras roi sur Israël.'),
('1r',11,38,'crampon1923','Si tu obéis à tout ce que je te commanderai, si tu marches dans mes voies et si tu fais ce qui est droit à mes yeux, en observant mes lois et mes commandements, comme l''a fait David, mon serviteur, je serai avec toi, je te bâtirai une maison stable, comme j''en ai bâti une à David, et je te donnerai Israël.'),
('1r',11,39,'crampon1923','Car j''humilierai la postérité de David à cause de son infidélité, mais non pour toujours. »'),
('1r',11,40,'crampon1923','Salomon chercha à faire mourir Jéroboam; mais Jéroboam se leva et s''enfuit en Egypte, auprès de Sésac, roi d''Egypte; il fut en Egypte jusqu''à la mort de Salomon.'),
('1r',11,41,'crampon1923','Le reste des actions de Salomon, tout ce qu''il a fait, et sa sagesse, cela n''est-il pas écrit dans le livre des actes de Salomon?'),
('1r',11,42,'crampon1923','Le temps que Salomon régna à Jérusalem, sur tout Israël, fut de quarante ans.'),
('1r',11,43,'crampon1923','Et Salomon se coucha avec ses pères, et il fut enterré dans la ville de David, son père. Roboam, son fils, régna à sa place. DEUXIÈME PARTIE. LE SCHISME. LES DEUX ROYAUMES JUSQU''AUX RÈGNES DE JORAM DE JUDA ET D''OCHOZIAS D''ISRAËL.'),
('1r',12,1,'crampon1923','Roboam se rendit à Sichem, car tout Israël était venu à Sichem pour le faire roi.'),
('1r',12,2,'crampon1923','Jéroboam, fils de Nabat, ayant appris ce qui se passait, — il était encore en Egypte où il s''était enfui loin du roi Salomon, et Jéroboam demeurait en Egypte, —'),
('1r',12,3,'crampon1923','on l''envoya chercher. Alors Jéroboam et toute l''assemblée d''Israël vinrent et parlèrent à Roboam en ces termes:'),
('1r',12,4,'crampon1923','« Ton père a rendu notre joug dur; toi maintenant, allège la dure servitude que nous a imposée ton père, et le joug pesant qu''il a mis sur nous; et nous te servirons. »'),
('1r',12,5,'crampon1923','Il leur dit: « Allez vous-en pour trois jours, et revenez vers moi. » Et le peuple s''en alla.'),
('1r',12,6,'crampon1923','Le roi Roboam consulta les vieillards qui s''étaient tenus auprès de Salomon, son père, pendant sa vie, en disant: « Que me conseillez-vous de répondre à ce peuple? »'),
('1r',12,7,'crampon1923','Ils lui parlèrent en disant: « Si aujourd''hui tu es serviable à ce peuple, si tu leur viens en aide, si tu leur réponds et si tu leur dis des paroles bienveillantes, ils seront pour toujours tes serviteurs. »'),
('1r',12,8,'crampon1923','Mais Roboam laissa le conseil que lui donnaient les vieillards, et il consulta les jeunes gens qui avaient grandi avec lui et qui se tenaient devant lui.'),
('1r',12,9,'crampon1923','Il leur dit: « Que me conseillez-vous de répondre à ce peuple qui me tient ce langage: Allège le joug que nous a imposé ton père? »'),
('1r',12,10,'crampon1923','Les jeunes gens qui avaient grandi avec lui répondirent en disant: « Tu parleras ainsi à ce peuple qui t''a tenu ce langage: Ton père a rendu notre joug pesant; toi allège-le-nous! Tu leur parleras ainsi: Mon petit doigt est plus gros que les reins de mon père.'),
('1r',12,11,'crampon1923','Eh bien! Mon père vous a chargés d''un joug pesant, et moi je rendrai votre joug plus pesant encore; mon père vous a châtiés avec des fouets, et moi je vous châtierai avec des scorpions. »'),
('1r',12,12,'crampon1923','Jéroboam et tout le peuple vinrent auprès de Roboam le troisième jour, selon que le roi avait dit: « Revenez vers moi dans trois jours. »'),
('1r',12,13,'crampon1923','Le roi répondit durement au peuple. Laissant le conseil que les vieillards lui avaient donné,'),
('1r',12,14,'crampon1923','il leur parla selon le conseil des jeunes gens, en ces termes: « Mon père a rendu votre joug pesant, et moi je rendrai votre joug plus pesant encore; mon père vous a châtiés avec des fouets, et moi je vous châtierai avec des scorpions. »'),
('1r',12,15,'crampon1923','Le roi n''écouta donc pas le peuple, car tel était le procédé de Yahweh pour l''accomplissement de la parole que Yahweh avait dite par Ahias de Silo à Jéroboam, fils de Nabat.'),
('1r',12,16,'crampon1923','Lorsque tout Israël vit que le roi ne l''écoutait pas, le peuple répondit au roi en ces termes: « Quelle part avons-nous avec David? Nous n''avons point d''héritage avec le fils d''Isaï! A tes tentes, Israël! Quant à toi, pourvois à ta maison, David! » Et Israël s''en alla dans ses tentes.'),
('1r',12,17,'crampon1923','Ce fut seulement sur les enfants d''Israël qui habitaient les villes de Juda que régna Roboam.'),
('1r',12,18,'crampon1923','Alors le roi Roboam envoya Aduram, qui était préposé aux impôts; mais Aduram fut lapidé par tout Israël, et il mourut. Et le roi Roboam se hâta de monter sur un char, pour s''enfuir à Jérusalem.'),
('1r',12,19,'crampon1923','C''est ainsi qu''Israël se détacha de la maison de David jusqu''à ce jour.'),
('1r',12,20,'crampon1923','Tout Israël ayant appris que Jéroboam était revenu d''Egypte, ils l''envoyèrent appeler dans l''assemblée, et ils le firent roi sur tout Israël. Il n''y eut personne qui suivit la maison de David, si ce n''est la seule tribu de Juda.'),
('1r',12,21,'crampon1923','De retour à Jérusalem, Roboam rassembla toute la maison de Juda et la tribu de Benjamin, cent quatre-vingt mille guerriers d''élite, pour qu''ils combattissent contre la maison d''Israël, afin de ramener le royaume à Roboam, fils de Salomon.'),
('1r',12,22,'crampon1923','Mais la parole de Dieu fut adressée à Sémaïas, homme de Dieu, en ces termes:'),
('1r',12,23,'crampon1923','« Parle à Roboam, fils de Salomon, roi de Juda, et à toute la maison de Juda et de Benjamin, et au reste du peuple, en disant:'),
('1r',12,24,'crampon1923','Ainsi dit Yahweh: Ne montez pas et ne faites pas la guerre à vos frères, les enfants d''Israël. Retournez chacun dans votre maison, car c''est par moi que cette chose est arrivée. » Ils écoutèrent la parole de Yahweh, et ils s''en retournèrent, se conformant à la parole de Yahweh.'),
('1r',12,25,'crampon1923','Jéroboam bâtit Sichem sur la montagne d''Ephraïm, et il y demeura; il en sortit ensuite, et bâtit Phanuel.'),
('1r',12,26,'crampon1923','Et Jéroboam dit dans son cœur: « Maintenant le royaume pourrait bien retourner à la maison de David.'),
('1r',12,27,'crampon1923','Si ce peuple monte pour faire des sacrifices dans la maison de Yahweh, à Jérusalem, le cœur de ce peuple retournera à son seigneur, à Roboam, roi de Juda, ils me tueront et retourneront à Roboam, roi de Juda. »'),
('1r',12,28,'crampon1923','Après s''être consulté, le roi fit deux veaux d''or, et il dit au peuple: « Assez longtemps vous êtes montés à Jérusalem! Israël, voici ton Dieu, qui t''a fait monter du pays d''Egypte. »'),
('1r',12,29,'crampon1923','Il plaça l''un de ces veaux à Béthel, et il mit l''autre à Dan.'),
('1r',12,30,'crampon1923','Ce fut là une occasion de péché, car le peuple allait jusqu''à Dan adorer l''un des veaux.'),
('1r',12,31,'crampon1923','Jéroboam fit une maison de hauts lieux, et il fit des prêtres pris parmi le peuple, qui n''étaient pas des enfants de Lévi.'),
('1r',12,32,'crampon1923','Jéroboam institua une fête au huitième mois, le quinzième jour du mois, à l''imitation de la fête qui se célébrait en Juda, et il offrit des sacrifices sur l''autel. C''est ainsi qu''il fit à Béthel, afin que l''on sacrifiât aux veaux qu''il avait faits. Il établit à Béthel les prêtres des hauts lieux qu''il avait élevés.'),
('1r',12,33,'crampon1923','Il monta sur l''autel qu''il avait fait à Béthel, le quinzième jour du huitième mois, le mois qu''il avait choisi de lui-même. Il institua une fête pour les enfants d''Israël, et il monta sur l''autel pour mettre le feu aux victimes.'),
('1r',13,1,'crampon1923','Voici qu''un homme de Dieu arriva, dans la parole de Yahweh, de Juda à Béthel, pendant que Jéroboam se tenait à l''autel pour mettre le feu aux victimes.'),
('1r',13,2,'crampon1923','Il cria contre l''autel, dans la parole de Yahweh, et il dit: « Autel! Autel! Ainsi parle Yahweh: Il naîtra un fils à la maison de David; son nom sera Josias; il immolera sur toi les prêtres des hauts lieux qui mettent sur toi le feu aux victimes, et l''on brûlera sur toi des ossements d''hommes! »'),
('1r',13,3,'crampon1923','Et le même jour il donna un signe, en disant: « Tel est le signe que Yahweh a parlé: voici que l''autel se fendra, et la cendre qui est dessus sera répandue. »'),
('1r',13,4,'crampon1923','Lorsque le roi Jéroboam entendit la parole que l''homme de Dieu avait criée contre l''autel de Béthel, il avança la main de dessus l''autel, en disant: « Saisissez-le! » Et la main qu''il avait étendue contre lui devint sèche, et il ne put la ramener à soi.'),
('1r',13,5,'crampon1923','L''autel se fendit, et la cendre se répandit de dessus l''autel, selon le signe qu''avait donné l''homme de Dieu, dans la parole de Yahweh.'),
('1r',13,6,'crampon1923','Le roi prit la parole et dit à l''homme de Dieu: « Apaise Yahweh, ton Dieu, et prie pour moi, afin que ma main revienne à moi. » L''homme de Dieu apaisa Yahweh, et le roi put ramener à lui sa main, qui devint comme auparavant.'),
('1r',13,7,'crampon1923','Le roi dit à l''homme de Dieu: « Entre avec moi dans la maison et ranime-toi, et je te donnerai un présent. »'),
('1r',13,8,'crampon1923','L''homme de Dieu répondit au roi: « Quand tu me donnerais la moitié de ta maison, je n''entrerais pas avec toi, et je ne mangerais pas de pain ni ne boirais d''eau dans ce lieu;'),
('1r',13,9,'crampon1923','car cet ordre m''a été donné dans la parole de Yahweh: Tu ne mangeras pas de pain et tu ne boiras pas d''eau, et tu ne reviendras pas par le chemin par lequel tu seras allé. »'),
('1r',13,10,'crampon1923','Il s''en alla donc par un autre chemin, et il ne s''en retourna pas par le chemin par lequel il était venu à Béthel.'),
('1r',13,11,'crampon1923','Or il y avait un vieux prophète qui demeurait à Béthel; ses fils vinrent lui raconter toutes les choses que l''homme de Dieu avait faites ce jour-là à Béthel; ils rapportèrent aussi à leur père les paroles qu''il avait dites au roi.'),
('1r',13,12,'crampon1923','Et leur père leur dit: « Par quel chemin s''en est-il allé? » Car ses fils avaient vu par quel chemin s''en était allé l''homme de Dieu qui était venu de Juda.'),
('1r',13,13,'crampon1923','Et il dit à ses fils: « Sellez-moi l''âne. » Ils lui sellèrent l''âne, et il monta dessus.'),
('1r',13,14,'crampon1923','Il alla après l''homme de Dieu et, l''ayant trouvé assis sous le térébinthe, il lui dit: « Es-tu l''homme de Dieu qui est venu de Juda? » Il répondit: « Je le suis. »'),
('1r',13,15,'crampon1923','Le prophète lui dit: « Viens avec moi à la maison, et tu mangeras un peu de pain. »'),
('1r',13,16,'crampon1923','Mais il répondit: « Je ne puis ni retourner avec toi, ni entrer avec toi; je ne mangerai point de pain, je ne boirai point d''eau avec toi dans ce lieu,'),
('1r',13,17,'crampon1923','car il m''a été dit dans la parole de Yahweh: Tu n''y mangeras pas de pain et tu n''y boiras pas d''eau, et tu ne reviendras pas par le chemin par lequel tu seras allé. »'),
('1r',13,18,'crampon1923','Et il lui dit: « Moi aussi, je suis prophète comme toi, et un ange m''a parlé dans la parole de Yahweh en ces termes: Ramène-le avec toi dans ta maison, pour qu''il mange du pain et boive de l''eau. » Il lui mentait.'),
('1r',13,19,'crampon1923','L''homme de Dieu retourna avec lui, et il mangea du pain et but de l''eau dans sa maison.'),
('1r',13,20,'crampon1923','Comme ils étaient assis à table, la parole de Yahweh fut adressée au prophète qui l''avait ramené;'),
('1r',13,21,'crampon1923','et il cria à l''homme qui était venu de Juda, en ces termes: « Ainsi parle Yahweh: Parce que tu as été rebelle à l''ordre de Yahweh, et que tu n''as pas observé le commandement que Yahweh, ton Dieu, t''avait prescrit;'),
('1r',13,22,'crampon1923','parce que tu es retourné, et que tu as mangé du pain et bu de l''eau dans le lieu dont Yahweh t''avait dit: Tu n''y mangeras pas de pain et n''y boiras pas d''eau, — ton cadavre n''entrera point dans le sépulcre de tes pères. »'),
('1r',13,23,'crampon1923','Après qu''il eut mangé du pain et qu''il eut bu, le vieux prophète sella l''âne pour lui, savoir, pour le prophète qu''il avait ramené.'),
('1r',13,24,'crampon1923','L''homme de Dieu s''en étant allé, il fut rencontré sur le chemin par un lion, qui le mit à mort. Pendant que son cadavre était étendu sur le chemin, l''âne resta à côté de lui, et le lion resta à côté du cadavre.'),
('1r',13,25,'crampon1923','Et voici, des gens qui passaient virent le cadavre étendu sur le chemin et le lion se tenant à côté du cadavre, et ils en parlèrent à leur arrivée dans la ville où demeurait le vieux prophète.'),
('1r',13,26,'crampon1923','Lorsque le prophète qui avait ramené du chemin l''homme de Dieu, l''eut appris, il dit: « C''est l''homme de Dieu qui a été rebelle à l''ordre de Yahweh, et Yahweh l''a livré au lion qui l''a déchiré et l''a fait mourir, selon la parole que Yahweh lui avait dite. »'),
('1r',13,27,'crampon1923','Il dit alors à ses fils: « Sellez-moi l''âne. » Lorsqu''ils l''eurent sellé,'),
('1r',13,28,'crampon1923','il partit et trouva le cadavre étendu sur le chemin, et l''âne et le lion qui se tenaient à côté du cadavre. Le lion n''avait pas dévoré le cadavre et n''avait pas déchiré l''âne.'),
('1r',13,29,'crampon1923','Le prophète releva le cadavre de l''homme de Dieu et, l''ayant mis sur l''âne, il le ramena, et le vieux prophète rentra dans la ville pour le pleurer et pour l''enterrer.'),
('1r',13,30,'crampon1923','Il mit le cadavre dans son sépulcre, et ils pleurèrent sur lui, en disant: « Hélas! Mon frère! »'),
('1r',13,31,'crampon1923','Lorsqu''il l''eut enterré, il dit à ses fils: « Quand je serai mort, vous m''enterrerez dans le sépulcre où est enterré l''homme de Dieu; vous déposerez mes os à côté de ses os.'),
('1r',13,32,'crampon1923','Car elle s''accomplira la parole qu''il a criée, dans la parole de Yahweh, contre l''autel qui est à Béthel, et contre toutes les maisons de hauts lieux qui sont dans les villes de Samarie. »'),
('1r',13,33,'crampon1923','Après cet événement, Jéroboam ne se détourna pas de sa voie mauvaise; de nouveau il créa des prêtres des hauts lieux pris parmi le peuple; quiconque le désirait, il le consacrait et celui-ci devenait prêtre des hauts lieux.'),
('1r',13,34,'crampon1923','En cela il y eut péché pour la maison de Jéroboam, et c''est pourquoi elle fut détruite et exterminée de la face de la terre.'),
('1r',14,1,'crampon1923','Dans ce temps-là, Abia, fils de Jéroboam, était devenu malade.'),
('1r',14,2,'crampon1923','Jéroboam dit à sa femme: « Lève-toi, je te prie, et déguise-toi pour qu''on ne sache pas que tu es la femme de Jéroboam, et va à Silo. Voici que là se trouve Ahias, le prophète, celui qui m''a dit que je serais roi sur ce peuple.'),
('1r',14,3,'crampon1923','Prends avec toi dix pains, des gâteaux et un vase de miel, et entre chez lui: il te dira ce qui doit arriver à l''enfant. »'),
('1r',14,4,'crampon1923','La femme de Jéroboam fit ainsi; s''étant levée, elle alla à Silo et entra dans la maison d''Ahias. Or Ahias ne pouvait plus voir, parce que la vieillesse avait obscurci ses yeux.'),
('1r',14,5,'crampon1923','Yahweh avait dit à Ahias: « Voici que la femme de Jéroboam vient pour obtenir de toi une parole au sujet de son fils, qui est malade; tu lui parleras de telle et telle manière. Quand elle arrivera, elle se donnera pour une autre. »'),
('1r',14,6,'crampon1923','Quand Ahias entendit le bruit de ses pas, au moment où elle franchissait la porte, il dit: « Entre, femme de Jéroboam; pourquoi te donnes-tu pour une autre? Je suis chargé pour toi d''un dur message.'),
('1r',14,7,'crampon1923','Va, dis à Jéroboam: Ainsi parle Yahweh, Dieu d''Israël: Je t''ai élevé du milieu du peuple et je t''ai établi chef sur mon peuple d''Israël;'),
('1r',14,8,'crampon1923','j''ai arraché le royaume de la maison de David, et je te l''ai donné; mais tu n''as pas été comme mon serviteur David, qui a observé mes commandements et marché après moi de tout son cœur, ne faisant que ce qui est droit à mes yeux;'),
('1r',14,9,'crampon1923','mais tu as fait le mal plus que tous ceux qui ont été avant toi, tu es allé te faire d''autres dieux et des images de fonte pour m''irriter, et tu m''as rejeté derrière ton dos!'),
('1r',14,10,'crampon1923','C''est pourquoi voici que je vais faire venir le malheur sur la maison de Jéroboam; j''exterminerai tout mâle appartenant à Jéroboam, celui qui est esclave et celui qui est libre et Israël, et je balaierai la maison de Jéroboam, comme on balaie l''ordure, jusqu''à ce qu''il n''en reste plus.'),
('1r',14,11,'crampon1923','Celui de la maison de Jéroboam qui mourra dans la ville sera mangé par les chiens, et celui qui mourra dans les champs sera mangé par les oiseaux du ciel: car Yahweh a parlé.'),
('1r',14,12,'crampon1923','Et toi, lève-toi, va dans ta maison; dès que tes pieds entreront dans la ville, l''enfant mourra.'),
('1r',14,13,'crampon1923','Tout Israël le pleurera, et on l''enterrera car il est le seul de la maison de Jéroboam qui sera mis dans un sépulcre, parce qu''il est le seul de la maison de Jéroboam en qui se soit trouvé quelque chose de bon devant Yahweh, le Dieu d''Israël.'),
('1r',14,14,'crampon1923','Yahweh établira sur Israël un roi qui exterminera la maison de Jéroboam ce jour-là. Mais quoi? Déjà la chose arrive!'),
('1r',14,15,'crampon1923','Yahweh frappera Israël, comme le roseau est agité au sein des eaux; il arrachera Israël de ce bon pays qu''il avait donné à leurs pères, et il les dispersera de l''autre côté du fleuve, parce qu''ils se sont fait des aschérahs, irritant Yahweh.'),
('1r',14,16,'crampon1923','Il livrera Israël à cause des péchés de Jéroboam qu''il a commis et qu''il a fait commettre à Israël. »'),
('1r',14,17,'crampon1923','La femme de Jéroboam se leva et, s''étant mise en route, elle arriva à Thersa. Comme elle franchissait le seuil de la maison, l''enfant mourut.'),
('1r',14,18,'crampon1923','On l''enterrera, et tout Israël le pleura, selon la parole que Yahweh avait dite par l''organe de son serviteur Ahias, le prophète.'),
('1r',14,19,'crampon1923','Le reste des actes de Jéroboam, comment il fit la guerre et comment il régna, voici que cela est écrit dans le livre des Chroniques des rois d''Israël.'),
('1r',14,20,'crampon1923','Le temps que régna Jéroboam fut de vingt-deux ans, et il se coucha avec ses pères. Nadab, son fils, régna à sa place.'),
('1r',14,21,'crampon1923','Roboam, fils de Salomon, régna en Juda. Il avait quarante et un ans lorsqu''il devint roi, et il régna dix-sept ans à Jérusalem, la ville que Yahweh avait choisie parmi toutes les tribus d''Israël pour y mettre son nom. Sa mère s''appelait Naama, l''Ammonite.'),
('1r',14,22,'crampon1923','Juda fit ce qui est mal aux yeux de Yahweh et, par les péchés qu''ils commirent, ils excitèrent sa jalousie plus que ne l''avaient fait leurs pères.'),
('1r',14,23,'crampon1923','Ils se bâtirent, eux aussi, des hauts lieux avec des stèles et des aschérahs, sur toute colline élevée et sous tout arbre vert.'),
('1r',14,24,'crampon1923','Il y eut même des prostitués dans le pays. Ils agirent selon toutes les abominations des nations que Yahweh avait chassées devant les enfants d''Israël.'),
('1r',14,25,'crampon1923','La cinquième année du règne de Roboam, Sésac, roi d''Egypte, monta contre Jérusalem.'),
('1r',14,26,'crampon1923','Il prit les trésors de la maison de Yahweh et les trésors de la maison du roi: il prit tout. Il prit tous les boucliers d''or que Salomon avait faits.'),
('1r',14,27,'crampon1923','A leur place, le roi Roboam fit des boucliers d''airain, et il les remit aux mains des chefs des coureurs qui gardaient l''entrée de la maison du roi.'),
('1r',14,28,'crampon1923','Chaque fois que le roi allait à la maison de Yahweh, les coureurs les portaient; et ils les rapportaient ensuite dans la chambre des coureurs.'),
('1r',14,29,'crampon1923','Le reste des actes de Roboam, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('1r',14,30,'crampon1923','Il y eut toujours guerre entre Roboam et Jéroboam.'),
('1r',14,31,'crampon1923','Roboam se coucha avec ses pères, et il fut enterré avec ses pères dans la ville de David. Sa mère s''appelait Naama, l''Ammonite; et Abiam, son fils, régna à sa place.'),
('1r',15,1,'crampon1923','La dix-huitième année du roi Jéroboam, fils de Nabat, Abiam devint roi de Juda,'),
('1r',15,2,'crampon1923','et il régna trois ans à Jérusalem. Sa mère se nommait Maacha, fille d''Abessalom.'),
('1r',15,3,'crampon1923','Il marcha dans tous les péchés de son père qu''il avait commis avant lui, et son cœur n''était pas tout entier à Yahweh, comme l''avait été le cœur de David, son père.'),
('1r',15,4,'crampon1923','Mais, à cause de David, Yahweh, son Dieu, lui donna une lampe à Jérusalem en établissant son fils après lui et en laissant subsister Jérusalem.'),
('1r',15,5,'crampon1923','Car David avait fait ce qui est droit aux yeux de Yahweh, et il ne s''était pas détourné pendant toute sa vie de tous les commandements qu''il en avait reçus, excepté dans l''affaire d''Urie le Héthéen.'),
('1r',15,6,'crampon1923','Il y eut guerre entre Roboam et Jéroboam tant qu''il vécut.'),
('1r',15,7,'crampon1923','Le reste des actes d''Abiam, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda. Il y eut guerre entre Abiam et Jéroboam.'),
('1r',15,8,'crampon1923','Abiam se coucha avec ses pères, et on l''enterrera dans la ville de David. Asa, son fils, régna à sa place.'),
('1r',15,9,'crampon1923','La vingtième année de Jéroboam, roi d''Israël, Asa devint roi de Juda,'),
('1r',15,10,'crampon1923','et il régna quarante et un ans à Jérusalem. Sa mère s''appelait Maacha, fille d''Abessalom.'),
('1r',15,11,'crampon1923','Asa fit ce qui est droit aux yeux de Yahweh, comme David, son père.'),
('1r',15,12,'crampon1923','Il fit disparaître du pays les prostitués et enleva toutes les idoles que ses pères avaient faites.'),
('1r',15,13,'crampon1923','Et même il ôta la dignité de reine-mère à Maacha, sa mère, parce qu''elle avait fait une idole abominable pour Astarté. Asa abattit son idole abominable et la brûla au torrent de Cédron.'),
('1r',15,14,'crampon1923','Mais les hauts lieux ne disparurent point, quoique le cœur d''Asa fut parfaitement à Yahweh pendant toute sa vie.'),
('1r',15,15,'crampon1923','Il mit dans la maison de Yahweh les choses consacrées par son père et les choses consacrées par lui-même, de l''argent, de l''or et des vases.'),
('1r',15,16,'crampon1923','Il y eut guerre entre Asa et Baasa, roi d''Israël, pendant toute leur vie.'),
('1r',15,17,'crampon1923','Baasa, roi d''Israël, monta contre Juda, et il bâtit Rama, pour empêcher les gens d''Asa, roi de Juda, de sortir et d''entrer.'),
('1r',15,18,'crampon1923','Asa prit tout l''argent et l''or qui étaient restés dans les trésors de la maison de Yahweh et les trésors de la maison du roi, et les mit entre les mains de ses serviteurs; et le roi Asa envoya ces derniers vers Ben-Hadad, fils de Tabremon, fils de Hézion, roi de Syrie, qui habitait à Damas, pour dire:'),
('1r',15,19,'crampon1923','« Qu''il y ait une alliance entre moi et toi, comme il y en avait une entre mon père et ton père. Je t''envoie un présent en argent et en or. Va, romps ton alliance avec Baasa, roi d''Israël, afin qu''il s''éloigne de moi. »'),
('1r',15,20,'crampon1923','Ben-Hadad écouta le roi Asa; il envoya les chefs de son armée contre les villes d''Israël, et il battit Ahion, Dan, Abel-Beth-Maacha, et tout Cenéroth avec tout le pays de Nephthali.'),
('1r',15,21,'crampon1923','Baasa, l''ayant appris, cessa de bâtir Rama, et resta à Thersa.'),
('1r',15,22,'crampon1923','Le roi Asa fit convoquer tout Juda, sans exempter personne; et ils emportèrent les pierres et le bois avec lesquels Baasa construisait Rama, et le roi Asa bâtit avec eux Gabaa de Benjamin et Maspha.'),
('1r',15,23,'crampon1923','Le reste de tous les actes d''Asa, tous ses exploits, et tout ce qu''il a fait, et les villes qu''il a bâties, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda? Toutefois, au temps de sa vieillesse, il eut les pieds malades.'),
('1r',15,24,'crampon1923','Asa se coucha avec ses pères et il fut enterré avec ses pères dans la ville de David, son père; et Josaphat, son fils, régna à sa place.'),
('1r',15,25,'crampon1923','Nadab, fils de Jéroboam, devint roi d''Israël la seconde année d''Asa, roi de Juda, et il régna deux ans sur Israël.'),
('1r',15,26,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, et il marcha dans la voie de son père et dans les péchés de son père qu''il avait fait commettre à Israël.'),
('1r',15,27,'crampon1923','Baasa, fils d''Ahias, de la maison d''Issachar, conspira contre lui; et Baasa le frappa à Gebbéthon, qui appartenait aux Philistins, car Nadab et tout Israël faisaient le siège de Gebbéthon.'),
('1r',15,28,'crampon1923','Baasa le mit à mort la troisième année d''Asa, roi de Juda, et il régna à sa place.'),
('1r',15,29,'crampon1923','Lorsqu''il fut devenu roi, il frappa toute la maison de Jéroboam; il n''épargna de la maison de Jéroboam aucune âme vivante, sans l''exterminer, selon la parole que Yahweh avait dite par l''organe de son serviteur Ahias de Silo,'),
('1r',15,30,'crampon1923','à cause des péchés de Jéroboam qu''il avait commis, et qu''il avait fait commettre à Israël, irritant ainsi Yahweh, le Dieu d''Israël.'),
('1r',15,31,'crampon1923','Le reste des actes de Nadab, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('1r',15,32,'crampon1923','Il y eut guerre entre Asa et Baasa, roi d''Israël, pendant toute leur vie.'),
('1r',15,33,'crampon1923','La troisième année d''Asa, roi de Juda, Baasa, fils d''Ahias, devint roi sur tout Israël à Thersa, et il régna vingt-quatre ans.'),
('1r',15,34,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, et il marcha dans la voie de Jéroboam et dans les péchés que celui-ci avait fait commettre à Israël.'),
('1r',16,1,'crampon1923','La parole de Yahweh fut adressée à Jéhu, fils de Hanani, contre Baasa, en ces termes:'),
('1r',16,2,'crampon1923','« Je t''ai élevé de la poussière et je t''ai établi chef de mon peuple d''Israël; mais tu as marché dans la voie de Jéroboam et tu as fait pécher mon peuple d''Israël, pour m''irriter par leurs péchés.'),
('1r',16,3,'crampon1923','C''est pourquoi voici que je vais balayer Baasa et sa maison, et je rendrai ta maison semblable à la maison de Jéroboam, fils de Nabat.'),
('1r',16,4,'crampon1923','Celui de la maison de Baasa qui mourra dans la ville sera mangé par les chiens, et celui des siens qui mourra dans les champs sera mangé par les oiseaux du ciel. »'),
('1r',16,5,'crampon1923','Le reste des actes de Baasa, ce qu''il a fait et ses exploits, cela n''est-il pas écrit dans la Chroniques des roi d''Israël?'),
('1r',16,6,'crampon1923','Baasa se coucha avec ses pères et il fut enterré à Thersa; et Ela, son fils, régna à sa place.'),
('1r',16,7,'crampon1923','La parole de Yahweh fut aussi dirigée par l''organe du prophète Jéhu, fils de Hanani, contre Baasa et contre sa maison, soit à cause de tout le mal qu''il avait fait sous les yeux de Yahweh, en l''irritant par l''œuvre de ses mains et en devenant semblable à la maison de Jéroboam, soit encore parce qu''il avait frappé cette maison.'),
('1r',16,8,'crampon1923','La vingt-sixième année d''Asa, roi de Juda, Ela, fils de Baasa, devint roi d''Israël à Thersa, et il régna deux ans.'),
('1r',16,9,'crampon1923','Son serviteur Zambri, chef de la moitié des chars, conspira contre lui. Ela était à Thersa, buvant et s''enivrant dans la maison d''Arsa, qui était préposé à la maison du roi à Thersa.'),
('1r',16,10,'crampon1923','Zambri entra, le frappa et le tua, la vingt-septième année d''Asa, roi de Juda, et il régna à sa place.'),
('1r',16,11,'crampon1923','Lorsqu''il fut devenu roi et qu''il fut assis sur son trône, il frappa toute la maison de Baasa, ne laissant vivre aucun enfant mâle, ni aucun de ses parents et de ses amis.'),
('1r',16,12,'crampon1923','C''est ainsi que Zambri détruisit toute la maison de Baasa, selon la parole de Yahweh qu''il avait dite contre Baasa par l''organe de Jéhu, le prophète,'),
('1r',16,13,'crampon1923','à cause de tous les péchés que Baasa et Ela, son fils, avaient commis et qu''ils avaient fait commettre à Israël, irritant par leurs idoles Yahweh, le Dieu d''Israël.'),
('1r',16,14,'crampon1923','Le reste des actes d''Ela, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('1r',16,15,'crampon1923','La vingt-septième année d''Asa, roi de Juda, Zambri fut roi pendant sept jours à Thersa. Le peuple était alors campé vis-à-vis de Gebbéthon, qui appartenait aux Philistins.'),
('1r',16,16,'crampon1923','Et le peuple qui campait apprit cette nouvelle: « Zambri a conspiré, et même il a tué le roi! » Le jour même, dans le camp, tout Israël établit pour roi d''Israël Amri, chef de l''armée.'),
('1r',16,17,'crampon1923','Amri et tout Israël avec lui montèrent de Gebbéthon et vinrent assiéger Thersa.'),
('1r',16,18,'crampon1923','Lorsqu''il vit la ville prise, Zambri se retira dans la citadelle de la maison du roi et brûla sur lui la maison du roi. C''est ainsi qu''il mourut,'),
('1r',16,19,'crampon1923','à cause des péchés qu''il avait commis, en faisant ce qui est mal aux yeux de Yahweh, et en marchant dans la voie de Jéroboam et dans le péché que Jéroboam avait commis pour faire pécher Israël.'),
('1r',16,20,'crampon1923','Le reste des actes de Zambri, et le complot qu''il forma, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('1r',16,21,'crampon1923','Le peuple d''Israël se divisa alors en deux partis: la moitié du peuple était pour Thebni, fils de Gineth, pour le faire roi, et l''autre moitié était pour Amri.'),
('1r',16,22,'crampon1923','Ceux qui suivaient Amri l''emportèrent sur ceux qui suivaient Thebni, fils de Gineth. Thebni mourut, et Amri régna.'),
('1r',16,23,'crampon1923','La trente et unième année d''Asa, roi de Juda, Amri devint roi d''Israël, et il régna douze ans.'),
('1r',16,24,'crampon1923','Lorsqu''il eut régné six ans à Thersa, il acheta de Somer la montagne de Samarie pour deux talents d''argent; puis il bâtit sur la montagne, et il donna à la ville qu''il avait bâtie le nom de Samarie, du nom de Somer, à qui la montagne appartenait.'),
('1r',16,25,'crampon1923','Amri fit ce qui est mal aux yeux de Yahweh, et il agit plus mal que tous ceux qui avaient régné avant lui.'),
('1r',16,26,'crampon1923','Il marcha dans toute la voie de Jéroboam, fils de Nabat, et dans les péchés que Jéroboam avait fait commettre à Israël, irritant par leurs idoles Yahweh, le Dieu d''Israël.'),
('1r',16,27,'crampon1923','Le reste des actes d''Amri, ce qu''il a fait, et les exploits qu''il a accomplis, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('1r',16,28,'crampon1923','Amri se coucha avec ses pères, et il fut enterré à Samarie. Achab, son fils, régna à sa place.'),
('1r',16,29,'crampon1923','Achab, fils d''Amri, devint roi d''Israël la trente-huitième année d''Asa, roi de Juda, et Achab, fils d''Amri, régna vingt-deux ans sur Israël à Samarie.'),
('1r',16,30,'crampon1923','Achab, fils d''Amri, fit ce qui est mal aux yeux du Seigneur, plus que tous ceux qui avaient été avant lui.'),
('1r',16,31,'crampon1923','Comme si c''eût été pour lui peu de chose de marcher dans les péchés de Jéroboam, fils de Nabat, il prit pour femme Jézabel, fille d''Ethbaal, roi des Sidoniens, et il alla servir Baal et se prosterner devant lui.'),
('1r',16,32,'crampon1923','Il éleva un autel à Baal dans la maison de Baal, qu''il bâtit à Samarie;'),
('1r',16,33,'crampon1923','Achab fit aussi l''aschérah. Achab fit plus encore que tous les rois d''Israël qui avaient été avant lui pour irriter Yahweh, le Dieu d''Israël.'),
('1r',16,34,'crampon1923','De son temps, Hiel de Béthel bâtit Jéricho; il en jeta les fondements au prix d''Abiram, son premier-né, et il en posa les portes au prix de Ségub, son dernier fils, selon la parole de Yahweh, qu''il avait dite par l''organe de Josué, fils de Nun.'),
('1r',17,1,'crampon1923','Elie, le Thesbite, un des habitants de Galaad, dit à Achab: « Yahweh est vivant, le Dieu d''Israël, devant qui je me tiens! Il n''y aura ces années-ci ni rosée ni pluie, sinon à ma parole. »'),
('1r',17,2,'crampon1923','Et la parole de Yahweh fut adressée à Elie, en ces termes:'),
('1r',17,3,'crampon1923','« Pars d''ici, dirige-toi vers l''orient et cache-toi au torrent de Carith, qui est en face du Jourdain.'),
('1r',17,4,'crampon1923','Tu boiras de l''eau du torrent, et j''ai commandé aux corbeaux de te nourrir là. »'),
('1r',17,5,'crampon1923','Il partit, et fit selon la parole de Yahweh; et il alla s''établir au torrent de Carith, qui est en face du Jourdain.'),
('1r',17,6,'crampon1923','Les corbeaux lui apportaient du pain et de la viande le matin, du pain et de la viande le soir, et il buvait de l''eau du torrent.'),
('1r',17,7,'crampon1923','Mais, au bout d''un certain temps, le torrent fut à sec, car il n''était pas tombé de pluie dans le pays.'),
('1r',17,8,'crampon1923','Alors la parole de Yahweh lui fut adressée en ces termes:'),
('1r',17,9,'crampon1923','« Lève-toi, va à Sarephta, qui appartient à Sidon, et tu y demeureras; voici que j''ai ordonné là à une femme veuve de te nourrir. »'),
('1r',17,10,'crampon1923','Il se leva et alla à Sarephta. Comme il arrivait à la porte de la ville, voici qu''il y avait là une femme veuve qui ramassait du bois. Il l''appela et lui dit: « Va me prendre, je te prie, un peu d''eau dans ce vase, afin que je boive. »'),
('1r',17,11,'crampon1923','Et elle alla en prendre. Il l''appela de nouveau, et il dit: « Apporte-moi, je te prie, un morceau de pain dans ta main. »'),
('1r',17,12,'crampon1923','Elle répondit: « Yahweh, ton Dieu, est vivant! Je n''ai rien de cuit, je n''ai qu''une poignée de farine dans un pot et un peu d''huile dans une cruche. Et voici que je ramasse deux morceaux de bois, afin que, rentrée à la maison, je prépare ce reste pour moi et pour mon fils; nous le mangerons, et nous mourrons ensuite. »'),
('1r',17,13,'crampon1923','Elie lui dit: « Ne crains point, rentre faire comme tu as dit. Seulement prépare-moi d''abord avec cela un petit gâteau, que tu m''apporteras; tu en feras ensuite pour toi et pour ton fils.'),
('1r',17,14,'crampon1923','Car ainsi parle Yahweh, le Dieu d''Israël: Le pot de farine ne s''épuisera point, et la cruche d''huile ne diminuera point, jusqu''au jour où Yahweh fera tomber de la pluie sur la face du sol. »'),
('1r',17,15,'crampon1923','Elle s''en alla et fit selon la parole d''Elie; et pendant longtemps elle eut de quoi manger, elle et sa famille, ainsi qu''Elie.'),
('1r',17,16,'crampon1923','Le pot de farine ne s''épuisa pas, et la cruche d''huile ne diminua pas, selon la parole de Yahweh, qu''il avait dite par l''organe d''Elie.'),
('1r',17,17,'crampon1923','Après ces événements, le fils de la femme, maîtresse de la maison, devint malade, et sa maladie fut très violente, au point qu''il ne resta plus de souffle en lui.'),
('1r',17,18,'crampon1923','Alors cette femme dit à Elie: « Qu''ai-je à faire avec toi, homme de Dieu? Es-tu venu chez moi pour rappeler le souvenir de mes iniquités et pour faire mourir mon fils? »'),
('1r',17,19,'crampon1923','Il lui répondit: « Donne-moi ton fils. » Et il le prit du sein de la femme et, l''ayant monté dans la chambre haute où il demeurait, il le coucha sur son lit.'),
('1r',17,20,'crampon1923','Puis, il invoqua Yahweh, en disant: « Yahweh, mon Dieu, auriez-vous encore fait tomber le malheur sur cette veuve chez laquelle je demeure, jusqu''à faire mourir son fils? »'),
('1r',17,21,'crampon1923','Et il s''étendit trois fois sur l''enfant, en invoquant Yahweh et en disant: « Yahweh, mon Dieu, je vous en prie, que l''âme de cet enfant revienne au dedans de lui! »'),
('1r',17,22,'crampon1923','Yahweh écouta la voix d''Elie, et l''âme de l''enfant revint au dedans de lui, et il fut rendu à la vie.'),
('1r',17,23,'crampon1923','Elie prit l''enfant, le descendit de la chambre haute dans la maison et le donna à sa mère; et Elie dit: « Voici que ton fils est vivant. »'),
('1r',17,24,'crampon1923','La femme dit à Elie: « Je reconnais maintenant que tu es un homme de Dieu, et que la parole de Yahweh dans ta bouche est vérité. »'),
('1r',18,1,'crampon1923','Après beaucoup de jours, la parole de Yahweh fut adressée à Elie, dans la troisième année, en ces termes: « Va, parais devant Achab, et je ferai tomber de la pluie sur la face du sol. »'),
('1r',18,2,'crampon1923','Et Elie partit, pour se présenter devant Achab. La famine était devenue grande à Samarie,'),
('1r',18,3,'crampon1923','Achab fit appeler Abdias, chef de sa maison. — Or Abdias craignait beaucoup Yahweh,'),
('1r',18,4,'crampon1923','car, lorsque Jézabel massacra les prophètes de Yahweh, Abdias prit cent prophètes et les cacha cinquante par cinquante dans des cavernes, où il les nourrit de pain et d''eau. —'),
('1r',18,5,'crampon1923','Achab dit à Abdias: « Va par le pays vers toutes les sources d''eau et vers tous les torrents; peut-être se trouvera-t-il de l''herbe, et nous conserverons la vie aux chevaux et aux mulets, et nous n''aurons pas à abattre de bétail. »'),
('1r',18,6,'crampon1923','Ils se partagèrent le pays pour le parcourir; Achab alla seul par un chemin, et Abdias alla seul par un autre chemin.'),
('1r',18,7,'crampon1923','Comme Abdias était en route, voici qu''Elie le rencontra. Abdias, l''ayant reconnu, tomba sur son visage et dit: « Est-ce toi, mon seigneur Elie? »'),
('1r',18,8,'crampon1923','Il lui répondit: « C''est moi; va dire à ton maître: Voici Elie! »'),
('1r',18,9,'crampon1923','Et Abdias dit: « Quel péché ai-je commis, que tu livres ton serviteur entre les mains d''Achab, pour qu''il me fasse mourir?'),
('1r',18,10,'crampon1923','Yahweh, ton Dieu, est vivant! Il n''y a ni nation ni royaume où mon maître n''ait envoyé pour te chercher; et quand on disait: Elie n''est pas ici, il faisait jurer le royaume et la nation qu''on ne t''avait pas trouvé.'),
('1r',18,11,'crampon1923','Et maintenant tu me dis: Va dire à ton maître: Voici Elie!'),
('1r',18,12,'crampon1923','Et lorsque je t''aurai quitté, l''Esprit de Yahweh te transportera je ne sais où; et j''irai informer Achab, qui ne te trouvera pas et me tuera. Cependant ton serviteur craint Yahweh dès sa jeunesse.'),
('1r',18,13,'crampon1923','N''a-t-on pas dit à mon seigneur ce que j''ai fait quand Jézabel a massacré les prophètes de Yahweh? J''ai caché cent des prophètes de Yahweh, cinquante par cinquante, dans des cavernes, et je les ai nourris de pain et d''eau.'),
('1r',18,14,'crampon1923','Et maintenant tu dis: Va dire à ton maître: Voici Elie! Il me tuera. »'),
('1r',18,15,'crampon1923','Mais Elie dit: « Yahweh des armées, devant qui je me tiens, est vivant! Aujourd''hui je me présenterai devant Achab. »'),
('1r',18,16,'crampon1923','Abdias alla à la rencontre d''Achab et lui apprit la nouvelle; et Achab se rendit au-devant d''Elie.'),
('1r',18,17,'crampon1923','Dès qu''Achab aperçut Elie, Achab lui dit: « Toi ici, le perturbateur d''Israël? »'),
('1r',18,18,'crampon1923','Elie répondit: « Je ne trouble point Israël; c''est toi, au contraire, et la maison de ton père, en ce que vous avez abandonné les commandements de Yahweh et que tu es allé après les Baals.'),
('1r',18,19,'crampon1923','Maintenant, envoie rassembler tout Israël auprès de moi, à la montagne du Carmel, ainsi que les quatre cent cinquante prophètes de Baal et les quatre cents prophètes d''Astarté, qui mangent de la table de Jézabel. »'),
('1r',18,20,'crampon1923','Achab envoya des messagers vers tous les enfants d''Israël, et rassembla les prophètes à la montagne du Carmel.'),
('1r',18,21,'crampon1923','Alors Elie s''approcha de tout le peuple et dit: « Jusques à quand clocherez-vous des deux côtés? Si Yahweh est Dieu, allez après lui; si c''est Baal, allez après lui! » Le peuple ne lui répondit rien.'),
('1r',18,22,'crampon1923','Et Elie dit au peuple: « Je suis resté seul des prophètes de Yahweh, et il y a quatre cent cinquante prophètes de Baal.'),
('1r',18,23,'crampon1923','Que l''on nous donne deux taureaux; qu''ils choisissent pour eux l''un des taureaux, qu''ils le coupent par morceaux et qu''ils le placent sur le bois, sans y mettre le feu; et moi je préparerai l''autre taureau, et je le placerai sur le bois, sans y mettre le feu.'),
('1r',18,24,'crampon1923','Puis invoquez le nom de votre dieu, et moi j''invoquerai le nom de Yahweh. Le dieu qui répondra par le feu, celui-là est Dieu. » Tout le peuple répondit en disant: « C''est bien! »'),
('1r',18,25,'crampon1923','Elie dit aux prophètes de Baal: « Choisissez pour vous l''un des taureaux, préparez-le d''abord, car vous êtes les plus nombreux, et invoquez le nom de votre dieu, mais ne mettez pas le feu. »'),
('1r',18,26,'crampon1923','Ils prirent le taureau qu''on leur donna et le préparèrent; et ils invoquèrent le nom de Baal depuis le matin jusqu''à midi, en disant: « Baal, réponds-nous! » Mais il n''y eut ni voix ni réponse. Et ils sautaient devant l''autel qu''ils avaient fait.'),
('1r',18,27,'crampon1923','A midi, Elie se moqua d''eux et dit: « Criez à haute voix, car il est dieu; il est en méditation, ou il est occupé, ou il est en voyage; peut-être qu''il dort, et il se réveillera. »'),
('1r',18,28,'crampon1923','Et ils crièrent à haute voix, et ils se firent, selon leur coutume, des incisions avec des épées et avec des lances, jusqu''à ce que le sang coulât sur eux.'),
('1r',18,29,'crampon1923','Lorsque midi fut passé, ils prophétisèrent jusqu''au moment où l''on présente l''oblation. Mais il n''y eut ni voix, ni réponse, ni signe d''attention.'),
('1r',18,30,'crampon1923','Elie dit à tout le peuple: « Approchez-vous de moi. » Tout le peuple s''étant approché de lui, Elie rétablit l''autel de Yahweh, qui avait été renversé.'),
('1r',18,31,'crampon1923','Elie prit douze pierres, d''après le nombre des tribus des fils de Jacob, auquel la parole de Yahweh avait été adressée en ces termes: « Israël sera ton nom. »'),
('1r',18,32,'crampon1923','Il bâtit avec ces pierres un autel au nom de Yahweh; puis,ayant fait autour de l''autel un fossé de la capacité de deux mesures de semence,'),
('1r',18,33,'crampon1923','il arrangea le bois, coupa le taureau par morceaux et le plaça sur le bois.'),
('1r',18,34,'crampon1923','Et il dit: « Remplissez d''eau quatre cruches, et versez-les sur l''holocauste et sur le bois. » Il dit: « Faites-le une seconde fois »; et ils le firent une seconde fois. Il dit: « Faites le une troisième fois »; et ils le firent une troisième fois.'),
('1r',18,35,'crampon1923','L''eau coula autour de l''autel, et il fit remplir aussi d''eau le fossé.'),
('1r',18,36,'crampon1923','A l''heure où l''on offre l''oblation du soir, Elie, le prophète, s''avança et dit: « Yahweh, Dieu d''Abraham, d''Isaac et d''Israël, que l''on sache aujourd''hui que vous êtes Dieu en Israël, que je suis votre serviteur et que j''ai fait toutes ces choses sur votre parole.'),
('1r',18,37,'crampon1923','Exaucez-moi, Yahweh, exaucez-moi! Afin que ce peuple reconnaisse que vous, Yahweh, êtes Dieu, et que c''est vous qui ramenez leur cœur en arrière. »'),
('1r',18,38,'crampon1923','Alors le feu de Yahweh tomba, et il consuma l''holocauste, le bois, les pierres et la terre, et absorba l''eau qui était dans le fossé.'),
('1r',18,39,'crampon1923','Quand tout le peuple vit cela, ils tombèrent sur leur visage et ils dirent: « C''est Yahweh qui est Dieu! C''est Yahweh qui est Dieu! »'),
('1r',18,40,'crampon1923','Et Elie leur dit: « Saisissez les prophètes de Baal; que pas un d''eux n''échappe! » Ils les saisirent, et Elie les fit descendre au torrent de Cison, où il les tua.'),
('1r',18,41,'crampon1923','Elie dit à Achab: « Monte, mange et bois; car j''entends le bruissement de la pluie. »'),
('1r',18,42,'crampon1923','Achab monta pour manger et pour boire; mais Elie monta au sommet du Carmel et, se penchant vers la terre, il mit son visage entre ses genoux,'),
('1r',18,43,'crampon1923','et il dit à son serviteur: « Monte, regarde du côté de la mer. » Le serviteur monta et, ayant regardé, il dit: « Il n''y a rien. » Et Elie dit: « Retourne sept fois. »'),
('1r',18,44,'crampon1923','A la septième fois, il dit: « Voici un petit nuage, comme la paume de la main d''un homme, qui s''élève de la mer. » Et Elie dit: « Va dire à Achab: Attelle et descends, afin que la pluie ne te surprenne pas. »'),
('1r',18,45,'crampon1923','En peu de temps, le ciel fut assombri par les nuages et le vent, et il tomba une forte pluie; et Achab, monté sur son char, s''en retourna à Jezrahel.'),
('1r',18,46,'crampon1923','Et la main de Yahweh fut sur Elie; il se ceignit les reins et courut devant Achab, jusqu''à l''entrée de Jezrahel.'),
('1r',19,1,'crampon1923','Achab rapporta à Jézabel tout ce qu''Elie avait fait, et comment il avait tué par l''épée tous les prophètes.'),
('1r',19,2,'crampon1923','Et Jézabel envoya un messager à Elie pour lui dire: « Que les dieux me traitent dans toute leur rigueur, si demain à cette heure je n''ai pas fait de ta vie comme tu as fait de la vie de chacun d''eux? »'),
('1r',19,3,'crampon1923','Elie, voyant cela, se leva et partit pour sauver sa vie. Il arriva à Bersabée, qui appartient à Juda, et y laissa son serviteur.'),
('1r',19,4,'crampon1923','Pour lui, il alla dans le désert l''espace d''une journée de marche; arrivé là, il s''assit sous un genêt et demanda pour lui la mort, en disant: « C''est assez! Maintenant, Yahweh, prends ma vie, car je ne suis pas meilleur que mes pères! »'),
('1r',19,5,'crampon1923','Il se coucha et s''endormit sous le genêt. Et voici qu''un ange le toucha et lui dit: « Lève-toi, mange. »'),
('1r',19,6,'crampon1923','Il regarda, et voici qu''il y avait à son chevet un gâteau cuit sur des pierres chauffées et une cruche d''eau. Après avoir mangé et bu, il se recoucha.'),
('1r',19,7,'crampon1923','L''ange de Yahweh vint une seconde fois, le toucha et dit: « Lève-toi, mange, car le chemin est trop long pour toi. »'),
('1r',19,8,'crampon1923','Il se leva, mangea et but, et, avec la force que lui donna cette nourriture, il marcha quarante jours et quarante nuits jusqu''à la montagne de Dieu, à Horeb.'),
('1r',19,9,'crampon1923','Là, il entra dans la caverne, et il y passa la nuit. Et voici que la parole de Yahweh lui fut adressée, et il lui dit: « Que fais-tu ici, Elie? »'),
('1r',19,10,'crampon1923','Il répondit: « J''ai été plein de zèle pour Yahweh, le Dieu des armées; car les enfants d''Israël ont abandonné votre alliance, renversé vos autels, et tué par l''épée vos prophètes; je suis resté moi seul, et ils cherchent à m''ôter la vie. »'),
('1r',19,11,'crampon1923','Yahweh dit: « Sors, et tiens-toi dans la montagne devant Yahweh, car voici que Yahweh va passer. » Et il y eut, devant Yahweh, un vent fort et violent qui déchirait les montagnes et brisait les rochers: Yahweh n''était pas dans le vent. Après le vent, il y eut un tremblement de terre: Yahweh n''était pas dans le tremblement de terre.'),
('1r',19,12,'crampon1923','Et après le tremblement de terre, un feu: Yahweh n''était pas dans le feu. Et après le feu, un murmure doux et léger.'),
('1r',19,13,'crampon1923','Quand Elie l''entendit, il s''enveloppa le visage de son manteau et, étant sorti, il se tint à l''entrée de la caverne. Et voici qu''une voix se fit entendre à lui, en disant: « Que fais-tu ici, Elie? »'),
('1r',19,14,'crampon1923','Il répondit: « J''ai été plein de zèle pour Yahweh, le Dieu des armées; car les enfants d''Israël ont abandonné votre alliance, renversé vos autels et tué par l''épée vos prophètes; je suis resté, moi seul, et ils cherchent à m''ôter la vie! »'),
('1r',19,15,'crampon1923','Yahweh lui dit: « Va, reprenant ton chemin, au désert de Damas, et, quand tu seras arrivé, tu oindras Hazaël pour roi sur la Syrie;'),
('1r',19,16,'crampon1923','tu oindras Jéhu, fils de Namsi, pour roi sur Israël, et tu oindras Elisée, fils de Saphat, d''Abel-Méhula, pour prophète à ta place.'),
('1r',19,17,'crampon1923','Et celui qui échappera à l''épée de Hazaël, Jéhu le fera mourir; et celui qui échappera à l''épée de Jéhu, Elisée le fera mourir.'),
('1r',19,18,'crampon1923','Mais je laisserai en Israël sept mille hommes, savoir tous ceux qui n''ont pas fléchi le genou devant Baal, tous ceux dont la bouche ne l''a point baisé. »'),
('1r',19,19,'crampon1923','Etant parti de là, Elie trouva Elisée, fils de Saphat, qui labourait; il y avait devant lui douze paires de bœufs, et il était avec la douzième. Elie s''approcha de lui, et il jeta sur lui son manteau.'),
('1r',19,20,'crampon1923','Elisée, quittant les bœufs, courut après Elie et dit: « Permets que j''embrasse mon père et ma mère, et je te suivrai. » Elie lui répondit: « Va, retourne, car que t''ai-je fait!... »'),
('1r',19,21,'crampon1923','Elisée s''éloigna de lui et, ayant pris la paire de bœufs, il les égorgea; et avec le harnais des bœufs, il fit cuire leur chair et la donna à manger au peuple. Puis il se leva, suivit Elie et fut à son service.'),
('1r',20,1,'crampon1923','Benhadad, roi de Syrie, rassembla toute son armée; il y avait avec lui trente-deux rois, des chevaux et des chars. Il monta et, ayant mis le siège devant Samarie, il l''attaqua.'),
('1r',20,2,'crampon1923','Il envoya dans la ville des messagers à Achab, roi d''Israël,'),
('1r',20,3,'crampon1923','pour lui dire: « Ainsi dit Benhadad: Ton argent et ton or sont à moi, tes femmes et tes plus beaux enfants sont à moi. »'),
('1r',20,4,'crampon1923','Le roi d''Israël répondit: « Comme tu le dis, ô roi, mon seigneur; je suis à toi avec tout ce que j''ai. »'),
('1r',20,5,'crampon1923','Les messagers revinrent et dirent: « Ainsi dit Benhadad: Je t''ai envoyé dire: Tu me livreras ton argent et ton or, tes femmes et tes enfants.'),
('1r',20,6,'crampon1923','Or quand demain, à cette heure, j''enverrai mes serviteurs chez toi, ils fouilleront ta maison et les maisons de tes serviteurs, et tout ce qui est précieux à tes yeux, ils le prendront de leurs mains et ils l''emporteront. »'),
('1r',20,7,'crampon1923','Le roi d''Israël convoqua tous les anciens du pays, et il dit: « Reconnaissez et voyez que cet homme veut notre malheur; car il m''a envoyé demander mes femmes et mes enfants, mon argent et mon or, et je ne lui avais pas refusé.'),
('1r',20,8,'crampon1923','Tous les anciens et tout le peuple dirent à Achab: « Ne l''écoute pas et ne consens pas. »'),
('1r',20,9,'crampon1923','Achab répondit donc aux messagers de Benhadad: Dites à mon seigneur le roi: Tout ce que tu as envoyé demander à ton serviteur la première fois, je le ferai, mais pour cette chose, je ne puis la faire. » Les messagers s''en allèrent, et lui portèrent la réponse.'),
('1r',20,10,'crampon1923','Benhadad envoya dire à Achab: « Que les dieux me traitent dans toute leur rigueur, si la poussière de Samarie suffit pour remplir le creux de la main de tout le peuple qui me suit! »'),
('1r',20,11,'crampon1923','Et le roi d''Israël répondit et dit: « Dites-lui: Que celui qui revêt son armure ne se glorifie pas comme celui qui la dépose! »'),
('1r',20,12,'crampon1923','Lorsque Benhadad entendit cette réponse, — il était à boire avec les rois sous les huttes, — il dit à ses serviteurs: « Prenez vos positions! » Et ils prirent leurs positions contre la ville.'),
('1r',20,13,'crampon1923','Mais voici qu''un prophète, s''approchant d''Achab, roi d''Israël, lui dit: « Ainsi dit Yahweh: Tu vois toute cette grande multitude? Voici que je vais la livrer aujourd''hui entre tes mains, afin que tu saches que je suis Yahweh. »'),
('1r',20,14,'crampon1923','Achab dit: « Par qui? » Et il répondit: « Ainsi dit Yahweh: Par les serviteurs des chefs des provinces. » Achab dit: « Qui engagera le combat? » Et il répondit: « Toi. »'),
('1r',20,15,'crampon1923','Alors Achab passa en revue les serviteurs des chefs des provinces, et il s''en trouva deux cent trente-deux; après eux, il passa en revue tout le peuple, tous les enfants d''Israël: ils étaient sept mille.'),
('1r',20,16,'crampon1923','Ils firent une sortie à midi, pendant que Benhadad buvait et s''enivrait sous les huttes, lui et les trente-deux rois, ses auxiliaires.'),
('1r',20,17,'crampon1923','Les serviteurs des chefs des provinces étaient sortis les premiers. Benhadad envoya aux informations, et on lui fit ce rapport: « Des hommes sont sortis de Samarie. »'),
('1r',20,18,'crampon1923','Il dit: « S''ils sortent pour la paix, prenez-les vivants; s''ils sortent pour le combat, prenez-les vivants. »'),
('1r',20,19,'crampon1923','Lorsque les serviteurs des chefs des provinces, ainsi que l''armée qui venait après eux, furent sortis de la ville,'),
('1r',20,20,'crampon1923','ils frappèrent chacun son homme, et les Syriens prirent la fuite. Israël les poursuivit. Benhadad, roi de Syrie, se sauva sur un cheval, avec des cavaliers.'),
('1r',20,21,'crampon1923','Le roi d''Israël sortit, frappa les chevaux et les chars, et fit éprouver aux Syriens une grande défaite.'),
('1r',20,22,'crampon1923','Alors le prophète s''approcha du roi d''Israël et lui dit: « Va, fortifie-toi, examine et vois ce que tu as à faire; car, au retour de l''année, le roi de Syrie montera contre toi. »'),
('1r',20,23,'crampon1923','Les serviteurs du roi de Syrie lui dirent: « Leurs dieux sont des dieux de montagnes; c''est pourquoi ils ont été plus forts que nous; mais combattons-les dans la plaine, et sûrement nous serons plus forts qu''eux.'),
('1r',20,24,'crampon1923','Fais encore ceci: ôte chacun des rois de son poste, et mets des chefs à leur place,'),
('1r',20,25,'crampon1923','et forme-toi une armée égale à celle que tu as perdue, avec autant de chevaux et autant de chariots. Nous les combattrons alors dans la plaine, et sûrement nous serons plus forts qu''eux. » Il écouta leur parole et fit ainsi.'),
('1r',20,26,'crampon1923','Au retour de l''année, Benhadad passa les Syriens en revue, et monta vers Aphec pour combattre Israël.'),
('1r',20,27,'crampon1923','Les enfants d''Israël furent aussi passés en revue; ils reçurent des vivres et ils s''avancèrent à la rencontre des Syriens. Les enfants d''Israël campèrent vis-à-vis d''eux, semblables à deux petits troupeaux de chèvres, tandis que les Syriens remplissaient le pays.'),
('1r',20,28,'crampon1923','Un homme de Dieu s''approcha et dit au roi d''Israël: « Ainsi dit Yahweh: Parce que les Syriens ont dit: Yahweh est un dieu des montagnes, et non un dieu des vallées, je livrerai entre tes mains toute cette grande multitude, et vous saurez que je suis Yahweh. »'),
('1r',20,29,'crampon1923','Ils campèrent sept jours en face les uns des autres. Le septième jour, le combat s''engagea, et les enfants d''Israël tuèrent aux Syriens cent mille hommes de pied en un jour.'),
('1r',20,30,'crampon1923','Le reste s''enfuit à Aphec, à la ville, et la muraille tomba sur vingt-sept mille hommes qui restaient. Benhadad s''était enfui et il allait dans la ville de chambre en chambre.'),
('1r',20,31,'crampon1923','Ses serviteurs lui dirent: « Voici, nous avons appris que les rois de la maison d''Israël sont des rois cléments; permets que nous mettions des sacs sur nos reins et des cordes à nos têtes, et que nous sortions vers le roi d''Israël: peut-être qu''il te laissera la vie. »'),
('1r',20,32,'crampon1923','Ils se mirent des sacs sur les reins et des cordes à la tête et, s''étant rendus auprès du roi d''Israël, ils dirent: « Ton serviteur Benhadad dit: Daigne me laisser la vie! » Achab répondit: « Est-il encore vivant? Il est mon frère. »'),
('1r',20,33,'crampon1923','Ces hommes tirèrent de là un heureux augure, et se hâtant de lui ravir cette parole, ils dirent: « Benhadad est ton frère. » Et il dit: « Allez le prendre. » Benhadad vint vers lui, et Achab le fit monter sur son char.'),
('1r',20,34,'crampon1923','Benhadad lui dit: « Je te rendrai les villes que mon père a prises à ton père, et tu établiras pour toi des rues à Damas, comme mon père en avait établi à Samarie. » Et Achab répondit: « Et moi, je te laisserai aller moyennant un traité d''alliance. » Il conclut une alliance avec lui, et le laissa aller.'),
('1r',20,35,'crampon1923','Un des fils des prophètes dit à son compagnon, dans la parole de Yahweh: « Frappe-moi, je te prie. » Mais cet homme refusa de le frapper.'),
('1r',20,36,'crampon1923','Et il lui dit: « Parce que tu n''as pas écouté la voix de Yahweh, voici, dès que tu m''auras quitté, le lion te frappera. » Et l''homme s''en alla d''auprès de lui, et le lion, l''ayant rencontré, le frappa.'),
('1r',20,37,'crampon1923','Il trouva un autre homme, et il lui dit: « Frappe-moi, je te prie. » Cet homme le frappa et le blessa.'),
('1r',20,38,'crampon1923','Alors le prophète alla se placer sur le chemin du roi, et il se déguisa avec un bandeau sur ses yeux.'),
('1r',20,39,'crampon1923','Lorsque le roi passa, il cria vers le roi, en disant: « Ton serviteur était sorti au milieu du combat; voici qu''un homme s''éloigna et m''amena un homme en disant: Garde cet homme. S''il vient à s''échapper, ta vie sera pour sa vie, ou tu paieras un talent d''argent.'),
('1r',20,40,'crampon1923','Et pendant que ton serviteur agissait çà et là, l''homme disparut. » Le roi d''Israël lui dit: « C''est là ton jugement; tu l''as rendu toi-même. »'),
('1r',20,41,'crampon1923','Aussitôt le prophète ôta le bandeau de ses yeux et le roi d''Israël le reconnut pour un des prophètes.'),
('1r',20,42,'crampon1923','Alors il dit au roi: « Ainsi dit Yahweh: Parce que tu as laissé échapper de tes mains l''homme que j''avais voué à l''anathème, ta vie sera pour sa vie et ton peuple pour son peuple. »'),
('1r',20,43,'crampon1923','Le roi d''Israël s''en alla chez lui, sombre et irrité, et il arriva à Samarie.'),
('1r',21,1,'crampon1923','Après ces événements, comme Naboth de Jezrahel avait une vigne à Jezrahel, à côté du palais d''Achab, roi de Samarie,'),
('1r',21,2,'crampon1923','Achab parla à Naboth en ces termes: « Cède-moi ta vigne pour qu''elle me serve de jardin potager, car elle est tout près de ma maison; je te donnerai à la place une vigne meilleure, ou, si cela te convient, de l''argent pour sa valeur. »'),
('1r',21,3,'crampon1923','Naboth répondit à Achab: « Que Yahweh me garde de te donner l''héritage de mes pères! »'),
('1r',21,4,'crampon1923','Achab rentra dans sa maison sombre et irrité à cause de cette parole que lui avait dite Naboth de Jezrahel: « Je ne donnerai pas l''héritage de mes pères. » Et, se couchant sur son lit, il détourna le visage et ne mangea pas.'),
('1r',21,5,'crampon1923','Jézabel, sa femme, vint auprès de lui et lui dit: « Pourquoi as-tu l''âme sombre et ne manges-tu pas? »'),
('1r',21,6,'crampon1923','Il lui répondit: « J''ai parlé à Naboth de Jezrahel et je lui ai dit: Cède-moi ta vigne pour de l''argent; ou, si tu l''aimes mieux, je te donnerai une autre vigne à la place. Mais il a dit: Je ne te donnerai pas ma vigne. »'),
('1r',21,7,'crampon1923','Alors Jézabel, sa femme, lui dit: « Est-ce toi qui exerces maintenant la royauté sur Israël? Lève-toi, prends de la nourriture, et que ton cœur se réjouisse; je te donnerai, moi, la vigne de Naboth de Jezrahel. »'),
('1r',21,8,'crampon1923','Et elle écrivit au nom d''Achab une lettre qu''elle scella du sceau du roi, et elle envoya la lettre aux anciens et aux magistrats qui étaient dans la ville et habitaient avec Naboth.'),
('1r',21,9,'crampon1923','Voici ce qu''elle écrivit dans la lettre: « Publiez un jeûne; placez Naboth en tête du peuple,'),
('1r',21,10,'crampon1923','et mettez en face du lui deux hommes de Bélial qui déposeront contre lui en ces termes: Tu as maudit Dieu et le roi! Puis menez-le dehors, lapidez-le, et qu''il meure. »'),
('1r',21,11,'crampon1923','Les gens de la ville de Naboth, les anciens et les magistrats qui habitaient dans sa ville, firent selon que leur avait envoyé dire Jézabel, selon qu''il était écrit dans la lettre qu''elle leur avait envoyée.'),
('1r',21,12,'crampon1923','Ils publièrent un jeûne, et ils placèrent Naboth en tête du peuple,'),
('1r',21,13,'crampon1923','et les deux hommes, fils de Bélial, vinrent se mettre en face de lui. Ces hommes de Bélial déposèrent contre Naboth devant le peuple en ces termes: « Naboth a maudit Dieu et le roi! » Puis ils le menèrent hors de la ville et le lapidèrent, et il mourut.'),
('1r',21,14,'crampon1923','Et ils envoyèrent dire à Jézabel: « Naboth a été lapidé, et il est mort. »'),
('1r',21,15,'crampon1923','Lorsque Jézabel eut appris que Naboth avait été lapidé et qu''il était mort, elle dit à Achab: « Lève-toi, prends possession de la vigne de Naboth de Jezrahel, qui a refusé de te la céder pour de l''argent; car Naboth n''est plus en vie, car il est mort. »'),
('1r',21,16,'crampon1923','Lorsqu''Achab eut appris que Naboth était mort, il se leva pour descendre à la vigne de Naboth de Jezrahel, afin d''en prendre possession.'),
('1r',21,17,'crampon1923','Alors la parole de Yahweh fut adressée à Elie, le Thesbite, en ces termes:'),
('1r',21,18,'crampon1923','« Lève-toi, descends au devant d''Achab, roi d''Israël, qui règne à Samarie; le voilà dans la vigne de Naboth, où il est descendu pour en prendre possession.'),
('1r',21,19,'crampon1923','Tu lui parleras en ces termes: Ainsi dit Yahweh: “N''as-tu pas tué et pris un héritage?” Et tu lui parleras en ces termes: “Ainsi dit Yahweh: Au lieu même où les chiens ont léché le sang de Naboth, les chiens lécheront aussi ton propre sang.” »'),
('1r',21,20,'crampon1923','Achab dit à Elie: « M''as-tu trouvé, ô mon ennemi? » Il répondit: « Je t''ai trouvé, parce que tu t''es vendu pour faire ce qui est mal aux yeux de Yahweh.'),
('1r',21,21,'crampon1923','Voici que je ferai venir le malheur sur toi; je te balaierai; j''exterminerai tout mâle appartenant à Achab, celui qui est esclave et celui qui est libre en Israël,'),
('1r',21,22,'crampon1923','et je rendrai ta maison semblable à la maison de Jéroboam, fils de Nabat, et à la maison de Baasa, fils d''Ahias, parce que tu m''as provoqué à la colère et que tu as fait pécher Israël. »'),
('1r',21,23,'crampon1923','Yahweh parla aussi contre Jézabel en ces termes: « Les chiens mangeront Jézabel près du fossé de Jezrahel.'),
('1r',21,24,'crampon1923','Celui de la maison d''Achab qui mourra dans la ville sera mangé par les chiens, et celui qui mourra dans les champs sera mangé par les oiseaux du ciel. »'),
('1r',21,25,'crampon1923','Il n''y a eu vraiment personne qui se soit vendu comme Achab pour faire ce qui est mal aux yeux de Yahweh; parce que Jézabel, sa femme, l''excitait.'),
('1r',21,26,'crampon1923','Il s''est conduit de la manière la plus abominable, en allant après les idoles, selon tout ce que faisaient les Amorrhéens que Yahweh chassa devant les enfants d''Israël.'),
('1r',21,27,'crampon1923','Lorsqu''Achab eut entendu les paroles d''Elie, il déchira ses vêtements et, ayant mis un sac sur son corps, il jeûna; il couchait avec le sac et il marchait avec lenteur.'),
('1r',21,28,'crampon1923','Et la parole de Yahweh fut adressée à Elie le Thesbite, en ces termes:'),
('1r',21,29,'crampon1923','« As-tu vu comment Achab s''est humilié devant moi? Parce qu''il s''est humilié devant moi, je ne ferai pas venir le malheur pendant sa vie; ce sera pendant la vie de son fils que je ferai venir le malheur sur sa maison. »'),
('1r',22,1,'crampon1923','On se reposa pendant trois ans, sans qu''il y eût guerre entre la Syrie et Israël.'),
('1r',22,2,'crampon1923','La troisième année, Josaphat, roi de Juda, descendit auprès du roi d''Israël.'),
('1r',22,3,'crampon1923','Le roi d''Israël dit à ses serviteurs: « Savez-vous que Ramoth-en-Galaad est à nous? Et nous ne faisons rien pour la reprendre des mains du roi de Syrie! »'),
('1r',22,4,'crampon1923','Et il dit à Josaphat: « Viendras-tu avec moi attaquer Ramoth-en-Galaad? » Josaphat répondit au roi d''Israël: « Il en sera de moi comme de toi, de mon peuple comme de ton peuple, de mes chevaux comme de tes chevaux. »'),
('1r',22,5,'crampon1923','Josaphat dit alors au roi d''Israël: « Consulte maintenant, je te prie, la parole de Yahweh. »'),
('1r',22,6,'crampon1923','Le roi d''Israël assembla les prophètes, au nombre de quatre cents environ, et leur dit: « Irai-je attaquer Ramoth-en-Galaad, ou m''en abstiendrai-je? » Ils répondirent: « Monte, et le Seigneur la livrera entre les mains du roi. »'),
('1r',22,7,'crampon1923','Mais Josaphat dit: « N''y a-t-il plus ici aucun prophète de Yahweh, par qui nous puissions l''interroger? »'),
('1r',22,8,'crampon1923','Le roi d''Israël répondit à Josaphat: « Il y a encore ici un homme par qui l''on pourrait consulter Yahweh; mais je le hais, car il ne prophétise sur moi rien de bon, mais seulement du mal: c''est Michée, fils de Jemla. » Et Josaphat dit: « Que le roi ne parle pas ainsi! »'),
('1r',22,9,'crampon1923','Alors le roi d''Israël, appelant un eunuque, lui dit: « Fais venir de suite Michée, fils de Jemla. »'),
('1r',22,10,'crampon1923','Le roi d''Israël et Josaphat roi de Juda, étaient assis chacun sur son trône, revêtus de leurs habits royaux, dans la place, à l''entrée de la porte de Samarie; et tous les prophètes prophétisaient devant eux.'),
('1r',22,11,'crampon1923','Sédécias, fils de Chanaana, s''était fait des cornes de fer, et il dit: « Ainsi dit Yahweh: Avec ces cornes tu frapperas les Syriens jusqu''à les exterminer. »'),
('1r',22,12,'crampon1923','Et tous les prophètes prophétisaient de même, en disant: « Monte à Ramoth-en-Galaad et sois vainqueur, car Yahweh la livrera entre les mains du roi. »'),
('1r',22,13,'crampon1923','Le messager qui était allé appeler Michée lui parla en ces termes: « Voici que les paroles des prophètes sont unanimes pour annoncer du bien au roi; que ta parole soit donc conforme à la parole de chacun d''eux: annonce du bien. »'),
('1r',22,14,'crampon1923','Michée répondit: « Yahweh est vivant! Ce que Yahweh me dira, je l''annoncerai. »'),
('1r',22,15,'crampon1923','Lorsqu''il fut arrivé près du roi, le roi lui dit: « Michée, irons-nous attaquer Ramoth-en-Galaad, ou nous en abstiendrons-nous? » Il lui répondit: « Monte et sois vainqueur, car Yahweh la livrera entre les mains du roi. »')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('1r',22,16,'crampon1923','Et le roi lui dit: « Jusqu''à combien de fois t''adjurerai-je de ne me dire que la vérité au nom de Yahweh? »'),
('1r',22,17,'crampon1923','Michée répondit: « Je vois tout Israël dispersé sur les montagnes, comme les brebis qui n''ont pas de berger; et Yahweh a dit: Ces gens n''ont pas de maître; qu''ils retournent en paix, chacun dans sa maison! »'),
('1r',22,18,'crampon1923','Le roi d''Israël dit à Josaphat: « Ne te l''ai-je pas dit? Il ne prophétise sur moi rien de bon, mais seulement du mal. »'),
('1r',22,19,'crampon1923','Et Michée dit: « Ecoute donc la parole de Yahweh: J''ai vu Yahweh assis sur son trône, et toute l''armée du ciel se tenait auprès de lui, à sa droite et à sa gauche.'),
('1r',22,20,'crampon1923','Et Yahweh dit: Qui trompera Achab, pour qu''il monte à Ramoth-en-Galaad et qu''il y périsse? Ils répondirent l''un d''une manière, l''autre d''une autre.'),
('1r',22,21,'crampon1923','Alors l''esprit vint se tenir devant Yahweh et dit: Moi, je le tromperai. Yahweh lui dit: Comment?'),
('1r',22,22,'crampon1923','Il répondit: Je sortirai et je serai un esprit de mensonge dans la bouche de tous ses prophètes. Yahweh dit: Tu le tromperas et tu en viendras à bout; sors, et fais ainsi.'),
('1r',22,23,'crampon1923','Voici donc que Yahweh a mis un esprit de mensonge dans la bouche de tous tes prophètes qui sont là. Et Yahweh a prononcé du mal sur toi. »'),
('1r',22,24,'crampon1923','Mais Sédécias, fils de Chanaana, s''étant approché, frappa Michée sur la joue et dit: « Par où l''esprit de Yahweh est-il sorti de moi pour te parler? »'),
('1r',22,25,'crampon1923','Michée répondit: « Voici que tu le verras en ce jour-là où tu iras de chambre en chambre pour te cacher. »'),
('1r',22,26,'crampon1923','Le roi d''Israël dit: « Prends Michée, et amène-le à Amon, gouverneur de la ville, et à Joas, fils du roi.'),
('1r',22,27,'crampon1923','Tu leur diras: Ainsi dit le roi: Mettez cet homme en prison, et nourrissez-le du pain de l''affliction et de l''eau d''affliction, jusqu''à ce que je vienne en paix. »'),
('1r',22,28,'crampon1923','Et Michée dit: « Si vraiment tu reviens en paix, Yahweh n''a point parlé par moi. » Il ajouta: « Entendez, vous tous, peuples. »'),
('1r',22,29,'crampon1923','Le roi d''Israël et Josaphat, roi de Juda, montèrent à Ramoth-en-Galaad.'),
('1r',22,30,'crampon1923','Le roi d''Israël dit à Josaphat: « Je veux me déguiser pour aller au combat; mais toi, revêts-toi de tes habits. » Et le roi d''Israël se déguisa et alla au combat.'),
('1r',22,31,'crampon1923','Le roi de Syrie avait donné un ordre aux trente-deux chefs de ses chars, en ces termes: « Vous n''attaquerez ni petit ni grand, mais seulement le roi d''Israël. »'),
('1r',22,32,'crampon1923','Quand les chefs des chars virent Josaphat, ils dirent: « Sûrement, c''est le roi d''Israël! » et ils se tournèrent contre lui pour l''attaquer. Josaphat poussa un cri.'),
('1r',22,33,'crampon1923','Quand les chefs des chars virent que ce n''était pas le roi d''Israël, ils se détournèrent de lui.'),
('1r',22,34,'crampon1923','Alors un homme tira de son arc au hasard et atteignit le roi d''Israël entre les jointures et la cuirasse. Le roi dit à celui qui conduisait son char: « Tourne, et fais-moi sortir du camp, car je suis blessé. »'),
('1r',22,35,'crampon1923','Le combat devint violent, ce jour-là. Le roi était tenu debout sur son char en face des Syriens, et il mourut le soir; le sang de la blessure coula dans l''intérieur du char.'),
('1r',22,36,'crampon1923','Vers le coucher du soleil, ce cri courut dans le camp: « Chacun à sa ville et chacun à son pays! »'),
('1r',22,37,'crampon1923','Ainsi mourut le roi. Il fut ramené à Samarie, et l''on enterra le roi à Samarie.'),
('1r',22,38,'crampon1923','Lorsqu''on lava le char à l''étang de Samarie, les chiens léchèrent le sang d''Achab et les prostituées s''y baignèrent, selon la parole que Yahweh avait dite.'),
('1r',22,39,'crampon1923','Le reste des actes d''Achab, tout ce qu''il a fait, la maison d''ivoire qu''il a bâtie et toutes les villes qu''il a bâties, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('1r',22,40,'crampon1923','Achab se coucha avec ses pères; et Ochozias, son fils, régna à sa place.'),
('1r',22,41,'crampon1923','Josaphat, fils d''Asa, devint roi de Juda la quatrième année d''Achab, roi d''Israël.'),
('1r',22,42,'crampon1923','Josaphat avait trente-cinq ans lorsqu''il devint roi, et il régna vingt-cinq ans à Jérusalem. Sa mère se nommait Azuba, fille de Salaï.'),
('1r',22,43,'crampon1923','Il marcha dans toute la voie d''Asa, son père, et ne s''en détourna point, faisant ce qui est droit aux yeux de Yahweh.'),
('1r',22,44,'crampon1923','Seulement les hauts lieux ne disparurent pas; le peuple continua d''offrir des sacrifices et des parfums sur les hauts lieux.'),
('1r',22,45,'crampon1923','Josaphat fut en paix avec le roi d''Israël.'),
('1r',22,46,'crampon1923','Le reste des actes de Josaphat, les exploits qu''il accomplit, et les guerres qu''il fit, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('1r',22,47,'crampon1923','Il ôta du pays le reste des prostitués qui y étaient encore demeurés au temps d''Asa, son père.'),
('1r',22,48,'crampon1923','Il n''y avait pas alors de roi en Edom; un gouverneur remplissait les fonctions de roi.'),
('1r',22,49,'crampon1923','Josaphat construisit dix vaisseaux de Tharsis pour aller à Ophir chercher de l''or; mais il n''y alla point, parce que les vaisseaux se brisèrent à Asiongaber.'),
('1r',22,50,'crampon1923','Alors Ochozias, fils d''Achab, dit à Josapahat: « Permets que mes serviteurs aillent avec tes serviteurs sur les vaisseaux. » Mais Josaphat ne voulut pas.'),
('1r',22,51,'crampon1923','Josaphat se coucha avec ses pères, et il fut enterré avec ses pères dans la ville de David, son père; Joram, son fils, régna à sa place.'),
('1r',22,52,'crampon1923','Ochozias, fils d''Achab, devint roi d''Israël à Samarie la dix-septième année de Josaphat, roi de Juda. Il régna deux ans sur Israël.'),
('1r',22,53,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, et il marcha dans la voie de son père et dans la voie de sa mère, et dans la voie de Jéroboam, fils de Nabat, qui avait fait pécher Israël.'),
('1r',22,54,'crampon1923','Il servit Baal et se prosterna devant lui, et il irrita Yahweh, Dieu d''Israël, selon tout ce qu''avait fait son père.'),
('2r',1,1,'crampon1923','Moab se révolta contre Israël, après la mort d''Achab.'),
('2r',1,2,'crampon1923','Ochozias tomba par la fenêtre en treillis de sa chambre haute à Samarie, et il fut malade. Il envoya des messagers et leur dit: « Allez consulter Béel-Zébub, dieu d''Accaron, pour savoir si je guérirai de cette maladie. »'),
('2r',1,3,'crampon1923','Mais l''ange de Yahweh dit à Elie, le Thesbite: « Lève-toi, monte à la rencontre des messagers du roi de Samarie, et dis-leur: “Est-ce parce qu''il n''y a point de Dieu en Israël que vous allez consulter Béel-Zébub, dieu d''Accaron?”'),
('2r',1,4,'crampon1923','C''est pourquoi ainsi dit Yahweh: “Du lit sur lequel tu es monté, tu ne descendras pas, tu mourras certainement.” » Et Elie s''en alla.'),
('2r',1,5,'crampon1923','Les messagers retournèrent auprès d''Ochozias, et il leur dit: « Pourquoi revenez-vous? »'),
('2r',1,6,'crampon1923','Ils lui répondirent: « Un homme est monté à notre rencontre et nous a dit: Allez, retournez vers le roi qui vous a envoyés, et dites-lui: Ainsi dit Yahweh: Est-ce parce qu''il n''y a point de Dieu en Israël que tu envoies consulter Béel-Zébub, dieu d''Accaron? C''est pourquoi du lit sur lequel tu es monté, tu ne descendras pas, mais tu mourras certainement. »'),
('2r',1,7,'crampon1923','Ochozias leur dit: « Quel était l''aspect de l''homme qui est monté à votre rencontre et qui vous a dit ces paroles? »'),
('2r',1,8,'crampon1923','Ils lui répondirent: « C''était un homme velu, avec une ceinture de cuir autour des reins. » Et Ochozias dit: « C''est Elie, le Thesbite. »'),
('2r',1,9,'crampon1923','Aussitôt il envoya vers lui un chef de cinquante avec ses cinquante hommes. Ce chef monta auprès d''Elie, et voici qu''il était assis sur le sommet de la montagne, et il lui dit: « Homme de Dieu, le roi a dit: Descends! »'),
('2r',1,10,'crampon1923','Elie répondit et dit au chef de cinquante: « Si je suis un homme de Dieu, que le feu descende du ciel et vous consume, toi et tes cinquante hommes? » Et le feu descendit du ciel et les consuma, lui et ses cinquante hommes.'),
('2r',1,11,'crampon1923','Ochozias envoya encore un autre chef de cinquante avec ses cinquante hommes. Ce chef, prenant la parole, dit à Elie: « Homme de Dieu, ainsi a dit le roi: Hâte-toi, descends! »'),
('2r',1,12,'crampon1923','Elie répondit et leur dit: « Si je suis un homme de Dieu, que le feu descende du ciel et vous consume, toi et tes cinquante hommes! » Et le feu de Dieu descendit du ciel, et les consuma, lui et ses cinquante hommes.'),
('2r',1,13,'crampon1923','De nouveau Ochozias envoya un troisième chef de cinquante avec ses cinquante hommes. Le troisième chef de cinquante monta, et, étant arrivé, il fléchit les genoux devant Elie, et lui dit en suppliant: « Homme de Dieu, de grâce, que ma vie et que la vie de ces cinquante hommes, tes serviteurs, soit précieuse à tes yeux!'),
('2r',1,14,'crampon1923','Voici que le feu est descendu du ciel et a consumé les deux premiers chefs de cinquante et leur cinquante hommes; mais maintenant que ma vie soit précieuse à tes yeux! »'),
('2r',1,15,'crampon1923','L''ange de Yahweh dit à Elie: « Descends avec lui, et ne crains pas devant lui. » Elie se leva et descendit avec lui vers le roi.'),
('2r',1,16,'crampon1923','Il lui dit: « Ainsi dit Yahweh: Parce que tu as envoyé des messagers consulter Béel-Zébub, dieu d''Accaron, — n''y a-t-il pas de Dieu en Israël dont on puisse consulter la parole? — à cause de cela, du lit sur lequel tu es monté tu ne descendras pas, mais tu mourras certainement. »'),
('2r',1,17,'crampon1923','Ochozias mourut, selon la parole de Yahweh qu''Elie avait dite; et Joram devint roi à sa place, la seconde année de Joram, fils de Josaphat, roi de Juda; car il n''avait pas de fils.'),
('2r',1,18,'crampon1923','Le reste des actes d''Ochozias, ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('2r',2,1,'crampon1923','Lorsque Yahweh fit monter Elie au ciel dans un tourbillon, Elie s''en allait de Galgala avec Elisée.'),
('2r',2,2,'crampon1923','Elie dit à Elisée: « Reste ici, je te prie, car Yahweh m''envoie jusqu''à Béthel. » Elisée répondit: « Yahweh est vivant et ton âme est vivante! Je ne te quitterai point! » Et ils descendirent à Béthel.'),
('2r',2,3,'crampon1923','Les fils des prophètes qui étaient à Béthel sortirent vers Elisée, et lui dirent: « Sais-tu que Yahweh enlèvera aujourd''hui ton maître de dessus ta tête? » Il répondit: « Je le sais aussi; tenez-vous en paix. »'),
('2r',2,4,'crampon1923','Elie lui dit: « Elisée, reste ici, je te prie, car Yahweh m''envoie à Jéricho. » Il répondit: « Yahweh est vivant et ton âme est vivante! Je ne te quitterai point! » Et ils arrivèrent à Jéricho.'),
('2r',2,5,'crampon1923','Les fils des prophètes qui étaient à Jéricho s''approchèrent d''Elisée et lui dirent: « Sais-tu que Yahweh enlèvera aujourd''hui ton maître de dessus ta tête? » Il répondit: « Je le sais aussi; tenez-vous en paix. »'),
('2r',2,6,'crampon1923','Elie lui dit: « Reste ici, je te prie, car Yahweh m''envoie au Jourdain. » Il répondit: « Yahweh est vivant et ton âme est vivante! Je ne te quitterai point! » Et ils s''en allèrent tous deux.'),
('2r',2,7,'crampon1923','Cinquante hommes d''entre les fils des prophètes allèrent après eux et se tinrent à distance, à l''opposé, et eux deux s''arrêtèrent au bord du Jourdain.'),
('2r',2,8,'crampon1923','Alors Elie, prenant son manteau, le roula et en frappa les eaux, qui se partagèrent d''un côté et de l''autre, et ils passèrent tous deux à sec.'),
('2r',2,9,'crampon1923','Lorsqu''ils eurent passé, Elie dit à Elisée: « Demande ce que tu veux que je fasse pour toi, avant que je sois enlevé d''avec toi. » Elisée répondit: « Que vienne sur moi une double portion de ton esprit? »'),
('2r',2,10,'crampon1923','Elie dit: « Tu demandes une chose difficile. Si tu me vois pendant que je serai enlevé d''avec toi, il t''arrivera ainsi; sinon, cela n''arrivera pas. »'),
('2r',2,11,'crampon1923','Ils continuaient de marcher en s''entretenant, et voici qu''un char de feu et des chevaux de feu les séparèrent l''un de l''autre, et Elie monta au ciel dans un tourbillon.'),
('2r',2,12,'crampon1923','Elisée regardait et criait: « Mon père! mon père! Char d''Israël et ses cavaliers! » Et il ne le vit plus. Il saisit alors ses vêtements et les déchira en deux morceaux,'),
('2r',2,13,'crampon1923','et il releva le manteau d''Elie qui était tombé de dessus lui. Puis, étant revenu au Jourdain, il s''arrêta sur le bord;'),
('2r',2,14,'crampon1923','et, prenant le manteau d''Elie qui était tombé de dessus lui, il en frappa les eaux et dit: « Où est Yahweh, le Dieu d''Elie? Où est-il? » Lorsqu''il eut frappé les eaux, elles se partagèrent d''un côté et de l''autre, et Elisée passa.'),
('2r',2,15,'crampon1923','Les fils des prophètes qui étaient à Jéricho, à l''opposé, le virent et dirent: « L''esprit d''Elie repose sur Elisée; » et, allant à sa rencontre, ils se prosternèrent contre terre devant lui.'),
('2r',2,16,'crampon1923','Ils lui dirent: « Voici qu''il y a parmi tes serviteurs cinquante hommes vaillants: qu''ils aillent donc chercher ton maître. Peut-être que l''Esprit de Yahweh, l''ayant emporté, l''a jeté sur une des montagnes ou dans une des vallées. » Il répondit: « Ne les envoyez pas. »'),
('2r',2,17,'crampon1923','Mais ils le pressèrent jusqu''à le couvrir de confusion, et il leur dit: « Envoyez-les. » Ils envoyèrent cinquante hommes, qui cherchèrent Elie pendant trois jours, sans le trouver.'),
('2r',2,18,'crampon1923','Lorsqu''ils furent de retour auprès d''Elisée, — car il demeurait à Jéricho, — il leur dit: « Ne vous avais-je pas dit: N''allez pas? »'),
('2r',2,19,'crampon1923','Les gens de la ville dirent à Elisée: « Le séjour de la ville est bon, comme le voit mon seigneur; mais les eaux sont mauvaises et le pays est stérile. »'),
('2r',2,20,'crampon1923','Il dit: « Apportez-moi une écuelle neuve, et mettez-y du sel. » Et ils la lui apportèrent.'),
('2r',2,21,'crampon1923','Il alla vers la source des eaux et, y ayant jeté du sel, il dit: « Ainsi dit Yahweh: J''assainis ces eaux; il n''en proviendra plus ni mort, ni stérilité. »'),
('2r',2,22,'crampon1923','Et les eaux furent assainies jusqu''à ce jour, selon la parole qu''Elisée avait dite.'),
('2r',2,23,'crampon1923','Il monta de là à Béthel; et comme il montait par la route, des petits garçons sortirent de la ville et se moquèrent de lui; ils lui disaient: « Monte, chauve! monte, chauve! »'),
('2r',2,24,'crampon1923','Il se retourna pour les regarder, et il les maudit au nom de Yahweh. Et deux ours sortirent de la forêt et déchirèrent quarante-deux de ces enfants.'),
('2r',2,25,'crampon1923','De là il alla sur la montagne de Carmel, et de là il revint à Samarie.'),
('2r',3,1,'crampon1923','Joram, fils d''Achab, devint roi d''Israël à Samarie la dix-huitième année de Josaphat, roi de Juda; et il régna douze ans.'),
('2r',3,2,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, non pas toutefois comme son père et sa mère; car il fit disparaître la stèle de Baal, que son père avait faite.'),
('2r',3,3,'crampon1923','Mais il s''attacha aux péchés de Jéroboam, fils de Nabat, qui avait fait pécher Israël, et il ne s''en détourna point.'),
('2r',3,4,'crampon1923','Mésa, roi de Moab, possédait des troupeaux, et il payait au roi d''Israël un tribut de cent mille agneaux et de cent mille béliers avec leurs toisons.'),
('2r',3,5,'crampon1923','A la mort d''Achab, le roi de Moab se révolta contre le roi d''Israël.'),
('2r',3,6,'crampon1923','Le roi Joram sortit donc en ce jour-là de Samarie et passa en revue tout Israël.'),
('2r',3,7,'crampon1923','S''étant mis en marche, il envoya dire à Josaphat, roi de Juda: « Le roi de Moab s''est révolté contre moi; viendras-tu avec moi attaquer Moab? » Josaphat répondit: « Je monterai; il en sera de moi comme de toi, de mon peuple comme de ton peuple, de mes chevaux comme de tes chevaux. »'),
('2r',3,8,'crampon1923','Et il dit: « Par quel chemin monterons-nous? » Joram répondit: « Par le chemin du désert d''Edom. »'),
('2r',3,9,'crampon1923','Le roi d''Israël, le roi de Juda et le roi d''Edom partirent. Après une marche de sept jours, il n''y eut point d''eau pour l''armée et pour les bêtes qui la suivaient.'),
('2r',3,10,'crampon1923','Alors le roi d''Israël dit: « Hélas! Yahweh a appelé ces trois rois pour les livrer aux mains de Moab! »'),
('2r',3,11,'crampon1923','Mais Josaphat dit: « N''y a-t-il ici aucun prophète de Yahweh, par qui nous puissions consulter Yahweh? » Un des serviteurs du roi d''Israël répondit et dit: « Il y a ici Elisée, fils de Saphat, qui versait l''eau sur les mains d''Elie. »'),
('2r',3,12,'crampon1923','Et Josaphat dit: « La parole de Yahweh est avec lui. » Le roi d''Israël, Josaphat, roi de Juda, et le roi d''Edom descendirent auprès de lui.'),
('2r',3,13,'crampon1923','Elisée dit au roi d''Israël: « Que me veux-tu, toi? Va vers les prophètes de ton père et vers les prophètes de ta mère. » Et le roi d''Israël lui dit: « Non, car Yahweh a appelé ces trois rois pour les livrer entre les mains de Moab. »'),
('2r',3,14,'crampon1923','Elisée dit: « Yahweh des armées, devant qui je me tiens, est vivant! Si je n''avais égard à Josaphat, roi de Juda, je ne ferais aucune attention à toi et je ne te regarderais pas.'),
('2r',3,15,'crampon1923','Maintenant, amenez-moi un joueur de harpe. » Et pendant que le joueur de harpe jouait, la main de Yahweh fut sur Elisée;'),
('2r',3,16,'crampon1923','et il dit: « Ainsi dit Yahweh: Faites dans cette vallée des fosses et des fosses.'),
('2r',3,17,'crampon1923','Car ainsi dit Yahweh: Vous ne verrez point de vent et vous ne verrez point de pluie, et cette vallée se remplira d''eau, et vous boirez, vous, vos troupeaux et vos bêtes de somme.'),
('2r',3,18,'crampon1923','Mais cela est peu de chose aux yeux de Yahweh: il livrera Moab entre vos mains.'),
('2r',3,19,'crampon1923','Vous frapperez toutes les villes fortes et toutes les villes de choix, vous abattrez tous les arbres fruitiers, vous boucherez toutes les sources d''eau, et vous désolerez, en les couvrant de pierres, tous les meilleurs champs. »'),
('2r',3,20,'crampon1923','De fait le matin, à l''heure où l''on offre l''oblation, voici que l''eau arriva par le chemin d''Edom, et le pays fut rempli d''eau.'),
('2r',3,21,'crampon1923','Cependant, tous les Moabites ayant appris que les rois montaient pour les attaquer, on convoqua tous les hommes capables de ceindre le baudrier, et même au-delà, et ils se postèrent sur la frontière.'),
('2r',3,22,'crampon1923','Ils se levèrent de bon matin et, quand le soleil brilla sur les eaux, les Moabites virent en face d''eux les eaux rouges comme du sang.'),
('2r',3,23,'crampon1923','Ils dirent: « C''est du sang! Les rois sont détruits, ils se sont frappés les uns les autres; et maintenant Moabites, au pillage! »'),
('2r',3,24,'crampon1923','Et ils s''avancèrent vers le camp d''Israël. Mais les Israélites se levèrent et frappèrent Moab, qui prit la fuite devant eux. Pénétrant dans le pays, ils frappèrent Moab;'),
('2r',3,25,'crampon1923','ils détruisirent les villes; chacun jetant sa pierre dans tous les meilleurs champs, ils les en remplirent; ils bouchèrent toutes les sources d''eau, ils abattirent tous les arbres fruitiers, au point que de Qir-Charoseth il ne resta que les pierres; les frondeurs l''avaient entourée et battue.'),
('2r',3,26,'crampon1923','Quand le roi de Moab vit qu''il avait le dessous dans le combat, il prit avec lui sept cents hommes, l''épée nue à la main, pour se frayer un passage jusqu''au roi d''Edom; mais ils ne purent y réussir.'),
('2r',3,27,'crampon1923','Prenant alors son fils premier-né, qui devait régner à sa place, il l''offrit en holocauste sur la muraille. Et une grande indignation s''empara d''Israël; et ils s''éloignèrent du roi de Moab et retournèrent dans leur pays.'),
('2r',4,1,'crampon1923','Une femme d''entre les femmes des fils de prophètes cria vers Elisée, en disant: « Ton serviteur mon mari est mort, et tu sais que ton serviteur craignait Yahweh; or le créancier est venu prendre mes deux enfants pour en faire ses esclaves. »'),
('2r',4,2,'crampon1923','Elisée lui dit: « Que puis-je faire pour toi? Dis-moi, qu''as-tu à la maison? » Elle répondit: « Ta servante n''a rien du tout à la maison, si ce n''est un vase d''huile. »'),
('2r',4,3,'crampon1923','Il dit: « Va demander au dehors des vases à tous tes voisins, des vases vides; n''en emprunte pas trop peu.'),
('2r',4,4,'crampon1923','Quand tu seras rentrée, tu fermeras la porte sur toi et sur tes enfants; tu verseras de ton huile dans tous ces vases, et ceux qui seront pleins, tu les mettras de côté. »'),
('2r',4,5,'crampon1923','Alors elle le quitta. Elle ferma la porte sur elle et sur ses enfants; ils approchaient d''elle les vases, et elle versait.'),
('2r',4,6,'crampon1923','Lorsque les vases furent pleins, elle dit à son fils: « Approche encore de moi un vase. » Mais il lui répondit: « Il n''y a plus de vase. » Et l''huile s''arrêta.'),
('2r',4,7,'crampon1923','Elle alla le rapporter à l''homme de Dieu, et il dit: « Va vendre l''huile et paie ta dette; et tu vivras, toi et tes fils, de ce qui restera. »'),
('2r',4,8,'crampon1923','Un jour Elisée passait par Sunam. Il y avait là une femme riche, qui le pressa d''accepter à manger; et toutes les fois qu''il passait, il se rendait chez elle pour manger.'),
('2r',4,9,'crampon1923','Elle dit à son mari: « Voici, je sais que c''est un saint homme de Dieu, qui passe ainsi souvent chez nous.'),
('2r',4,10,'crampon1923','Faisons-lui une petite chambre haute contre le mur, et mettons-y pour lui un lit, une table, un siège et un chandelier, afin qu''il s''y retire quand il viendra chez nous. »'),
('2r',4,11,'crampon1923','Elisée, étant revenu un autre jour à Sunam, se retira dans la chambre haute et y coucha.'),
('2r',4,12,'crampon1923','Il dit à Giézi, son serviteur: « Appelle cette Sunamite. » Giézi l''appela, et elle se présenta devant lui.'),
('2r',4,13,'crampon1923','Et Elisée dit à Giézi: « Dis-lui: Voici que tu nous as témoigné toute cette sollicitude: que peut-on faire pour toi? Faut-il parler pour toi au roi ou au chef de l''armée? » Elle répondit à Giézi: « J''habite au milieu de mon peuple. »'),
('2r',4,14,'crampon1923','Et Elisée dit: « Que faire pour elle? » Giézi répondit: « Mais elle n''a point de fils, et son mari est vieux. »'),
('2r',4,15,'crampon1923','Et Elisée dit: « Appelle-la. » Giézi l''appela, et elle se tint à la porte.'),
('2r',4,16,'crampon1923','Et Elisée lui dit: « A cette même époque, dans un an, tu caresseras un fils. » Et elle dit: « Non, mon seigneur, homme de Dieu, ne trompe pas ta servante. »'),
('2r',4,17,'crampon1923','Et la femme conçut, et elle enfanta un fils, à la même époque, l''année suivante, comme Elisée le lui avait dit.'),
('2r',4,18,'crampon1923','L''enfant grandit. Un jour qu''il était allé trouver son père auprès des moissonneurs,'),
('2r',4,19,'crampon1923','il dit à son père: « Ma tête! ma tête! » Le père dit à son serviteur: « Porte-le à sa mère. »'),
('2r',4,20,'crampon1923','Le serviteur l''ayant emporté et amené à sa mère, l''enfant resta sur les genoux de sa mère jusqu''à midi, puis il mourut.'),
('2r',4,21,'crampon1923','Elle monta, le coucha sur le lit de l''homme de Dieu, ferma la porte sur lui et sortit.'),
('2r',4,22,'crampon1923','Elle appela son mari, et dit: « Envoie-moi, je te prie, un des serviteurs et une des ânesses, que je courre vers l''homme de Dieu, pour en revenir aussitôt. »'),
('2r',4,23,'crampon1923','Il dit: « Pourquoi aller aujourd''hui vers lui? Ce n''est ni la nouvelle lune, ni le sabbat. » Elle répondit: « Sois tranquille. »'),
('2r',4,24,'crampon1923','Et, ayant fait seller l''ânesse, elle dit à son serviteur: « Mène-moi et va; ne m''arrête pas en route sans que je te le dise. »'),
('2r',4,25,'crampon1923','Elle partit et se rendit vers l''homme de Dieu, sur la montagne du Carmel. L''homme de Dieu l''ayant aperçue de loin, dit à Giézi, son serviteur: « Voici la Sunamite.'),
('2r',4,26,'crampon1923','Cours donc à sa rencontre et dis-lui: Te portes-tu bien? Ton mari se porte-t-il bien? Ton enfant se porte-t-il bien? » Elle répondit: « Bien! »'),
('2r',4,27,'crampon1923','Dès qu''elle fut arrivée auprès de l''homme de Dieu, sur la montagne, elle saisit ses pieds. Giézi s''approcha pour la repousser; mais l''homme de Dieu dit: « Laisse-la, car son âme est dans l''amertume, et Yahweh me l''a caché et ne me l''a pas fait connaître. »'),
('2r',4,28,'crampon1923','Alors elle dit: « Ai-je demandé un fils à mon seigneur? N''ai-je pas dit: Ne me trompe pas? »'),
('2r',4,29,'crampon1923','Et Elisée dit à Giézi: « Ceins tes reins, prends mon bâton dans ta main et pars. Si tu rencontres quelqu''un, ne le salue pas, et si quelqu''un te salue, ne lui réponds pas. Tu mettras mon bâton sur le visage de l''enfant. »'),
('2r',4,30,'crampon1923','La mère de l''enfant dit: « Yahweh est vivant et ton âme est vivante! je ne te quitterai point. » Et Elisée se leva et la suivit.'),
('2r',4,31,'crampon1923','Giézi les avait devancés et il avait mis le bâton sur le visage de l''enfant; mais il n''y eut ni voix, ni signe d''attention. Il s''en retourna au-devant d''Elisée et lui rapporta la chose en disant: « L''enfant ne s''est pas réveillé. »'),
('2r',4,32,'crampon1923','Lorsqu''Elisée arriva dans la maison, voici que l''enfant était mort, couché sur son lit.'),
('2r',4,33,'crampon1923','Elisée entra et, ayant fermé la porte sur eux deux, il pria Yahweh.'),
('2r',4,34,'crampon1923','Et il monta et se coucha sur l''enfant; il mit sa bouche sur sa bouche, ses yeux sur ses yeux, ses mains sur ses mains, et il s''étendit sur lui; et la chair de l''enfant se réchauffa.'),
('2r',4,35,'crampon1923','Elisée s''éloigna, et il allait çà et là dans la maison; puis il remonta sur le lit et s''étendit sur l''enfant; et l''enfant éternua sept fois, et l''enfant ouvrit les yeux.'),
('2r',4,36,'crampon1923','Elisée appela Giézi, et dit: « Appelle la Sunamite. » Giézi l''ayant appelée, elle vint vers Elisée qui lui dit: « Prends ton fils. »'),
('2r',4,37,'crampon1923','Elle vint tomber à ses pieds et se prosterna contre terre; et, prenant son fils, elle sortit.'),
('2r',4,38,'crampon1923','Elisée revint à Galgala, et la famine était dans le pays. Comme les fils des prophètes étaient assis devant lui, il dit à son serviteur: « Mets le grand pot, et fais cuire un potage pour les fils des prophètes. »'),
('2r',4,39,'crampon1923','L''un d''eux sortit dans les champs pour cueillir des herbes; il trouva une espèce de vigne sauvage et il y cueillit des coloquintes sauvages, plein son vêtement. A son retour, il les coupa en morceaux dans le pot où se préparait le potage, sans qu''ils en eussent connaissance.'),
('2r',4,40,'crampon1923','On versa du potage à ces hommes pour qu''ils en mangent; mais dès qu''ils eurent mangé du potage, ils poussèrent des cris en disant: « La mort est dans le pot, homme de Dieu! » Et ils ne purent manger.'),
('2r',4,41,'crampon1923','Elisée dit: « Apportez-moi de la farine. » Il en jeta dans le pot et dit: « Verse aux gens, et qu''ils mangent. » Et il n''y avait plus rien de mauvais dans le pot.'),
('2r',4,42,'crampon1923','Un homme vint de Baal-Salisa, apportant à l''homme de Dieu du pain des prémices, savoir vingt pains d''orge, et du blé frais dans son sac. Elisée dit: « Donne aux gens, et qu''ils mangent. »'),
('2r',4,43,'crampon1923','Son serviteur répondit: « Comment mettrai-je cela devant cent personnes? » Mais Elisée dit: « Donne aux gens et qu''ils mangent. Car ainsi dit Yahweh: On mangera, et il y aura un reste. »'),
('2r',4,44,'crampon1923','Il mit donc les pains devant eux, et ils mangèrent et ils en eurent de reste, selon la parole de Yahweh.'),
('2r',5,1,'crampon1923','Naaman, chef de l''armée du roi de Syrie, était auprès de son maître un homme puissant et considéré, car c''était par lui que Yahweh avait accordé le salut aux Syriens; mais cet homme fort et vaillant était lépreux.'),
('2r',5,2,'crampon1923','Or les Syriens, étant sortis par bandes, avaient emmené captive une petite fille du pays d''Israël, qui était au service de la femme de Naaman.'),
('2r',5,3,'crampon1923','Elle dit à sa maîtresse: « Oh! Si mon seigneur était auprès du prophète qui est à Samarie, le prophète le délivrerait de sa lèpre. »'),
('2r',5,4,'crampon1923','Naaman vint rapporter ce propos à son maître, en disant: « La jeune fille du pays d''Israël a parlé de telle et telle manière. »'),
('2r',5,5,'crampon1923','Et le roi de Syrie dit: « Va, et j''enverrai une lettre au roi d''Israël. » Il partit, prenant avec lui dix talents d''argent, six mille sicles d''or et dix vêtements de rechange.'),
('2r',5,6,'crampon1923','Il porta au roi d''Israël la lettre où il était dit: « Or donc, quand cette lettre te sera parvenue, voici que tu sauras que je t''envoie Naaman, mon serviteur, pour que tu le délivres de sa lèpre. »'),
('2r',5,7,'crampon1923','Après avoir lu la lettre, le roi d''Israël déchira ses vêtements et dit: « Suis-je un dieu, capable de faire mourir et de faire vivre, qu''il envoie vers moi pour que je délivre un homme de sa lèpre? Sachez donc et voyez qu''il me cherche querelle. »'),
('2r',5,8,'crampon1923','Lorsqu''Elisée, homme de Dieu, apprit que le roi d''Israël avait déchiré ses vêtements, il envoya dire au roi: « Pourquoi as-tu déchiré tes vêtements? Qu''il vienne donc à moi, et il saura qu''il y a un prophète en Israël. »'),
('2r',5,9,'crampon1923','Naaman vint avec ses chevaux et son char, et il s''arrêta à la porte de la maison d''Elisée.'),
('2r',5,10,'crampon1923','Elisée lui envoya un messager pour lui dire: « Va, et lave-toi sept fois dans le Jourdain; ta chair te reviendra, et tu seras pur. »'),
('2r',5,11,'crampon1923','Naaman fut irrité, et il s''en alla, en disant: « Voici que je me disais: Il sortira vers moi, il se présentera lui-même, il invoquera le nom de Yahweh, son Dieu, il agitera sa main sur la plaie et délivrera le lépreux.'),
('2r',5,12,'crampon1923','Les fleuves de Damas, l''Abana et le Pharphar, ne valent-ils pas mieux que toutes les eaux d''Israël? Ne pourrais-je pas m''y laver et devenir pur? » Et se tournant, il s''en allait en colère.'),
('2r',5,13,'crampon1923','Ses serviteurs s''approchèrent pour lui parler, et ils dirent: « Mon père, si le prophète t''avait demandé quelque chose de difficile, ne l''aurais-tu pas fait? Combien plus dois-tu lui obéir, quand il t''a dit: Lave-toi, et tu seras pur? »'),
('2r',5,14,'crampon1923','Il descendit et se plongea sept fois dans le Jourdain, selon la parole de l''homme de Dieu; et sa chair redevint comme la chair d''un petit enfant, et il fut purifié.'),
('2r',5,15,'crampon1923','Naaman retourna vers l''homme de Dieu, avec toute sa suite. Quand il fut arrivé, il se présenta devant lui et dit: « Voici donc que je sais qu''il n''y a point de Dieu sur toute la terre, si ce n''est en Israël. Et maintenant, accepte donc un présent de la part de ton serviteur. »'),
('2r',5,16,'crampon1923','Elisée répondit: « Aussi vrai que Yahweh devant qui je me tiens est vivant, je n''accepterai pas! » Naaman le pressant d''accepter, il refusa.'),
('2r',5,17,'crampon1923','Et Naaman dit: « Sinon, permets que l''on donne de la terre à ton serviteur, la charge de deux mulets; car ton serviteur ne veut plus offrir à d''autres dieux ni holocauste ni sacrifice, si ce n''est à Yahweh.'),
('2r',5,18,'crampon1923','Toutefois, que Yahweh pardonne ceci à ton serviteur: Quand mon maître entre dans la maison de Remmon pour y adorer, et qu''il s''appuie sur ma main, je me prosterne aussi dans la maison de Remmon; daigne Yahweh pardonner à ton serviteur si je me prosterne dans la maison de Remmon! »'),
('2r',5,19,'crampon1923','Elisée lui dit: « Va en paix. » Et Naaman quitta Elisée. Il était à une certaine distance,'),
('2r',5,20,'crampon1923','lorsque Giézi, serviteur d''Elisée, homme de Dieu, dit en lui-même: « Voici que mon maître a ménagé Naaman, ce Syrien, en n''acceptant pas de sa main ce qu''il avait apporté. Yahweh est vivant! Je vais courir après lui et j''en obtiendrai quelque chose. »'),
('2r',5,21,'crampon1923','Et Giézi se mit à poursuivre Naaman. Naaman, le voyant courir après lui, descendit de son char pour aller à sa rencontre, et il dit: « Tout va-t-il bien? »'),
('2r',5,22,'crampon1923','Giézi répondit: « Tout va bien! Mon maître m''envoie te dire: Voici que viennent d''arriver chez moi deux jeunes gens de la montagne d''Ephraïm, d''entre les fils des prophètes; donne pour eux, je te prie, un talent d''argent et deux vêtements de rechange. »'),
('2r',5,23,'crampon1923','Naaman dit: « Consens à prendre deux talents. » Il le pressa d''accepter et, ayant serré deux talents d''argent dans deux sacs avec deux habits de rechange, il les remit à deux de ses serviteurs pour les porter devant Giézi.'),
('2r',5,24,'crampon1923','Arrivé à la colline, Giézi les prit de leurs mains et les déposa dans la maison, puis il renvoya les hommes, qui partirent.'),
('2r',5,25,'crampon1923','Et il alla se présenter à son maître. Elisée lui dit: « D''où viens-tu, Giézi? » Il répondit: « Ton serviteur n''est allé ni d''un côté ni d''un autre. »'),
('2r',5,26,'crampon1923','Mais Elisée lui dit: « Mon esprit n''est-il pas allé avec toi, lorsque cet homme a quitté son char pour venir à ta rencontre? Est-ce le moment d''accepter de l''argent, et d''accepter des vêtements et des oliviers et des vignes et des brebis et des bœufs et des serviteurs et des servantes?'),
('2r',5,27,'crampon1923','La lèpre de Naaman s''attachera à toi et à ta postérité pour toujours. » Et Giézi sortit de la présence d''Elisée avec une lèpre blanche comme la neige.'),
('2r',6,1,'crampon1923','Les fils des prophètes dirent à Elisée: « Voici que le lieu où nous sommes assis devant toi est trop étroit pour nous.'),
('2r',6,2,'crampon1923','Allons jusqu''au Jourdain; nous prendrons chacun une poutre, et nous nous y ferons un lieu où nous puissions l''habiter. » Elisée répondit: « Allez. »'),
('2r',6,3,'crampon1923','Et l''un d''eux dit: « Consens à venir avec tes serviteurs. » Il répondit: « J''irai »;'),
('2r',6,4,'crampon1923','et il partit avec eux. Arrivés au Jourdain, ils coupèrent du bois.'),
('2r',6,5,'crampon1923','Comme l''un d''eux abattait une poutre, le fer tomba dans l''eau; il poussa un cri et dit: « Hélas! mon seigneur!... et il était emprunté! »'),
('2r',6,6,'crampon1923','L''homme de Dieu dit: « Où est-il tombé? » Et il lui montra l''endroit. Alors Elisée coupa un morceau de bois, le jeta en cet endroit et le fer surnagea.'),
('2r',6,7,'crampon1923','Et il dit: « Prends-le. » Il avança la main et le prit.'),
('2r',6,8,'crampon1923','Le roi de Syrie était en guerre avec Israël. Ayant tenu conseil avec ses serviteurs, il dit: « Mon camp sera dans tel et tel lieu. »'),
('2r',6,9,'crampon1923','Mais l''homme de Dieu envoya dire au roi d''Israël: « Garde-toi de traverser ce lieu, car les Syriens y descendent. »'),
('2r',6,10,'crampon1923','Et le roi d''Israël envoya des gens au lieu que lui avait dit et signalé l''homme de Dieu, et il s''y tint en garde, non pas une fois ni deux fois.'),
('2r',6,11,'crampon1923','Le cœur du roi de Syrie fut troublé de cette manœuvre; il appela ses serviteurs et il leur dit: « Ne voulez-vous me faire connaître lequel des nôtres est pour le roi d''Israël? »'),
('2r',6,12,'crampon1923','Un de ses serviteurs répondit: « Personne, ô roi, mon seigneur; mais Elisée, le prophète, qui est en Israël, rapporte au roi d''Israël les paroles que tu prononces dans ta chambre à coucher. »'),
('2r',6,13,'crampon1923','Le roi dit: « Allez et voyez où il est, et je l''enverrai prendre. » On vint lui faire ce rapport: « Voici qu''il est à Dothan. »'),
('2r',6,14,'crampon1923','Il envoya donc là des chevaux, des chars et une forte troupe, qui arrivèrent une nuit, et enveloppèrent la ville.'),
('2r',6,15,'crampon1923','Le serviteur de l''homme de Dieu se leva de bon matin et sortit; et voici qu''une troupe entourait la ville, avec des chevaux et des chars. Et le serviteur dit à Elisée: « Ah! Mon seigneur, comment ferons-nous? »'),
('2r',6,16,'crampon1923','Il répondit: « Ne crains rien; car ceux qui sont avec nous sont en plus grand nombre que ceux qui sont avec eux. »'),
('2r',6,17,'crampon1923','Elisée pria et dit: « Yahweh, ouvre ses yeux, pour qu''il voie. » Et Yahweh ouvrit les yeux du serviteur, et il vit, et voici que la montagne était pleine de chevaux et de chars de feu, autour d''Elisée.'),
('2r',6,18,'crampon1923','Les Syriens descendirent vers l''homme de Dieu. Elisée pria Yahweh et dit: « Daigne frapper d''aveuglement cette nation! » Et Yahweh les frappa d''aveuglement, selon la parole d''Elisée.'),
('2r',6,19,'crampon1923','Elisée leur dit: « Ce n''est pas ici le chemin, et ce n''est pas ici la ville; suivez-moi et je vous conduirai vers l''homme que vous cherchez. » Et il les conduisit à Samarie.'),
('2r',6,20,'crampon1923','Lorsqu''ils furent entrés dans Samarie, Elisée dit: « Yahweh, ouvrez les yeux de ces gens pour qu''ils voient! » Et Yahweh ouvrit leurs yeux, et ils virent, et voici qu''ils étaient au milieu de Samarie.'),
('2r',6,21,'crampon1923','Le roi d''Israël, en les voyant, dit à Elisée: « Les frapperai-je, les frapperai-je, mon père? »'),
('2r',6,22,'crampon1923','Et Elisée répondit: « Tu ne les frapperas point. Ceux que tu as faits prisonniers avec ton épée et ton arc, frappe-les; mais place devant ceux-ci du pain et de l''eau, afin qu''ils mangent et boivent, et qu''ils s''en aillent ensuite vers leur maître. »'),
('2r',6,23,'crampon1923','Le roi d''Israël leur fit servir un grand repas, et ils mangèrent et burent; puis il les renvoya, et ils s''en allèrent vers leur maître. Et les bandes des Syriens ne revinrent plus sur le territoire d''Israël.'),
('2r',6,24,'crampon1923','Après cela, Benhadad, roi de Syrie, ayant rassemblé toute son armée, monta et assiégea Samarie.'),
('2r',6,25,'crampon1923','Il y eut une grande famine à Samarie; et voici qu''on l''assiégeait si durement qu''une tête d''âne valait quatre-vingt sicles d''argent, et le quart d''un cab de fiente de pigeon cinq sicles d''argent.'),
('2r',6,26,'crampon1923','Comme le roi passait sur la muraille, une femme cria vers lui en disant: « Sauve-moi, ô roi mon seigneur! »'),
('2r',6,27,'crampon1923','Il dit: « Si Yahweh ne te sauve pas, avec quoi pourrais-je te sauver? Avec le produit de l''aire ou du pressoir? »'),
('2r',6,28,'crampon1923','Et le roi lui dit: « Qu''as-tu? » Elle dit: « Cette femme m''a dit: Donne ton fils, nous le mangerons aujourd''hui, et demain nous mangerons le mien.'),
('2r',6,29,'crampon1923','Nous avons donc fait cuire mon fils, et nous l''avons mangé. Et le jour suivant je lui ai dit: Donne ton fils et nous le mangerons. Mais elle a caché son fils. »'),
('2r',6,30,'crampon1923','Lorsque le roi entendit les paroles de cette femme, il déchira ses vêtements en passant sur la muraille; et le peuple vit, et voici qu''il avait par dessous un sac sur son corps.'),
('2r',6,31,'crampon1923','Le roi dit: « Que Dieu me traite dans toute sa rigueur, si la tête d''Elisée, fils de Saphat, reste aujourd''hui sur lui. »'),
('2r',6,32,'crampon1923','Or, pendant qu''Elisée était assis dans sa maison et que les anciens étaient assis auprès de lui, le roi envoya quelqu''un d''auprès de lui. Mais avant que le messager fut arrivé auprès d''Elisée, celui-ci dit aux anciens: « Savez-vous que ce fils d''assassin envoie quelqu''un pour m''ôter la tête? Faites attention: quand le messager viendra, fermez la porte et pressez-le avec la porte. Mais le bruit des pas de son maître ne se fait-il pas entendre derrière lui?... »'),
('2r',6,33,'crampon1923','Il leur parlait encore, et déjà le messager était descendu vers lui; et il dit: « Voici, c''est un mal qui vient de Yahweh; qu''ai-je à espérer encore de Yahweh? »'),
('2r',7,1,'crampon1923','Elisée dit: « Ecoutez la parole de Yahweh: Ainsi dit Yahweh: Demain, à cette heure, on aura une mesure de fleur de farine pour un sicle, et deux mesures d''orge pour un sicle, à la porte de Samarie. »'),
('2r',7,2,'crampon1923','L''officier sur la main duquel s''appuyait le roi répondit à l''homme de Dieu et dit: « Quand Yahweh ferait des fenêtres au ciel, cela pourrait-il arriver? » Elisée dit: « Voici que tu le verras de tes yeux, mais tu n''en mangeras point. »'),
('2r',7,3,'crampon1923','Il y avait à l''entrée de la porte quatre lépreux, qui se dirent l''un à l''autre: « Pourquoi resterions-nous ici jusqu''à ce que nous mourrions?'),
('2r',7,4,'crampon1923','Si nous prenons le parti d''entrer dans la ville, la famine est dans la ville, et nous y mourrons; si nous restons ici, nous mourrons également. Venez donc et jetons-nous dans le camp des Syriens; s''ils nous laissent la vie, nous vivrons, et s''ils nous font mourir, nous mourrons. »'),
('2r',7,5,'crampon1923','Ils se levèrent au crépuscule pour se rendre au camp des Syriens, et ils arrivèrent à l''entrée du camp des Syriens, et voici qu''il n''y avait personne.'),
('2r',7,6,'crampon1923','Le Seigneur avait fait entendre dans le camp des Syriens un bruit de chars et un bruit de chevaux, le bruit d''une grande armée, et ils s''étaient dit l''un à l''autre: « Voici que le roi d''Israël a pris à sa solde contre nous les rois des Héthéens et les rois des Egyptiens pour venir nous attaquer ».'),
('2r',7,7,'crampon1923','Et, se levant, ils avaient pris la fuite au crépuscule, abandonnant leurs tentes, leurs chevaux et leurs ânes, le camp tel qu''il était, et ils s''étaient enfuis pour sauver leur vie.'),
('2r',7,8,'crampon1923','Les lépreux, arrivés à l''entrée du camp, pénétrèrent dans une tente, et, après avoir bu et mangé, ils en emportèrent de l''argent, de l''or et des vêtements qu''ils allèrent cacher. Ils revinrent, pénétrèrent dans une autre tente et en emportèrent des objets qu''ils allèrent cacher de la même manière.'),
('2r',7,9,'crampon1923','Alors ils se dirent l''un à l''autre: « Nous n''agissons pas bien. Ce jour est un jour de bonne nouvelle; si nous gardons le silence et si nous attendons jusqu''à la lumière du matin, nous trouverons le châtiment. Venez donc et allons informer la maison du roi. »'),
('2r',7,10,'crampon1923','Ils partirent et, ayant appelé les gardes de la porte de la ville, ils leur firent ce rapport: « Nous sommes entrés dans le camp des Syriens, et voici qu''il n''y a personne, ni aucune voix d''homme; il n''y a que des chevaux attachés, des ânes attachés, et les tentes comme elles étaient. »'),
('2r',7,11,'crampon1923','Les gardes de la porte poussèrent des cris et portèrent la nouvelle à l''intérieur de la maison du roi.'),
('2r',7,12,'crampon1923','Le roi se leva de nuit, et il dit à ses serviteurs: « Je veux vous apprendre ce que nous font les Syriens. Sachant que nous sommes affamés, ils ont quitté leur camp pour se cacher dans les champs, et ils se sont dit: Quand ils sortiront de la ville, nous les saisirons vivants, et nous entrerons dans la ville. »'),
('2r',7,13,'crampon1923','L''un de ses serviteurs prit la parole et dit: « Que l''on prenne cinq des chevaux survivants qui restent encore dans la ville, — voici qu''ils sont comme toute la multitude d''Israël qui y est restée, voici qu''ils sont comme toute la multitude d''Israël qui se meurt, — et nous enverrons voir. »'),
('2r',7,14,'crampon1923','On prit deux chars avec les chevaux, et le roi envoya des hommes sur les traces de l''armée des Syriens, en disant: « Allez et voyez. »'),
('2r',7,15,'crampon1923','Ils Allèrent après eux jusqu''au Jourdain, et voici que toute la route était couverte de vêtements et d''objets que les Syriens avaient jetés, dans leur précipitation. A leur retour, les messagers rapportèrent tout au roi.'),
('2r',7,16,'crampon1923','Aussitôt le peuple sortit et pilla le camp des Syriens, et l''on eut une mesure de fleur de farine pour un sicle, et deux mesures d''orge pour un sicle, selon la parole de Yahweh.'),
('2r',7,17,'crampon1923','Le roi avait confié la garde de la porte à l''officier sur la main duquel il s''appuyait; mais cet officier y fut foulé aux pieds par le peuple, et il mourut, selon la parole qu''avait dite l''homme de Dieu quand le roi était descendu vers lui.'),
('2r',7,18,'crampon1923','En effet, quand l''homme de Dieu avait parlé au roi en disant: « On aura deux mesures d''orge pour un sicle et une mesure de fleur de farine pour un sicle, demain, à cette heure, à la porte de Samarie, »'),
('2r',7,19,'crampon1923','l''officier avait répondu à l''homme de Dieu et dit: « Quand Yahweh ferait des fenêtres au ciel, cela pourrait-il arriver? » Et Elisée avait dit: « Voici que tu le verras de tes yeux, mais tu n''en mangeras point. »'),
('2r',7,20,'crampon1923','Et c''est ce qui lui arriva: le peuple le foula aux pieds à la porte, et il mourut.'),
('2r',8,1,'crampon1923','Elisée parla à la femme dont il avait fait revivre l''enfant, en ces termes: « Lève-toi, va-t-en, toi et ta famille, et séjourne où tu pourras; car Yahweh a appelé la famine, et elle vient en effet sur le pays pour sept années. »'),
('2r',8,2,'crampon1923','La femme, s''étant levée, fit selon la parole de l''homme de Dieu: elle s''en alla, elle et sa famille, et séjourna sept ans au pays des Philistins.'),
('2r',8,3,'crampon1923','Au bout des sept ans, la femme revint du pays des Philistins et alla implorer le roi au sujet de sa maison et de son champ.'),
('2r',8,4,'crampon1923','Le roi s''entretenait avec Giézi, serviteur de l''homme de Dieu, en disant: « Raconte-moi, je te prie, toutes les grandes choses qu''Elisée a faites. »'),
('2r',8,5,'crampon1923','Pendant que le serviteur racontait au roi comment son maître avait rendu la vie à un mort, voici que la femme dont Elisée avait fait revivre le fils se mit à implorer le roi au sujet de sa maison et de son champ. Et Giézi dit: « O roi mon seigneur, voici la femme et voici son fils qu''Elisée a rendu à la vie. »'),
('2r',8,6,'crampon1923','Le roi interrogea la femme, qui lui fit le récit; et le roi lui donna un eunuque, en disant: « Fais restituer tout ce qui lui appartient, avec tous les revenus du champ, depuis le jour où elle a quitté le pays jusqu''à présent. »'),
('2r',8,7,'crampon1923','Elisée se rendit à Damas; Benhadad, roi de Syrie, était malade, et on l''informa, en disant: « l''homme de Dieu est arrivé ici. »'),
('2r',8,8,'crampon1923','Le roi dit à Hazaël: « Prends avec toi un présent, et va au-devant de l''homme de Dieu; consulte par lui Yahweh, en disant: Survivrai-je à cette maladie? »'),
('2r',8,9,'crampon1923','Hazaël alla au-devant d''Elisée. Il avait pris avec lui un présent, de tout ce qu''il y avait de meilleur à Damas, la charge de quarante chameaux. Lorsqu''il fut arrivé, il se présenta devant Elisée en disant: « Ton fils Benhadad, roi de Syrie, m''envoie vers toi pour dire: Survivrai-je à cette maladie? »'),
('2r',8,10,'crampon1923','Elisée lui répondit: « Va, dis-lui: Sûrement tu survivras. Mais Yahweh m''a fait voir que sûrement il mourra. »'),
('2r',8,11,'crampon1923','L''homme de Dieu arrêta son regard sur Hazaël et le fixa jusqu''à le faire rougir; et l''homme de Dieu pleura.'),
('2r',8,12,'crampon1923','Hazaël dit: « Pourquoi mon seigneur pleure-t-il? » Et Elisée répondit: « Parce que je sais le mal que tu feras aux enfants d''Israël: tu livreras aux flammes leurs villes fortes, tu tueras avec l''épée leurs jeunes gens, tu écraseras leurs petits enfants et tu fendras le ventre à leurs femmes enceintes. »'),
('2r',8,13,'crampon1923','Hazaël dit: « Mais qu''est donc ton serviteur, un chien, pour faire de si grandes choses? » Elisée répondit: « Yahweh m''a fait voir que tu seras roi de Syrie. »'),
('2r',8,14,'crampon1923','Hazaël, ayant quitté Elisée, revint auprès de son maître, qui lui dit: « Que t''a dit Elisée? » Il répondit: « Il m''a dit: Sûrement tu survivras. »'),
('2r',8,15,'crampon1923','Le lendemain, Hazaël prit une couverture et, l''ayant plongée dans l''eau, il l''étendit sur le visage du roi, qui mourut. Et Hazaël régna à sa place.'),
('2r',8,16,'crampon1923','La cinquième année de Joram, fils d''Achab, roi d''Israël, Josaphat étant encore roi de Juda, Joram, fils de Josaphat, roi de Juda, régna.'),
('2r',8,17,'crampon1923','Il avait trente-deux ans lorsqu''il devint roi, et il régna huit ans à Jérusalem.'),
('2r',8,18,'crampon1923','Il marcha dans la voie des rois d''Israël, comme avait fait la maison d''Achab, car il avait pour femme une fille d''Achab, et il fit ce qui est mal aux yeux de Yahweh.'),
('2r',8,19,'crampon1923','Mais Yahweh ne voulut pas détruire Juda, à cause de David, son serviteur, selon la promesse qu''il lui avait faite de lui donner toujours une lampe parmi ses fils.'),
('2r',8,20,'crampon1923','De son temps Edom s''affranchit de la domination de Juda et se donna un roi.'),
('2r',8,21,'crampon1923','Joram passa à Séïra avec tous les chars; s''étant levé de nuit, il battit les Edomites qui l''entouraient et les chefs des chars, et le peuple s''enfuit dans ses tentes.'),
('2r',8,22,'crampon1923','Edom s''affranchit de la domination de Juda, jusqu''à ce jour. Lobna s''affranchit aussi dans le même temps.'),
('2r',8,23,'crampon1923','Le reste des actes de Joram, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques de Juda?'),
('2r',8,24,'crampon1923','Joram se coucha avec ses pères, et il fut enterré avec ses pères dans la ville de David; et Ochozias, son fils, régna à sa place.'),
('2r',8,25,'crampon1923','La douzième année de Joram, fils d''Achab, roi d''Israël, régna Ochozias, fils de Joram, roi de Juda.'),
('2r',8,26,'crampon1923','Ochozias avait vingt-deux ans lorsqu''il devint roi, et il régna un an à Jérusalem. Sa mère s''appelait Athalie, fille d''Amri, roi d''Israël.'),
('2r',8,27,'crampon1923','Il marcha dans la voie de la maison d''Achab, et il fit ce qui est mal aux yeux de Yahweh, comme la maison d''Achab, car il était gendre de la maison d''Achab.'),
('2r',8,28,'crampon1923','Il alla avec Joram, fils d''Achab, combattre Hazaël, roi de Syrie, à Ramoth-en-Galaad. Les Syriens blessèrent Joram;'),
('2r',8,29,'crampon1923','le roi Joram s''en retourna pour se faire guérir à Jezrahel des blessures que les Syriens lui avaient faites à Ramoth, lorsqu''il se battait contre Hazaël, roi de Syrie. Ochozias, fils de Joram, roi de Juda, descendit pour voir Joram, fils d''Achab, à Jezrahel, parce qu''il était malade.'),
('2r',9,1,'crampon1923','Elisée, le prophète, appela un des fils des prophètes et lui dit: « Ceins tes reins, prends en ta main cette fiole d''huile et va à Ramoth-en-Galaad.'),
('2r',9,2,'crampon1923','Quand tu y seras arrivé, regarde après Jéhu, fils de Josaphat, fils de Namsi; et, l''ayant abordé, tu le feras lever du milieu de ses frères, et tu le conduiras dans une chambre retirée.'),
('2r',9,3,'crampon1923','Tu prendras la fiole d''huile, tu la répandras sur sa tête et tu diras: Ainsi dit Yahweh: Je t''oins roi d''Israël. Puis tu ouvriras la porte et tu t''enfuiras sans tarder. »'),
('2r',9,4,'crampon1923','Le jeune homme, serviteur du prophète, partit pour Ramoth-en-Galaad.'),
('2r',9,5,'crampon1923','Lorsqu''il arriva, voici que les chefs de l''armée étaient assis. Il dit: « Chef, j''ai un mot à te dire. » Et Jéhu dit: « Auquel de nous tous? » Il répondit: « A toi, chef. »'),
('2r',9,6,'crampon1923','Jéhu se leva et entra dans la maison; et le jeune homme répandit l''huile sur sa tête, en lui disant: « Ainsi dit Yahweh, Dieu d''Israël: Je t''oins roi du peuple de Yahweh, d''Israël.'),
('2r',9,7,'crampon1923','Tu frapperas la maison d''Achab, ton maître, et je vengerai sur Jézabel le sang de mes serviteurs les prophètes et le sang de tous les serviteurs de Yahweh.'),
('2r',9,8,'crampon1923','Toute la maison d''Achab périra; j''exterminerai tout mâle appartenant à Achab, celui qui est esclave et celui qui est libre en Israël,'),
('2r',9,9,'crampon1923','et je rendrai la maison d''Achab semblable à la maison de Jéroboam, fils de Nabat, et à la maison de Baasa, fils d''Ahia.'),
('2r',9,10,'crampon1923','Les chiens mangeront Jézabel dans le champ de Jézrahel, et il n''y aura personne pour l''enterrer. » Et le jeune homme, ouvrant la porte, s''enfuit.'),
('2r',9,11,'crampon1923','Alors Jéhu sortit pour rejoindre les serviteurs de son maître. Ils lui dirent: « Tout va-t-il bien? Pourquoi ce fou est-il venu vers toi? » Il leur répondit: « Vous connaissez l''homme et son langage. »'),
('2r',9,12,'crampon1923','Ils répliquèrent: « Mensonge! Déclare-le-nous! » Et il dit: « Il m''a parlé de telle et telle manière, disant: Ainsi dit Yahweh: Je t''oins roi d''Israël. »'),
('2r',9,13,'crampon1923','Aussitôt, chacun prenant son manteau, ils le mirent sous Jéhu, au haut des degrés; ils sonnèrent de la trompette et dirent: « Jéhu est roi! »'),
('2r',9,14,'crampon1923','Jéhu, fils de Josaphat, fils de Namsi, forma une conspiration contre Joram. — Joram et tout Israël défendaient alors Ramoth-en-Galaad contre Hazaël, roi de Syrie;'),
('2r',9,15,'crampon1923','mais le roi Joram s''en était retourné pour se faire guérir à Jezrahel des blessures que les Syriens lui avaient faites, lorsqu''il se battait contre Hazaël, roi de Syrie. — Jéhu dit: « Si c''est votre désir, que personne ne s''échappe de la ville pour aller porter la nouvelle à Jezrahel. »'),
('2r',9,16,'crampon1923','Et Jéhu, étant monté sur son char, partit pour Jezrahel, car Joram y était couché, et Ochozias, roi de Juda, était descendu pour visiter Joram.'),
('2r',9,17,'crampon1923','La sentinelle qui se tenait sur la tour à Jezrahel vit venir la troupe de Jéhu et dit: « Je vois une troupe. » Et Joram dit: « Prends un cavalier et envoie-le au-devant d''eux pour demander: Est-ce la paix? »'),
('2r',9,18,'crampon1923','Le cavalier alla au-devant de Jéhu et dit: « Ainsi dit le roi: Est-ce la paix? » Et Jéhu répondit: « Que t''importe la paix? Passe derrière moi. » La sentinelle en donna son avis, en disant: « Le messager est allé jusqu''à eux, et il ne revient pas. »'),
('2r',9,19,'crampon1923','Joram envoya un second cavalier, qui arriva vers eux et dit: « Ainsi dit le roi: Est-ce la paix? » Et Jéhu répondit: « Que t''importe la paix?; passe derrière moi. »'),
('2r',9,20,'crampon1923','La sentinelle en donna avis, en disant: « Le messager est allé jusqu''à eux, et il ne revient pas. Et la manière de conduire est comme la manière de conduire de Jéhu, fils de Namsi, car il conduit d''une manière insensée. »'),
('2r',9,21,'crampon1923','Alors Joram dit: « Attelle; » et on attela son char. Joram, roi d''Israël, et Ochozias, roi de Juda, sortirent chacun sur son char; ils sortirent au-devant de Jéhu, et ils le rencontrèrent dans le champ de Naboth de Jezrahel.'),
('2r',9,22,'crampon1923','En apercevant Jéhu, Joram lui dit: « Est-ce la paix, Jéhu? » Jéhu répondit: « Quelle paix, tant que durent les prostitutions de Jézabel, ta mère, et ses nombreux sortilèges? »'),
('2r',9,23,'crampon1923','Joram tourna bride et s''enfuit, et il dit à Ochozias: « Trahison, Ochozias! »'),
('2r',9,24,'crampon1923','Mais Jéhu saisit son arc de sa main, et frappa Joram entre les épaules: la flèche sortit par le cœur, et Joram s''affaissa dans son char.'),
('2r',9,25,'crampon1923','Et Jéhu dit à son officier Badacer: « Prends-le et jette-le dans le champ de Naboth de Jezrahel. Car, souviens-toi: lorsque moi et toi nous chevauchions ensemble derrière Achab, son père, Yahweh prononça contre lui cette sentence:'),
('2r',9,26,'crampon1923','« Aussi vrai que j''ai vu hier le sang de Naboth et le sang de ses fils, oracle de Yahweh, je te rendrai la pareille dans ce champ même, oracle de Yahweh. » Prends-le donc et jette-le dans le champ, selon la parole de Yahweh. »'),
('2r',9,27,'crampon1923','Ochozias, roi de Juda, voyant cela, s''enfuit par le chemin de la maison du jardin. Jéhu le poursuivit et dit: « Frappez-le, lui aussi, sur le char! » Et on le frappa à la montée de Gaver, près de Jeblaam. Il s''enfuit à Mageddo, et il y mourut.'),
('2r',9,28,'crampon1923','Ses serviteurs le transportèrent sur un char à Jérusalem, et ils l''enterrèrent dans son sépulcre avec ses pères, dans la ville de David.'),
('2r',9,29,'crampon1923','Ochozias était devenu roi de Juda la onzième année de Joram, fils d''Achab.'),
('2r',9,30,'crampon1923','Jéhu entra dans Jezrahel. Jézabel, l''ayant appris, mit du fard à ses yeux, se para la tête et regarda par la fenêtre.'),
('2r',9,31,'crampon1923','Comme Jéhu franchissait la porte, elle dit: « Est-ce la paix, Zamri, assassin de son maître? »'),
('2r',9,32,'crampon1923','Il leva les yeux vers la fenêtre et dit: « Qui est avec moi? Qui? » Et deux ou trois eunuques ayant regardé vers lui,'),
('2r',9,33,'crampon1923','il dit: « Jetez-la en bas! » Ils la jetèrent en bas, et il rejaillit de son sang sur la muraille et sur les chevaux, et Jéhu la foula aux pieds.'),
('2r',9,34,'crampon1923','Puis il entra et, ayant mangé et bu, il dit: « Allez voir cette maudite et enterrez-la, car elle est fille de roi. »'),
('2r',9,35,'crampon1923','Ils allèrent pour l''enterrer, mais ils ne trouvèrent d''elle que le crâne, les pieds et les paumes de ses mains.'),
('2r',9,36,'crampon1923','Ils retournèrent l''annoncer à Jéhu, qui dit: « Telle est la parole de Yahweh, qu''il avait prononcée par son serviteur Elie le Thesbite, en disant: Dans le champ de Jezrahel, les chiens mangeront la chair de Jézabel;'),
('2r',9,37,'crampon1923','et le cadavre de Jézabel sera comme du fumier sur la surface du champ, dans le champ de Jezrahel, de sorte qu''on ne pourra pas dire: c''est Jézabel. »'),
('2r',10,1,'crampon1923','Il y avait dans Samarie soixante-dix fils d''Achab. Jéhu écrivit une lettre qu''il envoya à Samarie aux chefs de Jezrahel, les anciens, et aux gouverneurs des enfants d''Achab; il y disait:'),
('2r',10,2,'crampon1923','« Aussitôt que cette lettre vous sera parvenue, — puisque vous avez avec vous les fils de votre maître, avec vous les chars et les chevaux, une ville forte et les armes, —'),
('2r',10,3,'crampon1923','voyez lequel des fils de votre maître est le meilleur et convient le mieux, mettez-le sur le trône de son père et combattez pour la maison de votre maître. »'),
('2r',10,4,'crampon1923','Ils eurent une très grande peur et ils dirent: « Voici que les deux rois n''ont pu lui résister; comment résisterions-nous? »'),
('2r',10,5,'crampon1923','Et le préfet du palais, le commandant de la ville, les anciens et les gouverneurs envoyèrent dire à Jéhu: « Nous sommes tes serviteurs et nous ferons tout ce que tu nous diras; nous n''établirons personne roi; fais ce qui te semblera bon. »'),
('2r',10,6,'crampon1923','Jéhu leur écrivit une seconde lettre; il disait: « Si vous êtes pour moi et si vous écoutez ma voix, prenez les têtes des hommes, fils de votre maître, et venez auprès de moi demain, à cette heure, à Jezrahel. » Or, les soixante-dix fils du roi étaient chez les grands de la ville, qui les élevaient.'),
('2r',10,7,'crampon1923','Quand la lettre leur fut parvenue, ils prirent les fils du roi et égorgèrent ces soixante-dix hommes; puis, ayant mis leurs têtes dans des corbeilles, ils les envoyèrent à Jéhu, à Jézrahel.'),
('2r',10,8,'crampon1923','Le messager vint l''en informer, en disant: « Ils ont apporté les têtes des fils du roi. » Et il dit: « Mettez-les en deux tas à l''entrée de la porte jusqu''au matin. »'),
('2r',10,9,'crampon1923','Le matin, il sortit et, se présentant à tout le peuple, il dit: « Vous êtes justes: voici que moi j''ai conspiré contre mon maître, et je l''ai tué; mais qui a frappé tous ceux-ci?'),
('2r',10,10,'crampon1923','Sachez donc qu''il ne tombe rien à terre de la parole de Yahweh, de la parole que Yahweh a prononcée sur la maison d''Achab; Yahweh a accompli ce qu''il a déclaré par l''organe de son serviteur Elie. »'),
('2r',10,11,'crampon1923','Et Jéhu frappa tous ceux qui restaient de la maison d''Achab à Jezrahel, tous ses grands, ses familiers et ses prêtres, jusqu''à ce qu''il n''en restât plus un seul.'),
('2r',10,12,'crampon1923','Puis, s''étant levé, il partit pour aller à Samarie. Arrivé à une maison de réunion des bergers, sur le chemin,'),
('2r',10,13,'crampon1923','Jéhu trouva les frères d''Ochozias, roi de Juda, et il dit: « Qui êtes-vous? » Ils répondirent: « Nous sommes les frères d''Ochozias, et nous descendons pour saluer les fils du roi et les fils de la reine. »'),
('2r',10,14,'crampon1923','Jéhu dit: « Saisissez-les vivants. » Et, les ayant saisis vivants, ils les égorgèrent à la citerne de la maison de réunion, au nombre de quarante-deux, sans que Jéhu en laissât échapper un seul.'),
('2r',10,15,'crampon1923','Etant parti de là, il rencontra Jonadab, fils de Réchab, qui venait au-devant de lui. Il le salua et lui dit: « Ton cœur est-il sincère, comme mon cœur l''est envers le tien? » Jonadab répondit: « Il l''est. » Et Jéhu dit: « S''il l''est, donne-moi ta main. » Il lui donna la main, et Jéhu le fit monter auprès de lui, dans le char,'),
('2r',10,16,'crampon1923','en disant: « Viens avec moi, et tu verras mon zèle pour Yahweh. » Il l''emmena ainsi sur son char.'),
('2r',10,17,'crampon1923','Arrivé à Samarie, Jéhu frappa tous ceux qui restaient à Samarie de la famille d''Achab, et il l''extermina, selon la parole que Yahweh avait dite à Elie.'),
('2r',10,18,'crampon1923','Jéhu assembla ensuite tout le peuple et leur dit: « Achab a peu servi Baal; Jéhu le servira beaucoup.'),
('2r',10,19,'crampon1923','Et maintenant, convoquez auprès de moi tous les prophètes de Baal, tous ses serviteurs et tous ses prêtres, sans qu''il en manque un seul, car j''ai un grand sacrifice à offrir à Baal; quiconque manquera ne vivra pas. » Or Jéhu agissait avec ruse, pour faire périr les serviteurs de Baal.'),
('2r',10,20,'crampon1923','Jéhu dit: « Publiez une assemblée solennelle en l''honneur de Baal »; et ils la publièrent.'),
('2r',10,21,'crampon1923','Jéhu envoya des messagers dans tout Israël, et tous les serviteurs de Baal vinrent, sans qu''un seul demeurât sans venir; ils entrèrent dans la maison de Baal, et la maison de Baal fut remplie d''un bout à l''autre.'),
('2r',10,22,'crampon1923','Jéhu dit à celui qui avait la garde du vestiaire: « Sorts des vêtements pour tous les serviteurs de Baal. » Et cet homme sortit des vêtements pour eux.'),
('2r',10,23,'crampon1923','Alors Jéhu, étant venu à la maison de Baal avec Jonadab, fils de Réchab, dit aux serviteurs de Baal: « Cherchez et regardez afin qu''il n''y ait ici avec nous aucun des serviteurs de Yahweh, mais seulement des serviteurs de Baal. »'),
('2r',10,24,'crampon1923','Lorsqu''ils furent entrés pour offrir des sacrifices et des holocaustes, Jéhu posta dehors quatre-vingts hommes, en leur disant: « Si quelqu''un des hommes que je mets entre vos mains s''échappe, la vie de celui qui l''aura laissé échapper paiera pour la sienne. »'),
('2r',10,25,'crampon1923','Aussitôt qu''il eut achevé d''offrir l''holocauste, Jéhu dit aux coureurs et aux officiers: « Entrez, frappez-les, que pas un ne sorte! » Et ils les frappèrent du tranchant de l''épée. Les coureurs et les officiers les jetèrent là, et, pénétrant dans le sanctuaire de la maison de Baal,'),
('2r',10,26,'crampon1923','ils tirèrent dehors les stèles de la maison de Baal et les brûlèrent;'),
('2r',10,27,'crampon1923','ils mirent en pièces la stèle de Baal; ils renversèrent aussi la maison de Baal et ils en firent un cloaque, qui a subsisté jusqu''à ce jour.'),
('2r',10,28,'crampon1923','Jéhu extermina Baal du milieu d''Israël.'),
('2r',10,29,'crampon1923','Mais Jéhu ne se détourna pas des péchés de Jéroboam, fils de Nabat, qui avait fait pécher Israël, ni des veaux d''or qui étaient à Béthel et qui étaient à Dan.'),
('2r',10,30,'crampon1923','Yahweh dit à Jéhu: « Parce que tu as bien exécuté ce qui était droit à mes yeux, et que tu as fait à la maison d''Achab tout ce qui était dans mon cœur, tes fils jusqu''à la quatrième génération seront assis sur le trône d''Israël. »'),
('2r',10,31,'crampon1923','Mais Jéhu ne prit point garde à marcher de tout son cœur dans la loi de Yahweh, Dieu d''Israël; il ne se détourna point des péchés de Jéroboam qui avait fait pécher Israël.'),
('2r',10,32,'crampon1923','En ces jours-là, Yahweh commença à retrancher du territoire d''Israël, et Hazaël battit les Israélites sur toute la frontière d''Israël;'),
('2r',10,33,'crampon1923','depuis le Jourdain, vers le soleil levant, il battit tout le pays de Galaad, les Gadites, les Rubénites, les Manassites, depuis Aroër, qui est sur le torrent de l''Arnon, jusqu''à Galaad et à Basan.'),
('2r',10,34,'crampon1923','Le reste des actes de Jéhu, tout ce qu''il a fait et tous ses exploits, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('2r',10,35,'crampon1923','Et Jéhu se coucha avec ses pères, et on l''enterra à Samarie. Joachaz, son fils, régna à sa place.'),
('2r',10,36,'crampon1923','Le temps que régna Jéhu sur Israël, à Samarie, fut de vingt-huit ans.'),
('2r',11,1,'crampon1923','Athalie, mère d''Ochozias, voyant que son fils était mort, se leva et fit périr toute la race royale.'),
('2r',11,2,'crampon1923','Mais Josaba, fille du roi Joram et sœur d''Ochozias, prit Joas, fils d''Ochozias, et l''enleva du milieu des fils du roi que l''on massacrait; elle le mit avec sa nourrice dans la chambre des lits. On le déroba ainsi aux regards d''Athalie, et il ne fut pas mis à mort.'),
('2r',11,3,'crampon1923','Il resta six ans caché avec Joschéba dans la maison de Yahweh; et ce fut Athalie qui régna sur le pays.'),
('2r',11,4,'crampon1923','La septième année, Joïada envoya chercher les centurions des Cariens et des coureurs, et il les fit venir auprès de lui dans la maison de Yahweh. Il conclut une alliance avec eux et, après leur avoir fait prêter serment dans la maison de Yahweh, il leur montra le fils du roi.'),
('2r',11,5,'crampon1923','Puis il leur donna ses ordres, en disant: « Voici ce que vous ferez: Le tiers d''entre vous qui entre en service le jour du sabbat, pour monter la garde à la maison du roi,'),
('2r',11,6,'crampon1923','— le tiers à la porte de Sur, et le tiers à la porte des coureurs, — vous ferez la garde à la maison de Yahweh pour en interdire l''entrée.'),
('2r',11,7,'crampon1923','Et vos deux autres divisions, tous ceux qui sortent de service le jour du sabbat, pour monter la garde à la maison de Yahweh auprès du roi,'),
('2r',11,8,'crampon1923','vous entourerez le roi de toutes parts, chacun les armes à la main; si quelqu''un entre dans les rangs, qu''on le mette à mort; et vous serez près du roi quand il sortira et quand il entrera. »'),
('2r',11,9,'crampon1923','Les centurions agirent selon tout ce qu''avait ordonné le prêtre Joïada. Ayant pris chacun leurs gens, ceux qui entraient en service le jour du sabbat et ceux qui sortaient de service le jour du sabbat, ils se rendirent auprès du prêtre Joïada.'),
('2r',11,10,'crampon1923','Le prêtre remit aux centurions les lances et les boucliers qui avaient appartenu au roi David, et qui se trouvaient dans la maison de Yahweh.'),
('2r',11,11,'crampon1923','Les coureurs, chacun les armes à la main, se tinrent depuis le côté droit de la maison jusqu''au côté gauche de la maison, près de l''autel et près de la maison, de manière à entourer le roi.'),
('2r',11,12,'crampon1923','Et le prêtre fit avancer le fils du roi, et il mit sur lui le diadème et le témoignage. Ils l''établirent roi et l''oignirent, et, frappant des mains, ils dirent: « Vive le roi! »'),
('2r',11,13,'crampon1923','Lorsque Athalie entendit le bruit des coureurs et du peuple, elle vint vers le peuple, à la maison de Yahweh.'),
('2r',11,14,'crampon1923','Elle regarda, et voici que le roi se tenait sur l''estrade, selon l''usage; près du roi, étaient les chefs et les trompettes, et tout le peuple du pays était dans la joie, et l''on sonnait des trompettes. Athalie déchira ses vêtements et cria: « Conspiration! Conspiration! »'),
('2r',11,15,'crampon1923','Alors le prêtre Joïada donna un ordre aux centurions qui étaient à la tête de l''armée et leur dit: « Faites-la sortir de la maison entre les rangs, et tuez par l''épée quiconque la suivra. » Car le prêtre avait dit: « Qu''elle ne soit pas mise à mort dans la maison de Yahweh. »'),
('2r',11,16,'crampon1923','On lui fit place des deux côtés, et elle se rendit par le chemin de l''entrée des chevaux, vers la maison du roi, et c''est là qu''elle fut tuée.'),
('2r',11,17,'crampon1923','Joïada conclut, entre Yahweh, le roi et le peuple, l''alliance par laquelle ils devaient être le peuple de Yahweh; il fit aussi l''alliance entre le roi et le peuple.'),
('2r',11,18,'crampon1923','Et tout le peuple du pays entra dans la maison de Baal, et ils la démolirent; ils brisèrent entièrement ses autels et ses images, et ils tuèrent devant les autels Mathan, prêtre de Baal. Après avoir mis des gardiens dans la maison de Yahweh,'),
('2r',11,19,'crampon1923','le prêtre Joïada prit les centurions, les Cariens et les coureurs, et tout le peuple du pays, et ils firent descendre le roi de la maison de Yahweh, et ils entrèrent dans la maison du roi par la porte des coureurs; et Joas s''assit sur le trône des rois.'),
('2r',11,20,'crampon1923','Tout le peuple du pays se réjouit, et la ville fut tranquille; et l''on fit mourir Athalie par l''épée dans la maison du roi.'),
('2r',12,1,'crampon1923','Joas avait sept ans lorsqu''il devint roi.'),
('2r',12,2,'crampon1923','La septième année de Jéhu, Joas devint roi, et il régna quarante ans à Jérusalem. Sa mère s''appelait Sébia, de Bersabée.'),
('2r',12,3,'crampon1923','Joas fit ce qui est droit aux yeux de Yahweh tout le temps que le prêtre Joïada lui donna ses instructions.'),
('2r',12,4,'crampon1923','Seulement les hauts lieux ne disparurent point; le peuple continuait d''offrir des sacrifices et des parfums sur les hauts lieux.'),
('2r',12,5,'crampon1923','Joas dit aux prêtres: « Tout l''argent du sanctuaire qu''on apporte dans la maison de Yahweh, savoir, l''argent de la taxe personnelle, l''argent pour le rachat des personnes d''après l''estimation de chacune, et tout l''argent que chacun a à cœur d''apporter à la maison de Yahweh;'),
('2r',12,6,'crampon1923','que les prêtres le prennent, chacun des gens de sa connaissance, et qu''ils réparent les brèches de la maison, partout où l''on en trouvera. »'),
('2r',12,7,'crampon1923','Or il arriva que, dans la vingt-troisième année du roi Joas, les prêtres n''avaient pas réparé les brèches de la maison.'),
('2r',12,8,'crampon1923','Le roi Joas appela le prêtre Joïada et les autres prêtres, et leur dit: « Pourquoi ne réparez-vous pas les brèches de la maison? Maintenant, vous ne prendrez plus l''argent de vos connaissances, mais vous le livrerez pour les brèches de la maison. »'),
('2r',12,9,'crampon1923','Les prêtres consentirent à ne plus prendre d''argent du peuple et ils n''eurent plus à réparer les brèches de la maison.'),
('2r',12,10,'crampon1923','Alors le prêtre Joïada prit un coffre et, ayant percé un trou dans son couvercle, il le plaça à côté de l''autel, à droite du passage par lequel on entrait dans la maison de Yahweh; les prêtres qui gardaient la porte y mettaient tout l''argent qu''on apportait dans la maison de Yahweh.'),
('2r',12,11,'crampon1923','Quand ils voyaient qu''il y avait beaucoup d''argent dans le coffre, le secrétaire du roi montait avec le grand prêtre, et ils liaient et comptaient l''argent qui se trouvait dans la maison de Yahweh.'),
('2r',12,12,'crampon1923','Ils remettaient l''argent pesé entre les mains de ceux qui faisaient exécuter l''ouvrage, qui étaient préposés sur la maison de Yahweh; et ceux-ci le donnaient aux charpentiers et aux autres ouvriers qui travaillaient à la maison de Yahweh;'),
('2r',12,13,'crampon1923','aux maçons et aux tailleurs de pierre; ils le donnaient aussi pour les achats de bois et de pierres de taille nécessaires à la réparation des brèches de la maison de Yahweh, et pour tout ce que l''on dépensait pour consolider la maison.'),
('2r',12,14,'crampon1923','Toutefois on ne fit pour la maison de Yahweh ni bassins d''argent, ni couteaux, ni coupes, ni trompettes, ni ustensile d''or, ni ustensile d''argent, avec l''argent qu''on apportait dans la maison de Yahweh:'),
('2r',12,15,'crampon1923','on le donnait à ceux qui faisaient exécuter l''ouvrage, pour qu''ils l''emploient à réparer la maison de Yahweh.'),
('2r',12,16,'crampon1923','On ne demandait pas de compte aux hommes entre les mains desquels on remettait l''argent pour le donner à ceux qui faisaient exécuter l''ouvrage, parce qu''ils se conduisaient avec probité.'),
('2r',12,17,'crampon1923','L''argent des sacrifices pour le délit et des sacrifices pour le péché n''était point apporté dans la maison de Yahweh: il était pour les prêtres.'),
('2r',12,18,'crampon1923','Alors Hazaël, roi de Syrie, monta et combattit contre Geth, dont il s''empara. Il résolut de monter contre Jérusalem.'),
('2r',12,19,'crampon1923','Joas, roi de Juda, prit toutes les choses consacrées, ce qu''avaient consacré Josaphat, Joram et Ochozias, ses pères, rois de Juda, ce qu''il avait consacré lui-même, et tout l''or qui se trouvait dans les trésors de la maison de Yahweh et de la maison du roi, et il envoya le tout à Hazaël, roi de Syrie, qui s''éloigna de Jérusalem.'),
('2r',12,20,'crampon1923','Le reste des actes de Joas, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('2r',12,21,'crampon1923','Ses serviteurs se soulevèrent et, ayant formé une conspiration, ils frappèrent Joas dans la maison de Mello, à la descente de Sella.'),
('2r',12,22,'crampon1923','Ce furent Josachar, fils de Semaath, et Josabad, fils de Somer, ses serviteurs, qui le frappèrent, et il mourut. On l''enterra avec ses pères, dans la ville de David; et Amasias, son fils, régna à sa place.'),
('2r',13,1,'crampon1923','La vingt-troisième année de Joas, fils d''Ochozias, roi de Juda, Joachaz, fils de Jéhu, régna sur Israël, à Samarie; il régna dix-sept ans.'),
('2r',13,2,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh; il imita les péchés de Jéroboam, fils de Nabat, qui avait fait pécher Israël, et il ne s''en détourna point.'),
('2r',13,3,'crampon1923','La colère de Yahweh s''enflamma contre Israël, et il les livra entre les mains de Hazaël, roi de Syrie, et entre les mains de Benhadad, fils de Hazaël, tout le temps.'),
('2r',13,4,'crampon1923','Joachaz implora Yahweh; et Yahweh l''écouta, car il vit l''angoisse d''Israël, opprimé par le roi de Syrie.'),
('2r',13,5,'crampon1923','Et Yahweh donna un libérateur à Israël; soustraits à la puissance des Syriens, les enfants d''Israël habitèrent dans leurs tentes comme auparavant.'),
('2r',13,6,'crampon1923','Mais ils ne se détournèrent point des péchés de la maison de Jéroboam, qui avait fait pécher Israël; ils y marchèrent, et même l''aschérah resta debout à Samarie.'),
('2r',13,7,'crampon1923','Car Yahweh ne laissa à Joachaz d''autre peuple armé, que cinquante cavaliers, dix chars et dix mille hommes de pied; car le roi de Syrie les avait fait périr et les avait rendus semblables à la poussière qu''on foule aux pieds.'),
('2r',13,8,'crampon1923','Le reste des actes de Joachaz, tout ce qu''il a fait, et ses exploits, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('2r',13,9,'crampon1923','Joachaz se coucha avec ses pères, et on l''enterra à Samarie; et Joas, son fils, régna à sa place.'),
('2r',13,10,'crampon1923','La trente-septième année de Joas, roi de Juda, Joas, fils de Joachaz, régna sur Israël, à Samarie; il régna seize ans.'),
('2r',13,11,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh; il ne se détourna d''aucun des péchés de Jéroboam, fils de Nabat, qui avait fait pécher Israël; il y marcha.'),
('2r',13,12,'crampon1923','Le reste des actes de Joas, tout ce qu''il a fait, ses exploits, et comment il combattait avec Amasias, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('2r',13,13,'crampon1923','Joas se coucha avec ses pères, et Jéroboam s''assit sur son trône; et Joas fut enterré à Samarie avec les rois d''Israël.'),
('2r',13,14,'crampon1923','Elisée souffrait de la maladie dont il mourut. Joas, roi d''Israël, descendit vers lui, et il pleura sur son visage, en disant: « Mon père! mon père! Char d''Israël et ses cavaliers! »'),
('2r',13,15,'crampon1923','Elisée lui dit: « Prends un arc et des flèches. » Et il prit un arc et des flèches.'),
('2r',13,16,'crampon1923','Et Elisée dit au roi d''Israël: « Mets ta main sur l''arc. » Quand il eut mis sa main sur l''arc, Elisée mit ses mains sur les mains du roi,'),
('2r',13,17,'crampon1923','et dit: « Ouvre la fenêtre du côté de l''orient; » et il l''ouvrit. Elisée dit: « Lance une flèche; » et il lança une flèche. Elisée dit: « C''est une flèche de délivrance de la part de Yahweh, une flèche de délivrance contre les Syriens! Tu battras les Syriens à Aphec jusqu''à leur extermination. »'),
('2r',13,18,'crampon1923','Elisée dit encore: « Prends les flèches. » Et il les prit. Elisée dit au roi d''Israël: « Frappe contre le sol. » Il frappa le sol trois fois, et s''arrêta.'),
('2r',13,19,'crampon1923','L''homme de Dieu s''irrita contre lui et dit: « Il fallait frapper le sol cinq ou six fois; alors tu aurais battu les Syriens jusqu''à leur extermination; mais maintenant tu battras trois fois les Syriens. »'),
('2r',13,20,'crampon1923','Elisée mourut, et on l''enterra. Les bandes de Moab pénétraient dans le pays quand revenait l''année nouvelle.'),
('2r',13,21,'crampon1923','Comme on enterrait un homme, voici que l''on aperçut une de ces bandes, et l''on jeta l''homme dans le sépulcre d''Elisée. L''homme toucha les os d''Elisée, et il reprit vie, et se leva sur ses pieds.'),
('2r',13,22,'crampon1923','Hazaël, roi de Syrie, avait opprimé Israël pendant toute la vie de Joachaz.'),
('2r',13,23,'crampon1923','Mais Yahweh leur fit miséricorde et eut compassion d''eux; il se tourna vers eux, à cause de son alliance avec Abraham, Isaac et Jacob; il ne voulut pas les détruire, et il ne les a pas rejetés de sa face jusqu''à présent.'),
('2r',13,24,'crampon1923','Hazaël, roi de Syrie, mourut, et Benhadad, son fils, régna à sa place.'),
('2r',13,25,'crampon1923','Joas, fils de Joachaz, reprit des mains de Benhadad, fils de Hazaël, les villes que Hazaël avait enlevées dans la guerre à Joachaz, son père. Joas le battit trois fois, et il recouvra les villes d''Israël.'),
('2r',14,1,'crampon1923','La deuxième année de Joas, fils de Joachaz, roi d''Israël, régna Amasias, fils de Joas, roi de Juda.'),
('2r',14,2,'crampon1923','Il avait vingt-cinq ans, lorsqu''il devint roi, et il régna vingt-neuf ans à Jérusalem. Sa mère s''appelait Joadan, de Jérusalem.'),
('2r',14,3,'crampon1923','Il fit ce qui est droit aux yeux de Yahweh, non pas toutefois comme David, son père; il se conduisit en tout comme avait Joas, son père.'),
('2r',14,4,'crampon1923','Seulement les hauts lieux ne disparurent point; le peuple continuait d''offrir des sacrifices et des parfums sur les hauts lieux.'),
('2r',14,5,'crampon1923','Lorsque la royauté fut affermie dans sa main, il frappa ses serviteurs, qui avaient tué le roi, son père.'),
('2r',14,6,'crampon1923','Mais il ne fit pas mourir les fils des meurtriers, selon ce qui est écrit dans le livre de la loi de Moïse, où Yahweh donne ce commandement: « Les pères ne seront pas mis à mort pour les enfants, et les enfants ne seront pas mis à mort pour les pères; mais on fera mourir chacun pour son péché. »'),
('2r',14,7,'crampon1923','Il battit dix mille Edomites dans la vallée du Sel, et il prit d''assaut Séla, et lui donna le nom de Jectéhel, qu''elle a conservé jusqu''à ce jour.'),
('2r',14,8,'crampon1923','Alors Amasias envoya des messagers à Joas, fils de Joachaz, fils de Jéhu, roi d''Israël, pour lui dire: « Viens, et voyons-nous en face. »'),
('2r',14,9,'crampon1923','Et Joas, roi d''Israël, envoya répondre à Amasias, roi de Juda: « L''épine qui est au Liban envoya dire au cèdre qui est au Liban: Donne ta fille pour femme à mon fils! Et les bêtes sauvages qui sont au Liban passèrent et foulèrent aux pieds l''épine.'),
('2r',14,10,'crampon1923','Tu as, en vérité, battu les Edomites, et ton cœur s''est élevé. Glorifie-toi, et reste chez toi. Pourquoi t''engager dans le malheur, pour tomber, toi, et Juda avec toi? »'),
('2r',14,11,'crampon1923','Mais Amasias ne l''écouta pas. Et Joas, roi d''Israël, monta, et ils se virent en face, lui et Amasias, roi de Juda, à Bethsamès, qui est à Juda.'),
('2r',14,12,'crampon1923','Juda fut battu devant Israël, et chacun s''enfuit dans sa tente.'),
('2r',14,13,'crampon1923','Joas, roi d''Israël, prit à Bethsamès Amasias, roi de Juda, fils de Joas, fils d''Ochozias. Il vint à Jérusalem et fit une brèche de quatre cents coudées dans la muraille de Jérusalem, depuis la porte d''Ephraïm jusqu''à la porte de l''angle.'),
('2r',14,14,'crampon1923','Il prit tout l''or et l''argent et tous les ustensiles qui se trouvaient dans la maison de Yahweh et dans les trésors de la maison du roi; il prit aussi des otages, et retourna à Samarie.'),
('2r',14,15,'crampon1923','Le reste des actes de Joas, ce qu''il a fait, et comment il combattit avec Amasias, roi de Juda, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('2r',14,16,'crampon1923','Joas se coucha avec ses pères, et il fut enterré à Samarie, avec les rois d''Israël. Jéroboam, son fils, régna à sa place.'),
('2r',14,17,'crampon1923','Amasias, fils de Joas, roi de Juda, vécut quinze ans après la mort de Joas, fils de Joachaz, roi d''Israël.'),
('2r',14,18,'crampon1923','Le reste des actes d''Amasias n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('2r',14,19,'crampon1923','On ourdit contre lui une conspiration à Jérusalem, et il s''enfuit à Lachis; mais on envoya après lui des hommes à Lachis, et on l''y mit à mort.'),
('2r',14,20,'crampon1923','On le transporta sur des chevaux, et il fut enterré à Jérusalem avec ses pères, dans la cité de David.'),
('2r',14,21,'crampon1923','Et tout le peuple de Juda prit Azarias, qui était âgé de seize ans; et on l''établit roi à la place de son père Amasias.'),
('2r',14,22,'crampon1923','Azarias rebâtit Elath et la ramena à Juda, après que le roi fut couché avec ses pères.'),
('2r',14,23,'crampon1923','La quinzième année d''Amasias, fils de Joas, roi de Juda, Jéroboam, fils de Joas roi d''Israël, régna à Samarie; son règne fut de quarante et un ans.'),
('2r',14,24,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh; il ne se détourna d''aucun des péchés de Jéroboam, fils de Nabat, qui avait fait pécher Israël.'),
('2r',14,25,'crampon1923','Il rétablit les limites d''Israël depuis l''entrée d''Emath jusqu''à la mer de l''Arabah, selon la parole de Yahweh, Dieu d''Israël, qu''il avait dite par l''organe de son serviteur Jonas, le prophète, fils d''Amathi, qui était de Geth-Chépher.'),
('2r',14,26,'crampon1923','Car Yahweh vit l''affliction très amère d''Israël, où il n''y avait plus ni homme marié, ni homme libre, ni personne pour venir au secours d''Israël.'),
('2r',14,27,'crampon1923','Et Yahweh n''avait pas encore résolu d''effacer le nom d''Israël de dessous les cieux, mais il les délivra par la main de Jéroboam, fils de Joas.'),
('2r',14,28,'crampon1923','Le reste des actes de Jéroboam, tout ce qu''il a fait, ses exploits, comment il combattit et comment il ramena à Israël Damas et Emath qui avait appartenu à Juda, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('2r',14,29,'crampon1923','Jéroboam se coucha avec ses pères, avec les rois d''Israël; et Zacharias, son fils, régna à sa place.'),
('2r',15,1,'crampon1923','La vingt-septième année de Jéroboam, roi d''Israël, régna Azarias, fils d''Amasias, roi de Juda.'),
('2r',15,2,'crampon1923','Il avait seize ans lorsqu''il devint roi, et il régna cinquante-deux ans à Jérusalem. Sa mère se nommait Jéchélia, de Jérusalem.'),
('2r',15,3,'crampon1923','Il fit ce qui est droit aux yeux de Yahweh, selon tout ce qu''avait fait Amasias, son père.'),
('2r',15,4,'crampon1923','Seulement les hauts lieux ne disparurent point; le peuple continuait à offrir des sacrifices et des parfums sur les hauts lieux.'),
('2r',15,5,'crampon1923','Yahweh frappa le roi, qui fut lépreux jusqu''au jour de sa mort et demeura dans une maison écartée. Joatham, fils du roi, était à la tête de la maison, jugeant le peuple du pays.'),
('2r',15,6,'crampon1923','Le reste des actes d''Azarias, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('2r',15,7,'crampon1923','Azarias se coucha avec ses pères, et on l''enterra avec ses pères dans la cité de David; et Joatham, son fils, régna à sa place.'),
('2r',15,8,'crampon1923','La trente-huitième année d''Azarias, roi de Juda, Zacharie, fils de Jéroboam, régna sur Israël à Samarie; son règne fut de six mois.'),
('2r',15,9,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, comme avaient fait ses pères; il ne se détourna pas des péchés de Jéroboam, fils de Nabat, qui avait fait pécher Israël.'),
('2r',15,10,'crampon1923','Sellum, fils de Jabès, conspira contre lui et, l''ayant frappé devant le peuple, il le mit à mort, et régna à sa place.'),
('2r',15,11,'crampon1923','Le reste des actes de Zacharie, voici que cela est écrit dans le livre des Chroniques des rois d''Israël.'),
('2r',15,12,'crampon1923','Telle était la parole de Yahweh, qu''il avait dite à Jéhu: « Tes fils jusqu''à la quatrième génération seront assis sur le trône d''Israël. » Et il en fut ainsi.'),
('2r',15,13,'crampon1923','Sellum, fils de Jabès, devint roi la trente-neuvième année d''Ozias, roi de Juda, et il régna pendant un mois à Samarie.'),
('2r',15,14,'crampon1923','Manahem, fils de Gadi, monta de Thersa et, étant venu à Samarie, il frappa dans Samarie Sellum, fils de Jabès, et le mit à mort; et il régna à sa place.'),
('2r',15,15,'crampon1923','Le reste des actes de Sellum, et la conspiration qu''il ourdit, voici que cela est écrit dans le livre des Chroniques des rois d''Israël.'),
('2r',15,16,'crampon1923','Alors Manahem, étant parti de Thersa, frappa Thapsa et tous ceux qui y étaient, avec son territoire; il la frappa, parce qu''elle n''avait pas ouvert ses portes, et il fendit le ventre de toutes les femmes enceintes.'),
('2r',15,17,'crampon1923','La trente-neuvième année d''Azarias, roi de Juda, Manahem, fils de Gadi, devint roi sur Israël; il régna dix ans à Samarie.'),
('2r',15,18,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, il ne se détourna pas, tant qu''il vécut, des péchés de Jéroboam, fils de Nabat, qui avait fait pécher Israël.'),
('2r',15,19,'crampon1923','Phul, roi d''Assyrie, vint dans le pays, et Manahem donna à Phul mille talents d''argent pour qu''il lui portât secours, et qu''il affermît le royaume dans sa main.'),
('2r',15,20,'crampon1923','Manahem leva cet argent sur Israël, sur tous ceux qui avaient de grandes richesses, afin de le donner au roi d''Assyrie; il exigea de chacun cinquante sicles d''argent. Le roi d''Assyrie s''en retourna et ne s''arrêta pas là, dans le pays.'),
('2r',15,21,'crampon1923','Le reste des actes de Manahem, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois d''Israël?'),
('2r',15,22,'crampon1923','Manahem se coucha avec ses pères; et Phacéia, son fils, régna à sa place.'),
('2r',15,23,'crampon1923','La cinquantième année d''Azarias, roi de Juda, Phacéia, fils de Manahem, régna sur Israël à Samarie; son règne fut de deux ans.'),
('2r',15,24,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh; il ne se détourna pas des péchés de Jéroboam, fils de Nabat, qui avait fait pécher Israël.'),
('2r',15,25,'crampon1923','Phacée, fils de Romélias, son officier, conspira contre lui; il le frappa à Samarie dans la tour de la maison du roi, ainsi qu''Argob et Arié; il avait avec lui cinquante hommes d''entre les fils des Galaadites. Il fit mourir Phacéia, et régna à sa place.'),
('2r',15,26,'crampon1923','Le reste des actes de Phacéia, et tout ce qu''il a fait, voici que cela est écrit dans le livre des Chroniques des rois d''Israël.'),
('2r',15,27,'crampon1923','La cinquante-deuxième année d''Azarias, roi de Juda, Phacée, fils de Romélias, régna sur Israël à Samarie; son règne fut de vingt ans.'),
('2r',15,28,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, il ne se détourna pas des péchés de Jéroboam, fils de Nabat, qui avait fait pécher Israël.'),
('2r',15,29,'crampon1923','Du temps de Phacée, roi d''Israël, Téglathphalasar, roi d''Assyrie, vint et prit Ajon, Abel-Beth-Machaa, Janoé, Cédès, Asor, Galaad et la Galilée, tout le pays de Nephthali, et il emmena captifs les habitants en Assyrie.'),
('2r',15,30,'crampon1923','Osée, fils d''Ela, ayant formé une conspiration contre Phacée, fils de Romélias, le frappa et le fit mourir; puis il régna à sa place, la vingtième année de Joatham, fils d''Ozias.'),
('2r',15,31,'crampon1923','Le reste des actes de Phacée, et tout ce qu''il a fait, voici que cela est écrit dans le livre des Chroniques des rois d''Israël.'),
('2r',15,32,'crampon1923','La deuxième année de Phacée, fils de Romélias, roi d''Israël, régna Joatham, fils d''Ozias, roi de Juda.'),
('2r',15,33,'crampon1923','Il avait vingt-cinq ans lorsqu''il devint roi, et il régna seize ans à Jérusalem. Sa mère s''appelait Jérusa, fille de Sadoc.'),
('2r',15,34,'crampon1923','Il fit ce qui est droit aux yeux de Yahweh; il agit entièrement comme avait agi Ozias, son père.'),
('2r',15,35,'crampon1923','Seulement les hauts lieux ne disparurent point; le peuple continuait d''offrir des sacrifices et des parfums sur les hauts lieux. Joatham bâtit la porte supérieure de la maison de Yahweh.'),
('2r',15,36,'crampon1923','Le reste des actes de Joatham, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('2r',15,37,'crampon1923','Dans ce temps-là, Yahweh commença à envoyer contre Juda Rasin, roi de Syrie, et Phacée, fils de Romélias.'),
('2r',15,38,'crampon1923','Joatham se coucha avec ses pères, et il fut enterré avec ses pères dans la cité de David, son père. Achaz, son fils, régna à sa place.'),
('2r',16,1,'crampon1923','La dix-septième année de Phacée, fils de Romélias, régna Achaz, fils de Joatham, roi de Juda.'),
('2r',16,2,'crampon1923','Achaz avait vingt ans lorsqu''il devint roi, et il régna seize ans à Jérusalem. Il ne fit pas ce qui est droit aux yeux de Yahweh, son Dieu, comme avait fait David, son père.'),
('2r',16,3,'crampon1923','Mais il marcha dans la voie des rois d''Israël, et même il fit passer son fils par le feu, selon les abominations des nations que Yahweh avait chassées devant les enfants d''Israël.'),
('2r',16,4,'crampon1923','Il offrait des sacrifices et des parfums aux hauts lieux, sur les collines et sous tout arbre vert.'),
('2r',16,5,'crampon1923','Alors Rasin, roi de Syrie, et Phacée, fils de Romélias, roi d''Israël, montèrent contre Jérusalem pour l''attaquer. Ils assiégèrent Achaz, mais ils ne purent pas le vaincre.'),
('2r',16,6,'crampon1923','Dans ce même temps, Rasin, roi de Syrie, ramena Elath au pouvoir des Syriens; il expulsa les Juifs d''Elath, et les Syriens vinrent à Elath, où ils ont habité jusqu''à ce jour.'),
('2r',16,7,'crampon1923','Achaz envoya des messagers à Téglathphalasar, roi d''Assyrie, pour lui dire: « Je suis ton serviteur et ton fils; monte et délivre-moi de la main du roi de Syrie et de la main du roi d''Israël, qui se sont levés contre moi. »'),
('2r',16,8,'crampon1923','Et Achaz prit l''argent et l''or qui se trouvaient dans la maison de Yahweh et dans les trésors de la maison du roi, et il l''envoya en présent au roi d''Assyrie.'),
('2r',16,9,'crampon1923','Le roi d''Assyrie l''écouta, et le roi d''Assyrie monta contre Damas et, l''ayant prise, il en emmena les habitants en captivité à Qir, et il fit mourir Rasin.'),
('2r',16,10,'crampon1923','Le roi Achaz se rendit à Damas au-devant de Téglathphalasar, roi d''Assyrie. Ayant vu l''autel qui était à Damas, le roi Achaz envoya au prêtre Urias le modèle de l''autel et sa forme selon tout son travail.'),
('2r',16,11,'crampon1923','Le prêtre Urias construisit l''autel; le prêtre Urias le fit entièrement d''après le modèle que le roi Achaz avait envoyé de Damas, avant que le roi ne revienne de Damas.'),
('2r',16,12,'crampon1923','A son arrivée de Damas, le roi vit l''autel. Le roi s''approcha de l''autel et il y monta;'),
('2r',16,13,'crampon1923','il fit brûler son holocauste et son oblation, versa sa libation, et répandit sur l''autel le sang de ses sacrifices pacifiques.'),
('2r',16,14,'crampon1923','Il éloigna de devant la maison, d''entre le nouvel autel et la maison de Yahweh, l''autel d''airain qui était devant Yahweh, et il le plaça à côté du nouvel autel, vers le nord.'),
('2r',16,15,'crampon1923','le roi Achaz donna encore cet ordre au prêtre Urias: « Fais brûler sur le grand autel l''holocauste du matin et l''oblation du soir, l''holocauste du roi et son oblation, l''holocauste de tout le peuple du pays et leur oblation, verses-y leur libation et répands-y tout le sang des holocaustes et tout le sang des sacrifices. Pour ce qui concerne l''autel d''airain, il m''appartiendra d''y pourvoir. »'),
('2r',16,16,'crampon1923','Le prêtre Urias fit tout ce qu''avait ordonné le roi Achaz.'),
('2r',16,17,'crampon1923','En outre, le roi Achaz brisa les cadres et les bases, et ôta les bassins qui étaient dessus; il descendit la mer d''airain de dessus les bœufs d''airain qui la supportaient, et il la posa sur un pavé de pierres;'),
('2r',16,18,'crampon1923','il changea, dans la maison de Yahweh, par considération pour le roi d''Assyrie, le portique du sabbat, qu''on avait construit dans la maison, et l''entrée extérieure du roi.'),
('2r',16,19,'crampon1923','Le reste des actes d''Achaz, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('2r',16,20,'crampon1923','Achaz se coucha avec ses pères, et il fut enterré avec ses pères dans la cité de David. Ezéchias, son fils, régna à sa place.'),
('2r',17,1,'crampon1923','La douzième année d''Achaz, roi de Juda, Osée, fils d''Ela, régna sur Israël à Samarie; son règne fut de neuf ans.'),
('2r',17,2,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, non pas cependant comme les rois d''Israël qui avaient été avant lui.'),
('2r',17,3,'crampon1923','Salmanasar, roi d''Assyrie, monta contre lui, et Osée fut assujetti et lui paya tribut.'),
('2r',17,4,'crampon1923','Mais le roi d''Assyrie découvrit une conspiration d''Osée, qui avait envoyé des messagers à Sua, roi d''Egypte, et qui ne payait plus le tribut au roi d''Assyrie, année par année; le roi d''Assyrie le fit donc saisir et jeter enchaîné dans une prison.'),
('2r',17,5,'crampon1923','Et le roi d''Assyrie parcourut tout le pays et monta contre Samarie; il l''assiégea pendant trois ans.'),
('2r',17,6,'crampon1923','La neuvième année d''Osée, le roi d''Assyrie prit Samarie; et emmena Israël captif en Assyrie. Il leur assigna pour séjour Hala, les rives du Habor, fleuve de Gosan, et les villes des Mèdes.'),
('2r',17,7,'crampon1923','Cela arriva parce que les enfants d''Israël avaient péché contre Yahweh, leur Dieu, qui les avait fait monter du pays d''Egypte, de dessous la main de Pharaon, roi d''Egypte, et parce qu''ils avaient craint d''autres dieux.'),
('2r',17,8,'crampon1923','Ils suivirent les rites des nations que Yahweh avait chassées devant les enfants d''Israël, et ceux que les rois d''Israël avaient établis.'),
('2r',17,9,'crampon1923','Les enfants d''Israël couvrirent d''une fausse apparence des choses qui n''étaient pas bien à l''égard de Yahweh, leur Dieu. Ils se bâtirent des hauts lieux dans toutes leurs villes, depuis les tours des gardiens jusqu''aux villes fortifiées.'),
('2r',17,10,'crampon1923','Ils se dressèrent des stèles et des aschérahs sur toute colline élevée et sous tout arbre vert.'),
('2r',17,11,'crampon1923','Et là ils brûlèrent des parfums sur tous les hauts lieux, comme les nations que Yahweh avait emmenées captives devant eux, et ils firent des choses mauvaises, irritant ainsi Yahweh.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('2r',17,12,'crampon1923','Ils servirent les idoles, au sujet desquelles Yahweh leur avait dit: « Vous ne ferez pas cela. »'),
('2r',17,13,'crampon1923','Yahweh rendit témoignage contre Israël et contre Juda par tous ses prophètes, par tous les voyants, en disant: « Revenez de vos mauvaises voies, et observez mes commandements et mes ordonnances, en suivant toute la loi que j''ai prescrite à vos pères et que je vous ai envoyée par l''organe de mes serviteurs les prophètes. »'),
('2r',17,14,'crampon1923','Mais ils n''écoutèrent point, et ils raidirent leur cou, comme leurs pères, qui n''avaient pas cru à Yahweh, leur Dieu.'),
('2r',17,15,'crampon1923','Ils rejetèrent ses ordonnances et son alliance qu''il avait conclue avec leurs pères, et les témoignages qu''il avait rendus contre eux. Ils allèrent après des choses de néant, et s''adonnèrent à la vanité, à la suite des nations qui les entouraient et que Yahweh leur avait commandé de ne pas imiter.'),
('2r',17,16,'crampon1923','Ils abandonnèrent tous les commandements de Yahweh, leur Dieu, ils se firent deux veaux en fonte, et ils se firent des aschérahs; ils se prosternèrent devant toute l''armée des cieux et ils servirent Baal.'),
('2r',17,17,'crampon1923','Ils firent passer par le feu leurs fils et leurs filles, ils pratiquèrent la divination et les enchantements, et ils s''appliquèrent à faire ce qui est mal aux yeux de Yahweh, de manière à l''irriter.'),
('2r',17,18,'crampon1923','Et Yahweh s''est fortement irrité contre Israël et il les a éloignés de sa face. — Il n''est resté que la seule tribu de Juda,'),
('2r',17,19,'crampon1923','quoique Juda lui-même n''eût pas gardé les commandements de Yahweh, leur Dieu, et qu''ils eussent suivi les rites établis par Israël. —'),
('2r',17,20,'crampon1923','Yahweh a rejeté toute la race d''Israël; il les a affligés, il les a livrés entre les mains des pillards, jusqu''à ce qu''il les ait chassés loin de sa face.'),
('2r',17,21,'crampon1923','Car Israël s''était détaché de la maison de David, et ils avaient établi roi Jéroboam, fils de Nabat; et Jéroboam avait détourné Israël de Yahweh et leur avait fait commettre un grand péché.'),
('2r',17,22,'crampon1923','Et les enfants d''Israël marchèrent dans tous les péchés que Jéroboam avait commis; ils ne s''en détournèrent point,'),
('2r',17,23,'crampon1923','jusqu''à ce que Yahweh eût chassé Israël loin de sa face, comme il l''avait dit par l''organe de tous ses serviteurs les prophètes. Et Israël fut emmené captif loin de son pays en Assyrie, où il est resté jusqu''à ce jour.'),
('2r',17,24,'crampon1923','Le roi d''Assyrie fit venir des gens de Babylone, de Cutha, d''Avah, d''Emath et de Sépharvaïm, et les établit dans les villes de Samarie à la place des enfants d''Israël; ils prirent possession de Samarie et ils habitèrent dans ses villes.'),
('2r',17,25,'crampon1923','Lorsqu''ils commencèrent à y habiter, ils ne craignaient pas Yahweh, et Yahweh envoya contre eux des lions qui les tuaient.'),
('2r',17,26,'crampon1923','On fit donc ce rapport au roi d''Assyrie: « Les nations que tu as déportées et établies dans les villes de Samarie ne connaissent pas la manière de servir le dieu du pays; et il a envoyé contre elles des lions et voici qu''ils les font mourir; parce qu''elles ignorent la manière de servir le dieu du pays. »'),
('2r',17,27,'crampon1923','Le roi d''Assyrie donna cet ordre: « Envoyez-y un des prêtres que vous avez amenés de là en captivité; qu''il aille s''y établir, et qu''il leur enseigne la manière de servir le dieu du pays. »'),
('2r',17,28,'crampon1923','Un des prêtres qu''on avait emmenés captifs de Samarie vint s''établir à Béthel, et leur enseigna comment ils devaient honorer Yahweh.'),
('2r',17,29,'crampon1923','Mais les nations firent chacune leurs dieux, et les placèrent dans les maisons des hauts lieux bâties par les Samaritains, chaque nation dans la ville qu''elle habitait.'),
('2r',17,30,'crampon1923','Les gens de Babylone firent Sochoth-Benoth, les gens de Cutha firent Nergel, les gens d''Emath firent Asima,'),
('2r',17,31,'crampon1923','ceux d''Avah firent Nebahaz et Tharthac, et ceux de Sapharvaïm livraient leurs enfants au feu en l''honneur d''Adramélech et d''Anamélech, dieux de Sépharvaïm.'),
('2r',17,32,'crampon1923','Ils honoraient aussi Yahweh, et ils se firent des prêtres des hauts lieux pris parmi tout le peuple, et ces prêtres faisaient pour eux des sacrifices dans les maisons des hauts lieux.'),
('2r',17,33,'crampon1923','Ainsi ils honoraient Yahweh, et ils servaient en même temps leurs dieux selon la coutume des nations d''où on les avait déportés.'),
('2r',17,34,'crampon1923','Ils suivent jusqu''à aujourd''hui les premières coutumes; ils ne craignent point Yahweh, et ils ne se conforment ni à leurs règlements et à leurs ordonnances, ni à la loi et aux commandements donnés par Yahweh aux enfants de Jacob, qu''il appela du nom d''Israël.'),
('2r',17,35,'crampon1923','Yahweh avait conclu une alliance avec eux et leur avait donné cet ordre: « Vous ne craindrez point d''autres dieux, vous ne vous prosternerez point devant eux, vous ne les servirez point et vous ne leur offrirez point de sacrifices.'),
('2r',17,36,'crampon1923','Mais Yahweh, votre Dieu, qui vous a fait monter du pays d''Egypte par une grande puissance et par son bras étendu, c''est lui que vous craindrez, devant lui que vous vous prosternerez, à lui que vous offrirez des sacrifices.'),
('2r',17,37,'crampon1923','Vous observerez les préceptes, les ordonnances, la loi et les commandements qu''il a écrits pour vous, les mettant toujours en pratique, et vous ne craindrez point d''autres dieux.'),
('2r',17,38,'crampon1923','Vous n''oublierez pas l''alliance que j''ai conclue avec vous, et vous ne craindrez point d''autres dieux.'),
('2r',17,39,'crampon1923','Mais vous craindrez Yahweh, votre Dieu, et c''est lui qui vous délivrera de la main de tous vos ennemis. »'),
('2r',17,40,'crampon1923','Et ils n''ont pas obéi, mais ils ont suivi leurs premières coutumes.'),
('2r',17,41,'crampon1923','Ainsi ces nations craignaient Yahweh, et en même temps servaient leurs images, et leurs enfants et les enfants de leurs enfants font jusqu''à ce jour ce qu''on fait leurs pères.'),
('2r',18,1,'crampon1923','La troisième année d''Osée, fils d''Ela, roi d''Israël, régna Ezéchias, fils d''Achaz, roi de Juda.'),
('2r',18,2,'crampon1923','Il avait vingt-cinq ans lorsqu''il devint roi, et il régna vingt-neuf ans à Jérusalem. Sa mère s''appelait Abi, fille de Zacharias.'),
('2r',18,3,'crampon1923','Il fit ce qui est droit aux yeux de Yahweh, selon tout ce qu''avait fait David, son père.'),
('2r',18,4,'crampon1923','Il fit disparaître les hauts lieux, brisa les stèles, coupa les aschérahs, et mit en pièces le serpent d''airain que Moïse avait fait, car les enfants d''Israël brûlaient jusqu''alors des parfums devant lui: on l''appelait Nohestan.'),
('2r',18,5,'crampon1923','Il mit sa confiance dans Yahweh, Dieu d''Israël, et il n''eut pas son semblable parmi tous les rois de Juda qui vinrent après lui ou qui le précédèrent.'),
('2r',18,6,'crampon1923','Attaché à Yahweh, il ne se détourna pas de lui, et il observa ses commandements que Yahweh avait prescrits à Moïse.'),
('2r',18,7,'crampon1923','Et Yahweh fut avec Ezéchias, et il réussit dans toutes ses entreprises. Ils se révolta contre le roi d''Assyrie, et il ne lui fut plus assujetti.'),
('2r',18,8,'crampon1923','Il battit les Philistins jusqu''à Gaza et ravagea son territoire, depuis la tour des gardiens jusqu''aux villes fortes.'),
('2r',18,9,'crampon1923','La quatrième année du roi Ezéchias, qui était la septième année d''Osée, fils d''Ela, roi d''Israël, Salmanasar, roi d''Assyrie, monta contre Samarie et l''assiégea.'),
('2r',18,10,'crampon1923','On la prit au bout de trois ans; ce fut la sixième année d''Ezéchias, qui était la neuvième d''Osée, roi d''Israël, que Samarie fut prise.'),
('2r',18,11,'crampon1923','Le roi d''Assyrie emmena Israël captif en Assyrie; il les établit à Hala, sur les rives du Habor, fleuve de Gosan, et dans les villes des Mèdes,'),
('2r',18,12,'crampon1923','parce qu''ils n''avaient pas écouté la voix de Yahweh leur Dieu, et qu''ils avaient transgressé son alliance, parce qu''ils n''avaient ni écouté ni mis en pratique tout ce qu''avait ordonné Moïse, serviteur de Yahweh.'),
('2r',18,13,'crampon1923','La quatorzième année du roi Ezéchias, Sennachérib, roi d''Assyrie, monta contre toutes les villes fortes de Juda et s''en empara.'),
('2r',18,14,'crampon1923','Ezéchias, roi de Juda, envoya dire au roi d''Assyrie à Lachis: « J''ai commis une faute; éloigne-toi de moi; ce que tu m''imposeras, je le subirai. » Et le roi d''Assyrie imposa à Ezéchias, roi de Juda, trois cents talents d''argent et trente talents d''or.'),
('2r',18,15,'crampon1923','Ezéchias donna tout l''argent qui se trouvait dans la maison de Yahweh et dans les trésors de la maison du roi.'),
('2r',18,16,'crampon1923','En ce temps-là Ezéchias, roi de Juda, brisa les portes du temple de Yahweh et les piliers qu''Ezéchias, roi de Juda, avait lui-même revêtus d''or, et il donna l''or au roi d''Assyrie.'),
('2r',18,17,'crampon1923','Le roi d''Assyrie envoya de Lachis à Jérusalem, vers le roi Ezéchias, son général en chef, son chef des eunuques et son grand échanson avec une troupe nombreuse; ils montèrent et arrivèrent à Jérusalem. Lorsqu''ils furent montés et arrivés, ils s''arrêtèrent à l''aqueduc de l''étang supérieur, sur le chemin du champ du Foulon,'),
('2r',18,18,'crampon1923','et appelèrent le roi. Eliacim, fils d''Helcias, chef de la maison du roi, se rendit auprès d''eux, avec Sobna, le secrétaire, et Joahé, fils d''Asaph, l''archiviste.'),
('2r',18,19,'crampon1923','Le grand échanson leur dit: « Dites à Ezéchias: Ainsi dit le grand roi, le roi d''Assyrie: Quelle est cette confiance sur laquelle tu t''appuies?'),
('2r',18,20,'crampon1923','Tu as dit — paroles en l''air! — J''ai conseil et force pour la guerre. Et maintenant, en qui te confies-tu pour te révolter contre moi?'),
('2r',18,21,'crampon1923','Voici que maintenant tu te fies à l''appui de ce roseau cassé — l''Egypte — qui pénètre et perce la main de quiconque s''appuie dessus: tel est Pharaon, roi d''Egypte, pour tous ceux qui se confient en lui.'),
('2r',18,22,'crampon1923','Peut-être me direz-vous: C''est en Yahweh, notre Dieu, que nous avons confiance!... Mais n''est-ce pas lui dont Ezéchias a fait disparaître les hauts lieux et les autels, en disant à Juda et à Jérusalem: Vous vous prosternerez devant cet autel, à Jérusalem?'),
('2r',18,23,'crampon1923','Maintenant, fais un accord avec mon maître, le roi d''Assyrie: je te donnerai deux mille chevaux, si tu peux fournir des cavaliers pour les monter!...'),
('2r',18,24,'crampon1923','Comment repousserais-tu un seul chef d''entre les moindres serviteurs de mon maître? Aussi mets-tu ta confiance dans l''Egypte pour les chars et pour les cavaliers.'),
('2r',18,25,'crampon1923','Maintenant, est-ce sans la volonté de Yahweh que je suis monté contre ce lieu pour le détruire? Yahweh m''a dit: « Monte contre ce pays et détruis-le. »'),
('2r',18,26,'crampon1923','Eliacim, fils d''Helcias, Sobna et Joahé dirent au grand échanson: « Parle à tes serviteurs en araméen, car nous l''entendons; et ne nous parle pas en langue judaïque, aux oreilles du peuple qui est sur la muraille. »'),
('2r',18,27,'crampon1923','Le grand échanson leur répondit: « Est-ce à ton maître et à toi que mon maître m''a envoyé dire ces paroles? N''est-ce pas à ces hommes assis sur la muraille, pour manger leurs excréments et pour boire leur urine avec vous? »'),
('2r',18,28,'crampon1923','Alors le grand échanson, s''étant avancé, cria à haute voix en langue judaïque et tint ce langage: « Ecoutez la parole du grand roi, du roi d''Assyrie!'),
('2r',18,29,'crampon1923','Ainsi dit le roi: Qu''Ezéchias ne vous abuse pas, car il ne pourra vous délivrer de sa main.'),
('2r',18,30,'crampon1923','Qu''Ezéchias ne vous persuade pas de vous confier en Yahweh, en disant: Yahweh nous délivrera sûrement, et cette ville ne sera pas livrée entre les mains du roi d''Assyrie.'),
('2r',18,31,'crampon1923','N''écoutez point Ezéchias, car ainsi dit le roi d''Assyrie: Faites la paix avec moi et rendez-vous à moi; et que chacun de vous mange de sa vigne et chacun de son figuier, et que chacun boive l''eau de son puits,'),
('2r',18,32,'crampon1923','jusqu''à ce que je vienne et que je vous emmène dans un pays comme le vôtre, un pays de blé et de vin, un pays de pain et de vignes, un pays d''oliviers à huile et de miel, afin que vous viviez et ne mourriez point. N''écoutez donc pas Ezéchias, car il vous abuse en disant: Yahweh nous délivrera.'),
('2r',18,33,'crampon1923','Est-ce que les dieux des nations ont délivré chacun leur pays de la main du roi d''Assyrie?'),
('2r',18,34,'crampon1923','Où sont les dieux d''Emath et d''Arphad? Où sont les dieux de Sépharvaïm, d''Ana et d''Ava? Ont-ils délivré Samarie de ma main?'),
('2r',18,35,'crampon1923','Quels sont, parmi tous les dieux des pays, ceux qui ont délivré leur pays de ma main, pour que Yahweh puisse délivrer Jérusalem de ma main? »'),
('2r',18,36,'crampon1923','Le peuple se tut et ne lui répondit pas un mot, car le roi avait donné cet ordre: « Vous ne lui répondrez pas. »'),
('2r',18,37,'crampon1923','Et Eliacim, fils d''Helcias, chef de la maison du roi, Sobna, le secrétaire, et Joahé, fils d''Asaph, l''archiviste, vinrent auprès d''Ezéchias, les vêtements déchirés, et lui rapportèrent les paroles du grand échanson.'),
('2r',19,1,'crampon1923','Lorsque le roi Ezéchias eut entendu ce rapport, il déchira ses vêtements, se couvrit d''un sac et alla dans la maison de Yahweh.'),
('2r',19,2,'crampon1923','Il envoya Eliacim, chef de sa maison, Sobna, le secrétaire, et les anciens des prêtres, couverts de sacs, vers Isaïe, le prophète, fils d''Amos.'),
('2r',19,3,'crampon1923','Ils lui dirent: « Ainsi dit Ezéchias: Ce jour est un jour d''angoisse, de châtiment et d''opprobre; car les enfants sont près de sortir du sein maternel, et il n''y a point de force pour enfanter.'),
('2r',19,4,'crampon1923','Peut-être Yahweh, ton Dieu, entendra-t-il toutes les paroles du grand échanson, que le roi d''Assyrie, son maître, a envoyé pour insulter au Dieu vivant, et le punira-t-il à cause des paroles qu''a entendues Yahweh, ton Dieu. Fais donc monter une prière pour le reste qui subsiste encore. »'),
('2r',19,5,'crampon1923','Les serviteurs du roi Ezéchias se rendirent auprès d''Isaïe;'),
('2r',19,6,'crampon1923','et Isaïe leur dit: « Voici ce que vous direz à votre maître. Ainsi dit Yahweh: “Ne t''effraie point des paroles que tu as entendues, par lesquelles les serviteurs du roi d''Assyrie m''ont outragé.'),
('2r',19,7,'crampon1923','Voici que je mets en lui un esprit tel que, sur une nouvelle qu''il apprendra, il retournera dans son pays, et je le ferai tomber par l''épée dans son pays.” »'),
('2r',19,8,'crampon1923','Le grand échanson s''en retourna et trouva le roi d''Assyrie qui attaquait Lobna; car il avait appris que son maître était parti de Lachis.'),
('2r',19,9,'crampon1923','Le roi d''Assyrie reçut une nouvelle au sujet de Tharaca, roi d''Ethiopie; on lui dit: « Voici qu''il s''est mis en marche pour te faire la guerre. » Et il envoya de nouveau des messagers à Ezéchias, en disant:'),
('2r',19,10,'crampon1923','« Vous parlerez ainsi à Ezéchias, roi de Juda: Que ton Dieu en qui tu te confies, ne t''abuse point en disant: Jérusalem ne sera pas livrée entre les mains du roi d''Assyrie.'),
('2r',19,11,'crampon1923','Voici que tu as appris ce qu''ont fait les rois d''Assyrie à tous les pays, les soumettant à l''anathème!... Et toi, tu serais délivré!...'),
('2r',19,12,'crampon1923','Est-ce que leurs dieux les ont délivrées, ces nations que mes pères ont détruites: Gosan, Haran, Réseph, et les fils d''Eden qui étaient à Thélasar?'),
('2r',19,13,'crampon1923','Où sont le roi d''Emath, le roi d''Arphad et le roi de la ville de Sépharvaïm, d''Ana et d''Ava? »'),
('2r',19,14,'crampon1923','Ezéchias ayant pris la lettre de la main des messagers, la lut; puis Ezéchias monta à la maison de Yahweh et la déploya devant Yahweh.'),
('2r',19,15,'crampon1923','Et Ezéchias pria devant Yahweh, en disant: « Yahweh, Dieu d''Israël, assis sur les Chérubins, c''est vous qui êtes le seul Dieu de tous les royaumes de la terre, vous qui avez fait les cieux et la terre.'),
('2r',19,16,'crampon1923','Yahweh, inclinez votre oreille et écoutez; Yahweh, ouvrez vos yeux et regardez. Entendez les paroles de Sennachérib, qui a envoyé le grand échanson pour insulter au Dieu vivant.'),
('2r',19,17,'crampon1923','Il est vrai, Yahweh, que les rois d''Assyrie ont détruit les nations et dévasté leurs territoires,'),
('2r',19,18,'crampon1923','et qu''ils ont jeté leurs dieux dans le feu; car ce n''étaient pas des dieux, mais des ouvrages de mains d''homme, du bois et de la pierre; et ils les ont anéantis.'),
('2r',19,19,'crampon1923','Maintenant Yahweh, notre Dieu, sauvez-nous de la main de Sennachérib, et que tous les royaumes de la terre sachent que vous seul, Yahweh, êtes Dieu. »'),
('2r',19,20,'crampon1923','Et Isaïe, fils d''Amos, envoya dire à Ezéchias: « Ainsi dit Yahweh, Dieu d''Israël: La prière que tu m''as adressée au sujet de Sennachérib, roi d''Assyrie, je l''ai entendue.'),
('2r',19,21,'crampon1923','Voici la parole que Yahweh a prononcée contre lui: Elle te méprise, elle se moque de toi, la vierge, fille de Sion; elle branle la tête derrière toi, la fille de Jérusalem.'),
('2r',19,22,'crampon1923','Qui as-tu insulté et outragé? Contre qui as-tu élevé la voix, et porté les yeux en haut? Contre le Saint d''Israël!...'),
('2r',19,23,'crampon1923','Par tes messagers tu as insulté le Seigneur, et tu as dit: Avec la multitude de mes chars, j''ai gravi le sommet des montagnes, les extrémités du Liban; Je couperai les plus élevés de ses cèdres, les plus beaux de ses cyprès; et j''atteindrai sa dernière cime, sa forêt semblable à un verger.'),
('2r',19,24,'crampon1923','J''ai creusé et j''ai bu des eaux étrangères; avec la plante de mes pieds je dessécherai tous les fleuves de l''Egypte.'),
('2r',19,25,'crampon1923','N''as-tu pas appris que depuis longtemps j''ai fait ces choses, que je les ai formées dès les temps anciens? A présent je les fais s''accomplir, pour que tu réduises en monceaux de ruines les villes fortes.'),
('2r',19,26,'crampon1923','Leurs habitants sont sans force, dans l''épouvante et le trouble; ils sont comme l''herbe des champs et la tendre verdure, comme le gazon des toits, comme le blé niellé qui sèche avant sa maturité.'),
('2r',19,27,'crampon1923','Mais je sais quand tu t''assieds, quand tu sors et quand tu entres, je connais ta fureur contre moi.'),
('2r',19,28,'crampon1923','Parce que tu es furieux contre moi, et que ton arrogance est montée à mes oreilles, je mettrai mon anneau dans ta narine et mon mors à tes lèvres, et je te ferai retourner par le chemin par lequel tu es venu.'),
('2r',19,29,'crampon1923','Et ceci sera un signe pour toi: On mangera cette année le produit du grain tombé; la seconde année, on mangera ce qui croît de soi-même; mais la troisième année, vous sèmerez et vous moissonnerez, vous planterez des vignes et vous en mangerez le fruit.'),
('2r',19,30,'crampon1923','Ce qui aura été sauvé de la maison de Juda, ce qui restera, poussera encore des racines par-dessous, et portera du fruit par-dessus.'),
('2r',19,31,'crampon1923','Car de Jérusalem il sortira un reste, et de la montagne de Sion des réchappés. Voilà ce que fera le zèle de Yahweh des armées.'),
('2r',19,32,'crampon1923','C''est pourquoi ainsi parle Yahweh sur le roi d''Assyrie: Il n''entrera point dans cette ville, il n''y lancera point de flèches, il ne lui présentera point de boucliers, il n''élèvera point de retranchements contre elle.'),
('2r',19,33,'crampon1923','Il s''en retournera par le chemin par lequel il est venu, et il n''entrera point dans cette ville, — oracle de Yahweh.'),
('2r',19,34,'crampon1923','Je protégerai cette ville pour la sauver, à cause de moi et à cause de David, mon serviteur. »'),
('2r',19,35,'crampon1923','Cette nuit-là, l''ange de Yahweh sortit et frappa, dans le camp des Assyriens, cent quatre-vingt-cinq mille hommes; et quand on se leva le matin, voici que c''étaient tous des cadavres.'),
('2r',19,36,'crampon1923','Et Sennachérib, roi d''Assyrie, ayant levé son camp, partit et s''en retourna, et il resta à Ninive.'),
('2r',19,37,'crampon1923','Comme il était prosterné dans la maison de Nesroch, son dieu, Adramélech et Sarasar, ses fils, le frappèrent avec l''épée, et s''enfuirent au pays d''Ararat. Et Assarhaddon, son fils, régna à sa place.'),
('2r',20,1,'crampon1923','En ce temps-là, Ezéchias fut malade à la mort. Le prophète Isaïe, fils d''Amos, vint auprès du lui et lui dit: « Ainsi dit Yahweh: Donne tes ordres à ta maison, car tu vas mourir, et tu ne vivras plus. »'),
('2r',20,2,'crampon1923','Ezéchias tourna son visage contre le mur, et pria Yahweh en ces termes:'),
('2r',20,3,'crampon1923','« Souvenez-vous, ô Yahweh, que j''ai marché devant votre face avec fidélité et intégrité de cœur, et que j''ai fait ce qui est bien à vos yeux. » Et Ezéchias versa des larmes abondantes.'),
('2r',20,4,'crampon1923','Isaïe, n''était pas sorti jusqu''à la cour du milieu, lorsque la parole de Yahweh lui fut adressée en ces termes:'),
('2r',20,5,'crampon1923','Retourne, et dis à Ezéchias, chef de mon peuple: « Ainsi dit Yahweh, le Dieu de David, ton père: J''ai entendu ta prière et j''ai vu tes larmes; voici que je te guéris; dans trois jours, tu monteras à la maison de Yahweh;'),
('2r',20,6,'crampon1923','j''ajouterai à tes jours quinze années. Je te délivrerai, toi et cette ville, de la main du roi d''Assyrie; je protégerai cette ville à cause de moi et à cause de David mon serviteur. »'),
('2r',20,7,'crampon1923','Isaïe dit: « Prenez une masse de figues. » On la prit, on l''appliqua sur l''ulcère, et Ezéchias guérit.'),
('2r',20,8,'crampon1923','Ezéchias avait dit à Isaïe: « A quel signe connaîtrai-je que Yahweh me guérira et que je monterai dans trois jours à la maison de Yahweh. »'),
('2r',20,9,'crampon1923','Isaïe dit: « Voici pour toi le signe donné par Yahweh, auquel tu connaîtras que Yahweh accomplira la parole qu''il a dite: l''ombre avancera-t-elle de dix degrés, ou reculera-t-elle de dix degrés? »'),
('2r',20,10,'crampon1923','Ezéchias répondit: « C''est peu de chose que l''ombre avance de dix degrés; mais qu''elle recule en arrière de dix degrés! »'),
('2r',20,11,'crampon1923','Alors Isaïe, le prophète invoqua Yahweh, qui fit reculer l''ombre en arrière de dix degrés sur les degrés d''Achaz, sur les degrés où elle était descendue.'),
('2r',20,12,'crampon1923','En ce même temps, Mérodach-Baladan, fils de Baladan, roi de Babylone, envoya une lettre et des présents à Ezéchias, parce qu''il avait appris qu''Ezéchias était malade.'),
('2r',20,13,'crampon1923','Ezéchias se réjouit de la venue des envoyés, et il leur montra toute la maison de son trésor, l''argent et l''or, les aromates et l''huile de prix, tout son arsenal et tout ce qui se trouvait dans ses trésors; il n''y eut rien qu''Ezéchias ne leur fit voir dans sa maison et dans tous ses domaines.'),
('2r',20,14,'crampon1923','Mais Isaïe, le prophète, vint auprès du roi Ezéchias, et lui dit: « Qu''ont dit ces gens-là, et d''où sont-ils venus vers toi? » Ezéchias répondit: « Ils sont venus d''un pays éloigné, de Babylone. »'),
('2r',20,15,'crampon1923','Et Isaïe dit: « Qu''ont-ils vu dans ta maison? » Et Ezéchias répondit: « Ils ont vu tout ce qui est dans ma maison; il n''y a rien dans mes trésors que je ne leur aie fait voir. »'),
('2r',20,16,'crampon1923','Et Isaïe dit à Ezéchias: « Ecoute la parole de Yahweh:'),
('2r',20,17,'crampon1923','Voici que des jours viendront où l''on emportera à Babylone tout ce qui est dans ta maison et ce que tes pères ont amassé jusqu''à ce jour; il n''en restera rien, dit Yahweh.'),
('2r',20,18,'crampon1923','Et l''on prendra de tes fils, qui seront sortis de toi, que tu auras engendrés, pour en faire des eunuques dans le palais du roi de Babylone. »'),
('2r',20,19,'crampon1923','Ezéchias répondit à Isaïe: « La parole de Yahweh que tu as prononcée est bonne. » Et il ajouta: « Oui, car la paix et la stabilité seront avec moi pendant ma vie. »'),
('2r',20,20,'crampon1923','Le reste des actes d''Ezéchias, tous ses exploits, et comment il fit l''étang et l''aqueduc et amena les eaux dans la ville, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('2r',20,21,'crampon1923','Ezéchias se coucha avec ses pères, et Manassé, son fils, régna à sa place.'),
('2r',21,1,'crampon1923','Manassé avait douze ans lorsqu''il devint roi, et il régna cinquante-cinq ans à Jérusalem. Sa mère s''appelait Haphsiba.'),
('2r',21,2,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, imitant les abominations des nations que Yahweh avait chassées devant les enfants d''Israël.'),
('2r',21,3,'crampon1923','Il rebâtit les hauts lieux qu''Ezéchias, son père avait détruits; il éleva des autels à Baal, il fit une aschérah, comme avait fait Achab, roi d''Israël, et il se prosterna devant toute l''armée du ciel et la servit.'),
('2r',21,4,'crampon1923','Il bâtit des autels dans la maison de Yahweh, de laquelle Yahweh avait dit: « C''est dans Jérusalem que je placerai mon nom. »'),
('2r',21,5,'crampon1923','Il bâtit des autels à toute l''armée du ciel dans les deux parvis de la maison de Yahweh.'),
('2r',21,6,'crampon1923','Il fit passer son fils par le feu; il pratiquait les augures et la divination; il institua des nécromanciens et des sorciers: faisant ainsi de plus en plus ce qui est mal aux yeux de Yahweh, de manière à l''irriter.'),
('2r',21,7,'crampon1923','Il mit l''idole d''Astarté, qu''il avait faite, dans la maison dont Yahweh avait dit à David et à Salomon, son fils: « C''est dans cette maison et c''est dans Jérusalem, que j''ai choisie parmi toutes les tribus d''Israël, que je veux placer mon nom pour toujours.'),
('2r',21,8,'crampon1923','Je ne ferai plus errer le pied d''Israël hors du pays que j''ai donné à ses pères, pourvu seulement qu''ils aient soin de mettre en pratique tout ce que je leur ai commandé et toute la loi que leur a prescrite mon serviteur Moïse. »'),
('2r',21,9,'crampon1923','Mais ils n''obéirent point; et Manassé les égara, au point qu''ils firent le mal plus que toutes les nations que Yahweh avait détruites devant les enfants d''Israël.'),
('2r',21,10,'crampon1923','Alors Yahweh parla par l''organe de ses serviteurs les prophètes, en ces termes:'),
('2r',21,11,'crampon1923','« Parce que Manassé, roi de Juda, a commis ces abominations, parce qu''il a fait pire que tout ce qu''avaient fait avant lui les Amorrhéens, et parce qu''il a fait aussi pécher Juda par ses idoles,'),
('2r',21,12,'crampon1923','voici ce que dit Yahweh, Dieu d''Israël: Voici que je vais faire venir sur Jérusalem et sur Juda des malheurs tels que les deux oreilles tinteront à qui en entendra parler.'),
('2r',21,13,'crampon1923','J''étendrai sur Jérusalem le cordeau de Samarie et le niveau de la maison d''Achab, et je nettoierai Jérusalem comme le plat qu''on nettoie et qu''on retourne sur sa face après l''avoir nettoyé.'),
('2r',21,14,'crampon1923','J''abandonnerai le reste de mon héritage, et je les livrerai entre les mains de leurs ennemis, et ils deviendront la proie et le butin de tous leurs ennemis:'),
('2r',21,15,'crampon1923','parce qu''ils ont fait ce qui est mal à mes yeux, et qu''ils m''ont irrité depuis le jour où leurs pères sont sortis d''Egypte jusqu''à présent. »'),
('2r',21,16,'crampon1923','Manassé répandit aussi beaucoup de sang innocent, jusqu''à en remplir Jérusalem d''un bout à l''autre, outre ses péchés par lesquels il fit pécher Juda, l''entraînant à faire ce qui est mal aux yeux de Yahweh.'),
('2r',21,17,'crampon1923','Le reste des actes de Manassé, tout ce qu''il a fait, et les péchés qu''il a commis, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('2r',21,18,'crampon1923','Manassé se coucha avec ses pères, et il fut enterré dans le jardin de sa maison, dans le jardin d''Oza. Amon, son fils, régna à sa place.'),
('2r',21,19,'crampon1923','Amon avait vingt-deux ans lorsqu''il devint roi, et il régna deux ans à Jérusalem. Sa mère s''appelait Messalemeth, fille de Harus, de Jétéba.'),
('2r',21,20,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, comme avait fait Manassé, son père;'),
('2r',21,21,'crampon1923','il marcha dans toute la voie où avait marché son père, il servit les idoles que son père avait servies, et il se prosterna devant elles;'),
('2r',21,22,'crampon1923','il abandonna Yahweh, le Dieu de ses pères, et il ne marcha pas dans la voie de Yahweh.'),
('2r',21,23,'crampon1923','Les serviteurs d''Amon conspirèrent contre lui et tuèrent le roi dans sa maison.'),
('2r',21,24,'crampon1923','Mais le peuple du pays frappa tous ceux qui avaient conspiré contre le roi Amon; et le peuple du pays établit roi Josias, son fils, à sa place.'),
('2r',21,25,'crampon1923','Le reste des actes d''Amon, et ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('2r',21,26,'crampon1923','On l''enterra dans son sépulcre, dans le jardin d''Oza; Josias, son fils, régna à sa place.'),
('2r',22,1,'crampon1923','Josias avait huit ans lorsqu''il devint roi, et il régna trente et un ans à Jérusalem. Sa mère s''appelait Idida, fille d''Hadaï, de Bésécath.'),
('2r',22,2,'crampon1923','Il fit ce qui est droit aux yeux de Yahweh, et il marcha entièrement dans la voie de David, son père, et il ne s''en détourna ni à droite ni à gauche.'),
('2r',22,3,'crampon1923','La dix-huitième année du roi Josias, le roi envoya dans la maison de Yahweh Saphan, le secrétaire, fils d''Aslia, fils de Messulam, en disant:'),
('2r',22,4,'crampon1923','« Monte vers Helcias, le grand prêtre, et qu''il tienne prêt l''argent qui a été apporté dans la maison de Yahweh, et que les gardiens de la porte ont recueilli du peuple.'),
('2r',22,5,'crampon1923','On remettra cet argent entre les mains de ceux qui font exécuter l''ouvrage, qui sont établis surveillants dans la maison de Yahweh, et ils le donneront à ceux qui travaillent à l''œuvre de la maison de Yahweh, pour réparer les brèches de la maison,'),
('2r',22,6,'crampon1923','aux charpentiers, aux manœuvres et aux maçons, et ils l''emploieront à acheter le bois et les pierres de taille pour réparer la maison.'),
('2r',22,7,'crampon1923','Mais on ne leur demandera pas de comptes pour l''argent remis entre leur mains, car ils se conduisent avec probité. »'),
('2r',22,8,'crampon1923','Alors Helcias, le grand prêtre, dit à Saphan, le secrétaire: « J''ai trouvé le livre de la Loi dans la maison de Yahweh. » Et Helcias donna le livre à Saphan, qui le lut.'),
('2r',22,9,'crampon1923','Puis Saphan, le secrétaire, revint vers le roi et rendit compte au roi en disant: « Tes serviteurs ont vidé l''argent qui se trouvait dans la maison, et l''ont remis entre les mains de ceux qui font exécuter l''ouvrage, qui sont établis surveillants dans la maison de Yahweh. »'),
('2r',22,10,'crampon1923','Saphan, le secrétaire, fit encore au roi cette communication: « Le prêtre Helcias m''a donné un livre. » Et Saphan le lut devant le roi.'),
('2r',22,11,'crampon1923','Lorsque le roi eut entendu les paroles du livre de la Loi, il déchira ses vêtements;'),
('2r',22,12,'crampon1923','et il donna cet ordre au prêtre Helcias, à Ahicam, fils de Saphan, à Achobor, fils de Micha, à Saphan, le secrétaire, et à Asaïas, serviteur du roi:'),
('2r',22,13,'crampon1923','« Allez consulter Yahweh pour moi, pour le peuple et pour tout Juda au sujet des paroles de ce livre qu''on a trouvé; car grande est la colère de Yahweh qui s''est enflammée contre nous, parce que nos pères n''ont pas obéi aux paroles de ce livre, en faisant tout ce qui nous est prescrit. »'),
('2r',22,14,'crampon1923','Le prêtre Helcias, Ahicam, Achobor, Saphan et Asaïas se rendirent auprès de la prophétesse Holda, femme de Sellum, fils de Thécua, fils d''Araas, gardien des vêtements; elle habitait à Jérusalem, dans le second quartier. Lorsqu''ils lui eurent parlé,'),
('2r',22,15,'crampon1923','elle leur dit: « Ainsi dit Yahweh, Dieu d''Israël: Dites à l''homme qui vous a envoyés vers moi:'),
('2r',22,16,'crampon1923','Ainsi dit Yahweh: Voici que je vais faire venir des malheurs sur ce lieu et sur ses habitants, selon toutes les paroles du livre qu''a lu le roi de Juda.'),
('2r',22,17,'crampon1923','Parce qu''ils m''ont abandonné et qu''ils ont offerts des parfums à d''autres dieux, de manière à m''irriter par tous les ouvrages de leurs mains, ma colère s''est enflammée contre ce lieu, et elle ne s''éteindra point.'),
('2r',22,18,'crampon1923','Et vous direz au roi de Juda, qui vous a envoyés pour consulter Yahweh: Ainsi dit Yahweh, Dieu d''Israël: Quant aux paroles que tu as entendues,'),
('2r',22,19,'crampon1923','parce que ton cœur s''est repenti et que tu t''es humilié devant Yahweh en entendant ce que j''ai prononcé contre ce lieu et contre ses habitants, savoir qu''ils seront un objet d''épouvante et de malédiction, et parce que tu as déchiré tes vêtements et pleuré devant moi, moi aussi je t''ai entendu, oracle de Yahweh.'),
('2r',22,20,'crampon1923','C''est pourquoi, voici que je te recueillerai auprès de tes pères; tu seras recueilli en paix dans ton sépulcre, et tes yeux ne verront pas tous les malheurs que je ferai venir sur ce lieu. » Ils rapportèrent au roi cette réponse.'),
('2r',23,1,'crampon1923','Le roi envoya rassembler auprès de lui tous les anciens de Juda et de Jérusalem.'),
('2r',23,2,'crampon1923','Et le roi monta à la maison de Yahweh, avec tous les hommes de Juda et tous les habitants de Jérusalem, les prêtres, les prophètes et tout le peuple, depuis le plus petit jusqu''au plus grand, et il lut devant eux toutes les paroles du livre de l''alliance, qu''on avait trouvé dans la maison de Yahweh.'),
('2r',23,3,'crampon1923','Le roi se tenant sur l''estrade, conclut l''alliance devant Yahweh, s''engageant à suivre Yahweh et à observer ses préceptes, ses ordonnances et ses lois, de tout son cœur et de toute son âme, en accomplissant les paroles de cette alliance, qui sont écrites dans ce livre. Et tout le peuple acquiesça à cette alliance.'),
('2r',23,4,'crampon1923','Le roi ordonna à Helcias, le grand prêtre, aux prêtres du second ordre et à ceux qui gardaient la porte, de rejeter du temple de Yahweh tous les ustensiles qui avaient été faits pour Baal, pour Astarté et pour toute l''armée du ciel; et il les brûla hors de Jérusalem dans les champs du Cédron, et en fit porter la poussière à Béthel.'),
('2r',23,5,'crampon1923','Il chassa les prêtres des idoles, établis par les rois de Juda, pour brûler des parfums sur les hauts lieux, dans les villes de Juda et aux environs de Jérusalem, et ceux qui offraient des parfums à Baal, au soleil, à la lune, aux douze signes et à toute l''armée du ciel.'),
('2r',23,6,'crampon1923','Il rejeta de la maison de Yahweh l''aschérah qu''il transporta hors de Jérusalem, vers la vallée du Cédron; il la brûla dans la vallée du Cédron et, l''ayant réduite en poussière, il jeta cette poussière sur les sépulcres des enfants du peuple.'),
('2r',23,7,'crampon1923','Il abattit les maisons des prostitués qui étaient dans la maison de Yahweh, et où les femmes tissaient des tentes pour Astarté.'),
('2r',23,8,'crampon1923','Il fit venir tous les prêtres des villes de Juda: il souilla les hauts lieux où les prêtres avaient brûlé des parfums, depuis Gabaa jusqu''à Bersabée, et il renversa les hauts lieux des portes, celui qui était à l''entrée de la porte de Josué, chef de la ville, et celui qui était à gauche de la porte de la ville.'),
('2r',23,9,'crampon1923','Toutefois les prêtres des hauts lieux ne montaient pas à l''autel de Yahweh à Jérusalem, mais ils mangeaient des pains sans levain au milieu de leurs frères.'),
('2r',23,10,'crampon1923','Le roi souilla Topheth, dans la vallée des fils d''Ennom, afin que personne ne fit passer par le feu son fils ou sa fille en l''honneur de Moloch.'),
('2r',23,11,'crampon1923','Il fit disparaître les chevaux que les rois de Juda avaient dédiés au soleil à l''entrée de la maison de Yahweh, près de la chambre de l''eunuque Nathan-Mélech, laquelle était dans les dépendances, et il brûla au feu les chars du soleil.'),
('2r',23,12,'crampon1923','Le roi détruisit les autels qui étaient sur le toit de la chambre haute d''Achaz et que les rois de Juda avaient faits, et les autels qu''avait faits Manassé dans les deux parvis de la maison de Yahweh, et de là il courut en jeter la poussière dans la vallée du Cédron.'),
('2r',23,13,'crampon1923','Le roi souilla les hauts lieux qui étaient en face de Jérusalem, sur la droite de la Montagne de Perdition, et que Salomon, roi d''Israël, avait bâtis à Astarté, l''abomination des Sidoniens, à Chamos, l''abomination des fils d''Ammon;'),
('2r',23,14,'crampon1923','il brisa les stèles et coupa les aschérahs, et il remplit d''ossements humains la place qu''elles occupaient.'),
('2r',23,15,'crampon1923','De même l''autel qui était à Béthel, et le haut lieu qu''avait fait Jéroboam, fils de Nabat, qui avait fait pécher Israël, il détruisit cet autel et le haut lieu; il brûla le haut lieu et le réduisit en poussière, et il brûla l''aschérah.'),
('2r',23,16,'crampon1923','Josias, s''étant tourné et ayant vu les sépulcres qui étaient là dans la montagne, envoya prendre les ossements des sépulcres, et il les brûla sur l''autel et le souilla, selon la parole de Yahweh prononcée par l''homme de Dieu qui avait annoncé ces choses.'),
('2r',23,17,'crampon1923','Il dit alors: « Quel est ce monument que je vois? » Les gens de la ville lui dirent: « C''est le sépulcre de l''homme de Dieu, qui est venu de Juda et qui a annoncé ces choses que tu as faites contre l''autel de Béthel. »'),
('2r',23,18,'crampon1923','Et il dit: « Laisses-le; que personne ne remue ses os! » C''est ainsi qu''on laissa ses os intacts avec les os du prophète qui était venu de Samarie.'),
('2r',23,19,'crampon1923','Josias fit encore disparaître toutes les maisons des hauts lieux, qui étaient dans les villes de Samarie et qu''avaient faites les rois d''Israël, en irritant Yahweh; il fit à leur égard entièrement comme il avait fait à Béthel.'),
('2r',23,20,'crampon1923','Il immola sur les autels tous les prêtres des hauts lieux qui étaient là, et il y brûla des ossements humains; puis il revint à Jérusalem.'),
('2r',23,21,'crampon1923','Le roi donna cet ordre à tout le peuple: « Célébrez la Pâque en l''honneur de Yahweh, votre Dieu, comme il est écrit dans le livre de l''alliance. »'),
('2r',23,22,'crampon1923','Aucune Pâque pareille à celle-ci n''avait été célébrée depuis le temps des juges qui jugèrent Israël, et pendant tous les jours des rois d''Israël et des rois de Juda.'),
('2r',23,23,'crampon1923','Ce fut la dix-huitième année du roi Josias qu''on célébra cette Pâque en l''honneur de Yahweh à Jérusalem.'),
('2r',23,24,'crampon1923','Josias fit encore disparaître les nécromanciens et les sorciers, ainsi que les théraphim, les idoles et toutes les abominations qui se voyaient dans le pays de Juda et à Jérusalem, afin d''accomplir les paroles de la Loi, écrites dans le livre que le prêtre Helcias avait trouvé dans la maison de Yahweh.'),
('2r',23,25,'crampon1923','Il n''y eut pas, avant Josias, de roi qui, comme lui, se tourna vers Yahweh de tout son cœur, de toute son âme et de toute sa force, selon toute la loi de Moïse; et après lui, il n''en a point paru de semblable.'),
('2r',23,26,'crampon1923','Toutefois Yahweh ne revint pas de l''ardeur de sa grande colère, parce sa colère était enflammée contre Juda, à cause des provocations par lesquelles Manassé l''avait irrité.'),
('2r',23,27,'crampon1923','Et Yahweh dit: « J''ôterai aussi Juda de devant ma face, comme j''ai ôté Israël; et je rejetterai cette ville de Jérusalem que j''avais choisie, et cette maison de laquelle j''avais dit: Là sera mon nom. »'),
('2r',23,28,'crampon1923','Le reste des actes de Josias, et tout ce qu''il a fait, cela n''est-t-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('2r',23,29,'crampon1923','De son temps, Pharaon-Néchao, roi d''Egypte, monta contre le roi d''Assyrie, vers le fleuve de l''Euphrate. Le roi Josias marcha à sa rencontre, et Pharaon le tua à Mageddo, dès qu''il le vit.'),
('2r',23,30,'crampon1923','Ses serviteurs le transportèrent mort de Mageddo sur un char et, l''ayant amené à Jérusalem, ils l''enterrèrent dans son sépulcre. Et le peuple du pays prit Joachaz fils de Josias; ils l''oignirent et le firent roi à la place de son père.'),
('2r',23,31,'crampon1923','Joachaz avait vingt-trois ans lorsqu''il devint roi, et il régna trois mois à Jérusalem. Sa mère s''appelait Amital, fille de Jérémie, de Lobna.'),
('2r',23,32,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, selon tout ce qu''avaient fait ses pères.'),
('2r',23,33,'crampon1923','Pharaon-Néchao l''enchaîna à Rébla, dans le pays d''Emath, pour qu''il ne régnât plus à Jérusalem, et il mit sur le pays une imposition de cent talents d''argent et d''un talent d''or.'),
('2r',23,34,'crampon1923','Pharaon-Néchao établit roi Éliacim, fils de Josias, à la place de Josias son père, et il changea son nom en celui de Joakim. Joachaz, dont il s''était emparé, alla en Egypte et y mourut.'),
('2r',23,35,'crampon1923','Joakim donna à Pharaon l''argent et l''or, mais il taxa le pays pour fournir la somme exigée par Pharaon: chacun selon ce qui lui était fixé, leva sur le peuple du pays l''argent et l''or, pour le donner à Pharaon-Néchao.'),
('2r',23,36,'crampon1923','Joakim avait vingt-cinq ans lorsqu''il devint roi, et il régna onze ans à Jérusalem. Sa mère s''appelait Zébida, fille de Phadaïas, de Ruma.'),
('2r',23,37,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, selon tout ce qu''avaient fait ses pères.'),
('2r',24,1,'crampon1923','De son temps, Nabuchodonosor, roi de Babylone, se mit en campagne, et Joakim lui fut assujetti pendant trois ans; mais il se révolta de nouveau contre lui.'),
('2r',24,2,'crampon1923','Yahweh envoya contre Joakim des bandes de Chaldéens, des bandes de Syriens, des bandes de Moabites et des bandes d''Ammonites; il les envoya contre Juda pour le détruire, selon la parole de Yahweh qu''il avait prononcée par l''organe de ses serviteurs les prophètes.'),
('2r',24,3,'crampon1923','Ce fut uniquement sur l''ordre de Yahweh que cela arriva contre Juda, pour l''ôter de devant sa face, à cause de tous les péchés commis par Manassé,'),
('2r',24,4,'crampon1923','et à cause du sang innocent qu''avait répandu Manassé, au point de remplir Jérusalem de sang innocent. C''est pourquoi Yahweh ne voulait point pardonner.'),
('2r',24,5,'crampon1923','Le reste des actes de Joakim, et tout ce qu''il a fait, cela n''est-il pas écrit dans le livre des Chroniques des rois de Juda?'),
('2r',24,6,'crampon1923','Joakim se coucha avec ses pères, et Joachin son fils, régna à sa place.'),
('2r',24,7,'crampon1923','Le roi d''Egypte ne sortit plus de son pays; car le roi de Babylone avait pris tout ce qui était au roi d''Egypte, depuis le torrent d''Egypte jusqu''au fleuve de l''Euphrate.'),
('2r',24,8,'crampon1923','Joachin avait dix-huit ans lorsqu''il devint roi, et il régna trois mois à Jérusalem. Sa mère s''appelait Nohesta, fille d''Elnathan, de Jérusalem.'),
('2r',24,9,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, selon tout ce qu''avait fait son père.'),
('2r',24,10,'crampon1923','En ce temps-là, les serviteurs de Nabuchodonosor, roi de Babylone, montèrent contre Jérusalem, et la ville fut assiégée.'),
('2r',24,11,'crampon1923','Nabuchodonosor, roi de Babylone, vint devant la ville pendant que ses serviteurs l''assiégeaient.'),
('2r',24,12,'crampon1923','Alors Joachin, roi de Juda, sortit auprès du roi de Babylone, avec sa mère, ses serviteurs, ses chefs et ses eunuques, et le roi de Babylone le fit prisonnier la huitième année de son règne.'),
('2r',24,13,'crampon1923','Il emporta de là tous les trésors de la maison de Yahweh et les trésors de la maison du roi, et il brisa tous les ustensiles d''or que Salomon, roi d''Israël, avait faits dans le temple de Yahweh, comme Yahweh l''avait annoncé.'),
('2r',24,14,'crampon1923','Il emmena en captivité tout Jérusalem, tous les chefs et tous les hommes vaillants, — dix mille captifs, — avec tous les artisans et les forgerons; il ne resta que le peuple pauvre du pays.'),
('2r',24,15,'crampon1923','Il transporta Joachin à Babylone, et il emmena captifs de Jérusalem à Babylone la mère du roi, les femmes du roi et ses eunuques, et les grands du pays.'),
('2r',24,16,'crampon1923','De plus, tous les guerriers au nombre de sept mille, ainsi que les artisans et les forgerons au nombre de mille, tous hommes vaillants et propres à la guerre: le roi de Babylone les emmena captifs à Babylone.'),
('2r',24,17,'crampon1923','Et le roi de Babylone établit roi, à la place de Joachin, Mathanias, son oncle, dont il changea le nom en celui de Sédécias.'),
('2r',24,18,'crampon1923','Sédécias avait vingt et un ans lorsqu''il devint roi, et il régna onze ans à Jérusalem. Sa mère s''appelait Amital, fille de Jérémie, de Lobna.'),
('2r',24,19,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, imitant tout ce qu''avait fait Joakim.'),
('2r',24,20,'crampon1923','Cela arriva à Jérusalem et en Juda, à cause de la colère de Yahweh, jusqu''à ce qu''il les rejette de devant sa face. Et Sédécias se révolta contre le roi de Babylone.'),
('2r',25,1,'crampon1923','La neuvième année du règne de Sédécias, le dixième mois, le dixième jour du mois, Nabuchodonosor, roi de Babylone, vint avec toute son armée contre Jérusalem, et établit son camp devant elle; on construisit tout autour des murs d''approche.'),
('2r',25,2,'crampon1923','La ville fut assiégée jusqu''à la onzième année de Sédécias.'),
('2r',25,3,'crampon1923','Le neuvième jour du mois, comme la famine était plus grande dans la ville, et qu''il n''y avait plus de pain pour le peuple du pays,'),
('2r',25,4,'crampon1923','une brèche fut faite à la ville, et tous les gens de guerre s''enfuirent la nuit par le chemin de la porte entre les deux murs, près du jardin du roi, pendant que les Chaldéens environnaient la ville. Le roi prit le chemin de l''Araba.'),
('2r',25,5,'crampon1923','Mais l''armée des Chaldéens poursuivit le roi et l''atteignit dans les plaines de Jéricho, et toute son armée se dispersa loin de lui.'),
('2r',25,6,'crampon1923','Ayant saisi le roi, ils le firent monter vers le roi de Babylone à Rébla, et on prononça sur lui une sentence.'),
('2r',25,7,'crampon1923','On égorgea les fils de Sédécias sous ses yeux. Puis Nabuchodonosor creva les yeux à Sédécias et le lia avec deux chaînes d''airain; et on le mena à Babylone.'),
('2r',25,8,'crampon1923','Le cinquième mois, le septième jour du mois, — c''était la dix-neuvième année du règne de Nabuchodonosor, roi de Babylone, — Nabuzardan, capitaine des gardes, serviteur du roi de Babylone, vint à Jérusalem.'),
('2r',25,9,'crampon1923','Il brûla la maison de Yahweh, la maison du roi et toutes les maisons de Jérusalem; il livra au feu toutes les grandes maisons.'),
('2r',25,10,'crampon1923','Toute l''armée des Chaldéens qui était avec le capitaine des gardes démolit les murailles formant l''enceinte de Jérusalem.'),
('2r',25,11,'crampon1923','Nabuzardan, capitaine des gardes, emmena captifs le reste du peuple qui était demeuré dans la ville, les transfuges qui s''étaient rendus au roi de Babylone et le reste de la multitude.'),
('2r',25,12,'crampon1923','Le capitaine des gardes laissa comme vignerons et comme laboureurs quelques-uns des pauvres du pays.'),
('2r',25,13,'crampon1923','Les Chaldéens brisèrent les colonnes d''airain qui étaient dans la maison de Yahweh, ainsi que les bases et la mer d''airain qui étaient dans la maison de Yahweh, et ils en emportèrent l''airain à Babylone.'),
('2r',25,14,'crampon1923','Ils prirent les pots, les pelles, les couteaux, les coupes et tous les ustensiles d''airain avec lesquels on faisait le service.'),
('2r',25,15,'crampon1923','Le capitaine des gardes, prit encore les encensoirs et les tasses, ce qui était d''or et ce qui était d''argent.'),
('2r',25,16,'crampon1923','Quant aux deux colonnes, à la mer et aux bases que Salomon avait faites dans la maison de Yahweh, il n''y avait pas à peser l''airain de tous ces ustensiles.'),
('2r',25,17,'crampon1923','La hauteur d''une colonne était de dix-huit coudées; et il y avait au-dessus un chapiteau d''airain, et la hauteur du chapiteau était de trois coudées; et il y avait tout autour du chapiteau un treillis et des grenades, le tout d''airain; il en était de même de la seconde colonne avec le treillis.'),
('2r',25,18,'crampon1923','Le capitaine des gardes prit Saraïas, le grand-prêtre, Sophonie, prêtre de second ordre, et les trois gardiens de la porte.'),
('2r',25,19,'crampon1923','Dans la ville, il prit un officier qui commandait aux gens de guerre, cinq hommes faisant partie du conseil privé du roi et qui furent trouvés dans la ville, le secrétaire du chef de l''armée chargé d''enrôler le peuple du pays, et soixante hommes du peuple du pays qui se trouvaient dans la ville.'),
('2r',25,20,'crampon1923','Les ayant pris, Nabuzardan, capitaine des gardes, les conduisit vers le roi de Babylone à Rébla.'),
('2r',25,21,'crampon1923','Et le roi de Babylone les frappa et les fit mourir à Rébla, dans le pays d''Emath. Ainsi Juda fut emmené captif loin de son pays.'),
('2r',25,22,'crampon1923','Quant au peuple demeuré au pays de Juda qu''y laissa Nabuchodonosor, roi de Babylone, il lui donna pour gouverneur Godolias, fils d''Ahicam, fils de Saphan.'),
('2r',25,23,'crampon1923','Lorsque tous les chefs des troupes eurent appris, eux et leurs hommes, que le roi de Babylone avait établi Godolias pour gouverneur, ils vinrent vers Godolias à Maspha, savoir, Ismaël, fils de Nathanias, Johanan, fils de Carée, Saraïas, fils de Thanéhumeth, de Nétopha, et Jézonias, fils du Maachathien, eux et leurs hommes.'),
('2r',25,24,'crampon1923','Godolias leur dit avec serment, à eux et à leurs hommes: « Ne craignez rien de la part des serviteurs des Chaldéens; demeurez dans le pays, servez le roi de Babylone, et vous vous en trouverez bien. »'),
('2r',25,25,'crampon1923','Mais, le septième mois, Ismaël, fils de Nathanias, fils d''Elisama, de la race royale, vint accompagné de dix hommes, et ils frappèrent à mort Godolias, ainsi que les Juifs et les Chaldéens qui étaient avec lui à Maspha.'),
('2r',25,26,'crampon1923','Alors tout le peuple, depuis le plus petit jusqu''au plus grand, et les chefs des troupes, se levèrent et s''en allèrent en Egypte, parce qu''ils avaient peur des Chaldéens.'),
('2r',25,27,'crampon1923','La trente-septième année de la captivité de Joachin, roi de Juda, le douzième mois, le vingt-septième jour du mois, Evil-Mérodach, roi de Babylone, en l''année de son avènement, releva la tête de Joachin, roi de Juda, et le tira de prison.'),
('2r',25,28,'crampon1923','Il lui parla avec bonté, et il mit son trône au-dessus du trône des rois qui étaient avec lui à Babylone.'),
('2r',25,29,'crampon1923','Il lui fit changer ses vêtements de prison, et Joachin mangea toujours en sa présence, tout le temps de sa vie.'),
('2r',25,30,'crampon1923','Quant à son entretien, son entretien perpétuel, le roi y pourvut chaque jour, tout le temps de sa vie.'),
('1ch',1,1,'crampon1923','Adam, Seth, Enos,'),
('1ch',1,2,'crampon1923','Caïnan, Malaléel, Jared,'),
('1ch',1,3,'crampon1923','Hénoch, Mathusalé, Lamech,'),
('1ch',1,4,'crampon1923','Noé, Sem, Cham et Japheth.'),
('1ch',1,5,'crampon1923','Fils de Japheth: Gomer, Magog, Madaï, Javan, Thubal, Mosoch et Thiras. —'),
('1ch',1,6,'crampon1923','Fils de Gomer: Ascénez, Riphath et Thogorma. —'),
('1ch',1,7,'crampon1923','Fils de Javan: Élisa, Tharsis, Céthim et Dodanim.'),
('1ch',1,8,'crampon1923','Fils de Cham: Chus, Mesraïm, Phut et Chanaan. —'),
('1ch',1,9,'crampon1923','Fils de Chus: Saba, Hévila, Sabatha, Regma et Sabathacha. — Fils de Regma: Saba et Dadan. —'),
('1ch',1,10,'crampon1923','Chus engendra Nemrod; c''est lui qui commença à être puissant sur la terre. —'),
('1ch',1,11,'crampon1923','Mesraïm engendra les Ludim, les Anamim, les Laabim, les Nephthuhim,'),
('1ch',1,12,'crampon1923','les Phétrusim, les Casluhim, d''où sont sortis les Philistins, et les Caphthorim. —'),
('1ch',1,13,'crampon1923','Chanaan engendra Sidon, son premier-né, et Heth,'),
('1ch',1,14,'crampon1923','ainsi que les Jébuséens, les Amorrhéens, les Gergéséens,'),
('1ch',1,15,'crampon1923','les Hévéens, les Aracéens, les Sinéens,'),
('1ch',1,16,'crampon1923','les Aradiens, les Samaréens et les Hamathéens.'),
('1ch',1,17,'crampon1923','Fils de Sem: Elam, Assur, Arphaxad, Lud, Aram; Hus, Hul, Géther et Mosoch. —'),
('1ch',1,18,'crampon1923','Arphaxad engendra Salé, et Salé engendra Héber.'),
('1ch',1,19,'crampon1923','Il naquit à Héber deux fils: le nom de l''un fut Phaleg, parce que de son temps la terre fut partagée, et le nom de son frère fut Jectan. —'),
('1ch',1,20,'crampon1923','Jectan engendra Elmodad, Saleph, Asarmoth, Jaré,'),
('1ch',1,21,'crampon1923','Adoram, Huzal, Décla,'),
('1ch',1,22,'crampon1923','Hébal, Abimaël, Saba,'),
('1ch',1,23,'crampon1923','Ophir, Hévila et Jobab. Tous ceux-là furent fils de Jectan.'),
('1ch',1,24,'crampon1923','Sem, Arphaxad, Salé,'),
('1ch',1,25,'crampon1923','Héber, Phaleg, Ragau,'),
('1ch',1,26,'crampon1923','Serug, Nachor, Tharé,'),
('1ch',1,27,'crampon1923','Abram, qui est Abraham.'),
('1ch',1,28,'crampon1923','Fils d''Abraham: Isaac et Ismaël.'),
('1ch',1,29,'crampon1923','Voici leur postérité: Nabaïoth, premier-né d''Ismaël, puis Cédar, Adbéel, Mabsam,'),
('1ch',1,30,'crampon1923','Masma, Duma, Massa, Hadad, Thema,'),
('1ch',1,31,'crampon1923','Jétur, Naphis, Cedma. Ce sont les fils d''Ismaël.'),
('1ch',1,32,'crampon1923','Fils de Cétura, concubine d''Abraham: elle enfanta Zamram, Jecsan, Madan, Madian, Jesboc et Sué. — Fils de Jecsan: Saba et Dadan. —'),
('1ch',1,33,'crampon1923','Fils de Madian: Epha, Epher, Hénoch, Abida et Eldaa. — Tous ceux-là sont fils de Cétura.'),
('1ch',1,34,'crampon1923','Abraham engendra Isaac. Fils d''Isaac: Esaü et Jacob.'),
('1ch',1,35,'crampon1923','Fils d''Esaü: Eliphaz, Rahuel, Jéhus, Ihélom et Coré. —'),
('1ch',1,36,'crampon1923','Fils d''Eliphaz: Théman, Omar, Séphi, Gathan, Cénez, Thamna, Amalec. —'),
('1ch',1,37,'crampon1923','Fils de Rahuel: Nahath, Zara, Samma et Méza.'),
('1ch',1,38,'crampon1923','Fils de Séir: Lotan, Sobal, Sébéon, Ana, Dison, Eser et Disan. —'),
('1ch',1,39,'crampon1923','Fils de Lotan: Hori et Homam. Sœur de Lotan: Thamna. —'),
('1ch',1,40,'crampon1923','Fils de Sobal: Alian, Manahath, Ebal, Séphi et Onam. — Fils de Sébéon: Aïa et Ana. — Fils d''Ana: Dison. —'),
('1ch',1,41,'crampon1923','Fils de Dison: Hamram, Eséban, Jéthran et Charan. —'),
('1ch',1,42,'crampon1923','Fils d''Eser: Balaan, Zavan et Jacan. — Fils de Disan: Hus et Aran.'),
('1ch',1,43,'crampon1923','Voici les rois qui ont régné dans le pays d''Edom avant qu''un roi régnât sur les enfants d''Israël: Béla, fils de Béor; le nom de sa ville était Dénaba.'),
('1ch',1,44,'crampon1923','Béla mourut, et, à sa place, régna Jobab, fils de Zaré, de Bosra.'),
('1ch',1,45,'crampon1923','Jobab mourut, et à sa place régna Husam, du pays des Thémanites.'),
('1ch',1,46,'crampon1923','Husam mourut, et, à sa place, régna Hadad, fils de Badad, qui défit Madian dans les champs de Moab; le nom de sa ville était Avith.'),
('1ch',1,47,'crampon1923','Hadad mourut, et, à sa place, régna Semla, de Masréca.'),
('1ch',1,48,'crampon1923','Semla mourut, et, à sa place, régna Saül, de Rohoboth sur le Fleuve.'),
('1ch',1,49,'crampon1923','Saül mourut, et à sa place, régna Balanan, fils d''Achobor.'),
('1ch',1,50,'crampon1923','Balanan mourut, et, à sa place, régna Hadad; le nom de sa ville était Phau, et le nom de sa femme, Méétabel, fille de Matred, fille de Mézaab.'),
('1ch',1,51,'crampon1923','Hadad mourut. Les chefs d''Edom étaient: le chef Thamna, le chef Alva, le chef Jétheth,'),
('1ch',1,52,'crampon1923','le chef Oolibama, le chef Ela, le chef Phinon,'),
('1ch',1,53,'crampon1923','le chef Cénez, le chef Théman, le chef Mabsar,'),
('1ch',1,54,'crampon1923','le chef Magdiel, le chef Hiram. Ce sont là les chefs d''Edom.'),
('1ch',2,1,'crampon1923','Voici les fils d''Israël: Ruben, Siméon, Lévi, Juda, Issachar, Zabulon,'),
('1ch',2,2,'crampon1923','Dan, Joseph, Benjamin, Nephthali, Gad et Aser.'),
('1ch',2,3,'crampon1923','Fils de Juda: Her, Onan et Séla; ces trois lui naquirent de la fille de Sué, la Chananéenne. — Her, premier-né de Juda, était méchant aux yeux de Yahweh, qui le fit mourir. —'),
('1ch',2,4,'crampon1923','Thamar, belle-fille de Juda, lui enfanta Pharès et Zara. — Tous les fils de Juda furent au nombre de cinq.'),
('1ch',2,5,'crampon1923','Fils de Pharès: Hesron et Hamul. —'),
('1ch',2,6,'crampon1923','Fils de Zara: Zamri, Ethan, Eman, Chalchal et Dara: en tout, cinq. —'),
('1ch',2,7,'crampon1923','Fils de Charmi: Achar, qui troubla Israël par une transgression au sujet d''une chose vouée à l''anathème. —'),
('1ch',2,8,'crampon1923','Fils d''Ethan: Azarias.'),
('1ch',2,9,'crampon1923','Fils qui naquirent à Hesron: Jéraméel, Ram et Calubi.'),
('1ch',2,10,'crampon1923','Ram engendra Aminadab; Aminadab engendra Nahasson, prince des fils de Juda;'),
('1ch',2,11,'crampon1923','Nahasson engendra Salma; Salma engendra Booz;'),
('1ch',2,12,'crampon1923','Booz engendra Obed; Obed engendra Isaï;'),
('1ch',2,13,'crampon1923','Isaï engendra Eliab son premier-né, Abinadab, le deuxième, Simmaa le troisième,'),
('1ch',2,14,'crampon1923','Nathanaël, le quatrième, Raddaï, le cinquième,'),
('1ch',2,15,'crampon1923','Asom, le sixième, et David, le septième.'),
('1ch',2,16,'crampon1923','Leurs sœurs étaient: Sarvia et Abigaïl. — Fils de Sarvia: Abisaï, Joab et Asaël, trois. —'),
('1ch',2,17,'crampon1923','Abigaïl enfanta Amasa, dont le père fut Jéther, l''Ismaélite.'),
('1ch',2,18,'crampon1923','Caleb, fils de Hesron eut des enfants d''Azuba, sa femme, et de Jérioth. Voici les fils qu''il eut d''Azuba: Jaser, Sobab et Ardon.'),
('1ch',2,19,'crampon1923','Azuba mourut, et Caleb prit pour femme Ephrata, qui lui enfanta Hur.'),
('1ch',2,20,'crampon1923','Hur engendra Uri, et Uri engendra Bézéléel. —'),
('1ch',2,21,'crampon1923','Ensuite Hesron s''unit à la fille de Machir, père de Galaad: il avait soixante ans quand il la prit; elle lui enfanta Ségub.'),
('1ch',2,22,'crampon1923','Ségub engendra Jaïr, qui eut vingt-trois villes dans le pays de Galaad.'),
('1ch',2,23,'crampon1923','Les Gessuriens et les Syriens leur prirent les Bourgs de Jaïr, ainsi que Canath et les villes de sa dépendance: soixante villes. Tous ceux-là étaient fils de Machir, père de Galaad.'),
('1ch',2,24,'crampon1923','Après la mort de Hesron à Caleb-Ephrata, Abia, la femme de Hesron, lui enfanta Ashur, père de Thécua.'),
('1ch',2,25,'crampon1923','Les fils de Jéraméel, premier-né de Hesron, furent: Ram, le premier-né, Buna, Aran, Asom et Achia.'),
('1ch',2,26,'crampon1923','Jéraméel eut une autre femme, nommée Athara, qui fut mère d''Onam. —'),
('1ch',2,27,'crampon1923','Les fils de Ram, premier-né de Jéraméel furent: Moos, Jamin et Acar. —'),
('1ch',2,28,'crampon1923','Les fils d''Onam furent: Séméï et Jada. — Fils de Séméï: Nadab et Abisur.'),
('1ch',2,29,'crampon1923','Le nom de la femme d''Abisur était Abihaïl, et elle lui enfanta Ahobban et Molid.'),
('1ch',2,30,'crampon1923','Fils de Nadab: Saled et Apphaïm. Saled mourut sans fils.'),
('1ch',2,31,'crampon1923','Fils d''Apphaïm: Jési. Fils de Jési: Sésan. Fils de Sesan: Oholaï. —'),
('1ch',2,32,'crampon1923','Fils de Jada, frère de Séméï: Jéther et Jonathan. Jéther mourut sans fils.'),
('1ch',2,33,'crampon1923','Fils de Jonathan: Phaleth et Ziza. — Ce sont là les fils de Jéraméel. —'),
('1ch',2,34,'crampon1923','Sésan n''eut pas de fils, mais il eut des filles. Il avait un esclave Egyptien, nommé Jéraa;'),
('1ch',2,35,'crampon1923','il lui donna sa fille pour femme, et elle lui enfanta Ethéï.'),
('1ch',2,36,'crampon1923','Ethéï engendra Nathan; Nathan engendra Zabad;'),
('1ch',2,37,'crampon1923','Zabad engendra Ophlal; Ophlal engendra Obed;'),
('1ch',2,38,'crampon1923','Obed engendra Jéhu; Jéhu engendra Azarias;'),
('1ch',2,39,'crampon1923','Azarias engendra Hellès; Hellès engendra Elasa;'),
('1ch',2,40,'crampon1923','Elasa engendra Sisamoï; Sisamoï engendra Sellum;'),
('1ch',2,41,'crampon1923','Sellum engendra Icamias, et Icamias engendra Elisama.'),
('1ch',2,42,'crampon1923','Fils de Caleb, frère de Jéraméel: Mésa, son premier-né, qui fut père de Ziph, et les fils de Marésa, père d''Hébron. —'),
('1ch',2,43,'crampon1923','Fils d''Hébron: Coré, Thaphua, Récem et Samma.'),
('1ch',2,44,'crampon1923','Samma engendra Raham, père de Jercaam; Récem engendra Sammaï. —'),
('1ch',2,45,'crampon1923','Fils de Sammaï: Maon; et Maon fut père de Bethsur. —'),
('1ch',2,46,'crampon1923','Epha, concubine de Caleb, enfanta Haran, Mosa et Gézez. Haran engendra Gézez. —'),
('1ch',2,47,'crampon1923','Fils de Jahaddaï: Regom, Joathan, Gosan, Phalet, Epha et Saaph. —'),
('1ch',2,48,'crampon1923','Maacha, concubine de Caleb, enfanta Saber et Tharana.'),
('1ch',2,49,'crampon1923','Elle enfanta encore Saaph, père de Madména, Sué, père de Machbéna et père de Gabaa. La fille de Caleb était Achsa.'),
('1ch',2,50,'crampon1923','Ceux-ci furent fils de Caleb. Fils de Hur, premier-né d''Ephrata: Sobal, père de Cariathiarim;'),
('1ch',2,51,'crampon1923','Salma, père de Bethléem; Hariph, père de Bethgader. —'),
('1ch',2,52,'crampon1923','Les fils de Sobal, père de Cariathiarim, furent: Haroé, Hatsi-Hamménuhoth.'),
('1ch',2,53,'crampon1923','Les familles de Cariathiarim, furent: les Jethréens, les Aphuthéens, les Sémathéens et les Maséréens. D''eux sont sortis les Saréens et les Esthaoliens. —'),
('1ch',2,54,'crampon1923','Fils de Salma: Bethléem et les Nétophatiens, Ataroth-Beth-Joab, moitié des Manachtiens, les Saréens,'),
('1ch',2,55,'crampon1923','ainsi que les familles des Scribes demeurant à Jabès, savoir, les Thiratiens, les Schimathiens et les Sucathiens. Ce sont les Cinéens, issus de Hamath, père de la maison de Réchab.'),
('1ch',3,1,'crampon1923','Voici les fils de David qui lui naquirent à Hébron: le premier-né, Amnon, d''Achinoam de Jezraël; le second, Daniel, d''Abigaïl de Carmel;'),
('1ch',3,2,'crampon1923','le troisième, Absalom, fils de Maacha, fille de Tholmaï, roi de Gessur; le quatrième, Adonias, fils de Haggith;'),
('1ch',3,3,'crampon1923','le cinquième, Saphatias, d''Abital; le sixième, Jéthraham, d''Egla, sa femme.'),
('1ch',3,4,'crampon1923','Ces six lui naquirent à Hébron, où il régna sept ans et six mois; puis il régna trente-trois ans à Jérusalem.'),
('1ch',3,5,'crampon1923','Et ceux-ci lui naquirent à Jérusalem: Simmaa, Sobab, Nathan, Salomon, quatre, de Bethsué, fille d''Ammiel;'),
('1ch',3,6,'crampon1923','Jébaar, Elisama, Eliphaleth,'),
('1ch',3,7,'crampon1923','Nogé, Népheg, Japhia,'),
('1ch',3,8,'crampon1923','Elisama, Eliada, Eliphéleth, neuf.'),
('1ch',3,9,'crampon1923','Ce sont là tous les fils de David, sans compter les fils des concubines. Thamar était leur sœur.'),
('1ch',3,10,'crampon1923','Fils de Salomon: Roboam; Abias, son fils; Asa, son fils; Josaphat, son fils;'),
('1ch',3,11,'crampon1923','Joram, son fils; Ochozias, son fils; Joas, son fils;'),
('1ch',3,12,'crampon1923','Amazias, son fils; Azarias, son fils; Joatham, son fils;'),
('1ch',3,13,'crampon1923','Achaz, son fils; Ezéchias, son fils; Manassé, son fils;'),
('1ch',3,14,'crampon1923','Amon, son fils; Josias, son fils.'),
('1ch',3,15,'crampon1923','Fils de Josias: le premier-né Johanan; le deuxième, Joakim; le troisième, Sédécias; le quatrième, Sellum. —'),
('1ch',3,16,'crampon1923','Fils de Joakim: Jéchonias, son fils; Sédécias, son fils. —'),
('1ch',3,17,'crampon1923','Fils de Jéchonias: Asir, Salathiel, son fils,'),
('1ch',3,18,'crampon1923','Melchiram, Phadaïa, Sennéser, Jécémias, Sama et Nadabias. —'),
('1ch',3,19,'crampon1923','Fils de Phadaïas: Zorobabel et Séméï. — Fils de Zorobabel: Mosollam, Hananias et Salomith, leur sœur;'),
('1ch',3,20,'crampon1923','et Hasaban, Ohol, Barachias, Hasadias, Josabhésed, cinq. —'),
('1ch',3,21,'crampon1923','Fils de Hananias: Phaltias et Jéséïas, les fils de Raphaïa, les fils d''Arnan, les fils d''Obdia, les fils de Séchénias. —'),
('1ch',3,22,'crampon1923','Fils de Séchénias: Séméïa. — Fils de Séméïa: Hattus, Jégaal, Baria, Naaria, Saphat, six. —'),
('1ch',3,23,'crampon1923','Fils de Naaria: Elioénaï, Ezéchias et Ezricam: trois. —'),
('1ch',3,24,'crampon1923','Fils d''Elioénaï: Oduïa, Eliasub, Phéléïa, Accub, Johanan, Dalaïa et Anani: sept.'),
('1ch',4,1,'crampon1923','Fils de Juda: Pharès, Hesron, Charmi, Hur et Sobal. —'),
('1ch',4,2,'crampon1923','Raïa, fils de Sobal, engendra Jahath; Jahath engendra Achamaï et Lahad. Ce sont les familles des Saréens.'),
('1ch',4,3,'crampon1923','Voici les descendants du père d''Etam: Jezrahel, Jéséma et Jédébos; le nom de leur sœur était Asalelphuni.'),
('1ch',4,4,'crampon1923','Phanuel fut le père de Gédor, et Ezer celui de Hosa. Ce sont là les fils de Hur, premier-né d''Ephrata, père de Bethléem.'),
('1ch',4,5,'crampon1923','Assur, père de Thécué, eut deux femmes: Halaa et Naara.'),
('1ch',4,6,'crampon1923','Naara lui enfanta Oozam, Hépher, Thémani et Ahasthari: ce sont là les fils de Naara. —'),
('1ch',4,7,'crampon1923','Fils de Halaa: Séreth, Isaar et Ethnan.'),
('1ch',4,8,'crampon1923','Cos engendra Anob et Soboba, et les familles d''Aharéhel, fils d''Arum.'),
('1ch',4,9,'crampon1923','Jabès était plus honoré que ses frères; sa mère lui donna le nom de Jabès, en disant: " C''est parce que je l''ai enfanté avec douleur. "'),
('1ch',4,10,'crampon1923','Jabès invoqua le Dieu d''Israël en disant: " Si vous me bénissez et que vous étendiez mes limites, si votre main est avec moi et si vous me préservez du malheur, en sorte que je ne sois pas dans l''affliction!... " Et Dieu lui accorda ce qu''il avait demandé.'),
('1ch',4,11,'crampon1923','Kélub, frère de Sua, engendra Mahir, qui fut père d''Esthon.'),
('1ch',4,12,'crampon1923','Esthon engendra la maison de Rapha, Phessé et Tehinna, père de la ville de Naas. Ce sont là les hommes de Récha.'),
('1ch',4,13,'crampon1923','Fils de Cénez: Othoniel et Saraïa. — Fils d''Othoniel: Hathath et Maonathi;'),
('1ch',4,14,'crampon1923','Maonathi engendra Ophra — Saraïa engendra Joab, père de ceux qui habitaient la vallée de Charaschim, car ils étaient ouvriers. —'),
('1ch',4,15,'crampon1923','Fils de Caleb, fils de Jéphoné: Hir, Ela et Maham. — Fils d''Ela: Cénez.'),
('1ch',4,16,'crampon1923','Fils de Jaléléel: Ziph, Zipha, Thiria et Asraël.'),
('1ch',4,17,'crampon1923','Fils d''Esra: Jéther, Méred, Epher et Jalon. La femme de Méred, l''Egyptienne, enfanta Mariam, Sammaï et Jesba, père d''Esthamo.'),
('1ch',4,18,'crampon1923','Son autre femme, la Juive, enfanta Jared, père de Gédor, Héber, père de Socho, et Icuthiel, père de Zanoé. Ceux-là sont les fils de Béthia, fille de Pharaon, que Méred avait prise pour femme.'),
('1ch',4,19,'crampon1923','Fils de la femme d''Odaïa, sœur de Naham: le père de Céïla, le Garmien, et le père d''Esthamo, le Machathien.'),
('1ch',4,20,'crampon1923','Fils de Simon: Amnon, Rinna, Ben-Hanan et Thilon. Fils de Jési: Zoheth et Ben-Zoheth.'),
('1ch',4,21,'crampon1923','Fils de Séla, fils de Juda: Her, père de Lécha, Laada, père de Marésa, et les familles de la maison où l''on travaille le byssus, de la maison d''Aschbéa,'),
('1ch',4,22,'crampon1923','et Jokim, et les hommes de Cozéba, et Joas, et Saraph, qui dominèrent sur Moab, et Jaschubi-Léchem. Ces choses sont anciennes.'),
('1ch',4,23,'crampon1923','C''étaient les potiers et les habitants de Nétaïm et de Gédéra; ils demeuraient là, près du roi, travaillant pour lui.'),
('1ch',4,24,'crampon1923','Fils de Siméon: Namuel, Jamin, Jarib, Zara, Saül.'),
('1ch',4,25,'crampon1923','Sellum, son fils; Madsam, son fils; Masma, son Fils. —'),
('1ch',4,26,'crampon1923','Fils de Masma: Hamuel, son fils; Zachur, son fils; Séméï, son fils. —'),
('1ch',4,27,'crampon1923','Séméï eut seize fils et six filles; ses frères n''eurent pas beaucoup de fils, et toutes leurs familles ne se multiplièrent pas autant que les fils de Juda.'),
('1ch',4,28,'crampon1923','Ils habitaient à Bersabée, à Molada, à Hasar-Suhal,'),
('1ch',4,29,'crampon1923','à Bala, à Asom, à Tholad,'),
('1ch',4,30,'crampon1923','à Bathuel, à Horma, à Sicéleg,'),
('1ch',4,31,'crampon1923','à Beth-Marchaboth, à Hasar-Susim, à Beth-Béraï et à Saarim: ce furent là leurs villes jusqu''au règne de David,'),
('1ch',4,32,'crampon1923','et leurs villages. Ils avaient encore: Etam, Aën, Remmon, Thochen et Asan, cinq villes,'),
('1ch',4,33,'crampon1923','et tous leurs villages, qui étaient aux environs de ces villes, jusqu''à Baal. Voilà leurs habitations, et leurs registres généalogiques.'),
('1ch',4,34,'crampon1923','Mosobab, Jemlech, Josa, fils d''Amasias,'),
('1ch',4,35,'crampon1923','Joël, Jéhu, fils de Josabias, fils de Saraïas, fils d''Asiel,'),
('1ch',4,36,'crampon1923','Elioénaï, Jacoba, Isuhaïa, Asaïa, Adiel, Ismiel, Banaïa,'),
('1ch',4,37,'crampon1923','Ziza, fils de Séphéï, fils d''Allon, fils d''Idaïa, fils de Semri, fils de Samaïa.'),
('1ch',4,38,'crampon1923','Ces hommes désignés par leurs noms étaient princes dans leurs familles. Leurs maisons patriarcales ayant pris un grand accroissement,'),
('1ch',4,39,'crampon1923','ils allèrent vers l''entrée de Gador, jusqu''à l''orient de la vallée, afin de chercher des pâturages pour leurs troupeaux.'),
('1ch',4,40,'crampon1923','Ils trouvèrent des pâturages gras et bons, et un territoire spacieux, tranquille et paisible; ceux qui y habitaient auparavant provenaient de Cham.'),
('1ch',4,41,'crampon1923','Ces hommes, inscrits par leurs noms, arrivèrent du temps d''Ezéchias, roi de Juda; ils détruisirent leurs tentes, ainsi que les Maonites qui se trouvaient là et, les ayant dévoués à l''anathème jusqu''à ce jour, ils s''établirent à leur place, car il y avait là des pâturages pour leurs troupeaux.'),
('1ch',4,42,'crampon1923','Des fils de Siméon allèrent aussi à la montagne de Séïr, au nombre de cinq cents hommes; Phaltias, Naarias, Raphaïas et Oziel, fils de Jési, étaient à leur tête.'),
('1ch',4,43,'crampon1923','Ils battirent le reste des Amalécites qui avaient échappé, et ils s''établirent là jusqu''à ce jour.'),
('1ch',5,1,'crampon1923','Fils de Ruben, premier-né d''Israël. — Car il était le premier-né; mais, parce qu''il souilla la couche de son père, son droit d''aînesse fut donné aux fils de Joseph, fils d''Israël, non, toutefois, pour que Joseph fût inscrit dans les généalogie comme premier-né.'),
('1ch',5,2,'crampon1923','Car Judas fut puissant parmi ses frères, et de lui est issu un prince. Mais le droit d''aînesse est à Joseph. —'),
('1ch',5,3,'crampon1923','Fils de Ruben, premier-né d''Israël: Enoch, Phallu, Esron et Charmi.'),
('1ch',5,4,'crampon1923','Fils de Joël: Samia, son fils; Gog, son fils; Séméï, son fils;'),
('1ch',5,5,'crampon1923','Micha, son fils; Réïa, son fils; Baal, son fils;'),
('1ch',5,6,'crampon1923','Bééra, son fils, que Thelgathphalnasar, roi d''Assyrie, emmena captif: il fut un des princes des Rubénites. —'),
('1ch',5,7,'crampon1923','Frères de Bééra, chacun selon sa famille, tels qu''ils sont inscrits dans les généalogies selon leurs générations: le chef, Jéhiel; Zacharie;'),
('1ch',5,8,'crampon1923','Bala, fils d''Azaz, fils de Samma, fils de Joël. Bala habitait à Aroër, et jusqu''à Nébo et à Béel-Méon;'),
('1ch',5,9,'crampon1923','à l''orient, il habitait jusqu''à l''entrée du désert, qui va depuis le fleuve de l''Euphrate, car leurs troupeaux étaient nombreux dans le pays de Galaad.'),
('1ch',5,10,'crampon1923','Du temps de Saül, ils firent la guerre aux Agaréens, qui tombèrent entre leurs mains, et ils habitèrent dans leurs tentes, sur tout le côté oriental de Galaad.'),
('1ch',5,11,'crampon1923','Les fils de Gad habitaient vis-à-vis d''eux dans le pays de Basan, jusqu''à Selcha.'),
('1ch',5,12,'crampon1923','C''étaient: le chef, Joël; le second, Saphan, puis Janaï et Saphath, en Basan.'),
('1ch',5,13,'crampon1923','Leurs frères, d''après leurs maisons patriarcales, étaient: Michaël, Mosollam, Sébé, Joraï, Jachan, Zié et Héber: sept.'),
('1ch',5,14,'crampon1923','Ils étaient fils d''Abihaïl, fils de Huri, fils de Jara, fils de Galaad, fils de Michaël, fils de Jésési, fils de Jeddo, fils de Buz.'),
('1ch',5,15,'crampon1923','Achi, fils d''Abdiel, fils de Guni, était chef de leurs maisons patriarcales.'),
('1ch',5,16,'crampon1923','Ils habitaient en Galaad, en Basan, et dans les villes de leurs dépendances, et dans tous les pâturages de Saron jusqu''à leurs extrémités.'),
('1ch',5,17,'crampon1923','Tous ces fils de Gad furent enregistrés dans les généalogies du temps de Joatham, roi de Juda, et du temps de Jéroboam, roi d''Israël.'),
('1ch',5,18,'crampon1923','Les fils de Ruben, les Gadites et la demi-tribu de Manassé avaient de vaillants hommes, portant le bouclier et l''épée, tirant de l''arc, et exercés à la guerre, au nombre de quarante quatre mille sept cent soixante, en état d''aller à l''armée.'),
('1ch',5,19,'crampon1923','Ils firent la guerre aux Agaréens, à Jéthur, à Naphis et à Nodab.'),
('1ch',5,20,'crampon1923','Ils furent aidés contre eux, et les Agaréens et tous ceux qui étaient avec eux furent livrés entre leurs mains. Car ils avaient crié vers Dieu pendant le combat, et il les avait exaucés, parce qu''ils s''étaient confiés en lui.'),
('1ch',5,21,'crampon1923','Ils enlevèrent leurs troupeaux, cinquante mille chameaux, deux cent cinquante mille brebis, deux mille ânes, et cent mille personnes,'),
('1ch',5,22,'crampon1923','car il était tombé beaucoup de morts, parce que la guerre était de Dieu. Et ils s''établirent à leur place jusqu''à la captivité.'),
('1ch',5,23,'crampon1923','Les fils de la demi-tribu de Manassé habitaient dans le pays depuis Basan jusqu''à Baal-Hermon et à Sanir, et à la montagne d''Hermon; ils étaient nombreux.'),
('1ch',5,24,'crampon1923','Voici les chefs de leurs familles: Epher, Jési, Eliel, Ezriel, Jérémia, Odoïa et Jédiel, hommes forts et vaillants, hommes de renom, chefs de leurs maisons patriarcales.'),
('1ch',5,25,'crampon1923','Mais ils furent infidèles au Dieu de leurs pères, et ils se prostituèrent en servant les dieux des peuples du pays que Dieu avait détruits devant eux.'),
('1ch',5,26,'crampon1923','Le Dieu d''Israël excita l''esprit de Phul, roi d''Assyrie, et l''esprit de Thelgathphalnasar, roi d''Assyrie; et Thelgathphalnasar emmena captifs les Rubénites, les Gadites et la demi-tribu de Manassé, et il les conduisit à Hala, à Habor, à Ara et au fleuve de Gozan, où ils sont demeurés jusqu''à ce jour.'),
('1ch',5,27,'crampon1923','Fils de Lévi: Gersom, Caath et Mérari.'),
('1ch',5,28,'crampon1923','Fils de Caath: Amram, Isaar et Oziel.'),
('1ch',5,29,'crampon1923','Fils d''Amram: Aaron, Moïse et Marie. — Fils d''Aaron: Nadab, Abiu, Eléazar et Ithamar. —'),
('1ch',5,30,'crampon1923','Eléazar engendra Phinées; Phinées engendra Abisué;'),
('1ch',5,31,'crampon1923','Abisué engendra Bocci; Bocci engendra Ozi;'),
('1ch',5,32,'crampon1923','Ozi engendra Zaraïas; Zaraïas engendra Méraïoth;'),
('1ch',5,33,'crampon1923','Méraïoth engendra Amarias; Amarias engendra Achitob;'),
('1ch',5,34,'crampon1923','Achitob engendra Sadoc; Sadoc engendra Achimaas;'),
('1ch',5,35,'crampon1923','Achimaas engendra Azarias; Azarias engendra Johanan;'),
('1ch',5,36,'crampon1923','Johanan engendra Azarias: c''est lui qui exerça le sacerdoce dans la maison que Salomon bâtit à Jérusalem;'),
('1ch',5,37,'crampon1923','Azarias engendra Amarias; Amarias engendra Achitob;'),
('1ch',5,38,'crampon1923','Achitob engendra Sadoc; Sadoc engendra Sellum;'),
('1ch',5,39,'crampon1923','Sellum engendra Helcias; Helcias engendra Azarias;'),
('1ch',5,40,'crampon1923','Azarias engendra Saraïas; Saraïas engendra Josédec.'),
('1ch',5,41,'crampon1923','Josédec partit pour l''exil quand Yahweh fil emmener en captivité Juda et Jérusalem par l''intermédiaire de Nabuchodonosor.'),
('1ch',6,1,'crampon1923','Fils de Lévi: Gersom, Caath et Mérari. —'),
('1ch',6,2,'crampon1923','Voici les noms des fils de Gersom: Lobni et Séméï. —'),
('1ch',6,3,'crampon1923','Fils de Caath: Amram, Isaar, Hébron et Oziel. —'),
('1ch',6,4,'crampon1923','Fils de Mérari: Moholi et Musi. Voici les familles de Lévi selon leurs pères:'),
('1ch',6,5,'crampon1923','De Gersom: Lobni, son fils; Jahath, son fils; Zamma, son fils;'),
('1ch',6,6,'crampon1923','Joah, son fils; Addo, son fils; Zara, son fils; Jethraï, son fils. —'),
('1ch',6,7,'crampon1923','Fils de Caath: Aminadab, son fils; Coré, son fils; Asir, son fils;'),
('1ch',6,8,'crampon1923','Elcana, son fils; Abiasaph, son fils; Asir, son fils;'),
('1ch',6,9,'crampon1923','Thahath, son fils; Uriel, son fils; Ozias, son fils; Saül, son fils.'),
('1ch',6,10,'crampon1923','Fils d''Elcana: Amasaï et Achimoth;'),
('1ch',6,11,'crampon1923','Elcana, son fils; Sophaï, son fils; Nahath, son fils;'),
('1ch',6,12,'crampon1923','Eliab, son fils; Jéroham, son fils; Elcana, son fils.'),
('1ch',6,13,'crampon1923','Fils de Samuel: le premier-né Vasséni, et Abia. —'),
('1ch',6,14,'crampon1923','Fils de Mérari: Moholi; Lobni, son fils; Séméï, son fils; Oza, son fils;'),
('1ch',6,15,'crampon1923','Sammaa, son fils; Haggia, son fils; Asaïa, son fils.'),
('1ch',6,16,'crampon1923','Voici ceux que David établit pour diriger le chant dans la maison de Yahweh, depuis que l''arche eut un lieu de repos:'),
('1ch',6,17,'crampon1923','ils remplirent les fonctions de chantres devant la Demeure de la tente de réunion, jusqu''à ce que Salomon eût bâti la maison de Yahweh à Jérusalem, et ils se tenaient à leur service selon leur règlement. —'),
('1ch',6,18,'crampon1923','Voici ceux qui officiaient avec leurs fils: — D''entre les fils des Caathites: Héman, le chantre, fils de Joël, fils de Samuel,'),
('1ch',6,19,'crampon1923','fils d''Elcana, fils de Jéroham, fils d''Eliel, fils de Thohu,'),
('1ch',6,20,'crampon1923','fils de Suph, fils d''Elcana, fils de Mahath, fils d''Amasaï,'),
('1ch',6,21,'crampon1923','fils d''Elcana, fils de Joël, fils d''Azarias, fils de Sophonias,'),
('1ch',6,22,'crampon1923','fils de Thahath, fils d''Asir, fils d''Abiasaph, fils de Coré,'),
('1ch',6,23,'crampon1923','fils d''Isaar, fils de Caath, fils de Lévi, fils d''Israël.'),
('1ch',6,24,'crampon1923','— Son frère Asaph, qui se tenait à sa droite: Asaph, fils de Barachias, fils de Samaa,'),
('1ch',6,25,'crampon1923','fils de Michaël, fils de Basaïas, fils de Melchias,')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('1ch',6,26,'crampon1923','fils d''Athanaï, fils de Zara, fils d''Adaïa,'),
('1ch',6,27,'crampon1923','fils d''Ethan, fils de Zamma, fils de Séméï,'),
('1ch',6,28,'crampon1923','fils de Jeth, fils de Gersom, fils de Lévi.'),
('1ch',6,29,'crampon1923','— Fils de Mérari, leurs frères, à la gauche: Ethan, fils de Cusi, fils d''Abdi, fils de Maloch,'),
('1ch',6,30,'crampon1923','fils de Hasabias, fils d''Amasias, fils de Helcias,'),
('1ch',6,31,'crampon1923','fils d''Amasaï, fils de Boni, fils de Somer,'),
('1ch',6,32,'crampon1923','fils de Moholi, fils de Musi, fils de Mérari, fils de Lévi.'),
('1ch',6,33,'crampon1923','Leurs frères, les lévites, étaient chargés de tout le service du tabernacle de la maison de Yahweh.'),
('1ch',6,34,'crampon1923','Mais Aaron et ses fils brûlaient les victimes sur l''autel des holocaustes et l''encens sur l''autel des parfums; ils avaient à remplir tout le ministère du saint des saints, et à faire l''expiation pour Israël, selon tout ce qu''avait ordonné Moïse, serviteur de Dieu.'),
('1ch',6,35,'crampon1923','Voici les fils d''Aaron: Eléazar, son fils; Phinées, son fils; Abisué, son fils;'),
('1ch',6,36,'crampon1923','Bocci, son fils; Ozi, son fils; Zaraïas, son fils;'),
('1ch',6,37,'crampon1923','Méraïoth, son fils; Amarias, son fils; Achitob, son fils;'),
('1ch',6,38,'crampon1923','Sadoc, son fils; Achimaas, son fils.'),
('1ch',6,39,'crampon1923','Voici leurs habitations, selon leurs enceintes, dans leurs territoires: — Aux fils d''Aaron, de la famille des Caathites, désignés les premiers par le sort,'),
('1ch',6,40,'crampon1923','on donna Hébron, dans le pays de Juda, et les pâturages qui l''entourent;'),
('1ch',6,41,'crampon1923','mais on donna le territoire de la ville et ses villages à Caleb, fils de Jéphoné.'),
('1ch',6,42,'crampon1923','On donna donc aux fils d''Aaron la ville de refuge Hébron, Lobna et ses pâturages,'),
('1ch',6,43,'crampon1923','Jéther, Esthémo et ses pâturages, Hélon et ses pâturages, Dabir et ses pâturages,'),
('1ch',6,44,'crampon1923','Asan et ses pâturages, Bethsémès et ses pâturages;'),
('1ch',6,45,'crampon1923','de la tribu de Benjamin, Gabée et ses pâturages, Almath et ses pâturages, Anathoth et ses pâturages. Total de leurs villes: treize villes, d''après leurs familles.'),
('1ch',6,46,'crampon1923','— Les autres fils de Caath eurent par le sort dix villes des familles de la tribu, de la demi-tribu de Manassé.'),
('1ch',6,47,'crampon1923','Les fils de Gersom, d''après leurs familles, eurent treize villes de la tribu d''Issachar, de la tribu d''Aser, de la tribu de Nephthali et de la tribu de Manassé, en Basan.'),
('1ch',6,48,'crampon1923','Les fils de Mérari, d''après leurs familles, eurent par le sort douze villes de la tribu de Ruben, de la tribu de Gad et de la tribu de Zabulon.'),
('1ch',6,49,'crampon1923','Les enfants d''Israël donnèrent aux Lévites les villes et leurs pâturages.'),
('1ch',6,50,'crampon1923','Ils donnèrent par le sort, de la tribu des enfants de Juda, de la tribu des enfants de Siméon et de la tribu des enfants de Benjamin, ces villes qu''ils désignèrent par leurs noms.'),
('1ch',6,51,'crampon1923','Pour les autres familles des fils de Caath, les villes qui leur échurent furent de la tribu d''Ephraïm.'),
('1ch',6,52,'crampon1923','On leur donna: la ville de refuge Sichem et ses pâturages, dans la montagne d''Ephraïm, Gazer et ses pâturages,'),
('1ch',6,53,'crampon1923','Jecmaam et ses pâturages, Bethoron et ses pâturages,'),
('1ch',6,54,'crampon1923','Hélon et ses pâturages, Geth-Remmon et ses pâturages;'),
('1ch',6,55,'crampon1923','et de la demi-tribu de Manassé, Aner et ses pâturages, Balaam et ses pâturages: pour les familles des autres fils de Caath.'),
('1ch',6,56,'crampon1923','On donna aux fils de Gersom: de la famille de la demi-tribu de Manassé, Gaulon en Basan et ses pâturages, Astharoth et ses pâturages;'),
('1ch',6,57,'crampon1923','de la tribu d''Issachar, Cédès et ses pâturages, Dabéreth et ses pâturages,'),
('1ch',6,58,'crampon1923','Ramoth et ses pâturages, Anem et ses pâturages;'),
('1ch',6,59,'crampon1923','de la tribu d''Aser, Masal et ses pâturages, Abdon et ses pâturages,'),
('1ch',6,60,'crampon1923','Hucac et ses pâturages, Rohob et ses pâturages;'),
('1ch',6,61,'crampon1923','et de la tribu de Nephthali, Cédès en Galilée et ses pâturages, Hamon et ses pâturages, et Cariathaïm et ses pâturages.'),
('1ch',6,62,'crampon1923','On donna au reste des Lévites, aux fils de Mérari: de la tribu de Zabulon, Remmono et ses pâturages, Thabor et ses pâturages;'),
('1ch',6,63,'crampon1923','de l''autre côté du Jourdain, vis-à-vis de Jéricho, à l''orient du Jourdain: de la tribu de Ruben, Bosor, au désert, et ses pâturages, Jassa et ses pâturages,'),
('1ch',6,64,'crampon1923','Cadémoth et ses pâturages, Méphaat et ses pâturages;'),
('1ch',6,65,'crampon1923','et de la tribu de Gad, Ramoth en Galaad et ses pâturages, Manaïm, et ses pâturages,'),
('1ch',6,66,'crampon1923','Hésebon et ses pâturages, Jézer et ses pâturages.'),
('1ch',7,1,'crampon1923','Fils d''Issachar: Thola, Phua, Jasub et Siméron: quatre. —'),
('1ch',7,2,'crampon1923','Fils de Thola: Ozi, Raphaïa, Jériel, Jémaï, Jebsem et Samuel, chefs de leurs maisons patriarcales issues de Thola, vaillants hommes, inscrits d''après leurs générations, au temps de David, au nombre de vingt-deux mille six cents. —'),
('1ch',7,3,'crampon1923','Fils d''Ozi: Izrahia. Fils de Izrahia: Michaël, Obadia, Johel et Jésia: en tout cinq chefs.'),
('1ch',7,4,'crampon1923','Ils avaient avec eux, selon leurs générations, selon leurs maisons patriarcales, des troupes armées pour la guerre, trente-six mille hommes; car ils avaient beaucoup de femmes et de fils.'),
('1ch',7,5,'crampon1923','Leurs frères, d''après toutes les familles d''Issachar, hommes vaillants, formaient un nombre total de quatre-vingt-sept mille, inscrits dans les généalogies.'),
('1ch',7,6,'crampon1923','Fils de Benjamin: Béla, Béchor et Jadiel: trois. —'),
('1ch',7,7,'crampon1923','Fils de Béla: Esbon, Ozi, Oziel, Jérimoth et Uraï: cinq chefs de maisons patriarcales, hommes vaillants, inscrits dans les généalogies, au nombre de vingt-deux mille quatre cents. —'),
('1ch',7,8,'crampon1923','Fils de Béchor: Zamira, Joas, Eliézer, Elioénaï, Amri, Jérimoth, Abia, Anathoth et Almath: tous ceux-là fils de Béchor,'),
('1ch',7,9,'crampon1923','inscrits dans les généalogies, d''après leurs générations, comme chefs de leurs maisons patriarcales, hommes vaillants, au nombre de vingt mille deux cents. —'),
('1ch',7,10,'crampon1923','Fils de Jadihel: Balan. — Fils de Balan: Jéhus, Benjamin, Aod, Chanana, Zéthan, Tarsis et Abisahar:'),
('1ch',7,11,'crampon1923','tous ceux là fils de Jadihel, chefs de leurs maisons patriarcales, hommes vaillants, au nombre de dix-sept mille deux cents, en état d''aller en armes à la guerre.'),
('1ch',7,12,'crampon1923','Sepham et Hapham, fils d''Hir: Hasim, fils d''Aher.'),
('1ch',7,13,'crampon1923','Fils de Nephthali: Jasiel, Guni, Jéser et Sellum, fils de Bala.'),
('1ch',7,14,'crampon1923','Fils de Manassé: Esriel. Sa concubine syrienne enfanta Machir, père de Galaad. —'),
('1ch',7,15,'crampon1923','Machir prit une femme de Happhim et de Saphan; le nom de sa sœur était Maacha. Le nom du second fils était Salphaad, et Salphaad eut des filles.'),
('1ch',7,16,'crampon1923','Maacha, femme de Machir, enfanta un fils, et l''appela du nom de Pharès; le nom de son frère était Sarès, et ses fils étaient Ulam et Récen. —'),
('1ch',7,17,'crampon1923','Fils d''Ulam: Badan. — Ce sont là les fils de Galaad, fils de Machir, fils de Manassé. —'),
('1ch',7,18,'crampon1923','Sa sœur Hammoléketh enfanta Ischod, Abiézer et Mohola. —'),
('1ch',7,19,'crampon1923','Les fils de Sémida étaient: Ahin, Séchem, Léci et Aniam.'),
('1ch',7,20,'crampon1923','Fils d''Ephraïm: Suthala; Bared, son fils; Thahath, son fils; Elada, son fils; Thahath, son fils;'),
('1ch',7,21,'crampon1923','Zabad, son fils; Suthala, son fils; Ezer et Elad, que tuèrent les hommes de Geth nés dans le pays, parce qu''ils étaient descendus pour prendre leurs troupeaux.'),
('1ch',7,22,'crampon1923','Ephraïm, leur père, fut longtemps dans le deuil, et ses frères vinrent pour le consoler.'),
('1ch',7,23,'crampon1923','Et il alla vers sa femme, et elle conçut et enfanta un fils; il l''appela du nom de Béria, parce qu''on était dans le malheur en sa maison.'),
('1ch',7,24,'crampon1923','Sa fille était Sara, qui bâtit Bethoron le Bas et Bethoron le Haut, et Ozen-Sara.'),
('1ch',7,25,'crampon1923','Rapha, son fils, et Réseph; Thalé, son fils; Taan, son fils;'),
('1ch',7,26,'crampon1923','Laadan, son fils; Ammiud, son fils; Elisama, son fils;'),
('1ch',7,27,'crampon1923','Nun, son fils; Josué, son fils. —'),
('1ch',7,28,'crampon1923','Leurs possessions et leurs habitations étaient: Béthel et les villes de sa dépendance; à l''orient, Noran; à l''occident, Gézer et les villes de sa dépendance, Sichem et les villes de sa dépendance, jusqu''à Aza et aux villes de sa dépendance.'),
('1ch',7,29,'crampon1923','Entre les mains des fils de Manassé étaient encore Bethsan et les villes de sa dépendance, Thanach et les villes de sa dépendance, Mageddo et les villes de sa dépendance, Dor et les villes de sa dépendance. Ce fut dans ces villes qu''habitèrent les fils de Joseph, fils d''Israël.'),
('1ch',7,30,'crampon1923','Fils d''Aser: Jemma, Jésua, Jessui, Baria, et Sara, leur sœur. —'),
('1ch',7,31,'crampon1923','Fils de Baria: Héber et Melchiel, qui fut père de Barsaïth.'),
('1ch',7,32,'crampon1923','Héber engendra Jéphlat, Somer, Hotham, et Suaa, leur sœur. —'),
('1ch',7,33,'crampon1923','Fils de Jéphlat: Phosech, Chamaal et Asoth: ce sont là les fils de Jéphlat. —'),
('1ch',7,34,'crampon1923','Fils de Somer: Ahi, Roaga, Haba et Aram. —'),
('1ch',7,35,'crampon1923','Fils de Hélem, son frère: Supha, Jemna, Sellès et Amal. —'),
('1ch',7,36,'crampon1923','Fils de Supha: Sué, Harnapher, Sual, Béri, Jamra,'),
('1ch',7,37,'crampon1923','Bosor, Hod, Samma, Salusa, Jéthran et Béra. —'),
('1ch',7,38,'crampon1923','Fils de Jéther: Jéphoné, Phaspha et Ara. —'),
('1ch',7,39,'crampon1923','Fils d''Olla: Arée, Haniel et Résia. —'),
('1ch',7,40,'crampon1923','Tous ceux-là étaient fils d''Aser, chefs de maisons patriarcales, hommes d''élite et vaillants, chefs des princes, inscrits au nombre de vingt-six mille hommes en état d''aller en armes à la guerre.'),
('1ch',8,1,'crampon1923','Benjamin engendra Béla, son premier-né, Asbel le second, Ahara le troisième,'),
('1ch',8,2,'crampon1923','Nohaa, le quatrième et Rapha le cinquième. —'),
('1ch',8,3,'crampon1923','Les fils de Béla furent: Addar, Géra, Abiud,'),
('1ch',8,4,'crampon1923','Abisué, Naaman, Ahoé,'),
('1ch',8,5,'crampon1923','Géra, Séphuphan, et Huram.'),
('1ch',8,6,'crampon1923','Voici les fils d''Ahod: — ils étaient chefs des familles qui habitaient Gabaa, et ils les déportèrent à Manahath —:'),
('1ch',8,7,'crampon1923','Naaman, Achia et Géra; c''est lui qui les déporta, et il engendra Oza et Ahiud.'),
('1ch',8,8,'crampon1923','Saharaïm eut des enfants au pays de Moab, après qu''il eut renvoyé ses femmes Husim et Bara.'),
('1ch',8,9,'crampon1923','Il eut de Hodès, sa femme: Jobab, Sébia, Mosa, Molchom,'),
('1ch',8,10,'crampon1923','Jéhus, Séchia et Marma; ce sont là ses fils, chefs de familles.'),
('1ch',8,11,'crampon1923','Il eut de Husim: Abitob et Elphaal. —'),
('1ch',8,12,'crampon1923','Fils d''Elphaal: Héber, Misaam et Samad, qui bâtit Ono, Lod et les villes de sa dépendance.'),
('1ch',8,13,'crampon1923','Baria et Sama, chefs des familles qui habitaient Aïalon, mirent en fuite les habitants de Geth.'),
('1ch',8,14,'crampon1923','Ahio, Sésac, Jérimoth,'),
('1ch',8,15,'crampon1923','Zabadia, Arod, Héder,'),
('1ch',8,16,'crampon1923','Michaël, Jespha et Joha étaient fils de Baria. —'),
('1ch',8,17,'crampon1923','Zabadia, Mosollam, Hézéci, Héber,'),
('1ch',8,18,'crampon1923','Jésamari, Jezlia et Jobab étaient fils d''Elphaal. —'),
('1ch',8,19,'crampon1923','Jacim, Zéchri, Zabdi,'),
('1ch',8,20,'crampon1923','Elioénaï, Séléthaï, Eliel,'),
('1ch',8,21,'crampon1923','Adaïa, Baraïa et Samarath étaient fils de Séméï. —'),
('1ch',8,22,'crampon1923','Jesphan, Héber, Eliel,'),
('1ch',8,23,'crampon1923','Abdon, Zéchri, Hanan,'),
('1ch',8,24,'crampon1923','Hanania, Elam, Anathothia,'),
('1ch',8,25,'crampon1923','Jephdaïa et Phanuel étaient fils de Sésac. —'),
('1ch',8,26,'crampon1923','Samsari, Sohoria, Otholia,'),
('1ch',8,27,'crampon1923','Jersia, Elia et Zéchri, étaient fils de Jéroham. —'),
('1ch',8,28,'crampon1923','Ce sont là des chefs de famille, des chefs selon leurs générations; ils habitaient à Jérusalem.'),
('1ch',8,29,'crampon1923','Le père de Gabaon habitait à Gabaon, et le nom de sa femme était Maacha.'),
('1ch',8,30,'crampon1923','Son fils premier-né, Abdon, puis Sur, Cis, Baal, Nadab,'),
('1ch',8,31,'crampon1923','Gédor, Ahio et Zacher.'),
('1ch',8,32,'crampon1923','Macelloth engendra Samaa. Ils habitèrent aussi près de leurs frères à Jérusalem, avec leurs frères. —'),
('1ch',8,33,'crampon1923','Ner engendra Cis; Cis engendra Saül; Saül engendra Jonathan, Melchisua, Abinadab et Esbaal. —'),
('1ch',8,34,'crampon1923','Fils de Jonathan: Méribbaal; Méribbaal engendra Micha. —'),
('1ch',8,35,'crampon1923','Fils de Micha: Phiton, Mélech, Tharaa et Achaz.'),
('1ch',8,36,'crampon1923','Achaz engendra Joada; Joada engendra Alamath, Azmoth et Zamri; Zamri engendra Mosa.'),
('1ch',8,37,'crampon1923','Mosa engendra Banaa; Rapha, son fils; Elasa, son fils; Asel, son fils.'),
('1ch',8,38,'crampon1923','Asel eut six fils, dont voici les noms: Ezricam, Bocru, Ismaël, Saria, Obdia et Hanan: tous ceux-là étaient fils d''Asel. —'),
('1ch',8,39,'crampon1923','Fils d''Esec, son frère: Ulam, son premier-né, Jéhus le deuxième, et Eliphalet le troisième.'),
('1ch',8,40,'crampon1923','Les fils d''Ulam furent de vaillants hommes, tirant de l''arc, et ils eurent beaucoup de fils, et de petits-fils, cent cinquante. Tous ceux-là sont des fils de Benjamin.'),
('1ch',9,1,'crampon1923','Ainsi tout Israël fut enregistré dans les généalogies, et voici qu''ils sont inscrits dans le livre des rois d''Israël; et Juda fut emmené captif à Babylone à cause de ses transgressions.'),
('1ch',9,2,'crampon1923','Les premiers habitants, qui demeuraient dans leurs possessions, dans leurs villes, furent les Israélites, les prêtres, les lévites et les Nathinéens.'),
('1ch',9,3,'crampon1923','A Jérusalem, habitèrent des fils de Juda, des fils de Benjamin, et des fils d''Ephraïm et de Manassé; —'),
('1ch',9,4,'crampon1923','des fils au Pharès, fils de Juda: Othéï, fils d''Ammiud, fils d''Amri, fils d''Omraï, fils de Bonni; —'),
('1ch',9,5,'crampon1923','des Silonites: Asaïa, le premier-né, et ses fils; —'),
('1ch',9,6,'crampon1923','des fils de Zara: Jéhuel; et leurs frères: six cent quatre vingt dix; —'),
('1ch',9,7,'crampon1923','Des fils de Benjamin: Salo, fils de Mosollam, fils d''Oduia, fils d''Asana;'),
('1ch',9,8,'crampon1923','Jobania, fils de Jéroham; Ela, fils d''Ozi, fils de Mochori; Mosollam, fils de Saphatia, fils de Rahuel, fils de Jébania;'),
('1ch',9,9,'crampon1923','et leurs frères, selon leurs générations: neuf cent cinquante-six. Tous ces hommes étaient chefs de famille selon leurs maisons patriarcales.'),
('1ch',9,10,'crampon1923','Des prêtres: Jédaïa, Joïarib, Jachim,'),
('1ch',9,11,'crampon1923','Azarias, fils d''Helcias, fils de Mosollam, fils de Sadoc, fils de Maraïoth, fils d''Achitob, prince de la maison de Dieu;'),
('1ch',9,12,'crampon1923','Adaïas, fils de Jéroham, fils de Phassur, fils de Melchias; Maasaï, fils d''Adiel, fils de Jezra, fils de Mosollam, fils de Mosollamith, fils d''Emmer;'),
('1ch',9,13,'crampon1923','et leurs frères, chefs de leurs maisons patriarcales: mille sept cent soixante hommes vaillants, pour l''œuvre du service de la maison de Dieu.'),
('1ch',9,14,'crampon1923','Des lévites: Séméïa, fils de Hassub, fils d''Ezricam, fils d''Hasébia, des fils de Mérari;'),
('1ch',9,15,'crampon1923','Bacbacar, Hérès, Galal, Matthania, fils de Micha, fils de Zéchri, fils d''Asaph;'),
('1ch',9,16,'crampon1923','Obdia, fils de Séméïa, fils de Galal, fils d''Idithun; Barachia, fils d''Asa, fils d''Elcana, qui habitait dans les villages de Nétophatiens.'),
('1ch',9,17,'crampon1923','Et les portiers: Sellum, Accub, Telmon, Ahiman, et leurs frères; Sellum était le chef,'),
('1ch',9,18,'crampon1923','et il est jusqu''à présent à la porte du roi, à l''orient. Ce sont là les portiers pour le camp des enfants de Lévi.'),
('1ch',9,19,'crampon1923','Sellum, fils de Coré, fils d''Abiasaph, fils de Coré, et ses frères de la maison de son père, les Coréïtes, remplissaient les fonctions de gardiens des portes du tabernacle; leurs pères avaient gardé l''entrée du camp de Yahweh;'),
('1ch',9,20,'crampon1923','Phinées, fils d''Eléazar, avait été autrefois leur chef, et Yahweh était avec lui.'),
('1ch',9,21,'crampon1923','Zacharie, fils de Mosollamia, était portier à l''entrée de la tente de réunion.'),
('1ch',9,22,'crampon1923','Tous ces hommes, choisis pour gardiens des portes, étaient au nombre de deux cent douze, enregistrés dans les généalogies de leurs villages; David et Samuel le voyant les avaient établis dans leurs fonctions.'),
('1ch',9,23,'crampon1923','Eux et leurs enfants étaient aux portes de la maison de Yahweh, de la maison du tabernacle, pour les gardes.'),
('1ch',9,24,'crampon1923','Les portiers se tenaient aux quatre vents, à l''orient, à l''occident, au nord et au midi.'),
('1ch',9,25,'crampon1923','Leurs frères, qui demeuraient dans leurs villages, devaient venir auprès d''eux de temps à autre, pour une semaine.'),
('1ch',9,26,'crampon1923','Car ces quatre chefs des portiers, qui étaient lévites, étaient constamment en fonctions, et ils avaient encore la surveillance des chambres et des trésors, à la maison de Dieu.'),
('1ch',9,27,'crampon1923','Ils logeaient autour de la maison de Dieu, dont ils avaient la garde, et ils devaient pourvoir à l''ouverture, chaque matin.'),
('1ch',9,28,'crampon1923','Quelques-uns des lévites avaient la surveillance des ustensiles du service, qu''ils rentraient et sortaient en les comptant.'),
('1ch',9,29,'crampon1923','D''autres veillaient sur les ustensiles, sur tous les ustensiles du sanctuaire, et sur la fleur de farine, le vin, l''huile, l''encens et les aromates.'),
('1ch',9,30,'crampon1923','Des fils de prêtres composaient les parfums aromatiques.'),
('1ch',9,31,'crampon1923','Un des lévites, Mathathias, premier-né le Sellum de Coréïte, avait le soin des gâteaux cuits sur la poêle.'),
('1ch',9,32,'crampon1923','Et quelques-uns de leurs frères d''entre les fils des Caathites, étaient chargés de préparer pour chaque sabbat les pains de proposition.'),
('1ch',9,33,'crampon1923','Ce sont là les chantres, chefs de famille des lévites, demeurant dans les chambres, exempts d''autres fonctions, parce qu''ils étaient à leur œuvre jour et nuit.'),
('1ch',9,34,'crampon1923','Ce sont là les chefs de famille des lévites, chefs selon leurs générations; ils habitaient à Jérusalem.'),
('1ch',9,35,'crampon1923','Le père de Gabaon, Jéhiel, habitait à Gabaon, et le nom de sa femme était Maacha.'),
('1ch',9,36,'crampon1923','Abdon, son fils premier-né, puis Sur, Cis, Baal, Ner, Nadab,'),
('1ch',9,37,'crampon1923','Gédor, Ahio, Zacharie et Macelloth.'),
('1ch',9,38,'crampon1923','Macelloth engendra Samaan. Eux aussi habitaient prés de leurs frères à Jérusalem, avec leurs frères. —'),
('1ch',9,39,'crampon1923','Ner engendra Cis; Cis engendra Saül; Saül engendra Jonathan, Melchisua, Abinadab et Esbaal. —'),
('1ch',9,40,'crampon1923','Fils de Jonathan: Méribbaal. Méribbaal engendra Micha. —'),
('1ch',9,41,'crampon1923','Fils de Micha: Phithon, Mélech, Tharaa.'),
('1ch',9,42,'crampon1923','Ahaz engendra Jara; Jara engendra Alamath, Azmoth et Zamri; Zamri engendra Mosa.'),
('1ch',9,43,'crampon1923','Mosa engendra Banaa. Raphaïa, son fils; Elasa, son fils; Asel, son fils.'),
('1ch',9,44,'crampon1923','Asel eut six fils, dont voici les noms: Ezricam, Bocru, Ismaël, Saria, Obdia et Hanan. Ce sont là les Fils d''Asel.'),
('1ch',10,1,'crampon1923','Les Philistins ayant livré bataille à Israël, les hommes d''Israël prirent la fuite devant les Philistins, et tombèrent blessés à mort sur la montagne de Gelboé.'),
('1ch',10,2,'crampon1923','Les Philistins s''attachèrent à poursuivre Saül et ses fils, et les Philistins tuèrent Jonathas, Abinadab et Melchisua, fils de Saül.'),
('1ch',10,3,'crampon1923','L''effort du combat se porta sur Saül; les archers l''ayant découvert, il eut grandement peur des archers.'),
('1ch',10,4,'crampon1923','Alors Saül dit à son écuyer: " Tire ton épée et m''en transperce, de peur que ces incirconcis ne viennent m''outrager. " L''écuyer ne le voulut pas faire, car il était saisi de crainte; alors Saül prit son épée et se jeta dessus.'),
('1ch',10,5,'crampon1923','L''écuyer, voyant que Saül était mort, se jeta aussi sur son épée, et mourut.'),
('1ch',10,6,'crampon1923','Ainsi périrent Saül et ses trois fils, et toute sa maison périt en même temps.'),
('1ch',10,7,'crampon1923','Tous les hommes d''Israël qui étaient dans la plaine, voyant que les enfants d''Israël s''étaient enfuis, et que Saül et ses fils étaient morts, abandonnèrent leurs villes et prirent aussi la fuite; et les Philistins vinrent et s''y établirent.'),
('1ch',10,8,'crampon1923','Le lendemain, les Philistins vinrent pour dépouiller les morts, et ils trouvèrent Saül et ses fils gisant sur la montagne de Gelboé.'),
('1ch',10,9,'crampon1923','L''ayant dépouillé, ils emportèrent sa tête et ses armes; puis ils envoyèrent publier cette bonne nouvelle par tout le pays des Philistins, devant leurs idoles et le peuple.'),
('1ch',10,10,'crampon1923','Ils mirent les armes de Saül dans la maison de leur dieu, et ils attachèrent son crâne dans le temple de Dagon.'),
('1ch',10,11,'crampon1923','Tout Jabès en Galaad ayant appris tout ce que les Philistins avaient fait à Saül,'),
('1ch',10,12,'crampon1923','tous les vaillants hommes se levèrent, prirent le corps de Saül et les corps de ses fils, et les transportèrent à Jabès. Ils enterrèrent leurs os sous le térébinthe, à Jabès, et ils jeûnèrent sept jours.'),
('1ch',10,13,'crampon1923','Saül mourut à cause de la transgression dont il s''était rendu coupable envers Yahweh, parce qu''il n''avait pas observé la parole de Yahweh, et pour avoir interrogé et consulté ceux qui évoquent les morts.'),
('1ch',10,14,'crampon1923','Il ne consulta point Yahweh, et Yahweh le fit mourir, et il transféra la royauté à David, fils d''Isaï.'),
('1ch',11,1,'crampon1923','Tout Israël s''assembla auprès de David à Hébron, en disant: " Voici que nous sommes tes os et ta chair.'),
('1ch',11,2,'crampon1923','Autrefois déjà, quand Saül était roi, c''était toi qui menais et ramenais Israël. Et Yahweh, ton Dieu, t''a dit: C''est toi qui paîtras mon peuple d''Israël, et c''est toi qui seras chef sur mon peuple d''Israël. "'),
('1ch',11,3,'crampon1923','Ainsi tous les anciens d''Israël vinrent auprès du roi à Hébron, et David fit alliance avec eux devant Yahweh, à Hébron; et ils oignirent David pour roi sur Israël, selon la parole de Yahweh prononcée par Samuel.'),
('1ch',11,4,'crampon1923','David marcha avec tout Israël contre Jérusalem, qui est Jébus; là étaient les Jébuséens, habitants du pays.'),
('1ch',11,5,'crampon1923','Les habitants de Jébus dirent à David: " Tu n''entreras pas ici. " Mais David s''empara de la forteresse de Sion: c''est la cité de David.'),
('1ch',11,6,'crampon1923','David dit: " Quiconque battra le premier les Jébuséens sera chef et prince. " Joab, fils de Sarvia, monta le premier, et il devint chef.'),
('1ch',11,7,'crampon1923','David s''établit dans la forteresse; c''est pourquoi on l''appela cité de David.'),
('1ch',11,8,'crampon1923','Il bâtit la ville tout autour, à partir du Mello et aux environs, et Joab répara le reste de la ville.'),
('1ch',11,9,'crampon1923','David devenait de plus en plus grand, et Yahweh des armées était avec lui.'),
('1ch',11,10,'crampon1923','Voici les chefs des héros qui étaient au service de David, et qui, avec tout Israël, l''aidèrent pendant son règne, après avoir contribué à le faire roi, selon la parole de Yahweh au sujet d''Israël.'),
('1ch',11,11,'crampon1923','Voici le nombre des héros qui étaient au service de David: Jesbaam, fils de Hachamoni, chef des Trente. Il brandit sa lance sur trois cents hommes, qu''il fit périr en une seule fois.'),
('1ch',11,12,'crampon1923','Après lui, Eléazar, fils de Dodo, l''Ahohite; il était parmi les trois vaillants.'),
('1ch',11,13,'crampon1923','Il était avec David à Phes-Domim, et les Philistins s''y étaient rassemblés pour combattre. Il y avait là une pièce de terre pleine d''orge, et le peuple fuyait devant les Philistins.'),
('1ch',11,14,'crampon1923','Ils se placèrent au milieu du champ, le défendirent et battirent les Philistins; et Yahweh opéra une grande délivrance.'),
('1ch',11,15,'crampon1923','Trois d''entre les trente capitaines descendirent auprès de David sur le rocher, à la caverne d''Odollam, tandis que le camp des Philistins était dressé dans la vallée des Réphaïm.'),
('1ch',11,16,'crampon1923','David était alors dans la forteresse, et il y avait un poste de Philistins à Bethléem.'),
('1ch',11,17,'crampon1923','David eut un désir, et il dit: " Qui me fera boire de l''eau de la citerne qui est à la porte de Bethléem? "'),
('1ch',11,18,'crampon1923','Aussitôt les trois hommes, passant au travers du camp des Philistins, puisèrent de l''eau de la citerne qui est à la porte de Bethléem. Ils la prirent et l''apportèrent à David; mais David ne voulut pas la boire, et il en fit une libation à Yahweh,'),
('1ch',11,19,'crampon1923','en disant: " Que mon Dieu me garde de faire cela! Boirais-je le sang de ces hommes avec leur vie? Car c''est au péril de leur vie qu''ils l''ont apportée. " Et il ne voulut pas la boire. Voilà ce que firent ces trois braves.'),
('1ch',11,20,'crampon1923','Abisaï, frère de Joab, était chef des Trois; il brandit sa lance contre trois cents hommes et les tua, et il eut du renom parmi les trois.'),
('1ch',11,21,'crampon1923','Il était le plus considéré de la seconde triade, et il fut leur chef; mais il n''égala pas les trois premiers.'),
('1ch',11,22,'crampon1923','Banaïas, fils de Joïada, fils d''un homme vaillant et riche en exploits, de Cabséel. Il frappa les deux ariels de Moab. Il descendit et frappa le lion au milieu de la citerne un jour de neige.'),
('1ch',11,23,'crampon1923','Il frappa un Egyptien d''une stature de cinq coudées; et dans la main de l''Egyptien, il y avait une lance semblable à une ensouple de tisserand. Il descendit vers lui avec un bâton, et il arracha la lance de la main de l''Egyptien et le frappa de sa propre lance.'),
('1ch',11,24,'crampon1923','Voilà ce que fit Banaïas, fils de Joïada, et il eut du renom parmi les trois vaillants.'),
('1ch',11,25,'crampon1923','Voici qu''il était plus considéré que les trente, mais il n''égala pas les trois. David le fit membre de son conseil secret.'),
('1ch',11,26,'crampon1923','Hommes vaillants de l''armée: Asaël, frère de Joab; Elchanan, fils de Dodo, de Bethléem;'),
('1ch',11,27,'crampon1923','Sammoth, d''Arori; Hellès, de Phalon;'),
('1ch',11,28,'crampon1923','Hira, fils d''Accès, de Thécué; Abiéser, d''Anathot;'),
('1ch',11,29,'crampon1923','Sobbochaï, le Husathite; Ilaï, l''Ahohite;'),
('1ch',11,30,'crampon1923','Maharaï, de Nétopha; Héled, fils de Baana, de Nétopha;'),
('1ch',11,31,'crampon1923','Ethaï, fils de Ribaï, de Gabaa des fils de Benjamin; Banaïa, de Pharaton;'),
('1ch',11,32,'crampon1923','Huraï, des vallées de Gaas; Abiel, d''Araba; Azmaveth, de Bauram; Eliaba, de Salabon;'),
('1ch',11,33,'crampon1923','Bené-Assem, de Gézon; Jonathan, fils de Sagé, d''Arar;'),
('1ch',11,34,'crampon1923','Ahiam, fils de Sachar, d''Arar;'),
('1ch',11,35,'crampon1923','Eliphal, fils d''Ur;'),
('1ch',11,36,'crampon1923','Hépher, de Méchéra; Ahia, de Phélon;'),
('1ch',11,37,'crampon1923','Hesro, de Carmel; Naaraï fils d''Asbaï;'),
('1ch',11,38,'crampon1923','Joël frère de Nathan; Mibahar, fils d''Agaraï;'),
('1ch',11,39,'crampon1923','Sélec, l''Ammonite; Naharaï, de Béroth, écuyer de Joab, fils de Sarvia;'),
('1ch',11,40,'crampon1923','Ira, de Jéther; Gareb, de Jéther;'),
('1ch',11,41,'crampon1923','Urie, le Hethéen; Zabad, fils d''Oholi;'),
('1ch',11,42,'crampon1923','Adina, fils de Siza le Rubénite, chef des Rubénites, et trente avec lui;'),
('1ch',11,43,'crampon1923','Hanan, fils de Maacha; Josaphat, de Mathan;'),
('1ch',11,44,'crampon1923','Ozia, d''Astaroth; Samma et Jéhiel, fils de Hotham d''Aroër;'),
('1ch',11,45,'crampon1923','Jédihel, fils de Samri; Joha, son frère, le Thosaïte;'),
('1ch',11,46,'crampon1923','Eliel, de Mahum; Jéribaï et Josaïa, fils d''Elnaëm; Jethma, le Moabite; (47 Vulgate) Eliel, Obed et Jasiel, de Masobia.'),
('1ch',11,47,'crampon1923',''),
('1ch',12,1,'crampon1923','Voici ceux qui vinrent vers David à Siceleg, lorsqu''il devait encore se tenir éloigné de la face de Saül, fils de Cis; ils étaient parmi les vaillants qui le secoururent pendant la guerre.'),
('1ch',12,2,'crampon1923','C''étaient des archers, exercés à lancer des pierres de la main droite et de la main gauche, et à tirer des flèches avec leur arc; ils étaient d''entre les frères de Saül, de Benjamin.'),
('1ch',12,3,'crampon1923','A leur tête Ahiéser, puis Joas, tous deux fils de Samaa, de Gabaa; Jaziel et Phallet, fils d''Azmoth; Baracha; Jéhu, d''Anatoth;'),
('1ch',12,4,'crampon1923','Samaïas, de Gabaon, vaillant parmi les Trente et chef des Trente; Jérémie; Jéhéziel; Johanan; Jézabad, de Gédéra;'),
('1ch',12,5,'crampon1923','Eluzaï; Jérimuth; Baalia; Samaria; Saphatia, de Haruph;'),
('1ch',12,6,'crampon1923','Elcana, Jésia, Azaréel, Joéser et Jesbaam, fils de Coré;'),
('1ch',12,7,'crampon1923','Joéla et Zabadia, fils de Jéroham, de Gédor.'),
('1ch',12,8,'crampon1923','Parmi les Gadites, des hommes vaillants passèrent auprès de David, dans les lieux forts, au désert: guerriers exercés au combat, sachant manier le bouclier et la lance, ayant un aspect de lions, aussi agiles que des gazelles sur les montagnes.'),
('1ch',12,9,'crampon1923','Ezer était le chef; Obdias, le second; Eliab, le troisième;'),
('1ch',12,10,'crampon1923','Masmana, le quatrième; Jérémie, le cinquième;'),
('1ch',12,11,'crampon1923','Ethi, le sixième; Eliel, le septième;'),
('1ch',12,12,'crampon1923','Johanan, le huitième; Elzébad, le neuvième;'),
('1ch',12,13,'crampon1923','Jérémie, le dixième; Machbanaï, le onzième.'),
('1ch',12,14,'crampon1923','C''étaient des fils de Gad, chefs de l''armée; un seul, le plus petit, pouvait l''emporter sur cent, et le plus grand sur mille.'),
('1ch',12,15,'crampon1923','Ce sont eux qui passèrent le Jourdain au premier mois, alors qu''il déborde sur toutes ses rives, et qui mirent en fuite tous les habitants des vallées, à l''orient et à l''occident.'),
('1ch',12,16,'crampon1923','Des fils de Benjamin et de Juda vinrent vers David, dans les lieux forts.'),
('1ch',12,17,'crampon1923','David sortit au-devant d''eux, prit la parole, et leur dit: " Si vous êtes venus à moi avec des sentiments pacifiques, pour me secourir, mon cœur se portera vers vous, en vue de nous unir; mais si c''est pour me livrer perfidement à mes ennemis, lorsque aucune violence ne s''attache à mes mains, que le Dieu de nos pères le voie et qu''il fasse justice! "'),
('1ch',12,18,'crampon1923','L''Esprit revêtit Amasaï, chef des Trente, et il dit: " A toi, David, et avec toi, fils d''Isaï! Paix, paix à toi, et paix à celui qui te secourt, car ton Dieu t''a secouru! " Et David les accueillit et les plaça parmi les chefs de la bande.'),
('1ch',12,19,'crampon1923','Des hommes de Manassé se joignirent à David, lorsqu''il alla avec les Philistins faire la guerre à Saül. Mais ils ne secoururent pas les Philistins; car les princes des Philistins renvoyèrent à dessein David en disant: " Au péril de nos têtes, il joindrait son maître Saül. "'),
('1ch',12,20,'crampon1923','Comme il revenait à Siceleg, des hommes de Manassé se joignirent à lui: Ednas, Jozabad, Jédihel, Michaël, Jozabad, Eliu et Salathi, chefs des milliers de Manassé.'),
('1ch',12,21,'crampon1923','Ils secoururent David contre les bandes, car ils étaient tous des vaillants, et ils furent chefs dans l''armée.'),
('1ch',12,22,'crampon1923','Et de jour en jour des hommes arrivaient auprès de David pour le secourir, jusqu''à ce qu''il eût une grande armée, comme une armée de Dieu.'),
('1ch',12,23,'crampon1923','Voici le nombre des chefs des hommes armés pour la guerre qui vinrent auprès de David à Hébron, pour lui transférer la royauté de Saül, selon l''ordre de Yahweh.'),
('1ch',12,24,'crampon1923','Fils de Juda, portant le bouclier et la lance, six mille huit cents, armés pour la guerre. —'),
('1ch',12,25,'crampon1923','Des fils de Siméon, hommes vaillants à la guerre, sept mille cent. —'),
('1ch',12,26,'crampon1923','Des fils de Lévi, quatre mille six cents;'),
('1ch',12,27,'crampon1923','et Joïada, chef de la famille d''Aaron, et avec lui trois mille sept cents;'),
('1ch',12,28,'crampon1923','et Sadoc, jeune homme vaillant, et la maison de son père, vingt-deux chefs. —'),
('1ch',12,29,'crampon1923','Des fils de Benjamin, frères de Saül, trois mille; car jusqu''alors la plus grande partie d''entre eux gardaient fidélité à la maison de Saül. —'),
('1ch',12,30,'crampon1923','Des fils d''Ephraïm, vingt mille huit cents, hommes vaillants et renommés dans les maisons de leurs pères. —'),
('1ch',12,31,'crampon1923','De la demi-tribu de Manassé, dix-huit mille, qui furent nominativement désignés pour aller établir David roi. —'),
('1ch',12,32,'crampon1923','Des fils d''Issachar, ayant l''intelligence des temps pour savoir ce que devait faire Israël, deux cents chefs, et tous leurs frères sous leurs ordres. —'),
('1ch',12,33,'crampon1923','De Zabulon, cinquante mille, en état d''aller à l''armée, prêts à la guerre et en parfait équipement de guerre, pour se ranger en bataille d''un cœur résolu. —'),
('1ch',12,34,'crampon1923','De Nephthali, mille chefs, et avec eux trente-sept mille, portant le bouclier et la lance. —'),
('1ch',12,35,'crampon1923','Des Danites prêts à la guerre, vingt-huit mille six cents. —'),
('1ch',12,36,'crampon1923','D''Aser, en état d''aller à l''armée et prêts à la guerre, quarante mille. —'),
('1ch',12,37,'crampon1923','Et de l''autre coté du Jourdain, des Rubenites, des Gadites et de la demi-tribu de Manassé, en parfait équipement d''armes de guerre, cent vingt mille.'),
('1ch',12,38,'crampon1923','Tous ces hommes de guerre, sachant se ranger en bataille, vinrent d''un cœur sincère à Hébron pour établir David roi sur tout Israël; et tout le reste d''Israël n''avait également qu''un cœur pour établir David roi.'),
('1ch',12,39,'crampon1923','Ils furent là trois jours avec David, mangeant et buvant, car leurs frères leur avaient préparé des provisions.'),
('1ch',12,40,'crampon1923','Et même ceux qui habitaient près d''eux, jusqu''à Issachar, à Zabulon et à Nephthali, apportaient des vivres sur des ânes, sur des chameaux, sur des mulets et sur des bœufs, des provisions de farine, des masses de figues sèches et des raisins secs, du vin, de l''huile, des bœufs et des brebis en abondance; car il y avait joie en Israël.'),
('1ch',12,41,'crampon1923',''),
('1ch',13,1,'crampon1923','David tint conseil avec les chefs de milliers et de centaines, avec tous les princes.'),
('1ch',13,2,'crampon1923','Et David dit à toute l''assemblée d''Israël: " Si vous le trouvez bon et si cela paraît venir de Yahweh, notre Dieu, envoyons au plus vite vers le reste de nos frères, dans toutes les contrées d''Israël, et aussi vers les prêtres et les lévites dans les villes où sont leurs pâturages, afin qu''ils se réunissent à nous,'),
('1ch',13,3,'crampon1923','et que nous ramenions auprès de nous l''arche de notre Dieu, car nous ne nous en sommes pas occupés dans les jours de Saül. "'),
('1ch',13,4,'crampon1923','Toute l''assemblée dit de faire ainsi, la chose ayant paru convenable aux yeux de tout le peuple.'),
('1ch',13,5,'crampon1923','David assembla donc tout Israël, depuis le Sihor d''Egypte jusqu''à l''entrée d''Emath, pour faire venir de Cariathiarim l''arche de Dieu.'),
('1ch',13,6,'crampon1923','Et David, avec tout Israël, monta à Baala, à Cariathiarim, qui est à Juda, pour faire monter de là l''arche de Dieu, de Yahweh qui siège sur les Chérubins, sur laquelle le Nom est invoqué.'),
('1ch',13,7,'crampon1923','Ils placèrent sur un chariot neuf l''arche de Dieu, et l''emmenèrent de la maison d''Abinadab: Oza et Ahio conduisaient le chariot.'),
('1ch',13,8,'crampon1923','David et tout Israël dansaient devant Dieu de toute leur force, en chantant, et en jouant des harpes, des luths, des tambourins, des cymbales et des trompettes.'),
('1ch',13,9,'crampon1923','Lorsqu''ils furent arrivés à l''aire de Chidon, Oza étendit la main pour saisir l''arche, parce que les bœufs avaient fait un faux pas.'),
('1ch',13,10,'crampon1923','La colère de Yahweh s''enflamma contre Oza, et Yahweh le frappa, parce qu''il avait étendu la main sur l''arche; et Oza mourut là, devant Dieu.'),
('1ch',13,11,'crampon1923','David fut fâché de ce que Yahweh avait ainsi porté un coup à Oza; et ce lieu a été appelé jusqu''à ce jour Phéréts-Oza.'),
('1ch',13,12,'crampon1923','David eut peur de Dieu en ce jour-là, et il dit: " Comment ferais-je venir vers moi l''arche de Dieu? "'),
('1ch',13,13,'crampon1923','David ne retira pas l''arche chez lui, dans la cité de David, et il la fit conduire dans la maison d''Obédédom de Geth.'),
('1ch',13,14,'crampon1923','L''arche de Dieu resta trois mois avec la famille d''Obédédom, dans sa maison; et Yahweh bénit la maison d''Obédédom et tout ce qui lui appartenait.'),
('1ch',14,1,'crampon1923','Hiram, roi de Tyr, envoya des messagers à David, avec du bois de cèdre, ainsi que des tailleurs de pierres et des charpentiers, pour lui bâtir une maison.'),
('1ch',14,2,'crampon1923','Et David reconnut que Yahweh l''affermissait comme roi sur Israël, car son royaume était haut élevé, à cause de son peuple d''Israël.'),
('1ch',14,3,'crampon1923','David prit encore des femmes à Jérusalem et il engendra encore des fils et des filles.'),
('1ch',14,4,'crampon1923','Voici les noms des enfants qu''il eut à Jérusalem: Samua, Sobad, Nathan, Salomon,'),
('1ch',14,5,'crampon1923','Jébahar, Elisua, Eliphalet,'),
('1ch',14,6,'crampon1923','Noga, Népheg, Japhia,'),
('1ch',14,7,'crampon1923','Elisama, Baaiada et Eliphalet.'),
('1ch',14,8,'crampon1923','Les Philistins apprirent que David avait été oint pour roi sur tout Israël; alors tous les Philistins montèrent pour rechercher David. David l''apprit, et il sortit au-devant d''eux.'),
('1ch',14,9,'crampon1923','Les Philistins, étant venus, se précipitèrent dans la vallée des Rephaïm.'),
('1ch',14,10,'crampon1923','David consulta Dieu, en disant: " Monterai-je contre les Philistins? Les livrerez-vous entre mes mains? " Et Yahweh lui dit: " Monte, et je les livrerai entre tes mains. "'),
('1ch',14,11,'crampon1923','Ils montèrent à Baal-Pharasim, et là David les battit. Et David dit: " Dieu a brisé mes ennemis par ma main, comme les eaux brisent les digues. " C''est pourquoi on a donné à ce lieu le nom de Baal-Pharasim.'),
('1ch',14,12,'crampon1923','Ils laissèrent là leurs dieux. Et David dit qu''on les livre au feu.'),
('1ch',14,13,'crampon1923','Les Philistins se précipitèrent de nouveau dans la vallée.'),
('1ch',14,14,'crampon1923','David consulta encore Dieu, et Dieu lui dit: " Ne monte pas après eux; détourne-toi d''eux, et tu arriveras sur eux du coté des balsamiers.'),
('1ch',14,15,'crampon1923','Quand tu entendras un bruit de pas dans les cimes des balsamiers, alors tu sortiras pour combattre, car Dieu sortira devant toi pour battre l''armée des Philistins. "'),
('1ch',14,16,'crampon1923','David fit comme Dieu le lui ordonnait, et ils battirent l''armée des Philistins depuis Gabaon jusqu''à Gazer.'),
('1ch',14,17,'crampon1923','La renommée de David se répandit dans tous les pays, et Yahweh le fit craindre à toutes les nations.'),
('1ch',15,1,'crampon1923','Il se fit des maisons dans la cité de David, et il prépara une place à l''arche de Dieu, et dressa pour elle une tente.'),
('1ch',15,2,'crampon1923','Alors David dit: " Il n''y a pour porter l''arche de Dieu que les lévites; car ce sont eux que Yahweh a choisis pour porter l''arche de Dieu et pour en faire le service à jamais. "'),
('1ch',15,3,'crampon1923','David assembla tout Israël à Jérusalem, pour faire monter l''arche de Yahweh à sa place, qu''il lui avait préparée.'),
('1ch',15,4,'crampon1923','David réunit les fils d''Aaron et les lévites:'),
('1ch',15,5,'crampon1923','des fils de Caath, Uriel le chef et ses frères, cent vingt;'),
('1ch',15,6,'crampon1923','des fils de Mérari, Asaïa le chef et ses frères, deux cent vingt;'),
('1ch',15,7,'crampon1923','des fils de Gersom, Joël le chef et ses frères, cent trente;'),
('1ch',15,8,'crampon1923','des fils d''Elisaphan, Séméïas le chef et ses frères, deux cents;'),
('1ch',15,9,'crampon1923','des fils d''Hébron, Eliel le chef et ses frères, quatre-vingts;'),
('1ch',15,10,'crampon1923','des fils d''Oziel, Aminadab le chef et ses frères, cent douze.'),
('1ch',15,11,'crampon1923','David appela les prêtres Sadoc et Abiathar, et les lévites Uriel, Asaïas, Joël, Séméïas, Eliel et Aminadab,'),
('1ch',15,12,'crampon1923','et il leur dit: " Vous êtes les chefs de famille des lévites; sanctifiez-vous, vous et vos frères, et faites monter l''arche de Yahweh, Dieu d''Israël, là où je lui ai préparé un séjour.'),
('1ch',15,13,'crampon1923','Parce que ce ne fut pas vous, la première fois, Yahweh, notre Dieu, nous a frappés; car nous ne l''avions pas cherché selon la loi. "'),
('1ch',15,14,'crampon1923','Les prêtres et les lévites se sanctifièrent pour faire monter l''arche de Yahweh, Dieu d''Israël.'),
('1ch',15,15,'crampon1923','Et les fils de Lévi, comme l''avait ordonné Moïse d''après la parole de Yahweh, portèrent l''arche de Dieu sur leurs épaules avec les barres.'),
('1ch',15,16,'crampon1923','David dit aux chefs des lévites d''établir leurs frères les chantres avec des instruments de musique, des cithares, des harpes et des cymbales, pour faire retentir des sons éclatants et joyeux.'),
('1ch',15,17,'crampon1923','Les lévites établirent Héman, fils de Joël, et, parmi ses frères, Asaph, fils de Barachias; parmi les fils de Mérari, leurs frères, Ethan, fils de Cusaïa;'),
('1ch',15,18,'crampon1923','et, avec eux, leurs frères du second ordre, Zacharie, Ben, Jaziel, Sémiramoth, Jahiel, Ani, Eliab, Banaïas, Maasias, Mathathias, Eliphalu, Macénias, Obédédom et Jéhiel, les portiers.'),
('1ch',15,19,'crampon1923','Les chantres Héman, Asaph et Ethan avaient des cymbales d''airain pour les faire retentir.'),
('1ch',15,20,'crampon1923','Zacharie, Oziel, Sémiramoth, Jahiel, Ani, Eliab, Maasias et Banaaïs avaient des cithares en alamoth.'),
('1ch',15,21,'crampon1923','Mathathias, Eliphalu, Macénias, Obédédom, Jéhiel et Ozaziu avaient des harpes à l''octave inférieure, pour présider au chant.'),
('1ch',15,22,'crampon1923','Chonénias, chef des lévites pour le transport, dirigeait le transport, car il s''y entendait.'),
('1ch',15,23,'crampon1923','Barachias et Elcana étaient portiers auprès de l''arche.'),
('1ch',15,24,'crampon1923','Sébénias, Josaphat, Nathanaël, Amasaï, Zacharie, Banaïas et Eliézer, les prêtres, sonnaient de la trompette devant l''arche de Dieu. Obédédom et Jéhias étaient portiers auprès de l''arche.'),
('1ch',15,25,'crampon1923','David, les anciens d''Israël et les chefs de milliers se mirent en route pour faire monter l''arche de l''alliance de Yahweh depuis la Maison d''Obédédom, au milieu de la joie.'),
('1ch',15,26,'crampon1923','Lorsque Dieu eut prêté son assistance aux lévites qui portaient l''arche de l''alliance de Yahweh, on immola six taureaux et six béliers.'),
('1ch',15,27,'crampon1923','David était couvert d''un manteau de byssus, ainsi que tous les lévites qui portaient l''arche, les chantres et Chonénias, qui dirigeait le transport de l''arche, parmi les chantres; et David avait sur lui un éphod de lin.'),
('1ch',15,28,'crampon1923','Tout Israël fit monter l''arche de l''alliance de Yahweh avec des cris de joie, au son de la trompette, des clairons et des cymbales, et en faisant retentir les cithares et les harpes.'),
('1ch',15,29,'crampon1923','Lorsque l''arche de l''alliance de Yahweh fut arrivée jusqu''à la cité de David, Michol, fille de Saül, regarda par la fenêtre et voyant le roi David bondir et danser, elle le méprisa dans son cœur.'),
('1ch',16,1,'crampon1923','Après qu''on eut fait entrer l''arche de Dieu, et qu''on l''eut déposée au milieu de la tente que David avait dressée pour elle, on offrit devant Dieu des holocaustes et des sacrifices pacifiques.'),
('1ch',16,2,'crampon1923','Quand David eut achevé d''offrir les holocaustes et les sacrifices pacifiques, il bénit le peuple au nom de Yahweh.'),
('1ch',16,3,'crampon1923','Puis il distribua à tous ceux d''Israël, hommes et femmes, à chacun un pain, une portion de viande et un gâteau de raisins.'),
('1ch',16,4,'crampon1923','Il établit devant l''arche de Yahweh des lévites pour faire le service, en invoquant, en célébrant et en louant Yahweh, le Dieu d''Israël.'),
('1ch',16,5,'crampon1923','C''étaient: Asaph, le chef; Zacharie, le second; puis Jahiel, Sémiramoth, Jéhiel, Mathathias, Eliab, Banaïas, Obédédom et Jéhiel, avec des cithares et des harpes pour instruments; et Asaph faisait retentir les cymbales;'),
('1ch',16,6,'crampon1923','les prêtres Banaïas et Jaziel sonnaient continuellement de la trompette devant l''arche de l''alliance de Dieu.'),
('1ch',16,7,'crampon1923','Ce fut en ce jour que David établit pour la première fois qu''on célébrerait Yahweh par l''organe d''Asaph et de ses frères:'),
('1ch',16,8,'crampon1923','Louez Yahweh, invoquez son nom, faites connaître ses œuvres parmi les peuples.'),
('1ch',16,9,'crampon1923','Chantez en son honneur, chantez des psaumes en son honneur, racontez toutes ses merveilles.'),
('1ch',16,10,'crampon1923','Glorifiez-vous dans son saint nom; que se réjouisse le cœur de ceux qui cherchent Yahweh!'),
('1ch',16,11,'crampon1923','Recherchez Yahweh et sa force; cherchez continuellement sa face.'),
('1ch',16,12,'crampon1923','Souvenez-vous des prodiges qu''il a faits, de ses miracles et des jugements de sa bouche,'),
('1ch',16,13,'crampon1923','race d''Israël, son serviteur, enfants de Jacob, ses élus.'),
('1ch',16,14,'crampon1923','Lui, Yahweh, est notre Dieu; ses jugements s''exercent sur toute la terre.'),
('1ch',16,15,'crampon1923','Souvenez-vous à jamais de son alliance. — la parole qu''il a dite pour mille générations.'),
('1ch',16,16,'crampon1923','De l''alliance qu''il a conclue avec Abraham, et de son serment à Isaac,'),
('1ch',16,17,'crampon1923','qu''il a érigé pour Jacob en loi, pour Israël en alliance éternelle,'),
('1ch',16,18,'crampon1923','disant: " A toi je donnerai le pays de Chanaan, comme la part de votre héritage. "'),
('1ch',16,19,'crampon1923','Alors que vous étiez faciles à compter, en petit nombre et étrangers dans le pays,'),
('1ch',16,20,'crampon1923','qu''ils erraient d''une nation à l''autre, et d''un royaume vers un autre peuple,'),
('1ch',16,21,'crampon1923','Il ne permit à personne de les opprimer, et il châtia des rois à cause d''eux;'),
('1ch',16,22,'crampon1923','" Ne touchez pas à mes oints, et ne faites pas de mal à mes prophètes! "'),
('1ch',16,23,'crampon1923','Chantez à Yahweh, habitants de toute la terre; annoncez de jour en jour son salut.'),
('1ch',16,24,'crampon1923','Racontez parmi les nations sa gloire, parmi tous les peuples ses merveilles.'),
('1ch',16,25,'crampon1923','Car Yahweh est grand et très digne de louange, il est redoutable par-dessus tous les dieux;'),
('1ch',16,26,'crampon1923','car tous les dieux des peuples sont des idoles. Et Yahweh a fait les cieux;'),
('1ch',16,27,'crampon1923','la majesté et la splendeur sont devant sa face; la force et la joie sont dans sa demeure.'),
('1ch',16,28,'crampon1923','Rendez à Yahweh, familles des peuples, rendez à Yahweh gloire et puissance,'),
('1ch',16,29,'crampon1923','rendez à Yahweh gloire pour son nom. Apportez des offrandes et venez en sa présence; adorez Yahweh dans de saints ornements,'),
('1ch',16,30,'crampon1923','tremblez devant lui, habitants de toute la terre. Et le monde affermi ne chancellera point.'),
('1ch',16,31,'crampon1923','Que les cieux se réjouissent et que la terre soit dans l''allégresse! Qu''on dise parmi les nations: " Yahweh est roi! "'),
('1ch',16,32,'crampon1923','Que la mer retentisse avec ce qu''elle contient! Que les champs tressaillent avec tout ce qu''ils renferment!'),
('1ch',16,33,'crampon1923','Que les arbres de la forêt poussent des cris joyeux, devant Yahweh, car il vient pour juger la terre!'),
('1ch',16,34,'crampon1923','Célébrez Yahweh, car il est bon, car sa miséricorde dure à jamais.'),
('1ch',16,35,'crampon1923','Dites: " Sauve-nous, Dieu de notre salut; rassemble-nous et retire-nous du milieu des nations, afin que nous célébrions ton saint nom, et que nous mettions notre gloire en ta louange. "'),
('1ch',16,36,'crampon1923','Béni soit Yahweh, le Dieu d''Israël, d''éternité en éternité! Et tout le peuple dit: " Amen! " et: " Louez Yahweh. "'),
('1ch',16,37,'crampon1923','David laissa là, devant l''arche de l''alliance de Yahweh, Asaph et ses frères pour faire continuellement le service devant l''arche, selon la tâche de chaque jour;'),
('1ch',16,38,'crampon1923','de même Obédédom avec ses frères, au nombre de soixante-huit, Obédédom, fils d''Idithun, et Hosa, comme portiers;'),
('1ch',16,39,'crampon1923','de même, le prêtre Sadoc et les prêtres, ses frères, devant la Demeure de Yahweh sur le haut lieu qui était à Gabaon,'),
('1ch',16,40,'crampon1923','pour qu''ils offrissent des holocaustes à Yahweh continuellement, matin et soir, sur l''autel des holocaustes, et pour qu''ils accomplissent tout ce qui est écrit dans la loi de Yahweh qu''il a imposée à Israël.'),
('1ch',16,41,'crampon1923','Auprès d''eux étaient Héman et Idithun, et le reste de ceux qui avaient été choisis et désignés par leurs noms, pour " louer Yahweh, car sa miséricorde dure à jamais! "'),
('1ch',16,42,'crampon1923','Avec eux, savoir, avec Héman et Idithun, étaient des trompettes et des cymbales pour ceux qui devaient les faire retentir, et des instruments pour les cantiques de Dieu. Les fils d''Idithun étaient pour la porte.'),
('1ch',16,43,'crampon1923','Tout le peuple s''en alla chacun dans sa maison; et David s''en retourna pour bénir sa maison.'),
('1ch',17,1,'crampon1923','Lorsque David fut établi dans sa maison, David dit à Nathan le prophète: " Voici que j''habite dans une maison de cèdre, et l''arche de l''alliance de Yahweh est sous la tente! "'),
('1ch',17,2,'crampon1923','Nathan répondit à David: " Fais ce que tu as dans le cœur, car Dieu est avec toi. "'),
('1ch',17,3,'crampon1923','Cette nuit-là, la parole de Dieu fut adressée à Nathan en ces termes:'),
('1ch',17,4,'crampon1923','" Va dire à David, mon serviteur: Ainsi parle Yahweh: Ce n''est pas toi qui me bâtiras une maison pour que j''y habite.'),
('1ch',17,5,'crampon1923','Car je n''ai point habité dans une maison, depuis le jour où j''ai fait monter Israël d''Egypte jusqu''à ce jour; mais j''ai été de tente en tente et de demeure en demeure.'),
('1ch',17,6,'crampon1923','Pendant tout le temps que j''ai voyagé avec tout Israël, ai-je dit un mot à l''un des juges d''Israël à qui j''ai ordonné de paître mon peuple, en disant: Pourquoi ne me bâtissez-vous pas une maison de cèdre?'),
('1ch',17,7,'crampon1923','Maintenant, tu diras à mon serviteur, à David: Ainsi parle Yahweh des armées: Je t''ai pris au pâturage, derrière les brebis, pour être prince sur mon peuple d''Israël;'),
('1ch',17,8,'crampon1923','j''ai été avec toi partout où tu allais, j''ai exterminé tous tes ennemis devant toi, et je t''ai fait un nom comme le nom des grands qui sont sur la terre.'),
('1ch',17,9,'crampon1923','J''ai assigné un lieu à mon peuple d''Israël, et je l''ai planté, et il habite chez lui, et il ne sera plus troublé, et les fils d''iniquité ne l''opprimeront plus, comme autrefois'),
('1ch',17,10,'crampon1923','et comme au jour où j''avais établi des juges sur mon peuple d''Israël. J''ai humilié tous tes ennemis. Et je t''annonce que Yahweh te bâtira une maison.'),
('1ch',17,11,'crampon1923','Quand tes jours seront accomplis et que tu iras avec tes pères, j''élèverai ta postérité après toi, l''un de tes fils, et j''affermirai son règne.'),
('1ch',17,12,'crampon1923','C''est lui qui me bâtira une maison, et j''affermirai son trône pour toujours.'),
('1ch',17,13,'crampon1923','Je serai pour lui un père, et il sera pour moi un fils; et je ne lui retirerai point ma grâce, comme je l''ai retirée à celui qui a régné avant toi.'),
('1ch',17,14,'crampon1923','Je l''établirai pour toujours dans ma maison et dans mon royaume, et son trône sera affermi pour toujours. "'),
('1ch',17,15,'crampon1923','Nathan parla à David selon toutes ces paroles et toute cette vision.'),
('1ch',17,16,'crampon1923','Et le roi David vint et demeura devant Yahweh; et il dit: " Qui suis-je, Yahweh Dieu, et quelle est ma maison pour que vous m''ayez fait arriver jusque-là?'),
('1ch',17,17,'crampon1923','Et c''est encore peu de chose à vos yeux, ô Dieu! Vous avez parlé de la maison de votre serviteur pour les temps lointains, et vous m''avez regardé comme un homme de haut rang, ô Yahweh Dieu.'),
('1ch',17,18,'crampon1923','Que pourrait vous dire de plus David sur l''honneur accordé à votre serviteur? Vous connaissez votre serviteur.'),
('1ch',17,19,'crampon1923','Yahweh, c''est à cause de votre serviteur et selon votre cœur, que vous avez fait toute cette grande chose, pour faire connaître toutes ces grandes choses.'),
('1ch',17,20,'crampon1923','Yahweh, nul n''est semblable à vous, et il n''y a point d''autre Dieu que vous, d''après tout ce que nous avons entendu de nos oreilles.'),
('1ch',17,21,'crampon1923','Quelle autre nation y a-t-il sur la terre comme votre peuple d''Israël, que Dieu est venu racheter pour en faire son peuple, pour vous faire un nom par des choses grandes et des prodiges, en chassant des nations de devant votre peuple que vous avez racheté de l''Egypte?'),
('1ch',17,22,'crampon1923','Vous avez fait de votre peuple d''Israël votre peuple à jamais, et vous, Yahweh, vous êtes devenu son Dieu.'),
('1ch',17,23,'crampon1923','Maintenant, Yahweh, que la parole que vous avez dite au sujet de votre serviteur et au sujet de sa maison subsiste à jamais, et agissez selon votre parole!'),
('1ch',17,24,'crampon1923','Qu''elle subsiste, et que votre nom soit glorifié à jamais, et que l''on dise: Yahweh des armées, le Dieu d''Israël, est Dieu pour Israël! Et que la maison de David, votre serviteur, soit affermie devant vous!'),
('1ch',17,25,'crampon1923','Car vous-même, ô mon Dieu, vous avez révélé à votre serviteur que vous lui bâtiriez une maison; c''est pourquoi votre serviteur a osé prier devant vous.'),
('1ch',17,26,'crampon1923','Maintenant, Yahweh, c''est vous qui êtes Dieu, et vous avez dit à votre serviteur cette parole agréable.'),
('1ch',17,27,'crampon1923','Maintenant, il vous a plu de bénir la maison de votre serviteur, afin qu''elle subsiste à jamais devant vous; car ce que vous bénissez, Yahweh, est béni pour toujours. "'),
('1ch',18,1,'crampon1923','Après cela, David battit les Philistins et les abaissa, et il ôta de la main des Philistins Geth et les villes de sa dépendance.'),
('1ch',18,2,'crampon1923','Il battit les Moabites, et les Moabites furent pour David des esclaves, lui apportant le tribut.'),
('1ch',18,3,'crampon1923','David battit Hadarézer, roi de Soba, vers Hamath, lorsqu''il était en chemin pour établir sa domination sur le fleuve de l''Euphrate.'),
('1ch',18,4,'crampon1923','David lui prit mille chars, sept mille cavaliers et vingt mille hommes de pied; David coupa les jarrets à tous les chevaux d''attelage, et n''en laissa que cent attelages.'),
('1ch',18,5,'crampon1923','Les Syriens de Damas étant venus au secours d''Hadarézer, roi de Soba, David battit aux Syriens vingt-deux mille hommes.'),
('1ch',18,6,'crampon1923','David mit des garnisons dans la Syrie de Damas; les Syriens furent pour David des esclaves, apportant le tribut. Yahweh donnait la victoire à David partout où il allait.'),
('1ch',18,7,'crampon1923','David prit les boucliers d''or qui étaient sur les serviteurs d''Hadarézer et les apporta à Jérusalem.'),
('1ch',18,8,'crampon1923','David prit encore une grande quantité d''airain à Thébath et à Chun, villes d''Hadarézer; Salomon en fit la mer d''airain, les colonnes et les ustensiles d''airain.'),
('1ch',18,9,'crampon1923','Lorsque Thoü, roi de Hamath, apprit que David avait battu toutes les forces d''Hadarézer, roi de Soba,'),
('1ch',18,10,'crampon1923','il envoya Adoram, son fils, vers le roi David, pour le saluer et pour le féliciter d''avoir attaqué Hadarézer et de l''avoir battu; car Thoü était constamment en guerre avec Hadarézer. Il envoya aussi toutes sortes de vases d''or, d''argent et d''airain.'),
('1ch',18,11,'crampon1923','Le roi David les consacra à Yahweh avec l''argent et l''or qu''il avait pris à toutes les nations, à Edom, à Moab, aux fils d''Ammon, aux Philistins et à Amalec.'),
('1ch',18,12,'crampon1923','Abisaï, fils de Sarvia, battit les Edomites, dans la vallée du Sel, au nombre de dix-huit mille.'),
('1ch',18,13,'crampon1923','Il mit des garnisons dans Edom, et tout Edom fut assujetti à David. Et Yahweh donnait la victoire à David partout où il allait.'),
('1ch',18,14,'crampon1923','David régna sur tout Israël, et il fit droit et justice à tout son peuple.'),
('1ch',18,15,'crampon1923','Joab, fils de Sarvia, commandait l''armée; Josaphat, fils d''Ahilud, était archiviste;'),
('1ch',18,16,'crampon1923','Sadoc, fils d''Achitob, et Achimélech, fils d''Abiathar, étaient prêtres; Susa était secrétaire;'),
('1ch',18,17,'crampon1923','Banaïas, fils de Joïada, était chef des Céréthiens et des Phéléthiens; et les fils de David étaient les premiers au côté du roi.'),
('1ch',19,1,'crampon1923','Après cela, Naas, roi des fils d''Ammon, mourut, et son fils régna à sa place.'),
('1ch',19,2,'crampon1923','David dit: " Je montrerai de la bienveillance à Hanon, fils de Naas, car son père m''a montré de la bienveillance. " Et David envoya des messagers pour le consoler au sujet de son père. Lorsque les serviteurs de David furent arrivés, dans le pays des fils d''Ammon, auprès de Hanon, pour le consoler,'),
('1ch',19,3,'crampon1923','les princes des fils d''Ammon dirent à Hanon: " Penses-tu que ce soit pour honorer ton père que David t''envoie des consolateurs? N''est-ce pas pour reconnaître et détruire, et pour explorer le pays, que ses serviteurs sont venus vers toi! "'),
('1ch',19,4,'crampon1923','Alors Hanon, ayant saisi les serviteurs de David, les rasa et coupa leurs habits à mi-hauteur, jusqu''à la hanche, et il les renvoya.'),
('1ch',19,5,'crampon1923','On alla informer David de ce qui était arrivé à ses hommes, et il envoya des gens à leur rencontre, car ces hommes étaient dans une grande confusion, et le roi leur fit dire: " Restez à Jéricho, jusqu''à ce que votre barbe ait repoussé, et vous reviendrez ensuite. "'),
('1ch',19,6,'crampon1923','Les fils d''Ammon virent qu''ils s''étaient rendus odieux à David, et Hanon et les fils d''Ammon envoyèrent mille talents d''argent pour prendre à leur solde des chars et des cavaliers chez les Syriens de Mésopotamie et chez les Syriens de Maacha et de Soba.'),
('1ch',19,7,'crampon1923','Ils prirent à leur solde trente-deux mille chars, et le roi de Maacha avec son peuple, lesquels vinrent camper près de Médaba. Les fils d''Ammon se rassemblèrent de leurs villes et vinrent au combat.'),
('1ch',19,8,'crampon1923','David l''apprit et fit partir contre eux Joab et toute l''armée, les hommes vaillants.'),
('1ch',19,9,'crampon1923','Les fils d''Ammon sortirent et se rangèrent en bataille à la porte de la ville; les rois qui étaient venus étaient à part dans la campagne.'),
('1ch',19,10,'crampon1923','Lorsque Joab vit qu''il y avait un front de bataille devant et derrière lui, il choisit parmi toute l''élite d''Israël un corps qu''il rangea en face des Syriens,'),
('1ch',19,11,'crampon1923','et il mit le reste du peuple sous le commandement de son frère Abisaï, les rangeant en face des fils d''Ammon. Il dit:'),
('1ch',19,12,'crampon1923','" Si les Syriens sont plus forts que moi, tu viendras à mon secours; et si les fils d''Ammon sont plus forts que toi, je te secourrai.'),
('1ch',19,13,'crampon1923','Sois ferme, et combattons vaillamment pour notre peuple et pour les villes de notre Dieu, et que Yahweh fasse ce qui semblera bon à ses yeux! "'),
('1ch',19,14,'crampon1923','Joab s''avança donc, ainsi que le peuple qui était avec lui, contre les Syriens pour les attaquer, et ceux-ci s''enfuirent devant lui.'),
('1ch',19,15,'crampon1923','Les fils d''Ammon, voyant que les Syriens avaient pris la fuite, s''enfuirent, eux aussi, devant Abisaï, frère de Joab, et rentrèrent dans la ville. Et Joab rentra dans Jérusalem.'),
('1ch',19,16,'crampon1923','Les Syriens, voyant qu''ils avaient été battus devant Israël, envoyèrent des messagers pour faire venir les Syriens qui étaient de l''autre côté du fleuve; et Sophach, chef de l''armée d''Hadarézer marchait devant eux.'),
('1ch',19,17,'crampon1923','David en reçut la nouvelle et, ayant assemblé tout Israël, il passa le Jourdain, vint vers eux, et disposa l''attaque contre eux; et David rangea son armée en bataille contre les Syriens. Ceux-ci engagèrent le combat contre lui,'),
('1ch',19,18,'crampon1923','mais les Syriens s''enfuirent devant Israël, et David tua aux Syriens les chevaux de sept mille chars et quarante mille hommes de pied; il mit aussi à mort Sophach, chef de l''armée.'),
('1ch',19,19,'crampon1923','Les vassaux d''Hadarézer, se voyant battus devant Israël, firent la paix avec David et lui furent assujettis. Et les Syriens ne voulurent plus porter secours aux fils d''Ammon.'),
('1ch',20,1,'crampon1923','Au temps du retour de l''année, au temps où les rois se mettent en campagne, Joab se mit à la tête d''une forte armée, ravagea le pays des fils d''Ammon et vint assiéger Rabba. Mais David resta à Jérusalem. Joab battit Rabba et la détruisit.'),
('1ch',20,2,'crampon1923','David enleva la couronne de leur roi de dessus sa tête, et il y trouva le poids d''un talent d''or; et il y avait sur elle une pierre précieuse, et elle fut mise sur la tête de David. Et il emporta de la ville un très grand butin.'),
('1ch',20,3,'crampon1923','Quant au peuple qui s''y trouvait, il l''en fit sortir, et il les déchira avec des scies, avec des pics de fer et des haches; et David traita de même toutes les villes des fils d''Ammon. Et David retourna à Jérusalem avec tout le peuple.'),
('1ch',20,4,'crampon1923','Après cela eut lieu une bataille à Gazer avec les Philistins. Alors Sabochaï, le Husathite, tua Saphaï, l''un des descendants de Rapha, et les Philistins furent humiliés.'),
('1ch',20,5,'crampon1923','Il y eut encore une bataille avec les Philistins; et Elchanan, fils de Jaïr, tua Lachmi, frère de Goliath, de Geth; le bois de sa lance était semblable à une ensouple de tisserand.'),
('1ch',20,6,'crampon1923','Il y eut encore une bataille à Geth. Il s''y trouva un homme de haute taille, qui avait six doigts à chaque main et à chaque pied, vingt-quatre en tout, et lui aussi descendait de Rapha.'),
('1ch',20,7,'crampon1923','Il insulta Israël, et Jonathan, fils de Samaa, frère de David, le tua.'),
('1ch',20,8,'crampon1923','Ces hommes étaient des fils de Rapha, à Geth; ils périrent par la main de David et par la main de ses serviteurs.'),
('1ch',21,1,'crampon1923','Satan se tint contre Israël, et il excita David à faire le dénombrement d''Israël.'),
('1ch',21,2,'crampon1923','Et David dit à Joab et aux chefs du peuple: " Allez, comptez Israël depuis Bersabée jusqu''à Dan, et faites-moi un rapport, afin que je sache leur nombre. "'),
('1ch',21,3,'crampon1923','Joab répondit: " Que Yahweh ajoute à son peuple cent fois ce qu''il y en a! O roi, monseigneur, ne sont-ils pas tous esclaves de mon seigneur? Pourquoi donc mon seigneur demande-t-il cela? Pourquoi faire venir le péché sur Israël? "'),
('1ch',21,4,'crampon1923','Mais la parole du roi prévalut contre Joab. Joab partit et parcourut tout Israël, et il revint à Jérusalem.'),
('1ch',21,5,'crampon1923','Et Joab remit à David le rôle du dénombrement du peuple: il y avait dans tout Israël onze cent mille hommes tirant l''épée, et en Juda quatre cent soixante-dix mille hommes tirant l''épée.'),
('1ch',21,6,'crampon1923','Il ne fit pas le dénombrement de Lévi et de Benjamin au milieu d''eux, car l''ordre du roi répugnait à Joab.'),
('1ch',21,7,'crampon1923','Dieu vit de mauvais œil cette affaire, et il frappa Israël.'),
('1ch',21,8,'crampon1923','Et David dit à Dieu: " J''ai commis un grand péché en faisant cela. Maintenant, ôtez, je vous prie, l''iniquité de votre serviteur, car j''ai tout à fait agi en insensé. "'),
('1ch',21,9,'crampon1923','Yahweh parla à Gad, le voyant de David, en ces termes:'),
('1ch',21,10,'crampon1923','" Va et parle à David en ces termes: Ainsi parle Yahweh: Je pose devant toi trois choses; choisis-en une, et je te la ferai. "'),
('1ch',21,11,'crampon1923','Gad vint vers David et lui dit: " Ainsi parle Yahweh: Choisis,'),
('1ch',21,12,'crampon1923','ou trois années de famine, ou trois mois durant lesquels tu seras emporté devant tes adversaires et atteint par le glaive de tes ennemis, ou trois jours durant lesquels le glaive de Yahweh et la peste seront dans le pays, et l''ange de Yahweh opérera la destruction dans tout le territoire d''Israël. Maintenant, vois ce que je dois répondre à celui qui m''envoie. "'),
('1ch',21,13,'crampon1923','David dit à Gad: " Je suis dans une cruelle angoisse. Ah! que je tombe entre les mains de Yahweh, car ses miséricordes sont très grandes, et que je ne tombe pas entre les mains des hommes! "'),
('1ch',21,14,'crampon1923','Et Yahweh envoya une peste en Israël, et il tomba soixante-dix mille hommes en Israël.'),
('1ch',21,15,'crampon1923','Et Dieu envoya un ange à Jérusalem pour la détruire; et pendant qu''il détruisait, Yahweh vit et se repentit de ce mal, et il dit à l''ange qui détruisait: " Assez! retire maintenant ta main. " L''ange de Yahweh se tenait près de l''aire d''Ornan, le Jésubéen.'),
('1ch',21,16,'crampon1923','David, ayant levé les yeux, vit l''ange de Yahweh se tenant entre la terre et le ciel, et ayant à la main son épée nue, tournée contre Jérusalem. Alors David et les anciens, couverts de sacs, tombèrent sur leur visage.'),
('1ch',21,17,'crampon1923','Et David dit à Dieu: " N''est-ce pas moi qui ai dit de faire le dénombrement du peuple? C''est moi qui ai péché et qui ai fait le mal; mais celles-là, ces brebis, qu''ont-elles fait? Yahweh, mon Dieu, que votre main soit donc sur moi et sur la maison de mon père, mais non sur votre peuple pour sa ruine. "'),
('1ch',21,18,'crampon1923','L''ange de Yahweh ordonna à Gad de dire à David de monter pour élever un autel à Yahweh sur l''aire d''Ornan, le Jébuséen.'),
('1ch',21,19,'crampon1923','David monta, selon la parole de Gad qu''il avait dite au nom de Yahweh.'),
('1ch',21,20,'crampon1923','Ornan, s''étant retourné, vit l''ange, et il se cacha, lui et ses quatre fils: Ornan battait alors du froment.'),
('1ch',21,21,'crampon1923','Lorsque David arriva auprès d''Ornan, Ornan regarda et il aperçut David; sortant aussitôt de l''aire, il se prosterna devant David, le visage contre terre.'),
('1ch',21,22,'crampon1923','David dit à Ornan: " Cède-moi l''emplacement de l''aire, et j''y bâtirai un autel à Yahweh; cède-le-moi pour sa pleine valeur en argent, pour que la plaie se retire de dessus le peuple. "'),
('1ch',21,23,'crampon1923','Ornan dit à David: " Prends-le, et que mon seigneur le roi fasse ce qu''il trouvera bon. Vois, je donne les bœufs pour l''holocauste, les traîneaux pour le bois, et le froment pour l''oblation; je donne tout cela. "'),
('1ch',21,24,'crampon1923','Mais le roi David dit à Ornan: " Non! Mais je veux l''acheter contre sa pleine valeur en argent, car je ne prendrai pas ce qui est à toi pour Yahweh, et je n''offrirai pas un holocauste qui ne me coûte rien. "'),
('1ch',21,25,'crampon1923','David donna à Ornan un poids de six cents sicles d''or pour l''emplacement.'),
('1ch',21,26,'crampon1923','Et David bâtit là un autel à Yahweh, et offrit des holocaustes et des sacrifices pacifiques. Il cria vers Yahweh, et Yahweh lui répondit par le feu qui descendit du ciel sur l''autel de l''holocauste.'),
('1ch',21,27,'crampon1923','Et Yahweh parla à l''ange, et celui-ci remit son épée dans le fourreau.'),
('1ch',21,28,'crampon1923','En ce temps-là, David, voyant que Yahweh l''avait exaucé dans l''aire d''Ornan, le Jébuséen, y offrait des sacrifices.'),
('1ch',21,29,'crampon1923','Le tabernacle de Yahweh, que Moïse avait construit au désert, et l''autel des holocaustes étaient en ce temps-là sur le haut lieu de Gabaon.'),
('1ch',21,30,'crampon1923','Mais David ne pouvait pas aller devant cet autel pour honorer Dieu, parce qu''il avait été terrifié par l''épée de l''ange de Yahweh.'),
('1ch',22,1,'crampon1923','Et David dit: " C''est ici la maison de Yahweh Dieu, et c''est l''autel pour les holocaustes d''Israël. "'),
('1ch',22,2,'crampon1923','David ordonna de rassembler les étrangers qui étaient dans le pays d''Israël, et il établit des tailleurs de pierre pour couper des pierres de taille pour la construction de la maison de Dieu.'),
('1ch',22,3,'crampon1923','David prépara aussi du fer en quantité, pour les clous des battants des portes et pour les crampons, ainsi que de l''airain en quantité incalculable,'),
('1ch',22,4,'crampon1923','et des bois de cèdre sans nombre; car les Sidoniens et les Tyriens avaient amené à David des bois de cèdre en abondance.'),
('1ch',22,5,'crampon1923','David disait: " Mon fils Salomon est jeune et faible, et la maison qui sera bâtie à Yahweh doit être magnifique à l''excès, afin d''être renommée et glorieuse dans tous les pays; je veux donc faire pour lui des préparatifs. " Et David fit beaucoup de préparatifs avant sa mort.'),
('1ch',22,6,'crampon1923','David appela Salomon, son fils, et lui ordonna de bâtir une maison à Yahweh, le Dieu d''Israël.'),
('1ch',22,7,'crampon1923','David dit à Salomon: " Mon fils, j''avais l''intention de bâtir une maison au nom de Yahweh, mon Dieu.'),
('1ch',22,8,'crampon1923','Mais la parole de Yahweh me fut adressée en ces termes: Tu as versé du sang en quantité et tu as fait de grandes guerres; tu ne bâtiras pas une maison à mon nom, car tu as versé devant moi beaucoup de sang sur la terre.'),
('1ch',22,9,'crampon1923','Voici, il te naîtra un fils qui sera un homme tranquille, je lui donnerai du repos devant tous ses ennemis d''alentour; car Salomon sera son nom, et je donnerai en Israël la paix et la tranquillité pendant sa vie.'),
('1ch',22,10,'crampon1923','Ce sera lui qui bâtira une maison à mon nom; il sera pour moi un fils, et je serai pour lui un père, et j''affermirai pour toujours le trône de sa royauté sur Israël.'),
('1ch',22,11,'crampon1923','Maintenant, mon fils, que Yahweh soit avec toi, afin que tu prospères et que tu bâtisses la maison de Yahweh, ton Dieu, selon ce qu''il a dit de toi.'),
('1ch',22,12,'crampon1923','Daigne seulement Yahweh t''accorder la prudence et l''intelligence, quand il te donnera autorité sur Israël, afin que tu observes la loi de Yahweh, ton Dieu!'),
('1ch',22,13,'crampon1923','Alors tu prospéreras, si tu prends soin de mettre en pratique les lois et les ordonnances que Yahweh a prescrites à Moïse pour Israël. Sois fort, et prends courage; ne crains point et ne t''effraie point.'),
('1ch',22,14,'crampon1923','Voici que par mes efforts, j''ai préparé pour la maison de Yahweh cent mille talents d''or, un million de talents d''argent; quant à l''airain et au fer, on ne saurait les peser, car il y en a en quantité; j''ai aussi préparé du bois et des pierres, et tu en ajouteras encore.'),
('1ch',22,15,'crampon1923','Tu as avec toi en multitude des ouvriers, des tailleurs de pierres, des artisans de la pierre et du bois et des hommes habiles dans toute espèce d''ouvrages.'),
('1ch',22,16,'crampon1923','L''or, l''argent, l''airain et le fer sont sans nombre. Lève-toi! A l''œuvre! et que Yahweh soit avec toi! "'),
('1ch',22,17,'crampon1923','David ordonna à tous les chefs d''Israël de venir en aide à Salomon, son fils, en disant:'),
('1ch',22,18,'crampon1923','" Yahweh, votre Dieu, n''est-il pas avec vous, et ne vous a-t-il pas donné du repos de tous côtés? Car il a livré entre mes mains les habitants du pays, et le pays est assujetti devant Yahweh et devant son peuple.'),
('1ch',22,19,'crampon1923','Maintenant, appliquez votre cœur et votre âme à chercher Yahweh, votre Dieu; levez-vous et bâtissez le sanctuaire de Yahweh Dieu, afin d''amener l''arche de l''alliance de Yahweh et les saints ustensiles de Dieu dans la maison qui sera bâtie au nom de Yahweh. "'),
('1ch',23,1,'crampon1923','David, vieux et rassasié de jours, établit Salomon, son fils, roi sur Israël.'),
('1ch',23,2,'crampon1923','Il réunit tous les chefs d''Israël, les prêtres et les lévites.'),
('1ch',23,3,'crampon1923','On compta les lévites, depuis l''âge de trente ans et au-dessus; leur nombre, par tête et par hommes, fut de trente huit mille.'),
('1ch',23,4,'crampon1923','Et David dit: " De ceux-là, que vingt-quatre mille soient préposés aux offices de la maison de Yahweh, que six mille soient scribes et magistrats,'),
('1ch',23,5,'crampon1923','quatre mille portiers, et que quatre mille louent Yahweh avec les instruments que j''ai faits pour le louer. "'),
('1ch',23,6,'crampon1923','David les distribua en classes, d''après les fils de Lévi: Gerson, Caath et Mérari.'),
('1ch',23,7,'crampon1923','Des Gersonites: Léédan et Séméï. —'),
('1ch',23,8,'crampon1923','Fils de Léédan: le chef Jahiel, Zétham et Joël: trois.'),
('1ch',23,9,'crampon1923','Fils de Séméï: Salomith, Hoziel et Aran: trois. Ce sont là les chefs de famille issus de Léédan. —'),
('1ch',23,10,'crampon1923','Fils de Séméï: Léheth, Ziza, Jaüs et Baria. Ce sont là les quatre fils de Séméï;')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('1ch',23,11,'crampon1923','Léheth était le chef, et Ziza le second; Jaüs et Baria n''eurent pas beaucoup de fils et ils furent comptés, selon leur famille, en une classe.'),
('1ch',23,12,'crampon1923','Fils de Caath: Amram, Isaar, Hébron et Oziel: quatre. —'),
('1ch',23,13,'crampon1923','Fils d''Amram: Aaron et Moïse. Aaron fut mis à part pour qu''on le sanctifie comme très saint, lui et ses fils à jamais, afin de faire fumer les parfums devant Yahweh, de faire son service et de bénir en son nom à jamais.'),
('1ch',23,14,'crampon1923','Quant à Moïse, homme de Dieu, ses fils furent comptés dans la tribu de Lévi.'),
('1ch',23,15,'crampon1923','Fils de Moïse: Gersom et Eliézer. —'),
('1ch',23,16,'crampon1923','Fils de Gersom: Subuël, le chef. —'),
('1ch',23,17,'crampon1923','Les fils d''Eliézer furent: Rohobia, le chef; Eliézer n''eut pas d''autre fils, mais les fils de Rohobia furent très nombreux. —'),
('1ch',23,18,'crampon1923','Fils d''Isaar: Salomith, le chef. —'),
('1ch',23,19,'crampon1923','Fils d''Hébron: Jériaü, le chef; Amarias, le second; Jahaziel, le troisième et Jecmaam, le quatrième, —'),
('1ch',23,20,'crampon1923','Fils d''Oziel: Micha, le chef; Jésia, le second.'),
('1ch',23,21,'crampon1923','Fils de Mérari: Moholi et Musi. — Fils de Moholi: Eléazar et Cis.'),
('1ch',23,22,'crampon1923','Eléazar mourut sans avoir de fils, mais seulement des filles; les fils de Cis, leurs frères, les prirent pour femmes. —'),
('1ch',23,23,'crampon1923','Fils de Musi: Molohi, Eder et Jérimoth: trois.'),
('1ch',23,24,'crampon1923','Ce sont là les fils de Lévi selon leurs familles, les chefs de famille selon qu''ils furent dénombrés, nommément comptés par tête; ils faisaient l''œuvre du service de la maison de Yahweh, depuis l''âge de vingt ans et au-dessus.'),
('1ch',23,25,'crampon1923','Car David dit: " Yahweh, le Dieu d''Israël, a donné le repos à son peuple, et il habitera pour toujours à Jérusalem;'),
('1ch',23,26,'crampon1923','et quant aux lévites, ils n''auront plus à porter la Demeure et tous les ustensiles pour son service. "'),
('1ch',23,27,'crampon1923','Ce fut d''après les derniers ordres de David que se fit le dénombrement des fils de Lévi depuis l''âge de vingt ans et au-dessus.'),
('1ch',23,28,'crampon1923','Car leur fonction était de se mettre à la disposition des fils d''Aaron pour le service de la maison de Yahweh, concernant les parvis et les chambres, la purification de toutes les choses saintes, et l''œuvre du service de la maison de Dieu;'),
('1ch',23,29,'crampon1923','concernant les pains de proposition, la fleur de farine pour les oblations, les galettes sans levain, ce qui est cuit sur la poêle et ce qui est mélangé, tout ce qu''il y avait à peser et à mesurer.'),
('1ch',23,30,'crampon1923','Ils avaient à se présenter chaque matin et chaque soir, afin de célébrer et louer Yahweh,'),
('1ch',23,31,'crampon1923','et d''offrir tous les holocaustes à Yahweh dans les sabbats, les nouvelles lunes et les fêtes, selon le nombre que la loi prescrit d''offrir à perpétuité devant Yahweh.'),
('1ch',23,32,'crampon1923','Ils devaient s''appliquer au soin de la tente de réunion, au soin des choses saintes et au soin des fils d''Aaron, leurs frères, pour le service de la maison de Yahweh.'),
('1ch',24,1,'crampon1923','Quant aux fils d''Aaron, voici leurs classes: Fils d''Aaron: Nadab, Abiu, Eléazar et Ithamar.'),
('1ch',24,2,'crampon1923','Nadab et Abiu moururent avant leur père, sans avoir de fils, et Eléazar et Ithamar remplirent les fonctions du sacerdoce.'),
('1ch',24,3,'crampon1923','David, Sadoc, de la descendance d''Eléazar, et Achimélech, de la descendance d''Ithamar, répartirent les fils d''Aaron par classes selon leur service.'),
('1ch',24,4,'crampon1923','On trouva parmi les fils d''Eléazar plus de chefs que parmi les fils d''Ithamar, et on les répartit ainsi: pour les fils d''Eléazar, seize chefs de famille, et, pour les fils d''Ithamar, huit chefs de famille.'),
('1ch',24,5,'crampon1923','On les répartit par le sort, les uns comme les autres, car il se trouvait des princes du sanctuaire et des princes de Dieu aussi bien parmi les fils d''Eléazar que parmi les fils d''Ithamar.'),
('1ch',24,6,'crampon1923','Séméïas, fils de Nathanaël, le secrétaire, un des lévites, les inscrivit devant le roi et les princes, devant Sadoc le grand prêtre, et Achimélech, fils d''Abiathar, et devant les chefs de familles sacerdotales et lévitiques, une famille étant tirée au sort pour Eléazar, puis une famille pour Ithamar.'),
('1ch',24,7,'crampon1923','Le premier sort échut à Joïarib, le deuxième à Jédéï,'),
('1ch',24,8,'crampon1923','le troisième à Harim, le quatrième à Séorim,'),
('1ch',24,9,'crampon1923','le cinquième à Melchia, le sixième à Maïman,'),
('1ch',24,10,'crampon1923','le septième à Accos, le huitième à Abia,'),
('1ch',24,11,'crampon1923','le neuvième à Jésua, le dixième à Séchénia,'),
('1ch',24,12,'crampon1923','le onzième a Eliasib, le douzième à Jacim,'),
('1ch',24,13,'crampon1923','le treizième à Hoppha, le quatorzième à Isbaab,'),
('1ch',24,14,'crampon1923','le quinzième à Belga, le seizième à Emmer,'),
('1ch',24,15,'crampon1923','le dix-septième à Hézir, le dix-huitième à Aphsès,'),
('1ch',24,16,'crampon1923','le dix-neuvième à Phétéïa, le vingtième à Hézéchiel,'),
('1ch',24,17,'crampon1923','le vingt et unième à Jachin, le vingt-deuxième à Gamul,'),
('1ch',24,18,'crampon1923','le vingt-troisième à Dalaiaü, le vingt-quatrième à Mazziaü.'),
('1ch',24,19,'crampon1923','Telles furent leurs classes selon leur service, afin qu''ils vinssent à la maison de Yahweh, selon le règlement qu''ils avaient reçu par l''organe d''Aaron, leur père, comme le lui avait ordonné Yahweh, le Dieu d''Israël.'),
('1ch',24,20,'crampon1923','Voici les chefs du reste des lévites: des fils d''Amram: Subaël; des fils de Subaël: Jéhédéïa;'),
('1ch',24,21,'crampon1923','de Rohobia, des fils de Rohobia: le chef Jésias.'),
('1ch',24,22,'crampon1923','Des Isaarites: Salémoth; des fils de Salémoth: Jahath.'),
('1ch',24,23,'crampon1923','Fils d''Hébron: Jériaü le premier, Amarias le deuxième, Jahaziel le troisième, Jecmaan le quatrième.'),
('1ch',24,24,'crampon1923','Fils d''Oziel: Micha; des fils de Micha: Samir;'),
('1ch',24,25,'crampon1923','frère de Micha: Jésia; fils de Jésia: Zacharias. —'),
('1ch',24,26,'crampon1923','Fils de Mérari: Moholi et Musi.'),
('1ch',24,27,'crampon1923','Fils de Mérari, par Oziaü, son fils: Saam, Zachur et Hébri.'),
('1ch',24,28,'crampon1923','De Moholi: Eléazar, qui n''eut point de fils;'),
('1ch',24,29,'crampon1923','de Cis, les fils de Cis; Jéraméel.'),
('1ch',24,30,'crampon1923','Fils de Musi: Moholi, Eder et Jérimoth.'),
('1ch',24,31,'crampon1923','Ce sont là les fils de Lévi, selon leurs familles. Eux aussi, comme leurs frères, les fils d''Aaron, ils tirèrent le sort devant le roi David, devant Sadoc et Achimélech, et devant les chefs de famille sacerdotales et lévitiques, les plus anciens étant sur le même pied que les plus jeunes.'),
('1ch',25,1,'crampon1923','David et les princes de l''armée mirent à part, pour le service, des fils d''Asaph, de Héman et d''Idithun qui prophétisaient avec la harpe, la cithare et les cymbales. Voici leur nombre, — de ceux qui étaient occupés au service —:'),
('1ch',25,2,'crampon1923','Des fils d''Asaph: Zacchur, Joseph, Nathania et Asaréla, fils d''Asaph, sous la direction d''Asaph, qui prophétisait selon les ordres du roi. —'),
('1ch',25,3,'crampon1923','D''Idithun, les fils d''Idithun: Godolias, Sori, Jéséïas, Hasabias, Mathathias et Séméi, six, selon les ordres de leur père Idithun, qui prophétisait avec la cithare pour célébrer et louer Yahweh. —'),
('1ch',25,4,'crampon1923','De Héman, les fils de Héman: Bocciaü, Mathaniaü, Oziel, Subuël, Jérimoth, Hananias, Hanani, Eliatha, Geddelthi, Romemthiézer, Jesbacassa, Mellothi, Othir et Mahazioth;'),
('1ch',25,5,'crampon1923','ils étaient tous fils de Héman, voyant du roi dans les paroles de Dieu, pour exalter sa puissance: Dieu avait donné à Héman quatorze fils et trois filles.'),
('1ch',25,6,'crampon1923','Tous ces lévites étaient sous les ordres de leurs pères pour le chant de la maison de Yahweh, ayant des cymbales, des cithares et des harpes pour le service de la maison de Dieu, sous les ordres de David, d''Asaph, d''Idithun et de Héman.'),
('1ch',25,7,'crampon1923','Leur nombre, y compris leurs frères exercés à chanter Yahweh, tous ceux qui avaient de l''habileté, était de deux cent quatre-vingt-huit.'),
('1ch',25,8,'crampon1923','Ils tirèrent le sort pour leurs fonctions, petits et grands, maîtres et disciples.'),
('1ch',25,9,'crampon1923','Le premier sort échut, pour Asaph, à Joseph; le second, à Godolias: lui, ses frères et ses fils: douze;'),
('1ch',25,10,'crampon1923','le troisième, à Zachur: lui, ses fils et ses frères: douze;'),
('1ch',25,11,'crampon1923','le quatrième, à Isari: lui, ses fils et ses frères: douze;'),
('1ch',25,12,'crampon1923','le cinquième à Nathania: lui, ses fils et ses frères: douze;'),
('1ch',25,13,'crampon1923','le sixième à Bocciaü: lui, ses fils et ses frères: douze;'),
('1ch',25,14,'crampon1923','le septième à Isrééla: lui, ses fils et ses frères: douze;'),
('1ch',25,15,'crampon1923','le huitième à Jésaïas: lui, ses fils et ses frères: douze;'),
('1ch',25,16,'crampon1923','le neuvième à Mathanias: lui, ses fils et ses frères: douze;'),
('1ch',25,17,'crampon1923','le dixième à Séméïas: lui, ses fils et ses frères: douze;'),
('1ch',25,18,'crampon1923','le onzième à Azaréel: lui, ses fils et ses frères: douze;'),
('1ch',25,19,'crampon1923','le douzième à Hasabias: lui, ses fils et ses frères: douze;'),
('1ch',25,20,'crampon1923','le treizième à Subuël: lui, ses fils et ses frères: douze;'),
('1ch',25,21,'crampon1923','le quatorzième à Mathathias: lui, ses fils et ses frères: douze;'),
('1ch',25,22,'crampon1923','le quinzième à Jérimoth: lui, ses fils et ses frères: douze;'),
('1ch',25,23,'crampon1923','le seizième à Hananias: lui, ses fils et ses frères: douze;'),
('1ch',25,24,'crampon1923','le dix-septième à Jesbacassa: lui, ses fils et ses frères: douze;'),
('1ch',25,25,'crampon1923','le dix-huitième à Hanani: lui, ses fils et ses frères: douze;'),
('1ch',25,26,'crampon1923','le dix-neuvième à Mellothi: lui, ses fils et ses frères: douze;'),
('1ch',25,27,'crampon1923','le vingtième à Eliatha: lui, ses fils et ses frères: douze;'),
('1ch',25,28,'crampon1923','le vingt-unième à Othir: lui, ses fils et ses frères: douze;'),
('1ch',25,29,'crampon1923','le vingt-deuxième à Geddelthi: lui, ses fils et ses frères: douze;'),
('1ch',25,30,'crampon1923','le vingt-troisième à Mahazioth: lui, ses fils et ses frères: douze;'),
('1ch',25,31,'crampon1923','le vingt-quatrième à Romemthiézer: lui, ses fils et ses frères: douze.'),
('1ch',26,1,'crampon1923','Voici les classes des portiers: Des Coréïtes: Mésélémia, fils de Coré, d''entre les fils d''Asaph. —'),
('1ch',26,2,'crampon1923','Fils de Mésélémia: Zacharias, le premier-né; Jadihel le deuxième, Zabadias le troisième, Jathanaël le quatrième,'),
('1ch',26,3,'crampon1923','Elam le cinquième, Johanan le sixième, Elioénaï le septième. —'),
('1ch',26,4,'crampon1923','Fils d''Obédédom: Séméïas, le premier-né; Jozabad le deuxième, Joaha le troisième, Sachar le quatrième, Nathanaël le cinquième,'),
('1ch',26,5,'crampon1923','Ammiel le sixième, Issachar le septième, Phollathi le huitième; car Dieu avait béni Obédédom. —'),
('1ch',26,6,'crampon1923','A Séméïas, son fils, naquirent des fils qui furent chefs dans la maison de leur père, car ils étaient de vaillants hommes.'),
('1ch',26,7,'crampon1923','Fils de Séméïas: Othni, Raphaël, Obed, Elzabad et ses frères, hommes vaillants, Eliu et Samachias.'),
('1ch',26,8,'crampon1923','Tous ceux-là étaient des fils d''Obédédom; eux, leurs fils et leurs frères, hommes braves et forts pour le service, étaient au nombre de soixante-deux, issus d''Obédédom.'),
('1ch',26,9,'crampon1923','Mésélémia avait des fils et des frères, hommes vaillants, au nombre de dix-huit.'),
('1ch',26,10,'crampon1923','Hosa, des fils de Mérari, avait pour fils: Semri, le chef: il n''était pas le premier-né, mais son père l''avait établi chef;'),
('1ch',26,11,'crampon1923','Helcias le second, Tabélias le troisième, Zacharias le quatrième. Tous les fils et les frères de Hosa étaient au nombre de treize.'),
('1ch',26,12,'crampon1923','Ces classes de portiers, les chefs de ces hommes, avaient, à côté de leurs frères, des fonctions pour le service de la maison de Yahweh.'),
('1ch',26,13,'crampon1923','Ils tirèrent les sorts pour chaque porte, petits et grands, selon leurs familles.'),
('1ch',26,14,'crampon1923','Le sort pour le côté de l''orient échut à Sélémias. On tira au sort pour Zacharias, son fils, qui était un sage conseiller, et le côté du septentrion lui échut.'),
('1ch',26,15,'crampon1923','Le côté du midi échut à Obédédom, et la maison des magasins à ses fils.'),
('1ch',26,16,'crampon1923','A Séphim et à Hosa échut le côté de l''occident, près de la porte Schalléketh, sur le chemin montant: une garde était en face de l''autre.'),
('1ch',26,17,'crampon1923','Il y avait à l''orient six lévites, au septentrion quatre par jour, au midi quatre par jour, et quatre aux magasins, deux à deux;'),
('1ch',26,18,'crampon1923','du côté des dépendances, à l''occident, quatre vers le chemin, deux aux dépendances. —'),
('1ch',26,19,'crampon1923','Telles sont les classes des portiers, d''entre les fils des Coréïtes et les fils de Mérari.'),
('1ch',26,20,'crampon1923','Les lévites, leurs frères, avaient l''intendance des trésors de la maison de Dieu et des trésors des choses consacrées.'),
('1ch',26,21,'crampon1923','Parmi les fils de Lédan, savoir les fils des Gersonites issus de Lédan, chefs des familles de Lédan le Gersonite, c''était Jéhiel;'),
('1ch',26,22,'crampon1923','les fils de Jéhiel, Zathan et Joël, son frère, avaient l''intendance des trésors de la maison de Yahweh.'),
('1ch',26,23,'crampon1923','Parmi les Amramites, les Isaarites, les Hébronites et les Ozihélites,'),
('1ch',26,24,'crampon1923','c''était Subuël, fils de Gersom, fils de Moïse, qui était l''intendant en chef des trésors.'),
('1ch',26,25,'crampon1923','Parmi ses frères issus d''Eliézer, dont le fils fut Rahabia, dont le fils fut Isaïas, dont le fils fut Joram, dont le fils fut Zéchri, dont le fils fut Sélémith,'),
('1ch',26,26,'crampon1923','c''étaient Sélémith et ses frères qui avaient l''intendance de tous les trésors des choses saintes qu''avaient consacrées le roi David, les chefs de famille, avec les chefs de milliers et de centaines et les chefs de l''armée:'),
('1ch',26,27,'crampon1923','ils les avaient consacrées sur le butin pris à la guerre, pour l''entretien de la maison de Yahweh.'),
('1ch',26,28,'crampon1923','Tout ce qu''avaient consacré Samuel, le voyant, Saül, fils de Cis, Abner, fils de Ner, Joab, fils de Sarvia, ou tout autre, était sous la main de Sélémith et de ses frères.'),
('1ch',26,29,'crampon1923','Parmi les Isaarites, Chonénias et ses fils étaient employés pour les affaires extérieures en Israël, comme scribes et comme magistrats.'),
('1ch',26,30,'crampon1923','Parmi les Hébronites, Hasabias et ses frères, hommes vaillants, au nombre de mille sept cents, avaient la surveillance d''Israël de l''autre côté du Jourdain, à l''occident, pour toutes les affaires de Yahweh et le service du roi.'),
('1ch',26,31,'crampon1923','Pour les Hébronites, Jéria était le chef, — Pour les Hébronites, selon leurs généalogies, par familles, on fit des recherches, la quarantième année du règne de David, et l''on trouva parmi eux de vaillants hommes à Jazer en Galaad, —'),
('1ch',26,32,'crampon1923','et ses frères, hommes vaillants, étaient au nombre de deux mille sept cents chefs de famille. Le roi David les établit sur les Rubénites, sur les Gadites et sur la demi-tribu de Manassé pour toutes les affaires de Dieu et les affaires du roi.'),
('1ch',27,1,'crampon1923','Les enfants d''Israël selon leur nombre, chefs de familles, chefs de milliers et de centaines, officiers au service du roi pour tout ce qui concernait les divisions, celles qui arrivaient et celles qui partaient, mois par mois, pendant tous les mois de l''année, — chaque division étant de vingt-quatre mille hommes, — étaient:'),
('1ch',27,2,'crampon1923','A la tête de la première division, pour le premier mois, était Jesboam, fils de Zabdiel, et il y avait dans sa division vingt-quatre mille hommes.'),
('1ch',27,3,'crampon1923','Il était d''entre les fils de Pharès, et il commandait tous les chefs des troupes du premier mois. —'),
('1ch',27,4,'crampon1923','A la tête de la division du deuxième mois était Dudia, l''Ahohite; Macelloth, le prince, était un chef de sa division; et il y avait dans sa division vingt-quatre mille hommes. —'),
('1ch',27,5,'crampon1923','Le chef de la troisième division, pour le troisième mois, était Banaïas, fils du prêtre Joïada, chef; et il y avait dans sa division vingt-quatre mille hommes.'),
('1ch',27,6,'crampon1923','Ce Banaïas était le héros des Trente, à la tête des Trente; Amizabad, son fils, était un chef de sa division. —'),
('1ch',27,7,'crampon1923','Le quatrième, pour le quatrième mois, était Asaël, frère de Joab, et, après lui, Zabadias, son fils; et il y avait dans sa division vingt-quatre mille hommes. —'),
('1ch',27,8,'crampon1923','Le cinquième, pour le cinquième mois, était le chef Samaoth, l''Izrahite; et il y avait dans sa division vingt-quatre mille hommes. —'),
('1ch',27,9,'crampon1923','Le sixième, pour le sixième mois, était Hira, fils d''Accès, de Thécua; et il y avait dans sa division vingt-quatre mille hommes. —'),
('1ch',27,10,'crampon1923','Le septième, pour le septième mois, était Hellès, le Phallonite, des fils d''Ephraïm; et il y avait dans sa division vingt-quatre mille hommes. —'),
('1ch',27,11,'crampon1923','Le huitième, pour le huitième mois, était Sobochaï, le Husathite, de la famille des Zarahites; et il y avait dans sa division vingt-quatre mille hommes. —'),
('1ch',27,12,'crampon1923','Le neuvième, pour le neuvième mois, était Abiézer, d''Anathoth, des fils de Benjamin; et il y avait dans sa division vingt-quatre mille hommes. —'),
('1ch',27,13,'crampon1923','Le dixième, pour le dixième mois, était Maraï, de Nétopha, de la famille des Zaharites; et il y avait dans sa division vingt-quatre mille hommes. —'),
('1ch',27,14,'crampon1923','Le onzième, pour le onzième mois, était Banaïas, de Pharathon des fils d''Ephraïm; et il y avait dans sa division vingt-quatre mille hommes. —'),
('1ch',27,15,'crampon1923','Le douzième, pour le douzième mois, était Holdaï, de Nétopha, de la famille d''Othoniel; et il y avait dans sa division vingt-quatre mille hommes. —'),
('1ch',27,16,'crampon1923','Et il y avait à la tête des tribus d''Israël: des Rubénites: Eliézer, fils de Zéchri; des Siméonites: Saphatias, fils de Maacha;'),
('1ch',27,17,'crampon1923','des Lévites: Hasabias, fils de Camuel; de la famille d''Aaron: Sadoc;'),
('1ch',27,18,'crampon1923','de Juda: Eliu, frère de David; d''Issachar, Amri, fils de Michaël;'),
('1ch',27,19,'crampon1923','de Zabulon: Jesmaïas, fils d''Abdias; de Nephtali: Jérimoth, fils d''Ozriel;'),
('1ch',27,20,'crampon1923','des fils d''Ephraïm: Osée, fils d''Ozaziu; de la demi-tribu de Manassé: Joël, fils de Phadaïas;'),
('1ch',27,21,'crampon1923','de la demi-tribu de Manassé, en Galaad: Jaddo, fils de Zacharias; de Benjamin: Jasiel, fils d''Abner;'),
('1ch',27,22,'crampon1923','de Dan: Ezrihel, fils de Jéroham. Ce sont les princes des tribus d''Israël.'),
('1ch',27,23,'crampon1923','David ne fit point le dénombrement de ceux qui étaient âgés de vingt ans et au-dessous, car Yahweh avait dit qu''il multiplierait Israël comme les étoiles du ciel.'),
('1ch',27,24,'crampon1923','Joab, fils de Sarvia, avait commencé le dénombrement, mais il ne l''acheva pas, la colère de Yahweh étant venue à cause de cela sur Israël, et le résultat n''en fut pas porté sur les rôles des chroniques du roi David.'),
('1ch',27,25,'crampon1923','Asmoth, fils d''Adiel, était préposé sur les trésors du roi; Jonathan, fils d''Ozias, sur les trésors dans les champs, dans les villes, dans les villages et dans les tours;'),
('1ch',27,26,'crampon1923','Ezri, fils de Chélub, sur les ouvriers des champs qui cultivaient la terre;'),
('1ch',27,27,'crampon1923','Séméï, de Rama, sur les vignes; Zabdias, de Sapham, sur les provisions de vin dans les vignes;'),
('1ch',27,28,'crampon1923','Balanan, de Géder, sur les oliviers et les sycomores dans la Séphéla; Joas, sur les provisions d''huile;'),
('1ch',27,29,'crampon1923','Séthraï, de Saron, sur les bœufs qui paissaient en Saron; Saphat, fils d''Adli, sur les bœufs dans les vallées;'),
('1ch',27,30,'crampon1923','Ubil, l''Ismaélite, sur les chameaux; Jadias, de Méronath, sur les ânesses;'),
('1ch',27,31,'crampon1923','Jaziz, l''Agarénien, sur les brebis. Tous ceux-là étaient intendants des biens du roi David.'),
('1ch',27,32,'crampon1923','Jonathan, oncle de David, était conseiller; c''était un homme de sens et de savoir. Jahiel, fils de Hachamoni, était avec les fils du roi.'),
('1ch',27,33,'crampon1923','Achitophel était conseiller du roi, et Chusaï, l''Archéen, était ami du roi;'),
('1ch',27,34,'crampon1923','après Achitophel, Joïada, fils de Banaïas, et Abiathar. Joab était chef de l''armée du roi.'),
('1ch',28,1,'crampon1923','David rassembla à Jérusalem tous les princes d''Israël: les princes des tribus, les chefs des divisions qui servaient le roi, les chefs de milliers et les chefs de centaines, les intendants de tous les biens et troupeaux du roi et de ses fils, ainsi que les intendants et les vaillants, — tous les vaillants soldats.'),
('1ch',28,2,'crampon1923','Le roi David se leva sur ses pieds et dit: " Ecoutez-moi, mes frères et mon peuple. J''avais l''intention de bâtir une maison de repos pour l''arche de l''alliance de Yahweh et pour le marche-pied de notre Dieu, et je faisais des préparatifs pour la construction.'),
('1ch',28,3,'crampon1923','Mais Dieu m''a dit: Tu ne bâtiras pas une maison à mon nom, parce que tu es un homme de guerre et que tu as versé le sang.'),
('1ch',28,4,'crampon1923','Yahweh, le Dieu d''Israël, m''a choisi dans toute la maison de mon père, pour que je fusse roi sur Israël à jamais. Car il a choisi Juda pour être chef; et dans la maison de Juda, il a choisi la maison de mon père, et, parmi les fils de mon père, il s''est complu en moi pour me faire régner sur tout Israël.'),
('1ch',28,5,'crampon1923','Et entre tous mes fils, — car Yahweh m''a donné beaucoup de fils, — il a choisi mon fils Salomon pour le faire asseoir sur le trône de la royauté de Yahweh, sur Israël.'),
('1ch',28,6,'crampon1923','Il m''a dit: C''est Salomon, ton fils, qui bâtira ma maison et mes parvis, car je l''ai choisi pour mon fils, et je serai pour lui un père.'),
('1ch',28,7,'crampon1923','J''affermirai pour toujours sa royauté, s''il reste attaché, comme il l''est aujourd''hui, à la pratique de mes commandements et de mes ordonnances.'),
('1ch',28,8,'crampon1923','Maintenant, aux yeux de tout Israël, de l''assemblée de Yahweh, et devant notre Dieu qui nous entend, gardez et observez avec soin tous les commandements de Yahweh, votre Dieu, afin que vous possédiez ce bon pays et que vous le transmettiez en héritage à vos fils après vous, à jamais.'),
('1ch',28,9,'crampon1923','Et toi, Salomon, mon fils, connais le Dieu de ton père, et sers-le d''un cœur parfait et d''une âme dévouée, car Yahweh sonde tous les cœurs et pénètre tout dessein des pensées. Si tu le cherches, il se laissera trouver par toi; mais si tu l''abandonnes, il te rejettera pour toujours.'),
('1ch',28,10,'crampon1923','Vois maintenant que Yahweh t''a choisi pour bâtir une maison qui sera son sanctuaire. Sois fort, et à l''œuvre. "'),
('1ch',28,11,'crampon1923','David donna à Salomon son fils le modèle du portique et des bâtiments, chambres du trésor, chambres hautes, chambres intérieures qui s''y rattachaient, ainsi que de la chambre du propitiatoire;'),
('1ch',28,12,'crampon1923','le plan de tout ce qu''il avait dans l''esprit touchant les parvis de la maison de Yahweh et toutes les chambres à l''entour, pour les trésors de la maison de Dieu et les trésors du sanctuaire,'),
('1ch',28,13,'crampon1923','pour les classes des prêtres et des lévites, pour toute l''œuvre du service de la maison de Yahweh, et pour tous les ustensiles employés au service de la maison de Yahweh;'),
('1ch',28,14,'crampon1923','le modèle des ustensiles d''or, avec le poids de l''or, pour tous les ustensiles de chaque service; le modèle de tous les ustensiles d''argent, avec le poids, pour tous les ustensiles de chaque service;'),
('1ch',28,15,'crampon1923','le poids des chandeliers d''or et de leurs lampes d''or, selon le poids de chaque chandelier et de ses lampes, et le poids des chandeliers d''argent, selon le poids de chaque chandelier;'),
('1ch',28,16,'crampon1923','le poids de l''or pour les tables des pains de proposition, pour chaque table, et le poids de l''argent pour les tables d''argent;'),
('1ch',28,17,'crampon1923','le modèle des fourchettes, des aiguières et des coupes d''or pur; des amphores d''or, avec le poids de chaque amphore; des amphores d''argent, avec le poids de chaque amphore;'),
('1ch',28,18,'crampon1923','de l''autel des parfums en or épuré, selon son poids; le modèle du char de Dieu, des Chérubins d''or qui étendent leurs ailes et couvrent l''arche de l''alliance de Yahweh.'),
('1ch',28,19,'crampon1923','" Tout cela, dit David, tous les ouvrages de ce modèle, Yahweh m''en a instruit par un écrit qui, de sa main, est venu à moi. "'),
('1ch',28,20,'crampon1923','David dit à Salomon, son fils: " Sois fort et courageux! A l''œuvre! Ne crains point et ne t''effraie point; car Yahweh Dieu, mon Dieu, sera avec toi; il ne te délaissera pas et ne t''abandonnera pas, jusqu''à l''achèvement de tout l''ouvrage pour le service de la maison de Yahweh.'),
('1ch',28,21,'crampon1923','Et voici avec toi les classes des prêtres et des lévites pour tout le service de la maison de Dieu; avec toi, pour toute espèce de travaux, sont aussi tous les hommes dévoués et habiles, pour tous les ouvrages; enfin, les chefs et le peuple pour l''exécution de tous tes ordres. "'),
('1ch',29,1,'crampon1923','Le roi David dit à toute l''assemblée: " Mon fils Salomon, le seul que Dieu ait choisi, est jeune et faible, et l''ouvrage est considérable; car ce palais n''est pas pour un homme, mais pour Yahweh Dieu.'),
('1ch',29,2,'crampon1923','J''ai mis tous mes efforts à préparer pour la maison de mon Dieu de l''or pour les objets d''or, de l''argent pour les objets d''argent, de l''airain pour les objets d''airain, du fer pour les objets de fer, du bois pour les objets de bois, des pierres d''onyx et des pierres à enchâsser, des pierres d''ornement et de diverses couleurs, toutes sortes de pierres précieuses et des pierres de marbre en abondance.'),
('1ch',29,3,'crampon1923','De plus, dans mon affection pour la maison de Dieu, l''or et l''argent que je possède en propre, je le donne à la maison de mon Dieu, outre tout ce que j''ai préparé pour la maison du sanctuaire:'),
('1ch',29,4,'crampon1923','trois mille talents d''or, d''or d''Ophir, et sept mille talents d''argent épuré, pour en revêtir les parois des chambres,'),
('1ch',29,5,'crampon1923','l''or pour les objets d''or, l''argent pour les objets d''argent, et pour tous les travaux de la main des ouvriers. Qui veut aujourd''hui remplir spontanément sa main d''offrandes pour Yahweh? "'),
('1ch',29,6,'crampon1923','Les chefs des familles, les princes des tribus d''Israël, les chefs de milliers et de centaines, ainsi que les intendants du roi, firent volontairement des offrandes.'),
('1ch',29,7,'crampon1923','Ils donnèrent pour le travail de la maison de Dieu cinq mille talents d''or, dix mille dariques, dix mille talents d''argent, dix-huit mille talents d''airain et cent mille talents de fer.'),
('1ch',29,8,'crampon1923','Ceux qui possédaient des pierres précieuses les donnèrent, pour le trésor de la maison de Yahweh, entre les mains de Jahiel, le Gersonite.'),
('1ch',29,9,'crampon1923','Le peuple se réjouit de leurs offrandes volontaires, car c''était d''un cœur parfait qu''ils faisaient ces offrandes volontaires à Yahweh; le roi David en eut aussi une grande joie.'),
('1ch',29,10,'crampon1923','David bénit Yahweh aux yeux de toute l''assemblée; et David dit: " Béni soyez-vous, d''éternité en éternité, Yahweh, Dieu de notre père d''Israël!'),
('1ch',29,11,'crampon1923','A vous, Yahweh, la grandeur, la puissance, la magnificence, la splendeur et la gloire, car tout, au ciel et sur la terre, vous appartient; à vous, Yahweh, la royauté; à vous de vous élever souverainement au-dessus de tout.'),
('1ch',29,12,'crampon1923','De vous dérivent la richesse et la gloire; vous dominez sur tout; dans votre main est la force et la puissance, et à votre main il appartient de donner à toutes choses grandeur et solidité.'),
('1ch',29,13,'crampon1923','Maintenant donc, ô notre Dieu, nous vous louons et nous célébrons votre nom glorieux.'),
('1ch',29,14,'crampon1923','Car qui suis-je et qui est mon peuple, que nous ayons le pouvoir et la force de faire volontairement de pareilles offrandes? Tout vient de vous, et nous vous donnons ce que nous avons reçu de votre main.'),
('1ch',29,15,'crampon1923','Car nous sommes devant vous des étrangers et des colons, comme l''étaient tous nos pères; nos jours sur la terre sont comme l''ombre, et il n''y a pas d''espoir.'),
('1ch',29,16,'crampon1923','Yahweh, notre Dieu, toutes ces richesses que nous avons préparées pour vous bâtir une maison pour votre saint nom, c''est de votre main qu''elles viennent, et c''est à vous que tout appartient.'),
('1ch',29,17,'crampon1923','Je sais, ô mon Dieu, que vous sondez les cœurs et que vous aimez la droiture; aussi j''ai fait volontairement toutes ces offrandes dans la droiture de mon cœur, et je vois maintenant avec joie votre peuple qui se trouve ici vous faire volontairement ses offrandes.'),
('1ch',29,18,'crampon1923','Yahweh, Dieu d''Abraham, d''Isaac et d''Israël, nos pères, gardez à jamais cette disposition comme la forme des sentiments du cœur de votre peuple, et tenez leur cœur tourné vers vous.'),
('1ch',29,19,'crampon1923','Et à mon fils Salomon donnez un cœur parfait pour observer vos commandements, vos préceptes et vos lois, pour les mettre tous en pratique et pour bâtir le palais pour lequel j''ai fait des préparatifs. "'),
('1ch',29,20,'crampon1923','David dit à toute l''assemblée: " Bénissez donc Yahweh, votre Dieu. " Et toute l''assemblée bénit Yahweh, le Dieu de leurs pères; ils s''inclinèrent et se prosternèrent devant Yahweh et devant le roi.'),
('1ch',29,21,'crampon1923','Le lendemain de ce jour, ils immolèrent des victimes à Yahweh, et offrirent en holocauste à Yahweh mille taureaux, mille béliers et mille agneaux, avec les libations ordinaires, et d''autres sacrifices en grand nombre pour tout Israël;'),
('1ch',29,22,'crampon1923','ils mangèrent et burent ce jour-là devant Yahweh avec une grande joie. Pour la seconde fois, ils proclamèrent roi Salomon, fils de David, et l''oignirent comme chef devant Yahweh; et ils oignirent Sadoc comme grand prêtre.'),
('1ch',29,23,'crampon1923','Salomon s''assit sur le trône de Yahweh comme roi, à la place de David, son père; il prospéra, et tout Israël lui obéit.'),
('1ch',29,24,'crampon1923','Tous les chefs et les vaillants, même tous les fils du roi David, se soumirent au roi Salomon.'),
('1ch',29,25,'crampon1923','Yahweh éleva au plus haut degré la grandeur de Salomon sous les yeux de tout Israël, et il donna à son règne une gloire que n''eut jamais avant lui aucun roi en Israël.'),
('1ch',29,26,'crampon1923','David, fils d''Isaï, régna sur tout Israël.'),
('1ch',29,27,'crampon1923','Le temps qu''il régna sur Israël fut de quarante ans; il régna sept ans à Hébron, et il régna trente-trois ans à Jérusalem.'),
('1ch',29,28,'crampon1923','Il mourut dans une heureuse vieillesse, rassasié de jours, de richesse et de gloire; et Salomon, son fils, régna à sa place.'),
('1ch',29,29,'crampon1923','Les actions du roi David, les premières et les dernières, voici qu''elles sont écrites dans l''histoire de Samuel le voyant, dans l''histoire de Nathan le prophète et dans l''histoire de Gad le voyant,'),
('1ch',29,30,'crampon1923','avec tout son règne et tous ses exploits et les vicissitudes qui lui sont survenues, ainsi qu''à Israël, et à tous les royaumes des autres pays.'),
('2ch',1,1,'crampon1923','Salomon, fils de David, s''affermit dans sa royauté; Yahweh, son Dieu, était avec lui, et il l''éleva à un très haut degré.'),
('2ch',1,2,'crampon1923','Salomon donna des ordres à tout Israël, aux chefs de milliers et de centaines, aux juges et à tous les princes de tout Israël, aux chefs de familles;'),
('2ch',1,3,'crampon1923','et Salomon se rendit avec toute l''assemblée au haut lieu qui était à Gabaon. Là se trouvait la tente de réunion de Dieu, que Moïse, serviteur de Yahweh, avait faite dans le désert;'),
('2ch',1,4,'crampon1923','quant à l''arche de Dieu, David l''avait transportée de Cariathiarim à la place qu''il lui avait préparée, car il avait dressé pour elle une tente à Jérusalem.'),
('2ch',1,5,'crampon1923','L''autel d''airain qu''avait fait Béséléel, fils d''Uri, fils de Hur, se trouvait aussi là, devant le tabernacle de Yahweh. Salomon et l''assemblée cherchèrent Yahweh.'),
('2ch',1,6,'crampon1923','Là, sur l''autel d''airain qui était devant Yahweh, près de la tente de réunion, Salomon offrit mille holocaustes.'),
('2ch',1,7,'crampon1923','La nuit suivante, Dieu apparut à Salomon et lui dit: " Demande ce que tu veux que je te donne. "'),
('2ch',1,8,'crampon1923','Salomon répondit à Dieu: " Vous avez montré une grande bienveillance envers David, mon père, et vous m''avez fait régner à sa place.'),
('2ch',1,9,'crampon1923','Maintenant, Yahweh Dieu, que s''accomplisse votre parole que vous avez dite à David, mon père, puisque vous m''avez fait régner sur un peuple nombreux comme la poussière de la terre!'),
('2ch',1,10,'crampon1923','Accordez-moi donc la sagesse et l''intelligence, afin que je sache me conduire devant votre peuple. Car qui pourrait juger votre peuple, ce peuple si grand? "'),
('2ch',1,11,'crampon1923','Dieu dit à Salomon: " Parce que c''est là ce qui est dans ton cœur, et que tu n''as pas demandé ni des richesses, ni des biens, ni de la gloire, ni la mort de tes ennemis, et que même tu n''as pas demandé de longs jours, et que tu as demandé pour toi la sagesse et l''intelligence pour juger mon peuple sur lequel je t''ai fait régner,'),
('2ch',1,12,'crampon1923','la sagesse et l''intelligence te sont données. Je te donnerai en outre des richesses, des biens et de la gloire, comme n''en a eu aucun roi avant toi, et comme n''en aura aucun après toi. "'),
('2ch',1,13,'crampon1923','Du haut lieu de Gabaon, de devant la tente de réunion, Salomon revint à Jérusalem, et il régna sur Israël.'),
('2ch',1,14,'crampon1923','Salomon rassembla des chars et des cavaliers; il avait quatorze cents chars et douze mille cavaliers, qu''il plaça dans les villes où étaient déposés les chars, et prés du roi à Jérusalem.'),
('2ch',1,15,'crampon1923','Le roi fit que l''argent et l''or étaient à Jérusalem aussi communs que les pierres, et il fit que les cèdres étaient aussi nombreux que les sycomores qui croissent dans la plaine.'),
('2ch',1,16,'crampon1923','C''était de l''Egypte que provenaient les chevaux de Salomon; une caravane de marchands du roi les allait prendre par troupes à un prix convenu;'),
('2ch',1,17,'crampon1923','on faisait monter et sortir d''Egypte un char pour six cents sicles d''argent, et un cheval pour cent cinquante sicles. Ils en faisaient aussi sortir de la même manière, par eux-mêmes, pour tous les rois des Héthéens et pour les rois de Syrie.'),
('2ch',1,18,'crampon1923','Salomon résolut de bâtir une maison au nom de Yahweh, et une maison royale pour lui.'),
('2ch',2,1,'crampon1923','Salomon compta soixante-dix mille hommes pour porter les fardeaux, quatre-vingt mille pour tailler les pierres dans la montagne, et trois mille six cents pour les surveiller.'),
('2ch',2,2,'crampon1923','Salomon envoya dire à Hiram, roi de Tyr: " Comme tu as fait pour David, mon père, à qui tu as envoyé des cèdres afin qu''il se bâtit une maison pour y habiter, fais de même pour moi.'),
('2ch',2,3,'crampon1923','Voici que j''élève une maison au nom de Yahweh, mon Dieu, pour la lui consacrer, pour brûler devant lui le parfum odoriférant, pour présenter continuellement les pains de proposition et pour offrir les holocaustes du matin et du soir, des sabbats, des nouvelles lunes et des fêtes de Yahweh, notre Dieu, selon qu''il est prescrit à Israël pour jamais.'),
('2ch',2,4,'crampon1923','La maison que je vais bâtir doit être grande, car notre Dieu est plus grand que tous les dieux.'),
('2ch',2,5,'crampon1923','Mais qui est capable de lui bâtir une maison, puisque le ciel et le ciel des cieux ne peuvent le contenir? Et qui suis-je pour lui bâtir une maison, si ce n''est pour faire brûler des parfums devant lui?'),
('2ch',2,6,'crampon1923','Et maintenant, envoie-moi un homme habile à travailler l''or et l''argent, l''airain et le fer, la pourpre rouge, le cramoisi et la pourpre violette, et connaissant l''art de la gravure, pour qu''il travaille avec les hommes habiles qui sont auprès de moi en Juda et à Jérusalem, et que David, mon père, a préparés.'),
('2ch',2,7,'crampon1923','Envoie-moi aussi du Liban des bois de cèdre, de cyprès et de santal; car je sais que tes serviteurs savent couper les bois du Liban. Mes serviteurs seront avec tes serviteurs,'),
('2ch',2,8,'crampon1923','pour me préparer du bois en abondance, car la maison que je vais bâtir sera grande et magnifique.'),
('2ch',2,9,'crampon1923','Et voici qu''aux bûcherons qui couperont les bois, à tes serviteurs, je donnerai, pour leur nourriture, vingt mille cors de froment, vingt mille cors d''orge, vingt mille baths de vin et vingt mille baths d''huile. "'),
('2ch',2,10,'crampon1923','Hiram, roi de Tyr, répondit dans une lettre qu''il envoya à Salomon: " C''est parce que Yahweh aime son peuple qu''il t''a établi roi sur eux. "'),
('2ch',2,11,'crampon1923','Et Hiram dit: " Béni soit Yahweh, Dieu d''Israël, qui a fait le ciel et la terre, de ce qu''il a donné au roi David un fils sage, prudent et intelligent, qui va bâtir une maison à Yahweh et une maison royale pour lui!'),
('2ch',2,12,'crampon1923','Et maintenant, je t''envoie un homme habile et intelligent, maître Hiram,'),
('2ch',2,13,'crampon1923','fils d''une femme d''entre les filles de Dan et d''un père Tyrien, habile à travailler l''or et l''argent, l''airain et le fer, les pierres et les bois, la pourpre rouge, la pourpre violette, le cramoisi, le lin fin, à faire toute espèce de gravures, et à élaborer tout plan qui lui sera proposé, de concert avec tes hommes habiles et avec les hommes habiles de mon seigneur David, ton père.'),
('2ch',2,14,'crampon1923','Et maintenant, que mon seigneur envoie à ses serviteurs le froment, l''orge, l''huile et le vin dont il a parlé.'),
('2ch',2,15,'crampon1923','Et nous, nous couperons des bois du Liban, autant que tu en auras besoin; et nous te les expédierons par mer en radeaux jusqu''à Joppé, et toi, tu les feras monter à Jérusalem.'),
('2ch',2,16,'crampon1923','Salomon compta tous les étrangers qui étaient dans le pays d''Israël, d''après le dénombrement qu''avait fait David, son père. On en trouva cent cinquante trois mille six cents.'),
('2ch',2,17,'crampon1923','Et il en prit soixante-dix mille pour les fardeaux, quatre-vingt mille pour tailler les pierres dans la montagne, et trois mille six cents comme surveillants pour faire travailler le peuple.'),
('2ch',3,1,'crampon1923','Salomon commença à bâtir la maison de Yahweh à Jérusalem, sur le mont Moria, qui avait été indiqué à David, son père, au lieu qu''avait préparé David, sur l''aire d''Ornan le Jébuséen.'),
('2ch',3,2,'crampon1923','Il commença à bâtir le deuxième jour du deuxième mois, en la quatrième année de son règne.'),
('2ch',3,3,'crampon1923','Voici les fondements que posa Salomon pour bâtir la maison de Dieu. La longueur, en coudées de l''ancienne mesure, était de soixante coudées, et la largeur de vingt coudées.'),
('2ch',3,4,'crampon1923','Le portique qui était sur le devant de la longueur, répondant à la largeur de la maison, avait vingt coudées de longueur et cent vingt coudées de hauteur; Salomon le couvrit d''or pur à l''intérieur.'),
('2ch',3,5,'crampon1923','Il revêtit la grande maison de bois de cyprès, il la revêtit d''or pur et y fit sculpter des palmes et des chaînettes.'),
('2ch',3,6,'crampon1923','Il revêtit la maison de pierres précieuses pour la décorer, et l''or était de Parvaïm.'),
('2ch',3,7,'crampon1923','Il revêtit d''or la maison, les poutres, les seuils, les murs et les portes, et il fit sculpter des chérubins sur les murs.'),
('2ch',3,8,'crampon1923','Il fit la maison du Saint des saints; sa longueur, répondant à la largeur de la maison, était de vingt coudées, et sa largeur de vingt coudées. Il la revêtit d''or pur, pour une valeur de six cents talents;'),
('2ch',3,9,'crampon1923','et le poids de l''or pour les clous était de cinquante sicles. Il revêtit aussi d''or les chambres hautes.'),
('2ch',3,10,'crampon1923','Il fit dans la maison du Saint des saints deux chérubins, œuvre de sculpture, et on les revêtit d''or.'),
('2ch',3,11,'crampon1923','Les ailes des chérubins avaient ensemble vingt coudées de longueur. Une aile du premier, longue de cinq coudées, touchait au mur de la maison, et l''autre aile, longue de cinq coudées, touchait à l''aile de l''autre chérubin.'),
('2ch',3,12,'crampon1923','Une aile du second chérubin, longue de cinq coudées, touchait au mur de la maison; et l''autre aile, longue de cinq coudées, rejoignait l''aile de l''autre chérubin.'),
('2ch',3,13,'crampon1923','Les ailes de ces chérubins, déployées, avaient vingt coudées. Ils étaient debout sur leurs pieds, la face tournée vers la maison.'),
('2ch',3,14,'crampon1923','Salomon fit un voile de pourpre violette, de pourpre rouge, de cramoisi et de fin lin, et il y broda des chérubins.'),
('2ch',3,15,'crampon1923','Il fit devant la maison deux colonnes de trente-cinq coudées de hauteur, et le chapiteau qui était sur leur sommet avait cinq coudées.'),
('2ch',3,16,'crampon1923','Il fit des chaînettes, comme dans le sanctuaire, et les mit au haut des colonnes, et il fit cent grenades qu''il mit dans les chaînettes.'),
('2ch',3,17,'crampon1923','Il dressa les colonnes sur le devant du temple, l''une à droite, l''autre à gauche; il nomma celle de droite Jachin, et celle de gauche Booz.'),
('2ch',4,1,'crampon1923','Salomon fit un autel d''airain; sa longueur était de vingt coudées, sa largeur de vingt coudées, et sa hauteur de dix coudées.'),
('2ch',4,2,'crampon1923','Il fit la mer d''airain fondu. Elle avait dix coudées d''un bord à l''autre, elle était entièrement ronde; sa hauteur était de cinq coudées, et un cordon de trente coudées mesurait sa circonférence.'),
('2ch',4,3,'crampon1923','Des figures de bœufs l''entouraient au-dessous du bord, dix par coudée, faisant tout le tour de la mer, sur deux rangs; les bœufs étaient fondus avec elle en une seule pièce.'),
('2ch',4,4,'crampon1923','Elle était posée sur douze bœufs, dont trois regardaient le nord, trois regardaient l''occident, trois regardaient le midi et trois regardaient l''orient; la mer était sur eux, et toute la partie postérieure de leur corps était cachée en dedans.'),
('2ch',4,5,'crampon1923','Son épaisseur était d''un palme, et son bord était semblable au bord d''une coupe, à une fleur de lis. Elle pouvait contenir trois mille baths.'),
('2ch',4,6,'crampon1923','Il fit dix bassins, et en plaça cinq à droite et cinq à gauche pour qu''on s''y lave; on y nettoyait ce qui devait être offert en holocauste. La mer était destinée aux purifications des prêtres.'),
('2ch',4,7,'crampon1923','Il fit les dix chandeliers d''or, selon les prescriptions faites à leur égard, et il les plaça dans le Temple, cinq à droite et cinq à gauche.'),
('2ch',4,8,'crampon1923','Il fit dix tables, et il les mit dans le Temple, cinq à droite et cinq à gauche. Il fit cent coupes d''or.'),
('2ch',4,9,'crampon1923','Il fit le parvis des prêtres et la grande cour, avec les portes pour la cour; il couvrit leurs battants d''airain.'),
('2ch',4,10,'crampon1923','Il plaça la mer du côté droit, à l''est, vers le sud.'),
('2ch',4,11,'crampon1923','Hiram fit les pots, les pelles et les coupes. C''est ainsi qu''Hiram acheva l''ouvrage qu''il fit pour le roi Salomon dans la maison de Dieu:'),
('2ch',4,12,'crampon1923','les deux colonnes, les bourrelets et les chapiteaux qui sont sur le sommet des colonnes; les deux treillis pour couvrir les deux bourrelets des chapiteaux qui sont sur le sommet des colonnes;'),
('2ch',4,13,'crampon1923','les quatre cents grenades pour les deux treillis, deux rangées de grenades par treillis, pour couvrir les deux bourrelets des chapiteaux qui sont sur les colonnes.'),
('2ch',4,14,'crampon1923','Il fit les bases; il fit les bassins sur les bases;'),
('2ch',4,15,'crampon1923','la mer et les douze bœufs au-dessous;'),
('2ch',4,16,'crampon1923','les pots, les pelles et les fourchettes. Maître Hiram fit tous ces ustensiles pour le roi Salomon, pour la maison de Yahweh; ils étaient d''airain poli.'),
('2ch',4,17,'crampon1923','Le roi les fit fondre dans la plaine du Jourdain, dans un sol argileux, entre Sochot et Saréda.'),
('2ch',4,18,'crampon1923','Salomon fit tous ces ustensiles en très grande quantité, car le poids de l''airain ne fut pas vérifié.'),
('2ch',4,19,'crampon1923','Salomon fit encore tous les autres ustensiles pour la maison de Dieu: l''autel d''or; les tables sur lesquelles on mettait les pains de proposition;'),
('2ch',4,20,'crampon1923','les chandeliers avec leurs lampes d''or pur, pour que, selon la loi, on les allume devant le sanctuaire;'),
('2ch',4,21,'crampon1923','les fleurs, les lampes et les mouchettes d''or, d''un or très pur;'),
('2ch',4,22,'crampon1923','les couteaux, les coupes, les tasses et les encensoirs d''or pur, ainsi que les battants d''or pour la porte intérieure de la maison à l''entrée du Saint des saints, et pour la porte de la maison à l''entrée du temple.'),
('2ch',5,1,'crampon1923','Ainsi fut achevé tout l''ouvrage que Salomon fit dans la maison de Yahweh. Et Salomon apporta ce que David, son père, avait consacré, ainsi que l''argent, l''or et tous les vases, et il les déposa dans les trésors de la maison de Dieu.'),
('2ch',5,2,'crampon1923','Alors Salomon assembla à Jérusalem les anciens d''Israël et tous les chefs des tribus, les princes des familles des enfants d''Israël, pour transporter de la cité de David, c''est-à-dire de Sion, l''arche de l''alliance de Yahweh.'),
('2ch',5,3,'crampon1923','Tous les hommes d''Israël se réunirent auprès du roi pour la fête, qui eut lieu le septième mois.'),
('2ch',5,4,'crampon1923','Lorsque tous les anciens d''Israël furent arrivés, les fils de Lévi portèrent l''arche.'),
('2ch',5,5,'crampon1923','Ils transportèrent l''arche, ainsi que la tente de réunion et tous les ustensiles sacrés qui étaient dans la tente; ce furent les prêtres Lévites qui les transportèrent.'),
('2ch',5,6,'crampon1923','Le roi Salomon et toute l''assemblée d''Israël convoquée auprès de lui, se tenaient devant l''arche. Ils immolèrent des brebis et des bœufs qui ne pouvaient être ni comptés ni nombrés à cause de leur multitude.'),
('2ch',5,7,'crampon1923','Les prêtres portèrent l''arche de l''alliance de Yahweh à sa place, dans le sanctuaire de la maison, dans le Saint des saints, sous les ailes des Chérubins;'),
('2ch',5,8,'crampon1923','et les Chérubins étendaient leurs ailes sur la place de l''arche, et les Chérubins couvraient l''arche et ses barres par-dessus.'),
('2ch',5,9,'crampon1923','Les barres avaient une longueur telle que leurs extrémités se voyaient à distance de l''arche devant le sanctuaire; mais on ne les voyait pas du dehors. L''arche a été là jusqu''à ce jour.'),
('2ch',5,10,'crampon1923','Il n''y avait dans l''arche que les deux tables que Moïse y avait placées à Horeb, lorsque Yahweh fit alliance avec les enfants d''Israël à leur sortie d''Egypte.'),
('2ch',5,11,'crampon1923','Au moment où les prêtres sortirent du Saint, — car tous les prêtres présents s''étaient sanctifiés sans observer l''ordre des classes,'),
('2ch',5,12,'crampon1923','et tous les Lévites qui étaient chantres, Asaph, Héman, Idithun, leurs fils et leurs frères, revêtus de fin lin, se tenaient à l''orient de l''autel avec des cymbales, des cithares et des harpes, ayant auprès d''eux cent vingt prêtres qui sonnaient des trompettes, —'),
('2ch',5,13,'crampon1923','et aussitôt que ceux qui sonnaient des trompettes et ceux qui chantaient, unis dans un même accord pour célébrer et louer Yahweh, firent retentir le son des trompettes, des cymbales et des autres instruments de musique, et célébrèrent Yahweh, en disant: " Car il est bon, car sa miséricorde dure à jamais! " en ce moment la maison, la maison de Yahweh, fut remplie d''une nuée.'),
('2ch',5,14,'crampon1923','Les prêtres ne purent pas y rester pour faire le service, à cause de la nuée; car la gloire de Yahweh remplissait la maison de Dieu.'),
('2ch',6,1,'crampon1923','Alors Salomon dit: " Yahweh veut habiter dans l''obscurité!'),
('2ch',6,2,'crampon1923','Et moi j''ai bâti une maison qui sera votre demeure, et un lieu pour que vous y résidiez à jamais. "'),
('2ch',6,3,'crampon1923','Puis le roi tourna son visage et bénit toute l''assemblée d''Israël, et toute l''assemblée d''Israël était debout.'),
('2ch',6,4,'crampon1923','Et il dit: " Béni soit Yahweh, Dieu d''Israël, qui a parlé par sa bouche à David, mon père, et qui a accompli par ses mains ce qu''il avait déclaré, en disant:'),
('2ch',6,5,'crampon1923','Depuis le jour où j''ai fait sortir du pays d''Egypte mon peuple, je n''ai pas choisi de ville, parmi toutes les tribus d''Israël, pour qu''on y bâtisse une maison où réside mon nom, et je n''ai pas choisi d''homme pour qu''il fût chef de mon peuple d''Israël;'),
('2ch',6,6,'crampon1923','mais j''ai choisi Jérusalem pour que mon nom y réside, et j''ai choisi David pour qu''il règne sur mon peuple d''Israël.'),
('2ch',6,7,'crampon1923','David, mon père, avait l''intention de bâtir une maison au nom de Yahweh, Dieu d''Israël;'),
('2ch',6,8,'crampon1923','mais Yahweh dit à David, mon père: Puisque tu as l''intention de bâtir une maison à mon nom, tu as bien fait d''avoir eu cette intention.'),
('2ch',6,9,'crampon1923','Seulement ce ne sera pas toi qui bâtiras la maison; ce sera ton fils, sorti de tes entrailles, qui bâtira la maison à mon nom.'),
('2ch',6,10,'crampon1923','Yahweh a accompli la parole qu''il avait prononcée: je me suis élevé à la place de David, mon père, et je me suis assis sur le trône d''Israël, comme Yahweh l''avait dit, et j''ai bâti la maison de Yahweh, Dieu d''Israël.'),
('2ch',6,11,'crampon1923','Et j''y ai placé l''arche où se trouve l''alliance de Yahweh, alliance qu''il a faite avec les enfants d''Israël. "'),
('2ch',6,12,'crampon1923','Salomon se plaça devant l''autel de Yahweh, en face de toute l''assemblée d''Israël, et il étendit ses mains.'),
('2ch',6,13,'crampon1923','Car Salomon avait fait une tribune d''airain et l''avait dressée au milieu du parvis; sa longueur était de cinq coudées, sa largeur de cinq coudées, et sa hauteur de trois coudées. Il y monta et, s''étant mis à genoux en face de toute l''assemblée d''Israël, il étendit ses mains vers le ciel,'),
('2ch',6,14,'crampon1923','et dit: " Yahweh, Dieu d''Israël, il n''y a point de Dieu semblable à vous dans les cieux et sur la terre; à vous, qui gardez l''alliance et la miséricorde envers vos serviteurs qui marchent de tout leur cœur en votre présence;'),
('2ch',6,15,'crampon1923','comme vous avez gardé à votre serviteur David, mon père, ce que vous lui avez dit; ce que vous avez déclaré de votre bouche, vous l''avez accompli par votre main, comme on le voit en ce jour.'),
('2ch',6,16,'crampon1923','Maintenant, Yahweh, Dieu d''Israël, observez, en faveur de votre serviteur David, mon père, ce que vous lui avez dit, en ces termes: " Il ne te manquera jamais devant moi un descendant qui siège sur le trône d''Israël, pourvu que tes fils prennent garde à leur voie, en marchant dans ma loi comme tu as marché devant moi.'),
('2ch',6,17,'crampon1923','Et maintenant, Yahweh, Dieu d''Israël, qu''elle s''accomplisse la parole que vous avez dite à votre serviteur David!'),
('2ch',6,18,'crampon1923','Mais est-il donc vrai que Dieu habite avec l''homme sur la terre? Voici que le ciel et le ciel des cieux ne peuvent vous contenir: combien moins cette maison que j''ai bâtie?'),
('2ch',6,19,'crampon1923','Cependant, Yahweh, mon Dieu, soyez attentif à la prière de votre serviteur et à sa supplication, en écoutant le cri joyeux et la prière que votre serviteur prononce devant vous,'),
('2ch',6,20,'crampon1923','en tenant vos yeux ouverts jour et nuit sur cette maison, sur le lieu dont vous avec dit que vous mettriez là votre nom, en écoutant la prière que votre serviteur fait en ce lieu.'),
('2ch',6,21,'crampon1923','Ecoutez les supplications de votre serviteur et de votre peuple d''Israël, lorsqu''ils prieront en ce lieu. Ecoutez du lieu de votre demeure, du ciel, écoutez et pardonnez.'),
('2ch',6,22,'crampon1923','Si quelqu''un pèche contre son prochain, et qu''on lui fasse prêter un serment, s''il vient jurer devant votre autel, dans cette maison,'),
('2ch',6,23,'crampon1923','écoutez-le du ciel, agissez, et jugez vos serviteurs, condamnant le coupable et faisant retomber sa conduite sur sa tête, déclarant juste l''innocent, et lui rendant selon son innocence.'),
('2ch',6,24,'crampon1923','Quand votre peuple d''Israël sera battu devant l''ennemi, parce qu''il aura péché contre vous, s''ils reviennent et rendent gloire à votre nom, s''ils vous adressent des prières et des supplications dans cette maison,'),
('2ch',6,25,'crampon1923','écoutez-les du ciel, pardonnez le péché de votre peuple d''Israël, et ramenez-les dans le pays que vous leur avez donné, à eux et à leurs pères.'),
('2ch',6,26,'crampon1923','Quand le ciel sera fermé et qu''il n''y aura pas de pluie, parce qu''ils auront péché contre vous, s''ils prient dans ce lieu et rendent gloire à votre nom, et s''ils se détournent de leurs péchés, parce que vous les aurez affligés,'),
('2ch',6,27,'crampon1923','écoutez-les du ciel, pardonnez les péchés de vos serviteurs et de votre peuple d''Israël, en leur enseignant la bonne voie dans laquelle ils doivent marcher, et faites tomber la pluie sur la terre que vous avez donnée pour héritage à votre peuple.'),
('2ch',6,28,'crampon1923','Quand la famine sera dans le pays, quand il y aura la peste, quand il y aura la rouille, la nielle, la sauterelle, le hasil; quand l''ennemi assiégera votre peuple dans le pays, dans ses portes, quand il y aura fléau et maladie quelconques,'),
('2ch',6,29,'crampon1923','si un homme, si tout votre peuple d''Israël fait entendre des prières et des supplications, et que chacun, reconnaissant sa plaie et sa douleur, étende ses mains vers cette maison,'),
('2ch',6,30,'crampon1923','écoutez-le du ciel, du lieu de votre demeure, et pardonnez; rendez à chacun selon toutes ses voies, vous qui connaissez son cœur, — car seul vous connaissez les cœurs des enfants des hommes, —'),
('2ch',6,31,'crampon1923','afin qu''ils vous craignent en marchant dans vos voies, tous les jours qu''ils vivront sur la face du pays que vous avez donné à leurs pères.'),
('2ch',6,32,'crampon1923','Quant à l''étranger, qui n''est pas de votre peuple d''Israël, mais qui viendra d''un pays lointain à cause de votre grand nom, de votre main forte et de votre bras étendu, quand il viendra prier dans cette maison,'),
('2ch',6,33,'crampon1923','écoutez-le du ciel, du lieu de votre demeure, et agissez selon tout ce que vous demandera l''étranger, afin que tous les peuples de la terre connaissent votre nom, pour vous craindre, comme votre peuple d''Israël, et qu''ils sachent que votre nom est appelé sur cette maison que j''ai bâtie.'),
('2ch',6,34,'crampon1923','Quand votre peuple sortira pour combattre son ennemi, en suivant la voie dans laquelle vous les aurez envoyés, s''ils vous adressent des prières, le visage tourné vers cette ville que vous avez choisie et vers la maison que j''ai bâtie à votre nom,'),
('2ch',6,35,'crampon1923','écoutez du ciel leur prière et leur supplication, et rendez-leur justice.'),
('2ch',6,36,'crampon1923','Quand ils pécheront contre vous — car il n''y a pas d''homme qui ne pèche, — et quand, irrité contre eux, vous les livrerez à l''ennemi, et que leur vainqueur les emmènera captifs dans un pays lointain ou rapproché,'),
('2ch',6,37,'crampon1923','s''ils rentrent en eux-mêmes dans le pays où ils seront captifs, s''ils reviennent à vous et vous adressent des supplications dans le pays de leur captivité, en disant: Nous avons péché, nous avons fait l''iniquité, nous avons commis le crime;'),
('2ch',6,38,'crampon1923','s''ils reviennent à vous de tout leur cœur et de toute leur âme, dans le pays de leur captivité où on les aura emmenés captifs, s''ils vous adressent des prières le visage tourné vers le pays que vous avez donné à leurs pères, vers la ville que vous avez choisie et vers la maison que j''ai bâtie à votre nom,'),
('2ch',6,39,'crampon1923','écoutez du ciel, du lieu de votre demeure, leur prière et leur supplication, et faites-leur droit, et pardonnez à votre peuple ses transgressions contre vous.'),
('2ch',6,40,'crampon1923','Maintenant, ô mon Dieu, que vos yeux soient ouverts et vos oreilles attentives à la prière faite en ce lieu!'),
('2ch',6,41,'crampon1923','Maintenant, Yahweh Dieu, levez-vous, venez à votre lieu de repos, vous et l''arche de votre force! Que vos prêtres, Yahweh Dieu, soient revêtus de salut, et que vos saints jouissent du bonheur!'),
('2ch',6,42,'crampon1923','Yahweh Dieu, ne repoussez pas la face de votre oint; souvenez-vous des grâces accordées à David, votre serviteur. "'),
('2ch',7,1,'crampon1923','Lorsque Salomon eut achevé de prier, le feu descendit du ciel et consuma l''holocauste et les victimes, et la gloire de Yahweh remplit la maison.'),
('2ch',7,2,'crampon1923','Les prêtres ne pouvaient entrer dans la maison de Yahweh, car la gloire de Yahweh remplissait sa maison.'),
('2ch',7,3,'crampon1923','Tous les enfants d''Israël virent descendre le feu et la gloire de Yahweh sur la maison et, tombant le visage contre terre sur le pavé, ils se prosternèrent et louèrent Yahweh, en disant: " Car il est bon, car sa miséricorde dure à jamais! "'),
('2ch',7,4,'crampon1923','Le roi et tout le peuple offrirent des sacrifices devant Yahweh.'),
('2ch',7,5,'crampon1923','Le roi Salomon immola, pour le sacrifice, vingt deux mille bœufs et cent vingt mille brebis. C''est ainsi que le roi et tout le peuple firent la dédicace de la maison de Dieu.'),
('2ch',7,6,'crampon1923','Les prêtres se tenaient à leurs postes, et les lévites aussi avec les instruments de musique de Yahweh que le roi David avait faits pour louer Yahweh, " car sa miséricorde dure à jamais! " lorsqu''il célébra Yahweh par leur ministère. Les prêtres sonnaient des trompettes vis-à-vis d''eux, et tout Israël était debout.'),
('2ch',7,7,'crampon1923','Salomon consacra le milieu du parvis qui est devant la maison de Yahweh; car il offrit là les holocaustes et les graisses des sacrifices pacifiques, parce que l''autel d''airain qu''il avait fait ne pouvait contenir l''holocauste, l''oblation et les graisses.'),
('2ch',7,8,'crampon1923','Salomon célébra la fête en ce temps-là pendant sept jours, et tout Israël avec lui, très grande multitude venue depuis l''entrée d''Emath jusqu''au torrent d''Egypte.'),
('2ch',7,9,'crampon1923','Le huitième jour, ils tinrent l''assemblée de clôture; car ils avaient fait la dédicace de l''autel pendant sept jours, et la fête pendant sept jours.'),
('2ch',7,10,'crampon1923','Et le vingt troisième jour du septième mois, Salomon renvoya dans ses tentes le peuple joyeux et le cœur content pour le bien que Yahweh avait fait à David, à Salomon et à Israël, son peuple.'),
('2ch',7,11,'crampon1923','Salomon acheva la maison de Yahweh et la maison du roi, et il mena à bien tout ce qui lui était venu à l''esprit de faire dans la maison de Yahweh et dans la maison du roi.'),
('2ch',7,12,'crampon1923','Et Yahweh lui apparut pendant la nuit et lui dit: " J''ai exaucé ta prière et j''ai choisi ce lieu comme la maison où l''on m''offrira des sacrifices.'),
('2ch',7,13,'crampon1923','Quand je fermerai le ciel et qu''il n''y aura pas de pluie, quand j''ordonnerai aux sauterelles de dévorer le pays, ou quand j''enverrai la peste dans mon peuple,'),
('2ch',7,14,'crampon1923','si mon peuple, sur lequel est invoqué mon nom, s''humilie, prie et cherche ma face, et s''il se détourne de ses mauvaises voies, je l''écouterai du ciel, je lui pardonnerai son péché et je guérirai son pays.'),
('2ch',7,15,'crampon1923','Maintenant, mes yeux seront ouverts et mes oreilles attentives à la prière faite en ce lieu.'),
('2ch',7,16,'crampon1923','Maintenant je choisis et je sanctifie cette maison, pour que mon nom y réside à jamais, et là seront à jamais mes yeux et mon cœur.'),
('2ch',7,17,'crampon1923','Et toi, si tu marches devant moi comme a marché David, ton père, mettant en pratique tout ce que je t''ai prescrit, et si tu observes mes lois et mes ordonnances,'),
('2ch',7,18,'crampon1923','j''affermirai le trône de ta royauté, selon l''alliance que j''ai conclue avec David, ton père, en disant: il ne te manquera jamais un descendant qui règne en Israël.'),
('2ch',7,19,'crampon1923','Mais si vous vous détournez, si vous abandonnez mes lois et mes commandements que j''ai mis devant vous, et si vous allez servir d''autres dieux et vous prosterner devant eux,'),
('2ch',7,20,'crampon1923','je les arracherai de mon pays que je leur ai donné; cette maison que j''ai consacrée à mon nom, je la rejetterai de devant ma face, et j''en ferai un sujet de sarcasme et de raillerie parmi tous les peuples.'),
('2ch',7,21,'crampon1923','Cette maison qui était si haut placée sera un sujet de stupeur pour quiconque passera près d''elle, et il dira: Pourquoi Yahweh a-t-il ainsi traité ce pays et cette maison?'),
('2ch',7,22,'crampon1923','Et l''on répondra: Parce qu''ils ont abandonné Yahweh, le Dieu de leurs pères, qui les a fait sortir du pays d''Egypte, et que, s''attachant à d''autres dieux, ils se sont prosternés devant eux et les ont servis; voilà pourquoi il a fait venir sur eux tous ces maux. "'),
('2ch',8,1,'crampon1923','Au bout de vingt ans, quand Salomon eut bâti la maison de Yahweh et sa propre maison,'),
('2ch',8,2,'crampon1923','il reconstruisit les villes que lui avait données Hiram, et y établit des enfants d''Israël.'),
('2ch',8,3,'crampon1923','Salomon marcha contre Emath-Soba, et s''en empara.'),
('2ch',8,4,'crampon1923','Il bâtit Thadmor dans le désert et toutes les villes servant de magasins qu''il bâtit dans le pays d''Emath.'),
('2ch',8,5,'crampon1923','Il bâtit Béthoron la haute et Béthoron la basse, villes fortes, ayant des murs, des portes et des barres;'),
('2ch',8,6,'crampon1923','Baalath, et toutes les villes servant de magasins qui appartenaient à Salomon, toutes les villes pour les chars, les villes pour la cavalerie, et tout ce qu''il plut à Salomon de bâtir à Jérusalem, au Liban et dans tout le pays soumis à sa domination.'),
('2ch',8,7,'crampon1923','Tout le peuple, qui était resté des Héthéens, des Amorrhéens, des Phérézéens, des Hévéens et des Jébuséens, ne faisant point partie d''Israël,'),
('2ch',8,8,'crampon1923','savoir, leurs descendants, qui étaient restés après eux dans le pays et que n''avaient pas détruits les enfants d''Israël, Salomon les leva comme gens de corvée, ce qu''ils ont été jusqu''à ce jour.'),
('2ch',8,9,'crampon1923','Mais Salomon ne fit esclave pour ses travaux aucun des enfants d''Israël, car ils étaient des hommes de guerre, les chefs de ses officiers, les commandants de ses chars et de sa cavalerie.'),
('2ch',8,10,'crampon1923','Les chefs des inspecteurs du roi Salomon étaient au nombre de deux cent cinquante, chargés de commander au peuple.'),
('2ch',8,11,'crampon1923','Salomon fit monter la fille de Pharaon de la cité de David dans la maison qu''il lui avait bâtie; car il dit: " Ma femme n''habitera pas dans la maison de David, roi d''Israël, parce que ces lieux sont saints, dans lesquels est entrée l''arche de Dieu. "'),
('2ch',8,12,'crampon1923','Alors Salomon offrit à Yahweh des holocaustes sur l''autel de Yahweh, qu''il avait construit devant le portique,'),
('2ch',8,13,'crampon1923','offrant chaque jour ce qui était prescrit par Moïse, ainsi qu''aux sabbats, aux nouvelles lunes et aux fêtes, trois fois l''année, à la fête des azymes, à la fête des semaines et à la fête des tabernacles.'),
('2ch',8,14,'crampon1923','Il établit, selon que l''avait réglé David, son père, les classes des prêtres dans leur service, les lévites dans leurs fonctions pour célébrer Yahweh et faire le service devant les prêtres selon l''ordre de chaque jour, et les portiers selon leurs classes, pour chaque porte; car ainsi l''avait ordonné David, homme de Dieu.'),
('2ch',8,15,'crampon1923','On ne s''écarta pas des prescriptions du roi au sujet des prêtres et des lévites, quel qu''en fût l''objet, et spécialement en ce qui concernait les trésors.'),
('2ch',8,16,'crampon1923','Ainsi fut préparée toute l''œuvre de Salomon, jusqu''au jour de la fondation de la maison de Yahweh et jusqu''à son achèvement. La maison de Yahweh fut achevée.'),
('2ch',8,17,'crampon1923','Salomon partit alors pour Asiongaber et pour Ailath, sur les bords de la mer, dans le pays d''Edom.'),
('2ch',8,18,'crampon1923','Et Hiram lui envoya par ses serviteurs des vaisseaux et des serviteurs connaissant la mer. Ils allèrent avec les serviteurs de Salomon à Ophir, et ils y prirent quatre cent cinquante talents d''or, qu''ils apportèrent au roi Salomon.'),
('2ch',9,1,'crampon1923','La reine de Saba, ayant appris la renommée de Salomon, vint pour éprouver Salomon par des énigmes, à Jérusalem, avec un équipage très considérable, et des chameaux portant des aromates, de l''or en grande quantité, et des pierres précieuses. Elle se rendit auprès de Salomon, et elle lui dit tout ce qu''elle avait dans le cœur.'),
('2ch',9,2,'crampon1923','Salomon répondit à toutes ses questions, et il n''y eut rien qui restât caché au roi, sans qu''il pût répondre.'),
('2ch',9,3,'crampon1923','Quand la reine de Saba eut vu la sagesse de Salomon, et la maison qu''il avait bâtie,'),
('2ch',9,4,'crampon1923','et les mets de sa table, et les appartements de ses serviteurs, et les chambres et les vêtements de ses domestiques, et ses échansons et leurs vêtements, et l''escalier par où il montait dans la maison de Yahweh, elle fut hors d''elle-même,'),
('2ch',9,5,'crampon1923','et elle dit au roi: " C''était donc vrai ce que j''ai appris dans mon pays de ce qui te concerne et de ta sagesse!'),
('2ch',9,6,'crampon1923','Je n''en croyais pas le récit avant d''être venue et d''avoir vu de mes yeux, et voici qu''on ne m''avait pas dit la moitié de la grandeur de ta sagesse! Tu surpasses ce que la renommée m''avait fait connaître.'),
('2ch',9,7,'crampon1923','Heureux tes gens, heureux tes serviteurs, qui sont continuellement devant toi et qui entendent ta sagesse!'),
('2ch',9,8,'crampon1923','Béni soit Yahweh, ton Dieu, qui s''est complu en toi et t''a placé sur son trône comme roi pour Yahweh, ton Dieu! C''est parce que ton Dieu aime Israël, pour le faire subsister à jamais, qu''il t''a établi roi sur lui, pour que tu fasses droit et justice. "'),
('2ch',9,9,'crampon1923','Elle donna au roi cent vingt talents d''or, une très grande quantité d''aromates et des pierres précieuses. Il n''y eut plus autant d''aromates tels que ceux que la reine de Saba donna au roi Salomon.'),
('2ch',9,10,'crampon1923','Les serviteurs de Hiram et les serviteurs de Salomon, qui apportaient de l''or d''Ophir, amenèrent aussi du bois de santal et des pierres précieuses.'),
('2ch',9,11,'crampon1923','Le roi fit avec le bois de santal des balustrades pour la maison de Yahweh et pour la maison du roi, et des harpes et des lyres pour les chantres. On n''avait pas vu auparavant de bois semblable dans le pays de Juda.'),
('2ch',9,12,'crampon1923','Le roi Salomon donna à la reine de Saba tout ce qu''elle désira, ce qu''elle demanda, plus qu''elle n''avait apporté au roi. Puis elle s''en retourna et alla dans son pays, elle et ses serviteurs.'),
('2ch',9,13,'crampon1923','Le poids de l''or qui arrivait à Salomon en une année était de six cent soixante-six talents d''or,'),
('2ch',9,14,'crampon1923','outre ce que les marchands et les négociants lui apportaient; tous les rois d''Arabie et les gouverneurs du pays apportaient de l''or et de l''argent à Salomon.'),
('2ch',9,15,'crampon1923','Le roi Salomon fit deux cents grands boucliers d''or battu, employant six cents sicles d''or battu pour chaque bouclier,'),
('2ch',9,16,'crampon1923','et trois cents petits boucliers d''or battu, employant trois cents sicles d''or pour chaque bouclier; et le roi les mit dans la maison de la forêt du Liban.'),
('2ch',9,17,'crampon1923','Le roi fit un grand trône d''ivoire et le revêtit d''or pur.'),
('2ch',9,18,'crampon1923','Ce trône avait six degrés et un marchepied d''or, fixés au trône; il y avait des bras de chaque côté du siège; deux lions se tenaient près des bras,'),
('2ch',9,19,'crampon1923','et douze lions se tenaient là sur les six degrés, six de chaque côte. Il ne s''est fait rien de pareil dans aucun royaume.'),
('2ch',9,20,'crampon1923','Tous les vases à boire du roi Salomon étaient d''or, et toute la vaisselle de la maison de la forêt du Liban était d''or fin. Rien n''était d''argent; on n''en faisait nul cas du temps de Salomon.'),
('2ch',9,21,'crampon1923','Car le roi avait des vaisseaux qui allaient à Tarsis, naviguant avec les serviteurs de Hiram; une fois tous les trois ans, les vaisseaux de Tharsis arrivaient, apportant de l''or et de l''argent, de l''ivoire, des singes et des paons.'),
('2ch',9,22,'crampon1923','Le roi Salomon fut plus grand que tous les rois de la terre par les richesses et par la sagesse.'),
('2ch',9,23,'crampon1923','Tous les rois de la terre cherchaient à voir Salomon, pour entendre la sagesse que Dieu avait mise dans son cœur;'),
('2ch',9,24,'crampon1923','et chacun apportait son présent, des objets d''argent et des objets d''or, des vêtements, des armes, des aromates, des chevaux et des mulets, chaque année.'),
('2ch',9,25,'crampon1923','Salomon avait quatre mille crèches pour les chevaux destinés à ses chars, et douze mille cavaliers, qu''il plaça dans les villes où étaient déposés ses chars, et près du roi à Jérusalem.'),
('2ch',9,26,'crampon1923','Il dominait sur tous les rois, depuis le Fleuve jusqu''au pays des Philistins et jusqu''à la frontière d''Egypte.'),
('2ch',9,27,'crampon1923','Le roi fit que l''argent était à Jérusalem aussi commun que les pierres, et il fit que les cèdres étaient aussi nombreux que les sycomores qui croissent dans la plaine.'),
('2ch',9,28,'crampon1923','On tirait des chevaux pour Salomon de l''Egypte et de tous les pays.'),
('2ch',9,29,'crampon1923','Le reste des actes de Salomon, les premiers et les derniers, cela n''est-il pas écrit dans les Paroles de Nathan le prophète, dans la Prophétie d''Ahias de Silo, et dans les Visions d''Addo le voyant au sujet de Jéroboam, fils de Nabat?'),
('2ch',9,30,'crampon1923','Salomon régna quarante ans à Jérusalem sur tout Israël.'),
('2ch',9,31,'crampon1923','Et Salomon se coucha avec ses pères, et on l''enterra dans la ville de David, son père; et Roboam, son fils, devint roi à sa place.'),
('2ch',10,1,'crampon1923','Roboam se rendit à Sichem, car tout Israël était venu à Sichem pour le faire roi.'),
('2ch',10,2,'crampon1923','Jéroboam, fils de Nabat, ayant appris ce qui se passait, — il était encore en Egypte, où il s''était enfui loin du roi Salomon, — revint d''Egypte,'),
('2ch',10,3,'crampon1923','et on l''envoya chercher. Alors Jéroboam et tout Israël vinrent et parlèrent à Roboam en ces termes:'),
('2ch',10,4,'crampon1923','" Ton père a rendu notre joug dur; maintenant, allège la dure servitude que nous a imposée ton père et le joug pesant qu''il a mis sur nous; et nous te servirons. "'),
('2ch',10,5,'crampon1923','Il leur dit: " Revenez vers moi dans trois jours. " Et le peuple s''en alla.'),
('2ch',10,6,'crampon1923','Le roi Roboam consulta les vieillards qui s''étaient tenus auprès de Salomon, son père, pendant sa vie, en disant: " Que me conseillez-vous de répondre à ce peuple? "'),
('2ch',10,7,'crampon1923','Ils lui parlèrent en disant: " Si tu es bon envers ce peuple, si tu les reçois avec faveur et si tu leur adresses des paroles bienveillantes, ils seront pour toujours tes serviteurs. "'),
('2ch',10,8,'crampon1923','Mais Roboam laissa le conseil que lui donnaient les vieillards, et il consulta les jeunes gens qui avaient grandi avec lui et qui se tenaient devant lui.'),
('2ch',10,9,'crampon1923','Il leur dit: " Que me conseillez-vous de répondre à ce peuple qui me tient ce langage: Allège le joug que nous a imposé ton père? "'),
('2ch',10,10,'crampon1923','Les jeunes gens qui avaient grandi avec lui lui répondirent en disant: " Tu parleras ainsi à ce peuple qui t''a tenu ce langage: Ton père a rendu notre joug pesant; toi, allège-le-nous! Tu leur parleras ainsi: Mon petit doigt est plus gros que les reins de mon père.'),
('2ch',10,11,'crampon1923','Eh bien! mon père vous a chargés d''un joug pesant, et moi je rendrai votre joug plus pesant encore; mon père vous a châtiés avec des fouets, et moi je vous châtierai avec des scorpions. "'),
('2ch',10,12,'crampon1923','Jéroboam et tout le peuple vinrent auprès de Roboam le troisième jour, selon que le roi avait dit: " Revenez vers moi dans trois jours. "'),
('2ch',10,13,'crampon1923','Le roi leur répondit durement. Laissant le conseil des vieillards,'),
('2ch',10,14,'crampon1923','le roi Roboam leur parla selon le conseil des jeunes gens, en ces termes: " Mon père a rendu votre joug pesant, et moi je vous le rendrai plus pesant encore; mon père vous a châtiés avec des fouets, et moi je vous châtierai avec des scorpions. "'),
('2ch',10,15,'crampon1923','Le roi n''écouta donc pas le peuple, car tel était le procédé de Dieu pour accomplir la parole que Yahweh avait dite par Ahias de Silo à Jéroboam, fils de Nabat.'),
('2ch',10,16,'crampon1923','Lorsque tout Israël vit que le roi ne l''écoutait pas, le peuple répondit au roi en ces termes: " Quelle part avons-nous avec David? Nous n''avons point d''héritage avec le fils d''Isaï. Chacun à ses tentes, Israël. Quant à toi, pourvois à ta maison, David! " Et tout Israël s''en alla dans ses tentes.'),
('2ch',10,17,'crampon1923','Ce fut seulement sur les enfants d''Israël qui habitaient les villes de Juda que régna Roboam.'),
('2ch',10,18,'crampon1923','Alors le roi Roboam envoya Aduram, qui était préposé aux impôts; mais Aduram fut lapidé par tout Israël, et il mourut. Et le roi Roboam se hâta de monter sur un char pour s''enfuir à Jérusalem.'),
('2ch',10,19,'crampon1923','C''est ainsi qu''Israël se détacha de la maison de David jusqu''à ce jour.'),
('2ch',11,1,'crampon1923','De retour à Jérusalem, Roboam rassembla la maison de Juda et de Benjamin, cent quatre-vingt mille guerriers d''élite, pour qu''ils combattissent contre Israël, afin de ramener le royaume à Roboam.'),
('2ch',11,2,'crampon1923','Mais la parole de Yahweh fut adressée à Sémaïas, homme de Dieu, en ces termes:'),
('2ch',11,3,'crampon1923','" Parle à Roboam, fils de Salomon, roi de Juda, et à tout Israël en Juda et en Benjamin, en disant:'),
('2ch',11,4,'crampon1923','Ainsi dit Yahweh: Ne montez pas et ne faites pas la guerre à vos frères! Retournez chacun dans votre maison, car c''est par moi que cette chose est arrivée. " Ils écoutèrent les paroles de Yahweh, et ils s''en retournèrent, sans marcher contre Jéroboam.'),
('2ch',11,5,'crampon1923','Roboam résida à Jérusalem, et il bâtit des villes fortes en Juda.'),
('2ch',11,6,'crampon1923','Il bâtit Bethléem, Etam, Thécué,'),
('2ch',11,7,'crampon1923','Bethsur, Socho, Odollam,'),
('2ch',11,8,'crampon1923','Geth, Marésa, Ziph,'),
('2ch',11,9,'crampon1923','Aduram, Lachis, Azéca,'),
('2ch',11,10,'crampon1923','Saraa, Aïalon et Hébron, villes fortes situées en Juda et en Benjamin.'),
('2ch',11,11,'crampon1923','Il mit les forteresses en état de défense et il y plaça des commandants, ainsi que des magasins de vivres, d''huile et de vin.'),
('2ch',11,12,'crampon1923','Il mit dans chaque ville des boucliers et des lances, et il les rendit très fortes. Juda et Benjamin étaient à lui.'),
('2ch',11,13,'crampon1923','Les prêtres et les lévites qui se trouvaient dans tout Israël vinrent de tous leurs territoires se présenter à Roboam;'),
('2ch',11,14,'crampon1923','car les fils de Lévi abandonnèrent leurs pâturages et leurs propriétés, et allèrent en Juda et à Jérusalem, parce que Jéroboam avec ses fils les excluait des fonctions sacerdotales en l''honneur de Yahweh,'),
('2ch',11,15,'crampon1923','et qu''il avait établi des prêtres pour les hauts lieux, pour les boucs et pour les veaux qu''il avait faits.'),
('2ch',11,16,'crampon1923','A leur suite, ceux de toutes les tribus d''Israël qui appliquaient leur cœur à chercher Yahweh, le Dieu d''Israël, vinrent à Jérusalem pour sacrifier à Yahweh, le Dieu de leurs pères.'),
('2ch',11,17,'crampon1923','Ils donnèrent ainsi de la force au royaume de Juda et affermirent Roboam, fils de Salomon, pendant trois ans; car ils marchèrent pendant trois ans dans la voie de David et de Salomon.'),
('2ch',11,18,'crampon1923','Roboam prit pour femme Mahalath, fille de Jérimoth, fils de David, et d''Abihaïl fille d''Eliab, fils d''Isaï.'),
('2ch',11,19,'crampon1923','Elle lui enfanta des fils: Jéhus, Somoria et Zom.'),
('2ch',11,20,'crampon1923','Après elle, il prit Maacha, fille d''Absalom, qui lui enfanta Abia, Ethaï, Ziza et Salomith.'),
('2ch',11,21,'crampon1923','Roboam aimait Maacha, fille d''Absalom, plus que toutes ses femmes et ses concubines; car il eut dix-huit femmes et soixante concubines, et il engendra vingt-huit fils et soixante filles.'),
('2ch',11,22,'crampon1923','Roboam donna le premier rang à Abia, fils de Maacha, pour qu''il fût chef parmi ses frères, car il voulait le faire roi.'),
('2ch',11,23,'crampon1923','Il dispersa habilement tous ses fils dans toutes les contrées de Juda et de Benjamin, dans toutes les villes fortes; il leur fournit des vivres en abondance et demanda pour eux une multitude de femmes.'),
('2ch',12,1,'crampon1923','Lorsque Roboam eut affermi son royaume et acquis de la force, il abandonna la loi de Yahweh, et tout Israël avec lui.'),
('2ch',12,2,'crampon1923','La cinquième année du règne de Roboam, Sésac, roi d''Egypte, monta contre Jérusalem, — parce qu''ils avaient péché contre Yahweh, —'),
('2ch',12,3,'crampon1923','avec mille deux cents chars et soixante mille cavaliers; et l''on ne pouvait compter le peuple qui vint d''Egypte avec lui: Libyens, Sukkiens et Ethiopiens.'),
('2ch',12,4,'crampon1923','Il prit les villes fortes qui appartenaient à Juda, et arriva jusqu''à Jérusalem.'),
('2ch',12,5,'crampon1923','Sémaïas le prophète vint auprès de Roboam et des chefs de Juda qui s''étaient réunis dans Jérusalem à l''approche de Sésac, et il leur dit: " Ainsi dit Yahweh: Vous m''avez abandonné; moi aussi, je vous abandonne entre les mains de Sésac. "'),
('2ch',12,6,'crampon1923','Les chefs d''Israël et le roi s''humilièrent et dirent: " Yahweh est juste! "'),
('2ch',12,7,'crampon1923','Quand Yahweh vit qu''ils s''humiliaient, la parole de Yahweh fut adressée à Sémaïas en ces termes: " Ils se sont humiliés, je ne les détruirai point; dans un peu de temps je leur donnerai la délivrance, et ma colère ne se répandra pas sur Jérusalem par la main de Sésac.'),
('2ch',12,8,'crampon1923','Mais ils lui seront assujettis, afin qu''ils sachent ce que c''est que me servir ou servir les royaumes des pays. "'),
('2ch',12,9,'crampon1923','Sésac, roi d''Egypte, monta contre Jérusalem; il prit les trésors de la maison de Yahweh et les trésors de la maison du roi: il prit tout. Il prit les boucliers d''or que Salomon avait faits.'),
('2ch',12,10,'crampon1923','A leur place, le roi Roboam fit des boucliers d''airain, et il les remit aux mains des chefs des coureurs qui gardaient l''entrée de la maison du roi.'),
('2ch',12,11,'crampon1923','Chaque fois que le roi allait à la maison de Yahweh, les coureurs venaient et les portaient; et ils les rapportaient ensuite dans la chambre des coureurs.'),
('2ch',12,12,'crampon1923','Comme Roboam s''était humilié, la colère de Yahweh se détourna de lui, de sorte qu''il ne fut pas détruit entièrement; et il y eut encore des choses bonnes en Juda.'),
('2ch',12,13,'crampon1923','Le roi Roboam s''affermit dans Jérusalem et régna. Il avait quarante et un ans lorsqu''il devint roi, et il régna dix-sept ans à Jérusalem, ville que Yahweh avait choisie parmi toutes les tribus d''Israël pour y mettre son nom. Sa mère s''appelait Naama, l''Ammonite.'),
('2ch',12,14,'crampon1923','Il fit le mal, parce qu''il n''appliqua pas son cœur à chercher Yahweh.'),
('2ch',12,15,'crampon1923','Les actes de Roboam, les premiers et les derniers, ne sont-ils pas écrits dans les Paroles de Séméïas le prophète et dans celles d''Addo le voyant concernant les généalogies? Il y eut toujours des guerres entre Roboam et Jéroboam.'),
('2ch',12,16,'crampon1923','Roboam se coucha avec ses pères, et il fut enterré dans la ville de David. Abia, son fils, régna à sa place.'),
('2ch',13,1,'crampon1923','La dix-huitième année du roi Jéroboam, Abia devint roi de Juda,'),
('2ch',13,2,'crampon1923','et il régna trois ans à Jérusalem. Sa mère s''appelait Michaïa, fille d''Uriel de Gabaa. Il y eut guerre entre Abia et Jéroboam.'),
('2ch',13,3,'crampon1923','Abia engagea les hostilités avec une armée de vaillants guerriers, quatre cent mille hommes d''élite; et Jéroboam se rangea en bataille contre lui avec huit cent mille hommes d''élite, vaillants guerriers.'),
('2ch',13,4,'crampon1923','Du haut du mont Séméron, qui est dans la montagne d''Ephraïm, Abia se leva et dit: " Ecoutez-moi, Jéroboam et tout Israël!'),
('2ch',13,5,'crampon1923','Ne devez-vous pas savoir que Yahweh, le Dieu d''Israël, a donné pour toujours à David la royauté sur Israël, à lui et à ses fils, par une alliance inviolable?'),
('2ch',13,6,'crampon1923','Et Jéroboam, fils de Nabat, serviteur de Salomon, fils de David, s''est levé et s''est révolté contre son maître.'),
('2ch',13,7,'crampon1923','Des gens de rien, des fils de Bélial, se sont rassemblés auprès de lui et l''on emporté sur Roboam, fils de Salomon. Roboam était encore un jeune homme, d''un cœur timide, et il ne put leur résister.'),
('2ch',13,8,'crampon1923','Et maintenant, vous pensez prévaloir devant le royaume de Yahweh, qui est entre les mains des fils de David; et vous êtes une multitude nombreuse, et avec vous sont les veaux d''or que Jéroboam vous a faits pour dieux.'),
('2ch',13,9,'crampon1923','N''avez-vous pas rejeté les prêtres de Yahweh, les fils d''Aaron et les lévites, et ne vous êtes-vous pas fait des prêtres, comme les peuples des pays? Quiconque est venu avec un jeune taureau et sept béliers, pour se faire consacrer, est devenu prêtre de ce qui n''est point Dieu.'),
('2ch',13,10,'crampon1923','Pour nous, Yahweh est notre Dieu, et nous ne l''avons point abandonné; les prêtres au service de Yahweh sont fils d''Aaron, et les lévites sont à leur ministère.'),
('2ch',13,11,'crampon1923','Chaque matin et chaque soir ils font fumer des holocaustes à Yahweh, ainsi que le parfum odoriférant; ils mettent les pains de proposition sur la table pure, et allument chaque soir le chandelier d''or avec ses lampes; car nous observons l''ordonnance de Yahweh, notre Dieu, et vous, vous l''avez abandonné.'),
('2ch',13,12,'crampon1923','Voici que Dieu et ses prêtres sont avec nous, à notre tête, ainsi que les trompettes sonores, pour les faire retentir contre vous. Enfants d''Israël, ne faites pas la guerre à Yahweh, le Dieu de vos pères, car vous n''auriez aucun succès. "'),
('2ch',13,13,'crampon1923','Jéroboam fit faire un mouvement tournant aux guerriers placés en embuscade pour qu''ils vinssent sur les derrières de l''ennemi, en sorte que ses troupes étaient en face de Juda, et l''embuscade par derrière.'),
('2ch',13,14,'crampon1923','Ceux de Juda se retournèrent, et voici qu''ils étaient attaqués en avant et en arrière. Ils crièrent vers Yahweh, et les prêtres sonnèrent des trompettes.'),
('2ch',13,15,'crampon1923','Les hommes de Juda poussèrent un cri de guerre et, pendant que les hommes de Juda poussaient le cri de guerre, Dieu frappa Jéroboam et tout Israël devant Abia et Juda.'),
('2ch',13,16,'crampon1923','Les enfants d''Israël s''enfuirent devant Juda, et Dieu les livra entre ses mains.'),
('2ch',13,17,'crampon1923','Abia et son peuple en firent un grand carnage, et cinq cent mille hommes d''élite tombèrent morts parmi Israël.'),
('2ch',13,18,'crampon1923','Les enfants d''Israël furent humiliés en ce temps-là, et les enfants de Juda se fortifièrent, parce qu''ils s''étaient appuyés sur Yahweh, le Dieu de leurs pères.'),
('2ch',13,19,'crampon1923','Abia poursuivit Jéroboam et lui prit des villes: Béthel et les villes de sa dépendance, Jésana et les villes de sa dépendance, Ephron et les villes de sa dépendance.'),
('2ch',13,20,'crampon1923','Jéroboam ne recouvra point de force du temps d''Abia; Yahweh le frappa et il mourut.'),
('2ch',13,21,'crampon1923','Mais Abia devint puissant; il prit quatorze femmes et engendra vingt-deux fils et seize filles.'),
('2ch',13,22,'crampon1923','Le reste des actes d''Abia, ses gestes et ses paroles, sont écrits dans les Mémoires du prophète Addo.'),
('2ch',13,23,'crampon1923','Abia se coucha avec ses pères, et on l''enterra dans la ville de David. Asa, son fils, régna à sa place; de son temps, le pays se reposa pendant dix ans.'),
('2ch',14,1,'crampon1923','Asa fit ce qui est bien et droit aux yeux de Yahweh, son Dieu. Il fit disparaître les autels de l''étranger et les hauts lieux,'),
('2ch',14,2,'crampon1923','il brisa les stèles et coupa les aschérahs.'),
('2ch',14,3,'crampon1923','Il ordonna à Juda de rechercher Yahweh, le Dieu de ses pères, et d''accomplir la loi et le précepte.'),
('2ch',14,4,'crampon1923','Il fit disparaître de toutes les villes de Juda les hauts lieux et les statues; et le royaume fut en repos devant lui.'),
('2ch',14,5,'crampon1923','Il bâtit des villes fortes en Juda; car le pays était en repos, et il n''y eut pas de guerre contre lui pendant ces années là, parce que Yahweh lui donna du repos.'),
('2ch',14,6,'crampon1923','Il dit à Juda: " Bâtissons ces villes, entourons-les de murs, de tours, de portes et de serrures; le pays est encore ouvert devant nous; car nous avons recherché Yahweh, notre Dieu; nous l''avons recherché, et il nous a donné du repos de tous cotés. " Ils bâtirent donc et réussirent.'),
('2ch',14,7,'crampon1923','Asa avait une armée de trois cent mille hommes de Juda, portant le bouclier et la lance, et de deux cent quatre-vingt mille de Benjamin, portant le bouclier et tirant de l''arc, tous vaillants hommes.'),
('2ch',14,8,'crampon1923','Zara, l''éthiopien, sortit contre eux avec une armée d''un million d''hommes et trois cents chars, et il s''avança jusqu''à Marésa.'),
('2ch',14,9,'crampon1923','Asa sortit contre lui, et ils se rangèrent en bataille dans la vallée de Séphata, près de Marésa.'),
('2ch',14,10,'crampon1923','Asa cria vers Yahweh, son Dieu, et dit: " Yahweh, vous pouvez secourir celui qui est faible aussi facilement que celui qui est fort; secourez-nous, Yahweh, notre Dieu! Car c''est sur vous que nous nous appuyons, et c''est en votre nom que nous sommes venus contre cette multitude. Yahweh, vous êtes notre Dieu: qu''un homme ne l''emporte pas contre vous! "'),
('2ch',14,11,'crampon1923','Yahweh frappa les Ethiopiens devant Asa et devant Juda, et les Ethiopiens prirent la fuite.'),
('2ch',14,12,'crampon1923','Asa et le peuple qui était avec lui les poursuivirent jusqu''à Gérare, et il tomba un si grand nombre d''Ethiopiens, qu''il n''y eut plus pour eux espoir de rétablissement, car ils furent brisés devant Yahweh et devant son camp. Asa et son peuple firent un très grand butin;'),
('2ch',14,13,'crampon1923','ils frappèrent toutes les villes autour de Gérare, car la terreur de Yahweh était sur elles; ils pillèrent toutes les villes, car il s''y trouvait un grand butin.'),
('2ch',14,14,'crampon1923','Ils frappèrent aussi les tentes des troupeaux, et ils capturèrent un grand nombre de brebis et des chameaux; et ils s''en revinrent à Jérusalem.'),
('2ch',15,1,'crampon1923','L''Esprit de Dieu vint sur Azarias, fils d''Oded,'),
('2ch',15,2,'crampon1923','qui alla au-devant d''Asa et lui dit: " Ecoutez-moi, Asa, et tout Juda et tout Benjamin. Yahweh est avec vous quand vous êtes avec lui; si vous le cherchez, il se laissera trouver par vous; mais si vous l''abandonnez, il vous abandonnera.'),
('2ch',15,3,'crampon1923','Pendant longtemps Israël a été sans vrai Dieu, sans prêtre qui enseignât, sans loi;')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('2ch',15,4,'crampon1923','mais, dans sa détresse, il s''est retourné vers Yahweh, son Dieu; ils l''ont cherché, et s''est laissé trouver par eux.'),
('2ch',15,5,'crampon1923','Dans ces temps-là, point de sécurité pour ceux qui allaient et venaient, car de grandes confusions pesaient sur tous les habitants des pays.'),
('2ch',15,6,'crampon1923','On se heurtait, peuple contre peuple, ville contre ville, parce que Dieu les agitait par toutes sortes de tribulations.'),
('2ch',15,7,'crampon1923','Vous donc, montrez-vous forts, et que vos mains ne faiblissent pas, car il y aura récompense pour vos œuvres. "'),
('2ch',15,8,'crampon1923','En entendant ces paroles, la prophétie d''Oded, le prophète, Asa prit courage; il fit disparaître les abominations de tout le pays de Juda et de Benjamin et des villes qu''il avait prises dans la montagne d''Ephraïm, et restaura l''autel de Yahweh qui était devant le portique de Yahweh.'),
('2ch',15,9,'crampon1923','Il rassembla tout Juda et Benjamin, et ceux d''Ephraïm, de Manassé et de Siméon qui étaient venus séjourner parmi eux; car un grand nombre de gens d''Israël avaient passé de son côté, en voyant que Yahweh, son Dieu, était avec lui.'),
('2ch',15,10,'crampon1923','Ils s''assemblèrent à Jérusalem le troisième mois de la quinzième année du règne d''Asa.'),
('2ch',15,11,'crampon1923','Ce jour-là, ils immolèrent à Yahweh, sur le butin qu''ils avaient amené, sept cents bœufs et sept mille brebis.'),
('2ch',15,12,'crampon1923','Ils prirent l''engagement solennel de chercher Yahweh, le Dieu de leurs pères, de tout leur cœur et de toute leur âme,'),
('2ch',15,13,'crampon1923','et quiconque ne rechercherait pas Yahweh, le Dieu d''Israël, serait mis à mort, le petit comme le grand, l''homme comme la femme.'),
('2ch',15,14,'crampon1923','Ils firent un serment à Yahweh à haute voix, avec des cris d''allégresse, au son des trompettes et des cors;'),
('2ch',15,15,'crampon1923','tout Juda fut dans la joie de ce serment, car ils avaient juré de tout leur cœur; car c''est de leur pleine volonté qu''ils avaient cherché Yahweh, et il s''était laissé trouver par eux; et Yahweh leur donna la paix tout à l''entour.'),
('2ch',15,16,'crampon1923','Le roi Asa ôta même à Maacha, sa mère, la dignité de reine-mère, parce qu''elle avait fait une idole abominable pour Astarté. Asa abattit son idole abominable et, l''ayant réduite en poudre, il la brûla au torrent de Cédron.'),
('2ch',15,17,'crampon1923','Mais les hauts lieux ne disparurent point d''Israël, quoique le cœur d''Asa fut parfait pendant toute sa vie.'),
('2ch',15,18,'crampon1923','Il déposa dans la maison de Dieu les choses consacrées par son père et les choses consacrées par lui-même, de l''argent, de l''or et des vases.'),
('2ch',15,19,'crampon1923','Il n''y eut point de guerre jusqu''à la trente-cinquième année du règne d''Asa.'),
('2ch',16,1,'crampon1923','La trente-sixième année du règne d''Asa, Baasa, roi d''Israël, monta contre Juda, et il bâtit Rama, pour empêcher les gens d''Asa, roi de Juda, de sortir et d''entrer.'),
('2ch',16,2,'crampon1923','Asa tira de l''argent et de l''or des trésors de la maison de Yahweh et de la maison du roi, et il envoya des messagers à Ben-Hadad, roi de Syrie, qui habitait à Damas, pour dire:'),
('2ch',16,3,'crampon1923','" Qu''il y ait une alliance entre moi et toi, comme il y en avait une entre mon père et ton père. Je t''envoie de l''argent et de l''or. Va, romps ton alliance avec Baasa, roi d''Israël, afin qu''il s''éloigne de moi. "'),
('2ch',16,4,'crampon1923','Ben-Hadad écouta le roi Asa; il envoya les chefs de son armée contre les villes d''Israël, et ils battirent Ahion, Dan, Abel-Maïm et toutes les villes à magasins de Nephthali.'),
('2ch',16,5,'crampon1923','Baasa, l''ayant appris, cessa de bâtir Rama, et interrompit ses travaux.'),
('2ch',16,6,'crampon1923','Le roi Asa prit tout Juda, et ils emportèrent les pierres et le bois avec lesquels Baasa construisait Rama; et il bâtit avec elles Gabaa et Maspha.'),
('2ch',16,7,'crampon1923','En ce temps-là, Hanani le voyant vint auprès d''Asa, roi de Juda, et lui dit: " Parce que tu t''es appuyé sur le roi de Syrie et que tu ne t''es pas appuyé sur Yahweh, ton Dieu, à cause de cela, l''armée du roi de Syrie s''est échappée de tes mains.'),
('2ch',16,8,'crampon1923','Les Ethiopiens et les Lybiens ne formaient-ils pas une grande armée, avec des chars, et des cavaliers très nombreux? Et cependant, parce que tu t''étais appuyé sur Yahweh, il les a livrés entre tes mains.'),
('2ch',16,9,'crampon1923','Car les yeux de Yahweh parcourent toute la terre pour soutenir ceux dont le cœur est parfaitement à lui. Tu as donc agi en insensé dans cette affaire, car désormais tu auras des guerres. "'),
('2ch',16,10,'crampon1923','Asa fut irrité contre le voyant, et il le fit mettre en prison, car il était en colère contre lui à cause de ses paroles. Dans le même temps, Asa opprima quelques-uns du peuple.'),
('2ch',16,11,'crampon1923','Et voici que les actes d''Asa, les premiers et les derniers, sont écrits dans le livre des rois de Juda et d''Israël.'),
('2ch',16,12,'crampon1923','Dans la trente-neuvième année de son règne, Asa eut les pieds malades au point d''éprouver de grandes souffrances; mais, même pendant sa maladie, il ne chercha pas Yahweh, mais les médecins.'),
('2ch',16,13,'crampon1923','Asa se coucha avec ses pères, et il mourut la quarante-unième année de son règne.'),
('2ch',16,14,'crampon1923','On l''enterra dans son sépulcre qu''il s''était creusé dans la ville de David; on le coucha sur un lit qu''on avait rempli de parfums et d''aromates préparés selon l''art du parfumeur, et l''on en brûla une quantité très considérable.'),
('2ch',17,1,'crampon1923','Josaphat, fils d''Asa, régna à sa place. Il se fortifia contre Israël:'),
('2ch',17,2,'crampon1923','il mit des troupes dans toutes les villes fortes de Juda, et il mit des garnisons dans le pays de Juda et dans les villes d''Ephraïm dont Asa, son père, s''était emparé.'),
('2ch',17,3,'crampon1923','Yahweh fut avec Josaphat, parce qu''il marcha dans les premières voies de David, son père, et qu''il ne rechercha point les Baals;'),
('2ch',17,4,'crampon1923','mais il rechercha le Dieu de son père et suivit ses commandements, sans imiter les actions d''Israël.'),
('2ch',17,5,'crampon1923','Yahweh affermit le royaume entre ses mains; tout Juda apportait des présents à Josaphat, et il eut en abondance des richesses et de la gloire.'),
('2ch',17,6,'crampon1923','Son courage grandit dans les voies de Yahweh, et il fit encore disparaître de Juda les hauts lieux et les aschéras.'),
('2ch',17,7,'crampon1923','La troisième année de son règne, il envoya ses chefs, Ben-Haïl, Obdias, Zacharias, Nathanaël et Michéas, enseigner dans les villes de Juda,'),
('2ch',17,8,'crampon1923','et avec eux les lévites Séméïas, Nathanias, Zabadias, Asaël, Sémiramoth, Jonathan, Adonias, Thobias, Thobadonias, et, avec ces lévites, les prêtres Elisama et Joram.'),
('2ch',17,9,'crampon1923','Ils enseignèrent dans Juda, ayant avec eux le livre de la loi de Yahweh; ils parcoururent toutes les villes de Juda, et ils enseignèrent parmi le peuple.'),
('2ch',17,10,'crampon1923','La terreur de Yahweh s''empara de tous les royaumes des pays qui environnaient Juda, et ils ne firent pas la guerre à Josaphat.'),
('2ch',17,11,'crampon1923','Des philistins apportèrent à Josaphat des présents et un tribut en argent; les Arabes aussi lui amenèrent du bétail, sept mille sept cents béliers et sept mille sept cents boucs.'),
('2ch',17,12,'crampon1923','Josaphat était en voie de s''élever au plus haut degré de grandeur. Il bâtit en Juda des forteresses et des villes pour servir de magasins;'),
('2ch',17,13,'crampon1923','et il avait beaucoup de provisions dans les villes de Juda, et des guerriers, hommes vaillants, dans Jérusalem.'),
('2ch',17,14,'crampon1923','Voici leur dénombrement, selon leurs familles. De Juda, chefs de milliers: Adna, le chef, et avec lui, trois cent mille vaillants hommes;'),
('2ch',17,15,'crampon1923','à ses côtés, Johanan, le chef, et avec lui, deux cent quatre-vingt mille hommes;'),
('2ch',17,16,'crampon1923','et à ses côtés, Amasias, fils de Zéchri, qui s''était volontairement consacré à Yahweh, et avec lui, deux cent mille vaillants hommes. —'),
('2ch',17,17,'crampon1923','De Benjamin: Eliada, homme vaillant, et avec lui, deux cent mille hommes armés de l''arc et du bouclier;'),
('2ch',17,18,'crampon1923','et à ses côtés, Jozabad, et avec lui, cent quatre-vingt mille hommes armés pour la guerre. —'),
('2ch',17,19,'crampon1923','Tels sont ceux qui étaient au service du roi, outre ceux que le roi avait placés dans les villes fortes, dans tout le territoire de Juda.'),
('2ch',18,1,'crampon1923','Josaphat avait en abondance des richesses et de la gloire, et il s''allia par mariage avec Achab.'),
('2ch',18,2,'crampon1923','Au bout de quelques années, il descendit auprès d''Achab. à Samarie, et Achab tua pour lui et pour le peuple qui était avec lui des brebis et des bœufs en grand nombre, et il l''engagea à monter à Ramoth-en-Galaad.'),
('2ch',18,3,'crampon1923','Achab, roi d''Israël, dit à Josaphat, roi de Juda: " Viendras-tu avec moi à Ramoth-en-Galaad? " Josaphat lui répondit: " Il en sera de moi comme de toi, de mon peuple comme de ton peuple; nous irons l''attaquer avec toi. "'),
('2ch',18,4,'crampon1923','Josaphat dit au roi d''Israël: " Consulte maintenant, je te prie, la parole de Yahweh. "'),
('2ch',18,5,'crampon1923','Le roi d''Israël convoqua les prophètes, au nombre de quatre cents, et leur dit: " Irons-nous attaquer Ramoth-en-Galaad, ou m''en abstiendrai-je? " Ils répondirent: " Monte, et Dieu la livrera entre les mains du roi. "'),
('2ch',18,6,'crampon1923','Mais Josaphat dit: " N''y a-t-il plus ici aucun prophète de Yahweh, par qui nous puissions l''interroger? "'),
('2ch',18,7,'crampon1923','Le roi d''Israël répondit à Josaphat: " Il y a encore un homme par qui l''on pourrait consulter Yahweh; mais je le hais, car il ne prophétise sur moi rien de bon, mais toujours du mal: c''est Michée, fils de Jemla. " Et Josaphat dit: " Que le roi ne parle plus ainsi! "'),
('2ch',18,8,'crampon1923','Alors le roi d''Israël, appelant un eunuque, lui dit: " Fais- venir de suite Michée, fils de Jemla. "'),
('2ch',18,9,'crampon1923','Le roi d''Israël et Josaphat, roi de Juda, étaient assis chacun sur son trône, revêtus de leurs habits royaux; ils étaient assis dans la place, à l''entrée de la porte de Samarie; et tous les prophètes prophétisaient devant eux.'),
('2ch',18,10,'crampon1923','Sédécias, fils de Chanaana, s''était fait des cornes de fer, et il dit: " Ainsi dit Yahweh: Avec ces cornes tu frapperas les Syriens jusqu''à les exterminer. "'),
('2ch',18,11,'crampon1923','Et tous les prophètes prophétisaient de même, en disant: " Monte à Ramoth-en-Galaad et sois vainqueur, car Yahweh la livrera entre les mains du roi! "'),
('2ch',18,12,'crampon1923','Le messager qui était allé appeler Michée lui parla en ces termes: " Voici que les paroles des prophètes sont unanimes pour annoncer du bien au roi; que ta parole soit donc conforme à celle de chacun d''eux: annonce du bien! " Michée répondit:'),
('2ch',18,13,'crampon1923','" Yahweh est vivant! Ce que mon Dieu dira, je l''annoncerai! "'),
('2ch',18,14,'crampon1923','Lorsqu''il fut arrivé près du roi, le roi lui dit: " Michée, irons-nous attaquer Ramoth-en-Galaad, ou m''en abstiendrai-je? " Il répondit: " Montez, et soyez vainqueurs! car ils sont livrés entre vos mains. "'),
('2ch',18,15,'crampon1923','Et le roi lui dit: " Jusqu''à combien de fois t''adjurerai-je de ne me dire que la vérité au nom de Yahweh? "'),
('2ch',18,16,'crampon1923','Michée répondit: " Je vois tout Israël dispersé sur les montagnes, comme les brebis qui m''ont pas de berger; et Yahweh dit: Ces gens n''ont pas de maître: qu''ils retournent en paix, chacun dans sa maison. "'),
('2ch',18,17,'crampon1923','Le roi d''Israël dit à Josaphat: " Ne te l''ai-je pas dit? Il ne prophétise sur moi rien de bon, mais seulement du mal. "'),
('2ch',18,18,'crampon1923','Michée dit: " Ecoutez donc la parole de Yahweh! J''ai vu Yahweh assis sur son trône et toute l''armée du ciel se tenait à sa droite et à sa gauche.'),
('2ch',18,19,'crampon1923','Et Yahweh dit: " Qui trompera Achab, roi d''Israël, pour qu''il monte à Ramoth-en-Galaad et qu''il y périsse? Ils répondirent l''un d''une manière, l''autre d''une autre.'),
('2ch',18,20,'crampon1923','Alors l''esprit vint se tenir devant Yahweh et dit: Moi, je le tromperai. Yahweh lui dit: Comment?'),
('2ch',18,21,'crampon1923','Il répondit: Je sortirai et je serai un esprit de mensonge dans la bouche de tous ses prophètes. Yahweh lui dit: Tu le tromperas, et tu en viendras à bout; sors et fais ainsi!'),
('2ch',18,22,'crampon1923','Voici donc que Yahweh a mis un esprit de mensonge dans la bouche de tes prophètes qui sont là. Et Yahweh a prononcé du mal sur toi. "'),
('2ch',18,23,'crampon1923','Mais Sédécias, fils de Chanaana, s''étant approché, frappa Michée sur la joue, et dit: " Par quel chemin l''esprit de Yahweh est-il sorti de moi pour te parler? "'),
('2ch',18,24,'crampon1923','Michée répondit: " Voici que tu le verras en ce jour-là où tu iras de chambre en chambre pour te cacher. "'),
('2ch',18,25,'crampon1923','Le roi d''Israël dit: " Prenez Michée, et amenez-le à Amon, gouverneur de la ville, et à Joas, fils du roi.'),
('2ch',18,26,'crampon1923','Vous leur direz: Ainsi dit le roi: Mettez cet homme en prison et nourrissez-le du pain d''affliction et de l''eau d''affliction, jusqu''à ce que je revienne en paix. "'),
('2ch',18,27,'crampon1923','Et Michée dit: " Si vraiment tu reviens en paix, Yahweh n''a point parlé par moi. " Il ajouta: " Entendez, vous tous, peuples! "'),
('2ch',18,28,'crampon1923','Le roi d''Israël et Josaphat, roi de Juda, montèrent à Ramoth-en-Galaad.'),
('2ch',18,29,'crampon1923','Le roi d''Israël dit à Josaphat: " Je veux me déguiser pour aller au combat; mais toi, revêts-toi de tes habits. " Et le roi d''Israël se déguisa, et ils allèrent au combat.'),
('2ch',18,30,'crampon1923','Le roi de Syrie avait donné un ordre aux chefs de ses chars, en ces termes: " Vous n''attaquerez ni petit ni grand, mais seulement le roi d''Israël. "'),
('2ch',18,31,'crampon1923','Quand les chefs des chars virent Josaphat, ils dirent: " C''est le roi d''Israël; et ils l''entourèrent pour l''attaquer. Josaphat poussa un cri et Yahweh le secourut, et Dieu attira d''auprès de lui les Syriens.'),
('2ch',18,32,'crampon1923','Quand les chefs des chars virent que ce n''était pas le roi d''Israël, ils se détournèrent de lui.'),
('2ch',18,33,'crampon1923','Alors un homme tira de son arc au hasard et atteignit le roi d''Israël entre les jointures et la cuirasse. Le roi dit à celui qui conduisait le char: " Tourne, et fais-moi sortir du camp, car je suis blessé. "'),
('2ch',18,34,'crampon1923','Le combat devient violent ce jour-là. Le roi d''Israël était tenu debout sur son char en face des Syriens, jusqu''au soir, où il mourut vers le coucher du soleil.'),
('2ch',19,1,'crampon1923','Josaphat, roi de Juda, revint en paix dans sa maison à Jérusalem.'),
('2ch',19,2,'crampon1923','Jéhu, fils de Hanani, le voyant, sortit au-devant de lui, et il dit au roi Josaphat: " Doit-on secourir le méchant, et aimes-tu ceux qui haïssent Yahweh? A cause de cela, est venue sur toi la colère, de par Yahweh.'),
('2ch',19,3,'crampon1923','Pourtant, il s''est trouvé quelque bien en toi, car tu as fait disparaître du pays les aschérahs, et tu as appliqué ton cœur à chercher Dieu. "'),
('2ch',19,4,'crampon1923','Josaphat résida à Jérusalem; et de nouveau il visita le peuple depuis Bersabée jusqu''à la montagne d''Ephraïm, et il les ramena à Yahweh, le Dieu de leurs pères.'),
('2ch',19,5,'crampon1923','Il établit des juges dans le pays, dans toutes les villes fortes de Juda, pour chaque ville.'),
('2ch',19,6,'crampon1923','Et il dit aux juges: " Prenez garde. à ce que vous ferez, car ce n''est pas pour les hommes que vous rendrez la justice, mais c''est pour Yahweh; il sera avec vous quand vous rendrez la justice.'),
('2ch',19,7,'crampon1923','Et moi maintenant, que la crainte de Yahweh soit sur vous; veillez sur vos actes, car il n''y a avec Yahweh, notre Dieu, ni iniquité, ni acception des personnes, ni acceptation des présents. "'),
('2ch',19,8,'crampon1923','A Jérusalem aussi, quand ils revinrent dans cette ville, Josaphat établit, pour les jugements de Yahweh et pour les contestations, des lévites, des prêtres et des chefs de maisons d''Israël.'),
('2ch',19,9,'crampon1923','Et il leur donna des ordres en ces termes: " Vous agirez ainsi en craignant Yahweh, dans la fidélité et l''intégrité du cœur.'),
('2ch',19,10,'crampon1923','Dans toute cause qui viendra devant vous de la part de vos frères établis dans leurs villes, quand il s''agira de distinguer entre meurtre et meurtre, entre loi, commandement, précepte ou ordonnance, vous les éclairerez, afin qu''ils ne se rendent pas coupables envers Yahweh, et que sa colère ne vienne pas sur vous et sur vos frères. Vous agirez ainsi, et vous ne serez point coupables.'),
('2ch',19,11,'crampon1923','Et voici que vous aurez à votre tête Amarias, le grand prêtre, pour toutes les affaires de Yahweh, et Zabadias, fils d''Ismaël, le prince de la maison de Juda, pour toutes les affaires du roi, et vous aurez devant vous les lévites comme officiers. Courage et à l''œuvre! et que Yahweh soit avec vous! "'),
('2ch',20,1,'crampon1923','Après cela, les fils de Moab et les fils d''Ammon, et avec eux des Ammonites, vinrent contre Josaphat pour lui faire la guerre.'),
('2ch',20,2,'crampon1923','Des messagers vinrent en informer Josaphat en disant: " Une multitude nombreuse marche contre toi d''au delà de la mer Morte, de la Syrie, et voici qu''ils sont à Asason-Thamar, qui est Engaddi ".'),
('2ch',20,3,'crampon1923','Effrayé, Josaphat se détermina à recourir à Yahweh, et il publia un jeûne pour tout Juda.'),
('2ch',20,4,'crampon1923','Juda s''assembla pour invoquer Yahweh; même l''on vint de toutes les villes de Juda pour invoquer Yahweh.'),
('2ch',20,5,'crampon1923','Josaphat se tint au milieu de l''assemblée de Juda et de Jérusalem, dans la maison de Yahweh, devant le nouveau parvis,'),
('2ch',20,6,'crampon1923','et il dit: " Yahweh, Dieu de nos pères, n''êtes-vous pas Dieu dans le ciel, et ne dominez-vous pas sur tous les royaumes des nations, et n''avez-vous pas en main la force et la puissance, sans que l''on puisse vous résister?'),
('2ch',20,7,'crampon1923','N''est-ce pas vous, ô notre Dieu, qui avez chassé les habitants de ce pays devant votre peuple d''Israël, et qui l''avez donné pour toujours à la postérité d''Abraham, votre ami.'),
('2ch',20,8,'crampon1923','Ils y ont habité et ils y ont bâti pour vous un sanctuaire à votre nom, en disant:'),
('2ch',20,9,'crampon1923','S''il nous survient une calamité, l''épée du jugement, la peste ou la famine, nous nous tiendrons devant cette maison et devant toi, car ton nom est sur cette maison, nous crierons vers vous du milieu de notre angoisse, et vous écouterez et vous sauverez!'),
('2ch',20,10,'crampon1923','Maintenant, voici les fils d''Ammon et de Moab, et ceux de la montagne de Séïr, chez lesquels vous n''avez pas permis à Israël d''entrer quand il venait du pays d''Egypte, mais dont il s''est détourné sans les détruire;'),
('2ch',20,11,'crampon1923','les voici qui nous récompensent en venant nous chasser de votre héritage, dont vous nous avez donné la possession!'),
('2ch',20,12,'crampon1923','O notre Dieu, ne rendrez-vous pas un jugement contre eux? Car nous sommes sans force devant cette nombreuse multitude qui s''avance contre nous, et nous ne savons que faire, mais nos yeux sont tournés vers vous. "'),
('2ch',20,13,'crampon1923','Et tout Juda se tenait debout devant Yahweh, avec leurs petits enfants, leurs femmes et leurs fils.'),
('2ch',20,14,'crampon1923','Alors, au milieu de l''assemblée, l''esprit de Yahweh fut sur Jahaziel, fils de Zacharias, fils de Banaïas, fils de Jéhiel, fils de Mathanias, lévite, d''entre les fils d''Asaph.'),
('2ch',20,15,'crampon1923','Et Jahaziel dit: " Soyez attentifs, tout Juda et habitants de Jérusalem, et toi, roi Josaphat! Ainsi vous dit Yahweh: Ne craignez point et ne vous effrayez point devant cette nombreuse multitude, car ce n''est pas vous que concerne la guerre, mais Dieu.'),
('2ch',20,16,'crampon1923','Demain descendez contre eux; voici qu''ils monteront par la colline de Sis, et vous les trouverez à l''extrémité de la vallée, en face du désert de Jéruel.'),
('2ch',20,17,'crampon1923','Vous n''aurez pas à combattre en cette affaire: présentez-vous; tenez-vous là, et vous verrez la délivrance que Yahweh vous accordera, ô Juda et Jérusalem. Ne craignez point et ne vous effrayez point; demain, sortez à leur rencontre, et Yahweh sera avec vous. "'),
('2ch',20,18,'crampon1923','Josaphat s''inclina le visage contre terre, et tout Juda et les habitants de Jérusalem tombèrent devant Yahweh pour adorer Yahweh.'),
('2ch',20,19,'crampon1923','Les lévites d''entre les fils de Caath et d''entre les fils de Coré, se levèrent pour célébrer Yahweh, le Dieu d''Israël, d''une voix forte et élevée.'),
('2ch',20,20,'crampon1923','Le lendemain, s''étant levés de bon matin, ils se mirent en marche vers le désert de Thécué. Comme ils partaient, Josaphat se tint debout et dit: " Ecoutez-moi, Juda et habitants de Jérusalem! Confiez-vous dans Yahweh, votre Dieu, et vous serez inébranlables; confiez-vous en ses prophètes, et vous aurez du succès. "'),
('2ch',20,21,'crampon1923','Ensuite, après avoir délibéré avec le peuple, il établit des chantres qui devaient, revêtus d''ornements sacrés et marchant devant l''armée, célébrer Yahweh, en disant: " Louez Yahweh, car sa miséricorde demeure à jamais! "'),
('2ch',20,22,'crampon1923','Au moment où l''on commençait les chants et les louanges, Yahweh dressa des pièges contre les fils d''Ammon et de Moab et contre ceux de la montagne de Séïr, qui étaient venus vers Juda, et ils furent battus.'),
('2ch',20,23,'crampon1923','Les fils d''Ammon et de Moab se tinrent contre les habitants de la montagne de Séïr pour les massacrer et les exterminer et, quand ils en eurent fini avec les habitants de Séïr, ils s''aidèrent les uns les autres à se détruire.'),
('2ch',20,24,'crampon1923','Lorsque Juda fut arrivé sur le poste de guet du désert, ils se tournèrent vers la multitude, et ne virent que des cadavres étendus par terre, sans que personne eût échappé.'),
('2ch',20,25,'crampon1923','Josaphat et son peuple allèrent piller leurs dépouilles, et ils y trouvèrent d''abondantes richesses, des cadavres et des objets précieux, et ils en enlevèrent pour eux jusqu''à ne pouvoir les porter; ils mirent trois jours à piller le butin, car il était considérable.'),
('2ch',20,26,'crampon1923','Le quatrième jour, ils s''assemblèrent dans la vallée de Beraca; car ils y bénirent Yahweh, et c''est pourquoi ils appelèrent ce lieu vallée de Beraca, qui est son nom jusqu''à ce jour.'),
('2ch',20,27,'crampon1923','Tous les hommes de Juda et de Jérusalem, ayant Josaphat à leur tête, se mirent joyeusement en route pour retourner à Jérusalem, car Yahweh les avait remplis de joie en les délivrant de leurs ennemis.'),
('2ch',20,28,'crampon1923','Ils entrèrent à Jérusalem au son des cithares, des harpes et des trompettes, vers la maison de Yahweh.'),
('2ch',20,29,'crampon1923','La terreur de Yahweh s''empara de tous les royaumes des pays, lorsqu''ils apprirent que Yahweh avait combattu contre les ennemis d''Israël.'),
('2ch',20,30,'crampon1923','Et le royaume de Josaphat fut tranquille, et son Dieu lui donna du repos de tous côtés.'),
('2ch',20,31,'crampon1923','Josaphat devint roi de Juda. Il avait trente-cinq ans lorsqu''il devint roi, et il régna vingt-cinq ans à Jérusalem. Sa mère s''appelait Azuba, fille de Selahi.'),
('2ch',20,32,'crampon1923','Il marcha dans la voie d''Asa, son père, et ne s''en détourna point, faisant ce qui est droit aux yeux de Yahweh.'),
('2ch',20,33,'crampon1923','Seulement les hauts lieux ne disparurent point, et le peuple n''avait pas encore fermement attaché son cœur au Dieu de ses pères.'),
('2ch',20,34,'crampon1923','Le reste des actes de Josaphat, les premiers et les derniers, voici qu''ils sont écrits dans les Paroles de Jéhu, fils de Hanani, lesquelles sont insérées dans le livre des rois d''Israël.'),
('2ch',20,35,'crampon1923','Après cela, Josaphat, roi de Juda, s''associa avec Ochosias, roi d''Israël, dont la conduite était criminelle.'),
('2ch',20,36,'crampon1923','Il s''associa avec lui pour construire des vaisseaux destinés à aller à Tharsis, et ils construisirent les vaisseaux à Asiongaber.'),
('2ch',20,37,'crampon1923','Alors Eliézer, fils de Dodau, de Marésa, prophétisa contre Josaphat, en disant: " Parce que tu t''es associé avec Ochozias, Yahweh a détruit ton œuvre. " Et les vaisseaux furent brisés, et ils ne purent aller à Tharsis.'),
('2ch',21,1,'crampon1923','Josaphat se coucha avec ses pères, et il fut enterré avec ses pères dans la ville de David; Joram, son fils, régna à sa place.'),
('2ch',21,2,'crampon1923','Joram avait des frères, fils de Josaphat: Azarias, Jahiel, Zacharias, Azarias, Michaël et Saphatias; ils étaient tous fils de Josaphat, roi de Juda.'),
('2ch',21,3,'crampon1923','Leur père leur avait donné des présents considérables en or et en argent, et en objets de prix, avec des villes fortes en Juda; mais il laissa le royaume à Joram, parce qu''il était le premier-né.'),
('2ch',21,4,'crampon1923','Joram s''établit sur le royaume de son père et, lorsqu''il se fut affermi, il fit mourir par l''épée tous ses frères, et aussi quelques-uns des chefs d''Israël.'),
('2ch',21,5,'crampon1923','Joram avait trente-deux ans lorsqu''il devint roi, et il régna huit ans à Jérusalem.'),
('2ch',21,6,'crampon1923','Il marcha dans la voie des rois d''Israël, comme avait fait la maison d''Achab, car il avait pour femme une fille d''Achab, et il fit ce qui est mal aux yeux de Yahweh.'),
('2ch',21,7,'crampon1923','Mais Yahweh ne voulut pas détruire la maison de David, à cause de l''alliance qu''il avait contractée avec David, et parce qu''il lui avait dit qu''il lui donnerait toujours une lampe, à lui et à ses fils.'),
('2ch',21,8,'crampon1923','De son temps, Edom se révolta contre la domination de Juda et se donna un roi.'),
('2ch',21,9,'crampon1923','Joram se mit en marche avec ses chefs et tous ses chars; s''étant levé de nuit, il battit les Edomites qui l''entouraient et les chefs des chars.'),
('2ch',21,10,'crampon1923','Edom s''affranchit de la domination de Juda, jusqu''à ce jour. Lobna s''affranchit aussi dans le même temps de sa domination, parce qu''il avait abandonné Yahweh, le Dieu de ses pères.'),
('2ch',21,11,'crampon1923','Joram fit même des hauts lieux dans les montagnes de Juda; il poussa à la prostitution les habitants de Jérusalem, et il séduisit Juda.'),
('2ch',21,12,'crampon1923','Il lui vint un écrit de la part du prophète Elie, disant: " Ainsi dit Yahweh, le Dieu de David, ton père: Parce que tu n''as pas marché dans les voies de Josaphat, ton père, et dans les voies d''Asa, roi de Juda,'),
('2ch',21,13,'crampon1923','mais que tu as marché dans la voie des rois d''Israël; parce que tu as poussé à la prostitution Juda et les habitants de Jérusalem, comme la maison d''Achab poussait Israël à la prostitution, et parce que tu as fait mourir tes frères, meilleurs que toi, la maison même de ton père:'),
('2ch',21,14,'crampon1923','voici que Yahweh frappera d''une grande plaie ton peuple, tes fils, tes femmes et tout ce qui t''appartient;'),
('2ch',21,15,'crampon1923','et toi, tu seras frappé de graves maladies, d''une maladie d''entrailles, telle que tes entrailles sortiront par la violence du mal, pendant de nombreux jours ".'),
('2ch',21,16,'crampon1923','Et Yahweh excita contre Joram l''esprit des Philistins et des Arabes voisins des Ethiopiens.'),
('2ch',21,17,'crampon1923','Etant montés en Juda, ils s''y répandirent, pillèrent toutes les richesses qui se trouvaient dans la maison du roi, et emmenèrent aussi ses fils et ses femmes, de sorte qu''il ne lui resta plus d''autre fils que Joachaz, le plus jeune de ses fils.'),
('2ch',21,18,'crampon1923','Après tout cela, Yahweh le frappa dans ses entrailles d''une maladie sans remède.'),
('2ch',21,19,'crampon1923','Les jours s''écoulant, sur la fin de la seconde année, les entrailles de Joram sortirent par la violence de son mal. Il mourut dans de grandes souffrances, et son peuple ne brûla pas de parfums en son honneur, comme il en avait brûlé pour ses pères.'),
('2ch',21,20,'crampon1923','Joram avait trente-deux ans lorsqu''il devint roi, et il régna huit ans à Jérusalem. Il s''en alla sans être regretté, et on l''enterra dans la ville de David, mais non dans les sépulcres des rois.'),
('2ch',22,1,'crampon1923','A la place de Joram, les habitants de Jérusalem firent roi Ochozias, son plus jeune fils; car la troupe qui était venue dans le camp avec les Arabes avait tué tous les plus âgés. C''est ainsi que régna Ochozias, fils de Joram, roi de Juda.'),
('2ch',22,2,'crampon1923','Il avait quarante-deux ans lorsqu''il devint roi, et il régna un an à Jérusalem. Sa mère s''appelait Athalie, fille d''Amri.'),
('2ch',22,3,'crampon1923','Lui aussi marcha dans les voies de la maison d''Achab, car sa mère était sa conseillère pour le faire pécher.'),
('2ch',22,4,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, comme ceux de la maison d''Achab; car après la mort de son père, ils furent ses conseillers pour sa perte.'),
('2ch',22,5,'crampon1923','Ce fut aussi sur leur conseil qu''il se mit en marche et alla avec Joram, fils d''Achab, roi d''Israël, combattre Hazaël, roi de Syrie, à Ramoth-en-Galaad. Les Syriens blessèrent Joram.'),
('2ch',22,6,'crampon1923','Joram s''en retourna pour se faire guérir à Jezrahel des blessures que les Syriens lui avaient faites à Rama, lorsqu''il se battait contre Hazaël, roi de Syrie. Azarias, fils de Joram, roi de Juda, descendit pour voir Joram, fils d''Achab, à Jezrahel, parce qu''il était malade.'),
('2ch',22,7,'crampon1923','Par la volonté de Dieu, ce fut la perte d''Ochozias, que de se rendre auprès de Joram. Lorsqu''il fut arrivé, il sortit avec Joram pour aller vers Jéhu, fils de Namsi, que Yahweh avait oint pour exterminer la maison d''Achab.'),
('2ch',22,8,'crampon1923','Et comme Jehu faisait justice de la maison d''Achab, il trouva les chefs de Juda et les fils des frères d''Ochozias, qui étaient au service d''Ochozias, et il les tua.'),
('2ch',22,9,'crampon1923','Il chercha Ochozias, et on le saisit dans Samarie, où il s''était caché; on l''amena à Jéhu, et on le fit mourir. Puis ils lui donnèrent la sépulture, car ils disaient: " C''est le fils de Josaphat, qui chercha Yahweh de tout son cœur. " Et il n''y eut personne de la maison d''Ochozias qui fût en état de régner.'),
('2ch',22,10,'crampon1923','Athalie, mère d''Ochozias, voyant que son fils était mort, se leva et fit périr toute la race royale de la maison de Juda.'),
('2ch',22,11,'crampon1923','Mais Josabeth, fille du roi, prit Joas, fils d''Ochosias, et l''enleva du milieu des fils du roi, que l''on massacrait; et elle le mit avec sa nourrice dans la chambre des lits. Josabeth, fille du roi Joram, femme du prêtre Joïada, et sœur d''Ochosias, le déroba ainsi aux regards d''Athalie, qui ne le fit point mourir.'),
('2ch',22,12,'crampon1923','Il resta six ans avec eux, caché dans la maison de Dieu; et ce fut Athalie qui régna sur le pays.'),
('2ch',23,1,'crampon1923','La septième année, Joïada, s''étant affermi, prit avec lui comme alliés les centurions Azarias, fils de Jéroham, Ismaël, fils de Johanan, Azarias, fils d''Obed, Maasias, fils d''Adaïas, et Elisaphat, fils de Zechri.'),
('2ch',23,2,'crampon1923','Ils parcoururent Juda et, ayant rassemblé les lévites de toutes les villes de Juda et les chefs de famille d''Israël, ils vinrent à Jérusalem.'),
('2ch',23,3,'crampon1923','Toute l''assemblée fit alliance avec le roi dans la maison de Dieu. Joïada leur dit: " Voici que le fils du roi va régner, comme Yahweh l''a déclaré à l''égard des fils de David.'),
('2ch',23,4,'crampon1923','Voici ce que vous ferez: Le tiers d''entre vous qui entre en service le jour du sabbat, prêtres et lévites, servira comme gardiens des portes;'),
('2ch',23,5,'crampon1923','un tiers servira à la maison du roi, et un tiers servira à la porte de Jésod; tout le peuple sera dans les parvis de la maison de Yahweh.'),
('2ch',23,6,'crampon1923','Que personne n''entre dans la maison de Yahweh, excepté les prêtres et les lévites de service: eux peuvent y entrer, car ils sont saints; et tout le peuple doit garder l''observance de Yahweh.'),
('2ch',23,7,'crampon1923','Les lévites entoureront le roi de toutes parts, chacun les armes à la main et, si quelqu''un entre dans la maison, qu''on le mette à mort; et vous serez près du roi quand il entrera et quand il sortira. "'),
('2ch',23,8,'crampon1923','Les lévites et tout Juda agirent selon tout ce qu''avait ordonné le prêtre Joïada. Ils prirent chacun leurs gens, ceux qui entraient en service et ceux qui sortaient de service le jour du sabbat; car le prêtre Joïada n''avait exempté aucune des divisions.'),
('2ch',23,9,'crampon1923','Le prêtre Joïada remit aux centurions les lances et les boucliers, grands et petits, qui avaient appartenu au roi David, et qui se trouvaient dans la maison de Dieu.'),
('2ch',23,10,'crampon1923','Il fit placer tout le peuple, chacun son arme à la main, depuis le côté droit de la maison jusqu''au côté gauche de la maison, près de l''autel et près de la maison, de manière à entourer le roi.'),
('2ch',23,11,'crampon1923','On fit avancer le fils du roi, on mit sur lui le diadème et le témoignage, et on l''établit roi. Et Joïada et ses fils l''oignirent, et ils dirent: " Vive le roi! "'),
('2ch',23,12,'crampon1923','Lorsqu''Athalie entendit le bruit du peuple, courant et acclamant le roi, elle vint vers le peuple, à la maison de Yahweh.'),
('2ch',23,13,'crampon1923','Elle regarda, et voici que le roi se tenait sur son estrade à l''entrée; près du roi étaient les chefs et les trompettes, et tout le peuple du pays était dans la joie; on sonnait des trompettes, et les chantres avec les instruments de musique donnaient des instructions pour les hymnes de louange. Athalie déchira ses vêtements et dit: " Conspiration! Conspiration! "'),
('2ch',23,14,'crampon1923','Alors le prêtre Joïada fit sortir les centurions, qui étaient à la tête de l''armée, et leur dit: " Faites-la sortir entre les rangs, et que quiconque la suivra soit mis à mort par l''épée! " Car le prêtre avait dit: " Ne la mettez pas à mort dans la maison de Yahweh. "'),
('2ch',23,15,'crampon1923','On lui fit place des deux côtés, et elle se rendit à l''entrée de la porte des chevaux, vers la maison du roi, et c''est là qu''ils la mirent à mort.'),
('2ch',23,16,'crampon1923','Joïada conclut entre lui, tout le peuple et le roi une alliance par laquelle ils devaient être le peuple de Yahweh.'),
('2ch',23,17,'crampon1923','Et tout le peuple entra dans la maison de Baal, et ils la démolirent; ils brisèrent ses autels et ses images, et ils tuèrent devant les autels Mathan, prêtre de Baal.'),
('2ch',23,18,'crampon1923','Joïada mit des gardiens dans la maison de Yahweh, sous l''autorité des prêtres et des lévites, que David avait distribués dans la maison de Yahweh pour qu''ils offrissent des holocaustes à Yahweh, comme il est écrit dans la loi de Moïse, au milieu des réjouissances et des chants, d''après les ordonnances de David.'),
('2ch',23,19,'crampon1923','Il établit les portiers aux portes de la maison de Yahweh, afin qu''il n''y entrât aucune personne souillée en quelque manière.'),
('2ch',23,20,'crampon1923','Il prit les centurions, les hommes considérés, ceux qui avaient autorité sur le peuple et tout le peuple du pays, et il fit descendre le roi de la maison de Yahweh. Ils entrèrent dans la maison du roi par la porte supérieure, et ils firent asseoir le roi sur le trône de la royauté.'),
('2ch',23,21,'crampon1923','Tout le peuple du pays se réjouit, et la ville fut tranquille; on fit mourir Athalie par l''épée.'),
('2ch',24,1,'crampon1923','Joas avait sept ans lorsqu''il devint roi, et il régna quarante ans à Jérusalem. Sa mère s''appelait Sébia, de Bersabée.'),
('2ch',24,2,'crampon1923','Joas fit ce qui est droit aux yeux de Yahweh pendant toute la vie du prêtre Joïada.'),
('2ch',24,3,'crampon1923','Joïada prit deux femmes pour Joas, qui engendra des fils et des filles.'),
('2ch',24,4,'crampon1923','Après cela, Joas eut à cœur de restaurer la maison de Yahweh.'),
('2ch',24,5,'crampon1923','Il assembla les prêtres et les lévites et leur dit: " Allez dans les villes de Juda, et vous recueillerez parmi tout Israël de l''argent, chaque année, pour réparer la maison de votre Dieu, et faites cela avec hâte. " Mais les lévites ne se hâtèrent point.'),
('2ch',24,6,'crampon1923','Le roi appela Joïada, le grand prêtre, et lui dit: " Pourquoi n''as-tu pas veillé sur les lévites pour qu''ils apportent de Juda et de Jérusalem la taxe imposée à Israël par Moïse, serviteur de Yahweh, et par l''assemblée, pour la tente du témoignage?'),
('2ch',24,7,'crampon1923','Car l''impie Athalie et ses fils ont ravagé la maison de Dieu, et ils ont fait servir pour les Baals toutes les choses consacrées à la maison de Yahweh. "'),
('2ch',24,8,'crampon1923','Alors le roi ordonna qu''on fit un coffre et qu''on le plaçât à la porte de la maison de Yahweh, en dehors.'),
('2ch',24,9,'crampon1923','Et l''on publia dans Juda et dans Jérusalem que chacun eût à apporter à Yahweh la taxe imposée dans le désert à Israël par Moïse, serviteur de Yahweh.'),
('2ch',24,10,'crampon1923','Tous les chefs et tout le peuple en eurent de la joie, et ils apportèrent et jetèrent dans le coffre tout ce qu''ils devaient payer.'),
('2ch',24,11,'crampon1923','Le temps venu de livrer le coffre aux inspecteurs du roi par l''intermédiaire des lévites, lorsque ceux-ci voyaient qu''il y avait beaucoup d''argent dans le coffre, le secrétaire du roi et le commissaire du grand prêtre venaient vider le coffre; ils le prenaient et le remettaient à sa place. Ainsi faisaient-ils chaque fois, et ils recueillaient de l''argent en abondance.'),
('2ch',24,12,'crampon1923','Le roi et Joïada le donnaient à ceux qui faisaient exécuter l''ouvrage de la maison de Yahweh, et ceux-ci prenaient à gage des tailleurs de pierres et des charpentiers pour restaurer la maison de Yahweh, ainsi que des artisans en fer et en airain pour consolider la maison de Yahweh.'),
('2ch',24,13,'crampon1923','Les ouvriers travaillèrent, et la restauration progressa en leurs mains; ils rétablirent la maison de Dieu en son état ancien et l''affermirent.'),
('2ch',24,14,'crampon1923','Quand ils eurent fini, ils apportèrent devant le roi et devant Joïada l''argent qui restait, et l''on en fit des ustensiles pour la maison de Yahweh, des ustensiles pour le service et pour les holocaustes, des coupes et d''autres ustensiles d''or et d''argent. Et l''on offrit continuellement des holocaustes dans la maison de Yahweh pendant toute la vie de Joïada.'),
('2ch',24,15,'crampon1923','Joïada devint vieux et rassasié de jours, et il mourut; il avait cent trente ans quand il mourut.'),
('2ch',24,16,'crampon1923','On l''enterra dans la ville de David avec les rois, parce qu''il avait fait du bien en Israël et à l''égard de Dieu et de sa maison.'),
('2ch',24,17,'crampon1923','Après la mort de Joïada, les chefs de Juda vinrent se prosterner devant le roi; alors le roi les écouta.'),
('2ch',24,18,'crampon1923','Et, abandonnant la maison de Yahweh, le Dieu de leurs pères, ils honorèrent les aschérahs et les idoles. La colère de Yahweh vint sur Juda et sur Jérusalem, à cause de cette prévarication.'),
('2ch',24,19,'crampon1923','Pour les faire revenir vers lui, Yahweh envoya parmi eux des prophètes qui rendirent témoignage contre eux, mais ils ne les écoutèrent pas.'),
('2ch',24,20,'crampon1923','L''esprit de Dieu revêtit Zacharie, fils du prêtre Joïada, qui se présenta devant le peuple et lui dit: " Ainsi dit Dieu: Pourquoi transgressez-vous les commandements de Yahweh, pour ne point prospérer? Parce que vous avez abandonné Yahweh, il vous abandonne à son tour. "'),
('2ch',24,21,'crampon1923','Et ils conspirèrent contre lui, et ils le lapidèrent par ordre du roi, dans le parvis de la maison de Yahweh.'),
('2ch',24,22,'crampon1923','Joas ne se souvint pas de l''affection qu''avait eue pour lui Joïada, père de Zacharie, et il fit périr son fils. Zacharie dit en mourant: " Que Yahweh voie et fasse justice! "'),
('2ch',24,23,'crampon1923','Au retour de l''année, l''armée des Syriens monta contre Joas et vint en Juda et à Jérusalem. Ils tuèrent parmi le peuple tous les chefs du peuple, et ils envoyèrent tout leur butin au roi de Damas.'),
('2ch',24,24,'crampon1923','L''armée des Syriens était venue avec un petit nombre d''hommes, et Yahweh livra entre leurs mains une armée considérable, parce qu''ils avaient abandonné Yahweh, le Dieu de leurs pères. Les Syriens exécutèrent le jugement contre Joas.'),
('2ch',24,25,'crampon1923','Lorsqu''ils se furent éloignés de lui, l''ayant laissé couvert de nombreuses blessures, ses serviteurs conspirèrent contre lui, à cause du sang des fils du prêtre Joïada; ils le tuèrent sur son lit, et il mourut. On l''enterra dans la ville de David, mais on ne l''enterra pas dans les sépulcres des rois.'),
('2ch',24,26,'crampon1923','Voici ceux qui conspirèrent contre lui: Zabad, fils de Semmaath, femme Ammonite, et Jozabad, fils de Samarith, femme Moabite.'),
('2ch',24,27,'crampon1923','Ce qui concerne ses fils, le grand nombre de prophéties dirigées contre lui et la restauration de la maison de Dieu, voici que cela est écrit dans les Mémoires sur le livre des Rois. Amasias, son fils, régna à sa place.'),
('2ch',25,1,'crampon1923','Amasias devint roi à l''âge de vingt cinq ans, et il régna neuf ans à Jérusalem. Sa mère s''appelait Joadan, de Jérusalem.'),
('2ch',25,2,'crampon1923','Il fit ce qui est droit aux yeux de Yahweh, mais non d''un cœur parfait.'),
('2ch',25,3,'crampon1923','Lorsque la royauté fut affermie sur lui, il mit à mort ses serviteurs qui avaient tué le roi, son père;'),
('2ch',25,4,'crampon1923','mais il ne fit pas mourir leurs fils, selon ce qui est écrit dans la Loi, dans le livre de Moïse, où Yahweh donne ce commandement: " Les pères ne mourront pas pour les enfants, et les enfants ne mourront pas pour les pères; mais chacun mourra pour ses péchés. "'),
('2ch',25,5,'crampon1923','Amasias rassembla les hommes de Juda et les organisa d''après les maisons patriarcales, les chefs de milliers et les chefs de centaines, pour tout Juda et Benjamin; il en fit le recensement depuis l''âge de vingt ans et au-dessus, et il trouva trois cent mille hommes d''élite, en état d''aller à la guerre, et de manier la lance et le bouclier.'),
('2ch',25,6,'crampon1923','Il prit encore à sa solde, parmi ceux d''Israël, cent mille vaillants hommes pour cent talents d''argent.'),
('2ch',25,7,'crampon1923','Un homme de Dieu vint auprès de lui, en disant: " O roi, qu''une armée d''Israël ne marche point avec toi, car Yahweh n''est pas avec Israël, avec tous les fils d''Ephraïm.'),
('2ch',25,8,'crampon1923','Mais pars seul, agis, sois vaillant dans le combat, et Dieu ne te laissera pas tomber devant l''ennemi, car Dieu a le pouvoir de secourir et de faire tomber. "'),
('2ch',25,9,'crampon1923','Amasias dit à l''homme de Dieu: " Mais que faire à l''égard des cent talents que j''ai donnés à la troupe d''Israël? " L''homme de Dieu répondit: " Yahweh peut te donner beaucoup plus que cela. "'),
('2ch',25,10,'crampon1923','Amasias sépara la troupe qui lui était venue d''Ephraïm, pour qu''elle allât dans son pays. Mais la colère de ces gens s''alluma contre Juda, et ils s''en allèrent dans leur pays enflammés de colère.'),
('2ch',25,11,'crampon1923','Amasias, rempli de courage, conduisit son peuple; il s''en alla dans la vallée du Sel, et battit dix mille hommes des fils de Séir.'),
('2ch',25,12,'crampon1923','Les fils de Juda en firent captifs dix mille vivants, et les menèrent au sommet d''un rocher; ils les précipitèrent du sommet du rocher, et tous furent broyés.'),
('2ch',25,13,'crampon1923','Cependant, les gens de la troupe qu''Amasias avait renvoyés pour qu''ils n''allassent pas à la guerre avec lui, se jetèrent sur les villages de Juda; depuis Samarie jusqu''à Béthoron, y tuèrent trois mille hommes et enlevèrent de nombreuses dépouilles.'),
('2ch',25,14,'crampon1923','Après qu''Amasias fut revenu de battre les Edomites, il apporta les dieux des fils de Séir et, les ayant établis pour ses dieux, il se prosterna devant eux et leur offrit des parfums.'),
('2ch',25,15,'crampon1923','La colère de Yahweh s''enflamma contre Amasias, et il envoya vers lui un prophète, qui lui dit: " Pourquoi as-tu honoré les dieux de ce peuple, qui n''ont pu délivrer leur peuple de ta main? "'),
('2ch',25,16,'crampon1923','Comme il lui parlait, Amasias lui dit: " Est-ce que nous t''avons fait conseiller du roi? Retire-toi! Pourquoi te frapperait-on? " Le prophète se retira et dit: " Je sais que Dieu a résolu de te détruire, parce que tu as fait cela et que tu n''as pas écouté mon conseil. "'),
('2ch',25,17,'crampon1923','Après avoir pris avis, Amasias, roi de Juda, envoya dire à Joas, fils de Joachaz, fils de Jéhu, roi d''Israël: " Viens, et voyons-nous en face! " Et Joas, roi d''Israël, envoya répondre à Amasias, roi de Juda:'),
('2ch',25,18,'crampon1923','" L''épine qui est au Liban envoya dire au cèdre qui est au Liban: Donne ta fille pour femme à mon fils. Et les bêtes sauvages qui sont au Liban passèrent et foulèrent l''épine.'),
('2ch',25,19,'crampon1923','Tu te dis: Voici que tu as battu les Edomites, et ton cœur te porte à te glorifier. Maintenant, reste chez toi! Pourquoi t''engager dans le malheur, pour tomber, toi et Juda avec toi? "'),
('2ch',25,20,'crampon1923','Mais Amasias ne l''écouta pas car ce fut d''après la volonté de Dieu qu''il fit cette guerre, afin de livrer les hommes de Juda entre les mains de l''ennemi, parce qu''ils avaient honoré les dieux d''Edom.'),
('2ch',25,21,'crampon1923','Et Joas, roi d''Israël, monta, et ils se virent en face, lui et Amasias, roi de Juda, à Bethsamès, qui est à Juda.'),
('2ch',25,22,'crampon1923','Juda fut battu devant Israël, et chacun s''enfuit dans sa tente.'),
('2ch',25,23,'crampon1923','Et Joas, roi d''Israël, prit à Bethsamès Amasias, roi de Juda, fils de Joas, fils de Joachaz. Il l''emmena à Jérusalem, et il fit une brèche de quatre cents coudées dans la muraille de Jérusalem, depuis la porte d''Ephraïm jusqu''à la porte de l''angle.'),
('2ch',25,24,'crampon1923','Il prit tout l''or et l''argent et tous les ustensiles qui se trouvaient dans la maison de Dieu, chez Obédédom, et les trésors de la maison du roi; il prit aussi des otages, et retourna à Samarie.'),
('2ch',25,25,'crampon1923','Amasias, fils de Joas, roi de Juda, vécut quinze ans après la mort de Joas, fils de Joachaz, roi d''Israël.'),
('2ch',25,26,'crampon1923','Le reste des actes, d''Amasias, les premiers et les derniers, cela n''est-il pas écrit dans le livre des rois de Juda et d''Israël?'),
('2ch',25,27,'crampon1923','Après qu''Amasias se fut détourné de Yahweh, on ourdit contre lui une conspiration à Jérusalem, et il s''enfuit à Lachis; mais on envoya après lui des hommes à Lachis, et on l''y mit à mort.'),
('2ch',25,28,'crampon1923','On le transporta sur des chevaux, et on l''enterra avec ses pères dans la ville de Juda.'),
('2ch',26,1,'crampon1923','Tout le peuple de Juda prit Ozias, qui était âgé de seize ans; et on l''établit roi à la place de son père, Amasias.'),
('2ch',26,2,'crampon1923','Ozias rebâtit Elath et la ramena à Juda, après que le roi fut couché avec ses pères.'),
('2ch',26,3,'crampon1923','Ozias avait seize ans lorsqu''il devint roi, et il régna cinquante-deux ans à Jérusalem. Sa mère se nommait Jéchélia, de Jérusalem.'),
('2ch',26,4,'crampon1923','Il fit ce qui est droit aux yeux de Yahweh, selon tout ce qu''avait fait Amasias, son père.'),
('2ch',26,5,'crampon1923','Il fut disposé à honorer Dieu pendant la vie de Zacharie, qui lui apprenait à craindre Dieu; et dans le temps qu''il honorait Yahweh, Dieu le fit prospérer.'),
('2ch',26,6,'crampon1923','Il partit en guerre contre les Philistins; il renversa le mur de Geth, le mur de Jabnia et le mur d''Azot, et construisit des villes dans le territoire d''Azot et parmi les Philistins.'),
('2ch',26,7,'crampon1923','Dieu l''aida contre les Philistins, contre les Arabes qui habitaient à Gur-Baal, et contre les Maonites.'),
('2ch',26,8,'crampon1923','Les Ammonites faisaient des présents à Ozias, et sa renommée parvint jusqu''à l''entrée de l''Egypte, car il devint très puissant.'),
('2ch',26,9,'crampon1923','Ozias bâtit des tours à Jérusalem sur la porte de l''angle, sur la porte de la vallée et sur l''angle, et il les fortifia.'),
('2ch',26,10,'crampon1923','Il bâtit des tours dans le désert, et il creusa beaucoup de citernes, parce qu''il avait là de nombreux troupeaux, ainsi que dans la Séphéla et sur les plateaux, et des laboureurs et des vignerons dans les montagnes et au Carmel, car il aimait l''agriculture.'),
('2ch',26,11,'crampon1923','Ozias avait une armée de guerriers qui allaient au combat par troupes, comptées d''après leur dénombrement par le secrétaire Jéhiel et le commissaire Maasias, sous les ordres de Hananias, l''un des chefs du roi.'),
('2ch',26,12,'crampon1923','Le nombre total des chefs de maisons, vaillants guerriers, était de deux mille six cents.'),
('2ch',26,13,'crampon1923','Ils commandaient à une armée de trois cent sept mille cinq cents hommes, qui faisaient la guerre avec une grande puissance, pour soutenir le roi contre l''ennemi.'),
('2ch',26,14,'crampon1923','Ozias leur procura, à toute cette armée, des boucliers, des lances, des casques, des cuirasses, des arcs et des frondes pour lancer des pierres.'),
('2ch',26,15,'crampon1923','Il fit construire à Jérusalem des machines inventées par un ingénieur, et destinées à être placées sur les tours et sur les angles des murs, pour lancer des flèches et de grosses pierres. Sa renommée s''étendait jusqu''au loin, car il fut merveilleusement aidé, jusque là qu''il devint puissant.'),
('2ch',26,16,'crampon1923','Mais lorsqu''il fut devenu puissant, son cœur s''éleva jusqu''à la ruine. Péchant contre Yahweh, son Dieu, il entra dans le temple de Yahweh pour brûler des parfums sur l''autel des parfums.'),
('2ch',26,17,'crampon1923','Le prêtre Azarias entra après lui, avec quatre-vingts prêtres de Yahweh, hommes courageux;'),
('2ch',26,18,'crampon1923','ils s''opposèrent au roi Ozias et lui dirent: " Ce n''est pas à toi, Ozias, d''offrir des parfums à Yahweh, mais aux prêtres, fils d''Aaron, qui ont été consacrés pour brûler des parfums. Sors du sanctuaire, car tu as péché, et cela ne tournera pas à ton honneur devant Yahweh Dieu. "'),
('2ch',26,19,'crampon1923','Ozias, qui tenait un encensoir à la main pour offrir des parfums, fut saisi de colère et, comme il s''irritait contre les prêtres, la lèpre se leva sur son front, en présence des prêtres, dans la maison de Yahweh, devant l''autel des parfums.'),
('2ch',26,20,'crampon1923','Le grand prêtre Azarias et tous les prêtres s''étant tournés vers lui, voici qu''il avait la lèpre au front. Ils le mirent précipitamment dehors, et lui-même se hâta de sortir, parce que Yahweh l''avait frappé.'),
('2ch',26,21,'crampon1923','Le roi Ozias fut lépreux jusqu''au jour de sa mort, et il demeura dans une maison écartée, comme lépreux, car il fut exclu de la maison de Yahweh. Joatham, son fils, était à la tête de la maison du roi, jugeant le peuple du pays.'),
('2ch',26,22,'crampon1923','Le reste des actes d''Ozias, les premiers et les derniers, Isaïe, fils d''Amos, le prophète les a écrits.'),
('2ch',26,23,'crampon1923','Ozias se coucha avec ses pères dans le champ de la sépulture des rois, car on disait: " Il est lépreux. " Joatham, son fils, régna à sa place.'),
('2ch',27,1,'crampon1923','Joatham avait vingt-cinq ans lorsqu''il devint roi, et il régna seize ans à Jérusalem. Sa mère s''appelait Jérusa, fille de Sadoc.'),
('2ch',27,2,'crampon1923','Il fit ce qui est droit aux yeux de Yahweh, selon tout ce qu''avait fait Ozias, son père; seulement il n''entra point dans le temple de Yahweh; mais le peuple se corrompait encore.'),
('2ch',27,3,'crampon1923','Joatham bâtit la porte supérieure de la maison de Yahweh, et fit beaucoup de constructions sur le mur d''Ophel.'),
('2ch',27,4,'crampon1923','Il bâtit des villes dans la montagne de Juda, il bâtit des forts et des tours dans les bois.'),
('2ch',27,5,'crampon1923','Il fit la guerre au roi des fils d''Ammon, et il l''emporta sur eux. Les fils d''Ammon lui donnèrent cette année-là cent talents d''argent, dix mille cors de froment, et dix mille d''orge; et les fils d''Ammon lui en apportèrent autant la seconde et la troisième année.'),
('2ch',27,6,'crampon1923','Joatham augmenta sa puissance, parce qu''il avait affermi ses voies devant Yahweh, son Dieu.'),
('2ch',27,7,'crampon1923','Le reste des actes de Joatham, toutes ses guerres et tout ce qu''il a fait, voici que cela est écrit dans le livre des rois d''Israël et de Juda.'),
('2ch',27,8,'crampon1923','Il avait vingt-cinq ans lorsqu''il devint roi, et il régna seize ans à Jérusalem.'),
('2ch',27,9,'crampon1923','Joatham se coucha avec ses pères, et on l''enterra dans la ville de David. Achaz, son fils, régna à sa place.'),
('2ch',28,1,'crampon1923','Achaz avait vingt ans lorsqu''il devint roi, et il régna seize ans à Jérusalem. Il ne fit pas ce qui est droit aux yeux de Yahweh, comme avait fait David, son père.'),
('2ch',28,2,'crampon1923','Il marcha dans les voies des rois d''Israël, et même il fit des images en fonte pour les Baals.'),
('2ch',28,3,'crampon1923','Il brûla des parfums dans la vallée de Ben-Hinnom, et il fit passer ses fils par le feu, selon les abominations des nations que Yahweh avait chassées devant les enfants d''Israël.'),
('2ch',28,4,'crampon1923','Il offrait des sacrifices et des parfums aux hauts lieux, sur les collines et sous tout arbre vert.'),
('2ch',28,5,'crampon1923','Yahweh, son Dieu, le livra entre les mains du roi de Syrie; les Syriens le battirent et lui firent un grand nombre de prisonniers, qu''ils emmenèrent à Damas. Il fut aussi livré entre les mains du roi d''Israël, qui le frappa d''une grande défaite.'),
('2ch',28,6,'crampon1923','Phacée, fils de Romélias, tua en Juda dans un seul jour cent vingt mille hommes, tous vaillants, parce qu''ils avaient abandonné Yahweh, le Dieu de leurs pères.'),
('2ch',28,7,'crampon1923','Zéchri, guerrier d''Ephraïm, tua Maasias, fils du roi, et Ezrica, chef de la maison royale, et Elcana, le second après le roi.'),
('2ch',28,8,'crampon1923','Les enfants d''Israël firent parmi leurs frères deux cent mille prisonniers, femmes, fils et filles, et ils leur prirent un butin considérable et ils emmenèrent le butin à Samarie.'),
('2ch',28,9,'crampon1923','Il y avait là un prophète de Yahweh, nommé Oded. Sortant au-devant de l''armée qui revenait à Samarie, il leur dit: " Voici que, dans sa colère contre, Juda, Yahweh, le Dieu de vos pères, les a livrés entre vos mains; et vous les avez tués avec une fureur qui a atteint jusqu''au ciel.'),
('2ch',28,10,'crampon1923','Et maintenant, vous songez à soumettre les enfants de Juda et de Jérusalem pour qu''ils soient vos serviteurs et vos servantes! Mais vous, n''avez-vous pas aussi des offenses à l''égard de Yahweh, votre Dieu?'),
('2ch',28,11,'crampon1923','Et maintenant, écoutez-moi, et renvoyez ces captifs que vous avez faits parmi vos frères, car l''ardeur de la colère de Yahweh est sur vous. "'),
('2ch',28,12,'crampon1923','Quelques-uns d''entre les chefs des enfants d''Ephraïm, Azarias, fils de Johanan, Barachias, fils de Mosollamoth, Ezéchias, fils de Sellum, et Amasa, fils d''Adali, s''élevèrent contre ceux qui revenaient de l''armée,'),
('2ch',28,13,'crampon1923','et leur dirent: " Vous ne ferez point entrer ici les captifs; car c''est pour nous charger d''une faute envers Yahweh que vous songez à ajouter à nos péchés et à nos fautes; car grande est notre faute, et l''ardeur de la colère de Yahweh est sur Israël. "'),
('2ch',28,14,'crampon1923','Les soldats abandonnèrent les captifs et le butin devant les chefs et devant toute l''assemblée.'),
('2ch',28,15,'crampon1923','Et les hommes qui ont été mentionnés par leurs noms se levèrent et, ayant pris les captifs, ils revêtirent avec le butin tous ceux qui étaient nus, leur donnant des habits et des chaussures; puis ils les firent manger et boire et les oignirent et, transportant sur des ânes tous ceux qui défaillaient, il les menèrent à Jéricho, la ville des palmiers, auprès de leurs frères. Et eux retournèrent à Samarie.'),
('2ch',28,16,'crampon1923','En ce temps-là, le roi Achaz envoya demander aux rois d''Assyrie de le secourir.'),
('2ch',28,17,'crampon1923','Car les Edomites étaient encore venus; ils avaient battu Juda et emmené des captifs.'),
('2ch',28,18,'crampon1923','Les Philistins s''étaient répandus dans les villes de la Séphéla et du Négeb de Juda; ils avaient pris Bethsamès, Aïalon, Gadéroth, Socho et les villes de sa dépendance, Thamna et les villes de sa dépendance, Gamzo et les villes de sa dépendance, et s''y étaient établis.'),
('2ch',28,19,'crampon1923','Car Yahweh humiliait Juda, à cause d''Achaz, roi d''Israël, qui avait déchaîné la licence dans Juda et commis des fautes contre Yahweh.'),
('2ch',28,20,'crampon1923','Thelgath-Phalnasar, roi d''Assyrie, vint contre lui, le traita avec rigueur et ne le fortifia pas.'),
('2ch',28,21,'crampon1923','Car Achaz avait dépouillé la maison de Yahweh, la maison du roi et des chefs, et fait des présents au roi d''Assyrie: ce qui ne lui fut d''aucun secours.'),
('2ch',28,22,'crampon1923','Pendant qu''il était dans la détresse, il continuait à offenser Yahweh, lui, le roi Achaz.'),
('2ch',28,23,'crampon1923','Il sacrifia aux dieux de Damas, qui le frappaient, et il dit: " Puisque les dieux des rois de Syrie leur viennent en aide, je leur offrirai des sacrifices et ils me secourront. " Mais ils furent une cause de chute pour lui et pour tout Israël.'),
('2ch',28,24,'crampon1923','Achaz rassembla les ustensiles de la maison de Dieu et mit en pièces les ustensiles de la maison de Dieu, et, ayant fermé les portes de la maison de Yahweh, il se fit des autels à tous les angles de Jérusalem.'),
('2ch',28,25,'crampon1923','Il établit des hauts lieux dans chacune des villes de Juda pour offrir des parfums à d''autres dieux. Il irrita ainsi Yahweh, le Dieu de ses pères.'),
('2ch',28,26,'crampon1923','Le reste de ses actes et toutes ses voies, les premières et les dernières, voici que cela est écrit dans le livre des rois de Juda et d''Israël.'),
('2ch',28,27,'crampon1923','Achaz se coucha avec ses pères, et on l''enterra dans la ville, dans Jérusalem, car on ne l''introduisit pas dans les sépulcres des rois d''Israël. Ezéchias, son fils, régna à sa place.'),
('2ch',29,1,'crampon1923','Ezéchias devint roi à l''âge de vingt cinq ans, et il régna vingt-neuf ans à Jérusalem. Sa mère s''appelait Abia, fille de Zacharias.'),
('2ch',29,2,'crampon1923','Il fit ce qui est droit aux yeux de Yahweh, selon tout ce qu''avait fait David, son père.'),
('2ch',29,3,'crampon1923','La première année de son règne, le premier mois, il ouvrit les portes de la maison de Yahweh et il les répara.'),
('2ch',29,4,'crampon1923','Il fit venir les prêtres et les lévites et, les ayant réunis sur la place orientale,'),
('2ch',29,5,'crampon1923','il leur dit: " Ecoutez-moi, lévites! Sanctifiez-vous maintenant, sanctifiez la maison de Yahweh, le Dieu de vos pères, et faites sortir du sanctuaire ce qui est impur.'),
('2ch',29,6,'crampon1923','Car nos pères ont péché, ils ont fait ce qui est mal aux yeux de Yahweh, notre Dieu, ils l''ont abandonné, ils ont détourné leur visage de la demeure de Yahweh et lui ont tourné le dos.'),
('2ch',29,7,'crampon1923','Ils ont même fermé les portes du portique et éteint les lampes, et ils n''ont pas fait brûler de parfums ni offert d''holocaustes dans le sanctuaire au Dieu d''Israël.'),
('2ch',29,8,'crampon1923','Et la colère de Yahweh a été sur Juda et Jérusalem, et il en a fait un objet de terreur, de stupeur et de moquerie, comme vous le voyez de vos yeux;'),
('2ch',29,9,'crampon1923','et voici qu''à cause de cela, nos pères sont tombés par l''épée, et nos fils, nos filles et nos femmes sont en captivité.'),
('2ch',29,10,'crampon1923','Maintenant, j''ai l''intention de faire alliance avec Yahweh, le Dieu d''Israël, pour que l''ardeur de sa colère se détourne de nous.'),
('2ch',29,11,'crampon1923','Maintenant, mes enfants, ne soyez plus négligents; car c''est vous que Yahweh a choisis pour vous tenir devant lui à son service, pour être ses serviteurs et pour lui offrir des parfums. "'),
('2ch',29,12,'crampon1923','Alors les lévites se levèrent: Mahath, fils d''Amasaï, Joël, fils d''Azarias, des fils des Caathites; des fils de Mérari, Cis fils d''Abdi, Azarias, fils de Jalaléel; des Gersonites, Joah, fils de Zemma, Eden, fils de Joah;'),
('2ch',29,13,'crampon1923','des fils d''Elisaphan, Samri et Jahiel; des fils d''Asaph, Zacharias et Mathanias;'),
('2ch',29,14,'crampon1923','des fils d''Héman, Jahiel et Seméï; et des fils d''Idithun, Séméïas et Oziel.'),
('2ch',29,15,'crampon1923','Ils réunirent leurs frères et, après s''être sanctifiés, ils vinrent, selon l''ordre du roi, d''après les paroles de Yahweh, pour purifier la maison de Yahweh.'),
('2ch',29,16,'crampon1923','Les prêtres entrèrent dans l''intérieur de la maison de Yahweh pour la purifier; ils firent sortir dans le parvis de la maison de Yahweh toutes les impuretés qu''ils trouvèrent dans le temple de Yahweh, et de là les lévites les prirent pour les emporter dehors à la vallée de Cédron.'),
('2ch',29,17,'crampon1923','Ils commencèrent à purifier le premier jour du premier mois; le huitième jour du mois, ils entrèrent dans le portique de Yahweh, et ils mirent huit jours à purifier la maison de Yahweh; le seizième jour du premier mois, ils avaient achevé.'),
('2ch',29,18,'crampon1923','Ils se rendirent ensuite chez le roi Ezéchias et dirent: " Nous avons purifié toute la maison de Yahweh, l''autel des holocaustes et tous ses ustensiles, et la table de proposition et tous ses ustensiles.'),
('2ch',29,19,'crampon1923','Et tous les ustensiles que le roi Achaz avait profanés pendant son règne, lors de ses transgressions, nous les avons remis en état et purifiés; ils sont devant l''autel de Yahweh. "'),
('2ch',29,20,'crampon1923','Le roi Ezéchias, s''étant levé de bon matin, assembla les chefs de la ville et monta à la maison de Yahweh.'),
('2ch',29,21,'crampon1923','Ils présentèrent sept taureaux, sept béliers, sept agneaux et sept boucs, en sacrifice pour le péché, pour le royaume, pour le sanctuaire et pour Juda. Le roi dit aux prêtres, fils d''Aaron, de les offrir sur l''autel de Yahweh.'),
('2ch',29,22,'crampon1923','Ils immolèrent les bœufs, et les prêtres recueillirent le sang, qu''ils répandirent sur l''autel; ils immolèrent les béliers, et répandirent le sang sur l''autel; ils immolèrent les agneaux, et répandirent le sang sur l''autel.'),
('2ch',29,23,'crampon1923','Puis ils firent approcher les boucs pour le péché devant le roi et l''assemblée, et tous posèrent la main sur eux.'),
('2ch',29,24,'crampon1923','Les prêtres les égorgèrent et avec leur sang ils firent l''expiation à l''autel, faisant l''expiation pour tout Israël; car c''était pour tout Israël que le roi avait ordonné l''holocauste et le sacrifice pour le péché.'),
('2ch',29,25,'crampon1923','Il fit placer les lévites dans la maison de Yahweh avec des cymbales, des cithares et des harpes, selon l''ordre de David, de Gad, le voyant du roi, et de Nathan le prophète; car cet ordre venait de Yahweh, par l''organe de ses prophètes.'),
('2ch',29,26,'crampon1923','Les lévites prirent place avec les instruments de David, et les prêtres avec les trompettes.'),
('2ch',29,27,'crampon1923','Et Ezéchias dit d''offrir l''holocauste, sur l''autel. Au moment où commença l''holocauste, commencèrent aussi le chant de Yahweh et le son des trompettes, accompagnés avec les instruments de David, roi d''Israël.'),
('2ch',29,28,'crampon1923','Toute l''assemblée se prosterna, on chanta le cantique et l''on sonna des trompettes, le tout jusqu''à ce que l''holocauste fut achevé.'),
('2ch',29,29,'crampon1923','Quand l''holocauste fut achevé, le roi et tous ceux qui étaient avec lui fléchirent le genou et adorèrent.'),
('2ch',29,30,'crampon1923','Le roi Ezéchias et les chefs dirent aux lévites de célébrer Yahweh avec les paroles de David et d''Asaph le voyant, et ils célébrèrent avec joie, et, s''inclinant, ils adorèrent.'),
('2ch',29,31,'crampon1923','Alors Ezéchias prit la parole et dit: " Maintenant, vous vous êtes consacrés de nouveau à Yahweh, approchez-vous, présentez des sacrifices et des actions de grâce dans la maison de Yahweh. " Et l''assemblée présenta des sacrifices et des actions de grâces, et tous ceux dont le cœur était généreux offrirent des holocaustes.'),
('2ch',29,32,'crampon1923','Le nombre des holocaustes qu''offrit l''assemblée fut de soixante dix bœufs, cent béliers et deux cents agneaux: tout cela pour un holocauste à Yahweh.'),
('2ch',29,33,'crampon1923','On consacra en outre six cents bœufs et trois mille brebis.'),
('2ch',29,34,'crampon1923','Mais les prêtres, étant en petit nombre, ne purent dépouiller tous les holocaustes; leurs frères, les lévites, les aidèrent jusqu''à ce que l''ouvrage fut fini et jusqu''à ce que les autres prêtres se fussent sanctifiés, car les lévites avaient mis plus de sincérité de cœur que les prêtres à se sanctifier.'),
('2ch',29,35,'crampon1923','Il y avait d''ailleurs beaucoup d''holocaustes, outre les graisses des sacrifices pacifiques et les libations pour les holocaustes. Ainsi fut rétabli le service de la maison de Yahweh.'),
('2ch',29,36,'crampon1923','Ezéchias et tout le peuple se réjouirent de ce que Dieu avait préparé pour le peuple, car la chose s''était faite subitement.'),
('2ch',30,1,'crampon1923','Ezéchias envoya des messagers dans tout Israël et Juda, et il écrivit des lettres à Ephraïm et à Manassé, les invitant à venir à la maison de Yahweh à Jérusalem, pour célébrer la Pâque en l''honneur de Yahweh, le Dieu d''Israël.'),
('2ch',30,2,'crampon1923','Le roi, ses chefs et toute l''assemblée de Jérusalem, avaient tenu conseil, afin que la Pâque fut célébrée au second mois;'),
('2ch',30,3,'crampon1923','car on n''avait pu la faire en son temps, parce que les prêtres ne s''étaient pas sanctifiés en assez grand nombre, et que le peuple ne s''était pas rassemblé à Jérusalem.'),
('2ch',30,4,'crampon1923','La chose parut juste aux yeux du roi et de toute l''assemblée.'),
('2ch',30,5,'crampon1923','Ils décidèrent de faire passer une proclamation dans tout Israël, depuis Bersabée jusqu''à Dan, pour que l''on vint à Jérusalem célébrer la Pâque en l''honneur de Yahweh, le Dieu d''Israël; car ils ne l''avaient plus célébrée en grand nombre, selon qu''il est écrit.'),
('2ch',30,6,'crampon1923','Les coureurs allèrent avec les lettres du roi et de ses chefs dans tout Israël et Juda, pour dire d''après l''ordre du roi: " Enfants d''Israël, revenez à Yahweh, le Dieu d''Abraham, d''Isaac et d''Israël, et il reviendra à ceux qui restent, à ceux d''entre vous qui ont échappé à la main des rois d''Assyrie.'),
('2ch',30,7,'crampon1923','Ne soyez pas comme vos pères et comme vos frères, qui ont péché contre Yahweh, le Dieu de leurs pères, et qu''il a livrés à la désolation, comme vous le voyez.'),
('2ch',30,8,'crampon1923','Ne roidissez donc pas votre cou, comme l''ont fait vos pères; donnez la main à Yahweh, venez à son sanctuaire, qu''il a sanctifié pour toujours, et servez Yahweh, votre Dieu, afin que le feu de sa colère se détourne de vous.'),
('2ch',30,9,'crampon1923','Car si vous revenez à Yahweh, vos frères et vos fils trouveront miséricorde auprès de ceux qui les ont emmenés captifs, et il ne détournera pas sa face de vous, si vous revenez à lui. "'),
('2ch',30,10,'crampon1923','Les coureurs passèrent ainsi de ville en ville dans le pays d''Ephraïm et de Manassé, et jusqu''à Zabulon; mais on se riait d''eux et on se moquait d''eux.'),
('2ch',30,11,'crampon1923','Quelques hommes seulement d''Aser, de Manassé et de Zabulon s''humilièrent et vinrent à Jérusalem.'),
('2ch',30,12,'crampon1923','Dans Juda aussi, la main de Dieu s''étendit pour leur donner un même cœur et leur faire exécuter l''ordre du roi et des chefs, selon la parole de Yahweh.'),
('2ch',30,13,'crampon1923','Un peuple nombreux se réunit à Jérusalem pour célébrer la fête des Azymes au second mois: ce fut une immense assemblée.'),
('2ch',30,14,'crampon1923','S''étant levés, ils firent disparaître les autels qui étaient à Jérusalem; ils firent aussi disparaître tous les autels des parfums, et ils les jetèrent dans la vallée du Cédron.'),
('2ch',30,15,'crampon1923','Ils immolèrent ensuite la Pâque, le quatorzième jour du second mois. Les prêtres et les lévites, pris de confusion, se sanctifièrent, et offrirent des holocaustes dans la maison de Yahweh.'),
('2ch',30,16,'crampon1923','Ils occupaient leur place ordinaire, selon leur règlement, selon la loi de Moïse, l''homme de Dieu; et les prêtres répandaient le sang qu''ils recevaient de la main des lévites.'),
('2ch',30,17,'crampon1923','Comme il y avait dans l''assemblée une foule de gens qui ne s''étaient pas sanctifiés, les lévites étaient chargés d''immoler les victimes pascales pour tous ceux qui n''étaient pas purs, afin de les consacrer à Yahweh.'),
('2ch',30,18,'crampon1923','Car une grande partie du peuple, une foule de ceux d''Ephraïm, de Manassé, d''Issachar et de Zabulon ne s''étaient pas purifiés, et ils mangèrent la Pâque sans se conformer à ce qui est écrit. Mais Ezéchias pria pour eux, en disant: " Que Yahweh, qui est bon, pardonne'),
('2ch',30,19,'crampon1923','à tous ceux qui ont appliqué leur cœur à chercher Dieu, Yahweh, le Dieu de leurs pères, quoiqu''ils n''aient pas la pureté requise au sanctuaire! "'),
('2ch',30,20,'crampon1923','Yahweh exauça Ezéchias et pardonna au peuple.'),
('2ch',30,21,'crampon1923','Et les enfants d''Israël qui se trouvèrent à Jérusalem célébrèrent la fête des Azymes pendant sept jours avec une grande joie, et chaque jour les lévites et les prêtres louaient Yahweh avec les instruments puissants, en l''honneur de Yahweh.'),
('2ch',30,22,'crampon1923','Ezéchias parla au cœur de tous les lévites, qui montraient une grande intelligence pour le service de Yahweh. Ils mangèrent les victimes de la fête pendant sept jours, offrant des sacrifices pacifiques et louant Yahweh, le Dieu de leurs pères.'),
('2ch',30,23,'crampon1923','Toute l''assemblée fut d''avis de célébrer sept autres jours, et ils célébrèrent sept autres jours joyeusement;'),
('2ch',30,24,'crampon1923','car Ezéchias, roi de Juda, avait donné à l''assemblée mille taureaux et sept mille brebis, et les chefs lui avaient donné mille taureaux et dix mille brebis, et des prêtres en grand nombre s''étaient sanctifiés.'),
('2ch',30,25,'crampon1923','Toute l''assemblée de Juda, les prêtres et les lévites, toute l''assemblée venue d''Israël et les étrangers venus du pays d''Israël ou établis en Juda se livrèrent à la joie.'),
('2ch',30,26,'crampon1923','Il y eut à Jérusalem de grandes réjouissances, au point que depuis le temps de Salomon, fils de David, roi d''Israël, rien de semblable n''avait eu lieu dans Jérusalem.'),
('2ch',30,27,'crampon1923','Les prêtres lévitiques se levèrent et bénirent le peuple, et leur voix fut entendue; leur prière arriva jusqu''à la sainte demeure de Yahweh, jusqu''au ciel.'),
('2ch',31,1,'crampon1923','Lorsque tout cela fut terminé, tous ceux d''Israël qui se trouvaient là partirent pour les villes de Juda, et ils brisèrent les stèles, coupèrent les aschérahs, et renversèrent les hauts lieux et les autels dans tout Juda et Benjamin, et dans Ephraïm et Manassé, jusqu''à complète destruction. Puis tous les enfants d''Israël retournèrent dans leurs villes, chacun dans son domaine.'),
('2ch',31,2,'crampon1923','Ezéchias établit les divisions des prêtres et des lévites d''après leurs classes, — chacun des prêtres et des lévites selon ses fonctions, — pour les holocaustes et les sacrifices pacifiques, pour le service du culte, pour les chants et les louanges, aux portes du camp de Yahweh.'),
('2ch',31,3,'crampon1923','Il fournit aussi de ses biens la portion du roi pour les holocaustes, pour les holocaustes du matin et du soir et pour les holocaustes des sabbats, des nouvelles lunes et des fêtes, comme il est écrit dans la loi de Yahweh.'),
('2ch',31,4,'crampon1923','Et il dit au peuple qui habitait Jérusalem de donner la portion des prêtres et des lévites, afin qu''ils s''attachassent fortement à la loi de Yahweh.'),
('2ch',31,5,'crampon1923','Lorsque cet ordre fut répandu, les enfants d''Israël offrirent en abondance les prémices du blé, du vin nouveau, de l''huile, du miel et de tous les produits des champs; ils apportèrent aussi en abondance la dîme de tout.'),
('2ch',31,6,'crampon1923','Les enfants d''Israël et de Juda qui demeuraient dans les villes de Juda donnèrent, eux aussi, la dîme des bœufs et des brebis, et la dîme des choses saintes qui étaient consacrées à Yahweh, leur Dieu, et l''on en fit plusieurs tas.'),
('2ch',31,7,'crampon1923','On commença à former les tas au troisième mois, et on les acheva au septième mois.'),
('2ch',31,8,'crampon1923','Ezéchias et les chefs vinrent et, ayant vu les tas, ils bénirent Yahweh et son peuple d''Israël.'),
('2ch',31,9,'crampon1923','Et Ezéchias interrogea les prêtres et les lévites au sujet de ces tas.'),
('2ch',31,10,'crampon1923','Le grand prêtre Azarias, de la maison de Sadoc, lui répondit: " Depuis qu''on a commencé d''apporter les dons prélevés dans la maison de Yahweh, nous avons mangé, nous nous sommes rassasiés, et nous en avons laissé beaucoup, car Yahweh a béni son peuple, et le reste est cette grande quantité. "'),
('2ch',31,11,'crampon1923','Ezéchias dit de préparer des chambres dans la maison de Yahweh, et on les prépara.'),
('2ch',31,12,'crampon1923','On y apporta fidèlement les dons prélevés, la dîme et les choses consacrées. Le lévite Chonénias en eut l''intendance, et Sémei, son frère, venait en second.'),
('2ch',31,13,'crampon1923','Jahiel, Azarias, Nahath, Asaël, Jérimoth, Jozabad, Eliel, Jesmachias, Mahath et Banaïas étaient surveillants sous l''autorité de Chonénias et de son frère Séméi, d''après la disposition du roi Ezéchias et d''Azarias, chef de la maison de Dieu.'),
('2ch',31,14,'crampon1923','Le lévite Coré, fils de Jemma, qui était portier à l''orient, était préposé aux dons volontaires faits à Dieu, pour distribuer ce qui était prélevé pour Yahweh et les choses très saintes.'),
('2ch',31,15,'crampon1923','A sa disposition se tenaient fidèlement, dans les villes des prêtres, Eden, Benjamin, Jésué, Séméias, Amarias et Sèchénias, pour faire les distributions à leurs frères, grands et petits, selon leurs classes:'),
('2ch',31,16,'crampon1923','excepté aux mâles enregistrés, de trois ans et au-dessus, à tous ceux qui entraient dans la maison de Yahweh, selon le besoin de chaque jour, pour faire leur service selon leurs fonctions et leurs classes.'),
('2ch',31,17,'crampon1923','Le registre des prêtres était dressé d''après leurs maisons paternelles, et les lévites étaient inscrits à partir de vingt ans et au-dessus, selon leurs fonctions et leurs classes.'),
('2ch',31,18,'crampon1923','Le registre comprenait tous leurs enfants, leurs femmes, leurs fils et leurs filles. toute l''assemblée; car dans leur fidélité ils s''occupaient saintement des saintes offrandes.'),
('2ch',31,19,'crampon1923','Et pour les fils d''Aaron, les prêtres qui demeuraient dans le territoire de la banlieue de leurs villes, il y avait dans chaque ville des hommes désignés par leurs noms pour distribuer les portions à tout mâle parmi les prêtres et à tous les lévites inscrits.'),
('2ch',31,20,'crampon1923','Voilà ce que fit Ezéchias dans tout Juda; il fit ce qui est bon, ce qui est droit et ce qui est vrai devant Yahweh, son Dieu.'),
('2ch',31,21,'crampon1923','Dans toute œuvre qu''il entreprit pour le service de la maison de Dieu, pour la loi et les commandements, en recherchant son Dieu, il agit de tout son cœur et il prospéra.'),
('2ch',32,1,'crampon1923','Après ces choses et ces actes de fidélité, Sennachérib, roi d''Asssyrie, se mit en marche et, étant entré en Juda, il campa contre les villes fortes, dans le dessein de s''en emparer.'),
('2ch',32,2,'crampon1923','Quand Ezéchias vit que Sennachérib était venu et qu''il se tournait contre Jérusalem pour l''attaquer,'),
('2ch',32,3,'crampon1923','il tint conseil avec ses chefs et ses hommes vaillants, afin de couvrir les eaux des sources qui étaient hors de la ville, et ils lui prêtèrent secours.'),
('2ch',32,4,'crampon1923','Un peuple nombreux se rassembla, et ils couvrirent tontes les sources et le ruisseau qui coulait au milieu du pays, en disant: " Pourquoi les rois d''Assyrie, en venant ici, trouveraient-ils des eaux abondantes? "'),
('2ch',32,5,'crampon1923','Ezéchias prit courage; il rebâtit toute la muraille qui était en ruine et restaura les tours; il bâtit l''autre mur en dehors, fortifia Mello dans la cité de David; il fit fabriquer une quantité d''armes et de boucliers.'),
('2ch',32,6,'crampon1923','Il donna des chefs militaires au peuple et, les ayant réunis prés de lui sur la place de la porte de la ville, il leur parla au cœur, en disant:'),
('2ch',32,7,'crampon1923','" Soyez forts et courageux; ne craignez point et ne vous effrayez point devant le roi d''Assyrie et devant toute la multitude qui est avec lui; car il y a plus avec nous qu''avec lui.'),
('2ch',32,8,'crampon1923','Avec lui est un bras de chair, et avec nous est Yahweh, notre Dieu, pour nous aider et mener nos combats. " Le peuple eut confiance dans les paroles d''Ezéchias, roi de Juda.'),
('2ch',32,9,'crampon1923','Après cela, Sennachérib, roi d''Assyrie, envoya ses serviteurs a Jérusalem, — il était devant Lachis avec toutes ses forces royales, — vers Ezéchias, roi de Juda, et vers tous ceux de Juda qui étaient à Jérusalem, pour leur dire:'),
('2ch',32,10,'crampon1923','" Ainsi dit Sennachérib, roi d''Assyrie: En quoi vous confiez-vous, pour que vous restiez assiégés à Jérusalem dans la détresse?'),
('2ch',32,11,'crampon1923','Ezéchias ne vous trompe-t-il pas pour vous livrer à la mort par la famine et par la soif, quand il dit: Yahweh notre Dieu nous sauvera de la main du roi d''Assyrie?'),
('2ch',32,12,'crampon1923','N''est-ce pas lui, Ezéchias, qui a fait disparaître les hauts lieux et les autels de Yahweh, en disant à Juda et à Jérusalem: Vous vous prosternerez devant un seul autel, et vous y offrirez des parfums?'),
('2ch',32,13,'crampon1923','Ne savez-vous pas ce que nous avons fait, mes pères et moi, à tous les peuples des pays? Les dieux des peuples des pays ont-ils pu vraiment sauver leur pays de ma main?'),
('2ch',32,14,'crampon1923','Quel est, parmi tous les dieux de ces nations que mes pères ont exterminées, celui qui a pu délivrer son peuple de ma main, pour que votre dieu puisse vous délivrer de ma main?'),
('2ch',32,15,'crampon1923','Et maintenant, qu''Ezéchias ne vous séduise point et ne vous trompe pas ainsi! Ne vous fiez pas à lui. Car aucun dieu d''aucune nation ni d''aucun royaume n''a pu délivrer son peuple de ma main et de la main de mes pères: combien moins votre dieu vous délivrera-t-il de ma main! "'),
('2ch',32,16,'crampon1923','Les serviteurs de Sennachérib parlèrent encore contre Yahweh Dieu et contre Ezéchias, son serviteur.'),
('2ch',32,17,'crampon1923','Il écrivit aussi une lettre pour insulter Yahweh, le Dieu d''Israël, et pour parler contre lui; il s''exprimait en ces termes: " De même que les dieux des nations des pays n''ont pu délivrer leur peuple de ma main, de même le dieu d''Ezéchias ne délivrera pas son peuple de ma main. "'),
('2ch',32,18,'crampon1923','Et ses serviteurs crièrent à haute voix, en langue judaïque, au peuple de Jérusalem qui était sur la muraille, pour l''effrayer et l''épouvanter, afin de pouvoir ainsi s''emparer de la ville.'),
('2ch',32,19,'crampon1923','Ils parlaient du Dieu de Jérusalem comme des dieux des peuples de la terre, ouvrages de mains d''homme.'),
('2ch',32,20,'crampon1923','A cause de cela, le roi Ezéchias et le prophète Isaïe, fils d''Amos, se mirent à prier, et ils crièrent vers le ciel.'),
('2ch',32,21,'crampon1923','Et Yahweh envoya un ange qui extermina tous les vaillants hommes, les princes et les chefs dans le camp du roi d''Assyrie. Le roi s''en retourna couvert de honte dans son pays. Lorsqu''il fut entré dans la maison de son dieu, quelques-uns de ceux qui étaient sortis de ses entrailles le firent tomber par l''épée.'),
('2ch',32,22,'crampon1923','Et Yahweh sauva Ezéchias et les habitants de Jérusalem de la main de Sennachérib, roi d''Assyrie, et de la main de tous ses ennemis, et il les guida de tous côtés.'),
('2ch',32,23,'crampon1923','Beaucoup de gens apportèrent à Jérusalem des offrandes à Yahweh, et de riches présents à Ezéchias, roi de Juda, qui fut élevé depuis lors aux yeux de toutes les nations.'),
('2ch',32,24,'crampon1923','En ce temps-là, Ezéchias fut malade à la mort. Il pria Yahweh, et Yahweh lui parla et lui accorda un prodige.'),
('2ch',32,25,'crampon1923','Mais Ezéchias ne répondît pas au bienfait qu''il avait reçu, car son cœur s''éleva, et la colère de Yahweh fut sur lui, ainsi que sur Juda et Jérusalem.'),
('2ch',32,26,'crampon1923','Et Ezéchias s''humilia à cause de l''orgueil de son cœur, lui et les habitants de Jérusalem, et la colère de Yahweh ne vint pas sur eux pendant la vie d''Ezéchias.'),
('2ch',32,27,'crampon1923','Ezéchias eut beaucoup de richesses et de gloire. Il amassa des trésors d''argent, d''or, de pierres précieuses, d''aromates, de boucliers et de toutes sortes d''objets désirables.'),
('2ch',32,28,'crampon1923','Il se fit des magasins pour les produits en blé, en vin et en huile, des crèches pour toute espèce de bétail, et il eut des troupeaux pour les étables.'),
('2ch',32,29,'crampon1923','Il se bâtit des villes, et il eut de nombreux troupeaux de bœufs et de brebis, car Dieu lui donna des biens considérables.'),
('2ch',32,30,'crampon1923','Ce fut lui aussi, Ezéchias, qui couvrit l''issue supérieure des eaux du Gihon, et les dirigea en bas vers l''occident de la cité de David. Ezéchias réussit dans toutes ses entreprises.'),
('2ch',32,31,'crampon1923','Et Dieu ne l''abandonna aux messagers que les chefs de Babylone envoyèrent auprès de lui pour s''informer du prodige qui avait eu lieu dans le pays, que pour l''éprouver, afin de connaître tout ce qu''il y avait dans son cœur.'),
('2ch',32,32,'crampon1923','Le reste des actes d''Ezéchias, et ses œuvres pieuses, voici que cela est écrit dans la Vision du prophète Isaïe, fils d''Amos, et dans le livre des rois de Juda et d''Israël.'),
('2ch',32,33,'crampon1923','Ezéchias se coucha avec ses pères, et on l''enterra dans le lieu le plus élevé des sépulcres des fils de David; et tout Juda et les habitants de Jérusalem lui rendirent des honneurs à sa mort. Et Manassé, son fils, régna à sa place.'),
('2ch',33,1,'crampon1923','Manassé avait douze ans lorsqu''il devint roi, et il régna cinquante-cinq ans à Jérusalem.'),
('2ch',33,2,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, imitant les abominations des nations que Yahweh avait chassées devant les enfants d''Israël.'),
('2ch',33,3,'crampon1923','Il rebâtit les hauts lieux qu''Ezéchias, son père, avait renversés; il éleva des autels aux Baals, il fit des aschérahs, et il se prosterna devant toute l''armée du ciel et la servit.'),
('2ch',33,4,'crampon1923','Il bâtit des autels dans la maison de Yahweh, de laquelle Yahweh avait dit: " C''est dans Jérusalem que sera mon nom à perpétuité. "'),
('2ch',33,5,'crampon1923','Il bâtit des autels à toute l''armée du ciel dans les deux parvis de la maison de Yahweh.'),
('2ch',33,6,'crampon1923','Il fit passer ses fils par le feu dans la vallée de Ben-Ennom; il pratiquait les augures, la divination et la magie; il institua des nécromanciens et des sorciers.'),
('2ch',33,7,'crampon1923','Il mit l''image de l''idole qu''il avait faite dans la maison de Dieu, dont Dieu avait dit à David et à Salomon, son fils: " C''est dans cette maison et c''est dans Jérusalem, que j''ai choisie parmi toutes les tribus d''Israël, que je veux placer mon nom à perpétuité.'),
('2ch',33,8,'crampon1923','Je ne ferai plus sortir le pied d''Israël de dessus la terre que j''ai destinée à vos pères, pourvu seulement qu''ils aient soin de mettre en pratique tout ce que je leur ai commandé, selon toute la loi, les préceptes et les ordonnances prescrites par l''organe de Moïse. "'),
('2ch',33,9,'crampon1923','Manassé égara Juda et les habitants de Jérusalem, au point qu''ils firent plus de mal que les nations que Yahweh avait détruites devant les enfants d''Israël.'),
('2ch',33,10,'crampon1923','Yahweh parla à Manassé et à son peuple, mais il n''y firent point attention.'),
('2ch',33,11,'crampon1923','Alors Yahweh fit venir contre eux les chefs de l''armée du roi d''Assyrie; ils prirent Manassé avec des anneaux et, l''ayant lié d''une double chaîne d''airain, ils le menèrent à Babylone.'),
('2ch',33,12,'crampon1923','Lorsqu''il fut dans l''angoisse, il implora Yahweh, son Dieu, et il s''humilia profondément devant le Dieu de ses pères.'),
('2ch',33,13,'crampon1923','Il le pria, et Yahweh, se laissant fléchir, écouta sa supplication et le ramena à Jérusalem dans sa royauté. Et Manassé reconnut que Yahweh est Dieu.'),
('2ch',33,14,'crampon1923','Après cela, il bâtit un mur extérieur à la cité de David, à l''occident, vers Gihon dans la vallée, jusqu''à l''entrée de la porte des poissons, de manière à entourer Ophel, et il l''éleva à une grande hauteur. Il mit aussi des chefs militaires dans toutes les villes fortes, en Juda.'),
('2ch',33,15,'crampon1923','Il fit disparaître de la maison de Yahweh les dieux étrangers et l''idole, ainsi que tous les autels qu''il avait bâtis sur la montagne de la maison de Yahweh et à Jérusalem, et il les jeta hors de la ville.'),
('2ch',33,16,'crampon1923','Il rebâtit l''autel de Yahweh et y offrit des sacrifices de paix et d''actions de grâces, et il dit à Juda de servir Yahweh, le Dieu d''Israël.'),
('2ch',33,17,'crampon1923','Le peuple sacrifiait bien encore sur les hauts lieux, mais seulement à Yahweh, son Dieu.'),
('2ch',33,18,'crampon1923','Le reste des actes de Manassé, sa prière à son Dieu, et les paroles des voyants qui lui parlèrent au nom de Yahweh, le Dieu d''Israël, voici que cela se trouve dans les actes des rois d''Israël.'),
('2ch',33,19,'crampon1923','Sa prière et la manière dont il fut exaucé, ses péchés et ses infidélités; les places où il bâtit les hauts lieux et dressa des aschérahs et des images avant de s''être humilié, voici que cela est écrit dans les Paroles de Hozaï.'),
('2ch',33,20,'crampon1923','Manassé se coucha avec ses pères, et on l''enterra dans sa maison. Amon, son fils, régna à sa place.'),
('2ch',33,21,'crampon1923','Amon avait vingt-deux ans lorsqu''il devint roi, et il régna deux ans à Jérusalem.'),
('2ch',33,22,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, comme avait fait Manassé, son père; Amon sacrifia à toutes les images qu''avait faites Manassé, son père, et il les servit;'),
('2ch',33,23,'crampon1923','et il ne s''humilia pas devant Yahweh, comme s''était humilié Manassé, son père; car lui, Amon, multiplia le péché.'),
('2ch',33,24,'crampon1923','Ses serviteurs conspirèrent contre lui et le mirent à mort dans sa maison.'),
('2ch',33,25,'crampon1923','Mais le peuple du pays frappa tous ceux qui avaient conspiré contre le roi Amon, et le peuple du pays établit roi à sa place Josias, son fils.'),
('2ch',34,1,'crampon1923','Josias avait huit ans lorsqu''il devint roi, et il régna trente et un an à Jérusalem.'),
('2ch',34,2,'crampon1923','Il fit ce qui est droit aux yeux de Yahweh, et il marcha dans les voies de David, son père, et il ne s''en détourna ni à droite ni à gauche.'),
('2ch',34,3,'crampon1923','La huitième année de son règne, lorsqu''il était encore un adolescent, il commença à rechercher le Dieu de David, son père, et, la douzième année, il commença à purifier Juda et Jérusalem des hauts lieux, des aschérahs, des images sculptées et des images fondues.'),
('2ch',34,4,'crampon1923','On renversa devant lui les autels des Baals, et il abattit les statues consacrées au soleil qui étaient placées dessus; il brisa les aschérahs, les images taillées et les images fondues, et, les ayant réduites en poussière, il répandit cette poussière sur les tombeaux de ceux qui leur avaient offert des sacrifices;'),
('2ch',34,5,'crampon1923','et il brûla les ossements des prêtres sur leurs autels. Et il purifia Juda et Jérusalem.'),
('2ch',34,6,'crampon1923','Dans les villes de Manassé, d''Ephraïm, de Siméon et jusqu''en Nephthali, — au milieu de leurs ruines, —'),
('2ch',34,7,'crampon1923','il renversa les autels, brisa et réduisit en poussière les aschérahs et les images sculptées, et abattit toutes les statues consacrées au soleil dans tout le pays d''Israël. Puis il retourna à Jérusalem.'),
('2ch',34,8,'crampon1923','La dix-huitième année de son règne, après qu''il eut purifié le pays et la maison de Dieu, il envoya Saphan, fils d''Aslia, Maasias, commandant de la ville, et Joha, fils de Joachaz, l''archiviste, pour réparer la maison de Yahweh, son Dieu.'),
('2ch',34,9,'crampon1923','Ils se rendirent auprès d''Helcias, le grand prêtre, et ils livrèrent l''argent qui avait été apporté dans la maison de Dieu, et que les lévites gardiens de la porte avaient recueilli de Manassé et d''Ephraïm, et de tout le reste d''Israël, et de tout Juda et Benjamin et des habitants de Jérusalem.'),
('2ch',34,10,'crampon1923','Ils remirent cet argent entre les mains de ceux qui faisaient exécuter l''ouvrage, qui étaient établis surveillants dans la maison de Yahweh, et ceux-ci le donnèrent aux ouvriers qui travaillaient à la maison de Yahweh, pour réparer et consolider la maison.'),
('2ch',34,11,'crampon1923','Et ils le donnèrent aux charpentiers et aux maçons, et ils l''employèrent à acheter des pierres de taille et du bois pour la charpente, et pour mettre des poutres aux bâtiments qu''avaient détruits les rois de Juda.'),
('2ch',34,12,'crampon1923','Ces hommes travaillaient fidèlement à leur tâche. Ils avaient pour surveillants Jahath et Abdias, lévites d''entre les fils de Mérari, Zacharias et Mosollam, d''entre les fils des Caathites, qui les dirigeaient, ainsi que d''autres lévites qui tous s''entendaient aux instruments de musique.'),
('2ch',34,13,'crampon1923','Ceux-ci surveillaient aussi les manœuvres et dirigeaient tous les ouvriers pour chaque travail. Il y avait encore des lévites secrétaires, commissaires et portiers.'),
('2ch',34,14,'crampon1923','Au moment où l''on retirait l''argent qui avait été apporté dans la maison de Yahweh, le prêtre Helcias trouva le livre de la loi de Yahweh, donnée par l''organe de Moïse.'),
('2ch',34,15,'crampon1923','Alors Helcias, prenant la parole, dit à Saphan, le secrétaire: " J''ai trouvé le livre de la loi dans la maison de Yahweh "; et Helcias donna le livre à Saphan.'),
('2ch',34,16,'crampon1923','Saphan porta le livre au roi, et il rendit aussi compte au roi, en disant: " Tout ce qui a été confié à tes serviteurs, ils l''ont fait:'),
('2ch',34,17,'crampon1923','ils ont vidé l''argent qui se trouvait dans la maison de Yahweh et l''ont remis entre les mains de ceux qui sont établis surveillants et entre les mains de ceux qui font exécuter l''ouvrage. "'),
('2ch',34,18,'crampon1923','Saphan, le secrétaire, fit encore au roi cette communication: " Le prêtre Helcias m''a donné un livre. " Et Saphan lut dans ce livre devant le roi.'),
('2ch',34,19,'crampon1923','Lorsque le roi eut entendu les paroles de la loi, il déchira ses vêtements,'),
('2ch',34,20,'crampon1923','et il donna cet ordre à Helcias, à Ahicam, fils de Saphan, à Abdon, fils de Micha, à Saphan, le secrétaire, et à Asaa, serviteur du roi:'),
('2ch',34,21,'crampon1923','" Allez consulter Yahweh pour moi et pour ce qui reste en Israël et en Juda, au sujet des paroles du livre qu''on a trouvé; car grande est la colère de Yahweh qui s''est répandue sur nous, parce que nos pères n''ont pas observé la parole de Yahweh, en agissant selon tout ce qui est écrit dans ce livre. "'),
('2ch',34,22,'crampon1923','Helcias et ceux que le roi avait désignés se rendirent auprès de la prophétesse Holda, femme de Sellum, fils de Thecuath, fils de Hasra, gardien des vêtements; elle habitait à Jérusalem, dans le second quartier. Lorsqu''ils lui eurent parlé selon leur mission,'),
('2ch',34,23,'crampon1923','elle leur dit: " Ainsi dit Yahweh, Dieu d''Israël: Dites à l''homme qui vous a envoyés vers moi:'),
('2ch',34,24,'crampon1923','Ainsi dit Yahweh: Voici que je vais faire venir des malheurs sur ce lieu et sur ses habitants, toutes les malédictions écrites dans le livre qu''on a lu devant le roi de Juda.'),
('2ch',34,25,'crampon1923','Parce qu''ils m''ont abandonné et qu''ils ont offert des parfums à d''autres dieux, de manière à m''irriter par tous les ouvrages de leurs mains, ma colère s''est répandue sur ce lieu, et elle ne s''éteindra point.'),
('2ch',34,26,'crampon1923','Et vous direz au roi de Juda qui vous a envoyés pour consulter Yahweh: Ainsi dit Yahweh, Dieu d''Israël: Quant aux paroles que tu as entendues,'),
('2ch',34,27,'crampon1923','parce que ton cœur s''est repenti, et que tu t''es humilié devant Dieu en entendant ces paroles contre ce lieu et contre ses habitant; parce que, en t''humiliant devant moi, tu as déchiré tes vêtements et pleuré devant moi, moi aussi je t''ai entendu, oracle de Yahweh.'),
('2ch',34,28,'crampon1923','Voici que je te recueillerai auprès de tes pères, tu seras recueilli en paix dans ton sépulcre, et tes yeux ne verront pas tous les malheurs que je ferai venir sur ce lieu et sur ses habitants. " Ils rapportèrent au roi cette réponse.'),
('2ch',34,29,'crampon1923','Le roi envoya rassembler tous les anciens de Juda et de Jérusalem.'),
('2ch',34,30,'crampon1923','Et le roi monta à la maison de Yahweh avec tous les hommes de Juda et les habitants de Jérusalem, les prêtres, les lévites et tout le peuple, depuis le plus grand jusqu''au plus petit, et il lut devant eux toutes les paroles du livre de l''alliance qu''on avait trouvé dans la maison de Yahweh.'),
('2ch',34,31,'crampon1923','Le roi, se tenant sur son estrade, conclut l''alliance devant Yahweh, s''engageant à suivre Yahweh, et à observer ses préceptes, ses ordonnances et ses lois de tout son cœur et de toute son âme, en mettant en pratique les paroles de l''alliance qui sont écrites dans ce livre.'),
('2ch',34,32,'crampon1923','Et il fit acquiescer à l''alliance tous ceux qui se trouvaient à Jérusalem et en Benjamin; et les habitants de Jérusalem agirent selon l''alliance de Dieu, du Dieu de leurs pères.'),
('2ch',34,33,'crampon1923','Josias fit disparaître toutes les abominations de tous les pays appartenant aux enfants d''Israël, et il obligea tous ceux qui se trouvaient en Israël à servir Yahweh, leur Dieu. Tant qu''il vécut, ils ne se détournèrent point de Yahweh, le Dieu de leurs pères.'),
('2ch',35,1,'crampon1923','Josias célébra à Jérusalem la Pâque en l''honneur de Yahweh, et on immola la Pâque le quatorzième jour du premier mois.'),
('2ch',35,2,'crampon1923','Il établit les prêtres dans leurs fonctions, et il les encouragea à faire le service dans la maison de Yahweh.'),
('2ch',35,3,'crampon1923','Il dit aux lévites qui enseignaient tout Israël et qui étaient consacrés à Yahweh: " Placez l''arche sainte dans la maison qu''a bâtie Salomon, fils de David, roi d''Israël; vous n''avez plus à la porter sur l''épaule. Servez maintenant Yahweh, votre Dieu, et son peuple d''Israël.'),
('2ch',35,4,'crampon1923','Tenez-vous prêts, selon vos familles, dans vos classes, selon le règlement de David, roi d''Israël, et selon le dispositif de Salomon, son fils.'),
('2ch',35,5,'crampon1923','Tenez-vous dans le sanctuaire, selon les divisions des familles de vos frères, les fils du peuple, — pour chaque division une classe de la famille des lévites.'),
('2ch',35,6,'crampon1923','Immolez la Pâque, sanctifiez-vous et préparez-la pour vos frères, pour qu''on se conforme à la parole de Yahweh, qu''il a dite par l''organe de Moïse. "'),
('2ch',35,7,'crampon1923','Josias donna aux gens du peuple du petit bétail, agneaux et chevreaux, au nombre de trente mille, le tout en vue de la Pâque, pour tous ceux qui se trouvaient là, et trois mille bœufs, le tout pris sur les biens du roi.'),
('2ch',35,8,'crampon1923','Ses chefs firent spontanément un présent au peuple, aux prêtres et aux lévites: Helcias, Zacharias et Jahiel, princes de la maison de Dieu, donnèrent aux prêtres pour la Pâque deux mille six cents agneaux et trois cents bœufs;'),
('2ch',35,9,'crampon1923','Chonénias, Séméïas et Nathanaël, ses frères, Hasabias, Jéhiel et Jozabad, princes des lévites, donnèrent aux lévites pour la Pâque cinq mille agneaux et cinq cents bœufs.'),
('2ch',35,10,'crampon1923','Ainsi le service fut organisé: les prêtres se tinrent à leurs postes, ainsi que les lévites, selon leurs divisions, conformément à l''ordre du roi.'),
('2ch',35,11,'crampon1923','Les lévites immolèrent la Pâque, et les prêtres répandaient le sang qu''ils recevaient de leur main, tandis que les lévites dépouillaient les victimes.'),
('2ch',35,12,'crampon1923','Ils mirent à part les morceaux destinés à l''holocauste, pour les donner aux divisions des familles des gens du peuple, afin qu''ils les offrissent à Yahweh, comme il est écrit dans le livre de Moïse; et de même pour les bœufs.'),
('2ch',35,13,'crampon1923','Ils firent rôtir au feu la Pâque, selon le règlement, et ils firent cuire les saintes offrandes dans des pots, des chaudrons et des poêles, et ils s''empressèrent de les distribuer à tous les gens du peuple.'),
('2ch',35,14,'crampon1923','Ensuite ils préparèrent la Pâque pour eux et pour les prêtres; car les prêtres, fils d''Aaron, furent occupés, jusqu''à la nuit, à offrir l''holocauste et les graisses: c''est pourquoi les lévites la préparèrent pour eux et pour les prêtres, fils d''Aaron.'),
('2ch',35,15,'crampon1923','Les chantres, fils d''Asaph, étaient à leur place, selon l''ordre de David, d''Asaph, d''Héman et d''Idithun, le voyant du roi, et les portiers étaient à chaque porte; ils n''avaient pas à se détourner de leur office, car leurs frères, les lévites, préparaient pour eux la Pâque.'),
('2ch',35,16,'crampon1923','Ainsi fut organisé tout le service de Yahweh, en ce jour-là, pour célébrer la Pâque et offrir des holocaustes sur l''autel de Yahweh, conformément à l''ordre du roi Josias.'),
('2ch',35,17,'crampon1923','Les enfants d''Israël qui se trouvaient là célébrèrent la Pâque en ce temps, et la fête des Azymes pendant sept jours.'),
('2ch',35,18,'crampon1923','Aucune Pâque pareille à celle-ci n''avait été célébrée en Israël depuis les jours de Samuel le prophète, et aucun des rois d''Israël n''avait fait une Pâque pareille à celle que célébrèrent Josias, les prêtres et les lévites, tout Juda et tout Israël qui se trouvaient là, et les habitants de Jérusalem.'),
('2ch',35,19,'crampon1923','Ce fut la dix-huitième année du règne de Josias que cette Pâque fut célébrée.'),
('2ch',35,20,'crampon1923','Après tout cela, lorsque Josias eut réparé la maison de Yahweh, Néchao, roi d''Egypte, monta pour combattre à Charcamis, sur l''Euphrate; et Josias sortit à sa rencontre.'),
('2ch',35,21,'crampon1923','Et Néchao lui envoya des messagers pour dire: " Que me veux-tu, roi de Juda? Ce n''est pas contre toi que je viens aujourd''hui; mais c''est contre une maison avec laquelle je suis en guerre, et Dieu m''a dit de me hâter. Cesse de t''opposer à Dieu, qui est avec moi, et qu''il ne te fasse pas mourir! "'),
('2ch',35,22,'crampon1923','Mais Josias ne se détourna pas de lui et se déguisa pour l''attaquer; il n''écouta pas les paroles de Néchao, qui venaient de la bouche de Dieu; il s''avança pour combattre dans la plaine de Mageddo.'),
('2ch',35,23,'crampon1923','Les archers tirèrent sur le roi Josias, et le roi dit à ses serviteurs: " Transportez-moi, car je suis gravement blessé. "'),
('2ch',35,24,'crampon1923','Ses serviteurs le transportèrent du char, et le placèrent dans l''autre char qui était à lui, et l''emmenèrent à Jérusalem. Il mourut, et fut enterré dans les sépulcres de ses pères. Tout Juda et Jérusalem pleurèrent Josias.'),
('2ch',35,25,'crampon1923','Jérémie composa une lamentation sur Josias; tous les chanteurs et toutes les chanteuses ont parlé de Josias dans leurs lamentations, jusqu''à ce jour; on en a fait une coutume en Israël. Et voici que ces chants sont écrits dans les Lamentations.'),
('2ch',35,26,'crampon1923','Le reste des actes de Josias, et ses œuvres pieuses conformes à ce qui est écrit dans la loi de Yahweh,'),
('2ch',35,27,'crampon1923','ses actes, les premiers et les derniers, voici que cela est écrit dans le livre des rois d''Israël et de Juda.')
